-- Retorna LOGIN do usuario no infarma
CREATE FUNCTION dbo.FN_UsuarioInfarma()
RETURNS varchar(15)
AS
BEGIN
	Declare @Usuario varchar(15);
	
	If SUSER_SNAME() <> 'DMDAPP' COLLATE LATIN1_GENERAL_CI_AS
		Set @Usuario = SUSER_SNAME();
	Else
		Set @Usuario = PROGRAM_NAME();

	Return @Usuario;
END;
GO

