CREATE FUNCTION [dbo].[FN_SaldoCreditoCliente]
(
@PCodCli int
)
RETURNS numeric(18,4)

AS

BEGIN

Declare @PVlrSld numeric(18,4),
        @CodCliPag int,
		@SldLimCre numeric(18,4),
		@VlrTotPen  numeric(18,4)

Set @PVlrSld = 0
 
Set @CodCliPag = (Select IsNull(Cod_CliPag,0) From dbo.CLIEN Where Codigo = @PCodCli)

Set @SldLimCre = 0

Select @SldLimCre = IsNull(Round(Sum(IsNull(cl.Limite_Credito,0)-IsNull(cl.Total_Debito,0)),2),0)
  From dbo.CLIEN cl 
 Where cl.Cod_CliPag = @CodCliPag

Set @VlrTotPen = 0
Select @VlrTotPen = IsNull(Sum(dbo.FN_ValPdv(cb.Cod_Estabe,cb.Numero)),0)
  From dbo.PDVCB cb 
       Inner Join dbo.CLIEN cl on cb.Cod_Cliente = cl.Codigo 
 Where cb.Status1 = 'P'
   And cb.Status2 = 'F'
   And cb.Tip_Pedido <> 'C'
   And cb.Cod_Cliente = cl.Codigo 
   And cl.Cod_CliPag = @CodCliPag

Set @PVlrSld = IsNull(@SldLimCre,0) - IsNull(@VlrTotPen,0)
        
-- Retorna o resultado da function
RETURN @PVlrSld

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ProxNumero]
@Campo VarChar(15),
@Retorno Int Output

AS

BEGIN

  SET NOCOUNT ON;

  Begin Transaction

  Declare @SeqName SYSNAME;

  Set @SeqName = Quotename('DMDSeq_' + @Campo);
  
  if Object_id(@SeqName, 'SO') is not null  
    begin
      -- Utiliza Sequence 
      Declare @SqlCmd nvarchar(MAX);
      Set @SqlCmd = 'SET @Retorno = NEXT VALUE FOR ' + @SeqName;
      Execute sp_executesql @SqlCmd=@SqlCmd
              , @params=N'@Retorno Int Out'
              , @Retorno=@Retorno OUT;
    end
  else
    begin
      if Exists(Select Campo From NUMER where Campo = @Campo)
        begin
          Update NUMER 
             Set Valor = Isnull(Valor,0) + 1
           Where Campo = @Campo
        end
      else
        Insert NUMER (Campo,Valor) Values (@Campo,1)
    end;

  Commit Transaction;

  Select @Retorno = Valor From NUMER Where Campo = @Campo;

END;
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create Procedure PR_ExcecaoAuditNew @operacao char(1)
As
Begin
	Set Nocount On;
	Set Xact_Abort On;

	Declare @Usuario Sysname;

	If OBJECT_ID('FN_UsuarioInfarma') IS NOT NULL
		EXEC @Usuario = FN_UsuarioInfarma;
	
	Set @Usuario = ISNULL(@Usuario, SUSER_NAME());

	If @operacao = 'i'
	Begin
		If Not Exists (Select 0 From dbo.TBAUDNEW_SPID Where Des_Spid = @@SPID And Usuario = @Usuario)
			Insert Into dbo.TBAUDNEW_SPID (Usuario, Des_Spid) Values (@Usuario, @@SPID);
	End;
	Else If @operacao = 'd'
	Begin
		Delete From dbo.TBAUDNEW_SPID Where Des_Spid = @@SPID And Usuario = @Usuario;
	END;
End;
GO

