CREATE FUNCTION [dbo].[FN_ValSbtUltEnt] 
(
  @PCodEstabe integer,    
  @PCodPrd integer,       
  @PCodLot varchar(20),   -- opcional
  @PDatRef smalldatetime, -- opcional
  @PQtdPrd int
)
RETURNS NUMERIC(18,4)

AS

BEGIN

Declare @WValSbt numeric(18,4)  -- ST Retida, A Recolher, Ressarcimento

Set @WValSbt = 0

-- se não informou data referência utiliza data atual
if @PDatRef < 1000
  Set @PDatRef = Cast(GetDate() as date)


if (@PCodLot = '*') and
   not Exists(Select 1 
                 From NFECB cb 
                      Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo) 
                Where cb.Cod_Estabe = @PCodEstabe
                  And cb.Status = 'F'
                  And ((cb.Tip_NF = 'C') or (cb.Tip_NF = 'T')) 
                  And it.Cod_Produto = @PCodPrd
                  And it.Cod_Lote = @PCodLot
                  And cb.Dat_Movimento <= @PDatRef)
  Set @PCodLot = ''


-- se não informou o lote utiliza lote "ativo"
if @PCodLot = ''
  Select top 1 @PCodLot = x.Cod_Lote 
    From (Select top 1 Cod_Lote, Dat_VEncim
            From PRLOT
           Where Cod_Estabe = @PCodEstabe
             And Cod_Produt = @PCodPrd
             And Qtd_Saldo > 0
          UNION
          Select top 1 Cod_Lote, Dat_Vencim
            From PRLTL
           Where Cod_Estabe = @PCodEstabe
             And Cod_Produt = @PCodPrd
             And Qtd_Saldo > 0
           Order by Dat_Vencim) x

if (@PCodLot <> '') and
   Exists(Select 1 
            From NFECB cb 
                 Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo) 
           Where cb.Cod_Estabe = @PCodEstabe
             And cb.Status = 'F'
             And ((cb.Tip_NF = 'C') or (cb.Tip_NF = 'T')) 
             And it.Cod_Produto = @PCodPrd
             And it.Cod_Lote = @PCodLot
             And cb.Dat_Movimento <= @PDatRef)
  begin
    Select top 1 
	       @WValSbt = Round((IsNull(it.Vlr_SubsTrib,0)+IsNull(it.Vlr_SbtRes,0)+IsNull(it.Vlr_DifTri,0))*@PQtdPrd/(it.Qtd_Pedido+it.Qtd_Bonificacao),4) 
      From NFECB cb 
           Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo) 
     Where cb.Cod_Estabe = @PCodEstabe
       And cb.Status = 'F'
       And ((cb.Tip_NF = 'C') or (cb.Tip_NF = 'T')) 
       And it.Cod_Produto = @PCodPrd
       And it.Cod_Lote = @PCodLot
       And cb.Dat_Movimento <= @PDatRef
     Order by cb.Protocolo desc
  end

-- Retorna o resultado da function
RETURN IsNull(@WValSbt,0)

END
GO

