       @rt_Per_AcrAlqExtFcpReg = IsNull(rx.Per_AcrAlqExtFcpReg,0),
       @rt_Per_RedBasCalExtReg = Isnull(rx.Per_RedBasCalExtReg,0),
       @rt_Per_IcmDiferiExtReg = IsNull(rx.Per_IcmDiferiExtReg,0),
       @rt_Per_IcmDesoneExtReg = Isnull(rx.Per_IcmDesoneExtReg,0),
       @rt_Cod_MtvDesIcmReg = Isnull(rx.Cod_MtvDesIcmReg,'9'),
       @rt_Flg_DscDesIcmReg = IsNull(rx.Flg_DscDesIcmReg,0),
       @rt_C_PerRepIcmReg = Isnull(rx.C_PerRepIcmReg,0),

       @rg_Flg_UsaDebPresum = IsNull(rg.Flg_UsaDebPresum,0),
       @rt_Alq_DebPresum = Case 
                                 When IsNull(rg.Flg_UsaDebPresum,0) = 1 then IsNull(rx.Alq_IcmPresumLoc,0) 
                                                         Else 0 
                           End,    
       @rt_Flg_DscIcmOrgPub = IsNull(rg.Flg_DscIcmOrgPub,0),
       @rt_Flg_DscIcmOrgPubAcr = IsNull(rg.Flg_DscIcmOrgPubAcr,0),
       @rt_Flg_DscSbtOrgPub = IsNull(rg.Flg_DscSbtOrgPub,0)
  From RTXCT rx
       Inner Join RGTRI rg on rx.Cod_RegTri = rg.Cod_RegTri
Where rx.Cod_RegTri = @PCodRegTri
and  rx.Cod_ClaTri = @PClaTri

-- tipo da nota diferente de devolucao
if @PTipNot <> 'D'
  begin
    -- vendas, outras saidas
    Set @WClaTriExt = @rt_ClaTriExt
    Set @WTipPrcBasDebSbt = @rt_Tip_PrcBasDebSbt
    Set @WCtrBasCalDeb = @rt_Ctrl_BasCalDebSai
    Set @WAlqAgrDeb = @rt_Alq_AgrDebSai
    Set @WPerRedBasCalDeb = @rt_Per_RedBasCalDebSai
    Set @WPerLimMinIcmSbtSaiRedDeb = @rt_Per_LimMinIcmSbtSaiRedDeb
    Set @WTipPrcLimMinBasCalIcmSbtSai = @rt_Tip_PrcLimMinBasCalIcmSbtSai
    Set @WAlqAgrLimMinBasCalIcmSbtSai = @rt_Alq_AgrLimMinBasCalIcmSbtSai     
    Set @WTipPrcLimMinIcmSbt = @rt_Tip_PrcLimMinIcmSbtSai
    Set @WPerLimMinIcmSbt = @rt_Per_LimMinIcmSbtSai
