if @PTipNot = 'D'  -- tipo da nota devolucao
  begin
    Set @PPrcFab = IsNull(@PArqPrcFab,0)
    Set @PPrcMax = IsNull(@PArqPrcMax,0)
    Set @PPrcRefFpb = IsNull(@PArqPrcRefFpb,0)
