CREATE TRIGGER [dbo].[TR_NFEIT_AtualizaDados] ON [dbo].[NFEIT] 
AFTER INSERT, UPDATE, DELETE 
NOT FOR REPLICATION
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 

-- valor de projeto incluido (embutido) no desconto total Vlr_DscIte1
-- após alterações Vlr_DscIte2 eficou sem uso: 
--    antes deveria ser valor de desconto de projeto embutido no desconto total (Vlr_Dsc1)
--    ou seja, antes, Vlr_Dsc1 = Vlr.Dsesc.Item(ref:Per_DescItem) + vlr.Desc.Projeto
--    atualmente Vlr_Dsc1 = ref. descnto dp item (Per_DescItem)

if Update(Vlr_DscIte1) or Update(Vlr_DscIte2) or Update(Per_DescItem)
  begin
	IF trigger_nestlevel() > 3 
	  RETURN

    Update N
       Set N.Vlr_DscIte1 = Round(N.Vlr_DscIte1,2),
           N.Vlr_DscIte2 = Round(N.Vlr_DscIte2,2)
      From Inserted I 
           inner Join NFEIT N on (N.Cod_Estabe  = I.Cod_Estabe  and N.Protocolo = I.Protocolo and
                                  N.Cod_Produto = I.Cod_Produto and N.Cod_Lote  = I.Cod_Lote  and
                                  N.Num_SeqIte  = I.Num_SeqIte)
     Where ( (N.Vlr_DscIte1 <> Round(N.Vlr_DscIte1,2)) or
             (N.Vlr_DscIte2 <> Round(N.Vlr_DscIte2,2)) ) 

    if Update(Per_DescItem)
      Update N
         Set N.Vlr_DscIte1 = Round(Round(N.Prc_Unitario*N.Qtd_Pedido,2) * (N.Per_DescItem/100),2)
        From Inserted I 
             inner Join Deleted D on (D.Cod_Estabe  = I.Cod_Estabe  and D.Protocolo = I.Protocolo and
                                      D.Cod_Produto = I.Cod_Produto and D.Cod_Lote  = I.Cod_Lote  and
                                      D.Num_SeqIte  = I.Num_SeqIte)
             inner Join NFEIT N on (N.Cod_Estabe  = I.Cod_Estabe  and N.Protocolo = I.Protocolo and
                                    N.Cod_Produto = I.Cod_Produto and N.Cod_Lote  = I.Cod_Lote  and
                                    N.Num_SeqIte  = I.Num_SeqIte)
       Where I.Per_DescItem <> D.Per_DescItem 
         And N.Vlr_DscIte1 <> Round(Round(N.Prc_Unitario*N.Qtd_Pedido,2) * (N.Per_DescItem/100),2)


    Update N
       Set N.Per_DescItem = Case 
                              When (Round(N.Prc_Unitario*N.Qtd_Pedido,2) > 0) and
                                   (Round(N.Per_DescItem,4) <> Round(N.Vlr_DscIte1*100/Round(N.Prc_Unitario*N.Qtd_Pedido,2),4)) Then
                                N.Vlr_DscIte1*100/Round(N.Prc_Unitario*N.Qtd_Pedido, 2)
                              When (Round(N.Prc_Unitario*N.Qtd_Pedido,2) > 0) then N.Per_DescItem
                              Else 0
                            End
      From Inserted I 
           inner Join NFEIT N on (N.Cod_Estabe  = I.Cod_Estabe  and N.Protocolo = I.Protocolo and
                                  N.Cod_Produto = I.Cod_Produto and N.Cod_Lote  = I.Cod_Lote  and
                                  N.Num_SeqIte  = I.Num_SeqIte)
     Where 1 = 1
       And Round(N.Per_DescItem,4) <> Case 
                                        When (Round(N.Prc_Unitario*N.Qtd_Pedido,2) > 0) and
                                             (Round(N.Per_DescItem,4) <> Round(N.Vlr_DscIte1*100/Round(N.Prc_Unitario*N.Qtd_Pedido,2),4)) Then
                                          Round(N.Vlr_DscIte1*100/Round(N.Prc_Unitario*N.Qtd_Pedido, 2),4)
                                        When (Round(N.Prc_Unitario*N.Qtd_Pedido,2) > 0) then N.Per_DescItem
                                        Else 0
                                      End

  end


if Update(Qtd_Pedido) or Update(Qtd_Bonificacao) or Update(Prc_Unitario) or
   Update(Per_DescItem) or Update(Vlr_DscIte1)
  begin
	IF trigger_nestlevel() > 3 
	  RETURN

    Update N
       Set N.Vlr_TotItem = Round(N.Prc_Unitario*N.Qtd_Pedido,2) - N.Vlr_DscIte1,
           N.Vlr_BruItem = Round(N.Prc_Unitario*(N.Qtd_Pedido+N.Qtd_Bonificacao),2)
      From Inserted I 
           inner Join NFEIT N on (N.Cod_Estabe  = I.Cod_Estabe  and N.Protocolo = I.Protocolo and
                                  N.Cod_Produto = I.Cod_Produto and N.Cod_Lote  = I.Cod_Lote  and
                                  N.Num_SeqIte  = I.Num_SeqIte)
     Where ( (N.Vlr_TotItem <> Round(N.Prc_Unitario*N.Qtd_Pedido,2) - N.Vlr_DscIte1) or
             (N.Vlr_BruItem <> Round(N.Prc_Unitario*(N.Qtd_Pedido+N.Qtd_Bonificacao),2)) )
  end

-- desconto total do item (desc. Comerc. item + bonificacao) exceto desc. comercial nota (desc. rateado)
if Update(Qtd_Pedido) or Update(Qtd_Bonificacao) or Update(Prc_Unitario) or
   Update(Per_DescItem) or Update(Vlr_DscIte1) or Update(Vlr_BruItem) or Update(Vlr_TotItem) 
  begin
	IF trigger_nestlevel() > 3 
	  RETURN

    Update N
       Set N.Vlr_DescItem = N.Vlr_BruItem - N.Vlr_TotItem
      From Inserted I 
           inner Join NFEIT N on (N.Cod_Estabe  = I.Cod_Estabe  and N.Protocolo = I.Protocolo and
                                  N.Cod_Produto = I.Cod_Produto and N.Cod_Lote  = I.Cod_Lote  and
                                  N.Num_SeqIte  = I.Num_SeqIte)
     Where N.Vlr_DescItem <> N.Vlr_BruItem - N.Vlr_TotItem
  end

-- calcula valor liquido do item na nota
-- procedimento sera executado tambem no fechamento da nota
if Update(Vlr_TotItem) or Update(Vlr_DscTri) or Update(Vlr_DescRateado) or Update(Vlr_DespRateada) or
   Update(Vlr_SubsTrib) or Update(Vlr_SbtRes) or Update(Vlr_DifTri) or Update(Vlr_Ipi) or
   Update(Vlr_Suframa) or Update(Vlr_Frete) or Update(Vlr_Seguro) or Update(Vlr_DspExt)
  begin
	IF trigger_nestlevel() > 3 
	  RETURN

    Update N
       Set N.Vlr_LiqIte = N.Vlr_TotItem -IsNull(N.Vlr_DscTri,0)- IsNull(N.Vlr_DescRateado ,0) 
                         +IsNull(N.Vlr_DespRateada,0) +IsNull(N.Vlr_SubsTrib,0) +IsNull(N.Vlr_DifTri,0) 
                         +IsNull(N.Vlr_SbtRes,0) +IsNull(N.Vlr_Ipi,0)
                         +IsNull(N.Vlr_Suframa,0) +IsNull(N.Vlr_Frete,0) +IsNull(N.Vlr_Seguro,0)
                         +IsNull(N.Vlr_DspExt,0)
      From Inserted I 
           inner Join NFEIT N on (N.Cod_Estabe  = I.Cod_Estabe  and N.Protocolo = I.Protocolo and
                                  N.Cod_Produto = I.Cod_Produto and N.Cod_Lote  = I.Cod_Lote  and
                                  N.Num_SeqIte  = I.Num_SeqIte)
     Where N.Vlr_LiqIte <> N.Vlr_TotItem -IsNull(N.Vlr_DscTri,0)- IsNull(N.Vlr_DescRateado ,0) 
                         +IsNull(N.Vlr_DespRateada,0) +IsNull(N.Vlr_SubsTrib,0) +IsNull(N.Vlr_DifTri,0) 
                         +IsNull(N.Vlr_SbtRes,0) +IsNull(N.Vlr_Ipi,0)
                         +IsNull(N.Vlr_Suframa,0) +IsNull(N.Vlr_Frete,0) +IsNull(N.Vlr_Seguro,0)
                         +IsNull(N.Vlr_DspExt,0)
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_PRLOT_AtualizaSaldoDisponivel] ON [dbo].[PRLOT] 
FOR INSERT, UPDATE, DELETE
NOT FOR REPLICATION 
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 

Declare @FlgAtu bit

Update L
   Set L.Fat_CnvAprEmbPad = ap.Fat_CnvApr
  From PRLOT L   
       Inner Join PARAM pm on L.Cod_Estabe = pm.Cod_Estabe
       Inner Join PRXAP ap on L.Cod_Produt = ap.Cod_Produt and ap.Flg_Padrao = 1
       Inner Join Inserted I on L.Cod_Estabe = I.Cod_Estabe and L.Cod_Dep = I.Cod_Dep and 
	                            L.Cod_Produt = I.Cod_Produt and L.Cod_Lote = I.Cod_Lote
 Where Case When IsNull(pm.FlgAltUnvItePdv,0) = 1 then ap.Fat_CnvApr
            Else 1
       End <> L.Fat_CnvAprEmbPad

Set @FlgAtu = 0

if Update(Qtd_FisPra) or Update(Qtd_SolPra)
  begin
    Set @FlgAtu = 1
    Update L
       Set L.Qtd_SldPra = IsNull(I.Qtd_FisPra,0) - IsNull(I.Qtd_SolPra,0)
      From Inserted I 
           inner Join PRLOT L on L.Cod_Estabe = I.Cod_Estabe and L.Cod_Dep = I.Cod_Dep and L.Cod_Produt = I.Cod_Produt and L.Cod_Lote = I.Cod_Lote
  end

if Update(Qtd_FisDep) or Update(Qtd_SolDep)
  begin
    Set @FlgAtu = 1
    Update L
       Set L.Qtd_SldDep = IsNull(I.Qtd_FisDep,0) - IsNull(I.Qtd_SolDep,0)
      From Inserted I 
           inner Join PRLOT L on L.Cod_Estabe = I.Cod_Estabe and L.Cod_Dep = I.Cod_Dep and L.Cod_Produt = I.Cod_Produt and L.Cod_Lote = I.Cod_Lote
  end

if @FlgAtu = 1
  begin
    Update L
       Set L.Qtd_Fisico = IsNull(I.Qtd_FisPra,0) + IsNull(I.Qtd_FisDep,0),
           L.Qtd_Solicitado = IsNull(I.Qtd_SolPra,0) + IsNull(I.Qtd_SolDep,0),
           L.Qtd_Saldo = IsNull(I.Qtd_FisPra,0) - IsNull(I.Qtd_SolPra,0) + IsNull(I.Qtd_FisDep,0) - IsNull(I.Qtd_SolDep,0)
      From Inserted I 
           inner Join PRLOT L on L.Cod_Estabe = I.Cod_Estabe and L.Cod_Dep = I.Cod_Dep and L.Cod_Produt = I.Cod_Produt and L.Cod_Lote = I.Cod_Lote
  end

-- Atualiza quantidades em DPXPR (em 29/11/2016)
Insert into DPXPR(Cod_Estabe, Cod_Dep, Cod_Produt)
  Select distinct I.Cod_Estabe, I.Cod_Dep, I.Cod_Produt
    From Inserted I 
         inner Join PRLOT L on L.Cod_Estabe = I.Cod_Estabe and L.Cod_Dep = I.Cod_Dep and L.Cod_Produt = I.Cod_Produt and L.Cod_Lote = I.Cod_Lote
   Where L.Qtd_Fisico <> 0
     And not Exists(Select 1 From DPXPR dp
                     Where I.Cod_Estabe = dp.Cod_Estabe and I.Cod_Produt = dp.Cod_Produt)

Update P
   Set P.Qtd_Fisico = IsNull(x.QtdFis,0)+IsNull(y.QtdFis,0)
  From DPXPR P  
       inner join Inserted I on (P.Cod_Estabe = I.Cod_Estabe And P.Cod_Dep = I.Cod_Dep And P.Cod_Produt = I.Cod_Produt) 
       left  join (Select Cod_Estabe, Cod_Dep, Cod_Produt, Sum(Qtd_Fisico) as QtdFis
                     From PRLTL 
                    Where Qtd_Saldo > 0
                    Group by Cod_Estabe, Cod_Dep, Cod_Produt) x on (P.Cod_Estabe = x.Cod_Estabe and P.Cod_Dep = x.Cod_Dep and P.Cod_Produt = x.Cod_Produt)
       left  join (Select Cod_Estabe, Cod_Dep, Cod_Produt, Sum(Qtd_Fisico) as QtdFis
                     From PRLOT
                    Where Qtd_Saldo > 0
                    Group by Cod_Estabe, Cod_Dep, Cod_Produt) y on (P.Cod_Estabe = y.Cod_Estabe and P.Cod_Dep = y.Cod_Dep and P.Cod_Produt = y.Cod_Produt)
 Where @FlgAtu = 1

-- ATualiza Vencto prox. lote em PRXES
Update P
   Set P.Dat_PrxVctLot = l.Dat_Vencim
  From PRXES P  
       inner join Inserted I on (P.Cod_Estabe = I.Cod_Estabe And P.Cod_Produt = I.Cod_Produt) 
       left  join (Select Cod_Estabe, Cod_Produt, Dat_Vencim = MIN(Dat_Vencim) 
                     From PRLOT 
                    Where Qtd_Saldo > 0 
                    Group by Cod_Estabe, Cod_Produt) l on ((P.Cod_Estabe = l.Cod_Estabe) and (P.Cod_Produt = l.Cod_Produt)) 
 Where @FlgAtu = 1

GO

SET ANSI_NULLS ON  
GO
SET QUOTED_IDENTIFIER ON
GO


Create Function [dbo].[FN_ViewPoliticaAtiva]
(
	@PIdPolCom int,
	@PDatRef smalldatetime
)

Returns Table

As

Return (
    Select Id_PolCom, 
           Case 
             When (Dat_Inicio Is Null or (IsNull(@PDatRef, cast(GetDate() as Date)) >= Dat_Inicio))
              And (Dat_Termino Is Null or (IsNull(@PDatRef, cast(GetDate() as Date)) <= Dat_Termino)) 
              And (Bloqueado = 0 Or Bloqueado Is Null)  Then Cast(1 As Bit) 
           Else Cast(0 As Bit) End As FlgPolOk
      From dbo.POCOM
     Where Id_PolCom = @PIdPolCom
);
GO

SET ANSI_NULLS ON  
GO
SET QUOTED_IDENTIFIER ON
GO

Create Function [dbo].[FN_PoliticaAtiva]
(
	@PIdPolCom int,
	@PDatRef smalldatetime
)

Returns bit

As
Begin
    Declare @FlgPolOk bit;

    Select @FlgPolOk = FlgPolOk 
      From dbo.FN_ViewPoliticaAtiva (@PIdPolCom, @PDatRef);

	-- Retorna o resultado da function
	Return IsNull(@FlgPolOk,0);
End
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_PRODU_AtualizaDados] ON [dbo].[PRODU] 
AFTER INSERT, UPDATE, DELETE 
NOT FOR REPLICATION
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 

-- Forma a data atual com a hora zerada 
Set DateFormat ymd

Declare @Date smalldatetime
Set @Date = GetDate()

if (Update(Descri) or Update(Aprese)) and ((Select top 1 FlgAltUnvItePdv From PARAM) = 1)
  begin
    Update P
      Set P.Descricao = Rtrim(I.Descri) + ' '  + I.Aprese
    From Inserted I inner Join PRODU P on P.Codigo = I.Codigo
  end

if (Update(Descricao)) and ((Select top 1 FlgAltUnvItePdv From PARAM) = 0)
  begin
    Update P
      Set P.Descri = Substring(I.Descricao,1,30),
          P.Aprese = Substring(I.Descricao, Case When (len(I.Descricao)-11) > 31 then (len(I.Descricao)-11) Else 31 End, 12)
    From Inserted I inner Join PRODU P on P.Codigo = I.Codigo
  end

if Update(Cod_GrpPrc)
  begin
    Update P
      Set P.Flg_Generico = Case
	                         When P.Cod_GrpPrc = 'G' then 1
							 Else 0
						End
    From Inserted I inner Join PRODU P on P.Codigo = I.Codigo
  end

if Update(Alt_Emb) or Update(Lrg_Emb) or Update(Prf_Emb)
  begin
    Update P
      Set P.Vol_Emb = I.Alt_Emb*I.Lrg_Emb*I.Prf_Emb
    From Inserted I inner Join PRODU P on P.Codigo = I.Codigo
    
    Update E    
       Set Qtd_UndEmb = 1, 
           Alt_Emb = IsNull(I.Alt_Emb,0), 
           Lrg_Emb = IsNull(I.Lrg_Emb,0), 
           Prf_Emb = IsNull(I.Prf_Emb,0),
           Qtd_EmbPalete = 0, 
           Qtd_CamPalete = 0
    From Inserted I Inner Join 
         PRODU P on P.Codigo = I.Codigo Inner Join 
         PREAN E on I.Codigo = E.Cod_Produt and I.Cod_Ean = E.Cod_Ean
  end

if Update(Unidade_Venda) or Update(Qtd_FraVen) or Update(Peso)
  begin
    Update E    
       Set Qtd_UndEmb = 1, 
           Des_UndEmb = IsNull(I.Unidade_Venda,''), 
           Qtd_FraVen = IsNull(I.Qtd_FraVen,0), 
           Pes_Emb = IsNull(I.Peso,0),
           Qtd_EmbPalete = 0, 
           Qtd_CamPalete = 0
    From Inserted I Inner Join 
         PRODU P on P.Codigo = I.Codigo Inner Join 
         PREAN E on I.Codigo = E.Cod_Produt and I.Cod_Ean = E.Cod_Ean
  end

if Update(Qtd_Embalagem) or Update(Und_EmbCmp) or Update(Pes_EmbCmp) or  
   Update(Alt_EmbCmp) or Update(Lrg_EmbCmp) or Update(Prf_EmbCmp) or
   Update(Qtd_EmbPalete) or Update(Qtd_CamPalete)
  begin
    Update E    
       Set Qtd_UndEmb = IsNull(I.Qtd_Embalagem,0), 
           Des_UndEmb = IsNull(I.Und_EmbCmp,''), 
           Qtd_FraVen = 0, 
           Pes_Emb = IsNull(I.Pes_EmbCmp,0),
           Alt_Emb = IsNull(I.Alt_EmbCmp,0), 
           Lrg_Emb = IsNull(I.Lrg_EmbCmp,0), 
           Prf_Emb = IsNull(I.Prf_EmbCmp,0), 
           Qtd_EmbPalete = IsNull(I.Qtd_EmbPalete,0), 
           Qtd_CamPalete = IsNull(I.Qtd_CamPalete,0)
    From Inserted I Inner Join 
         PRODU P on P.Codigo = I.Codigo Inner Join 
         PREAN E on I.Codigo = E.Cod_Produt and I.Cod_EanEmbCmp = E.Cod_Ean
  end

-- atualiza Prc_Fabric nos estabelecimentos
if Update(Prc_Fabric12)
  Update pr
     Set pr.Prc_Fabric = case 
                           when (Round(IsNull(es.Per_AlqIcm,0),2) = 12.00) or ((Charindex(es.Des_Estado,';MG;SP;') > 0) and (IsNull(p.Flg_Generico,0) = 1)) then p.Prc_Fabric12
                           else pr.Prc_Fabric
                         end,
		 pr.Dat_PrcFab = Convert(date, getdate())
    From Inserted I 
         inner join PRODU P  on P.Codigo = I.Codigo 
         inner join PRXES pr on P.Codigo = pr.Cod_Produt 
         inner join ESTAB es on pr.Cod_Estabe = es.Cod_Estabe
   Where pr.Prc_Fabric <> case 
                            when (Round(IsNull(es.Per_AlqIcm,0),2) = 12.00) or ((Charindex(es.Des_Estado,';MG;SP;') > 0) and (IsNull(p.Flg_Generico,0) = 1)) then p.Prc_Fabric12
                            else pr.Prc_Fabric
                          end

if Update(Prc_Fabric17)
  Update pr
     Set pr.Prc_Fabric = case 
                           when Round(IsNull(es.Per_AlqIcm,0),2) = 17.00 then p.Prc_Fabric17
                           else pr.Prc_Fabric
                         end,
	 	 pr.Dat_PrcFab = Convert(date, getdate())
    From Inserted I 
         inner join PRODU P  on P.Codigo = I.Codigo 
         inner join PRXES pr on P.Codigo = pr.Cod_Produt 
         inner join ESTAB es on pr.Cod_Estabe = es.Cod_Estabe
   Where pr.Prc_Fabric <> case 
                            when Round(IsNull(es.Per_AlqIcm,0),2) = 17.00 then p.Prc_Fabric17
                            else pr.Prc_Fabric
                          end

if Update(Prc_Fabric175)
  Update pr
     Set pr.Prc_Fabric = case 
                           when Round(IsNull(es.Per_AlqIcm,0),2) = 17.50 then p.Prc_Fabric175
                           else pr.Prc_Fabric
                         end,
		 pr.Dat_PrcFab = Convert(date, getdate())
    From Inserted I 
         inner join PRODU P  on P.Codigo = I.Codigo
         inner join PRXES pr on P.Codigo = pr.Cod_Produt 
         inner join ESTAB es on pr.Cod_Estabe = es.Cod_Estabe
   Where pr.Prc_Fabric <> case 
                            when Round(IsNull(es.Per_AlqIcm,0),2) = 17.50 then p.Prc_Fabric175
                            else pr.Prc_Fabric
                          end

if Update(Prc_Fabric18)
  Update pr
     Set pr.Prc_Fabric = case 
                           when Round(IsNull(es.Per_AlqIcm,0),2) = 18.00 then p.Prc_Fabric18
                           else pr.Prc_Fabric
                         end,
		 pr.Dat_PrcFab = Convert(date, getdate())
    From Inserted I 
         inner join PRODU P  on P.Codigo = I.Codigo 
         inner join PRXES pr on P.Codigo = pr.Cod_Produt
         inner join ESTAB es on pr.Cod_Estabe = es.Cod_Estabe
   Where pr.Prc_Fabric <> case 
