-- atualiza historico de preços
--if Update(Prc_UltEntLiq) or Update(Prc_UltEntLiqIpi) or 
if Update(Prc_RefFpb) or
   Update(Prc_Fabric12) or Update(Prc_MaxCon12) or 
   Update(Prc_Fabric17) or Update(Prc_MaxCon17) or 
   Update(Prc_Fabric175) or Update(Prc_MaxCon175) or 
   Update(Prc_Fabric18) or Update(Prc_MaxCon18) or 
   Update(Prc_Fabric19) or Update(Prc_MaxCon19) or 
   Update(Prc_Fabric195) or Update(Prc_MaxCon195) or 
   Update(Prc_Fabric20) or Update(Prc_MaxCon20) or 
   Update(Prc_Fabric205) or Update(Prc_MaxCon205) or 
   Update(Prc_Fabric21) or Update(Prc_MaxCon21) or 
   Update(Prc_Fabric22) or Update(Prc_MaxCon22) 
  begin
    Declare @CodEstabe int, 
            @CodProdut int, 
            @DatAltera smalldatetime,
            @NumSequen int

    DECLARE Table_Cr CURSOR Local Fast_Forward For 
      
	  /*Select es.Cod_Estabe, px.Codigo, @Date */
	  Select es.Cod_Estabe, px.Codigo, px.Transacao			 			 
        From ESTAB es 
		     Cross Join (Select I.Codigo,  
								Transacao = Case When I.Transacao > @Date Then I.Transacao /* DMD-7878 */
												 Else @Date 
											End 
                           From	Inserted I 
                                Inner Join Deleted D on I.Codigo = D.Codigo
                          --Where ( (IsNull(I.Prc_UltEntLiq,0)    <> IsNull(D.Prc_UltEntLiq,0)) or
                          --        (IsNull(I.Prc_UltEntLiqIpi,0) <> IsNull(D.Prc_UltEntLiqIpi,0)) or
                          Where ( (IsNull(I.Prc_RefFpb,0)       <> IsNull(D.Prc_RefFpb,0)) or
                                  (IsNull(I.Prc_Fabric12,0)     <> IsNull(D.Prc_Fabric12,0)) or
                                  (IsNull(I.Prc_MaxCon12,0)     <> IsNull(D.Prc_MaxCon12,0)) or 
                                  (IsNull(I.Prc_Fabric17,0)     <> IsNull(D.Prc_Fabric17,0)) or
                                  (IsNull(I.Prc_MaxCon17,0)     <> IsNull(D.Prc_MaxCon17,0)) or 
                                  (IsNull(I.Prc_Fabric175,0)    <> IsNull(D.Prc_Fabric175,0)) or
                                  (IsNull(I.Prc_MaxCon175,0)    <> IsNull(D.Prc_MaxCon175,0)) or
                                  (IsNull(I.Prc_Fabric18,0)     <> IsNull(D.Prc_Fabric18,0)) or
                                  (IsNull(I.Prc_MaxCon18,0)     <> IsNull(D.Prc_MaxCon18,0)) or
                                  (IsNull(I.Prc_Fabric19,0)     <> IsNull(D.Prc_Fabric19,0)) or
                                  (IsNull(I.Prc_MaxCon19,0)     <> IsNull(D.Prc_MaxCon19,0)) or
                                  (IsNull(I.Prc_Fabric195,0)    <> IsNull(D.Prc_Fabric195,0)) or
                                  (IsNull(I.Prc_MaxCon195,0)    <> IsNull(D.Prc_MaxCon195,0)) or
                                  (IsNull(I.Prc_Fabric20,0)     <> IsNull(D.Prc_Fabric20,0)) or
                                  (IsNull(I.Prc_MaxCon20,0)     <> IsNull(D.Prc_MaxCon20,0)) or
                                  (IsNull(I.Prc_Fabric205,0)    <> IsNull(D.Prc_Fabric205,0)) or
                                  (IsNull(I.Prc_MaxCon205,0)    <> IsNull(D.Prc_MaxCon205,0)) or
                                  (IsNull(I.Prc_Fabric21,0)     <> IsNull(D.Prc_Fabric21,0)) or
                                  (IsNull(I.Prc_MaxCon21,0)     <> IsNull(D.Prc_MaxCon21,0)) or
                                  (IsNull(I.Prc_Fabric22,0)     <> IsNull(D.Prc_Fabric22,0)) or
                                  (IsNull(I.Prc_MaxCon22,0)     <> IsNull(D.Prc_MaxCon22,0)) 
                                ) ) px 
    OPEN Table_Cr
    FETCH NEXT FROM Table_Cr INTO @CodEstabe, @CodProdut, @DatAltera
    WHILE @@FETCH_STATUS = 0
    BEGIN

      Exec PR_IncluiHSPRC @CodEstabe, @CodProdut, @DatAltera, @NumSequen output   

      Update H
        Set H.Vlr_RefFpb = I.Prc_RefFpb,
            --H.Vlr_PrcUltEntLiq = I.Prc_UltEntLiq,
            --H.Vlr_PrcUltEntLiqIpi = I.Prc_UltEntLiqIpi,
            H.Vlr_PrcFab12 = I.Prc_Fabric12,
            H.Vlr_PrcMaxCon12 = I.Prc_MaxCon12,
            H.Vlr_PrcFab17 = I.Prc_Fabric17,
            H.Vlr_PrcMaxCon17 = I.Prc_MaxCon17,
            H.Vlr_PrcFab175 = I.Prc_Fabric175,
            H.Vlr_PrcMaxCon175 = I.Prc_MaxCon175,
            H.Vlr_PrcFab18 = I.Prc_Fabric18,
            H.Vlr_PrcMaxCon18 = I.Prc_MaxCon18,
            H.Vlr_PrcFab19 = I.Prc_Fabric19,
            H.Vlr_PrcMaxCon19 = I.Prc_MaxCon19,
            H.Vlr_PrcFab195 = I.Prc_Fabric195,
            H.Vlr_PrcMaxCon195 = I.Prc_MaxCon195,
            H.Vlr_PrcFab20 = I.Prc_Fabric20,
            H.Vlr_PrcMaxCon20 = I.Prc_MaxCon20,
            H.Vlr_PrcFab205 = I.Prc_Fabric205,
            H.Vlr_PrcMaxCon205 = I.Prc_MaxCon205,
            H.Vlr_PrcFab21 = I.Prc_Fabric21,
            H.Vlr_PrcMaxCon21 = I.Prc_MaxCon21,
            H.Vlr_PrcFab22 = I.Prc_Fabric22,
            H.Vlr_PrcMaxCon22 = I.Prc_MaxCon22,
            H.Usuario = Substring(dbo.FN_UsuarioInfarma(),1,15)
      From HSPRC H 
		   inner Join Inserted I on H.Cod_Produto = I.Codigo
      Where H.Cod_Estabe  = @CodEstabe
      and H.Cod_Produto   = @CodProdut 
      and H.Dat_Alteracao = @DatAltera
      and H.Seq_Alteracao = @NumSequen

      FETCH NEXT FROM Table_Cr INTO @CodEstabe, @CodProdut, @DatAltera
    END
    CLOSE Table_Cr
    DEALLOCATE Table_Cr
  end

