CREATE FUNCTION [dbo].[FN_ViewPoliticasProduto] 
(
       @PIdPolComPriori int,     
       @PCodPrd int,
       @PDatRef smalldatetime
)

RETURNS TABLE 
AS 
RETURN (

  Select distinct
         v.Nivel, v.Ordem, v.Id_PolCom, 
         v.Prc_Promoc, v.Qtd_PrzMax, v.Per_Descon, v.Per_DscVis,
         v.Qtd_Minimo, v.Qtd_Maximo 

  From (Select Nivel = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 'C'
                         Else 'H'
                       End, 
               Ordem = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 08 
                         Else 18 
                       End,
               it.Id_PolCom, 0 as Prc_Promoc, 
               it.Qtd_PrzMax, it.Per_Descon, it.Per_DscVis, 1 as Qtd_Minimo, 0 as Qtd_Maximo
        From PCXCP it 
             Inner Join PRODU p on it.Cod_Classi = substring(p.Cod_Classif,1,2)
        Where p.Codigo = @PCodPrd
        And not Exists (Select 1 From PCXPR x Where x.Id_PolCom = it.Id_PolCom and x.Cod_Produt = @PCodPrd) 
                       
        -- PCXFB
        Union All
        Select Nivel = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 'B'
                         Else 'G'
                       End, 
               Ordem = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 07 
                         Else 17 
                       End, 
               it.Id_PolCom, 0 as Prc_Promoc, 
               it.Qtd_PrzMax, it.Per_Descon, it.Per_DscVis, 1 as Qtd_Minimo, 0 as Qtd_Maximo
        From PCXFB it 
             Inner Join PRODU p on it.Cod_Fabric = p.Cod_Fabricante
        Where p.Codigo = @PCodPrd
        And not Exists (Select 1 From PCXPR x Where x.Id_PolCom = it.Id_PolCom and x.Cod_Produt = @PCodPrd) 
        
        -- PCXPR
        Union All
        Select Nivel = Case 
                        When it.Id_PolCom = @PIdPolComPriori then 'A'
                        Else 'F'
                      End, 
               Ordem = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 05 
                         Else 15 
                       End, 
               it.Id_PolCom, it.Prc_Promoc, 
               it.Qtd_PrzMax, it.Per_Descon, it.Per_DscVis, it.Qtd_Minimo, IsNull(it.Qtd_Maximo,0) as Qtd_Maximo
        From PCXPR it 
        Where it.Qtd_Minimo > 0 
        And it.Cod_Produt = @PCodPrd 
        Union All 
        Select Nivel = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 'A'
                         Else 'F'
                       End, 
               Ordem = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 04 
                         Else 14 
                       End, 
               it.Id_PolCom, it.Prc_Promoc, 
               it.Qtd_PrzMax, it.Per_Dsc2 as Per_Descon, it.Per_DscVis2 as Per_DscVis, it.Qtd_Min2 as Qtd_Minimo, IsNull(it.Qtd_Max2,0) as Qtd_Maximo
        From PCXPR it 
        Where it.Qtd_Min2 > 0 
        And it.Cod_Produt = @PCodPrd 
        Union All 
        Select Nivel = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 'A'
                         Else 'F'
                       End, 
               Ordem = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 03 
                         Else 13 
                       End, 
               it.Id_PolCom, it.Prc_Promoc, 
               it.Qtd_PrzMax, it.Per_Dsc3 as Per_Descon, it.Per_DscVis3 as Per_DscVis, it.Qtd_Min3 as Qtd_Minimo, IsNull(it.Qtd_Max3,0) as Qtd_Maximo
        From PCXPR it 
        Where it.Qtd_Min3 > 0 
        And it.Cod_Produt = @PCodPrd 
        Union All 
        Select Nivel = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 'A'
                         Else 'F'
                       End, 
               Ordem = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 02 
                         Else 12 
                       End, 
               it.Id_PolCom, it.Prc_Promoc, 
               it.Qtd_PrzMax, it.Per_Dsc4 as Per_Descon, it.Per_DscVis4 as Per_DscVis, it.Qtd_Min4 as Qtd_Minimo, IsNull(it.Qtd_Max4,0) as Qtd_Maximo
        From PCXPR it 
        Where it.Qtd_Min4 > 0 
        And it.Cod_Produt = @PCodPrd 
        Union All 
        Select Nivel = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 'A'
                         Else 'F'
                       End, 
               Ordem = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 01 
                         Else 11 
                       End, 
               it.Id_PolCom, it.Prc_Promoc, 
               it.Qtd_PrzMax, it.Per_Dsc5 as Per_Descon, it.Per_DscVis5 as Per_DscVis, it.Qtd_Min5 as Qtd_Minimo, IsNull(it.Qtd_Max5,0) as Qtd_Maximo
        From PCXPR it 
        Where it.Qtd_Min5 > 0 
        And it.Cod_Produt = @PCodPrd 
        -- produto q nao atingiu quantidade minima
        Union All 
        Select Nivel = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 'A'
                         Else 'F'
                       End, 
               Ordem = Case 
                         When it.Id_PolCom = @PIdPolComPriori then 06 
                         Else 16 
                       End, 
               it.Id_PolCom, 0 as Prc_Promoc, 
               it.Qtd_PrzMax, 0 as Per_Descon, 0 as Per_DscVis, 1 as Qtd_Minimo, 0 as Qtd_Maximo
        From PCXPR it 
        Where it.Qtd_Minimo > 1 
        And (Isnull(it.Per_Descon,0)+IsNull(it.Per_DscVis,0)) <> 0 
        And it.Cod_Produt = @PCodPrd) v
      
       Inner Join POCOM pc on v.Id_PolCom = pc.Id_PolCom
	   --Cross Apply dbo.FN_ViewPoliticaAtiva(pc.Id_PolCom, @PDatRef) vw

  Where pc.Tip_PolCom <> 'KIT'
--    And vw.FlgPolOk = 1
    And dbo.FN_TransacaoAtiva(pc.Dat_Inicio, pc.Dat_Termino, @PDatRef, pc.Bloqueado) = 1

);
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_RetornaPoliticasProduto]
(
 @PCodOri varchar(1),      -- Origem (A-Ativo, P-Receptivo, M-Móvel, T-Eletronico/EDI, W-Internet/WEB, H-Hospitalar, D-por Desdobramento, V-por Val)
 @PCodEstabe int,          -- OPCIONAL: cod.estabe: -1 
 @PCodCli int,             
 @PCodVdr int,             -- OPCIONAL: cod.vendedor: 0 
 @PCodOpe int,             -- OPCIONAL: cod.operador: 0 
 @PIdPolComCab int,     
 @PCodPrd int,
 @PDatRef smalldatetime,
 @PCodLayPde int,          -- OPCIONAL: layout pedido eletronico: 0
 @PCodGrpLay int           -- OPCIONAL: grupo do layout pedido eletronico: 0
)

RETURNS @retPoliticas TABLE 
  ( Cod_Estabe int, 
	Id_PolCom int,
    Cod_PolCom varchar(25),
	Dat_Cadastro smalldatetime,
	Flg_NegDsc bit,
    Flg_AcuVrbPos bit, 
    Flg_AcuVrbNeg bit, 
    Flg_MarkupCusCom bit, 
    Tip_RatBon varchar(1), 
    Tip_GerVrb varchar(1), 
    Flg_CtrPdvVrbVdr bit, 
    Flg_CtrPdvVrbOpe bit, 
    Controle_Saldo varchar(1), 
    Per_AcrAutPrc numeric(9,4), 
    Per_DscAutPrc numeric(9,4), 
    Prc_Promoc numeric(18,8), 
    Qtd_PrzMax smallint, 
    Per_Descon numeric(7,4), 
	Per_DscVis numeric(7,4), 
    Qtd_Minimo smallint, 
	Qtd_Maximo smallint, 
    Ordem smallint, 
    Nivel varchar(1),
    Val_PrcTab numeric(18,4),
    Per_DscMaxTab numeric(7,4),
    Prc_Unitar numeric(18,4)
  ) 

--Retorna todas politicas permitidas para o produto

AS

BEGIN

Declare @pr_CodCla varchar(2),
		@WTipPrz char(1),
		@WFlgExcClaPolComCab bit,
        @WQtdPrzPolComCab int,
        @WFlgPolCabBlqOutPolIte bit

Set @pr_CodCla = IsNull((Select Substring(Cod_Classif,1,2) From PRODU Where Codigo = @PCodPrd),'')

Set @WQtdPrzPolComCab = 0
Set @WFlgPolCabBlqOutPolIte = 0
Set @WTipPrz = 'F'
Set @WFlgExcClaPolComCab = 0

if Exists(Select 1 From POCOM Where Id_PolCom = @PIdPolComCab)
  Select @WQtdPrzPolComCab = IsNull(pc.Qtd_PrzMax,0),
         @WFlgPolCabBlqOutPolIte = IsNull(pc.Flg_BlqPolDifItePdv,0),
		 @WTipPrz = IsNull(pc.Cod_TipPrz,'F'),
         @WFlgExcClaPolComCab = IsNull(pc.Flg_ExcCla,0)
    From POCOM pc   
	     left join PCXCP cp on pc.Id_PolCom = cp.Id_PolCom
   Where pc.Id_PolCom = @PIdPolComCab

Delete From @retPoliticas

Insert Into @retPoliticas
  Select pe.Cod_Estabe, p.Id_PolCom, p.Cod_PolCom, p.Dat_Cadastro, Flg_NegDsc=IsNull(p.Flg_NegDsc,0), 
         Flg_AcuVrbPos=IsNull(p.Flg_AcuVrbPos,0), Flg_AcuVrbNeg=IsNull(p.Flg_AcuVrbNeg,0), 
	     Flg_MarkupCusCom=IsNull(p.Flg_MarkupCusCom,0), Tip_RatBon=IsNull(p.Tip_RatBon,''), 
         TipGerVrb = dbo.FN_TipGerVrbPdv(p.Id_PolCom), Flg_CtrPdvVrbVdr=IsNull(p.Flg_CtrPdvVrbVdr,0), Flg_CtrPdvVrbOpe=IsNull(p.Flg_CtrPdvVrbOpe,0), 
         Controle_Saldo=IsNull(p.Controle_Saldo,''), Per_AcrAutPrc=IsNull(p.Per_AcrAutPrc,0), Per_DscAutPrc=IsNull(p.Per_DscAutPrc,0), 
         s.Prc_Promoc, s.Qtd_PrzMax, s.Per_Descon, s.Per_DscVis, s.Qtd_Minimo, s.Qtd_Maximo, s.Ordem, s.Nivel, 
         Val_PrcTab = IsNull(tp.Val_PrcVen,0), Per_DscMaxTab = IsNull(tp.Per_DscMax,0),
         Prc_Uni = Case
                     When s.Prc_Promoc > 0 then s.Prc_Promoc
                     When IsNull(tp.Val_PrcVen,0) > 0 then tp.Val_PrcVen
                     When IsNull(p.Per_AcrAutPrc,0) > 0 then Round(IsNull(pr.Prc_Venda,0)*(1+p.Per_AcrAutPrc/100),IsNull(pm.QtdDecPrcItePdv,0))
                     When IsNull(p.Per_DscAutPrc,0) > 0 then Round(IsNull(pr.Prc_Venda,0)*(1-p.Per_DscAutPrc/100),IsNull(pm.QtdDecPrcItePdv,0))
                     Else Round(IsNull(pr.Prc_Venda,0)*(1-IsNull(pr.Per_DscAut,0)/100),IsNull(pm.QtdDecPrcItePdv,0))
                   End
    From POCOM p 
		 --Cross Apply dbo.FN_ViewPoliticaAtiva(p.Id_PolCom, @PDatRef) vw
--         Inner Join PCXES pe on ((p.Id_PolCom = pe.Id_PolCom) and (pe.Cod_Estabe = @PCodEstabe)) 
         Inner Join PCXES pe on ((p.Id_PolCom = pe.Id_PolCom) and ( ((@PCodEstabe > -1) and (pe.Cod_Estabe = @PCodEstabe)) or (@PCodEstabe < 0)) ) 
         Inner Join PARAM pm on pe.Cod_Estabe = pm.Cod_Estabe
         Inner Join PRXES pr on pe.Cod_Estabe = pr.Cod_Estabe and pr.Cod_Produt = @PCodPrd

         Inner Join CLIEN cl on cl.Codigo = @PCodCli
         Left  Join ENXES es on es.Cod_Estabe = @PCodEstabe and es.Num_CgcCpf = cl.Cgc_Cpf and es.Cod_Client = cl.Codigo
         Left  Join PCXCL pc on ((p.Id_PolCom = pc.Id_PolCom) and (pc.Cod_Client = cl.Codigo)) 
         Left  Join PCXGC pg on ((p.Id_PolCom = pg.Id_PolCom) and (pg.Cod_GrpCli = cl.Cod_GrpCli)) 
         Left  Join PCXUF pu on ((p.Id_PolCom = pu.Id_PolCom) and (pu.Cod_Uf = cl.Cod_Estado)) 
         Left  Join PCXVE pv on ((p.Id_PolCom = pv.Id_PolCom) and (pv.Cod_Vended = @PCodVdr)) 
         Left  Join PCXOP po on ((p.Id_PolCom = po.Id_PolCom) and (po.Cod_Vended = @PCodOpe)) 
         Left  Join TBPRC tb on ((tb.Cod_Estabe = @PCodEstabe) or (tb.Flg_AllEstabe = 1)) 
		                    and (tb.Cod_TabPrc = Case 
                                                   When (IsNull(p.Flg_UsaTabPrcCadCli,0) = 1) and (IsNull(es.Cod_TabPrc,0) > 0) 
                                                     then es.Cod_TabPrc 
                                                   Else p.Cod_TabPrc
                                                 End)
         Left  Join TPXPR tp on ((tb.Cod_Estabe = tp.Cod_Estabe) and (tb.Cod_TabPrc = tp.Cod_TabPrc) and (tp.Cod_Produt = @PCodPrd))
         Left  Join dbo.FN_ViewPoliticasProduto(@PIdPolComCab, @PCodPrd, @PDatRef) s on (p.Id_PolCom = s.Id_PolCom) 

         Left  Join LGXPC lp on (lp.Cod_Estabe = @PCodEstabe and lp.Cod_Layout = @PCodLayPde and lp.Cod_Grupo = @PCodGrpLay and lp.Id_PolCom = p.Id_PolCom)
         Left  Join TBLPG lg on (lg.Cod_Estabe = lp.Cod_Estabe and lg.Cod_Layout = lp.Cod_Layout and lg.Cod_Grupo = lp.Cod_Grupo)

 Where ( (pc.Cod_Client > 0) or (pg.Cod_GrpCli > 0) or (pu.Cod_Uf <> '') ) 
   And ( (@PCodVdr = 0) or ((@PCodVdr > 0) and (pv.Cod_Vended = @PCodVdr)) )
   And ( (@PCodOpe = 0) or ((@PCodOpe > 0) and (po.Cod_Vended = @PCodOpe)) )
   And IsNull(s.Ordem,0) > 0

   And p.Tip_PolCom <> 'KIT'
   And ( (p.Dat_Inicio Is Null  or (@PDatRef >= p.Dat_Inicio))  and
         (p.Dat_Termino Is Null or (@PDatRef <= p.Dat_Termino)) and
         (p.Bloqueado Is Null or p.Bloqueado = 0) ) 

   And (((@WTipPrz = 'L') and (s.Qtd_PrzMax >= @WQtdPrzPolComCab)) or 
        (@WTipPrz = 'F')) 
   And ((p.Flg_BlqCli = 0) or ((p.Flg_BlqCli = 1) and (IsNull(cl.Flg_BlqPrm,0) = 0)))

   And (((@PCodOri = 'M') and (p.Flg_Cfv = 1)) or
        ((@PCodOri = 'T') and (p.Flg_PedEle = 1)) or
        ((@PCodOri = 'W') and (p.Flg_Web = 1)) or
        ((Charindex(@PCodOri,';M;T;W;') = 0) and (p.Flg_Televendas = 1)))

   And @pr_CodCla = Case
                      When @WFlgExcClaPolComCab = 1 then 
                        Case
                          When Exists(Select Cod_Classi From PCXCP Where Id_PolCom = @PIdPolComCab And Cod_Classi = @pr_CodCla) then @pr_CodCla
                          Else '??'
                        End
                      Else @pr_CodCla
                    End

-- verifica se politica do cabecalho permite outrqas politica no item
   And p.Id_PolCom = Case
                       When @WFlgPolCabBlqOutPolIte = 1 then @PIdPolComCab
	                   Else p.Id_PolCom
                     End
-- verifica se há restrição de uso da politica do item
   And ((p.Flg_BlqPolDifCabPdv = 0) or (p.Id_PolCom = @PIdPolComCab))

-- verifica politicas vinculadas ao layout
   And ((IsNull(lg.Flg_UsaPolVnc,0) = 1) and (IsNull(lp.Id_PolCom,0) > 0) or (IsNull(lg.Flg_UsaPolVnc,0) = 0))

 Order by s.Nivel, pe.Cod_Estabe, p.Dat_Cadastro, s.Ordem, s.Id_PolCom 

RETURN
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ReprocessaEstoquePulmao]
@PCodEstabe int,
@PCodPrd int

WITH RECOMPILE
AS

SET NOCOUNT ON 

Update pr 
   Set pr.Qtd_Pulmao = IsNull(vp.C_QtdPulmao,0)
  From dbo.PRXES pr
       left Join dbo.V_PULMAO vp on pr.Cod_Estabe = vp.Cod_Estabe and pr.Cod_Produt = vp.Cod_Produto
 Where pr.Cod_Estabe = @PCodEstabe
   And ((@PCodPrd > 0) and (pr.Cod_Produt = @PCodPrd) or (@PCodPrd <= 0))
   and pr.Qtd_Pulmao <> IsNull(vp.C_QtdPulmao,0)

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CorrigeQtdLoteProduto]
@PCodEstabe int,
@PCodPed int,
@PCodPrd int

AS

SET NOCOUNT ON

Set DateFormat ymd

-- corrige quantidades solicitades de lotes de um produto não multiplos de fator de conversão do item

Begin Transaction
  
Declare @CodDep smallint,
        @FatBon numeric(18,8),
        @FatCnvImpFat int,
        @FlgMov bit,
        @QtdPedAju int,
        @QtdBonAju int,
        @QtdMovPra int,
        @QtdMovDep int,
        @QtdMov int,

        @cr_CodLot varchar(20), 
        @cr_TipSai varchar(1),
        @cr_NumVol int,
        @cr_QtdSai int,
        @cr_QtdPed int,
        @cr_QtdBon int,
        @cr_QtdPra int,
        @cr_QtdDep int,
        @cr_QtdTot int


-- SEM WMS
if (Select IsNull(Flg_WMS,0) From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PCodPed) = 0
  begin
    -- sem WMS: deposito unico
    Set @CodDep = IsNull((Select min(Cod_Dep) 
                            From TBDEP 
                           Where Cod_Estabe = @PCodEstabe),1)
    
    Set @FlgMov = 1
    
    While (@FlgMov = 1) and
          Exists(Select 1
                   From PDVIT 
                  Where Cod_Estabe = @PCodEstabe
                    And Cod_Pedido = @PCodPed
                    And Cod_Produto = @PCodPrd
                    And (Qtd_Pedido+Qtd_Bonificacao) > 0
                  Group by Cod_Produto, Cod_Lote, Tip_Sai, Fat_CnvImpFat
                 Having ((sum(Qtd_Pedido+Qtd_Bonificacao)) % Fat_CnvImpFat) > 0)
      begin

        Select top 1 
               @cr_CodLot = Cod_Lote, 
               @cr_TipSai = Tip_Sai,
               @cr_QtdSai = sum((Qtd_Pedido+Qtd_Bonificacao)) % Fat_CnvImpFat
          From PDVIT 
         Where Cod_Estabe = @PCodEstabe
           And Cod_Pedido = @PCodPed
           And Cod_Produto = @PCodPrd
           And (Qtd_Pedido+Qtd_Bonificacao) > 0
         Group by Cod_Produto, Cod_Lote, Tip_Sai, Fat_CnvImpFat
        Having ((sum(Qtd_Pedido+Qtd_Bonificacao)) % Fat_CnvImpFat) > 0
    
        while (@FlgMov = 1) and (@cr_QtdSai > 0) and
              Exists(Select 1
                       From PDVIT
                      Where Cod_Estabe = @PCodEstabe
                        And Cod_Pedido = @PCodPed
                        And Cod_Produto = @PCodPrd
                        And Cod_Lote = @cr_CodLot
                        And Tip_Sai = @cr_TipSai
                        And (Qtd_Pedido+Qtd_Bonificacao) > 0
                        And (Qtd_Pedido+Qtd_Bonificacao) = (Qtd_Pra+Qtd_Dep))
          begin
            Select @cr_QtdPed = Qtd_Pedido, 
                   @cr_QtdBon = Qtd_Bonificacao,
                   @cr_QtdPra = Qtd_Pra, 
                   @cr_QtdDep = Qtd_Dep
              From PDVIT
             Where Cod_Estabe = @PCodEstabe
               And Cod_Pedido = @PCodPed
               And Cod_Produto = @PCodPrd
               And Cod_Lote = @cr_CodLot
               And Tip_Sai = @cr_TipSai
               And (Qtd_Pedido+Qtd_Bonificacao) > 0
    
            if @cr_QtdBon = 0
              begin
    		    Set @QtdMov = @cr_QtdSai
    
                Set @QtdMovDep = Case 
                                   When @cr_QtdDep > @QtdMov then @QtdMov
                                   Else @cr_QtdDep
                                 End
                Set @QtdMov = @QtdMov - @QtdMovDep
    	       
                Set @QtdMovPra = Case 
                                   When @cr_QtdPra > @QtdMov then @QtdMov
                                   Else @cr_QtdPra
                                 End
    
    			Set @QtdPedAju = @cr_QtdPed - @QtdMovDep - @QtdMovPra
    			Set @QtdBonAju = 0
              end
            else
              begin
                Set @cr_QtdTot = @cr_QtdPed + @cr_QtdBon
                Set @FatBon = @cr_QtdBon*1.0/@cr_QtdPed*1.0
    
                -- dar saída em 1 unidade
    			-- refaz proporcionalidade bonificação
                Set @cr_QtdTot = @cr_QtdTot - 1
                Set @QtdBonAju = @FatBon*@cr_QtdTot/(1+@FatBon) + 0.05
                Set @QtdPedAju = @QtdBonAju/@FatBon
    			if (@QtdPedAju+@QtdBonAju) > @cr_QtdTot
                  Set @QtdPedAju = @cr_QtdTot-@QtdBonAju
    
                -- qtd a movimentar (dar saída)
                Set @QtdMov = (@cr_QtdPed+@cr_QtdBon) - (@QtdPedAju+@QtdBonAju)
    
                -- dar saída em QtdMov
                Set @QtdMovDep = Case 
                                   When @cr_QtdDep > @QtdMov then @QtdMov
                                   Else @cr_QtdDep
                                 End
                Set @QtdMov = @QtdMov - @QtdMovDep
    	       
                Set @QtdMovPra = Case 
                                   When @cr_QtdPra > @QtdMov then @QtdMov
                                   Else @cr_QtdPra
                                 End
              end
    
            if (@QtdMovPra+@QtdMovDep) <= 0
              Set @FlgMov = 0
    
            if (@FlgMov = 1) and
    		   Exists(Select 1
                        From PRLOT
                       Where Cod_Estabe = @PCodEstabe 
                         And Cod_Dep = @CodDep
                         And Cod_Produt = @PCodPrd
                         And Cod_Lote = @cr_CodLot
                         And Qtd_SolPra >= @QtdMovPra
                         And Qtd_SolDep >= @QtdMovDep) and
               Exists(Select 1
                        From PDVIT
                       Where Cod_Estabe = @PCodEstabe 
                         And Cod_Pedido = @PCodPed 
                         And Cod_Produto = @PCodPrd 
                         And Cod_Lote = @cr_CodLot
                         And Tip_Sai = @cr_TipSai
                         And Qtd_Pra >= @QtdMovPra
                         And Qtd_Dep >= @QtdMovDep)
              begin
    	 	    Set @FlgMov = 1
                Set @cr_QtdSai = @cr_QtdSai - @QtdMovDep - @QtdMovPra
    	
                Update PRLOT
                   Set Qtd_SolPra = Qtd_SolPra - @QtdMovPra, 
                       Qtd_SolDep = Qtd_SolDep - @QtdMovDep
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Dep = @CodDep
                   And Cod_Produt = @PCodPrd
                   And Cod_Lote = @cr_CodLot
                   And Qtd_SolPra >= @QtdMovPra
                   And Qtd_SolDep >= @QtdMovDep
    	
                Update PDVIT
                   Set Qtd_Pra = Qtd_Pra - @QtdMovPra, 
                       Qtd_Dep = Qtd_Dep - @QtdMovDep, 
                       Qtd_Pedido = @QtdPedAju,
                       Qtd_Bonificacao = @QtdBonAju
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Pedido = @PCodPed 
                   And Cod_ProdutO = @PCodPrd 
                   And Cod_Lote = @cr_CodLot
                   And Tip_Sai = @cr_TipSai
                   And Qtd_Pra >= @QtdMovPra
                   And Qtd_Dep >= @QtdMovDep
              end  -- if Exists(Select 1
    
            else
              Set @FlgMov = 0
          end  -- while (@FlgMov = 1) and (@cr_QtdSai > 0) and
    
      end  -- While (@FlgMov = 1) and
  end  -- if (Select IsNull(Flg_WMS,0) 

-- com WMS
if (Select IsNull(Flg_WMS,0) From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PCodPed) = 1
  begin
    Set @FatCnvImpFat = IsNull((Select max(IsNull(Fat_CnvImpFat,1))
                                  From PDVIT
                                 Where Cod_Estabe = @PCodEstabe 
                                   And Cod_Pedido = @PCodPed
                                   And Cod_Produto = @PCodPrd),1)

    Set @FlgMov = 1
    
    While (@FlgMov = 1) and
          Exists(Select 1
                   From PDVLT 
                  Where Cod_Estabe = @PCodEstabe
                    And Cod_Pedido = @PCodPed
                    And Cod_Produt = @PCodPrd
                    And Qtd_Lote > 0
                    And Qtd_CxaFec = 0  -- somente fracionados
                  Group by Cod_Dep, Cod_Produt, Cod_Lote
                 Having (sum(Qtd_Lote) % @FatCnvImpFat) > 0)
      begin
    
        Select top 1 
               @CodDep = Cod_Dep, 
               @cr_CodLot = Cod_Lote, 
               @cr_QtdSai = sum(Qtd_Lote) % @FatCnvImpFat
          From PDVLT 
         Where Cod_Estabe = @PCodEstabe
           And Cod_Pedido = @PCodPed
           And Cod_Produt = @PCodPrd
           And Qtd_Lote > 0
           And Qtd_CxaFec = 0  -- somente fracionados
         Group by Cod_Dep, Cod_Produt, Cod_Lote
        Having (sum(Qtd_Lote) % @FatCnvImpFat) > 0
    
        while (@FlgMov = 1) and (@cr_QtdSai > 0) and
              Exists(Select 1
                       From PDVLT
                      Where Cod_Estabe = @PCodEstabe
                        And Cod_Pedido = @PCodPed
                        And Cod_Dep    = @CodDep
                        And Cod_Produt = @PCodPrd
                        And Cod_Lote   = @cr_CodLot
                        And Qtd_CxaFec = 0  -- somente fracionados
                        And Qtd_Lote > 0
                        And Qtd_Lote = (Qtd_LotePra+Qtd_LoteDep))
          begin
            Select @cr_NumVol = Num_Vol,
			       @cr_QtdPed = Qtd_Lote, 
                   @cr_QtdPra = Qtd_LotePra, 
                   @cr_QtdDep = Qtd_LoteDep
              From PDVLT
             Where Cod_Estabe = @PCodEstabe
               And Cod_Pedido = @PCodPed
               And Cod_Dep    = @CodDep
               And Cod_Produt = @PCodPrd
               And Cod_Lote   = @cr_CodLot
               And Qtd_CxaFec = 0
               And Qtd_Lote > 0
             Order by Num_Vol desc
    
    		Set @QtdMov = @cr_QtdSai
    
            Set @QtdMovDep = Case 
                               When @cr_QtdDep > @QtdMov then @QtdMov
                               Else @cr_QtdDep
                             End
            Set @QtdMov = @QtdMov - @QtdMovDep
    	       
            Set @QtdMovPra = Case 
                               When @cr_QtdPra > @QtdMov then @QtdMov
                               Else @cr_QtdPra
                             End
    
            Set @QtdPedAju = @cr_QtdPed - @QtdMovDep - @QtdMovPra
    
            if (@QtdMovPra+@QtdMovDep) <= 0
              Set @FlgMov = 0
    
            if (@FlgMov = 1) and
    		   Exists(Select 1
                        From PRLOT
                       Where Cod_Estabe = @PCodEstabe 
                         And Cod_Dep = @CodDep
                         And Cod_Produt = @PCodPrd
                         And Cod_Lote = @cr_CodLot
                         And Qtd_SolPra >= @QtdMovPra
                         And Qtd_SolDep >= @QtdMovDep) and
               Exists(Select 1
                        From PDVLT
                       Where Cod_Estabe = @PCodEstabe 
                         And Cod_Pedido = @PCodPed 
                         And Num_Vol    = @cr_NumVol
                         And Cod_Dep    = @CodDep
                         And Cod_Produt = @PCodPrd 
                         And Cod_Lote   = @cr_CodLot
                         And Qtd_LotePra >= @QtdMovPra
                         And Qtd_LoteDep >= @QtdMovDep)
              begin
    	 	    Set @FlgMov = 1
                Set @cr_QtdSai = @cr_QtdSai - @QtdMovDep - @QtdMovPra
    	
                Update PRLOT
                   Set Qtd_SolPra = Qtd_SolPra - @QtdMovPra, 
                       Qtd_SolDep = Qtd_SolDep - @QtdMovDep
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Dep = @CodDep
                   And Cod_Produt = @PCodPrd
                   And Cod_Lote = @cr_CodLot
                   And Qtd_SolPra >= @QtdMovPra
                   And Qtd_SolDep >= @QtdMovDep
    	
                Update PDVLT
                   Set Qtd_LotePra = Qtd_LotePra - @QtdMovPra, 
                       Qtd_LoteDep = Qtd_LoteDep - @QtdMovDep, 
                       Qtd_Lote = @QtdPedAju
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Pedido = @PCodPed 
                   And Num_Vol = @cr_NumVol
                   And Cod_Dep = @CodDep
                   And Cod_Produt = @PCodPrd 
                   And Cod_Lote = @cr_CodLot
                   And Qtd_LotePra >= @QtdMovPra
                   And Qtd_LoteDep >= @QtdMovDep
              end  -- if Exists(Select 1
    
            else
              Set @FlgMov = 0
          end  -- while (@FlgMov = 1) and (@cr_QtdSai > 0) and
    
      end  -- While (@FlgMov = 1) and

    Delete From PDVLT
     Where Cod_Estabe = @PCodEstabe 
       And Cod_Pedido = @PCodPed 
       And Cod_Produt = @PCodPrd 
       And (Qtd_Lote+Qtd_LotePra+Qtd_LoteDep) = 0
  end

Commit Transaction
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_SolicitaLoteProduto]
@PCodEstabe int,
@PCodPed int,
@PFlgLotEsp bit,
@PCodPrd int,
@PCodLot varchar(20),
@PTipSai varchar(1),
@PCodPrm int,
@PCodKitPrm int,
@PQtdPed int,
@PQtdBon int,
@PFatCnvImpFat int,
@PFlgLotNaoFra bit

AS

SET NOCOUNT ON

Set DateFormat ymd

Begin Transaction

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

if @PQtdPed is null 
  Set @PQtdPed = 0
if @PQtdBon is null 
  Set @PQtdBon = 0
if IsNull(@PFatCnvImpFat,0) = 0
  Set @PFatCnvImpFat = 1
  
-- corrige saldos negativos
if Exists(Select Cod_Produt
            From PRLOT 
           Where Cod_Estabe = @PCodEstabe
             And Cod_Produt = @PCodPrd
             And ((Qtd_SolPra < 0) or (Qtd_SolDep < 0)))
  begin
    Update PRLOT
       Set Qtd_SolPra = 0
     Where Cod_Estabe = @PCodEstabe
       And Cod_Produt = @PCodPrd
       And Qtd_SolPra < 0
    
    Update PRLOT
       Set Qtd_SolDep = 0
     Where Cod_Estabe = @PCodEstabe
       And Cod_Produt = @PCodPrd
       And Qtd_SolDep < 0
  end

if Exists(Select Cod_Produt
            From PRLOT 
           Where Cod_Estabe = @PCodEstabe
             And Cod_Produt = @PCodPrd
             And ((Qtd_Saldo < 0) or (Qtd_Fisico < 0) or (Qtd_SldPra < 0) or (Qtd_FisPra < 0) or (Qtd_SldDep < 0) or (Qtd_FisDep < 0)))
  begin
    Update PRLOT
       Set Qtd_FisPra = Qtd_FisPra + Abs(Qtd_SldPra)
     Where Cod_Estabe = @PCodEstabe
       And Cod_Produt = @PCodPrd
       And Qtd_SldPra < 0
    
    Update PRLOT
       Set Qtd_FisDep = Qtd_FisDep + Abs(Qtd_SldDep)
     Where Cod_Estabe = @PCodEstabe
       And Cod_Produt = @PCodPrd
       And Qtd_SldDep < 0
  end
  
-- garante bloqueio do registro
Update PRXES
   Set Qtd_Solici = 0
 Where Cod_Estabe = @PCodEstabe 
   And Cod_Produt = @PCodPrd
   And Qtd_Solici < 0

Update PRXES
   Set Qtd_PrmSolici = 0
 Where Cod_Estabe = @PCodEstabe   
   And Cod_Produt = @PCodPrd
   And Qtd_PrmSolici < 0
  
Update PRXES
   Set Qtd_Solici = Qtd_Solici + 0
 Where Cod_Estabe = @PCodEstabe
   And Cod_Produt = @PCodPrd

Declare @CodDep smallint,
        @QtdPedAju int,
        @QtdBonAju int,
        @FatBon numeric(18,8),
        @PedSol int,
        @BonSol int,
        @CodLotPri varchar(20),  -- primeiro lote solicitado
        @CodLotEsp varchar(20),  -- lote especifico
        @lt_LocEst varchar(1),
        @lt_DatVct smalldatetime,
        @lt_CodLot varchar(20),
        @lt_SldLot int,
        @AccQtdAte int,
        @AccBonAte int,
        @QtdDsp int,
		@QtdLotDsp int,
        @QtdDspPrd int,
        @QtdDspLot int,
        @QtdDspPrm int,
        @QtdEmbFec int,
        @FlgPrdForLin bit,
        @PerQtp numeric(18,4),
        @PerQtpAcu numeric(18,4),
        @pm_FlgPerCmpEst bit,
        @to_CodCfoNorInt int,
		@cl_CodCliPag int,
		@cl_QtdMesMinPrzVctLot int,
        @CodMtvRej varchar(3),
        @QtdSolPrdIni int,
        @WAccQtdTot int,
        @WQtdPra int,
        @WQtdDep int
        
-- sem WMS: deposito unico
Set @CodDep = IsNull((Select min(Cod_Dep) 
                        From TBDEP 
                       Where Cod_Estabe = @PCodEstabe),1)

-- coloca campos de tabela na memoria
Select @pm_FlgPerCmpEst = Isnull(FlgPerCmpEst,0)
  From PARAM
 Where Cod_Estabe = @PCodEstabe
  
Select @to_CodCfoNorInt = t.Cod_CfoNorInt
  From TPOPE t 
       Inner Join PDVCB p on (t.Cod_Ope = p.Tip_Faturamento)
 Where p.Cod_Estabe = @PCodEstabe
   And p.Numero = @PCodPed

Select @cl_CodClipag = IsNull(cl.Cod_CliPag,0),
       @cl_QtdMesMinPrzVctLot = IsNull(Qtd_MesMinPrzVctLot,0)
 From PDVCB cb
      Left Outer Join CLIEN cl on (cb.Cod_Cliente = cl.Codigo)
 Where cb.Cod_Estabe = @PCodEstabe
   And cb.Numero = @PCodPed

-- variaveis para salvar valores iniciais do pedido para serem usados qdo incluir uma nova linha (lote)
Declare @it_LocFis varchar(15), 
        @it_CodFab int, 
        @it_PerDsc numeric(18,4), 
        @it_PrcUni numeric(18,8), 
        @it_PrcTab numeric(18,4), 
        @it_PrcTabBru numeric(18,4), 
        @it_FlgPrcUniDsc bit, 
        @it_PrzMax int, 
        @it_DscPrz numeric(18,4), 
        @it_DscVis numeric(18,4),
        @it_QtdSol int,
        @it_PrcMaxCon numeric(18,4), 
        @it_PrcFab numeric(18,4), 
        @it_NumSeqDig int,
        @it_NomUsuDbq varchar(15),
        @it_DesUnvImpFat char(3),
        @it_DesAprImpFat varchar(12),
        @it_IdPolCom int,
        @it_FlgVerba bit, 
        @it_PrcPolCom numeric(18,8), 
        @it_PerDscPolCom numeric(18,4), 
        @it_PerDscVisPolCom numeric(18,4),
        @it_QtdPrzPolCom int,
        @it_FlgPolPrm bit,
        @it_PrcUniLiqPer numeric(18,4),
        @it_PrcLiqUltEnt numeric(18,4),
        @it_PrcRefFpb numeric(18,4),
        @it_PrcUniPde numeric(18,4), 
        @it_PerDscPde numeric(18,4), 
        @it_CodPrjPde varchar(12),
        @it_NumSeqPdc varchar(6),
        @it_PerVrbPar numeric(18,4), 
        @it_PerVrbBon numeric(18,4), 
        @it_VlrBonificacao numeric(18,4),
        @it_VlrDscBonRat numeric(18,4),
        @it_PrcCusMinComMarkup numeric(18,4),
        @it_VlrBasVerba numeric(18,4),
        @IdPolLot int   -- politica com lote especifico

Select @it_LocFis = it.Loc_Fisica,
       @it_CodFab = it.Cod_Fabricante,
       @it_QtdSol = IsNull(it.Qtd_Solicitado,0),
       @it_PerDsc = it.Per_Desconto,
       @it_PrcUni = it.Prc_Unitario,
       @it_PrcTab = it.Prc_Tabela,
       @it_PrcTabBru = it.Prc_TabBru,
       @it_FlgPrcUniDsc = it.Flg_PrcUniDsc,
       @it_PrzMax = it.Qtd_PrzMax,
       @it_DscPrz = it.Per_Descon,
       @it_DscVis = it.Per_DscVis,
       @it_PrcMaxCon = it.Prc_MaxCon,
       @it_PrcFab = it.Prc_Fabric,
       @it_NumSeqDig = it.Num_SeqDig,
       @it_NomUsuDbq = it.Nom_UsuDesbloq,
       @it_DesUnvImpFat = it.Des_UnvImpFat,
       @it_DesAprImpFat = it.Des_AprImpFat,
       @it_IdPolCom = it.Id_PolCom,
       @IdPolLot = Case
                     When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = it.Cod_Estabe and pl.Id_PolCom = it.Id_PolCom and pl.Cod_Produt = it.Cod_Produto) then it.Id_PolCom
                     Else 0
                   End,
       @it_FlgVerba = IsNull(it.Flg_Verba,0), 
       @it_PrcPolCom = it.Prc_PolCom, 
       @it_PerDscPolCom = it.Per_DscPolCom, 
       @it_PerDscVisPolCom = it.Per_DscVisPolCom,
       @it_QtdPrzPolCom = it.Qtd_PrzPolCom,
       @it_FlgPolPrm = ISNULL(it.Flg_PolPrm,0),
       @it_PrcUniLiqPer = it.Prc_UniLiqPer,
       @it_PrcLiqUltEnt = it.Prc_LiqUltEnt,
       @it_PrcRefFpb = it.Prc_RefFpb,
       @it_CodPrjPde = it.Cod_PrjPde,
       @it_PerDscPde = it.Per_DscPde,
       @it_PrcUniPde = it.Prc_UniPde,
       @it_NumSeqPdc = it.Num_SeqPdc,
       @it_PerVrbPar = IsNull(it.Per_VrbPar,0), 
       @it_PerVrbBon = IsNull(it.Per_VrbBon,0), 
       @it_VlrBonificacao = ISNULL(it.Vlr_Bonificacao,0),
       @it_VlrDscBonRat = ISNULL(it.Vlr_DscBonRat,0),
       @it_PrcCusMinComMarkup = ISNULL(it.Prc_CusMinComMarkup,0),
       @it_VlrBasVerba = ISNULL(it.Vlr_BasVerba,0)
  From PDVIT it
 Where it.Cod_Estabe = @PCodEstabe 
   And it.Cod_Pedido = @PCodPed 
   And it.Cod_Produto = @PCodPrd 
   And it.Cod_Lote = @PCodLot
   And it.Tip_Sai = @PTipSai

if @it_QtdSol = 0
  Set @it_QtdSol = @PQtdPed + @PQtdBon

-- exclui o regitro de origem
Delete From PDVIT
 Where Cod_Estabe = @PCodEstabe 
   And Cod_Pedido = @PCodPed 
   And Cod_Produto = @PCodPrd 
   And Cod_Lote = @PCodLot
   And Tip_Sai = @PTipSai

Set @AccQtdAte = 0
Set @AccBonAte = 0

Set @QtdDspLot = (Select sum(IsNull(Qtd_Saldo,0)) From PRLOT Where Cod_Estabe = @PCodEstabe And Qtd_Saldo > 0 And Cod_Produt = @PCodPrd)

Select @FlgPrdForLin = Case 
                         When Flag_ImprClassif1 = 'N' then 1 
                         Else 0 
                       End, 
       @QtdEmbFec = IsNull(Qtd_Embalagem,1)
  From PRODU 
 Where Codigo = @PCodPrd

if @QtdEmbFec = 0
  Set @QtdEmbFec = 1

Select @QtdDspPrd = dbo.FN_EstoqueDisponivelPrd(Cod_Estabe,Cod_Produt),
       @QtdSolPrdIni = ISNULL(Qtd_Solici,0),
       @QtdDspPrm = IsNull(Qtd_PrmDispon,0)
  From PRXES 
 Where Cod_Estabe = @PCodEstabe 
   And Cod_Produt = @PCodPrd

if IsNull(@QtdDspLot,0) < IsNull(@QtdDspPrd,0)
  Set @QtdDsp = IsNull(@QtdDspLot,0)
else
  Set @QtdDsp = IsNull(@QtdDspPrd,0)
  
-- verifica estoque disponivel para promocao
if (@PCodPrm > 0) and 
   (Charindex((Select Substring(Cod_OrigemPdv,1,1) From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PCodPed),';M;T;W;') > 0) 
  if IsNull((Select Flg_BlqCtrQtdPrm From PRMCB Where Codigo = @PCodPrm),0) = 0
    begin
      if @QtdDspPrm < 0 
        Set @QtdDspPrm = 0 
      if @QtdDspPrm < @QtdDsp
        Set @QtdDsp = @QtdDspPrm
    end
  
Set @CodLotPri = ''     -- primeiro lote solicitado
Set @CodMtvRej = ''

Set @QtdLotDsp = dbo.FN_QtdLoteDisponivel (@PCodEstabe, @cl_CodCliPag, @PCodPrd, @Date, @cl_QtdMesMinPrzVctLot, @IdPolLot)

-- verifica se existe lote para atendimento
if (@QtdDsp > 0) and (@QtdLotDsp = 0)
  begin
    Set @QtdDsp = 0
    Set @CodMtvRej = 'LT-'
  end

if @QtdLotDsp < @QtdDsp 
  Set @QtdDsp = @QtdLotDsp

if ((@QtdDsp/@PFatCnvImpFat)*@PFatCnvImpFat) > 0
  begin
    -- acumulador total de solicitacoes do produto
    Set @WAccQtdTot = 0

    if @PQtdPed+@PQtdBon > 0 
      Set @PerQtp = @PQtdPed*100/(@PQtdPed+@PQtdBon)
    else
      Set @PerQtp = 0

    -- ajusta quantidades conforme estoque disponivel
    Set @QtdPedAju = @PQtdPed
    Set @QtdBonAju = @PQtdBon
    if @QtdDsp < (@PQtdPed+@PQtdBon)
      begin
        if @PQtdBon > 0
          begin
            Set @FatBon = @PQtdBon*1.0/@PQtdPed*1.0
            Set @QtdBonAju = @FatBon*@QtdDsp/(1+@FatBon) + 0.05
            Set @QtdPedAju = @QtdBonAju/@FatBon
			if (@QtdPedAju+@QtdBonAju) > @QtdDsp
              Set @QtdPedAju = @QtdDsp-@QtdBonAju
          end
        else
          Set @QtdPedAju = @QtdDsp
      end

    -- inclui novo(s) registro(s) conforme disponibilidade dos lotes
    -- solicita lote especifico ou pelo vencimento
	if @PFlgLotEsp = 1
	  Set @CodLotEsp = @PCodLot
	else
	  Set @CodLotEsp = ''

    -- solicita lote por vencimento
    if @to_CodCfoNorInt > 0
      begin
        -- venda FAT
		if @pm_FlgPerCmpEst = 0  
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For
              Select '1' as CodLocEst, lt.Dat_Vencim, lt.Cod_Lote, 
                     SldLot = Case 
                                When @PFlgLotNaoFra = 1 Then lt.Qtd_SldPra/@QtdEmbFec*@QtdEmbFec
                                Else lt.Qtd_SldPra 
                              End  
                From PRLOT lt Inner Join
                     PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where lt.Cod_Estabe = @PCodEstabe
                 And lt.Cod_Dep = @CodDep
                 And lt.Cod_Produt = @PCodPrd 
                 And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                       ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
                 And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                             (lt.Dat_Vencim >= Case
                                                                 When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                 When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                 Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                               End))) or
                       ((@IdPolLot > 0) and 
                        Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                 And lt.Qtd_Saldo > 0 
                 And lt.Qtd_SldPra > 0
               Order by CodLocEst, lt.Dat_Vencim
          end
        else
          begin
            -- compartilha estoque
            Declare PRLOT_Cr Cursor Local Fast_Forward For 
              Select lt.CodLocEst, lt.Dat_Vencim, lt.Cod_Lote, lt.SldLot
                From ( Select '1' as CodLocEst, l1.Cod_Estabe, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote,
                              SldLot = Case 
                                         When @PFlgLotNaoFra = 1 Then l1.Qtd_SldPra/@QtdEmbFec*@QtdEmbFec
                                         Else l1.Qtd_SldPra 
                                       End  
                         From PRLOT l1 
                        Where l1.Cod_Estabe = @PCodEstabe
                          And l1.Cod_Dep = @CodDep
                          And l1.Cod_Produt = @PCodPrd 
                          And l1.Qtd_Saldo > 0 
                          And l1.Qtd_SldPra > 0
                       Union
                       Select '2' as CodLocEst, l2.Cod_Estabe, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                              SldLot = Case 
                                         When @PFlgLotNaoFra = 1 Then l2.Qtd_SldDep/@QtdEmbFec*@QtdEmbFec
                                         Else l2.Qtd_SldDep 
                                       End  
                         From PRLOT l2 
                        Where l2.Cod_Estabe = @PCodEstabe
                          And l2.Cod_Dep = @CodDep
                          And l2.Cod_Produt = @PCodPrd 
                          And l2.Qtd_Saldo > 0 
                          And l2.Qtd_SldDep > 0 ) lt Inner Join
                     PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where 1 = 1
                 And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                       ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
                 And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                             (lt.Dat_Vencim >= Case
                                                                 When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                 When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                 Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                               End))) or
                       ((@IdPolLot > 0) and 
                        Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
               Order by lt.CodLocEst, lt.Dat_Vencim
          end
      end
    else
      begin
        -- venda ORC
        if @pm_FlgPerCmpEst = 0
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For
              Select '2' as CodLocEst, lt.Dat_Vencim, lt.Cod_Lote,
                     SldLot = Case 
                                When @PFlgLotNaoFra = 1 Then Qtd_SldDep/@QtdEmbFec*@QtdEmbFec
                                Else lt.Qtd_SldDep 
                              End  
                From PRLOT lt Inner Join
                     PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where lt.Cod_Estabe = @PCodEstabe
                 And lt.Cod_Dep = @CodDep
                 And lt.Cod_Produt = @PCodPrd 
                 And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                       ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
                 And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                             (lt.Dat_Vencim >= Case
                                                                 When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                 When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                 Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                               End))) or
                       ((@IdPolLot > 0) and 
                        Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                 And lt.Qtd_Saldo > 0 
                 And lt.Qtd_SldDep > 0
               Order by CodLocEst, lt.Dat_Vencim
          end
        else
          begin
            -- compartilha estoque
            Declare PRLOT_Cr Cursor Local Fast_Forward For
              Select lt.CodLocEst, lt.Dat_Vencim, lt.Cod_Lote, lt.SldLot
                From ( Select '2' as CodLocEst, l2.Cod_Estabe, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote,
                              SldLot = Case 
                                         When @PFlgLotNaoFra = 1 Then l2.Qtd_SldDep/@QtdEmbFec*@QtdEmbFec
                                         Else l2.Qtd_SldDep 
                                       End  
                         From PRLOT l2
                        Where l2.Cod_Estabe = @PCodEstabe
                          And l2.Cod_Dep = @CodDep
                          And l2.Cod_Produt = @PCodPrd 
                          And l2.Qtd_Saldo > 0 
                          And l2.Qtd_SldDep > 0
                       Union
                       Select '1' as CodLocEst, l1.Cod_Estabe, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote,
                              SldLot = Case 
                                         When @PFlgLotNaoFra = 1 Then l1.Qtd_SldPra/@QtdEmbFec*@QtdEmbFec
                                         Else l1.Qtd_SldPra 
                                       End  
                         From PRLOT l1 
                        Where l1.Cod_Estabe = @PCodEstabe
                          And l1.Cod_Dep = @CodDep
                          And l1.Cod_Produt = @PCodPrd 
                          And l1.Qtd_Saldo > 0 
                          And l1.Qtd_SldPra > 0 ) lt Inner Join
                     PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where 1 = 1
                 And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                       ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
                 And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                             (lt.Dat_Vencim >= Case
                                                                 When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                 When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                 Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                               End))) or
                       ((@IdPolLot > 0) and 
                        Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
               Order by lt.CodLocEst desc, lt.Dat_Vencim
          end
      end

    Open PRLOT_Cr
    Fetch Next From PRLOT_Cr Into @lt_LocEst, @lt_DatVct, @lt_CodLot, @lt_SldLot 

    While @@FETCH_STATUS = 0
	  begin
        -- ajusta saldo do lote : proporcional a fator de conversão DMD-7954: 30/03/2023
        Set @lt_SldLot = (@lt_SldLot/@PFatCnvImpFat) * @PFatCnvImpFat

        While (@AccQtdAte+@AccBonAte < @QtdPedAju+@QtdBonAju) and 
              (@lt_SldLot > 0) and (@@FETCH_STATUS = 0)
          begin
            Set @PedSol = @QtdPedAju - @AccQtdAte
            Set @BonSol = @QtdBonAju - @AccBonAte
      
            -- se o saldo do lote nao atender a qtd.solicitada refazer a solicitacao proporcionalmente
            if @PedSol+@BonSol > @lt_SldLot
              begin
                Set @PedSol = Round(@lt_SldLot*@PerQtp/100,0)
                Set @BonSol = @lt_SldLot-@PedSol
              end
      
            -- garante as quantidades solicitadas
            if (@PedSol = 0) or ((@AccQtdAte+@PedSol) > @QtdPedAju) or ((@AccBonAte+@BonSol) > @QtdBonAju)
              Break
      
            -- Atualiza saldo do lote
            Set @WQtdPra = 0
            Set @WQtdDep = 0
            
            if @CodLotPri = ''
              Set @CodLotPri = @lt_CodLot

            if @lt_LocEst = '1'
              begin
                Update PRLOT
                   Set Qtd_SolPra = Qtd_SolPra + @PedSol + @BonSol
                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Dep = @CodDep
                   And Cod_Produt = @PCodPrd
                   And Cod_Lote = @lt_CodLot
      
                Set @WQtdPra = @PedSol + @BonSol
                Set @WAccQtdTot = @WAccQtdTot + @WQtdPra
              end
            else
              begin
                Update PRLOT
                   Set Qtd_SolDep = Qtd_SolDep + @PedSol + @BonSol
                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Dep = @CodDep
                   And Cod_Produt = @PCodPrd
                   And Cod_Lote = @lt_CodLot
      
                Set @WQtdDep = @PedSol + @BonSol
                Set @WAccQtdTot = @WAccQtdTot + @WQtdDep
              end
           
            -- incrementa saldo solicitado em PRXES
            Update PRXES 
               Set Qtd_Solici = Qtd_Solici + @PedSol + @BonSol,
                   Qtd_PrmSolici = Case 
                                     When IsNull(@PCodPrm,0) > 0 then Qtd_PrmSolici + @PedSol + @BonSol
                                     Else Qtd_PrmSolici 
                                   End
             Where Cod_Estabe = @PCodEstabe
               And Cod_Produt = @PCodPrd
          
            Set @AccQtdAte = @AccQtdAte + @PedSol
            Set @AccBonAte = @AccBonAte + @BonSol
      
            -- atualiza qtd atendida e o lote ativo
            if Exists(Select Cod_Produto From PDVIT 
                       Where Cod_Estabe = @PCodEstabe
                         And Cod_Pedido = @PCodPed 
                         and Cod_Produto = @PCodPrd 
                         and Cod_Lote = @lt_CodLot
                         and Tip_Sai = @PTipSai)
              begin
                Update PDVIT
                   Set Qtd_Pedido = Qtd_Pedido + @PedSol,
                       Qtd_Bonificacao = Qtd_Bonificacao + @BonSol,
                       Qtd_Solicitado = Qtd_Solicitado + @PedSol + @BonSol,
                       Qtd_Pra = Qtd_Pra + @WQtdPra,
                       Qtd_Dep = Qtd_Dep + @WQtdDep   
                 Where Cod_Estabe = @PCodEstabe
                   and Cod_Pedido = @PCodPed 
                   and Cod_Produto = @PCodPrd 
                   and Cod_Lote = @lt_CodLot
                   and Tip_Sai = @PTipSai
              end
            else
              begin
                Insert into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai, 
      		                   Qtd_Pedido, Qtd_Bonificacao, Prc_Unitario, Per_Desconto, Per_Descon, Per_DscVis)  
                           Values (@PCodEstabe, @PCodPed, @PCodPrd, @lt_CodLot, @PTipSai, 
      				           @PedSol, @BonSol, @it_PrcUni, @it_PerDsc, @it_DscPrz, @it_DscVis)
                if @@error <> 0
                    begin
                      Rollback Transaction
                      Return
                    end
      
                Update PDVIT
                   Set Fat_CnvImpFat = @PFatCnvImpFat,
                       Qtd_PrzMax = @it_PrzMax, 
                       Loc_Fisica = @it_LocFis, 
                       Cod_Fabricante = @it_CodFab,
                       Cod_Promocao = @PCodPrm, 
                       Cod_KitPrm = @PCodKitPrm, 
                       Qtd_Solicitado = @PedSol+@BonSol, 
                       Flg_PrcUniDsc = @it_FlgPrcUniDsc, 
                       Prc_Tabela = @it_PrcTab,  
                       Prc_TabBru = @it_PrcTabBru, 
                       Qtd_Pra = @WQtdPra, 
                       Qtd_Dep = @WQtdDep, 
                       Prc_MaxCon = @it_PrcMaxCon,
                       Prc_Fabric = @it_PrcFab,  
                       Num_SeqDig = @it_NumSeqDig,  
                       Nom_UsuDesbloq = @it_NomUsuDbq,  
                       Des_UnvImpFat = @it_DesUnvImpFat, 
                       Des_AprImpFat = @it_DesAprImpFat,
                       Id_PolCom = @it_IdPolCom, 
                       Flg_Verba = @it_FlgVerba, 
                       Prc_PolCom = @it_PrcPolCom,  
                       Per_DscPolCom = @it_PerDscPolCom, 
                       Per_DscVisPolCom = @it_PerDscVisPolCom,
                       Qtd_PrzPolCom = @it_QtdPrzPolCom, 
                       Flg_PolPrm = @it_FlgPolPrm,
                       Prc_UniLiqPer = @it_PrcUniLiqPer, 
                       Prc_LiqUltEnt = @it_PrcLiqUltEnt,
                       Prc_RefFpb = @it_PrcRefFpb,
                       Cod_PrjPde = @it_CodPrjPde,
                       Prc_UniPde = @it_PrcUniPde, 
                       Per_DscPde = @it_PerDscPde,
                       Num_SeqPdc = @it_NumSeqPdc,
                       Per_VrbPar = @it_PerVrbPar,
                       Per_VrbBon = @it_PerVrbBon,
                       Vlr_Bonificacao = @it_VlrBonificacao, 
                       Vlr_DscBonRat = @it_VlrDscBonRat, 
                       Prc_CusMinComMarkup = @it_PrcCusMinComMarkup,
                       Vlr_BasVerba = @it_VlrBasVerba
                 Where Cod_Estabe = @PCodEstabe
                   and Cod_Pedido = @PCodPed 
                   and Cod_Produto = @PCodPrd 
                   and Cod_Lote = @lt_CodLot
                   and Tip_Sai = @PTipSai
              end
      
            -- decrementa quantidade solicitada inicial
            Set @it_QtdSol = @it_QtdSol - @PedSol - @BonSol
      
            -- calcula tributos      
            EXEC PR_CalcTributPdvit @PCodEstabe, @PCodPed, @PCodPrd, @lt_CodLot, @PTipSai
            if @@error <> 0
              begin
                Rollback Transaction
                Return
              end
      
            Fetch Next From PRLOT_Cr Into @lt_LocEst, @lt_DatVct, @lt_CodLot, @lt_SldLot 
          end  -- While (@AccQtdAte+@AccBonAte < @QtdPedAju+@QtdBonAju)

        Fetch Next From PRLOT_Cr Into @lt_LocEst, @lt_DatVct, @lt_CodLot, @lt_SldLot
      end  -- While @@FETCH_STATUS 

    Close PRLOT_Cr
    Deallocate PRLOT_Cr

    -- verifica bonificacao
    if @PQtdBon > 0
      begin
        if @AccQtdAte + @AccBonAte > 0 
          Set @PerQtpAcu = @AccQtdAte*100/(@AccQtdAte+@AccBonAte)
        else
          Set @PerQtpAcu = 0
        if Round(@PerQtpAcu*100,0) <> Round(@PerQtp*100,0)
          begin
            Set @AccQtdAte = 0
            Set @AccBonAte = 0
--            Rollback Transaction A 
            Rollback Transaction 
            Return
          end
      end

/*    
    -- incrementa saldo solicitado
    Update PRXES 
      Set Qtd_Solici = Qtd_Solici + @AccQtdAte + @AccBonAte
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd
      
    Update PRXES
      Set Qtd_PrmSolici = Qtd_PrmSolici + @AccQtdAte + @AccBonAte
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd 
    And IsNull(@PCodPrm,0) > 0
*/
  end

-- registra faltas em @CodLotPri: primeiro lote solicitado
if @CodLotPri = ''
  Set @CodLotPri = '*'

if @AccQtdAte+@AccBonAte < @PQtdPed+@PQtdBon
  begin
    if @CodMtvRej = ''
      if @QtdDsp > 0
        Set @CodMtvRej = 'ES-'   -- estoque insuficiente
      else
      if @FlgPrdForLin = 1
        Set @CodMtvRej = 'PR-'   -- produto descontinuado
      else
        Set @CodMtvRej = 'ES0'   -- estoque zero
    
    if Exists(Select Cod_Produto From PDVIT 
               Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PCodPed 
                 and Cod_Produto = @PCodPrd and Cod_Lote = @CodLotPri and Tip_Sai = @PTipSai)
      begin
        Update PDVIT
           Set Qtd_Solicitado = Qtd_Solicitado + @PQtdPed + @PQtdBon - @AccQtdAte - @AccBonAte,
               Cod_MtvRej = @CodMtvRej
         Where Cod_Estabe = @PCodEstabe
           and Cod_Pedido = @PCodPed 
           and Cod_Produto = @PCodPrd 
           and Cod_Lote = @CodLotPri
           and Tip_Sai = @PTipSai
      end
    else
      begin
        Insert into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai, 
                           Qtd_Pedido, Qtd_Bonificacao, Prc_Unitario, Per_Desconto, Per_Descon, Per_DscVis)
                   Values (@PCodEstabe, @PCodPed, @PCodPrd, @CodLotPri, @PTipSai, 
				           0, 0, @it_PrcUni, @it_PerDsc, @it_DscPrz, @it_DscVis)
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end

        Update PDVIT
           Set Fat_CnvImpFat = @PFatCnvImpFat,
               Qtd_PrzMax = @it_PrzMax,
               Loc_Fisica = @it_LocFis,
               Cod_Fabricante = @it_CodFab,
               Cod_Promocao = @PCodPrm,
               Cod_KitPrm =  @PCodKitPrm,  
               Qtd_Solicitado = @PQtdPed+@PQtdBon-@AccQtdAte-@AccBonAte,
               Flg_PrcUniDsc = @it_FlgPrcUniDsc,
               Prc_Tabela =  @it_PrcTab,
               Prc_TabBru = @it_PrcTabBru, 
               Qtd_Pra = 0,
               Qtd_Dep = 0,
               Prc_MaxCon = @it_PrcMaxCon,
               Prc_Fabric = @it_PrcFab,
               Num_SeqDig = @it_NumSeqDig,
               Nom_UsuDesbloq = @it_NomUsuDbq,
               Des_UnvImpFat = @it_DesUnvImpFat,
               Des_AprImpFat = @it_DesAprImpFat,
               Id_PolCom = @it_IdPolCom,
               Flg_Verba = @it_FlgVerba, 
               Prc_PolCom = @it_PrcPolCom,
               Per_DscPolCom = @it_PerDscPolCom,
               Per_DscVisPolCom = @it_PerDscVisPolCom,
               Cod_MtvRej = @CodMtvRej, 
               Qtd_PrzPolCom = @it_QtdPrzPolCom,
               Flg_PolPrm = @it_FlgPolPrm, 
               Prc_UniLiqPer = @it_PrcUniLiqPer,
               Prc_LiqUltEnt = @it_PrcLiqUltEnt,
               Prc_RefFpb = @it_PrcRefFpb,
               Cod_PrjPde = @it_CodPrjPde,
               Prc_UniPde = @it_PrcUniPde,
               Per_DscPde = @it_PerDscPde,
               Num_SeqPdc = @it_NumSeqPdc,
               Per_VrbPar = @it_PerVrbPar,
               Per_VrbBon = @it_PerVrbBon, 
               Vlr_Bonificacao = @it_VlrBonificacao,
               Vlr_DscBonRat = @it_VlrDscBonRat,
               Prc_CusMinComMarkup = @it_PrcCusMinComMarkup,
               Vlr_BasVerba = @it_VlrBasVerba
         Where Cod_Estabe = @PCodEstabe
           and Cod_Pedido = @PCodPed 
           and Cod_Produto = @PCodPrd 
           and Cod_Lote = @CodLotPri
           and Tip_Sai = @PTipSai
      end

    -- decrementa quantidade solicitada inicial
    Set @it_QtdSol = @it_QtdSol - @PQtdPed - @PQtdBon + @AccQtdAte + @AccBonAte

    -- calcula tributos      
    EXEC PR_CalcTributPdvit @PCodEstabe, @PCodPed, @PCodPrd, @CodLotPri, Tip_Sai
    if @@error <> 0
      begin
        Rollback Transaction
        Return
      end

  end  -- if ((@QtdDsp/@PFatCnvImpFat)*@PFatCnvImpFat) > 0

-- ajusta quantidade solicitada
if @it_QtdSol < 0
  Set @it_QtdSol = 0
if @it_QtdSol > 0 
  begin
    Update PDVIT
       Set Qtd_Solicitado = Qtd_Solicitado + @it_QtdSol
     Where Cod_Estabe = @PCodEstabe
       and Cod_Pedido = @PCodPed 
       And Cod_Produto = @PCodPrd 
       And Cod_Lote = @CodLotPri
       And Tip_Sai = @PTipSai
  end  

if (@QtdSolPrdIni + @WAccQtdTot) <>
   IsNull((Select IsNull(Qtd_Solici,0) From PRXES Where Cod_Estabe = @PCodEstabe And Cod_Produt = @PCodPrd),0) 
  begin
    RAISERROR('Erro na solicitação do Produto',16,1)
    Rollback Transaction
	Return
  end 

-- corrige quantidades solicitades de lotes não multiplos de fator de conversão do item
Exec dbo.PR_CorrigeQtdLoteProduto @PCodEstabe, @PCodPed, @PCodPrd
if @@error <> 0
  begin
    Rollback Transaction
    Return
  end
else
  Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_SolicitaLotesPDV]
@CodEstabe int,
@CodPed int,       -- num. do pedido
@QtdMesVctMin int,  -- qtd meses vencimento minimo de lotes DESCARTAR  
@FlgErr bit output

AS

SET NOCOUNT ON 

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Declare @StrMsg varchar(400)

Set @FlgErr = 0
Set @StrMsg = ''

if Exists(Select 1
           From PDVCB
          Where Cod_Estabe = @CodEstabe
            And Numero = @CodPed
            And IsNull(Sta_SepLot,'') <> '')
  begin
    Set @FlgErr = 1
    Return
  end

Set @StrMsg = IsNull((Select MsgErr = Case
                                        When CharIndex(Status2,';N;D;') > 0 then 'Pedido já faturado'
                                        When (Status1 <> 'P') or (Status2 <> 'F') then 'Pedido não está pendente/fechado'
                                        When IsNull(Bloqueio,'') <> '' then 'Pedido está bloqueado'
                                        When IsNull(Flg_Wms,0) = 0 then 'Pedido não permite solicitar lotes'
                                        Else ''
                                      End
                        From PDVCB
                       Where Cod_Estabe = @CodEstabe
                         And Numero = @CodPed),'')
if @StrMsg <> ''
  Set @FlgErr = 1

/*
-- retirar esta critica quando o sistema permitir solicitação de lote específico parcial
if (@FlgErr = 0) and
   Exists(Select 1 From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed)
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Pedido já solicitou lotes'
  end
*/

-- verifica se existe quantidades em PDVLT inválidas
if (@FlgErr = 0) and
   Exists(Select lt.Cod_Produt, lt.QtdLot, it.QtdIte 
             From (Select Cod_Produt, QtdLot = SUM(IsNull(Qtd_Lote,0)) 
                     From PDVLT 
                   Where Cod_Estabe = @CodEstabe
                     And Cod_Pedido = @CodPed
                     And IsNull(Qtd_Lote,0) > 0 
                   Group by Cod_Produt) lt 
                 Inner Join (Select Cod_Produto, QtdIte = SUM(IsNull(Qtd_Pedido,0)+Isnull(Qtd_Bonificacao,0)) 
                               From PDVIT 
                              Where Cod_Estabe = @CodEstabe
                                And Cod_Pedido = @CodPed
                                And (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0 
                              Group by Cod_Produto) it on it.Cod_Produto = lt.Cod_Produt 

           Where IsNull(lt.QtdLot,0) > IsNull(it.QtdIte,0))
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Existem itens em PDVLT com quantidades superiores de PDVIT '
  end

if (@FlgErr = 0) and
   Exists(Select Cod_Produto, Tip_Sai, count(*) From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed Group By Cod_Produto, Tip_Sai Having count(*) > 1)
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Existem produtos com mais de um lote'
  end

if (@FlgErr = 0) and
   Exists(Select z1.Cod_Zon, z2.Cod_Zon 
            From TBZON z1, TBZON z2
           Where z1.Cod_Estabe = z2.Cod_Estabe
             And z1.Cod_Dep = z2.Cod_Dep
             And z1.Cod_Estabe = @CodEstabe
             And z1.Cod_Zon > 0
             And z1.Cod_Zon <> z2.Cod_Zon 
             And ((z1.Num_RuaIni between z2.Num_RuaIni and z2.Num_RuaFim) or
                  (z1.Num_RuaFim between z2.Num_RuaIni and z2.Num_RuaFim)))
  begin
    Set @FlgErr = 1
    Select top 1 
           @StrMsg = 'Endereços conflitantes entre as Zonas '+CAST(z1.Cod_Zon as varchar)+' e '+CAST(z2.Cod_Zon as varchar)
      From TBZON z1, TBZON z2
     Where z1.Cod_Estabe = z2.Cod_Estabe
       And z1.Cod_Dep = z2.Cod_Dep
       And z1.Cod_Estabe = @CodEstabe
       And z1.Cod_Zon > 0
       And z1.Cod_Zon <> z2.Cod_Zon 
       And ((z1.Num_RuaIni between z2.Num_RuaIni and z2.Num_RuaFim) or
            (z1.Num_RuaFim between z2.Num_RuaIni and z2.Num_RuaFim))    
  end

-- critica cadastros, inconsistencias, embalagem padrao, apresentacao padrao, etc...
if @FlgErr = 0
  Exec PR_CriticaCadastrosVolumesWMS @CodEstabe, @CodPed, @FlgErr output, @StrMsg output

-- verifica reabastecimento do picking
if @FlgErr = 0
  Exec PR_VerificaAbastecimentoPedido @CodEstabe, @CodPed, @StrMsg output, @FlgErr output  


if @FlgErr = 1
  begin
    RAISERROR(@StrMsg,16,1)
    Return
  end
else
BEGIN
  Begin Transaction

--    Declare @DesLoc varchar(80) = '(ANTES) PR_SolicitaLotesPDV pedido: '+cast(@CodPed as varchar)
--    Exec PR_Verifica_Divergencia_PRXESxPRLOT_PRLTL @DesLoc, @CodEstabe, 0

    Declare @CodPrd int,
            @TipSai varchar(1),
            @IdPolLot int,
            @QtdPdv int,
            @QtdLot int,
            @QtdSld int,
			@FatCnvImpFat int,
            @QtdMov int,
            @FlgMov bit = 0,
            @CodLotTip varchar(20),
            @QtdTotTip int,
            @QtdPraTip int,
            @QtdDepTip int,
            @QtdFra int,
            @QtdEmbFec int,
            @QtdEmbFecCal int,
            @QtdCxaFec int,
            @QtdUndLot int,
            @QtdSldFiscal int,
            @QtdSolPulmao int,
            @cl_CodCliPag int,
            @cl_CodGrpCli int,
            @cl_QtdMesMinPrzVctLot int,
            @cl_FlgBlqLotVarPdv bit,
            @StrPrd varchar(100),
            @FlgIntWms bit = 0,
            @BlqEstFisNeg bit = 0,
            @FlgUndMin bit = 0,
            @StaIntWms varchar(1),
            @FlgTipVenFat bit = 0,
            @FlgPodeFechar bit = 0,
		    @Usuario varchar(15)

    Set @Usuario = dbo.FN_UsuarioInfarma()

    Select @FlgIntWms = IsNull(FlgIntegrWmsExt,0),
           @BlqEstFisNeg = IsNull(BlqEstFisNeg,0)   -- nao permite negativar estoque fiscal
      From PMEST 
     Where Cod_Estabe = @CodEstabe

    Select @FlgUndMin = IsNull(FlgAltUnvItePdv,0) 
      From PARAM 
     Where Cod_Estabe = @CodEstabe

    Select @StaIntWms = IsNull(cb.Sta_IntWms,''),
           @FlgTipVenFat = Case When ISNull(op.Cod_CfoNorInt,0) > 0 then 1 ELse 0 End
      From PDVCB cb
           Left Join TPOPE op on cb.Tip_Faturamento = op.Cod_Ope 
     Where cb.Cod_Estabe = @CodEstabe and cb.Numero = @CodPed

    Set @FlgPodeFechar = 0
    if @FlgIntWms = 0
      begin
        -- atualiza status PDVCB: 'X"- em processamento
        Update PDVCB
           Set Sta_SepLot = 'X'
         Where Cod_Estabe = @CodEstabe
           And Numero = @CodPed
           And IsNull(Sta_SepLot,'') = ''

        if Exists(Select 1
                    From PDVCB
                   Where Cod_Estabe = @CodEstabe
                     And Numero = @CodPed
                     And IsNull(Sta_SepLot,'') = 'X')
          Set @FlgPodeFechar = 1
      end
    else
      begin
        if @StaIntWms = ''
          Exec PR_WMSGerarXMLSaida @CodEstabe, @CodPed

        Update PDVCB
           Set Sta_IntWMS = '0'
         Where Cod_Estabe = @CodEstabe 
           And Numero = @CodPed
           And IsNull(Sta_IntWMS,'') = ''
      end


    Set @FlgErr = 0
    Set @StrMsg = ''

    if @FlgPodeFechar = 1
      begin 

        IF OBJECT_ID('tempdb..#ARQ_PDVIT') IS NOT NULL
          DROP TABLE #ARQ_PDVIT
        
        CREATE TABLE #ARQ_PDVIT
        (
            Chave int identity,
        	Cod_Produt int,
            Id_PolLot int,
            Fat_CnvImpFat int,
            Qtd_Pdv int
        ) 

        IF OBJECT_ID('tempdb..#ARQ_PRLTL') IS NOT NULL
          DROP TABLE #ARQ_PRLTL
        
        CREATE TABLE #ARQ_PRLTL
        (
            Chave int identity,
        	Cod_Estabe smallint,
            Cod_Dep smallint,
            Num_Rua smallint, 
        	Num_Col smallint, 
        	Num_Niv smallint, 
        	Num_Apt smallint,
        	Tip_LocEnd varchar(1),
            Cod_Produt int,
        	Cod_Lote varchar(20),
            Cod_Fabricante int,
            Dat_Vencim smalldatetime,
            Dat_Entrada smalldatetime,
            Qtd_EmbFec int,
            C_QtdEmbFec int,
            Qtd_Saldo int,
            Qtd_SldPra int,
            Qtd_SldDep int
        ) 
        
        CREATE UNIQUE CLUSTERED INDEX IX_ARQ_PRLTL ON #ARQ_PRLTL (Chave);
        CREATE NONCLUSTERED INDEX IX_ARQ_PRLTL_1 ON #ARQ_PRLTL (Cod_Estabe, Cod_Produt, Dat_Vencim);


        -- popula #ARQ_PDVIT --------------------------------------------------
        Insert into #ARQ_PDVIT
          Select it.Cod_Produto, 
                 IdPolLot = Case
                              When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = it.Cod_Estabe and pl.Id_PolCom = it.Id_PolCom and pl.Cod_Produt = it.Cod_Produto) then it.Id_PolCom
                              Else 0
                            End, 
                 max(IsNull(it.Fat_CnvImpFat,1)) as FatCnvImpFat,
                 sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) as QtdPdv
            From PDVIT it 
           Where it.Cod_Estabe = @CodEstabe 
             And it.Cod_Pedido = @CodPed
             And IsNull(it.Qtd_Pedido,0) > 0
           Group by it.Cod_Estabe, it.Cod_Produto, it.Id_PolCom

        -- desconta PDVLT já solicitado ---131370
		Declare @cr_CodPrd int,
                @cr_IdPolLot int,
                @cr_QtdLot int

        -- lotes já solicitados
        Declare PDVLT_Cr Cursor Local Fast_Forward For 

          Select Cod_Produt, Id_PolCOm
               , Qtd_Lote = sum(Qtd_Lote)
            From PDVLT
           Where Cod_Estabe = @CodEstabe
             And Cod_Pedido = @CodPed
           Group by Cod_Produt, Id_PolCom
           Order by Cod_Produt, Id_PolCom Desc

        Open PDVLT_Cr  
        Fetch Next From PDVLT_Cr Into @cr_CodPrd, @cr_IdPolLot, @QtdSld
        While @@FETCH_STATUS = 0
          begin
            Set @CodPrd = @cr_CodPrd

            While (@CodPrd = @cr_CodPrd) and (@@FETCH_STATUS = 0)  
              begin

                -- desconta lote diferenciado se houver
                if Exists(Select 1 From #ARQ_PDVIT Where Cod_Produt = @CodPrd 
                             And Id_PolLot = @cr_IdPolLot 
                             And @cr_IdPolLot > 0 And Qtd_Pdv > 0)
                  begin
                    Select @cr_QtdLot = Qtd_Pdv 
                      From #ARQ_PDVIT 
                     Where Cod_Produt = @CodPrd
                       And Id_PolLot = @cr_IdPolLot
                       And Qtd_Pdv > 0

                    Set @QtdMov = Case 
                                    When @cr_QtdLot > @QtdSld then @QtdSld
                                    Else @cr_QtdLot
                                  End

                    Update #ARQ_PDVIT 
                       Set Qtd_Pdv = Qtd_Pdv - @QtdMov
                     Where Cod_Produt = @CodPrd
                       And Id_PolLot = @cr_IdPolLot
                       And @QtdMov >= Qtd_Pdv
                    if @@rowcount > 0
                      Set @QtdSld = @QtdSld - @QtdMov
                  end

                -- desconta restante
                if @QtdSld > 0
                  Set @FlgMov = 1
				   
                while (@QtdSld > 0) and (@FlgMov = 1) and
                      Exists(Select 1 From #ARQ_PDVIT Where Cod_Produt = @CodPrd And Qtd_Pdv > 0)
                  begin
                    Set @FlgMov = 0

                    Select top 1 
                           @cr_IdPolLot = Id_PolLot
                         , @cr_QtdLot = Qtd_Pdv 
                      From #ARQ_PDVIT 
                     Where Cod_Produt = @CodPrd
                       And Qtd_Pdv > 0
                     Order by Id_PolLot desc

                    Set @QtdMov = Case 
                                    When @cr_QtdLot > @QtdSld then @QtdSld
                                    Else @cr_QtdLot
                                  End

                    Update #ARQ_PDVIT 
                       Set Qtd_Pdv = Qtd_Pdv - @QtdMov
                     Where Cod_Produt = @CodPrd
                       And Id_PolLot = @cr_IdPolLot
                       And @QtdMov <= Qtd_Pdv
                    if @@rowcount > 0
                      begin
                        Set @FlgMov = 1
                        Set @QtdSld = @QtdSld - @QtdMov
                      end

                  end -- while (@QtdSld > 0) and (@FlgMov = 1) and

                Fetch Next From PDVLT_Cr Into @cr_CodPrd, @cr_IdPolLot, @QtdSld

              end  -- While (@CodPrd = @cr_CodPrd) and (@@FETCH_STATUS = 0)

            Delete From #ARQ_PDVIT 
             Where Cod_Produt = @CodPrd
               And Qtd_Pdv = 0

          end  -- While @@FETCH_STATUS = 0
          
        Close PDVLT_Cr
        Deallocate PDVLT_Cr
        -- fim popula #ARQ_PRLTL -------------------------------------------------------

        -- popula #ARQ_PRLTL descontando abastecimentos pendentes
        Insert into #ARQ_PRLTL
          Select lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt,
                 dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua),
                 lt.Cod_Produt, lt.Cod_Lote, pr.Cod_Fabricante, lt.Dat_Vencim, lt.Dat_Entrada,
                 Qtd_EmbFec  = IsNull(lt.Qtd_EmbFec,0),
                 C_QtdEmbFec = IsNull(lt.C_QtdEmbFec,0),
                 Qtd_Saldo   = IsNull(lt.Qtd_Saldo,0)  - IsNull(ab.C_QtdMov,0),
                 Qtd_SldPra  = IsNull(lt.Qtd_SldPra,0) - IsNull(ab.C_QtdMov,0),
                 Qtd_SldDep  = IsNull(lt.Qtd_SldDep,0)
            From PRLTL lt Inner Join
                 PRODU pr on lt.Cod_Produt = pr.Codigo Left Join
                 ( Select it.Cod_Produt, it.Cod_Lote, it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, it.Num_Apt,
                          C_QtdMov = sum(QTd_Mov)
                     From ABAIT it
                          Inner Join ABACB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Abaste = cb.Cod_Abaste
                    Where cb.Cod_Estabe = @CodEstabe
                      And cb.Cod_STa = 'A'
                    Group by it.Cod_Produt, it.Cod_Lote, it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, it.Num_Apt
                 ) ab on lt.Cod_Produt = ab.Cod_Produt and lt.Cod_Lote = ab.Cod_Lote and
                         lt.Cod_Dep = ab.Cod_Dep and lt.Num_Rua = ab.Num_Rua and lt.Num_Col = ab.Num_Col and lt.Num_Niv = ab.Num_Niv and lt.Num_Apt = ab.Num_Apt
           Where lt.Cod_Estabe = @CodEstabe
             And (IsNull(lt.Qtd_Saldo,0) - IsNull(ab.C_QtdMov,0)) > 0
             And IsNull(lt.Qtd_EmbFec,0) > 0

        -- normaliza #ARQ_PRLTL
        Update #ARQ_PRLTL
           Set Qtd_SldDep = Qtd_SldDep + Abs(Qtd_SldPra),
               Qtd_SldPra = 0
         Where Qtd_SldPra < 0
        
		-- TBZON
        Update TBZON
           Set Num_Esteira = 1
         Where Cod_Estabe = @CodEstabe
           And ISNULL(Num_Esteira,0) = 0

        Declare @NumVol int,
                @to_CodCfoNorInt int,
                @to_TipOpe varchar(1),
                @pm_FlgBlqCnfTrf bit, 
                @pm_CodOpeWmsDef int,
                @DatVct smalldatetime,
                @DatEnt smalldatetime,
                @CodLot varchar(20),
                @CodLotEsp varchar(20),  -- lote especifico
				@QtdLotSel int,
                @LocEst varchar(1),
                @OrdDep varchar(1),
				@FlgPrePck bit,
                @CodDep int, 
                @CodDepAnt int, 
                @NumEst smallint,
                @NumEstAnt smallint,
                @NumRua int, 
                @NumCol int, 
                @NumNiv int, 
                @NumApt int, 
                @SldLot int,
                @FatCnvAprEmbPad int,
                @QtdPraLot int,
                @QtdDepLot int,
                @QtdDif int,
                @FlgDesord bit,
                @dx_CodLocFis varchar(15),
                @pr_VolUniMin numeric(18,8),  -- @pr_VolEmb
                @cx_CodCxaPad int,
                @cx_VolCxaPad numeric(18,4),
                @cx_NewCodCxaPad int,
                @VolMaxCxa numeric(18,4),
                @VolTotIte numeric(18,4),
                @VolAcu numeric(18,4),
                @QtdAteAcu int,
                @QtdAte int,
                @Per numeric(18,8)

        Select @cl_CodCliPag = Case 
                                 When IsNull(cl.Cod_CliPag,0) > 0 then cl.Cod_CliPag
                                 Else cl.Codigo
                               End,
               @cl_QtdMesMinPrzVctLot = IsNull(cl.Qtd_MesMinPrzVctLot,0),
               @cl_CodGrpCli = cl.Cod_GrpCli,
			   @cl_FlgBlqLotVarPdv = IsNull(Flg_BlqLotVarPdv,0)
          From CLIEN cl Inner Join PDVCB cb on (cb.Cod_Cliente = cl.Codigo)
         Where cb.Cod_Estabe = @CodEstabe 
           And cb.Numero = @CodPed
          
        if @cl_CodCliPag is null Set @cl_CodCliPag = 0
        if @cl_QtdMesMinPrzVctLot is null Set @cl_QtdMesMinPrzVctLot = 0
        if @cl_CodGrpCli is null Set @cl_CodGrpCli = 0
                     
        Select @to_CodCfoNorInt = IsNull(t.Cod_CfoNorInt,0),
               @to_TipOpe = IsNull(t.Tip_Ope,'')
          From TPOPE t Inner Join PDVCB p on (t.Cod_Ope = p.Tip_Faturamento)
         Where p.Cod_Estabe = @CodEstabe 
           And p.Numero = @CodPed

        Select @pm_FlgBlqCnfTrf = IsNull(FlgBlqCnfTrf,0), 
               @pm_CodOpeWmsDef = IsNull(CodOpeWmsDef,0) 
          From PMEST
         Where Cod_Estabe = @CodEstabe  

        -- pega o último volume de caixa fechada, se já existir
        Set @NumVol = IsNull((Select max(Num_Vol)
                                From PDVLT 
                               Where Cod_Estabe = @CodEstabe 
                                 And Cod_Pedido = @CodPed
                                 And ((Cod_LocFis = 'PRLTL') And (Qtd_CxaFec > 0))),0)	

        -- negativa volumes fracionados pré-existentes
        Update PDVLT
           Set Num_Vol = -1
         Where Cod_Estabe = @CodEstabe 
           And Cod_Pedido = @CodPed
           And ((Cod_LocFis <> 'PRLTL') or (Qtd_CxaFec > 0))


        -- elimina registro de conferencia existentes
        Delete from CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed

        Delete from CPVCB Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed
          
        -- **************************************************  solicita lotes (CAIXA FECHADA) por vencimento do DEPOSITO FECHADO  ******************************************************************
        Declare PDVIT_Cr Cursor Local Fast_Forward For 

          Select Cod_Produt, Id_PolLot, Fat_CnvImpFat, Qtd_Pdv
            From #ARQ_PDVIT

        Open PDVIT_Cr  
        Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @FatCnvImpFat, @QtdPdv
        While @@FETCH_STATUS = 0  
          begin
            -- nao permite negativar estoque fiscal
            if (@BlqEstFisNeg = 1) and (@FlgTipVenFat = 1)
              begin
                Set @QtdSldFiscal = dbo.FN_SldFiscalDisponPrd(@CodEstabe,@CodPrd)
                if @QtdPdv > @QtdSldFiscal 
                  Set @QtdPdv = @QtdSldFiscal
              end

            if @FlgUndMin = 0
              begin
                Select @pr_VolUniMin = IsNull(Vol_Emb,0)
                  From PRODU
                 Where Codigo = @CodPrd
              end
            else
            -- volume da embalagem Unidade minima
              begin
                Select @pr_VolUniMin = IsNull(Vol_Emb/Fat_CnvApr,0)
                  From PRXAP
                 Where Cod_Produt = @CodPrd
				   And Flg_Padrao = 1
              end

            -- verifica atendimento lote especifico
			Set @QtdLotSel = 0

            Set @QtdFra = @QtdPdv  
            -------------------------------------------------------------------------------------------------------------------------------------------------------
            if @to_CodCfoNorInt > 0
              begin
                -- venda FAT estoque compartilhado
                Declare PRLTL_Cr Cursor Local Fast_Forward For 

                  Select '1' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal, 
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, lt.Qtd_SldPra
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0),
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_SldPra,0) >= IsNull(l1.C_QtdEmbFec,0)
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0), 
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldPra,0) >= IsNull(l2.C_QtdEmbFec,0)
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     and IsNull(lt.Qtd_SldPra,0) > 0
                     and @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                  UNION ALL
                  Select '2' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal,
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, IsNull(lt.Qtd_SldDep,0) 
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0),
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_SldDep,0) >= IsNull(l1.C_QtdEmbFec,0) 
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0), 
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldDep,0) >= IsNull(l2.C_QtdEmbFec,0)  
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd  
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                     And @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                   Order by OrdDep, CodLocEst, Dat_Vencim, Flg_PrePck desc, Num_Rua, Num_Niv, Num_Apt, Num_Col, Cod_Lote, Dat_Entrada
				   --        1,2       1,2
              end
            else
              begin
                -- venda ORC estoque compartilhado
                Declare PRLTL_Cr Cursor Local Fast_Forward For 
                  Select '2' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal,
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, lt.Qtd_SldDep
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0), 
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_SldDep,0) >= IsNull(l1.C_QtdEmbFec,0)
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0),
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldDep,0) >= IsNull(l2.C_QtdEmbFec,0)
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                     And @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                  UNION ALL
                  Select '1' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal,
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, lt.Qtd_SldPra
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0), 
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                            And IsNull(l1.Qtd_SldPra,0) >= IsNull(l1.C_QtdEmbFec,0)
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0),
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldPra,0) >= IsNull(l2.C_QtdEmbFec,0)
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_SldPra,0) > 0
                     And @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                   Order by OrdDep, CodLocEst desc, Dat_Vencim, Flg_PrePck desc, Num_Rua, Num_Niv, Num_Apt, Num_Col, Cod_Lote, Dat_Entrada
              end
            -------------------------------------------------------------------------------------------------------------------------------------------------------
            Open PRLTL_Cr
            Fetch Next From PRLTL_Cr Into @LocEst, @OrdDep, @DatVct, @FlgPrePck, @DatEnt, @CodLot, @QtdEmbFec, @QtdEmbFecCal,
                                          @CodDep, @NumRua, @NumCol, @NumNiv,@NumApt, @SldLot 

            While @@FETCH_STATUS = 0
              begin
                -- ajusta saldo do lote : proporcional a fator de conversão DMD-7954: 30/03/2023
                Set @SldLot = (@SldLot/@FatCnvImpFat) * @FatCnvImpFat

                -- verifica lote unico
                Set @QtdLotSel = @QtdLotSel + 1
                if (@cl_FlgBlqLotVarPdv = 1) and (@QtdLotSel > 1)
                  Break

                if (@QtdFra > 0) and (@QtdFra >= @QtdEmbFecCal) and (@SldLot >= @QtdEmbFecCal)
                  begin
                    Set @QtdCxaFec = Case 
                                       When @SldLot < @QtdFra Then @SldLot / @QtdEmbFecCal
                                       Else @QtdFra / @QtdEmbFecCal
                                     End

                    Set @QtdUndLot = @QtdCxaFec * @QtdEmbFecCal

                    -- decrementa saldo em PRLTL
                    Set @QtdPraLot = 0
                    Set @QtdDepLot = 0
                    if @LocEst = '1'
                      Set @QtdPraLot = @QtdUndLot
                    else
                      Set @QtdDepLot = @QtdUndLot

                    Update PRLTL
                       Set Qtd_SolPra = IsNull(Qtd_SolPra,0) + @QtdPraLot,
                           Qtd_SolDep = IsNull(Qtd_SolDep,0) + @QtdDepLot
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
                       And Qtd_EmbFec = @QtdEmbFec 
                       And Cod_Dep =  @CodDep
                       And Num_Rua = @NumRua
                       And Num_Col = @NumCol
                       And Num_Niv = @NumNiv
                       And Num_Apt = @NumApt

                    Set @QtdFra = @QtdFra - @QtdUndLot
                    Set @SldLot = @SldLot - @QtdUndLot

                    -- grava registro em PDVLT 
                    Set @VolTotIte = @QtdUndLot*@pr_VolUniMin
                    Set @FlgDesord = 0

					if (@QtdPraLot+@QtdDepLot) > 0
                      begin
					    --Set @NumEst = IsNull((Select z.Num_Esteira From TBZON z Where z.Cod_Estabe = @CodEstabe and @NumRua between z.Num_RuaIni and z.Num_RuaFim),0)
						Set @NumEst = IsNull((Select z.Num_Esteira From TBZON z Where z.Cod_Estabe = @CodEstabe and Cod_Dep = @CodDep and @NumRua between z.Num_RuaIni and z.Num_RuaFim),0)

                        -- caixa fechada: sempre um novo volume
                        Set @NumVol = @NumVol + 1
                        if @NumVol = 0 Set @NumVol = 1

                        if Exists(Select 1 From PDVLT 
                                   Where Cod_Estabe = @CodEstabe 
                                     And Cod_Pedido = @CodPed And Num_Vol = @NumVol) 
                          Set @NumVol = @NumVol + 1

                        -- caixa fechada: PDVLT.Cod_LocFis = 'PRLTL',  PDVLT.Qtd_CxaFec > 0
                        Insert Into PDVLT (Cod_Estabe, Cod_Pedido, Num_Vol, Cod_Produt, Cod_Lote
                                        ,  Qtd_EmbFec, Fat_CnvAprEmbPad, Qtd_Lote, Qtd_CxaFec
                                        ,  Cod_Dep, Num_Esteira, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis
                                        ,  Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Id_PolCom, Flg_Desord, Flg_Manual
                                        ,  Cod_FunSep, Transacao)
                                   Values (@CodEstabe, @CodPed, @NumVol, @CodPrd, @CodLot
                                        ,  @QtdEmbFec, @QtdEmbFecCal, @QtdUndLot, @QtdCxaFec
                                        ,  @CodDep, @NumEst, @NumRua, @NumCol, @NumNiv, @NumApt, 'PRLTL'
                                        ,  @QtdPraLot, @QtdDepLot, @VolTotIte, @IdPolLot, @FlgDesord, 0
                                        ,  0, @Now )
                        if @@error <> 0
                          begin
                            Rollback Transaction
                            Return
                          end
                      end

                  end -- if (@QtdFra > 0) and (@QtdFra >= @QtdEmbFec) and (@SldLot >= @QtdEmbFec) 

                Fetch Next From PRLTL_Cr Into @LocEst, @OrdDep, @DatVct, @FlgPrePck, @DatEnt, @CodLot, @QtdEmbFec, @QtdEmbFecCal,
                                              @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @SldLot 
              end    -- While @@FETCH_STATUS = 0
              
            Close PRLTL_Cr
            Deallocate PRLTL_Cr

            Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @FatCnvImpFat, @QtdPdv
          end  -- While @@FETCH_STATUS = 0
          
        Close PDVIT_Cr
        Deallocate PDVIT_Cr
        
--------  FIM SOLICITA CAIXA FECHADA PULMAO --------------------------------------------------------------------------------------------------------------


        -- **************************************************  solicita lotes fracionados por vencimento do PICKING  ******************************************************************
        -- unico volume para fracionados
        Set @NumVol = @NumVol + 1

        -- ajusta volumes fracionados pré-existentes negativados
        Update PDVLT
           Set Num_Vol = @NumVol
         Where Cod_Estabe = @CodEstabe 
           And Cod_Pedido = @CodPed
           And Num_Vol < 0

        if @FlgUndMin = 0
          begin
            Declare PDVIT_Cr Cursor Local Fast_Forward For 
              Select x.Cod_Produt, x.IdPolLot, pr.Qtd_Embalagem, IsNull(pr.Vol_Emb,0), x.QtdFra,
                     FatCnvImpFat = IsNull((Select max(IsNull(Fat_CnvImpFat,1)) From #ARQ_PDVIT Where Cod_Produt = x.Cod_Produt and Id_PolLot = x.IdPolLot),1)     
				From (Select it.Cod_Produt, it.IdPolLot, (it.QtdPdv-IsNull(d.QtdLot,0)) as QtdFra
                        From (Select a.Cod_Produt, 
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = @CodEstabe and pl.Id_PolCom = a.Id_PolLot and pl.Cod_Produt = a.Cod_Produt) then a.Id_PolLot
                                                  Else 0
                                                End,
                                     sum(IsNull(a.Qtd_Pdv,0)) as QtdPdv
                                From #ARQ_PDVIT a
                               Where IsNull(a.Qtd_Pdv,0) > 0
                               Group by a.Cod_Produt, a.Id_PolLot) it Left Outer Join

                             (Select b.Cod_Produt, 
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = b.Cod_Estabe and pl.Id_PolCom = b.Id_PolCom and pl.Cod_Produt = b.Cod_Produt) then b.Id_PolCom
                                                  Else 0
                                                End,
                                     sum(IsNull(b.Qtd_Lote,0)) as QtdLot
                                From PDVLT b
                               Where b.Cod_Estabe = @CodEstabe
                                 And b.Cod_Pedido = @CodPed
                                 And IsNull(b.Qtd_Lote,0) > 0 
                                 And IsNull(b.Qtd_CxaFec,0) > 0   
                               Group by b.Cod_Estabe, b.Cod_Produt, b.Id_PolCom) d on (it.Cod_Produt = d.Cod_Produt and it.IdPolLot = d.IdPolLot)
                            
                       Where (it.QtdPdv-IsNull(d.QtdLot,0)) > 0) x  

                     Inner Join PRODU pr on x.Cod_Produt = pr.Codigo
          end
        else
          begin
            -- trabalha com unidade minima
            Declare PDVIT_Cr Cursor Local Fast_Forward For 
              Select x.Cod_Produt, x.IdPolLot, pr.Qtd_Embalagem, IsNull(ap.Vol_Emb/ap.Fat_CnvApr,0), x.QtdFra,
                     FatCnvImpFat = IsNull((Select max(IsNull(Fat_CnvImpFat,1)) From #ARQ_PDVIT Where Cod_Produt = x.Cod_Produt and Id_PolLot = x.IdPolLot),1)     
                From (Select it.Cod_Produt, it.IdPolLot, (it.QtdPdv-IsNull(d.QtdLot,0)) as QtdFra  -- it.Cod_Estabe, 
                        From (Select a.Cod_Produt, 
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = @CodEstabe and pl.Id_PolCom = a.Id_PolLot and pl.Cod_Produt = a.Cod_Produt) then a.Id_PolLot
                                                  Else 0
                                                End,
                                     sum(IsNull(a.Qtd_Pdv,0)) as QtdPdv
                                From #ARQ_PDVIT a
                               Where IsNull(a.Qtd_Pdv,0) > 0
                               Group by a.Cod_Produt, a.Id_PolLot) it Left Outer Join
                 
                             (Select b.Cod_Produt,
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = b.Cod_Estabe and pl.Id_PolCom = b.Id_PolCom and pl.Cod_Produt = b.Cod_Produt) then b.Id_PolCom
                                                  Else 0
                                                End,
                                     sum(IsNull(b.Qtd_Lote,0)) as QtdLot
                                From PDVLT b
                               Where b.Cod_Estabe = @CodEstabe
                                 And b.Cod_Pedido = @CodPed
                                 And IsNull(b.Qtd_Lote,0) > 0 
                                 And IsNull(b.Qtd_CxaFec,0) > 0   
                               Group by b.Cod_Estabe, b.Cod_Produt, b.Id_PolCom) d on (it.Cod_Produt = d.Cod_Produt and it.IdPolLot = d.IdPolLot)

                       Where (it.QtdPdv-IsNull(d.QtdLot,0)) > 0) x  

                     Inner Join PRODU pr on x.Cod_Produt = pr.Codigo
					 Inner Join PRXAP ap on pr.Codigo = ap.Cod_Produt and ap.Flg_Padrao = 1
          end
                 
        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @QtdEmbFec, @pr_VolUniMin, @QtdFra, @FatCnvImpFat
                           
        While @@FETCH_STATUS = 0
          begin
			if @FatCnvImpFat = 0 Set @FatCnvImpFat = 1

            -- nao permite negativar estoque fiscal
            if (@BlqEstFisNeg = 1) and (@FlgTipVenFat = 1)
              begin
                -- qtd solicitada anteriormente (cx fexhada)
                Set @QtdSolPulmao = IsNull((Select sum(Qtd_Lote) From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed 
                                               And Cod_Produt = @CodPrd And Cod_LocFis = 'PRLTL'),0)
                Set @QtdSldFiscal = dbo.FN_SldFiscalDisponPrd(@CodEstabe,@CodPrd) - @QtdSolPulmao
                if @QtdSldFiscal < 0 Set @QtdSldFiscal = 0
                if @QtdFra > @QtdSldFiscal 
                  Set @QtdFra = @QtdSldFiscal
              end
 
            Set @QtdAteAcu = 0    -- acumulador por produto
           
            -- verifica atendimento lote unico
            Set @CodLotEsp = ''
            Set @QtdLotSel = 0
			if (@cl_FlgBlqLotVarPdv = 1) and 
               Exists(Select 1 From PDVLT WHere Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Cod_Produt = @CodPrd) 
              Set @CodLotEsp = (Select top 1 Cod_Lote From PDVLT WHere Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Cod_Produt = @CodPrd)

            -- fracionados solicita somente pelo vencimento --
            if @to_CodCfoNorInt > 0
              begin
                Declare PRLOT_Cr Cursor Local Fast_Forward For   
                  Select '1' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldPra, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             and IsNull(l1.Qtd_SldPra,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                            From PRLOT l2 
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldPra,0) > 0
                          --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldPra,0) > 0
                  UNION ALL
                  Select '2' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldDep, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             And IsNull(l1.Qtd_SldDep,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                            From PRLOT l2 
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldDep,0) > 0
                          --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                   Order by OrdDep, Dat_Vencim, CodLocEst
              end
            else
              begin
                Declare PRLOT_Cr Cursor Local Fast_Forward For 
                  Select '1' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldPra, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             And IsNull(l1.Qtd_SldPra,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0) 
                            From PRLOT l2 
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldPra,0) > 0
                          --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldPra,0) > 0
                  UNION ALL
                  Select '2' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldDep, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0)
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             And IsNull(l1.Qtd_SldDep,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                            From PRLOT l2
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldDep,0) > 0
                             --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                   Order by OrdDep, Dat_Vencim, CodLocEst desc
              end
            -------------------------------------------------------------------------------------------------------------------------------------------------------
            Open PRLOT_Cr
            Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad

            Set @QtdAteAcu = 0
            
            While @@FETCH_STATUS = 0
              begin
                -- ajusta saldo do lote : proporcional a fator de conversão DMD-7954: 30/03/2023
                Set @SldLot = (@SldLot/@FatCnvImpFat) * @FatCnvImpFat

                While (@QtdAteAcu < @QtdFra) and (@@FETCH_STATUS = 0)
                  begin
                    -- verifica lote unico
                    Set @QtdLotSel = @QtdLotSel + 1
                    if (@cl_FlgBlqLotVarPdv = 1) and (@QtdLotSel > 1)
                      Break
		    
                    Set @QtdAte = @QtdFra - @QtdAteAcu
                    -- se o saldo do lote nao atender a qtd.solicitada refazer a solicitacao proporcionalmente
                    if @QtdAte > @SldLot
                      begin
                        Set @QtdAte = @SldLot
                      end
                     -- Atualiza saldo do lote
                    Set @QtdPraLot = 0
                    Set @QtdDepLot = 0
                    if @LocEst = '1'
                      Set @QtdPraLot = @QtdAte
                    else
                      Set @QtdDepLot = @QtdAte
		    
                    Update PRLOT
                       Set Qtd_SolPra = Qtd_SolPra + @QtdPraLot,
                           Qtd_SolDep = Qtd_SolDep + @QtdDepLot
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Dep = @CodDep
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
 		    
                    Set @QtdAteAcu = @QtdAteAcu + @QtdAte
		    
                    -- verifica se lote foi solicitado fora de ordem
                    Set @FlgDesord = 0
                    if (@DatVct is not Null) and (@cl_QtdMesMinPrzVctLot > 0) and 
                       (Exists(Select Cod_Lote From PRLOT Where Cod_Estabe = @CodEstabe And Cod_Dep = @CodDep And Cod_Produt = @CodPrd And Qtd_Saldo > 0 And Dat_Vencim < @DatVct))
                      Set @FlgDesord = 1
                               
                    -- pega endereço de picking do produto
                    Select @NumRua = dx.Num_Rua,
                           @NumCol = dx.Num_Col,   
                           @NumNiv = dx.Num_Niv,   
                           @NumApt = dx.Num_Apt,
                           @dx_CodLocFis = dx.Cod_LocFis,
                           @NumEst = ISNULL(z.Num_Esteira,0)   
                      From DPXPR dx Left Outer Join
                           TBZON z on (dx.Cod_Estabe = z.Cod_Estabe and dx.Num_Rua between z.Num_RuaIni and z.Num_RuaFim)
                     Where dx.Cod_Estabe = @CodEstabe
                       And dx.Cod_Dep = @CodDep
                       And dx.Cod_Produt = @CodPrd
                           
                    -- grava/regrava registro em PDVLT 
                    Set @VolTotIte = (@QtdPraLot+@QtdDepLot)*@pr_VolUniMin
		    
                     -- aqui ??? Id_PolCOm ????
                    if not Exists(Select 1 From PDVLT 
                                   Where Cod_Estabe = @CodEstabe 
                                     And Cod_Pedido = @CodPed And Num_Vol = @NumVol 
                                     And Cod_Produt = @CodPrd And Cod_Lote = @CodLot)
                      Insert Into PDVLT (Cod_Estabe, Cod_Pedido, Num_Vol, Cod_Produt, Cod_Lote
                                      ,  Qtd_EmbFec, Fat_CnvAprEmbPad, Qtd_Lote, Qtd_CxaFec
                                      ,  Cod_Dep, Num_Esteira, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis
                                      ,  Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Id_PolCom, Flg_Desord, Flg_Manual
                                      ,  Cod_FunSep, Transacao)
                                 Values (@CodEstabe, @CodPed,    @NumVol, @CodPrd,    @CodLot
                                      ,  @QtdEmbFec, @FatCnvAprEmbPad, 0,        0
                                      ,  @CodDep, @NumEst,     @NumRua, @NumCol, @NumNiv, @NumApt, @dx_CodLocFis
                                      , 0,           0,           0,          0,         @FlgDesord,  0
                                      , 0,          @Now)
                                              
                    Update PDVLT
                       Set Qtd_Lote    = IsNull(Qtd_Lote,0)    + @QtdAte,
                           Vol_TotIte  = IsNull(Vol_TotIte,0)  + @VolTotIte,
                           Qtd_LotePra = IsNull(Qtd_LotePra,0) + @QtdPraLot,
                           Qtd_LoteDep = IsNull(Qtd_LoteDep,0) + @QtdDepLot
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Pedido = @CodPed 
                       And Num_Vol = @NumVol 
                       And Cod_Produt = @CodPrd 
                       And Cod_Lote = @CodLot

                    Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad
		    
                  end  -- While (@QtdAteAcu < @QtdFra) and (@@FETCH_STATUS = 0)
				Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad
              end  -- While @@FETCH_STATUS = 0

            Close PRLOT_Cr
            Deallocate PRLOT_Cr

            Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @QtdEmbFec, @pr_VolUniMin, @QtdFra, @FatCnvImpFat
          end    -- While @@FETCH_STATUS = 0
          
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

	    -- corrige quantidades solicitades de lotes não multiplos de fator de conversão do item
        Exec dbo.PR_CorrigeQtdLoteProduto @CodEstabe, @CodPed, @CodPrd
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end

        -- verifica se necessita corrigir quantidades do pedido em PDVIT
        Exec PR_Corrige_PDVITxPDVLT @CodEstabe, @CodPed
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end

        -- normaliza quantidades 1 e 2 entre PDVLT e PDVIT
        if @FlgErr = 0
          Exec PR_NormalizaPDVITxPDVLT @CodEstabe, @CodPed

        -- verifica resultado 
        if @FlgErr = 0
          Exec PR_DivergenciasPDVITxPDVLT @CodEstabe, @CodPed, @FlgErr output, @StrMsg output

        -- reorganiza volumes
        if @FlgErr = 0
          Exec PR_ReorganizaVolumesPDV @CodEstabe, @CodPed

        -- atualiza status PDVCB
        if @FlgErr = 0
          Update PDVCB
             Set Sta_SepLot = 'F'
           Where Cod_Estabe = @CodEstabe
             And Numero = @CodPed


        IF OBJECT_ID('tempdb..#ARQ_PRLOT') IS NOT NULL
          DROP TABLE #ARQ_PRLOT

        IF OBJECT_ID('tempdb..#ARQ_PRLTL') IS NOT NULL
          DROP TABLE #ARQ_PRLTL

        IF OBJECT_ID('tempdb..#ARQ_PDVIT') IS NOT NULL
          DROP TABLE #ARQ_PDVIT


        -- recalcula tributos PDV devido a SBt Ret Ant em PDVLT
        -- seria melhor criar uma flag em PDVCB?
        if Exists(Select 1
                    From PDVCB cb
                         inner join RGTRI rg on cb.Cod_RegTri = rg.Cod_RegTri
                   Where cb.Numero = @CodPed
                     And cb.Tip_Pedido = 'P'
                     And rg.Flg_DscSbtOrgPub = 1)
          Exec dbo.PR_CalcTributPDV @CodEstabe, @CodPed

      end  -- if @FlgPodeFechar = 1

    if @FlgErr = 1
      begin
        Update PDVCB
           Set Sta_SepLot = null
         Where Cod_Estabe = @CodEstabe
           And Numero = @CodPEd
        RAISERROR(@StrMsg,16,1)
        Rollback Transaction
        Return
      end
    else
      begin
--        Set @DesLoc = '(DEPOIS) PR_SolicitaLotesPDV pedido: '+cast(@CodPed as varchar)
--        Exec PR_Verifica_Divergencia_PRXESxPRLOT_PRLTL @DesLoc, @CodEstabe, 0

        Commit Transaction
      end
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CorrigeEstoqueProdut] 
@PCodEstabe int,
@PCodProdut int   -- opcional @PCodProdut = 0 : reprocessa todos os produtos

AS

SET NOCOUNT ON

-- igualando Qtd_Fisico em PRODU com PRSLD:.
if Exists(Select 1
            From PRXES p
                 Cross Apply (Select top 1 s.Qtd_SldAtu
                                From PRSLD s
                               Where s.Cod_Estabe = p.Cod_Estabe and s.Cod_Produt = p.Cod_Produt
                               Order by s.Dat_Movime desc) x
           Where p.Cod_Estabe = @PCodEstabe
             And p.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else p.Cod_Produt End
             And p.Qtd_Fisico <> IsNull(x.Qtd_SldAtu,0))
  begin
    Update p
       Set p.Qtd_Fisico = IsNull(x.Qtd_SldAtu,0)
      From PRXES p
           Cross Apply (Select top 1 s.Qtd_SldAtu
                          From PRSLD s
                         Where s.Cod_Estabe = p.Cod_Estabe and s.Cod_Produt = p.Cod_Produt
                         Order by s.Dat_Movime desc) x
     Where p.Cod_Estabe = @PCodEstabe
       And p.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else p.Cod_Produt End
       And p.Qtd_Fisico <> IsNull(x.Qtd_SldAtu,0)
  end

-- atualiza quarentena em PRXES
if Exists(Select 1
            From PRXES p 
                Left Join (Select lt.Cod_Estabe, lt.Cod_Produt, Sum(lt.Qtd_Saldo) as QtdQuarentena
                             From PRLTL lt
                            Where lt.Cod_Estabe = @PCodEstabe 
                              And lt.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else lt.Cod_Produt End
                              And lt.Qtd_Saldo > 0
                              And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'X'
                            Group by lt.Cod_Estabe, lt.Cod_Produt) x on p.Cod_Produt = x.Cod_Produt
           Where p.Cod_Estabe = @PCodEstabe 
             And p.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else p.Cod_Produt End
             And p.Qtd_Quaren <> IsNull(x.QtdQuarentena,0))
  begin
    Update p
       Set p.Qtd_Quaren = IsNull(x.QtdQuarentena,0)
      From PRXES p 
           Left Join (Select lt.Cod_Estabe, lt.Cod_Produt, Sum(lt.Qtd_Saldo) as QtdQuarentena
                        From PRLTL lt
                       Where lt.Cod_Estabe = @PCodEstabe 
                         And lt.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else lt.Cod_Produt End
                         And lt.Qtd_Saldo > 0
                         And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'X'
                       Group by lt.Cod_Estabe, lt.Cod_Produt) x on p.Cod_Produt = x.Cod_Produt
     Where p.Cod_Estabe = @PCodEstabe 
       And p.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else p.Cod_Produt End
       And p.Qtd_Quaren <> IsNull(x.QtdQuarentena,0)
   end
 
-- atualiza cross docking em PRXES
if Exists(Select 1
            From PRXES p 
                 Left Join (Select lt.Cod_Estabe, lt.Cod_Produt, Sum(lt.Qtd_Saldo) as QtdCrossDock
                              From PRLTL lt
                             Where lt.Cod_Estabe = @PCodEstabe 
                               And lt.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else lt.Cod_Produt End
                               And lt.Qtd_Saldo > 0
                               And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'C'
                             Group by lt.Cod_Estabe, lt.Cod_Produt) x on p.Cod_Produt = x.Cod_Produt
           Where p.Cod_Estabe = @PCodEstabe 
             And p.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else p.Cod_Produt End
             And p.Qtd_CrossDock <> IsNull(x.QtdCrossDock,0))
  begin
    Update p
       Set p.Qtd_CrossDock = IsNull(x.QtdCrossDock,0)
      From PRXES p 
           Left Join (Select lt.Cod_Estabe, lt.Cod_Produt, Sum(lt.Qtd_Saldo) as QtdCrossDock
                        From PRLTL lt
                       Where lt.Cod_Estabe = @PCodEstabe 
                         And lt.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else lt.Cod_Produt End
                         And lt.Qtd_Saldo > 0
                         And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'C'
                       Group by lt.Cod_Estabe, lt.Cod_Produt) x on p.Cod_Produt = x.Cod_Produt
     Where p.Cod_Estabe = @PCodEstabe 
       And p.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else p.Cod_Produt End
       And p.Qtd_CrossDock <> IsNull(x.QtdCrossDock,0)
  end

if Exists(Select 1
            From PRXES p 
                 Left Join (Select Cod_Estabe, Cod_Produto, 
                                   QtdTotRes = sum(IsNull(Qtd_Movimento,0)+IsNull(Qtd_ResDep,0))
                              From RESER 
                             Where Cod_Estabe  = @PCodEstabe 
                               And Cod_Produto = Case When @PCodProdut > 0 then @PCodProdut Else Cod_Produto End
                             Group by Cod_Estabe, Cod_Produto) x on (p.Cod_Estabe = x.Cod_Estabe And p.Cod_Produt = x.Cod_Produto) 
           Where p.Cod_Estabe = @PCodEstabe 
             And p.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else p.Cod_Produt End
             And p.Qtd_Reserv <>  IsNull(x.QtdTotRes,0))
  begin
    Update p
       Set p.Qtd_Reserv = IsNull(x.QtdTotRes,0)
      From PRXES p 
           Left Join (Select Cod_Estabe, Cod_Produto, 
                             QtdTotRes = sum(IsNull(Qtd_Movimento,0)+IsNull(Qtd_ResDep,0))
                        From RESER 
                       Where Cod_Estabe  = @PCodEstabe 
                         And Cod_Produto = Case When @PCodProdut > 0 then @PCodProdut Else Cod_Produto End
                       Group by Cod_Estabe, Cod_Produto) x on (p.Cod_Estabe = x.Cod_Estabe And p.Cod_Produt = x.Cod_Produto) 
     Where p.Cod_Estabe = @PCodEstabe 
       And p.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else p.Cod_Produt End
       And p.Qtd_Reserv <>  IsNull(x.QtdTotRes,0)
  end
  
if Exists(Select 1
            From PRXES p 
                 Inner Join (Select Cod_Estabe, Cod_Produto, 
                                    QtdTotAva = sum(IsNull(Qtd_Movimento,0)+IsNull(Qtd_AvaDep,0))
                               From AVARI 
                              Where Cod_Estabe = @PCodEstabe 
                               And Cod_Produto = Case When @PCodProdut > 0 then @PCodProdut Else Cod_Produto End
                             Group by Cod_Estabe, Cod_Produto) x on (p.Cod_Estabe = x.Cod_Estabe And p.Cod_Produt = x.Cod_Produto)
           Where p.Cod_Estabe = @PCodEstabe 
             And p.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else p.Cod_Produt End
             And p.Qtd_Avaria <> IsNull(x.QtdTotAva,0))
  begin
    Update p
       Set p.Qtd_Avaria =  IsNull(x.QtdTotAva,0)
      From PRXES p 
           Left Join (Select Cod_Estabe, Cod_Produto, 
                             QtdTotAva = sum(IsNull(Qtd_Movimento,0)+IsNull(Qtd_AvaDep,0))
                        From AVARI 
                       Where Cod_Estabe = @PCodEstabe 
                        And Cod_Produto = Case When @PCodProdut > 0 then @PCodProdut Else Cod_Produto End
                      Group by Cod_Estabe, Cod_Produto) x on (p.Cod_Estabe = x.Cod_Estabe And p.Cod_Produt = x.Cod_Produto)
     Where p.Cod_Estabe = @PCodEstabe 
       And p.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else p.Cod_Produt End
       And p.Qtd_Avaria <> IsNull(x.QtdTotAva,0)
  end


-- solicitando quantidades de pedidos em PRODU
Update p
   Set p.Qtd_Solici = IsNull(x.Qtd_Solicitado,0)+IsNull(y.Qtd_Solicitado,0)
  From PRXES p LEFT OUTER JOIN 
       (Select it.Cod_Estabe, it.Cod_Produto,
               sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) as Qtd_Solicitado
          From PDVCB cb Inner Join 
               PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
         Where cb.Cod_Estabe = @PCodEstabe
           and cb.Tip_Pedido = 'P'
           and cb.Status1 = 'P'
           and cb.Status2 <> 'N'
           and cb.Status2 <> 'D'
           --and cb.Status2 <> 'X'
           and ((IsNull(cb.Bloqueio,'') = '') or (cb.Bloqueio <> 'SR'))
           and it.Cod_Produto = Case When @PCodProdut > 0 then @PCodProdut Else it.Cod_Produto End
           and (IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) > 0
         Group by it.Cod_Estabe, it.Cod_Produto) x ON (p.Cod_Estabe = x.Cod_Estabe And p.Cod_Produt = x.Cod_Produto) LEFT OUTER JOIN 
       (Select it.Cod_Estabe, it.Cod_Produt,
               sum(IsNull(it.Qtd_Produt,0)) as Qtd_Solicitado
          From ORCCB cb Inner Join
               ORCIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Cod_Orcame = it.Cod_Orcame)
         Where cb.Cod_Estabe = @PCodEstabe
           and cb.Sta_Movime = 'F'
           and IsNull(cb.Cod_OriVen,'') <> 'DMD'
           and IsNull(cb.Num_Docume,0) = 0
           and it.Tip_EntSai = 'S'
           and it.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else it.Cod_Produt End
           and (IsNull(it.Qtd_Produt,0)) > 0
         Group by it.Cod_Estabe, it.Cod_Produt) y ON (p.Cod_Estabe = y.Cod_Estabe and p.Cod_Produt = y.Cod_Produt)
 Where p.Cod_Estabe = @PCodEstabe
   And p.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else p.Cod_Produt End
   And p.Qtd_Solici <> IsNull(x.Qtd_Solicitado,0)+IsNull(y.Qtd_Solicitado,0)

Update p
   Set p.Qtd_PrmSolici = IsNull(x.Qtd_Solicitado,0)+IsNull(y.Qtd_Solicitado,0)
  From PRXES p Left Join
       (Select it.Cod_Estabe, it.Cod_Produto,
               sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) as Qtd_Solicitado
          From PDVCB cb Inner Join
               PDVIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido
         Where cb.Cod_Estabe = @PCodEstabe
           and cb.Tip_Pedido = 'P'
           and cb.Status1 = 'P'
           and cb.Status2 <> 'N'
           and cb.Status2 <> 'D'
           and ((IsNull(cb.Bloqueio,'') = '') or (cb.Bloqueio <> 'SR'))
           and it.Cod_Produto = Case When @PCodProdut > 0 then @PCodProdut Else it.Cod_Produto End
           and (IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) > 0
           and it.Cod_Promocao > 0
         Group by it.Cod_Estabe, it.Cod_Produto) x ON (p.Cod_Estabe = x.Cod_Estabe and p.Cod_Produt = x.Cod_Produto) Left Outer Join
       (Select it.Cod_Estabe, it.Cod_Produt,
               sum(IsNull(it.Qtd_Produt,0)) as Qtd_Solicitado
          From ORCCB cb Inner Join 
               ORCIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Cod_Orcame = it.Cod_Orcame
         Where cb.Cod_Estabe = @PCodEstabe
           and cb.Sta_Movime = 'F'
           and IsNull(cb.Num_Docume,0) = 0
		   and IsNull(cb.Cod_OriVen,'') <> 'DMD'
           and it.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else it.Cod_Produt End
           and it.Tip_EntSai = 'S'
           and (IsNull(it.Qtd_Produt,0)) > 0
           and it.Cod_Promoc > 0
         Group by it.Cod_Estabe, it.Cod_Produt) y ON (p.Cod_Estabe = y.Cod_Estabe and p.Cod_Produt = y.Cod_Produt)
 Where p.Cod_Estabe = @PCodEstabe 
   And p.Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else p.Cod_Produt End
   And p.Qtd_PrmSolici <> IsNull(x.Qtd_Solicitado,0)+IsNull(y.Qtd_Solicitado,0)

-- normaliza PRXES
if Exists(Select 1
            From PRXES pr
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else Cod_Produt End
             And Qtd_Dispon <> (IsNull(Qtd_Fisico,0)-IsNull(Qtd_Solici,0)-IsNull(Qtd_Reserv,0)-IsNull(Qtd_Avaria,0)))
  begin
    Update PRXES
       Set Qtd_Dispon = IsNull(Qtd_Fisico,0)-IsNull(Qtd_Solici,0)-IsNull(Qtd_Reserv,0)-IsNull(Qtd_Avaria,0)
     Where Cod_Estabe = @PCodEstabe 
       And Cod_Produt = Case When @PCodProdut > 0 then @PCodProdut Else Cod_Produt End
       And Qtd_Dispon <> (IsNull(Qtd_Fisico,0)-IsNull(Qtd_Solici,0)-IsNull(Qtd_Reserv,0)-IsNull(Qtd_Avaria,0))
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].PR_ReprocessaTransitoProduto
@PCodEstabe int,
@PCodPrd int     -- codigo produto <= 0 : reprocessa tudo

AS

SET NOCOUNT ON 

BEGIN TRANSACTION

-- Reprocessando Transito
Update pr
   Set pr.Qtd_Transi = Case When IsNull(cp.QtdPen,0) > 0 Then cp.QtdPen Else 0 End  
  From dbo.PRXES pr 
       left Join (Select it.Cod_Estabe, it.Cod_Produto,
                         QtdPen = sum(IsNull(it.Qtd_Pendente,0))
                    From dbo.PDCCB cb 
                         Inner Join dbo.PDCIT it on (it.Cod_Estabe = cb.Cod_Estabe and it.Numero = cb.Numero)
                   Where cb.Cod_Estabe = @PCodEstabe
                     And cb.Status = 'P' 
                   Group by it.Cod_Estabe, it.Cod_Produto) cp on pr.Cod_Estabe = cp.Cod_Estabe and pr.Cod_Produt = cp.Cod_Produto
 Where pr.Cod_Estabe = @PCodEstabe
   And ((@PCodPrd > 0) and (pr.Cod_Produt = @PCodPrd) or (@PCodPrd <= 0))

COMMIT TRANSACTION
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ReprocessaQtdSolicPRODU]
@PCodEstabe int

WITH RECOMPILE
AS

SET NOCOUNT ON
SET ANSI_WARNINGS OFF

BEGIN TRANSACTION

Declare @CodPrd int,
        @CodLot varchar(20),
        @QtdMov int,
        @QtdPra int,
        @QtdDep int,
        @CodPrm int,
        @QtdDis int,
        @QtdCxaFec int,
        @QtdEmbFec int,
        @CodDep smallint, 
        @NumRua smallint, 
        @NumCol smallint , 
        @NumNiv smallint, 
        @NumApt smallint,
        @DatVct smalldatetime

  Set @CodDep = IsNull((Select top 1 Cod_Dep From dbo.TBDEP Order by Cod_Dep),1)

-----------------------

-- Normaliza PRLOT/PRLTL
  Update dbo.PRLOT
     Set Cod_Dep = @CodDep
   Where Cod_Estabe = @PCodEstabe  
     And IsNull(Cod_Dep,0) < @CodDep
     And Not Exists (Select Cod_Estabe, @CodDep, Cod_Produt, Cod_Lote 
                     Intersect
                     Select Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote From dbo.PRLOT)
  
  Update dbo.PRLTL
     Set Cod_Dep = @CodDep
   Where Cod_Estabe = @PCodEstabe  
     And IsNull(Cod_Dep,0) < @CodDep
  
  Update dbo.PRLTL
     Set Qtd_EmbFec = 1
   Where Cod_Estabe = @PCodEstabe    
     And IsNull(Qtd_EmbFec,0) <= 0    
  
  Update l1
     Set l1.Dat_Vencim = l2.Dat_Vencim
    From dbo.PRLTL l1 Inner Join
         (Select Cod_Estabe, Cod_Produt, Cod_Lote, Dat_Vencim = max(Dat_Vencim), Dat_Fabric = max(Dat_Fabric)
            From dbo.PRLTL
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Produt > 0
           Group by Cod_Estabe, Cod_Produt, Cod_Lote) l2 on (l1.Cod_Estabe = l2.Cod_Estabe and 
                                                             l1.Cod_Produt = l2.Cod_Produt and 
                                                             l1.Cod_Lote = l2.Cod_Lote)
   Where l1.Cod_Estabe = @PCodEstabe
     And IsNull(l1.Dat_Vencim,0) <> IsNull(l2.Dat_Vencim,0)       
  
  Update l1
     Set l1.Dat_Fabric = l2.Dat_Fabric
    From dbo.PRLTL l1 Inner Join
         (Select Cod_Estabe, Cod_Produt, Cod_Lote, Dat_Vencim = max(Dat_Vencim), Dat_Fabric = max(Dat_Fabric)
            From dbo.PRLTL
           Where Cod_Estabe = @PCodEstabe 
             and Cod_Produt > 0
           Group by Cod_Estabe, Cod_Produt, Cod_Lote) l2 on (l1.Cod_Estabe = l2.Cod_Estabe and 
                                                             l1.Cod_Produt = l2.Cod_Produt and 
                                                             l1.Cod_Lote = l2.Cod_Lote)
   Where l1.Cod_Estabe = @PCodEstabe
     And IsNull(l1.Dat_Fabric,0) <> IsNull(l2.Dat_Fabric,0)       

  Update l1
     Set l1.Dat_Vencim = l2.Dat_Vencim
    From dbo.PRLTL l1, dbo.PRLOT l2
   Where l1.Cod_Estabe = l2.Cod_Estabe
     And l1.Cod_Produt = l2.Cod_Produt
     And l1.Cod_Lote = l2.Cod_Lote
     And l1.Cod_Estabe = @PCodEstabe
     And IsNull(l1.Dat_Vencim,0) <> IsNull(l2.Dat_Vencim,0)
  
  Update l1
     Set l1.Dat_Fabric = l2.Dat_Fabric
    From dbo.PRLTL l1, dbo.PRLOT l2
   Where l1.Cod_Estabe = l2.Cod_Estabe
     And l1.Cod_Produt = l2.Cod_Produt
     And l1.Cod_Lote = l2.Cod_Lote
     And l1.Cod_Estabe = @PCodEstabe
     And IsNull(l1.Dat_Fabric,0) <> IsNull(l2.Dat_Fabric,0)
  
  Update l1
     Set l1.Dat_Vencim = l2.Dat_Vencim
    From dbo.PRLOT l1 Inner Join
         (Select Cod_Estabe,Cod_Produt, Cod_Lote, Dat_Vencim = max(Dat_Vencim), Dat_Fabric = max(Dat_Fabric)
            From dbo.PRLTL
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Produt > 0
           Group by Cod_Estabe, Cod_Produt, Cod_Lote) l2 on (l1.Cod_Estabe = l2.Cod_Estabe and 
                                                             l1.Cod_Produt = l2.Cod_Produt and 
                                                             l1.Cod_Lote = l2.Cod_Lote)
   Where l1.Cod_Estabe = @PCodEstabe
     And IsNull(l1.Dat_Vencim,0) <> IsNull(l2.Dat_Vencim,0)       
  
  Update l1
     Set l1.Dat_Fabric = l2.Dat_Fabric
    From dbo.PRLOT l1 Inner Join
         (Select Cod_Estabe, Cod_Produt, Cod_Lote, Dat_Vencim = max(Dat_Vencim), Dat_Fabric = max(Dat_Fabric)
            From dbo.PRLTL
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Produt > 0
           Group by Cod_Estabe, Cod_Produt, Cod_Lote) l2 on (l1.Cod_Estabe = l2.Cod_Estabe and 
                                                             l1.Cod_Produt = l2.Cod_Produt and 
                                                             l1.Cod_Lote = l2.Cod_Lote)
   Where l1.Cod_Estabe = @PCodEstabe 
     And IsNull(l1.Dat_Fabric,0) <> IsNull(l2.Dat_Fabric,0)       
  
  Delete lt
    From dbo.PRLOT lt
         Inner Join dbo.PRXES pr on lt.Cod_Estabe = pr.Cod_Estabe and lt.Cod_Produt = pr.Cod_Produt
   Where lt.Cod_Estabe = @PCodEstabe
     And lt.Qtd_Saldo > 0
     And pr.Qtd_Dispon = 0     
     And not Exists(Select 1 From dbo.PRSLD s Where pr.Cod_Estabe = s.Cod_Estabe and pr.Cod_Produt = s.Cod_Produt)

  -- se não existir, insere em PRLOT lotes de PRLTL
  Insert into PRLOT(Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_FisPra, Qtd_SolPra, Qtd_FisDep, Qtd_SolDep)
    Select distinct l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Cod_Lote, max(l1.Dat_Vencim), max(l1.Dat_Fabric), 0, 0, 0, 0
      From dbo.PRLTL l1 
     Where l1.Cod_Estabe = @PCodEstabe 
       And l1.Qtd_Fisico > 0
       And not Exists(Select 1 From dbo.PRLOT l2 
                       Where l1.Cod_Estabe = l2.Cod_Estabe and l1.Cod_Dep = l2.Cod_Dep
                         and l1.Cod_Produt = l2.Cod_Produt and l1.Cod_Lote = l2.Cod_Lote)
     Group by l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Cod_Lote

-- normaliza PRLOT
  Update dbo.PRLOT
     Set Qtd_FisPra = 0
  Where Cod_Estabe = @PCodEstabe
    And Qtd_FisPra < 0

  Update dbo.PRLOT
     Set Qtd_FisDep = 0
   Where Cod_Estabe = @PCodEstabe
     And Qtd_FisDep < 0

  Delete 
    From dbo.PRLTL
   Where Cod_Estabe = @PCodEstabe
     And IsNull(Qtd_Fisico,0) = 0

  Delete lt
    From dbo.PRLOT lt 
         Left Join dbo.PRLTL dp on ((lt.Cod_Estabe = dp.Cod_Estabe) and (lt.Cod_Produt = dp.Cod_Produt) and (lt.Cod_Lote = dp.Cod_Lote))
 Where lt.Cod_Estabe = @PCodEstabe     
   And lt.Qtd_Fisico = 0
   And IsNull(lt.Cod_Lote,'') = ''
   And IsNull(dp.Qtd_Fisico,0) = 0

  -- normalizando PDVLT e PRLTL e PRLOT
  Update dbo.PDVLT
     Set Num_Apt = 0
   Where Cod_Estabe = @PCodEstabe    
     And Num_Apt is null

  Update dbo.PRLTL
     Set Num_Apt = 0
   Where Cod_Estabe = @PCodEstabe    
     And Num_Apt is null

  Update dbo.PRLOT
     Set Cod_Lote = '*'
   Where Cod_Estabe = @PCodEstabe    
     And IsNull(Cod_Lote,'') = ''

  Update dbo.PRLTL
     Set Cod_Lote = '*'
   Where Cod_Estabe = @PCodEstabe    
     And IsNull(Cod_Lote,'') = ''

/*
  -- normaliza quantidades dos estoques nos itens de pedido: lento 3s
  -- colocar nos procedimentos iniciais
  if Exists(Select 1
              From dbo.PDVIT it
             Where it.Cod_Estabe = @PCodEstabe 
               And not Exists (Select 1 From dbo.PDVCB cb Where cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido))
    begin
      Delete it
        From dbo.PDVIT it
       Where it.Cod_Estabe = @PCodEstabe 
         And not Exists (Select 1 From dbo.PDVCB cb Where cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
    end
  
  if Exists(Select 1
              From dbo.ORCIT it
             Where it.Cod_Estabe = @PCodEstabe 
               And not Exists (Select 1 From dbo.ORCCB cb Where cb.Cod_Estabe = it.Cod_Estabe And cb.Cod_Orcame = it.Cod_Orcame))
    begin
      Delete it
        From dbo.ORCIT it 
       Where it.Cod_Estabe = @PCodEstabe  
         And not Exists (Select 1 From dbo.ORCCB cb Where cb.Cod_Estabe = it.Cod_Estabe And cb.Cod_Orcame = it.Cod_Orcame)
    end

  if Exists(Select 1
              From dbo.PDVLT it
             Where it.Cod_Estabe = @PCodEstabe 
               And not Exists (Select 1 From dbo.PDVCB cb Where cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido))
    Delete it
      From dbo.PDVLT it 
    Where it.Cod_Estabe = @PCodEstabe 
      And not Exists (Select 1 From dbo.PDVCB cb Where cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
*/
    

/*
  -- lento: 10s
  If object_id('tempdb..#PDVCB') Is Not Null
    Drop Table #PDVCB;

  Select Cod_Estabe, Numero Into #PDVCB
  From (
  Select Cb.Cod_Estabe, cb.Numero
    From dbo.PDVCB cb
   Where cb.Tip_Pedido <> 'C' And cb.Status1 <> 'P' And cb.Status2 <> 'A'
      And ( Exists(Select it.Cod_Pedido 
                     From dbo.PDVIT it
                    Where it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Pedido = cb.Numero
                      And (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0)))) 
     And (cb.Flg_Calc = 0 Or cb.Flg_Calc Is Null)
  UNION 
  Select Cb.Cod_Estabe, cb.Numero
    From dbo.PDVCB cb
   Where cb.Tip_Pedido <> 'C' And cb.Status1 <> 'P' And cb.Status2 <> 'A'
      And ( Exists(Select it.Cod_Pedido 
                     From dbo.PDVLT it
                    Where it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Pedido = cb.Numero
                      And Isnull(it.Qtd_Lote,0) <> (Isnull(it.Qtd_LotePra,0)+Isnull(it.Qtd_LoteDep,0)))) 
     And (cb.Flg_Calc = 0 Or cb.Flg_Calc Is Null)
  ) as X

  Update cb 
     Set Flg_Calc = 1
    From dbo.PDVCB cb
         inner join #PDVCB T ON cb.Cod_Estabe = T.Cod_Estabe And cb.Numero = T.Numero
*/
Update cb
   Set cb.Flg_Calc = 1
  From dbo.PDVCB cb
 Where cb.Cod_Estabe = @PCodEstabe
   And cb.Tip_Pedido <> 'C' And cb.Status1 <> 'P' And cb.Status2 <> 'A'
   And ( Exists(Select 1
                  From dbo.PDVIT it
                 Where it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Pedido = cb.Numero
                   And (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> 
                       (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0))) or
		 Exists(Select it.Cod_Pedido 
                  From dbo.PDVLT it
                 Where it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Pedido = cb.Numero
                   And Isnull(it.Qtd_Lote,0) <> 
                       (Isnull(it.Qtd_LotePra,0)+Isnull(it.Qtd_LoteDep,0))) )
   And IsNull(cb.Flg_Calc,0) = 0



  if Exists(Select 1
              From dbo.PDVCB cb 
                   inner Join dbo.PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
             Where cb.Cod_Estabe = @PCodEstabe
               and cb.Tip_Pedido = 'P'
               and IsNull(cb.Flg_WMS,0) = 1 
               and not Exists(Select 1 From dbo.PDVLT lt Where lt.Cod_Estabe = cb.Cod_Estabe and lt.Cod_Pedido = cb.Numero)
               and cb.Status1 = 'P'
               and cb.Status2 <> 'N'
               and IsNull(cb.Bloqueio,'') <> 'SR'
               and (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0)))
    begin
      Update it
         Set it.Qtd_Pra = 0,
             it.Qtd_Dep = 0
        From dbo.PDVCB cb 
             inner Join dbo.PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
       Where cb.Cod_Estabe = @PCodEstabe
         and cb.Tip_Pedido = 'P'
         and IsNull(cb.Flg_WMS,0) = 1 
         and not Exists(Select 1 From dbo.PDVLT lt Where lt.Cod_Estabe = cb.Cod_Estabe and lt.Cod_Pedido = cb.Numero)
         and cb.Status1 = 'P'
         and cb.Status2 <> 'N'
         and IsNull(cb.Bloqueio,'') <> 'SR'
         and (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0))
    end

  -- normaliza quantidades dos estoques nos itens de pedido em PDVIT
  if Exists(Select 1
              From dbo.PDVCB cb Inner Join
                   dbo.PDVIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido
             Where cb.Cod_Estabe = @PCodEstabe
               And cb.Tip_Pedido = 'P'
               And cb.Status1 = 'P'
               And cb.Status2 <> 'N'
               And IsNull(cb.Bloqueio,'') <> 'SR'
               And (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0)))
    begin
      Update it
         Set it.Qtd_Pra = Case
                            when (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0) > IsNull(it.Qtd_Dep,0)) then
                              Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)-IsNull(it.Qtd_Dep,0)
                            else 0 
                          end
        From dbo.PDVCB cb Inner Join
             dbo.PDVIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido
       Where cb.Cod_Estabe = @PCodEstabe
         And cb.Tip_Pedido = 'P'
         And cb.Status1 = 'P'
         And cb.Status2 <> 'N'
         And IsNull(cb.Bloqueio,'') <> 'SR'
         And (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0))
    end
    
  if Exists(Select 1
              From dbo.PDVCB cb 
                   inner Join dbo.PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
             Where cb.Cod_Estabe = @PCodEstabe
               and cb.Tip_Pedido = 'P'
               and ( (IsNull(cb.Flg_WMS,0) = 0) or 
                     ( (IsNull(cb.Flg_WMS,0) = 1) and 
                       (not Exists(Select 1 From dbo.PDVLT lt Where lt.Cod_Estabe = cb.Cod_Estabe and lt.Cod_Pedido = cb.Numero) ) ))
               and cb.Status1 = 'P'
               and cb.Status2 <> 'N'
               and IsNull(cb.Bloqueio,'') <> 'SR'
               and (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0)))
    begin
      Update it
         Set it.Qtd_Dep = Case
                            when (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0) > IsNull(it.Qtd_Pra,0)) then
                              Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)-IsNull(it.Qtd_Pra,0)
                            else 0 
                          end
        From dbo.PDVCB cb inner Join 
             dbo.PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
       Where cb.Cod_Estabe = @PCodEstabe
         and cb.Tip_Pedido = 'P'
         and ( (IsNull(cb.Flg_WMS,0) = 0) or 
               ((IsNull(cb.Flg_WMS,0) = 1) and (not Exists(Select 1 From dbo.PDVLT lt Where lt.Cod_Estabe = cb.Cod_Estabe and lt.Cod_Pedido = cb.Numero))) )
         and cb.Status1 = 'P'
         and cb.Status2 <> 'N'
         and IsNull(cb.Bloqueio,'') <> 'SR'
         and (Isnull(it.Qtd_Pedido,0)+Isnull(it.Qtd_Bonificacao,0)) <> (Isnull(it.Qtd_Pra,0)+Isnull(it.Qtd_Dep,0))
    end
  
  -- normaliza quantidades dos estoques nos itens de pedido em PDVLT
  if Exists(Select 1 
              From dbo.PDVCB cb 
                   inner Join dbo.PDVLT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
             Where cb.Cod_Estabe = @PCodEstabe
               and cb.Tip_Pedido = 'P'
               and cb.Status1 = 'P'
               and cb.Status2 <> 'N'
               and cb.Status2 <> 'D'
               and IsNull(cb.Bloqueio,'') <> 'SR'
               and Isnull(it.Qtd_Lote,0) <> (Isnull(it.Qtd_LotePra,0)+Isnull(it.Qtd_LoteDep,0)))
    begin
      Update it
         Set it.Qtd_LotePra = Case
                                when (Isnull(it.Qtd_Lote,0) > IsNull(it.Qtd_LoteDep,0)) then
                                  Isnull(it.Qtd_Lote,0)-IsNull(it.Qtd_LoteDep,0)
                                else 0 
                              end
        From dbo.PDVCB cb 
             inner Join dbo.PDVLT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
       Where cb.Cod_Estabe = @PCodEstabe
         and cb.Tip_Pedido = 'P'
         and cb.Status1 = 'P'
         and cb.Status2 <> 'N'
         and cb.Status2 <> 'D'
         and IsNull(cb.Bloqueio,'') <> 'SR'
         and Isnull(it.Qtd_Lote,0) <> (Isnull(it.Qtd_LotePra,0)+Isnull(it.Qtd_LoteDep,0))
    end

  if Exists(Select 1   
              From dbo.PDVCB cb 
                   inner Join dbo.PDVLT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
             Where cb.Cod_Estabe = @PCodEstabe
               and cb.Tip_Pedido = 'P'
               and cb.Status1 = 'P'
               and cb.Status2 <> 'N'
               and cb.Status2 <> 'D'
               and IsNull(cb.Bloqueio,'') <> 'SR'
               and Isnull(it.Qtd_Lote,0) <> (Isnull(it.Qtd_LotePra,0)+Isnull(it.Qtd_LoteDep,0)))
    begin
      Update it
         Set it.Qtd_LoteDep = Case
                                when (Isnull(it.Qtd_Lote,0) > IsNull(it.Qtd_LotePra,0)) then
                                  Isnull(it.Qtd_Lote,0)-IsNull(it.Qtd_LotePra,0)
                                else 0 
                              end
        From dbo.PDVCB cb 
             inner Join dbo.PDVLT it on (cb.Cod_Estabe = it.Cod_Estabe  and cb.Numero = it.Cod_Pedido)
       Where cb.Cod_Estabe = @PCodEstabe
         and cb.Tip_Pedido = 'P'
         and cb.Status1 = 'P'
         and cb.Status2 <> 'N'
         and cb.Status2 <> 'D'
         and IsNull(cb.Bloqueio,'') <> 'SR'
         and Isnull(it.Qtd_Lote,0) <> (Isnull(it.Qtd_LotePra,0)+Isnull(it.Qtd_LoteDep,0))
    end

  Update dbo.PDVCB
     Set Flg_Calc = 0
   Where Cod_Estabe = @PCodEstabe 
     and Flg_Calc = 1


  -- zerando solicitacoes em PRLOT
  Update dbo.PRLOT
     Set Qtd_SolPra = 0,
         Qtd_SolDep = 0
   Where Cod_Estabe = @PCodEstabe    
     And ((Qtd_SolPra <> 0) or (Qtd_SolDep <> 0))
            
  -- zerando solicitacoes em PRLTL
  Update dbo.PRLTL
     Set Qtd_SolPra = 0,
         Qtd_SolDep = 0
   Where Cod_Estabe = @PCodEstabe    
     And ((Qtd_SolPra <> 0) or (Qtd_SolDep <> 0))

  
  -- atualiza solicitacoes em PRLOT (RESERVAS)
  Insert Into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Qtd_FisPra, Qtd_FisDep)
    Select r.Cod_Estabe, r.Cod_Dep, r.Cod_Produto, r.Cod_Lote, 
           sum(Isnull(r.Qtd_Movimento,0)) as Qtd_ResPra, 
           sum(Isnull(r.Qtd_ResDep,0)) as Qtd_ResDep
      From dbo.RESER r
     Where r.Cod_Estabe = @PCodEstabe     
       And not Exists(Select 1 From dbo.PRLOT l 
                       Where (r.Cod_Estabe = l.Cod_Estabe) and (r.Cod_Dep = l.Cod_Dep)
                         and (r.Cod_Produto = l.Cod_Produt) and (r.Cod_Lote = l.Cod_Lote))
     Group by r.Cod_Estabe, r.Cod_Dep, r.Cod_Produto, r.Cod_Lote
  
  Update l
     Set l.Qtd_SolPra = l.Qtd_SolPra + r.QtdResPra,
         l.Qtd_SolDep = l.Qtd_SolDep + r.QtdResDep
    From dbo.PRLOT l 
         Inner Join (Select Cod_Estabe, Cod_Dep, Cod_Produto, Cod_Lote, 
                            sum(Isnull(Qtd_Movimento,0)) as QtdResPra, 
                            sum(Isnull(Qtd_ResDep,0)) as QtdResDep
                       From dbo.RESER 
                      Where Cod_Estabe = @PCodEstabe
                      Group by Cod_Estabe, Cod_Dep, Cod_Produto, Cod_Lote) r on (l.Cod_Estabe = r.Cod_Estabe and l.Cod_Dep = r.Cod_Dep 
                                                                            and  l.Cod_Produt = r.Cod_Produto and  l.Cod_Lote = r.Cod_Lote)
   Where l.Cod_Estabe = @PCodEstabe      

  -- atualiza solicitacoes em PRLOT (AVARIAS)
  Insert Into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Qtd_FisPra, Qtd_FisDep)
    Select a.Cod_Estabe, a.Cod_Dep, a.Cod_Produto, a.Cod_Lote, 
           sum(Isnull(a.Qtd_Movimento,0)) as Qtd_AvaPra, 
           sum(Isnull(a.Qtd_AvaDep,0)) as Qtd_AvaDep
      From dbo.AVARI a
     Where a.Cod_Estabe = @PCodEstabe 
       And not Exists(Select 1 From dbo.PRLOT l 
                       Where (a.Cod_Estabe = l.Cod_Estabe) and (a.Cod_Dep = l.Cod_Dep)
                         and (a.Cod_Produto = l.Cod_Produt) and (a.Cod_Lote = l.Cod_Lote))
     Group by a.Cod_Estabe, a.Cod_Dep, a.Cod_Produto, a.Cod_Lote
  
  Update l
     Set l.Qtd_SolPra = l.Qtd_SolPra + a.QtdAvaPra,
         l.Qtd_SolDep = l.Qtd_SolDep + a.QtdAvaDep
    From dbo.PRLOT l 
         Inner Join (Select Cod_Estabe, Cod_Dep, Cod_Produto, Cod_Lote, 
                            sum(Isnull(Qtd_Movimento,0)) as QtdAvaPra, 
                            sum(Isnull(Qtd_AvaDep,0)) as QtdAvaDep
                       From dbo.AVARI 
                      Where Cod_Estabe = @PCodEstabe
                      Group by Cod_Estabe, Cod_Dep, Cod_Produto, Cod_Lote) a on (l.Cod_Estabe = a.Cod_Estabe and l.Cod_Dep = a.Cod_Dep 
					                                                        and  l.Cod_Produt = a.Cod_Produto and  l.Cod_Lote = a.Cod_Lote)
   Where l.Cod_Estabe = @PCodEstabe      

  -- atualiza solicitacoes em PRLOT (PEDIDOS)
  Declare PDVIT_Cr Cursor Local For 
    Select it.Cod_Produto, it.Cod_Lote,
           sum(Isnull(it.Qtd_Pra,0)), sum(Isnull(it.Qtd_Dep,0))
      From dbo.PDVCB cb 
           Inner Join dbo.PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
     Where cb.Cod_Estabe = @PCodEstabe
       and cb.Tip_Pedido = 'P'
       and IsNull(cb.Flg_WMS,0) = 0
       and cb.Status1 = 'P'
       and cb.Status2 <> 'N'
       and cb.Status2 <> 'D'
       and IsNull(cb.Bloqueio,'') <> 'SR'
       and (IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) > 0
     Group by it.Cod_Produto, it.Cod_Lote
    UNION ALL
    Select it.Cod_Produt, it.Cod_Lote,
           sum(Isnull(it.Qtd_Produt,0)), 0
    From dbo.ORCCB cb 
         Inner Join dbo.ORCIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Cod_Orcame = it.Cod_Orcame)
   Where cb.Cod_Estabe = @PCodEstabe
     And cb.Sta_Movime = 'F'
     and IsNull(cb.Num_Docume,0) = 0
     and it.Tip_EntSai = 'S'
     And IsNull(cb.Cod_OriVen,'') <> 'DMD'
     and (IsNull(it.Qtd_Produt,0)) > 0
   Group by it.Cod_Produt, it.Cod_Lote
   Order by Cod_Produto, Cod_Lote
  Open PDVIT_Cr
  Fetch Next From PDVIT_Cr Into @CodPrd, @CodLot, @QtdPra, @QtdDep
  While @@FETCH_STATUS = 0
    begin
      if Not Exists(Select 1 From dbo.PRLOT 
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Dep = @CodDep
                       And Cod_Produt = @CodPrd 
                       And Cod_Lote = @CodLot) 
        begin
          Set @DatVct = (Select Top 1 it.Dat_Vencim
                           from dbo.NFECB cb 
                                Inner Join dbo.NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Protocolo = it.Protocolo)
                          Where cb.Cod_Estabe = @PCodEstabe
                            And it.Cod_Produto = @CodPrd
                            And it.Cod_Lote = @CodLot
                            And cb.Status = 'F'
                          Order by it.Dat_Movimento desc)
          Insert Into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Qtd_FisPra, Qtd_FisDep)
                     Values (@PCodEstabe, @CodDep, @CodPrd, @CodLot, @DatVct, 0, 0)
        end
  
      Update dbo.PRLOT
         Set Qtd_SolPra = Qtd_SolPra + @QtdPra,
             Qtd_SolDep = Qtd_SolDep + @QtdDep
       Where Cod_Estabe = @PCodEstabe    
         And Cod_Dep = @CodDep
         And (Cod_Produt = @CodPrd) and (Cod_Lote = @CodLot)
  
      Fetch Next From PDVIT_Cr Into @CodPrd, @CodLot, @QtdPra, @QtdDep
    end
  Close PDVIT_Cr
  Deallocate PDVIT_Cr
  
  -- atualiza solicitacoes em PRLOT/PRLTL (PEDIDOS - PDVLT)
  Declare PDVLT_Cr Cursor Local For 
    Select it.Cod_Produt, it.Cod_Lote, it.Qtd_CxaFec, it.Qtd_EmbFec,
           it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, Num_Apt,
           sum(Isnull(it.Qtd_LotePra,0)),
           sum(Isnull(it.Qtd_LoteDep,0))
      From dbo.PDVCB cb 
           Inner Join dbo.PDVLT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
     Where cb.Cod_Estabe = @PCodEstabe
       and cb.Tip_Pedido = 'P'
       and IsNull(cb.Flg_WMS,0) = 1
       and cb.Status1 = 'P'
       and cb.Status2 <> 'N'
       and cb.Status2 <> 'D'
       and IsNull(cb.Bloqueio,'') <> 'SR'
       and IsNull(it.Qtd_Lote,0) > 0
     Group by it.Cod_Produt, it.Cod_Lote, it.Qtd_CxaFec, it.Qtd_EmbFec,
              it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, Num_Apt
     Order by it.Cod_Produt, it.Cod_Lote
  Open PDVLT_Cr
  Fetch Next From PDVLT_Cr Into @CodPrd, @CodLot, @QtdCxaFec, @QtdEmbFec, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdPra, @QtdDep
  While @@FETCH_STATUS = 0
    begin
      if Not Exists(Select 1 From dbo.PRLOT 
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Produt = @CodPrd 
                       And Cod_Dep = @CodDep
                       And Cod_Lote = @CodLot) 
        begin
          Set @DatVct = (Select Top 1 it.Dat_Vencim
                           from dbo.NFECB cb 
                                Inner Join dbo.NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Protocolo = it.Protocolo)
                          Where cb.Cod_Estabe = @PCodEstabe
                            And it.Cod_Produto = @CodPrd
                            And it.Cod_Lote = @CodLot
                            And cb.Status = 'F'
                          Order by it.Dat_Movimento desc)
          Insert Into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Qtd_FisPra, Qtd_FisDep)
                     Values (@PCodEstabe, @CodDep, @CodPrd, @CodLot, @DatVct, 0, 0)
        end
  
      if @QtdCxaFec = 0
        begin
          Update dbo.PRLOT
             Set Qtd_SolPra = Qtd_SolPra + @QtdPra,
                 Qtd_SolDep = Qtd_SolDep + @QtdDep
           Where Cod_Estabe = @PCodEstabe    
             And Cod_Dep = @CodDep
             And (Cod_Produt = @CodPrd) and (Cod_Lote = @CodLot)
        end
  
      if @QtdCxaFec > 0
        begin
          Set @DatVct = (Select Dat_Vencim From dbo.PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @CodDep And Cod_Produt = @CodPrd And Cod_Lote = @CodLot)
          if Not Exists(Select 1 From dbo.PRLTL 
                         Where Cod_Estabe = @PCodEstabe And Cod_Produt = @CodPrd and Cod_Lote = @CodLot
                           And Cod_Dep = @CodDep
                           And Num_Rua = @NumRua
                           And Num_Col = @NumCol
                           And Num_Niv = @NumNiv
                           And Num_Apt = @NumApt)
                           --And Qtd_EmbFec = @QtdEmbFec)
            begin
              Insert Into PRLTL(Cod_Estabe, Cod_Produt, Cod_Lote, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                                Qtd_EmbFec, Dat_Vencim, Qtd_FisPra, Qtd_FisDep)
                         Values(@PCodEstabe, @CodPrd, @CodLot, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt,
                                @QtdEmbFec, @DatVct, 0, 0)
            end
  
          Update dbo.PRLTL
             Set Qtd_SolPra = Qtd_SolPra + @QtdPra,
                 Qtd_SolDep = Qtd_SolDep + @QtdDep
           Where Cod_Estabe = @PCodEstabe    
             And Cod_Produt = @CodPrd and Cod_Lote = @CodLot
             And Cod_Dep = @CodDep
             And Num_Rua = @NumRua
             And Num_Col = @NumCol
             And Num_Niv = @NumNiv
             And Num_Apt = @NumApt
        end
  
      Fetch Next From PDVLT_Cr Into @CodPrd, @CodLot, @QtdCxaFec, @QtdEmbFec, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdPra, @QtdDep
    end
  Close PDVLT_Cr
  Deallocate PDVLT_Cr


  -- Reprocessando Transito
  Exec dbo.PR_ReprocessaTransitoProduto @PCodEstabe, 0

  
  -- corrige saldo negativo em PRLOT
  if Exists(Select 1 
              From dbo.PRLOT 
             Where Cod_Estabe = @PCodEstabe
               And ( (Qtd_Saldo < 0) or (Qtd_Fisico < 0) or 
                     (Qtd_SldPra < 0) or (Qtd_FisPra < 0) or 
                     (Qtd_SldDep < 0) or (Qtd_FisDep < 0) ))
    begin
      Update dbo.PRLOT
         Set Qtd_FisPra = Qtd_FisPra + Abs(Qtd_SldPra)
       Where Cod_Estabe = @PCodEstabe
         And Qtd_SldPra < 0
  
      Update dbo.PRLOT
         Set Qtd_FisDep = Qtd_FisDep + Abs(Qtd_SldDep)
       Where Cod_Estabe = @PCodEstabe
         And Qtd_SldDep < 0
    end

  -- corrige saldo negativo em PRLTL
  if Exists(Select Cod_Produt, Cod_Lote, Qtd_Fisico, Qtd_Solicitado, Qtd_Saldo 
              From dbo.PRLTL 
             Where Cod_Estabe = @PCodEstabe
               And ( (Qtd_Saldo < 0) or (Qtd_Fisico < 0) or 
                     (Qtd_SldPra < 0) or (Qtd_FisPra < 0) or 
                     (Qtd_SldDep < 0) or (Qtd_FisDep < 0) ))
    begin
      Update dbo.PRLTL
         Set Qtd_FisPra = Qtd_FisPra + Abs(Qtd_SldPra)
       Where Cod_Estabe = @PCodEstabe
         And Qtd_SldPra < 0
  
      Update dbo.PRLTL
         Set Qtd_FisDep = Qtd_FisDep + Abs(Qtd_SldDep)
       Where Cod_Estabe = @PCodEstabe
         And Qtd_SldDep < 0
    end


  Exec dbo.PR_CorrigeEstoqueProdut @PCodEstabe, 0


COMMIT TRANSACTION
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_EstoqueDisponivelLoteVen]
(
  @PCodEstabe int
, @PCodPrd int
, @PCodCliPagOpc int
, @PDatBas smalldatetime = null
, @PQtdMesMinPrzVctLotOpc int = null
, @PIdPolComOpc int  = null
)

RETURNS int

AS

BEGIN

Declare @QtdLotDis int

if IsNull(@PDatBas,0) = 0
  Set @PDatBas = cast(GetDate() as date)

Set @QtdLotDis = 0

Set @QtdLotDis = IsNull((Select QtdLotDis = IsNull(pk.Qtd_Saldo,0) + IsNull(dp.Qtd_Saldo,0)
                           From PRXES p Left Join

						        (Select lt.Cod_Produt, Qtd_Saldo = sum(lt.Qtd_Saldo)
                                   From (Select l1.Cod_Produt, l1.Qtd_Saldo
                                           From PRLOT l1 Inner Join
                                                PRODU pr on l1.Cod_Produt = pr.Codigo Inner Join
                                                DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and 
                                                            l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @PCodCliPagOpc Left Join
                                                (Select pl.Cod_Produt, pl.Cod_Lote
                                                   From PCXPL pl Inner Join 
                                                        POCOM pc on (pl.Id_PolCom = pc.Id_Polcom)
                                                  Where pc.Id_PolCom = @PIdPolComOpc
                                                    And dbo.FN_TransacaoAtiva(pc.Dat_Inicio, pc.Dat_Termino, @PDatBas, pc.Bloqueado) = 1) x on (l1.Cod_Produt = x.Cod_Produt 
                                                                                                                            and  l1.Cod_Lote = x.Cod_Lote) Left Join
                                                CLPRV vp on (vp.Cod_CliPag = @PCodCliPagOpc and vp.Cod_Produt = pr.Codigo) Left Join
                                                CLFBV vf on (vf.Cod_CliPag = @PCodCliPagOpc and vf.Cod_Fabric = pr.Cod_Fabricante)
                                          Where l1.Cod_Estabe = @PCodEstabe
                                            And l1.Cod_Produt = @PCodPrd
                                            And IsNull(l1.Qtd_Saldo,0) > 0 

                                            And ( (IsNull(x.Cod_Produt,0) > 0) or
                                                  ( (x.Cod_Produt is null) and 
                                                    ( (l1.Dat_Vencim is null) or 
                                                      (l1.Dat_Vencim >= Case
                                                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                          Else dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(@PQtdMesMinPrzVctLotOpc,0))
                                                                        End) ) ))  

                                          UNION ALL

                                         Select l2.Cod_Produt, l2.Qtd_Saldo
                                           From PRLOT l2 inner Join
                                                PRODU pr on l2.Cod_Produt = pr.Codigo Left Join
                                                (Select pl.Cod_Produt, pl.Cod_Lote
                                                   From PCXPL pl Inner Join 
                                                        POCOM pc on (pl.Id_PolCom = pc.Id_Polcom)
                                                  Where pc.Id_PolCom = @PIdPolComOpc
                                                    And dbo.dbo.FN_TransacaoAtiva(pc.Dat_Inicio, pc.Dat_Termino, @PDatBas, pc.Bloqueado) = 1) x on (l2.Cod_Produt = x.Cod_Produt 
                                                                                                                                               and  l2.Cod_Lote = x.Cod_Lote) Left Join
                                                CLPRV vp on (vp.Cod_CliPag = @PCodCliPagOpc and vp.Cod_Produt = pr.Codigo) Left Join
                                                CLFBV vf on (vf.Cod_CliPag = @PCodCliPagOpc and vf.Cod_Fabric = pr.Cod_Fabricante)

                                          Where l2.Cod_Estabe = @PCodEstabe 
                                            And l2.Cod_Produt = @PCodPrd

                                            And IsNull(l2.Qtd_Saldo,0) > 0 
                                            And ( (IsNull(x.Cod_Produt,0) > 0) or
                                                  ( (x.Cod_Produt is null) and 
                                                    ( (l2.Dat_Vencim is null) or 
                                                      (l2.Dat_Vencim >= Case
                                                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                          Else dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(@PQtdMesMinPrzVctLotOpc,0))
                                                                        End) ) ))  

                                            And not Exists(Select 1 From DPXGC x 
                                                            Where x.Cod_Estabe = @PCodEstabe And x.Cod_Dep = l2.Cod_Dep)) lt
                                  Group by lt.Cod_Produt) pk on p.Cod_Produt = pk.Cod_Produt Left Join

                                (Select lt.Cod_Produt, Qtd_Saldo = sum(lt.Qtd_Saldo)
                                   From (Select l1.Cod_Estabe, l1.Cod_Produt, l1.Qtd_Saldo
                                           From PRLTL l1 Inner Join
                                                PRODU pr on l1.Cod_Produt = pr.Codigo Inner Join
                                                DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep 
                                                        and de.Cod_GrpCli = @PCodCliPagOpc Left Join
                                                (Select pl.Cod_Produt, pl.Cod_Lote
                                                   From PCXPL pl Inner Join 
                                                        POCOM pc on (pl.Id_PolCom = pc.Id_Polcom)
                                                  Where pc.Id_PolCom = @PIdPolComOpc
                                                    And dbo.dbo.FN_TransacaoAtiva(pc.Dat_Inicio, pc.Dat_Termino, @PDatBas, pc.Bloqueado) = 1) x on (l1.Cod_Produt = x.Cod_Produt 
                                                                                                                                               and  l1.Cod_Lote = x.Cod_Lote) Left Join
                                                CLPRV vp on (vp.Cod_CliPag = @PCodCliPagOpc and vp.Cod_Produt = pr.Codigo) Left Join
                                                CLFBV vf on (vf.Cod_CliPag = @PCodCliPagOpc and vf.Cod_Fabric = pr.Cod_Fabricante)
                                          Where l1.Cod_Estabe = @PCodEstabe
                                            And dbo.FN_TipLocEnd(l1.Cod_Estabe, l1.Cod_Dep, l1.Num_Rua) = 'D'
                                            And l1.Cod_Produt = @PCodPrd
                                            And IsNull(l1.Qtd_Saldo,0) > 0 

                                            And ( (IsNull(x.Cod_Produt,0) > 0) or
                                                  ( (x.Cod_Produt is null) and 
                                                    ( (l1.Dat_Vencim is null) or 
                                                      (l1.Dat_Vencim >= Case
                                                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                          Else dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(@PQtdMesMinPrzVctLotOpc,0))
                                                                        End) ) ))  


                                          UNION ALL

                                         Select l2.Cod_Estabe, l2.Cod_Produt, l2.Qtd_Saldo
                                           From PRLTL l2 Inner Join
                                                PRODU pr on l2.Cod_Produt = pr.Codigo Left Join
                                                (Select pl.Cod_Produt, pl.Cod_Lote
                                                   From PCXPL pl Inner Join 
                                                        POCOM pc on (pl.Id_PolCom = pc.Id_Polcom)
                                                  Where pc.Id_PolCom = @PIdPolComOpc
                                                    And dbo.dbo.FN_TransacaoAtiva(pc.Dat_Inicio, pc.Dat_Termino, @PDatBas, pc.Bloqueado) = 1) x on (l2.Cod_Produt = x.Cod_Produt 
                                                                                                                                               and  l2.Cod_Lote = x.Cod_Lote) Left Join
                                                CLPRV vp on (vp.Cod_CliPag = @PCodCliPagOpc and vp.Cod_Produt = pr.Codigo) Left Join
                                                CLFBV vf on (vf.Cod_CliPag = @PCodCliPagOpc and vf.Cod_Fabric = pr.Cod_Fabricante)

                                          Where l2.Cod_Estabe = @PCodEstabe 
                                            And dbo.FN_TipLocEnd(l2.Cod_Estabe, l2.Cod_Dep, l2.Num_Rua) = 'D'
                                            And l2.Cod_Produt = @PCodPrd
                                            And IsNull(l2.Qtd_Saldo,0) > 0 

                                            And IsNull(l2.Qtd_Saldo,0) > 0 
                                            And ( (IsNull(x.Cod_Produt,0) > 0) or
                                                  ( (x.Cod_Produt is null) and 
                                                    ( (l2.Dat_Vencim is null) or 
                                                      (l2.Dat_Vencim >= Case
                                                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                          Else dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(@PQtdMesMinPrzVctLotOpc,0))
                                                                        End) ) ))  

                                            And not Exists (Select 1 From DPXGC x Where x.Cod_Estabe = @PCodEstabe and x.Cod_Dep = l2.Cod_Dep)) lt

							      Group by lt.Cod_Produt) dp on p.Cod_Produt = dp.Cod_Produt  

                          Where p.Cod_Estabe = @PCodEstabe 
                            And p.Cod_Produt = @PCodPrd) ,0)

-- Retorna o resultado da function
RETURN @QtdLotDis

END
GO

SET ANSI_NULLS ON  
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_IdPolComLayValido]
(
@PCodEstabe int,
@PCodLayout int,
@PCodGrupo int,
@PCodCli int
)

RETURNS int

AS

BEGIN

Declare @PIdPolCom int = 0

-- sugere a primeira politica que atende ao cliente e se for unica

if (Select count(p.Id_PolCom)
      From POCOM p 
           Inner Join (Select distinct it.Id_PolCom  -- prioridade: politica que não bloqueiam uso de outras politicas, data de cadastro mais recente
                         From LGXPC it 
                              Inner Join POCOM p on it.Id_PolCom = p.Id_PolCom 
                              Inner Join PCXES pe on it.Id_PolCom = pe.Id_PolCom and pe.Cod_Estabe = it.Cod_Estabe 
                        Where it.Cod_Estabe = @PCodEstabe
                          And it.Cod_Layout = @PCodLayout
                          And it.Cod_Grupo = @PCodGrupo
                          And dbo.FN_TransacaoAtiva(p.Dat_Inicio, p.Dat_Termino, cast(GetDate() as date), p.Bloqueado) = 1
                          And ((p.Flg_PedEle = 1) or (p.Flg_Web = 1))) x on p.Id_PolCOm = x.Id_PolCom
           Left  Join CLIEN cl on cl.Codigo = @PCodCli
           Left  Join PCXCL pc on ((p.Id_PolCom = pc.Id_PolCom) and (pc.Cod_Client = cl.Codigo)) 
           Left  Join PCXGC pg on ((p.Id_PolCom = pg.Id_PolCom) and (pg.Cod_GrpCli = cl.Cod_GrpCli)) 
           Left  Join PCXUF pu on ((p.Id_PolCom = pu.Id_PolCom) and (pu.Cod_Uf = cl.Cod_Estado)) 
     Where ((IsNull(pc.Cod_Client,0) > 0) or (IsNull(pg.Cod_GrpCli,0) > 0) or (IsNull(pu.Cod_Uf,'') <> '')) ) = 1

  Select top 1 @PIdPolCom = p.Id_PolCom
    From POCOM p 
         Inner Join (Select distinct it.Id_PolCom,  -- prioridade: politica que não bloqueiam uso de outras politicas, data de cadastro mais recente
  	                        Ordem = Case 
                                      When IsNull(p.Flg_BlqPolDifItePdv,0) = 0 Then '1' 
                                      Else '2'
                                    End,
                            p.Dat_Cadastro								 
                       From LGXPC it 
                            Inner Join POCOM p on it.Id_PolCom = p.Id_PolCom 
                            Inner Join PCXES pe on it.Id_PolCom = pe.Id_PolCom and pe.Cod_Estabe = it.Cod_Estabe 
                      Where it.Cod_Estabe = @PCodEstabe
                        And it.Cod_Layout = @PCodLayout
                        And it.Cod_Grupo = @PCodGrupo
                        And dbo.FN_TransacaoAtiva(p.Dat_Inicio, p.Dat_Termino, cast(GetDate() as date), p.Bloqueado) = 1
                        And ((p.Flg_PedEle = 1) or (p.Flg_Web = 1))) x on p.Id_PolCOm = x.Id_PolCom
  
         Left Join CLIEN cl on cl.Codigo = @PCodCli
         Left Join PCXCL pc on ((p.Id_PolCom = pc.Id_PolCom) and (pc.Cod_Client = cl.Codigo)) 
         Left Join PCXGC pg on ((p.Id_PolCom = pg.Id_PolCom) and (pg.Cod_GrpCli = cl.Cod_GrpCli)) 
         Left Join PCXUF pu on ((p.Id_PolCom = pu.Id_PolCom) and (pu.Cod_Uf = cl.Cod_Estado)) 
   Where ((IsNull(pc.Cod_Client,0) > 0) or (IsNull(pg.Cod_GrpCli,0) > 0) or (IsNull(pu.Cod_Uf,'') <> '')) 
   Order by Ordem, p.Tip_PolCom, x.Dat_Cadastro desc, p.Id_PolCom desc

-- Retorna o resultado da function
RETURN IsNull(@PIdPolCom,0)

END
GO

SET ANSI_NULLS ON  
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_IdPoliticaItem]
(
@PCodEstabe int,
@PCodLayout int,
@PCodGrpLay int,
@PCodOri varchar(1),
@PCodCli int,
@PIdPolCab int,
@PFlgPolCabInf bit,
@PCodPrd int,
@PQtdPed int,
@PDscInf numeric(18,8),
@PFlgDscInf bit,
@PFlgUsaPolLay bit,  -- utiliza somente politicas vinculadas
@PDatRef datetime    -- data do pedido, data atual
)

RETURNS int

AS

BEGIN

Set @PCodOri = Ltrim(Rtrim(@PCodOri))

Declare @PIdPolCom int,
        @pm_FlgUsaPolComPdv bit,
        @pm_FlgSugPolComIdeal bit,
        @pm_FlgSugPolComMenDsc bit

Select @pm_FlgUsaPolComPdv = IsNull(FlgUsaPolComPdv,0),
       @pm_FlgSugPolComIdeal = IsNull(FlgSugPolComIdeal,0),
       @pm_FlgSugPolComMenDsc = IsNull(FlgSugPolComMenDsc,0)
From PARAM
Where Cod_Estabe = @PCodEstabe

Set @PIdPolCom = 0

if @pm_FlgUsaPolComPdv = 1
  begin
    Set @PIdPolCom = (Select top 1 x.Id_PolCom 
                      From (Select p.Id_PolCom, p.Dat_Cadastro, s.Per_Descon, s.Ordem, s.Nivel,
                                   Prioridade1 = Case 
                                                   When (IsNull(s.Per_Descon,0) >= @PDscInf) and 
                                                        (@PIdPolCab > 0) and (p.Id_PolCom = @PIdPolCab) then '1'
                                                   When (IsNull(s.Per_Descon,0) >= @PDscInf) and (IsNull(lp.Id_PolCom,0) > 0) then '2'
                                                   When (IsNull(s.Per_Descon,0) >= @PDscInf) then '3'
                                                   --demais poiiticas
                                                   Else '4' 
                                                 End
                            From POCOM p 
                                 Inner Join PCXES pe on ((p.Id_PolCom = pe.Id_PolCom) and (pe.Cod_Estabe = @PCodEstabe))
                                 Left  Join dbo.FN_ViewPoliticasProduto(@PIdPolCab, @PCodPrd, @PDatRef) s on (p.Id_PolCom = s.Id_PolCom) 
                                 Left  Join LGXPC lp on (lp.Cod_Estabe = @PCodEstabe and lp.Cod_Layout = @PCodLayout and lp.Cod_Grupo = @PCodGrpLay and lp.Id_PolCom = p.Id_PolCom)
                                 Left  Join CLIEN cl on cl.Codigo = @PCodCli
                                 Left  Join PCXCL pc on ((p.Id_PolCom = pc.Id_PolCom) and (pc.Cod_Client = cl.Codigo)) 
                                 Left  Join PCXGC pg on ((p.Id_PolCom = pg.Id_PolCom) and (pg.Cod_GrpCli = cl.Cod_GrpCli)) 
                                 Left  Join PCXUF pu on ((p.Id_PolCom = pu.Id_PolCom) and (pu.Cod_Uf = cl.Cod_Estado)) 
                            
                            Where IsNull(p.Tip_PolCom,'') <> 'KIT'
                            And dbo.FN_TransacaoAtiva(p.Dat_Inicio, p.Dat_Termino, @PDatRef, p.Bloqueado) = 1

                            And ( (@PCodOri = '') or
                                  ((@PCodOri = 'M') And (IsNull(p.Flg_Cfv,0) = 1)) or  -- movel - força de vendas 
                                  (((@PCodOri = 'T') or (@PCodOri = 'W')) And ((IsNull(p.Flg_PedEle,0) = 1) or (IsNull(p.Flg_Web,0) = 1))) or  -- E-commerce / internet
                                  ((@PCodOri <> '') and (CharIndex(@PCodOri,';M;T;W;') = 0) And (IsNull(p.Flg_Televendas,0) = 1)) ) 
                            And IsNull(s.Ordem,0) > 0 
                            And dbo.FN_PoliticaProdutoValida(@PCodEstabe, @PCodOri, p.Id_PolCom, @PCodPrd) = 1
                            
                            -- filtrar politicas validas para o cliente e produto vinculadas ao layout
                            And ((@PFlgUsaPolLay = 1) and (IsNull(lp.Id_PolCom,0) > 0) or (@PFlgUsaPolLay = 0))
                            And ((pc.Cod_Client > 0) or (pg.Cod_GrpCli > 0) or (pu.Cod_Uf <> ''))
                            
                            -- filtrar politicas que atendem o desconto, quando for o caso
                            And (((@PFlgDscInf = 0) and (s.Per_DesCon >= 0)) or 
                                 ((@PFlgDscInf = 1) and (s.Per_DesCon > = @PDscInf))) 
							And (@PQtdPed >= S.Qtd_Minimo)) x
                        
                      --Order by Prioridade1, Nivel, Ordem, Dat_Cadastro Desc, Id_PolCom desc )
                      Order by 
                        -- pedido eletronico
                        Case When (@PCodLayout > 0) then Prioridade1 End,
                        Case When (@PCodLayout > 0) then Nivel End,
                        Case When (@PCodLayout > 0) then Ordem End,
                        Case When (@PCodLayout > 0) then Dat_Cadastro End Desc,
                        Case When (@PCodLayout > 0) then Id_PolCom End Desc,
                     
                        -- Menor desconto
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Per_Descon End,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Prioridade1 End,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Nivel End,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Ordem End,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Dat_Cadastro End Desc,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Id_PolCom End desc,
                     
                        -- Maior desconto
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Per_Descon End Desc,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Prioridade1 End,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Nivel End,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Ordem End,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Dat_Cadastro End Desc,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Id_PolCom End desc)

    ------------------------------------------------------------------------------------------------------------------------------------------

    if (IsNull(@PIdPolCom,0) = 0) and (@PDscInf > 0)
      begin
        Set @PDscInf = 0

        Set @PIdPolCom = (Select top 1 x.Id_PolCom 
                          From (Select p.Id_PolCom, p.Dat_Cadastro, s.Per_Descon, s.Ordem, s.Nivel,
                                       Prioridade1 = Case 
                                                       When (IsNull(s.Per_Descon,0) >= @PDscInf) and 
                                                            (@PIdPolCab > 0) and (p.Id_PolCom = @PIdPolCab) then '1'
                                                       When (IsNull(s.Per_Descon,0) >= @PDscInf) and (IsNull(lp.Id_PolCom,0) > 0) then '2'
                                                       When (IsNull(s.Per_Descon,0) >= @PDscInf) then '3'
                                                       --demais poiiticas
                                                       Else '4' 
                                                     End
                                From POCOM p 
                                     Inner Join PCXES pe on ((p.Id_PolCom = pe.Id_PolCom) and (pe.Cod_Estabe = @PCodEstabe))
                                     Left  Join dbo.FN_ViewPoliticasProduto(@PIdPolCab, @PCodPrd, @PDatRef) s on (p.Id_PolCom = s.Id_PolCom) 
                                     Left  Join LGXPC lp on (lp.Cod_Estabe = @PCodEstabe and lp.Cod_Layout = @PCodLayout and lp.Cod_Grupo = @PCodGrpLay and lp.Id_PolCom = p.Id_PolCom)
                                     Left  Join CLIEN cl on cl.Codigo = @PCodCli
                                     Left  Join PCXCL pc on ((p.Id_PolCom = pc.Id_PolCom) and (pc.Cod_Client = cl.Codigo)) 
                                     Left  Join PCXGC pg on ((p.Id_PolCom = pg.Id_PolCom) and (pg.Cod_GrpCli = cl.Cod_GrpCli)) 
                                     Left  Join PCXUF pu on ((p.Id_PolCom = pu.Id_PolCom) and (pu.Cod_Uf = cl.Cod_Estado)) 
                                
                                Where IsNull(p.Tip_PolCom,'') <> 'KIT'
                                And dbo.FN_TransacaoAtiva(p.Dat_Inicio, p.Dat_Termino, @PDatRef, p.Bloqueado) = 1

                                And ( (@PCodOri = '') or
                                      ((@PCodOri = 'M') And (IsNull(p.Flg_Cfv,0) = 1)) or  -- movel - força de vendas 
                                      (((@PCodOri = 'T') or (@PCodOri = 'W')) And ((IsNull(p.Flg_PedEle,0) = 1) or (IsNull(p.Flg_Web,0) = 1))) or  -- E-commerce / internet
                                      ((@PCodOri <> '') and (CharIndex(@PCodOri,';M;T;W;') = 0) And (IsNull(p.Flg_Televendas,0) = 1)) ) 

                                And IsNull(s.Ordem,0) > 0 
                                And dbo.FN_PoliticaProdutoValida(@PCodEstabe, @PCodOri, p.Id_PolCom, @PCodPrd) = 1
                                
                                -- filtrar politicas validas para o cliente e produto vinculadas ao layout
                                And ((@PFlgUsaPolLay = 1) and (IsNull(lp.Id_PolCom,0) > 0) or (@PFlgUsaPolLay = 0))
                                And ((pc.Cod_Client > 0) or (pg.Cod_GrpCli > 0) or (pu.Cod_Uf <> ''))
                                
                                -- filtrar politicas que atendem o desconto, quando for o caso
                                And (((@PFlgDscInf = 0) and (s.Per_DesCon >= 0)) or 
                                     ((@PFlgDscInf = 1) and (s.Per_DesCon > = @PDscInf))) 
								And (@PQtdPed >= S.Qtd_Minimo)) x
                            
                          --Order by Prioridade1, Nivel, Ordem, Dat_Cadastro Desc, Id_PolCom desc )
                          Order by 
                            -- pedido eletronico
                            Case When (@PCodLayout > 0) then Prioridade1 End,
                            Case When (@PCodLayout > 0) then Nivel End,
                            Case When (@PCodLayout > 0) then Ordem End,
                            Case When (@PCodLayout > 0) then Dat_Cadastro End Desc,
                            Case When (@PCodLayout > 0) then Id_PolCom End Desc,
                         
                            -- Menor desconto
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Per_Descon End,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Prioridade1 End,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Nivel End,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Ordem End,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Dat_Cadastro End Desc,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Id_PolCom End desc,
                         
                            -- Maior desconto
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Per_Descon End Desc,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Prioridade1 End,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Nivel End,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Ordem End,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Dat_Cadastro End Desc,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Id_PolCom End desc)
       
      end

  end  -- if @pm_FlgUsaPolComPdv = 1

-- Retorna o resultado da function
RETURN IsNull(@PIdPolCom,0)

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_QtdLoteDisponivel]
(
  @PCodEstabe int,
  @PCodCliPag int,
  @PCodPrd int,
  @PDatBas smalldatetime,
  @PQtdMesMinPrzVctLot int,
  @PIdPolCom int
)
RETURNS int

AS

BEGIN

Declare @QtdLotDis int,
        @QtdPck int,
		@QtdDep int

if IsNull(@PDatBas,0) = 0
  Set @PDatBas = cast(GetDate() as date)

Set @QtdLotDis = 0

-- total disponivel no picking
Set @QtdPck = IsNull((Select sum(IsNull(lt.Qtd_Saldo,0))
                        From PRLOT lt Inner Join 
                             PRODU pr on (lt.Cod_Produt = pr.Codigo) Left Join
                             (Select pl.Cod_Produt, pl.Cod_Lote
                                From PCXPL pl Inner Join 
                                     POCOM pc on (pl.Id_PolCom = pc.Id_Polcom)
                               Where pc.Id_PolCom = @PIdPolCom
                                 And dbo.FN_TransacaoAtiva(pc.Dat_Inicio, pc.Dat_Termino, @PDatBas, pc.Bloqueado) = 1) x on (lt.Cod_Produt = x.Cod_Produt and lt.Cod_Lote = x.Cod_Lote) Left Join
                             CLPRV vp on (vp.Cod_CliPag = @PCodCliPag and vp.Cod_Produt = pr.Codigo) Left Join
                             CLFBV vf on (vf.Cod_CliPag = @PCodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante)
                       Where lt.Cod_Estabe = @PCodEstabe
                         And lt.Cod_Produt = @PCodPrd
                         And lt.Qtd_Saldo > 0
                         And ( (IsNull(x.Cod_Produt,0) > 0) or
                               ( (x.Cod_Produt is null) and 
                                 ( (lt.Dat_Vencim is null) or 
                                   (lt.Dat_Vencim >= Case
                                                       When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                       When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                       Else dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(@PQtdMesMinPrzVctLot,0))
                                                     End) ) ) ) ) ,0)
            
Set @QtdDep = IsNull((Select sum(IsNull(lt.Qtd_Saldo,0))
                        From PRLTL lt Inner Join 
                             PRODU pr on (lt.Cod_Produt = pr.Codigo) Left Join
                             (Select pl.Cod_Produt, pl.Cod_Lote
                                From PCXPL pl Inner Join 
                                     POCOM pc on (pl.Id_PolCom = pc.Id_Polcom)
                               Where pc.Id_PolCom = @PIdPolCom
                                 And dbo.FN_TransacaoAtiva(pc.Dat_Inicio, pc.Dat_Termino, @PDatBas, pc.Bloqueado) = 1) x on (lt.Cod_Produt = x.Cod_Produt and lt.Cod_Lote = x.Cod_Lote) Left Join
                             CLPRV vp on (vp.Cod_CliPag = @PCodCliPag and vp.Cod_Produt = pr.Codigo) Left Join
                             CLFBV vf on (vf.Cod_CliPag = @PCodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante)
                       Where lt.Cod_Estabe = @PCodEstabe 
                         And lt.Cod_Produt = @PCodPrd
                         And lt.Qtd_Saldo > 0
                         And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                         And ( (IsNull(x.Cod_Produt,0) > 0) or
                               ( (x.Cod_Produt is null) and 
                                 ( (lt.Dat_Vencim is null) or 
                                   (lt.Dat_Vencim >= Case
                                                       When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                       When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                       Else dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(@PQtdMesMinPrzVctLot,0))
                                                     End) ) ) ) ) ,0)

Set @QtdLotDis = @QtdPck + @QtdDep

-- Retorna o resultado da function
RETURN @QtdLotDis

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ValidaPolitica]
@PCodEstabe int,  
@PDatPed datetime,      
@PCodPolCom varchar(25) output,
@PIdPolCom int output,
@PCodRej varchar(3) output,
@PDesRej varchar(60) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now datetime,
        @Date datetime

Set @Now = GetDate()
Set @Date = cast(GetDate() as date)

if IsNull(@PDatPed,0) = 0
  Set @PDatPed = @Date
else
  Set @PDatPed = cast(@PDatPed as date)

Set @PCodPolCom = Ltrim(Rtrim(@PCodPolCom))
Set @PCodRej = ''
Set @PDesRej = ''

if IsNull(@PIdPolCom,0) = 0 Set @PIdPolCom = 0

Declare @pc_IdPolCom int, 
        @pc_CodPolCom varchar(25)

if (@PIdPolCom > 0) or (@PCodPolCom <> '')
  begin

    Set @pc_IdPolCom = 0
    Set @pc_CodPolCom = ''

    if (@PIdPolCom > 0) and 
       (Exists(Select 1 From POCOM Where Id_PolCom = @PIdPolCom))
      Set @pc_CodPolCom = IsNull((Select Cod_PolCom From POCOM Where Id_PolCom = @PIdPolCom),'')

    if (@PCodPolCom <> '') and
      (Exists(Select 1 From POCOM Where Cod_PolCom = @PCodPolCom))
      Set @pc_IdPolCom = IsNull((Select top 1 pc.Id_PolCom 
                                   From (Select Id_PolCom, Dat_Termino,
                                                Ordem = Case 
                                                          When dbo.FN_TransacaoAtiva(Dat_Inicio, Dat_Termino, @PDatPed, Bloqueado) = 1 then '1'
                                                          Else '2'
                                                        End
                                           From POCOM
                                          Where Cod_PolCom = @PCodPolCom) pc
                                  Order by pc.Ordem, pc.Dat_Termino Desc),0)  -- não permitir duplicar Cod_PolCom

    if ((@PIdPolCom > 0) and (@pc_CodPolCom = '')) or
       ((@PCodPolCom <> '') and (@pc_IdPolCom = 0))
      begin
        Set @PCodRej = 'PCX'
        Set @PDesRej = 'Politica Comercializacao Invalida'
      end

    if @PDesRej = ''
      begin
        Set @pc_IdPolCom = 0
        Set @pc_CodPolCom = ''

        if @PIdPolCom > 0
          begin
            Set @pc_CodPolCom = IsNull((Select Cod_PolCom From POCOM Where Id_PolCom = @PIdPolCom),'')
            if @PCodPolCom = ''
			  begin
                Set @PCodPolCom = @pc_CodPolCom
                Set @pc_IdPolCom = @PIdPolCom
              end
          end

        if @PCodPolCom <> ''
          begin
            Set @pc_IdPolCom = IsNull((Select top 1 pc.Id_PolCom 
                                         From (Select Id_PolCom, Dat_Termino,
                                                      Ordem = Case 
                                                                When dbo.FN_TransacaoAtiva(Dat_Inicio, Dat_Termino, @PDatPed, Bloqueado) = 1 then '1'
                                                                Else '2'
                                                              End
                                                 From POCOM
                                                Where Cod_PolCom = @PCodPolCom) pc
                                        Order by pc.Ordem, pc.Dat_Termino Desc),0)  -- não permitir duplicar Cod_PolCom
            if @PIdPolCom = 0
              begin
                Set @PIdPolCom = @pc_IdPolCom
                Set @pc_CodPolCom = @PCodPolCom
              end
          end

        if (@PIdPolCom <> @pc_IdPolCom) or (@PCodPolCom <> @pc_CodPolCom)
          begin
            Set @PCodRej = 'CAD'
	        Set @PDesRej = 'Inconsistentes'
          end
      end

    -- validade da politica
    if (@PIdPolCom > 0) and (@PCodRej = '')
      begin
        if not Exists(Select 1 From PCXES Where Cod_Estabe = @PCodEstabe and Id_PolCom = @PIdPolCom)
          begin
            Set @PCodRej = 'PCX'
            Set @PDesRej = 'Politica Comercializacao Invalida'
          end
        else
	    if IsNull((Select Bloqueado From POCOM Where Id_PolCom = @PIdPolCom),0) = 1
          begin
            Set @PCodRej = 'PCB'
            Set @PDesRej = 'Politica Comercializacao Bloqueada'
          end
        else
        if not exists(Select 1 From POCOM 
                       Where Id_PolCom = @PIdPolCom 
                         And dbo.FN_TransacaoAtiva(Dat_Inicio, Dat_Termino, @PDatPed, Bloqueado) = 1)
          begin
            Set @PCodRej = 'PCV'
            Set @PDesRej = 'Politica Comercializacao Vencida'
          end
      end

  end -- if (@PCodPolCom <> '') or (@PIdPolCom > 0) 

GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ExcluiCancelaNFSCB]
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int,
@PCodMve int,
@PNomUsu varchar(15),
@PFlgCanPdv bit

AS

SET NOCOUNT ON
SET ANSI_WARNINGS OFF

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Declare @cb_FlgWms bit,
        @cb_StaNot varchar(1),
        @cb_TipNot varchar(1),
        @cb_CodCfo int,
        @cb_DatEmi smalldatetime,
        @cb_MovEst bit,
        @cb_CodCli int,
        @cb_CodVdr int,
        @cb_CodOpe int,
        @cb_CodSup int,
        @cb_CodPdv int,
        @cb_SubFat int,
        @cb_ValDebVrbVdr numeric(18,4),
        @cb_ValNot numeric(18,4),
        @cb_CodFun int,
        @cb_CodFor int,
        @cb_CodCtr int,
        @cb_IdConsig int,
        @cb_NumSeqCtr int, 
        @cb_StaIntWms varchar(1),
        @cb_Usuario varchar(15),
        @cr_CodDoc int,
        @pm_FlgIntWms bit = 0,
    @FlgPodeCancelar bit,
        @va_IsnCtaFinDeb int,
        @va_IsnCtaFinCre int,
        @va_DatMovime smalldatetime,
        @va_NumSequen int,     
        @pm_FlgUsaInterv bit,
        @WMsg varchar(128),
        @WFlgErr bit,
        @WQtdEmbFec int,
        @WCodDepCan smallint,
        @WNumRuaCan smallint,
        @WNumCol smallint,
        @WNumNiv smallint,
        @WNumApt smallint,
        @WDatVct smalldatetime,
        @WDatFab smalldatetime,
        @WTipDes varchar(3),
        @WCodDes int,
        @WCodDoc int,
        @CodTipSaiCng varchar(3) = '',
    @pc_CtlSld varchar(1)

-- Validacao login usuario infarma  
if (@PNomUsu='' or @PNomUsu='SISTEMA')
  set @PNomUsu = dbo.FN_UsuarioInfarma()

-- coloca campos na memoria
Select @pm_FlgUsaInterv = IsNull(FlgUsaInterv,0)
  From PMFIN

Select @pm_FlgIntWms = IsNull(FlgIntegrWmsExt,0) 
  From PMEST Where Cod_Estabe = @PCodEstabe

Select @cb_FlgWms = IsNull(cb.Flg_Wms,0),
       @cb_StaIntWms = IsNull(cb.Sta_IntWms,''),          
       @cb_StaNot = cb.Status,
       @cb_TipNot = cb.Tip_Saida,
       @cb_CodCfo = Isnull(cb.Cod_Cfo1,0),
       @cb_DatEmi = cb.Dat_Emissao,
       @cb_MovEst = IsNull(cb.Flg_MovEst,0),
       @cb_CodCli = IsNull(cb.Cod_Cliente,0),
       @cb_CodFun = IsNull(cb.Cod_Funcionario,0),
       @cb_CodFor = IsNull(cb.Cod_Fornecedor,0),
       @cb_CodVdr = cb.Cod_Vendedor,
       @cb_CodOpe = IsNull(cb.Cod_VendTlmkt, 0),
       @cb_CodSup = cb.Cod_Supervisor,
       @cb_CodPdv = cb.Cod_Pedido,
       @cb_SubFat = cb.Num_NotSubFat,
       @cb_ValDebVrbVdr = IsNull(cb.Vlr_DebVrbVdr,0),
       @cb_ValNot = IsNull(cb.Vlr_TotalNota,0),
       @cb_CodCtr = IsNull(cb.Cod_Contrato,0),
       @cb_IdConsig = IsNull(cb.Id_Consig,0),
       @cb_NumSeqCtr = IsNull(cb.Num_SequenciaCtr,0), 
       @cb_Usuario = cb.Usuario,
     @pc_CtlSld = pc.Controle_Saldo
  From NFSCB cb
       Left Join POCOM pc on pc.Id_PolCom = cb.Id_PolCom
 Where cb.Cod_Estabe = @PCodEstabe and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot

if @cb_StaNot = 'C'
  RAISERROR('Nota já cancelada',16,1)
else
if (@cb_FlgWms = 1) and 
   not Exists(Select 1
                From TBZON z 
                     inner join PMEST p on z.Cod_Estabe = p.Cod_Estabe and z.Cod_Zon = p.CodZonCan 
               Where z.Cod_Estabe = @PCodEstabe
                 And dbo.FN_TipLocEnd(z.Cod_Estabe, z.Cod_Dep, z.Num_RuaIni) = 'X'
                 And z.Cod_Dep > 0 And z.Num_RuaIni > 0)
  RAISERROR('Zona de Quarentena(cancelamentos) não configurada ou inválida',16,1)
else

BEGIN
  BEGIN TRANSACTION

  Set @FlgPodeCancelar = 0

  if (@cb_FlgWms = 0) or (@cb_MovEst = 0)
    Set @FlgPodeCancelar = 1
  else
  if (@pm_FlgIntWms = 0) and (@cb_StaIntWms = '')
    Set @FlgPodeCancelar = 1
  else
  if @pm_FlgIntWms = 1
    begin
      if @cb_StaIntWms = '4'
        begin
          Set @FlgPodeCancelar = 1
          Set @PFlgCanPdv = (Select IsNull(Flg_CanPdv,0) From NFSCB
                              Where Cod_Estabe = @PCodEstabe 
                                And Ser_Nota = @PSerNot
                                And Num_Nota = @PNumNot)
        end
      else
        begin
          Update NFSCB
             Set Sta_IntWMS = '3'
           Where Cod_Estabe = @PCodEstabe 
             And Ser_Nota = @PSerNot
             And Num_Nota = @PNumNot
             And IsNull(Sta_IntWMS,'') = ''

          Update NFSCB
             Set Flg_CanPdv = @PFlgCanPdv,
           Usuario = @PNomUsu
           Where Cod_Estabe = @PCodEstabe 
             And Ser_Nota = @PSerNot
             And Num_Nota = @PNumNot

          Exec PR_WMSGerarXMLEntradaCanNFS @PCodEstabe, @PSerNot, @PNumNot

        end
    end

  if @FlgPodeCancelar = 1
    begin
              
      if (@cb_StaNot = 'A') and (@cb_TipNot <> 'V')
        begin
          -- exclui os itens
          Delete from NFSIT 
           Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot

          -- exclui as duplicatas
          Delete from CTREC
           Where Cod_Estabe = @PCodEstabe
             And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot

          -- se a nota tiver sido a ultima, exclui, senao cancela
          if @PSerNot = 'XXX'
            begin
              Delete from NFSCB
               Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
            end
          else
          if (Select Nota_Fiscal_M1 from NMFIS Where Cod_Estabe = @PCodEstabe) = @PNumNot
            begin
              Update NMFIS
                 Set Nota_Fiscal_M1 = @PNumNot - 1
               Where Cod_Estabe = @PCodEstabe
              
              Delete from NFSCB
               Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
            end
          else
            begin
              Update NFSCB
                 Set Status = 'C',
                     Dat_Cancelamento = @Date,
                     Flg_CanPdv = @PFlgCanPdv,
                     Usuario = @PNomUsu,
                     Transacao = GetDate()
               Where Cod_Estabe = @PCodEstabe 
                 and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
            end
        end
      else
      if (@cb_StaNot = 'F') and (@cb_MovEst = 0)
        begin
          -- cancela titulos
          Exec PR_CancelaDevolveTitulosCTREC @PCodEstabe, @PSerNot, @PNumNot, @PNomUsu, 'C', 0, 0
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end

          -- cancela o cabeçalho
          Update NFSCB
             Set Status = 'C',
                 Dat_Cancelamento = @Date,
                 Flg_CanPdv = @PFlgCanPdv,
                 Usuario = @PNomUsu,
                 Transacao = GetDate()
           Where Cod_Estabe = @PCodEstabe 
             and Ser_Nota = @PSerNot and Num_Nota = @PNumNot

          -- transfere saldos de PRSLD
          EXEC PR_TransfEstNFS @PCodEstabe, @PSerNot, @PNumNot
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end

          -- se for o caso cancela os desc. sub.fat na Nf origem (ORC)
          if (@PSerNot <> 'ORC') and (@cb_SubFat > 0)
            begin
              Declare CTREC_Cr Cursor Local Fast_Forward For 
                Select Cod_Documento
                  From CTREC
                 Where Cod_Estabe = @PCodEstabe
                   And Ser_NfOrigem = 'ORC' and Num_NfOrigem = @cb_SubFat
                  
              Open CTREC_Cr
              Fetch Next From CTREC_Cr
                Into @cr_CodDoc
              While @@FETCH_STATUS = 0
                begin
                  Update CTREC
                     Set Vlr_DscSubFat = 0
                   Where Cod_Estabe = @PCodEstabe
                     And Cod_Documento = @cr_CodDoc

                  -- atualiza saldo contas a receber
                  EXEC PR_AtualizaCtrec @PCodEstabe, @cr_CodDoc,0
                  if @@error <> 0
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end

                  Fetch Next From CTREC_Cr
                    Into @cr_CodDoc
                end
              Close CTREC_Cr
              Deallocate CTREC_Cr
            end
        end
      else
      if @Cb_StaNot = 'F' and @Cb_MovEst = 1
        if not Exists(Select Codigo from TPMVE Where Codigo = @PCodMve)
          begin
            Set @WMsg = 'O código para o Tipo de Movimento "'+Cast(@PCodMve as varchar(2))+
                                    '-Entrada por Cancelamento de NF" não foi '+
                                    'cadastrado em Tipos de Movimentação de Estoque'
            RAISERROR(@WMsg,16,1)
          end
        else
          begin
            Declare @it_CodPrd int,
                    @it_CodLot varchar(20),
                    @it_SeqIte int,
                    @it_TipSai varchar(1),
                    @it_QtdPrd int,
                    @it_QtdBon int,
                    @it_PrcUni numeric(18,8),
                    @it_QtdPra int,
                    @it_QtdDep int,
                    @it_VlrVrbPolVdr numeric(18,4),
          @it_VlrVrbPolOpe numeric(18,4),
                    @it_VlrVrbPolSup numeric(18,4),
                    @it_VlrVrbPar numeric(18,4),
                    @it_VlrVrbBon numeric(18,4),
                    @it_IdPolCom int,
                    @it_PrcFab numeric(18,4), 
                    @it_PrcUniPde numeric(18,4), 
                    @it_PerDscPde numeric(18,4),
                    @it_CodCfo int,
          @it_CodFab int,

                    @WCodOri varchar(20),
                    @WQtdMov int,
                    @WDatCan smalldatetime,
                    @WCodAcr int,
                    @WDesHst varchar(40),
                    @WQtdItePdv int,
                    @WQtdIteNfs int,
                    @WDivItens int,
                    @WFlgReaPdvOk bit,
                    @WQtdPra int ,
                    @WQtdDep int,
                    @WValMov numeric(18,4),
                    @WCodFor int,
                    @WValEdi numeric(18,4),
                    @WValBru numeric(18,4),
                    
                    @WNumRuaPck smallint,
                    @WNumColPck smallint,
                    @WNumNivPck smallint,
                    @WNumAptPck smallint

            -- pega depósito/rua da zona de quarentena(cancelamento)
            Select top 1 
                   @WCodDepCan = z.Cod_Dep, 
                   @WNumRuaCan = z.Num_RuaIni 
              From TBZON z 
                   inner join PMEST p on z.Cod_Estabe = p.Cod_Estabe and z.Cod_Zon = p.CodZonCan 
             Where z.Cod_Estabe = @PCodEstabe
               And dbo.FN_TipLocEnd(z.Cod_Estabe, z.Cod_Dep, z.Num_RuaIni) = 'X'

            -- se nao for cancelar pedido ver se esta ok pdv x nfs
            Set @WFlgReaPdvOk = 0
            if @PFlgCanPdv = 0
              begin
                Set @WQtdItePdv = IsNull((Select count(*) from PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @cb_CodPdv and Qtd_Pedido > 0),0)
                Set @WQtdIteNfs = IsNull((Select count(*) from NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot),0)

                -- O mesmo produto pode ser dividido em lotes diferentes na nota
        Select @WDivItens = Count(1) 
                  From (Select Cod_Produto,Sum(Qtd_Pedido) as Qtd 
                          From PDVIT 
                         Where Cod_Estabe = @PCodEstabe 
                           And Cod_Pedido = @cb_CodPdv and Qtd_Pedido > 0
                         Group By Cod_Produto) p Full Join 
                       (Select Cod_Produto,Sum(Qtd_Produto) as Qtd 
                          From NFSIT 
                         Where Cod_Estabe = @PCodEstabe 
                           And Ser_Nota = @PSerNot and Num_Nota = @PNumNot
                         Group By Cod_Produto) n On p.Cod_Produto = n.Cod_Produto
         Where IsNull(p.Qtd,0) <> IsNull(n.Qtd,0)
        
                if (@WDivItens = 0) and (@WQtdItePdv > 0) and (@WQtdIteNfs > 0)
                  Set @WFlgReaPdvOk = 1
                else
                  begin
                    Set @WMsg = 'Divergencia entre itens do pedido e da nota. Pedido deve ser cancelado'
                    RAISERROR(@WMsg,16,1)
                  end
              end

            Update NFSCB
               Set Status = 'C',
                   Dat_Cancelamento = @Date,
                   Flg_CanPdv = @PFlgCanPdv,
                   Usuario = @PNomUsu,
                   Transacao = GetDate()
             Where Cod_Estabe = @PCodEstabe 
               and Ser_Nota = @PSerNot and Num_Nota = @PNumNot

            Set @WFlgErr = 0
            Set @WDatCan = @Date
            Set @WDesHst = 'CANCELAMENTO NF '+@PSerNot+' '+cast(@PNumNot as varchar)

            Declare NFSIT_Cr Cursor Local Fast_Forward For 
              Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, it.Qtd_Produto, it.Qtd_Bonificacao, it.Prc_Unitario,
                     IsNull(it.Cod_Cfo,0), IsNull(it.Prc_Fabric,0), IsNull(it.Prc_UniPde,0), IsNull(it.Per_DscPde,0), 
                     IsNull(it.Qtd_Pra,0), IsNull(it.Qtd_Dep,0), IsNull(it.Vlr_Verba,0), IsNull(it.Vlr_VrbOpe,0), IsNull(it.Vlr_VrbSup,0), IsNull(it.Vlr_VrbPar,0), 
                     IsNull(it.Vlr_VrbBon,0), IsNull(it.Id_PolCom,0), pr.Cod_Fabricante
                From NFSIT it 
                     Inner Join NFSCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota and it.Num_Nota = cb.Num_Nota
                     Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
               Where cb.Cod_Estabe = @PCodEstabe and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot and cb.Flg_MovEst = 1

            Open NFSIT_Cr
            Fetch Next From NFSIT_Cr
              Into @it_CodPrd, @it_CodLot, @it_SeqIte, @it_QtdPrd, @it_QtdBon, @it_PrcUni,
                   @it_CodCfo, @it_PrcFab, @it_PrcUniPde, @it_PerDscPde,  
                   @it_QtdPra, @it_QtdDep, @it_VlrVrbPolVdr, @it_VlrVrbPolOpe, @it_VlrVrbPolSup, @it_VlrVrbPar, 
                   @it_VlrVrbBon, @it_IdPolCom, @it_CodFab 

            While (@@FETCH_STATUS = 0) and (@WFlgErr = 0)
              begin
                if (@it_QtdPra+@it_QtdDep) <> (@it_QtdPrd+@it_QtdBon)
                  Set @it_QtdPra = @it_QtdPrd + @it_QtdBon - @it_QtdDep

                Set @WNumCol = 0
                Set @WNumNiv = 0
                Set @WNumApt = 0
                Set @WDatVct = null
                Set @WDatFab = null
                Set @WQtdEmbFec = 1

                -- pega o vencimento do lote
                Select @WDatVct = Dat_Vencim, 
                       @WDatFab = Dat_Fabric 
                  From PRLOT 
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Dep = @WCodDepCan
                   And Cod_Produt = @it_CodPrd 
                   and Cod_Lote = @it_CodLot

                if @WDatVct is null
                  Set @WDatVct = (Select top 1 Dat_Vencim From PRLTL Where Cod_Estabe = @PCodEstabe and Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot And Cod_Dep = @WCodDepCan)
                if @WDatFab is null
                  Set @WDatFab = (Select top 1 Dat_Fabric From PRLTL Where Cod_Estabe = @PCodEstabe and Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot And Cod_Dep = @WCodDepCan)

                -- verifica e ajusta se for emprestimo de estoque
                if (@cb_CodCfo > 0) and (@it_QtdDep > 0)
                  Set @it_QtdDep = @it_QtdDep * (-1) 
                if (@cb_CodCfo = 0) and (@it_QtdPra > 0)
                  Set @it_QtdPra = @it_QtdPra * (-1) 

                -- gera um acerto. o saldo é atualizado pela trigger
                Set @WNumRuaPck = 0
                Set @WNumColPck = 0
                Set @WNumNivPck = 0
                Set @WNumAptPck = 0
                
                Select @WNumRuaPck = Num_Rua, 
                       @WNumColPck = Num_Col, 
                       @WNumNivPck = Num_Niv, 
                       @WNumAptPck = Num_Apt 
                  From DPXPR 
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Dep = @WCodDepCan
                   And Cod_Produt = @it_CodPrd

                Exec PR_ProxNumero 'Acerto', @WCodAcr output
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
                  
                Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, 
                                   Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric,
                                   Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                                   Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Cod_OriMov, Historico, Usuario, Transacao)
                            Values(@PCodEstabe, @WCodAcr, @WDatCan,
                                   @it_CodPrd, @it_CodLot, @WDatVct, @WDatFab, 
                                   @WCodDepCan, @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck,
                                   @it_QtdPra, @it_QtdDep, @PCodMve, 'NF', @WDesHst,  @PNomUsu, GetDate())
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end

                -- se WMS transfere para Zona de cancelamentos se não estiver integrado
                if (@cb_FlgWms = 1) and (@pm_FlgIntWms = 0)
                  begin
                    -- se nao existir o lote, cria
                    if (Select Count(*) From PRLTL 
                         Where Cod_Estabe = @PCodEstabe 
                           and Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot
                           and Cod_Dep = @WCodDepCan and Num_Rua = @WNumRuaCan 
                           and Num_Col = @WNumCol and Num_Niv = @WNumNiv 
                           and Num_Apt = @WNumApt) = 0
                      begin
                        Insert into PRLTL (Cod_Estabe, Cod_Produt, Cod_Lote, Qtd_EmbFec, Dat_Vencim, Dat_Fabric, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Dat_Entrada, Qtd_FisPra, Qtd_SolPra,Qtd_FisDep,Qtd_SolDep)
                                   Values (@PCodEstabe, @it_CodPrd, @it_CodLot, @WQtdEmbFec, @WDatVct, @WDatFab, @WCodDepCan, @WNumRuaCan, @WNumCol, @WNumNiv, @WNumApt, @Date, 0, 0, 0, 0)
                        if @@error <> 0
                          begin
                            if @@trancount > 0
                              Rollback Transaction
                            Return
                          end
                      end

                    -- tira de PRLOT
                    Update PRLOT
                       Set Qtd_FisPra = Qtd_FisPra - Abs(@it_QtdPra)
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Dep = @WCodDepCan
                       And Cod_Produt = @it_CodPrd 
                       and Cod_Lote = @it_CodLot
                       And Abs(@it_QtdPra) > 0
                       And Qtd_SldPra >= Abs(@it_QtdPra)
                       And @WFlgErr = 0
                    if (@@rowcount = 0) and (Abs(@it_QtdPra) > 0) and (@WFlgErr = 0)
                      begin
                        Set @WFlgErr = 1
                        Set @WMsg = 'Estoque insuficiente no Picking a transferir p/ zona de cancelamentos'
                      end

                    Update PRLOT
                       Set Qtd_FisDep = Qtd_FisDep - Abs(@it_QtdDep)
                     Where Cod_Estabe = @PCodEstabe
                       And Cod_Dep = @WCodDepCan 
                       And Cod_Produt = @it_CodPrd 
                       and Cod_Lote = @it_CodLot
                       And Abs(@it_QtdDep) > 0
                       And Qtd_SldDep >= Abs(@it_QtdDep)
                       And @WFlgErr = 0
                    if (@@rowcount = 0) and (Abs(@it_QtdDep) > 0) and (@WFlgErr = 0)
                      begin
                        Set @WFlgErr = 1
                        Set @WMsg = 'Estoque insuficiente no Picking a transferir p/ zona de cancelamentos'
                      end

                    -- transfere para zona de cancelados
                    Update PRLTL
                       Set Qtd_FisPra = Qtd_FisPra +  Abs(@it_QtdPra)
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot
                       And Cod_Dep = @WCodDepCan
                       And Num_Rua = @WNumRuaCan 
                       And Num_Col = @WNumCol
                       And Num_Niv = @WNumNiv
                       And Num_Apt = @WNumApt
                       And Abs(@it_QtdPra) > 0
                       And @WFlgErr = 0
                    if (@@rowcount = 0) and (Abs(@it_QtdPra) > 0) and (@WFlgErr = 0)
                      begin
                        Set @WFlgErr = 1
                        Set @WMsg = 'Erro na transferencia p/ zona de cancelamentos (endereço inexistente)'
                      end

                    Update PRLTL
                       Set Qtd_FisDep = Qtd_FisDep +  Abs(@it_QtdDep)
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot
                       And Cod_Dep = @WCodDepCan
                       And Num_Rua = @WNumRuaCan 
                       And Num_Col = @WNumCol
                       And Num_Niv = @WNumNiv
                       And Num_Apt = @WNumApt
                       And Abs(@it_QtdDep) > 0
                       And @WFlgErr = 0
                    if (@@rowcount = 0) and (Abs(@it_QtdDep) > 0) and (@WFlgErr = 0)
                      begin
                        Set @WFlgErr = 1
                        Set @WMsg = 'Erro na transferencia p/ zona de cancelamentos (endereço inexistente)'
                      end
                      
                    -- registra log entrada
                    Set @WCodOri = 'TRF_EST'

                    -- registra log transferencia picking p/ zona de cancelamento
                    -- saida picking
                    Set @WQtdMov = (Abs(@it_QtdPra) + Abs(@it_QtdDep)) * (-1)
                    Exec PR_InserePRLOG @PCodEstabe, @it_CodPrd, @it_CodLot, @WCodDepCan, 
                                        @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck,
                                        @WQtdMov, @WCodOri, '', @PSerNot, @PNumNot, '', @PNomUsu
                    if @@error <> 0 
                      begin
                        if @@trancount > 0
                          Rollback Transaction
                        Return
                      end 
                    
                    -- entrada na zona de cancelamento
                    Set @WQtdMov = Abs(@it_QtdPra) + Abs(@it_QtdDep)
                    Exec PR_InserePRLOG @PCodEstabe, @it_CodPrd, @it_CodLot, @WCodDepCan, 
                                        @WNumRuaCan, @WNumCol, @WNumNiv, @WNumApt,
                                        @WQtdMov, @WCodOri, '', @PSerNot, @PNumNot, '', @PNomUsu
                    if @@error <> 0 
                      begin
                        if @@trancount > 0
                          Rollback Transaction
                        Return
                      end 
                      
                  end    -- @cb_FlgWms = 1

                -- re-solicita pedido se for reabrir
                if (@WFlgReaPdvOk = 1 ) and (@WFlgErr = 0)
                  if ((@cb_FlgWms = 0) and (Exists(Select Cod_Pedido From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @cb_CodPdv And Cod_Produto = @it_CodPrd And Cod_Lote = @it_CodLot And Qtd_Pedido > 0))) or
                     ((@cb_FlgWms = 1) and (Exists(Select Cod_Pedido From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @cb_CodPdv And Cod_Produto = @it_CodPrd And Cod_Lote = '*' And Qtd_Pedido > 0)))
                    begin

                      if @cb_FlgWms = 0
                        Select @WQtdPra = Qtd_Pra,
                               @WQtdDep = Qtd_Dep
                          From PDVIT 
                         Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @cb_CodPdv And Cod_Produto = @it_CodPrd And Cod_Lote = @it_CodLot
                      else
                        Select @WQtdPra = Qtd_Pedido,
                               @WQtdDep = Qtd_Bonificacao
                          From PDVIT 
                         Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @cb_CodPdv And Cod_Produto = @it_CodPrd And Cod_Lote = '*'

                      if @WQtdPra is null
                        Set @WQtdPra = 0
                      if @WQtdDep is null
                        Set @WQtdDep = 0

                      if @cb_FlgWms = 0
                        begin
                          if @WQtdPra > 0
                            begin
                              Update PRLOT 
                                 Set Qtd_SolPra = Qtd_SolPra + @WQtdPra
                               Where Cod_Estabe = @PCodEstabe 
                                 /*And Cod_Dep = @WCodDepCan               DMD-8136*/
                                 And Cod_Produt = @it_CodPrd 
                                 and Cod_Lote = @it_CodLot
                                 And Qtd_SldPra >= @WQtdPra
                              if @@rowcount = 0
                                begin
                                  Set @WFlgErr = 1
                                  Set @WMsg = 'Inconsistencia nos lotes. Pedido deve ser cancelado'
                                end
                            end
                          if @WQtdDep > 0
                            begin
                              Update PRLOT 
                                 Set Qtd_SolDep = Qtd_SolDep + @WQtdDep
                               Where Cod_Estabe = @PCodEstabe 
                                 /*And Cod_Dep = @WCodDepCan               DMD-8136*/
                                 And Cod_Produt = @it_CodPrd 
                                 and Cod_Lote = @it_CodLot
                                 And Qtd_SldDep >= @WQtdDep
                              if @@rowcount = 0
                                begin
                                  Set @WFlgErr = 1
                                  Set @WMsg = 'Inconsistencia nos lotes. Pedido deve ser cancelado'
                                end
                          end
                        end

                      Update PRXES
                         Set Qtd_Solici = Qtd_Solici + @WQtdPra + @WQtdDep
                       Where Cod_Estabe = @PCodEstabe 
                         And Cod_Produt = @it_CodPrd
                    end                

                  else
                    begin
                      Set @WFlgErr = 1
                      Set @WMsg = 'Item inexistente no pedido: '+cast(@it_CodPrd as varchar)+'/'+@it_CodLot+'. Pedido deve ser cancelado'
                    end                

                if @WFlgErr = 0 
                  begin
                    -- identifica bonificacao  
                    Set @it_TipSai = ''
                    if (@it_CodCfo = 5910) or (@it_CodCfo = 6910)
                      Set @it_TipSai = 'B'
                      
                    if @cb_CodCli > 0 
                      begin
                         -- atualiza verbas do cliente 
                        if ((@it_VlrVrbPar <> 0) or (@it_VlrVrbBon <> 0)) and (@cb_TipNot = 'V') and (@it_TipSai = '')
                          begin
                            Set @it_VlrVrbPar = -@it_VlrVrbPar
                            Set @it_VlrVrbBon = -@it_VlrVrbBon
                            
                            Exec PR_AtualizaSaldoVBCSD @PCodEstabe, @cb_CodCli, @WDatCan, 0, @it_CodPrd, @it_CodLot, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPar, @it_VlrVrbBon, 'CANCELAMENTO NF', 'SISTEMA'
                            if (@@error <> 0)
                              begin
                                if @@trancount > 0
                                  Rollback Transaction
                                Return
                              end
                          end
                      end
 
                     -- grava movimento relativo a remessa/venda em consignação: CFOP: 5917/6917,  5112/6112, 5113/6113, 5114/6114 
                    if (@cb_IdConsig > 0) and (@cb_NumSeqCtr > 0) and (dbo.FN_CfopConsigValido(@cb_CodCfo) = 1)
                      begin
                        if dbo.FN_TipoNFConsig(@cb_CodCfo) = 'R'
                          Set @CodTipSaiCng = 'NFR'
                        else
                          Set @CodTipSaiCng = 'NFF'

                        Exec PR_GravaMovimeCNGMV @PCodEstabe, @cb_IdConsig, @it_CodPrd, @it_CodLot,
                                                 @cb_DatEmi, 'S', @CodTipSaiCng, @PSerNot, @PNumNot, @it_TipSai, 'C', 
                                                 @WQtdMov, @it_PrcUni
                        if (@@error <> 0)
                          begin
                            if @@trancount > 0
                              Rollback Transaction
                            Return
                          end
                      end

                    -- verba
                    -- @pc_CtlSld já está com controle da política do cabeçalho (default)
                    if Exists (Select 1 From POCOM Where Id_PolCom = @it_IdPolCom)
                      Select @pc_CtlSld = pc.Controle_Saldo
                        From POCOM pc
                       Where pc.Id_PolCom = @it_IdPolCom

                    if @pc_CtlSld = 'V' -- Vendedor/Operador
                      begin
                        -- atualiza verba de politica para vendedor  cuidado que pode ser NF de bonificacao tb
            if (@it_VlrVrbPolVdr <> 0) and (@cb_CodVdr >  0)
                          begin
                            Set @it_VlrVrbPolVdr = -@it_VlrVrbPolVdr
                            Exec PR_AtualizaSaldoVBSLD @PCodEstabe, @cb_CodVdr, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolVdr, 'CANCELAMENTO NF', 'SISTEMA'
                            if (@@error <> 0)
                              begin
                                if @@trancount > 0
                                  Rollback Transaction
                                Return
                              end
                          end

            -- atualiza verba de politica para Operador. Cuidado que pode ser NF de bonificação tb
            if (@it_VlrVrbPolOpe <> 0) and (@cb_CodOpe > 0)
              begin
              Set @it_VlrVrbPolOpe = -@it_VlrVrbPolOpe
              Exec PR_AtualizaSaldoVBSLD @PCodEstabe, @cb_CodOpe, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolOpe, 'CANCELAMENTO NF', 'SISTEMA'
              if (@@error <> 0)
                begin
                                if @@trancount > 0
                                  Rollback Transaction
                Return
                end
              end

                        -- atualiza verba de politica para supervidsor
            if (@it_VlrVrbPolSup <> 0) and (@cb_CodSup > 0)
                          begin
                            Set @it_VlrVrbPolSup = -@it_VlrVrbPolSup
                            Exec PR_AtualizaSaldoVBSSD @PCodEstabe, @cb_CodSup, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolSup, 'CANCELAMENTO NF', 'SISTEMA'
                            if (@@error <> 0)
                              begin
                                if @@trancount > 0
                                  Rollback Transaction
                                Return
                              end
                          end
                      end  -- if @pc_CtlSld = 'V' -- Vendedor/Operador

                    if @pc_CtlSld = 'F' -- Fabricante
                      begin
                        -- atualiza verba de politica para Vendedor. Cuidado que pode ser NF de bonificação tb
            if (@it_VlrVrbPolVdr <> 0) and (@cb_CodVdr > 0)
              begin
              Set @it_VlrVrbPolVdr = -@it_VlrVrbPolVdr
              Exec PR_AtualizaSaldoVBFSL @PCodEstabe, @cb_CodVdr, @it_CodFab, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolVdr, 'CANCELAMENTO NF', 'SISTEMA'
              if (@@error <> 0)
                begin
                                if @@trancount > 0
                                  Rollback Transaction
                Return
                end
              end
                      
            -- atualiza verba de politica para Operador. Cuidado que pode ser NF de bonificação tb
            if (@it_VlrVrbPolOpe <> 0) and (@cb_CodOpe > 0)
              begin
              Set @it_VlrVrbPolOpe = -@it_VlrVrbPolOpe
              Exec PR_AtualizaSaldoVBFSL @PCodEstabe, @cb_CodOpe, @it_CodFab, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolOpe, 'CANCELAMENTO NF', 'SISTEMA'
              if (@@error <> 0)
                begin
                                if @@trancount > 0
                                  Rollback Transaction
                Return
                end
              end
            end  -- if @pc_CtlSld = 'F' -- Fabricante

                    -- verba fornecedor   
                    Set @WValBru = Round(@it_QtdPrd*@it_PrcFab,2)
                    Set @WValEdi = Round(@it_QtdPrd*@it_PrcUniPde*(1-@it_PerDscPde/100),2)
                    if @WValEdi > 0
                      begin
                        Set @WValMov = @WValBru - @WValEdi
                        Set @WCodFor = IsNull((Select fb.Cod_ForPref From PRODU pr Inner Join FBXES fb on pr.Cod_Fabricante = fb.Cod_Fabric and @PCodEstabe = fb.Cod_Estabe
                                                Where pr.Codigo = @it_CodPrd),0)
                        if (@WCodFor > 0) and (@WValMov > 0) and (@it_TipSai = '')
                          begin
                            Set @WValMov = -@WValMov
                            Exec PR_AtualizaSaldoVBFSD @PCodEstabe, @WCodFor, @WDatCan, 0, @it_CodPrd, @it_CodLot, 'S', 'X', @PSerNot, @PNumNot, @WValMov, 'SAIDA NF', 'SISTEMA'
                            if (@@error <> 0)
                              begin
                                if @@trancount > 0
                                  Rollback Transaction
                                Return
                              end
                          end
                      end
                      
                  end

                Fetch Next From NFSIT_Cr
                  Into @it_CodPrd, @it_CodLot, @it_SeqIte, @it_QtdPrd, @it_QtdBon, @it_PrcUni,
                       @it_CodCfo, @it_PrcFab, @it_PrcUniPde, @it_PerDscPde,
                       @it_QtdPra, @it_QtdDep, @it_VlrVrbPolVdr, @it_VlrVrbPolOpe, @it_VlrVrbPolSup, @it_VlrVrbPar, 
                       @it_VlrVrbBon, @it_IdPolCom, @it_CodFab 
              end
            Close NFSIT_Cr
            Deallocate NFSIT_Cr

            if @WFlgErr = 1
              begin
                if @WMsg <> ''
                  RAISERROR(@WMsg,16,1)
                if @@trancount > 0
                  Rollback Transaction
                Return
              end

            -- cancela os titulos
            Exec PR_CancelaDevolveTitulosCTREC @PCodEstabe, @PSerNot, @PNumNot, @PNomUsu, 'C', 0, 0
            if @@error <> 0
              begin
                if @@trancount > 0
                  Rollback Transaction
                Return
              end

            -- atualiza estatisticas da nota: cabeçalho e itens
            Exec PR_AtualizaEstatisticasNFS @PCodEstabe, @PSerNot, @PNumNot, 'C'
            if @@error <> 0
              begin
                if @@trancount > 0
                  Rollback Transaction
                Return
              end

            -- atualiza verbas
            if @cb_ValDebVrbVdr > 0
              begin
                Exec PR_AtualizaSaldoVBSLD @PCodEstabe, @cb_CodVdr, @WDatCan, 0, 0, '', '', 'S', 'C', @PSerNot, @PNumNot, @cb_ValDebVrbVdr, 'CANCELAMENTO NF', 'SISTEMA'
                if (@@error <> 0)
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
              end



            -- cancela o pedido
            if (@PFlgCanPdv = 1) and Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @cb_CodPdv and Status1 <> 'C')
              begin
                Update PDVCB
                   Set Bloqueio = 'SR'
                 Where Cod_Estabe = @PCodEstabe 
                   And Numero = @cb_CodPdv and Status1 <> 'C'

                Exec PR_CancelaPDV @PCodEstabe, @Cb_CodPdv, @PNomUsu, 0
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
              end

            -- reabre o pedido
            if (@PFlgCanPdv = 0) and (@WFlgReaPdvOk = 1)
              begin
                Update PDVCB
                   Set Status1 = 'P',
                       Status2 = 'A',
                       Cod_SerNfs = null,
                       Cod_NumNfsIni = null,
                       Cod_NumNfsFim = null,
                       Cod_FunSeparador = 0,
                       Cod_FunConferidor = 0,
                       Cod_FunEmbalador = 0,
                       Qtd_Volumes = 0,
                       Qtd_Peso = 0,
                       Hor_PreNota = null,
                       Hor_Fatura = null,
                       Hor_Saida = null,
                       Hor_ConferIni = null,         
                       Hor_ConferFim = null         
                 Where Cod_Estabe = @PCodEstabe 
                   And Numero = @cb_CodPdv

                -- Elimina Solicitacao de Lotes
                Delete From PDVLT
                 Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @cb_CodPdv

                -- Elimina a conferencia
                Delete From CPVIT
                 Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @cb_CodPdv

                Delete From CPVCB
                 Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @cb_CodPdv
  
                -- tem que excluir nota nao fiscal
                if @cb_CodCfo = 0
                  begin
                    Delete from NFSIT 
                     Where Cod_Estabe = @PCodEstabe 
                       and Ser_Nota = @PSerNot and Num_Nota = @PNumNot

                    Delete from NFSCB
                     Where Cod_Estabe = @PCodEstabe 
                      and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
                  end
                else
                  begin
                    Update NFSCB
                       Set Cod_Pedido = 0
                     Where Cod_Estabe = @PCodEstabe 
                       and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
                  end
              end  -- -- reabre o pedido

            -- atualiza contratos
            if (@cb_CodCtr > 0) and (@cb_NumSeqCtr > 0)
              begin
                Exec PR_RetornarItensCtrHospitalar @PCodEstabe, @cb_CodCtr, @cb_NumSeqCtr 
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
              end

            -- atualiza itens na tabela de consignações
            if (@cb_IdConsig > 0) and (@cb_NumSeqCtr > 0)
              begin
                Exec PR_FaturaConsignacao 'S', @PCodEstabe, @PSerNot, @PNumNot, @cb_IdConsig, @cb_NumSeqCtr
                if (@@error <> 0)
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
              end

            -- estorna vale
            if (@cb_TipNot = 'D') and ((@cb_CodCli > 0) or (@cb_CodFun > 0) or (@cb_CodFor > 0))
              begin
                if @cb_CodCli > 0
                  begin
                    Set @WTipDes = 'CLI'
                    Set @WCodDes = @cb_CodCli
                  end
                else
                if @cb_CodFun > 0
                  begin
                    Set @WTipDes = 'FUN'
                    Set @WCodDes = @cb_CodFun
                  end
                else
                if @cb_CodFor > 0
                  begin
                    Set @WTipDes = 'FOR'
                    Set @WCodDes = @cb_CodFor
                  end
                  
                if Exists(Select Cod_Vale From VALES
                           Where Cod_Estabe = @PCodEstabe 
                             And Cod_CtrLanAut = 'DNS'
                             And Num_CtrLanAut = @PNumNot
                             And Tip_Entid = @WTipDes
                             And Cod_Entid = @WCodDes
                             And Deb_Cre = 'D'
                             And Round(Val_Vale,2) = Round(@cb_ValNot,2))
                  begin
                    Delete From VALES
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_CtrLanAut = 'DNS'
                       And Num_CtrLanAut = @PNumNot
                       And Tip_Entid = @WTipDes
                       And Cod_Entid = @WCodDes
                       And Deb_Cre = 'D'
                       And Round(Val_Vale,2) = Round(@cb_ValNot,2)
                    if @@ROWCOUNT = 0
            begin                  
                        Set @va_IsnCtaFinDeb = 0
                        Set @va_IsnCtaFinCre = 0

                        -- pega contas gerenciais invertidas
                        if @pm_FlgUsaInterv = 1 
                          begin
                            Select @va_IsnCtaFinDeb = IsNull(Isn_CtaFinCre,0), 
                                   @va_IsnCtaFinCre = IsNull(Isn_CtaFinDeb,0)
                              From VALES
                             Where Cod_Estabe = @PCodEstabe 
                               And Cod_CtrLanAut = 'DNS'
                               And Num_CtrLanAut = @PNumNot
                               And Tip_Entid = @WTipDes
                               And Cod_Entid = @WCodDes
                               And Deb_Cre = 'D'
                          end
                  
                        -- inclui vale
                        EXEC PR_ProxNumero 'Vale', @WCodDoc output
                        if @@error <> 0
                          begin
                            if @@trancount > 0
                              Rollback Transaction
                            Return
                          end

                        Insert into VALES
                          (Cod_Estabe, Cod_Vale, Des_Vale, Tip_Entid, Cod_Entid, Dat_Emissa, Val_Vale, Deb_Cre, 
                           Cod_CtrLanAut, Num_CtrLanAut, Isn_CtaFinDeb, Isn_CtaFinCre, Usuario, Transacao)
                        Values
                          (@PCodEstabe, @WCodDoc,'NFS Cancelamento Devolucao: '+@PSerNot+'/'+cast(@PNumNot as varchar), @WTipDes, @WCodDes, @Date, @cb_ValNot, 'C',
                           'DNS', @PNumNot, @va_IsnCtaFinDeb, @va_IsnCtaFinCre, @cb_Usuario,@Now)
                      end
                  end
              end  -- estorna vale
              
          end
          
      -- exclui lançamentos em PCMOV
      while exists(Select Isn_CtaFin 
                     From PCMOV
                    Where Cod_Estabe = @PCodEstabe
                      And Nom_Tabela = 'NFSCB'
                      And Tip_Docume = 'NFS'
                      And Ser_Docume = @PSerNot
                      And Num_Docume = @PNumNot)
        begin
          Select top 1 @va_IsnCtaFinDeb = Isn_CtaFin, 
                       @va_DatMovime = Dat_Movime,
                       @va_NumSequen = Num_Sequen    
            From PCMOV
           Where Cod_Estabe = @PCodEstabe
             And Nom_Tabela = 'NFSCB'
             And Tip_Docume = 'NFS'
             And Ser_Docume = @PSerNot
             And Num_Docume = @PNumNot
    
          -- elimina registro em PCMOV
          Delete From PCMOV
           Where Cod_Estabe = @PCodEstabe
             And Nom_Tabela = 'NFSCB'
             And Tip_Docume = 'NFS'
             And Ser_Docume = @PSerNot
             And Num_Docume = @PNumNot
             And Isn_CtaFin = @va_IsnCtaFinDeb

          -- reprocessa saldo PCMOV
          Exec PR_ReprocessaPCMOV @va_IsnCtaFinDeb, @va_DatMovime
        end             

    end -- if @FlgPodeCancelar = 1

  if @@trancount > 0
    COMMIT TRANSACTION
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AnalisaCreditoCliente]
@PCodOpe varchar(3),   -- COT-cotacao, <>- outras
@PCodEstabe int,       -- -1: todos os estabelecimentos
@PCodCli int,
@PNumPdv int,          -- pedido especifico
@PMsg varchar(8000) output,
@PSta smallint output,
@PStaLic varchar(1) output,
@PCodMtv varchar(3) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = cast(GetDate() as date)

Set @PMsg = ''
Set @PSta = 0      -- 0=verde; 1=amarelo; 2=vermelho; 3=preto
Set @PStaLic = ''  -- licencas do cliente quando paremetrizado, B=bloqueado (vencido)
Set @PCodMtv = ''  -- codigo motivo rejeição

if Exists(Select Codigo From CLIEN Where Codigo = @PCodCli)
  BEGIN

  Declare @cl_Bloqueado bit, 
          @cl_Motivo_Bloqueio varchar(30), 
          @cl_Usuario_Bloqueio varchar(15),
          @cl_Atraso_Atual int, 
          @cl_Atraso_Permitido int,
          @cl_Sta_ChqVnc varchar(1),
          @cl_Cod_CliPag int,
          @cl_SldLimCred numeric(18,4),
          @cl_Limite_Credito numeric(18,4),
          @cl_Atraso_MedAtu int,
		  @cl_Data_UltimaFatura smalldatetime,
		  @cl_Data_Cadastro smalldatetime,
		  @cl_Dat_LimCreAtu smalldatetime,
          @cl_Cod_InfCredito int,
          @cl_Flg_NaoBlqDocPdv bit,
          @cl_Flg_NaoBlqFinPdv bit,

          @ic_Descricao varchar(30),
          @ic_Controle varchar(1),

          @pm_FlgBlqIncPdvCliAtr bit,
          @pm_FlgBlqPdvAtrCtr bit,
          @pm_FlgCtrBlqPdvLicCli bit,
          @pm_QtdDiaAtrMedCtr int,
          @pm_QtdMesTmpCom int,
          @pm_FlgBlqVenCliSemLimCre bit,
          @pm_FlgBlqCtrDocClaPrd bit,

		  @Wpr_FlgBlqCtrLic bit,
          @WValTotPdvPen numeric(18,4),
          @WAtrMedAtu int,
          @WFlgLicSauIrr bit,
          @WFlgLicAnvIrr bit,
          @WFlgLicCrfIrr bit,
          @WFlgAlvFunIrr bit,
          @WMsgLicIrr varchar(30),
		  @WFlgBlqCtrDocClaPrd bit

  Select @cl_Bloqueado = IsNull(cl.Bloqueado,0), 
         @cl_Motivo_Bloqueio = IsNull(cl.Motivo_Bloqueio,''), 
         @cl_Usuario_Bloqueio = IsNull(cl.Usuario_Bloqueio,''),
         @cl_Atraso_Atual = IsNull(cl.Atraso_Atual,0), 
         @cl_Atraso_Permitido = IsNull(cl.Atraso_Permitido,0),
         @cl_Sta_ChqVnc = IsNull(cl.Sta_ChqVnc,''),
         @cl_Cod_CliPag = IsNull(cl.Cod_CliPag,0),
         @cl_Limite_Credito = IsNull(cl.Limite_Credito,0),
         @cl_SldLimCred = IsNull(cl.Limite_Credito,0) - IsNull(cl.Total_Debito,0),
		 @cl_Atraso_MedAtu = IsNull(cl.Atraso_MedAtu,0),
         @cl_Data_UltimaFatura = IsNull(cl.Data_UltimaFatura,0),
         @cl_Data_Cadastro = IsNull(cl.Data_Cadastro,0),
         @cl_Dat_LimCreAtu = IsNull(cl.Dat_LimCreAtu,0),
         @cl_Cod_InfCredito = IsNull(Cod_InfCredito,0),
		 @cl_Flg_NaoBlqDocPdv = IsNull(cl.Flg_NaoBlqDocPdv,0),
		 @cl_Flg_NaoBlqFinPdv = IsNull(cl.Flg_NaoBlqFinPdv,0),
         @ic_Descricao = IsNull(ic.Descricao,''),
         @ic_Controle = IsNull(ic.Controle,'')
    From CLIEN cl
         Left Outer Join INFCR ic on cl.Cod_InfCredito = ic.Codigo
	Where cl.Codigo = @PCodCli

  if @cl_Flg_NaoBlqFinPdv = 0
    if Exists(Select 1 From CLIEN Where IsNull(Flg_NaoBlqFinPdv,0) = 1 And Cod_CliPag = @cl_Cod_CliPag)
      Set @cl_Flg_NaoBlqFinPdv = 1

  if @PCodEstabe <> - 1
    Select @pm_FlgBlqIncPdvCliAtr = IsNull(FlgBlqIncPdvCliAtr,0),
           @pm_FlgBlqPdvAtrCtr = IsNull(FlgBlqPdvAtrCtr,0),
           @pm_FlgCtrBlqPdvLicCli = IsNull(FlgCtrBlqPdvLicCli,0),
           @pm_QtdDiaAtrMedCtr = IsNull(QtdDiaAtrMedCtr,0),
           @pm_QtdMesTmpCom = IsNull(QtdMesTmpCom,0),
           @pm_FlgBlqVenCliSemLimCre = IsNull(FlgBlqVenCliSemLimCre,0),
           @pm_FlgBlqCtrDocClaPrd = IsNull(FlgBlqCtrDocClaPrd,0)
      From PARAM
     Where Cod_Estabe = @PCodEstabe
  else
    begin
      Set @pm_FlgBlqIncPdvCliAtr = Case 
                                     When Exists(Select 1 From PARAM Where IsNull(FlgBlqIncPdvCliAtr,0) = 1) then 1 
                                     Else 0 
                                   End
      Set @pm_FlgBlqPdvAtrCtr = Case 
                                  When Exists(Select 1 From PARAM Where IsNull(FlgBlqPdvAtrCtr,0) = 1) then 1 
                                  Else 0 
                                End
      Set @pm_FlgCtrBlqPdvLicCli = Case 
                                     When Exists(Select 1 From PARAM Where IsNull(FlgCtrBlqPdvLicCli,0) = 1) then 1 
                                     Else 0 
                                   End
      Set @pm_QtdDiaAtrMedCtr = Case 
                                  When Exists(Select 1 From PARAM Where IsNull(QtdDiaAtrMedCtr,0) = 1) then 1 
                                  Else 0 
                                End
      Set @pm_QtdMesTmpCom = Case 
                               When Exists(Select 1 From PARAM Where IsNull(QtdMesTmpCom,0) = 1) then 1 
                               Else 0 
                             End
      Set @pm_FlgBlqVenCliSemLimCre = Case 
                                        When Exists(Select 1 From PARAM Where IsNull(FlgBlqVenCliSemLimCre,0) = 1) then 1 
                                        Else 0 
                                      End
      Set @pm_FlgBlqCtrDocClaPrd = Case 
                                     When Exists(Select 1 From PARAM Where IsNull(FlgBlqCtrDocClaPrd,0) = 1) then 1 
                                     Else 0 
                                   End
    end

    -- ver bloqueio manual
    if @cl_Bloqueado = 1
      begin
        Set @PSta = 3
        Set @PCodMtv = 'CLB'
--        if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
        if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
        Set @PMsg = @PMsg + @cl_Motivo_Bloqueio+' ('+@cl_Usuario_Bloqueio+')'
      end

    -- bloqueio financeiro
    if @cl_Flg_NaoBlqFinPdv = 0  -- nunca bloqueia financeiramente
      begin

        if @pm_FlgBlqIncPdvCliAtr = 1
          if @cl_Atraso_Atual > @cl_Atraso_Permitido
            begin
              Set @PSta = 3
              Set @PCodMtv = 'CLB'
              if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
              Set @PMsg = @PMsg + 'ATRASO ATUAL MAIOR QUE O PERMITIDO' 
            end

        -- ver bloqueio por cheques
        if @cl_Sta_ChqVnc = '1' 
          begin
            if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
            Set @PMsg = @PMsg + 'CHEQUE(s) P/TIT(s).VENCIDO(s)'
            if 2 > @PSta
              Set @PSta = 2
          end
        else
          if @cl_Cod_CliPag > 0
            begin
              -- verifica atraso do grupo
              if Exists(Select 1 From CLIEN 
                          Where Cod_CliPag = @cl_Cod_CliPag
                          And Sta_ChqVnc = '1')
                begin
                  if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
                  Set @PMsg = @PMsg + 'CHEQUE(s) P/TIT(s).VENCIDO(s) (GRUPO)'
                  if 2 > @PSta
                    Set @PSta = 2
                end
            end

        if @cl_Sta_ChqVnc = '2' 
          begin
            if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
            Set @PMsg = @PMsg + 'CHEQUE(s).DEVOLVIDO(s)'
            if 2 > @PSta
              Set @PSta = 2
          end
        else
          if @cl_Cod_CliPag > 0
            begin
              -- verifica atraso do grupo
              if Exists(Select 1 From CLIEN 
                          Where Cod_CliPag = @cl_Cod_CliPag
                          And Sta_ChqVnc = '2')
                begin
                  if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
                  Set @PMsg = @PMsg + 'CHEQUE(s).DEVOLVIDO(s) (GRUPO)'
                  if 2 > @PSta
                    Set @PSta = 2
                end
            end
       
        if @cl_Sta_ChqVnc = '3'
          begin
            if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
            Set @PMsg = @PMsg + 'CHEQUE(s).BAIXADO(s)'
            if 2 > @PSta
              Set @PSta = 2
          end
        else
          if @cl_Cod_CliPag > 0
            begin
              -- verifica atraso do grupo
              if Exists(Select 1 From CLIEN 
                          Where Cod_CliPag = @cl_Cod_CliPag
                          And Sta_ChqVnc = '3')
                begin
                  if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
                  Set @PMsg = @PMsg + 'CHEQUE(s).BAIXADO(s) (GRUPO)'
                  if 2 > @PSta
                    Set @PSta = 2
                end
            end

        -- ver bloqueio automatico
        -- debita pedidos nao faturados do limite de credito+
        Set @cl_SldLimCred = dbo.FN_SaldoCreditoCliente(@PCodCli)
        if @cl_SldLimCred < 0
          begin
            if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
            Set @PMsg = @PMsg + 'LIMITE DE CRÉDITO ESTOURADO'
            if 2 > @PSta
              Set @PSta = 2

/*
            -- bloqueia cliente se for o caso
            Update CLIEN
              Set Bloqueado = 1,
                  Motivo_Bloqueio = 'Bloq. auto. por lim. de créd.'
            Where Codigo = @PCodCli
            And IsNull(Bloqueado,0) = 0
            And @pm_FlgBlqVenCliSemLimCre = 1
*/
          end

        if @cl_Atraso_Atual > @cl_Atraso_Permitido
          begin
            if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
            Set @PMsg = @PMsg + 'ATRASO NOS PAGAMENTOS'
            if 2 > @PSta
              Set @PSta = 2
          end
        else
          if @cl_Cod_CliPag > 0
            begin
              -- verifica atraso do grupo
              if Exists(Select 1 From CLIEN 
                          Where Cod_CliPag = @cl_Cod_CliPag
                          And Atraso_Atual > Atraso_Permitido)
                begin
                  if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
                  Set @PMsg = @PMsg + 'ATRASO NOS PAGAMENTOS(GRUPO)'
                  if 2 > @PSta
                    Set @PSta = 2
                end
            end

        if @pm_FlgBlqPdvAtrCtr = 1
          if @cl_Atraso_MedAtu > @pm_QtdDiaAtrMedCtr
            begin
              if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
              Set @PMsg = @PMsg + 'ATRASO MEDIO MAIOR QUE O PERMITIDO'
              if 2 > @PSta
                Set @PSta = 2
            end
          else
            if @cl_Cod_CliPag > 0
              begin
                -- verifica atraso medio do grupo
    			Set @WAtrMedAtu = 0
	    		Set @WAtrMedAtu = IsNull((Select Sum(IsNull(Atraso_MedAtu,0))/count(*) as Atr_MedMed From CLIEN 
                                          Where Cod_CliPag = @cl_Cod_CliPag
                                          And Atraso_MedAtu > 0),0)
                if IsNull(@WAtrMedAtu,0) > @pm_QtdDiaAtrMedCtr
                  begin
                    if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
                    Set @PMsg = @PMsg + 'ATRASO MEDIO MAIOR QUE O PERMITIDO(GRUPO)'
                    if 2 > @PSta
                      Set @PSta = 2
                  end
              end

        if @pm_QtdMesTmpCom > 0 
          if ((DateDiff(day,@cl_Data_UltimaFatura,@Date)/ 30) > @pm_QtdMesTmpCom) and
             ((DateDiff(day,@cl_Data_Cadastro,@Date)/ 30) > @pm_QtdMesTmpCom) and
             ((DateDiff(day,@cl_Dat_LimCreAtu,@Date)/ 30) > @pm_QtdMesTmpCom) 
            begin
              if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
              Set @PMsg = @PMsg + 'CLIENTE NÃO COMPRA HÁ MAIS DE '+cast(@pm_QtdMesTmpCom as varchar)+' MESES'
              if 2 > @PSta
                Set @PSta = 2
            end

        -- ver bloqueio por inf. de credito
        if @cl_Cod_InfCredito > 0 
          begin
            if IsNull(@ic_Descricao,'') <> ''
              begin
                if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
                Set @PMsg = @PMsg + @ic_Descricao
                if @ic_Controle = 'B' -- bloqueado
                  if 3 > @PSta
                    begin
                      Set @PSta = 3
                      Set @PCodMtv = 'CLB'
                    end
                  else
			        Set @PCodMtv = ''
                else
                if @ic_Controle = 'A'   -- aprovacao
                  if 2 > @PSta
                    Set @PSta = 2
                  else
	    		    Set @PCodMtv = ''
                else
                if @ic_Controle = 'O'   -- observacao
                  if 1 > @PSta
                    Set @PSta = 1
              end
          end

      end  -- if @cl_Flg_NaoBlqFinPdv = 0

    -- ver bloqueios por licenças vencidas
	-- licença da saúde
    Exec PR_AnalisaLicencaCliente @PCodOpe, 'SAUDE',  @PCodCli, @WFlgLicSauIrr output, @WMsgLicIrr output
    if @WFlgLicSauIrr = 1
      if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
        Set @PMsg = @PMsg + @WMsgLicIrr

	-- licença da ANVISA
    Exec PR_AnalisaLicencaCliente @PCodOpe, 'ANVISA',  @PCodCli, @WFlgLicAnvIrr output, @WMsgLicIrr output
    if @WFlgLicAnvIrr = 1
      if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
        Set @PMsg = @PMsg + @WMsgLicIrr

    -- licenca CRF
    Exec PR_AnalisaLicencaCliente @PCodOpe, 'CRF',  @PCodCli, @WFlgLicCrfIrr output, @WMsgLicIrr output
    if @WFlgLicCrfIrr = 1
      if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
        Set @PMsg = @PMsg + @WMsgLicIrr

    -- ALvara de funcionamento
    Exec PR_AnalisaLicencaCliente @PCodOpe, 'ALVARA',  @PCodCli, @WFlgAlvFunIrr output, @WMsgLicIrr output
    if @WFlgAlvFunIrr = 1
      if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
        Set @PMsg = @PMsg + @WMsgLicIrr


    -- verifica se existe pelo menos 1 item que necessita de validação da documentação
    Set @Wpr_FlgBlqCtrLic = 0
    if (@PNumPdv > 0) and
       (@pm_FlgBlqCtrDocClaPrd = 1) and   -- parametro global: Ignora bloqueio controle de documentação por classificação de produto
       not Exists(Select 1
                    From PDVIT it
                         Inner join PRODU pr on pr.Codigo = it.Cod_Produto		 
                         Left  Join CLASS c1 on Substring(pr.Cod_Classif,1,2) = c1.Codigo
                         Left  Join CLASS c2 on Substring(pr.Cod_Classif,1,4) = c2.Codigo
                         Left  Join CLASS c3 on Substring(pr.Cod_Classif,1,7) = c3.Codigo
                   Where it.Cod_Estabe = @PCodEstabe
                     and it.Cod_Pedido = @PNumPdv
                     and it.Qtd_Pedido > 0
                     and IsNull(c1.Flg_BlqCtrDocClaPrd,0) = 0
                     and IsNull(c2.Flg_BlqCtrDocClaPrd,0) = 0
                     and IsNull(c3.Flg_BlqCtrDocClaPrd,0) = 0)
          Set @Wpr_FlgBlqCtrLic = 1  -- ignora bloqueio de controle de documentacao

/*
    Set @Wpr_FlgBlqCtrLic = 0
    if @PNumPdv > 0
	  begin
        set @Wpr_FlgBlqCtrLic = 1
        DECLARE Table_Cr CURSOR Local Fast_Forward For
          Select FlgBlqCtrDocClaPrd = Case 
                                        When (pm.FlgBlqCtrDocClaPrd = 1) And (Select cl.Flg_BlqCtrDocClaPrd From CLASS cl Where cl.codigo =  Left(pd.cod_Classif, 2) And  cl.Flg_BlqCtrDocClaPrd = 1) = 1 Then 1 
                                        When (pm.FlgBlqCtrDocClaPrd = 1) And (Select cl.Flg_BlqCtrDocClaPrd From CLASS cl Where cl.codigo =  Left(pd.cod_Classif, 4) And  cl.Flg_BlqCtrDocClaPrd = 1) = 1 Then 1 
                                        When (pm.FlgBlqCtrDocClaPrd = 1) And (Select cl.Flg_BlqCtrDocClaPrd From CLASS cl Where cl.codigo =  Left(pd.cod_Classif, 7) And  cl.Flg_BlqCtrDocClaPrd = 1) = 1 Then 1 
                                        Else 0
                                      End
          From PDVIT it
                Inner join PARAM pm on pm.Cod_Estabe = it.Cod_Estabe
	  	        Inner join PRODU pd on pd.Codigo = it.Cod_Produto		 
          Where it.Cod_Estabe = @PCodEstabe
	        and it.Cod_Pedido = @PNumPdv
        OPEN Table_Cr
        FETCH NEXT FROM Table_Cr INTO @WFlgBlqCtrDocClaPrd
        WHILE @@FETCH_STATUS = 0
        BEGIN
	      if @WFlgBlqCtrDocClaPrd = 0
	        set @Wpr_FlgBlqCtrLic = 0   
	      FETCH NEXT FROM Table_Cr INTO @WFlgBlqCtrDocClaPrd
        END
        CLOSE Table_Cr
        DEALLOCATE Table_Cr 
 	  End
*/

    if (@cl_Flg_NaoBlqDocPdv = 0) and (@Wpr_FlgBlqCtrLic = 0) -- nunca bloqueia pedido por documentação
      if @pm_FlgCtrBlqPdvLicCli = 1  -- valida documentação
        begin
          if (@WFlgLicSauIrr = 1) or (@WFlgLicAnvIrr = 1) or (@WFlgLicCrfIrr = 1) or (@WFlgAlvFunIrr = 1)
            Set @PStaLic = 'B'
        end
      else
        begin
          if (@WFlgLicAnvIrr = 1) or (@WFlgLicCrfIrr = 1) or (@WFlgAlvFunIrr = 1)
            begin
              if 2 > @PSta
                Set @PSta = 2
            end
        end

  END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_IncluiPDVCB]
@PTipPedido char(1),    -- 'P'-Pedido, 'C'-Cotacao
@PCodEstabe int,
@PNumPdv int = NULL output,    -- se = 0 : cria novo pedido
@PCodOri varchar(1),    -- A-Ativo, P-Receptivo, M-Móvel, T-Eletronico/EDI, W-Internet/WEB, H-Hospitalar, D-por Desdobramento, V-por Vales
@PCodCli int,
@PFlgUsaWms bit,        -- PDVCB.Flg_WMS
@PTipOpe varchar(3),
@PCodVdr int,           -- opcional
@PCodOpe int,           -- opcional
@PCodDig int,           -- opcional
@PIdPolCom int,
@PCodPrz int,
@PCodLayPde int,
@PFlgBlqWms bit,        -- nunca usa WMS tem prioridade sobre @PFlgUsaWms
@PFlgBlqPol bit,        -- nunca usa politica
@PMsgErr varchar(8000) output,
@PIdPVMCB int

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now  = GetDate()
Set @Date = cast(GetDate() as Date)

Set @PCodOri = Ltrim(Rtrim(@PCodOri))
Set @PTipOpe = Ltrim(Rtrim(@PTipOpe))

BEGIN

Set @PMsgErr = ''

if @PNumPdv is null
  Set @PNumPdv = 0

Declare @UsuInfarma varchar(15)

Declare @WCodAgeCob int = 0,
        @WMsg varchar(1000),
        @WSta smallint,
        @WStaLic varchar(1),
        @WCodMtv varchar(3),
		@WTipPrz varchar(1),
        @WTipSaiPdv varchar(1),
        @WTipGerVrb varchar(1),
        @WFlgMarkupCusCom bit,
        @WDesLayPde varchar(25),

        @pv_CodTipPed varchar(3),
		@es_CodRegTri int = 0,

		@pm_FlgUsaPolComPdv bit = 0,
		@pm_FlgOrcAgeCobCar bit = 0,
		@pm_FlgGerComOpeAtv bit = 0,
		@pm_CodOpeSemCom int = 0,
		@pm_CodOpePdvCon int = 0,
		@pm_CodAgeCobCar int = 0,
		@pm_FlgPrzLinConFin bit = 0

-- PARAM
Select @pm_FlgUsaPolComPdv = IsNull(FlgUsaPolComPdv,0),
       @pm_FlgOrcAgeCobCar = IsNull(FlgOrcAgeCobCar,0),
       @pm_FlgGerComOpeAtv = IsNull(FlgGerComOpeAtv,0),
       @pm_CodOpeSemCom = IsNull(CodOpeSemCom,0),
	   @pm_CodOpePdvCon = IsNull(CodOpePdvCon,0),
       @pm_CodAgeCobCar = IsNull(CodAgeCobCar,0),
	   @pm_FlgPrzLinConFin = IsNull(FlgPrzLinConFin,0) 
From PARAM 
Where Cod_Estabe = @PCodEstabe

-- se pedido existir ajusta parametros 
Set @WCodAgeCob = 0

if Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
  begin
    Set @PFlgUsaWms = (Select IsNull(Flg_WMS,0) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    Set @WCodAgeCob = (Select IsNull(Cod_Agente,0) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)

    if @PCodOri = ''
      Set @PCodOri = (Select Substring(Cod_OrigemPdv,1,1) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    if @PTipOpe = ''
      Set @PTipOpe = (Select Tip_Faturamento From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    if @PCodVdr = 0
      Set @PCodVdr = (Select IsNull(Cod_Vendedor,0) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    if @PCodOpe = 0
      Set @PCodOpe = (Select IsNull(Cod_VendTlmkt,0) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    if @PCodDig = 0
      Set @PCodDig = (Select IsNull(Cod_Digitador,0) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    if @PIdPolCom = 0
      Set @PIdPolCom = (Select IsNull(Id_PolCom,0) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    if @PCodPrz = 0
      Set @PCodPrz = (Select IsNull(Cod_Prz,0) From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
  end

if @PTipPedido = 'C'
  Set @pv_CodTipPed = 'COT'
else
  Set @pv_CodTipPed = 'PDV'

-- ajusta flags
if @PFlgBlqWms = 1         -- nunca usa WMS
  Set @PFlgUsaWms = 0
if @PFlgBlqPol = 1         -- nunca usa politica
  begin
    Set @pm_FlgUsaPolComPdv = 0
    Set @PIdPolCom = 0
  end

if @PCodOri = '' Set @PCodOri = 'A'   -- ???????
if @PTipOpe = '' Set @PTipOpe = 'FAT'

-----------------------------------------------------------------------------------------------------------------------------
if not Exists(Select Codigo From CLIEN Where Codigo = @PCodCli)
  begin
    if DATALENGTH(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + CHAR(13)
    Set @PMsgErr = 'Cliente inválido ('+cast(@PCodCli as varchar)+')'
  end

if not Exists(Select es.Num_CgcCpf From ENXES es Inner Join CLIEN cl on es.Cod_Estabe = @PCodEstabe and es.Num_CgcCpf = cl.Cgc_Cpf and es.Cod_Client = cl.Codigo Where cl.Codigo = @PCodCli)
  begin
    if DATALENGTH(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + CHAR(13)
    Set @PMsgErr = 'Configuração do Cliente('+cast(@PCodCli as varchar)+') no Estabelecimento('+cast(@PCodEstabe as varchar)+') inválido'
  end

if not Exists(Select Cod_Ope From TPOPE Where Cod_Ope = @PTipOpe and Tip_EntSai = 'S')
  begin
    if DATALENGTH(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + CHAR(13)
    Set @PMsgErr = 'Tipo de Operação inválido ('+@PTipOpe+')'
  end

-----------------------------------------------------------------------------------------------------------------------------
  
Select @PCodVdr = Case
                    When (@PCodVdr > 0) and exists(select 1 from VENDE where Codigo = @PCodVdr and Cod_TipVenBas <> 'TLM') then @PCodVdr
                    Else IsNull(es.Cod_Vendedor,0) 
                  End,
       @PCodOpe = Case
                    When @PCodOpe > 0 then @PCodOpe
                    When (@pm_FlgGerComOpeAtv = 1) and (IsNull(es.Cod_Operador,0) > 0) then IsNull(es.Cod_Operador,0)
                    When (@pm_FlgGerComOpeAtv = 1) and (@pm_CodOpeSemCom > 0) then @pm_CodOpeSemCom
                    When @pm_CodOpePdvCon > 0 then @pm_CodOpePdvCon
                    When @PCodDig > 0 then @PCodDig
                    Else 0
                  End,
       @PCodDig = Case
                    When @PCodDig > 0 then @PCodDig
                    When @pm_CodOpePdvCon > 0 then @pm_CodOpePdvCon
                    Else 0
                  End,
       @es_CodRegTri = IsNull(es.Cod_RegTri,0)
From CLIEN cl
     Left Join ENXES es on es.Cod_Estabe = @PCodEstabe and es.Num_CgcCpf = cl.Cgc_Cpf and es.Cod_Client = cl.Codigo
     Left Join RGTRI rg on es.Cod_RegTri = rg.Cod_RegTri
Where cl.Codigo = @PCodCli 
And es.Cod_Estabe = @PCodEstabe

-----------------------------------------------------------------------------------------------------------------------------------
-- ignora erro se @PIdPVMCB > 0
if @PIdPVMCB = 0
  begin
    if not Exists(Select Codigo
                  From VENDE 
    			  Where Codigo = @PCodVdr
                  And Cod_TipVenBas <> 'TLM')
      begin
        if DATALENGTH(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + CHAR(13)
        Set @PMsgErr = 'Vendedor inválido ('+cast(@PCodVdr as varchar)+')'
      end
    
    if not Exists(Select Codigo
                  From VENDE
    			  Where Codigo = @PCodOpe 
    			  And Cod_TipVenBas = 'TLM')
      begin
        if DATALENGTH(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + CHAR(13)
        Set @PMsgErr = 'Operador inválido ('+cast(@PCodOpe as varchar)+')'
      end
    
    if @es_CodRegTri = 0
      begin
        if DATALENGTH(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + CHAR(13)
        Set @PMsgErr = 'Região Tributária inválida ('+cast(@es_CodRegTri as varchar)+')'
      end
  end  -- if @PIdPVMCB = 0

if (@PCodDig > 0) and not Exists(Select Codigo From VENDE Where Codigo = @PCodDig And Cod_TipVenBas = 'TLM')
  begin
    Set @PCodDig = @PCodOpe
  end

-----------------------------------------------------------------------------------------------------------------------------------

Exec PR_AnalisaCreditoCliente @pv_CodTipPed, @PCodEstabe, @PCodCli, @PNumPdv, 
                              @WMsg output, @WSta output, @WStaLic output, @WCodMtv output
/*
      if WSta = 3 then raise Exception.Create(PChar('Venda bloqueada: '+WMsg1[0]));
*/

if @WCodAgeCob = 0
  Set @WCodAgeCob = Case
                     When (Exists (Select Cod_AgeCob From TPOPE Where Cod_Ope = @PTipOpe and Tip_EntSai = 'S' And IsNull(Cod_AgeCob,0) > 0)) then
                       (Select Cod_AgeCob From TPOPE Where Cod_Ope = @PTipOpe)
		             When (Exists (Select Cod_CfoNorInt From TPOPE Where Cod_Ope = @PTipOpe and Tip_EntSai = 'S' And IsNull(Cod_CfoNorInt,0) = 0)) and (@pm_FlgOrcAgeCobCar = 1) then 
				       @pm_CodAgeCobCar
                     Else 
				       (Select es.Cod_AgeCob From ENXES es Inner Join CLIEN cl on es.Cod_Estabe = @PCodEstabe and es.Num_CgcCpf = cl.Cgc_Cpf and es.Cod_Client = cl.Codigo
				        Where cl.Codigo = @PCodCli)
                     End

-- politica de comercialização
Set @WTipPrz = ''
if (@PIdPolCom > 0) or ((@pm_FlgUsaPolComPdv = 1) and (@PCodOri <> 'T'))  -- exceto pedido eletronico
  begin
    if @PIdPolCom = 0
      Set @PIdPolCom = dbo.FN_SugereIdPolComCli (@PCodOri, @WTipPrz, @PCodEstabe, @PCodCli, @PCodVdr, @PCodOpe, @PCodPrz)  -- aqui passava @PCodPrz = 0
    if @PIdPolCom = 0
      Set @PIdPolCom = dbo.FN_SugereIdPolComCli (@PCodOri, @WTipPrz, @PCodEstabe, @PCodCli, @PCodVdr, @PCodOpe, 0)
  end 

-- aqui, qdo for o caso sugere o prazo
if @PCodPrz > 0 
  if @pm_FlgUsaPolComPdv = 1
    begin
      if not Exists(Select Cod_TabPrz From PCXPZ Where Id_PolCom = @PIdPolCom And Cod_TabPrz = @PCodPrz)
        Set @PCodPrz = 0
    end
  else
    begin
      if not Exists(Select Cod_Prz From PRZCB Where Cod_Prz = @PCodPrz And Flg_ParOk = 1)
        Set @PCodPrz = 0
    end

----------------------------------------------------------------------------------------------------------------------------------------
BEGIN TRANSACTION

  if (@PMsgErr <> '') and 
     ((@PNumPdv > 0) and not Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv))
    Set @PNumPdv = 0
  else
  -- cria pedido
  if (@PMsgErr = '') and 
     ((@PNumPdv = 0) or not Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv))
    begin
      if @PNumPdv = 0
        begin
          EXEC PR_ProxNumero 'Pedido_Venda', @PNumPdv output
        end
  
      -- Status1 = 'P'     -- Pendente
      -- Status2 = 'A'     -- em aberto
      -- Tip_Pedido = 'P'  -- P=Pedido C=Cotacao
      Set @UsuInfarma = dbo.FN_UsuarioInfarma()
      Set @WDesLayPde = IsNull((Select Des_Layout From TBCLP Where Cod_Layout = @PCodLayPde),'')
      Set @WTipSaiPdv = dbo.FN_TipSaiPdv(@PTipOpe)
      Set @WTipGerVrb = dbo.FN_TipGerVrbPdv(@PIdPolCom)
      Set @WFlgMarkupCusCom =  dbo.FN_FlgMarkupPDVCB(@PIdPolCom)
  
      Insert Into PDVCB (Cod_Estabe, Numero, Cod_Cliente, Flg_WMS, Status1, Status2, Tip_Pedido, Tip_SaiPdv,
  	                   Tip_Faturamento, Cod_Vendedor, Cod_VendTlmkt, Cod_Digitador, Cod_OrigemPdv,
  	                   Cod_RegTri, Cod_Agente, Id_PolCom, Cod_Prz, Cod_LayoutPde, Des_LayoutPde,
                         Flg_Credito, Cod_BlqLic, Cod_MtvRej, Tip_GerVrb, Flg_MarkupCusCom,
                         Id_PVMCB, Dat_Pedido, Hor_Entrada, Usuario, Transacao)
  
                 Values (@PCodEstabe, @PNumPdv, @PCodCli, @PFlgUsaWms, 'P', 'A', @PTipPedido, @WTipSaiPdv, 
                         @PTipOpe, @PCodVdr, @PCodOpe, @PCodDig, @PCodOri,
                         @es_CodRegTri, @WCodAgeCob, @PIdPolCom, @PCodPrz, @PCodLayPde, @WDesLayPde,
                         @WSta, @WStaLic, @WCodMtv, @WTipGerVrb, @WFlgMarkupCusCom,
                         @PIdPVMCB, @Date, @Now, @UsuInfarma, @Now)
  
      if (@@error <> 0)
        begin
          if @@trancount > 0
  	      Rollback Transaction
  		Return
        end
    end  -- if (@PNumPdv = 0) or
  
  -- para pedidos Pendentes/Abertos
  if Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv)
    begin
      Exec PR_InfoDefaultPDVCB @PCodEstabe, @PNumPdv
    end

  if @@trancount > 0
    COMMIT TRANSACTION

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_InfoDefaultPDVIT]
@PFlgPolCom bit,           -- indica se utiliza politica de comercialização
@PCodEstabe int,           -- estabelecimento
@PNumPdv int,              -- numero pedido
@PCodPrd int,              -- produto
@PQtdPed int,              -- qtd pedido
@PQtdBon int,              -- qtd bonificacao
@PIdPolComIte int output,  -- politica de comercializaçãodo item : passa também parametro
@PFlgBlqDscAutIte bit,     -- bloqueia desconto automatico (Layout PDE)  -- TBLPG.Flg_BlqDscAutIte
-------------------------------------------------------------------------------------------------------
@PFlgAchou bit output,
@PLocFis varchar(15) output,                  -- somente registra
@PCodFab int output,                          -- somente registra 
@PPrcFab numeric(18,8) output,                -- somente registra
@PPrcMaxCon numeric(18,8) output,             -- somente registra
@PPrcRefFpb numeric(18,8) output,             -- somente registra
@PPrcTab numeric(18,8) output,
@PPrcTabBru numeric(18,8) output,             -- somente registra

@PFatCnvImpFat smallint output,               -- somente registra
@PPrcUni numeric(18,8) output,

@PPrcCusMinComMarkup numeric(18,8) output,    -- usado somene na critica
@PPerDscPolCom numeric(7,4) output,
@PPerDscVisPolCom numeric(7,4) output,
@PPrcPolCom numeric(18,8) output,
@PQtdPrzPolCom int output,
@PFlgGerVrbIte bit output,           -- PDVIT.Flg_Verba: indica se gera verba p/ acumular, não gera e usa verba no pedido
@PFlgPolPrm bit output,
@PCodKitPrm int output,
@PCodPromoc int output,
@PFlgEmbDscPrc bit output,           -- PDVIT.Flg_PrcUniDsc: embute desconto no preço  NPOL (nao politica)  
@PQtdPrzMax int output,              -- PDVIT.Qtd_PrzMax
@PPerDscLin numeric(7,4) output,     -- PDVIT.Per_Desconto: desconto prazo "linear"
@PPerDscPrz numeric(7,4) output,     -- PDVIT.Per_Descon: desconto prazo "fabricante" prazo
@PPerDscVis numeric(7,4) output,     -- PDVIT.Per_DscVis: desconto prazo "fabricante" vista
@PPrcUniLiqPer numeric(18,8) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Date smalldatetime

Set @Date = cast(GetDate() as Date)

BEGIN TRANSACTION

  Declare @WFlgBlqDscExt bit = 0,     -- Bloqueia desconto extra
          @WQtdPrzIte int = 0,

          @PFlgPromoc bit,        
          @PDesPromoc varchar(30),
          @PFlgBlqCtrQtdPromoc bit,
          @PQtdEstPromoc int,
          @PQtdMinPromoc int,
          @PDatEncPromoc smalldatetime,   
          @PDatVctLotPromoc smalldatetime,
          @PQtdPrzPromoc int,
          @PPerDscPromoc decimal(7,4),
          @PPerBonPromoc decimal(7,4),
          @PPrcPromoc decimal(18,8)

  Declare @WPerDscMax numeric(7,4),
          @WPerDscAut numeric(7,4),
          @WPrcUni numeric(18,8),
          @WPrcTabAux numeric(18,8),
          @WPerDscPrzIte numeric(7,4),
          @WPerDscVisIte numeric(7,4),
          @WPerDscTabSug numeric(7,4),
          @WTipPrz varchar(1),
          @WPrcUniLiqPromoc numeric(18,8),
          @WPrcUniLiqPolCom numeric(18,8),
          @WPrcUniLiqPdv numeric(18,8),
          @WQtdMaxCfg int

  Declare @pr_PrcVenda numeric(18,8),
          @pr_PrcCustoMedio numeric(18,8),
          @pr_PrcCusMedCom numeric(18,8),
          @pr_PrcCusLiqEnt numeric(18,8),
          @pr_PrcUltEnt numeric(18,8),
          @pr_PerDscUltEnt numeric(7,4),
          @pr_FlgBlqDsc bit,
          @pr_CodCla varchar(7),
          @pr_PerBonAut numeric(7,4),
          @pr_PerDscAut numeric(7,4),
          @pr_PerDscAutOrc numeric(7,4),
          @pr_CodPromoc int,
          @pr_QtdDispon int,
          @pr_QtdPromocDispon int,

          @fb_PerDscMax numeric(7,4),

          @pv_DatPedido smalldatetime,
          @pv_TipPdv varchar(1),  
          @pv_CodOriPdv varchar(2),
          @pv_TipFat varchar(3),   
          @pv_CodCli int, 
          @pv_CodVdr int, 
          @pv_CodOpe int,
          @pv_IdPolCom int,

          @pv_TipRatBon varchar(1),
          @pv_FlgMarkupCusCom bit,
          @pv_CodTabPrc int,   
          @pv_QtdPrzPdv int,
          @pv_PerDscPrzPdv numeric(7,4),
          @pv_PerDscVisPdv numeric(7,4),
          @pv_TipGerVrb varchar(1),
          @pv_FlgMrkCusCom bit, 

          @op_TipPrc varchar(1),
          @op_FlgOrc bit = 0,
          @cl_CodUf varchar(2), 
          @cl_FlgConFin bit,   
          @cl_FlgBlqEmbDscItePrcUni bit,
          @cl_FlgBlqDscPrmExtVenVis bit,

          @pe_CodLayPde int,
          @pe_CodGrpPde int,

          --@pc_FlgBlqVerba bit,

          @pm_QtdDecPrcItePdv smallint,
          @pm_FlgTabPrcConFin bit,
          @pm_FlgEmbDscItePrcUni bit,
          @pm_FlgSugPrmPdv bit,
          @pm_FlgNaoSugDscItePdv bit,
          @pm_PerDscPrmExtVenVis numeric(7,4),
          @pm_FlgCtrDscIte bit,      
          @pm_PerMaxDscIte numeric(7,4)

  Set @PFlgAchou = 0
  Set @PLocFis = ''

  Set @PCodFab = 0
  Set @PQtdPrzMax = 0

  Set @PPrcFab = 0
  Set @PPrcMaxCon = 0
  Set @PPrcRefFpb = 0
  Set @PPrcTab = 0
  Set @PPrcTabBru = 0
  Set @PPrcUni = 0
  Set @PPrcUniLiqPer = 0
  Set @PPrcPolCom = 0
  Set @PPrcCusMinComMarkup = 0
  Set @PFatCnvImpFat = 1

  Set @PPerDscLin = 0
  Set @PPerDscPrz = 0
  Set @PPerDscVis = 0
  Set @PQtdPrzPolCom = 0
  Set @PPerDscPolCom = 0
  Set @PPerDscVisPolCom = 0

  Set @PCodKitPrm = 0
  Set @PCodPromoc = 0
  Set @PFlgGerVrbIte = 0
  Set @PFlgPolPrm = 0
  Set @PFlgPromoc = 0
  Set @PDesPromoc = 0
  Set @PFlgBlqCtrQtdPromoc = 0
  Set @PQtdEstPromoc = 0
  Set @PDatEncPromoc = 0
  Set @PDatVctLotPromoc = 0
  Set @PQtdMinPromoc = 0
  Set @PQtdPrzPromoc = 0
  Set @PPerDscPromoc = 0
  Set @PPerBonPromoc = 0
  Set @PPrcPromoc = 0
  Set @PFlgEmbDscPrc = 0

    -- Status1 = 'P'     -- Pendente
    -- Status2 = 'A','X' -- em aberto 

  if Exists(Select 1 From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv And ((Status2 = 'A') or (Status2 = 'X'))) and
     Exists(Select 1 From PRXES pr Inner Join PRODU p on pr.Cod_Produt = p.Codigo Where pr.Cod_Estabe = @PCodEstabe And pr.Cod_Produt = @PCodPrd)
    begin
      Select @PFlgAchou       = 1,
	         @PLocFis            = IsNull(d.Cod_LocFis,''),   
	         @pr_CodCla          = IsNull(p.Cod_Classif,''), 
			 @PCodFab            = IsNull(p.Cod_Fabricante,0),   
			 @PPrcFab            = IsNull(pr.Prc_Fabric,0),      
			 @PPrcMaxCon         = IsNull(pr.Prc_MaxCon,0),      
			 @PPrcRefFpb         = IsNull(p.Prc_RefFpb,0),       
			 @pr_PrcVenda        = IsNull(pr.Prc_Venda,0), 
			 @pr_FlgBlqDsc       = IsNull(pr.Flg_BlqDsc,0), 
			 @pr_PerBonAut       = IsNull(pr.Per_BonAut,0), 
			 @pr_PerDscAut       = IsNull(pr.Per_DscAut,0), 
			 @pr_PerDscAutOrc    = IsNull(pr.Per_DscAutOrc,0), 
             @pr_PrcCustoMedio   = IsNull(pr.Prc_CusMed,0),   
			 @pr_PrcCusMedCom    = IsNull(pr.Prc_CusMedCom,0), 
			 @pr_PrcCusLiqEnt    = IsNull(pr.Prc_CusLiqEnt,0), 
			 @pr_PrcUltEnt       = IsNull(pr.Prc_UltEnt,0), 
			 @pr_PerDscUltEnt    = IsNull(pr.Per_DscUltEnt,0),
             @pr_CodPromoc       = IsNull(pr.Cod_Promocao,0),
             @pr_QtdDispon       = dbo.FN_EstoqueDisponivelPrd(pr.Cod_Estabe,pr.Cod_Produt),
             @pr_QtdPromocDispon = IsNull(pr.Qtd_PrmDispon,0),
			 @fb_PerDscMax       = Case 
                                     When IsNull(fb.Per_DscMaxVis,0) > IsNull(fb.Per_DscMaxPrz,0) then IsNull(fb.Per_DscMaxVis,0)
                                     Else IsNull(fb.Per_DscMaxPrz,0) 
                                   End
        From PRXES pr 
             Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
             Left Join FABRI fb on p.Cod_Fabricante = fb.Codigo
             Left Outer Join DPXPR d ON ((pr.Cod_Estabe = d.Cod_Estabe) and (pr.Cod_Produt = d.Cod_Produt) and 
                                          d.Cod_Dep = (Select Min(Cod_Dep) FROM DPXPR 
                                                       Where Cod_Estabe = @PCodEstabe
                                                       And Cod_Produt = pr.Cod_Produt)) 
        Where pr.Cod_Estabe = @PCodEstabe
        And pr.Cod_Produt = @PCodPrd


      -- parametros na memoria
      Select @pm_QtdDecPrcItePdv    = IsNull(QtdDecPrcItePdv,2),
             @pm_FlgTabPrcConFin    = IsNull(FlgTabPrcConFin,0),
             @pm_FlgEmbDscItePrcUni = IsNull(FlgEmbDscItePrcUni,0),
             @pm_FlgSugPrmPdv       = IsNull(FlgSugPrmPdv,0),
             @pm_FlgNaoSugDscItePdv = IsNull(FlgNaoSugDscItePdv,0),
             @pm_PerDscPrmExtVenVis = IsNull(PerDscPrmExtVenVis,0),
             @pm_FlgCtrDscIte       = IsNull(FlgCtrDscIte,0),
             @pm_PerMaxDscIte       = IsNull(PerMaxDscIte,0)
        From PARAM
        Where Cod_Estabe = @PCodEstabe

      -- coloca PDVCB na memoria
      Select @pv_DatPedido    = IsNull(cb.Dat_Pedido,@Date),
	         @pv_TipPdv       = IsNull(cb.Tip_Pedido,''),
             @pv_CodOriPdv    = IsNull(cb.Cod_OrigemPdv,''),
             @pv_TipFat       = IsNull(cb.Tip_Faturamento,''),
             @pv_CodCli       = IsNull(cb.Cod_Cliente,0),
			 @pv_IdPolCom     = IsNull(cb.Id_PolCom,0),

			 @pv_CodVdr       = IsNull(cb.Cod_Vendedor,0),
			 @pv_CodOpe       = IsNull(cb.Cod_VendTlmkt,0),

             @pv_TipRatBon    = IsNull(cb.Tip_RatBon,''),
             @pv_FlgMarkupCusCom = IsNull(cb.Flg_MarkupCusCom,0),
             @pv_CodTabPrc    = IsNull(cb.Cod_TabPrc,0),
--             @pv_QtdPrzPdv    = IsNull(cb.Qtd_Prz,0),
             @pv_QtdPrzPdv    = Cast(IsNull(cb.Qtd_PrzMed,0) as int),
             @pv_PerDscPrzPdv = IsNull(cb.Per_DscPrz,0),
             @pv_PerDscVisPdv = IsNull(cb.Per_DscVis,0),
             @pv_TipGerVrb    = IsNull(cb.Tip_GerVrb,'X'),
             @pv_FlgMrkCusCom = IsNull(cb.Flg_MarkupCusCom,0), 
             @op_TipPrc       = IsNull(op.Tip_Prc,''),
             @op_FlgOrc       = Case
                                  When IsNull(op.Cod_CfoNorInt,0) = 0 then 1
                                  Else 0
                                End,
             @cl_CodUf        = IsNull(cl.Cod_Estado,''),
             @cl_FlgConFin    = Case When (IsNull(cl.Tipo_Consumidor,'') = 'F') and (@pm_FlgTabPrcConFin = 1) then 1 Else 0 End,
             @cl_FlgBlqEmbDscItePrcUni = IsNull(en.Flg_BlqEmbDscItePrcUni,0),
             @cl_FlgBlqDscPrmExtVenVis = IsNull(Flg_BlqDscPrmExtVenVis,0),

             @pe_CodLayPde = IsNull(pe.Cod_Layout,0),
             @pe_CodGrpPde = IsNull(pe.Cod_GrpClp,0)

        From PDVCB cb
             Left Join TPOPE op on cb.Tip_Faturamento = op.Cod_Ope
             Left Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
             Left Join ENXES en on cb.Cod_Estabe = en.Cod_Estabe and cl.Cgc_Cpf = en.Num_CgcCpf and cl.Codigo = en.Cod_Client
             Outer Apply (Select top 1 p.Cod_Layout, p.Cod_GrpClp 
                            From PDECB p 
                           Where p.Cod_Estabe = cb.Cod_Estabe
                             And p.Num_PedVen = cb.Numero
                           Order by p.Isn_Arquiv desc) pe
        Where cb.Cod_Estabe = @PCodEstabe
        And cb.NUmero = @PNumPdv


      -- guarda o tipo de prazo: (F)abricante, (L)inear
      Set @WTipPrz = Substring(@pv_CodOriPdv,2,1)            
      if Ltrim(Rtrim(@WTipPrz)) = '' Set @WTipPrz = 'L'      

      -- embute desconto no preço
      if (@pm_FlgEmbDscItePrcUni = 1) and (@cl_FlgBlqEmbDscItePrcUni = 0)  
        Set @PFlgEmbDscPrc = 1 

      Set @WFlgBlqDscExt = 0  --@cl_FlgBlqDscPrmExtVenVis
      Set @WPrcUniLiqPromoc = 0
      Set @WPrcUniLiqPolCom = 0

      -- pr.bruto
      Set @PPrcTabBru = @pr_PrcVenda    

      -- desconto automatico do produto (p/ preco do cadastro)
      Set @WPerDscAut = 0
      if @pr_PerBonAut = 0
        if Upper(LTrim(RTrim(@pv_TipFat))) = 'ORC'
          Set @WPerDscAut = @pr_PerDscAutOrc
        else
          Set @WPerDscAut = @pr_PerDscAut
      if IsNull(@PFlgBlqDscAutIte,0) = 1   -- PARAM ????
        Set @WPerDscAut = 0


      -- inicializa
      --Set @pc_FlgBlqVerba  = 0
      Set @PPrcCusMinComMarkup = 0

-------------------------------------------------------------------------------------------------------------------------
      if @PFlgPolCom = 1
        begin
          if @PIdPolComIte = 0 
            Set @PIdPolComIte = dbo.FN_SugerePoliticaProduto(Substring(@pv_CodOriPdv,1,1),
                                                             @PCodEstabe,
                                                             @pv_CodCli, @pv_CodVdr, @pv_CodOpe,
                                                             @pv_IdPolCom, @PCodPrd, @PQtdPed,
                                                             @pe_CodLayPde, @pe_CodGrpPde)

          -- nem sempre a politica do cabeçalho atende ao item
          if (@PIdPolComIte = 0) and
             (dbo.FN_PoliticaProdutoValida(@PCodEstabe, Substring(@pv_CodOriPdv,1,1), @pv_IdPolCom, @PCodPrd) = 1)		   
		    Set @PIdPolComIte = @pv_IdPolCom 

          --Set @pv_CodTabPrc = IsNull((Select Cod_TabPrc From POCOM Where Id_PolCom = @PIdPolComIte),0)

          if Exists(Select 1 From POCOM Where Id_PolCom = @PIdPolComIte)
            begin
             -- Select @pc_FlgBlqVerba = Case 
             --                            When (IsNull(pc.Flg_AcuVrbPos,0) = 0) and (IsNull(pc.Flg_AcuVrbNeg,0) = 0) then 1 
             --                            Else 0 
             --                          End,
              Select @PFlgGerVrbIte = Case 
                                       When (IsNull(pc.Flg_NegDsc,0) = 1) and (IsNull(pc.Flg_GerVrbPdv,0) = 0) and    -- negocia desconto e não gera e usa verba exclusivamente no pedido
                                            ((IsNull(pc.Flg_AcuVrbPos,0) = 1) or (IsNull(pc.Flg_AcuVrbNeg,0) = 1)) then 1 
                                       Else 0 
                                     End,
                     --@pc_FlgBlqVerba  = IsNull(pc.Flg_BlqVerba,0),
                     @PFlgPolPrm = IsNull(pc.Flg_BlqCli,0), 
                     @PPrcCusMinComMarkup = Case
                                              When (@pv_TipGerVrb <> 'P') and 
                                                   ( (IsNull(pc.Flg_MarkupCusCom,0) = 1) or (@pv_TipRatBon <> '') ) then dbo.FN_PrcMinCom(@PCodEstabe,@PCodPrd)
                                              Else 0
                                            End
                From POCOM pc 
               Where pc.Id_PolCom = @PIdPolComIte
       
            end  -- if Exists(Select 1 From POCOM Where Id_PolCom = @PIdPolComIte)
       
        end  -- if @PFlgPolCom = 1
-------------------------------------------------------------------------------------------------------------------------

      -- Pr. Tabela
      Set @PPrcTab = dbo.FN_PrecoTabelaProduto(@pv_CodCli, @PCodEstabe, @PCodPrd, @PIdPolComIte, @pv_CodTabPrc, @op_FlgOrc, @PFlgBlqDscAutIte)

      Set @PFatCnvImpFat = 1    
      Set @WPerDscMax = 0   -- desconto maximo permitido (para calculo Pr.Permitido) 
      Set @WPerDscTabSug = 0                                        

      Set @WPrcUni = @PPrcTab   -- aquix ?????  o preço de tabela pode estar com desconto embutido (TPXPR)
      Set @WPrcUniLiqPdv = 0          

      -- preço unitario
      if @cl_FlgConFin = 0 
        begin
          --if @PFlgPrcDif = 1
          --Set @WPrcUni = @PPrcTab
          --Set @WPrcUni = ProduCds.FieldByName('H_PrcVen').AsFloat
          --else             
          if @op_TipPrc = 'V' 
            begin
              Set @WPrcUni = @PPrcTab
            end
          else
          if @op_TipPrc = 'M'
            begin
              if @pr_PrcCusMedCom > 0 
                Set @WPrcUni = @pr_PrcCusMedCom  -- custo medio comercial
              else
                Set @WPrcUni = @pr_PrcCustoMedio
              Set @WPerDscMax = 0
            end
          else
          if @op_TipPrc = 'C'
            begin
              Set @WPrcUni = @pr_PrcCusLiqEnt
              Set @WPerDscMax = 0
             end
          else
          if @op_TipPrc = 'E'
            begin
              Set @WPrcUni = @pr_PrcUltEnt*(1-@pr_PerDscUltEnt/100)
              Set @WPerDscMax = 0
             end
        end
      else
        begin
          Set @WPrcUni = @PPrcTab
          Set @WPerDscMax = 0
        end
   
-------------------------------------------------------------------------------------------------------------------------
      if @PFlgPolCom = 0
        begin
          Set @PIdPolComIte = 0  

          -- promocao
          Exec PR_ProdutoEmPromocao @PCodEstabe, @pr_CodPromoc, @PCodPrd, @cl_CodUf,
                                    @PFlgPromoc output, @PDesPromoc output, @PDatEncPromoc output, @PDatVctLotPromoc output, @PQtdMinPromoc output,
                                    @PQtdPrzPromoc output, @PPerDscPromoc output, @PPerBonPromoc output, @PPrcPromoc output, @PFlgBlqCtrQtdPromoc output
          if @PFlgPromoc = 1
            begin
              if @PFlgBlqCtrQtdPromoc = 1
                Set @PQtdEstPromoc = @pr_QtdDispon
              else
                Set @PQtdEstPromoc = @pr_QtdPromocDispon
            end

          Set @WQtdPrzIte = @pv_QtdPrzPdv  

          if @WTipPrz = 'L'     -- prazo linear
            begin
              -- politica de comercializacao = 0
              Set @PQtdPrzMax = 0     --@pv_QtdPrzPdv ????
              Set @PPerDscPrz = 0
              Set @PPerDscVis = 0
        
              if @op_TipPrc = 'V' 
                begin
                  if @fb_PerDscMax > @WPerDscMax
                    Set @WPerDscMax = @fb_PerDscMax
                  if @pm_FlgCtrDscIte = 0
                    if @pm_PerMaxDscIte = 0 
                      Set @WPerDscMax = 99
                   else
                      if @pm_PerMaxDscIte > @WPerDscMax
                        Set @WPerDscMax = @pm_PerMaxDscIte
                 
                  -- sugere promocao automatica
                  if (@pm_FlgSugPrmPdv = 1) and
                     (@PFlgPromoc = 1) and (@op_TipPrc = 'V') and (@PQtdEstPromoc > 0) and
                     ((@pr_QtdPromocDispon > 0) or (@PFlgBlqCtrQtdPromoc = 1)) and
                     (@pr_FlgBlqDsc = 0) 
                    begin
                      if @PPerDscPromoc > 0
                        Set @PPerDscLin = @PPerDscPromoc
                      else
                      if @PPrcPromoc > 0 
                        Set @WPrcUni = @PPrcPromoc
                    end
                  else
                    begin
                      Set @WPerDscTabSug = 0

                      if (@pv_CodTabPrc > 0) and            
                         Exists(Select 1 From TPXPR it 
                                              Inner Join TBPRC cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_TabPrc = cb.Cod_TabPrc 
                                 Where it.Cod_TabPrc = @pv_CodTabPrc
                                   And it.Cod_Produt = @PCodPrd
                                   And ((cb.Cod_Estabe = @PCodEstabe) or (cb.Flg_AllEstabe = 1)))
                        begin
                          Select @WPerDscTabSug = Case 
                                                    When IsNull(cb.Flg_IniDsc,0) = 1 then IsNull(it.Per_DscMax,0)
                                                    Else 0
                                                  End
                            From TPXPR it 
                                 Inner Join TBPRC cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_TabPrc = cb.Cod_TabPrc 
                           Where it.Cod_TabPrc = @pv_CodTabPrc
                             And it.Cod_Produt = @PCodPrd
                             And ((cb.Cod_Estabe = @PCodEstabe) or (cb.Flg_AllEstabe = 1))
                        end
                      
                       -- sugere desconto da tabela de preços
                      if (@WPerDscTabSug > 0) and (@pr_FlgBlqDsc = 0) 
                        Set @PPerDscLin = @WPerDscTabSug
                    end
                 
                end  -- if @op_TipPrc = 'V'
        
              -- calcula @WPrcUniLiqPdv
              Set @WPrcUni = Round(@WPrcUni,@pm_QtdDecPrcItePdv)
              Set @WPrcUniLiqPdv = @WPrcUni*(1-@PPerDscLin/100)
        
            end -- if @WTipPrz = 'L'
          else
            begin  -- if @WTipPrz = 'F': prazo fabricante - quando alterar aqui ver rotina de reprocessamento de comercializacao de itens
              Set @PPerDscLin = 0

              if @op_TipPrc = 'V' 
                begin
                  -- cond. comercializacao padrao
                  Exec PR_PdvitConComDef @PCodEstabe, @PCodPrd, @pv_CodCli, @pv_QtdPrzPdv, @pv_PerDscPrzPdv, @pv_PerDscVisPdv,
                                          @WQtdPrzIte output, @WPerDscPrzIte output, @WPerDscVisIte output
                
                  Set @PQtdPrzMax = @WQtdPrzIte
                  Set @PPerDscPrz = @WPerDscPrzIte
                  Set @PPerDscVis = @WPerDscVisIte
                
                  -- sugere promocao automatica
                  if (@pm_FlgSugPrmPdv = 1) and
                     (@PFlgPromoc = 1) and (@op_TipPrc = 'V') and
                     ((@pr_QtdPromocDispon > 0) or (@PFlgBlqCtrQtdPromoc = 1)) and
                     (@pr_FlgBlqDsc = 0) 
                    begin
                      if @PQtdPrzPromoc > 0 
                        Set @PQtdPrzMax = @PQtdPrzPromoc
                      if @PPerDscPromoc > 0
                        begin
                          Set @PPerDscPrz = @PPerDscPromoc
                          Set @PPerDscVis = @PPerDscPromoc
                          -- desconto adicional em venda a vista se configurado nas opcoes do sistema
                          -- se existir uma condicao pre-existente na venda a vista
                          if (@pm_PerDscPrmExtVenVis > 0) and
                             (@WPerDscVisIte > 0) and (@WFlgBlqDscExt = 0) 
                            -- (D1+D2) - (D1*D2)/100
                          Set @PPerDscVis = Round((@PPerDscPromoc+@pm_PerDscPrmExtVenVis) - (@PPerDscPromoc*@pm_PerDscPrmExtVenVis)/100,2)
                        end
                      else
                      if @PPrcPromoc > 0 
                        begin
                          Set @WPrcUni = @PPrcPromoc
                
                          Set @PPerDscPrz = 0
                          Set @PPerDscVis = 0
                          -- desconto adicional em venda a vista se configurado nas opcoes do sistema
                          -- se existir uma condicao pre-existente na venda a vista
                          if (@pm_PerDscPrmExtVenVis > 0) and
                             (@WPerDscVisIte > 0) and (@WFlgBlqDscExt = 0) 
                            Set @PPerDscVis = Round(@pm_PerDscPrmExtVenVis,2)
                        end
                
                    end  -- if (@pm_FlgSugPrmPdv = 1) and

                end  -- if @op_TipPrc = 'V'

              -- calcula @WPrcUniLiqPdv
              Set @WPrcUni = Round(@WPrcUni,@pm_QtdDecPrcItePdv)
              Set @WPrcUniLiqPdv = @WPrcUni*(1-@PPerDscPrz/100)

            end  -- if @WTipPrz = 'F'     -- prazo fabricante

          -- calcula preco progressivo
          --CalculaPrcUnitarioPdvit(PIteDts,PPsqDts,@pv_TipFat,@op_TipPrc,PEstCli,@pv_CodTabPrc,
          --                         @WQtdPrzIte, @WQtdPrzIte,PdvcbCds.FieldByName('Flg_TabProgres').AsBoolean,@cl_FlgConFin,PFlgPrcDif,true);

         Set @PPrcUni = @WPrcUni

        end  -- if @PFlgPolCom = 0
------------------------------------------------------------------------------------------------------------------------------------------------

      if @PFlgPolCom = 1
        begin
          -- promocao
          Set @PCodKitPrm = dbo.FN_IdKitPromocao(@PIdPolComIte)

          -- calcula preco progressivo
          --CalculaPrcUnitarioPdvit(PPsqPrd,PPsqDts,PTipFat,PTipPrc,PEstCli,PCodTabPrc,
          --                        PQtdPrzMax,PQtdPrzMax,PdvcbCds.FieldByName('Flg_TabProgres').AsBoolean,false,false,true);

          -- condicoes da politica: define preço unitario/desconto conforme politica de comercializacao
          -- na digitacao do pedido o preço já é sugerido e pode ser alterado
		  -- o parametro em PR_PrcPrdPolitica pede preço de tabela
		  -- @WPrcUni já pode estar com % de desconto automatico do produto e da politica
		  -- @PPrcTab já está com desconto automatico do produto e da politica
          if (@cl_FlgConFin = 0) and (@op_TipPrc <> 'V')
		    Set @WPrcTabAux = @WPrcUni
          else
		    Set @WPrcTabAux = @pr_PrcVenda*(1-@WPerDscAut/100)  -- aqui deve ser preço do produto com seu desconto automatico....
          if @PQtdPed > 0
            Exec PR_PrcPrdPolitica @pv_CodCli, @PCodEstabe, @PCodPrd, @PIdPolComIte, @PQtdPed, @WPrcTabAux, @pv_DatPedido,
                                   @PPrcUni output, @PQtdPrzMax output, @PPerDscPrz output, @PPerDscVis output, @WQtdMaxCfg output

          -- calcula @WPrcUniLiqPdv
          if @PPrcUni = 0
            Set @PPrcUni = @WPrcUni
          Set @PPrcUni = Round(@PPrcUni,@pm_QtdDecPrcItePdv)
          Set @WPrcUniLiqPdv = @PPrcUni*(1-@PPerDscPrz/100)

--          if IsNull(@pc_FlgBlqVerba,0) = 0
--            Set @PFlgVerba = 1
--          else
--            Set @PFlgVerba = 0

          Set @PQtdPrzPolCom = IsNull(@PQtdPrzMax,0)
--          Set @PPrcPolCom = IsNull(@WPrcUni,0)  alterado em 23/07/2020
          Set @PPrcPolCom = IsNull(@PPrcUni,0)
          Set @PPerDscPolCom = IsNull(@PPerDscPrz,0)
          Set @PPerDscVisPolCom = IsNull(@PPerDscVis,0)
          if @pv_TipPdv = 'C'
            Set @PPerDscLin = IsNull(@PPerDscPrz,0)

          if @PPerDscVisPolCom < @PPerDscPolCom
            Set @PPerDscVisPolCom = @PPerDscPolCom

        end  -- if @PFlgPolCom = 1

      -- produto bloqueado para descontos
      if (@pr_FlgBlqDsc = 1) or (@pm_FlgNaoSugDscItePdv = 1) 
        begin
          Set @PPerDscLin    = 0     
          Set @PPerDscPrz    = 0     
          Set @PPerDscVis    = 0     

          --if @pv_FlgMrkCusCom = 0
          Set @PFlgGerVrbIte  = 0

          Set @PPrcPolCom    = 0
          Set @PPerDscPolCom = 0
          Set @PPerDscVisPolCom = 0
        end

      -- desconto a vista nao pode ser menor que desc. a prazo
      if @PPerDscVis < @PPerDscPrz      
        Set @PPerDscVis = @PPerDscPrz

      -- desconto maximo
      if @WPerDscTabSug > @WPerDscMax
        Set @WPerDscMax = @WPerDscTabSug

	  if @PPerDscLin > @WPerDscMax
        Set @WPerDscMax = @PPerDscLin
      if @PPerDscVis > @WPerDscMax
        Set @WPerDscMax = @PPerDscVis

      if @PPerDscPromoc > @WPerDscMax
        Set @WPerDscMax = @PPerDscPromoc

      -- preco minimo permitido ------
	  if (@PPrcUni > 0) and (@PPrcUni < @WPrcUni)
        Set @WPrcUni = @PPrcUni

      Set @PPrcUniLiqPer = @WPrcUni*(1-@WPerDscMax/100)

      -- calcula preco minimo politica liquido
      Set @WPrcUniLiqPolCom = @PPrcPolCom*(1-@PPerDscVisPolCom/100)
      if (@WPrcUniLiqPolCom > 0) and (@WPrcUniLiqPolCom < @PPrcUniLiqPer)
        Set @PPrcUniLiqPer = @WPrcUniLiqPolCom

      -- calcula preco minimo promocional liquido
      Set @WPrcUniLiqPromoc = @PPrcPromoc*(1-@PPerDscPromoc/100)
      if (@WPrcUniLiqPromoc > 0) and (@WPrcUniLiqPromoc < @PPrcUniLiqPer)
        Set @PPrcUniLiqPer = @WPrcUniLiqPromoc

      -- verifica se venda foi da promocao
      Set @PCodPromoc = 0
      if @PFlgPromoc = 1
        Set @PCodPromoc = @pr_CodPromoc  
/*
      if @PFlgPromoc = 1
        begin
          if @PQtdBon > 0 
            Set @PCodPromoc = @pr_CodPromoc  
          else
          if @WPrcUniLiqPromoc > 0 
            if (Round(@WPrcUniLiqPdv,4) >= Round(@WPrcUniLiqPromoc,4)) and
               (Round(@WPrcUniLiqPdv,4) < Round(@PPrcTab,4)) and
               (Round(@WPrcUniLiqPdv,4) <= Round(@PPrcUniLiqPer,4)) 
              Set @PCodPromoc = @pr_CodPromoc
        end
*/

    end   -- if @PCodPrd > 0

COMMIT TRANSACTION
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraPdvRemConsig]
@PCodEstabe int, 
@PIdConsig int, 
@PNumSequen int,
@PTipOpe varchar(3),
@PNumPdv int output,
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now  smalldatetime = GetDate(),
        @Date smalldatetime = cast(GetDate() as Date)

Set @PNumPdv = 0
Set @PMsgErr = ''

if not Exists(Select 1 
                From CNGCB 
               Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig And Sta_Consig = 'P') 
  Set @PMsgErr = 'Contrato de Consignação não está "pendente"'
else
if not Exists(Select 1 
                From CNGCB cb
                     Inner Join CLIEN cl on cb.Cod_TipCng = 'C' and cb.Cod_Entida = cl.Codigo 
               Where cb.Cod_Estabe = @PCodEstabe And cb.Id_Consig = @PIdConsig)
  Set @PMsgErr = 'Clinte inválido'
else
if not Exists(Select 1 
                From CNGRC 
               Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig And Num_Sequen = @PNumSequen And Sta_CngPed = '1') 
  Set @PMsgErr = 'Não existe pedido a gerar'
else
if not Exists(Select 1 
                From CNGRI it 
               Where it.Cod_Estabe = @PCodEstabe And it.Id_Consig = @PIdConsig and it.Num_Sequen = @PNumSequen
                 And it.Qtd_Pedido > 0)
  Set @PMsgErr = 'Não existe itens a gerar'
else
if not Exists(Select 1 
                From CNGRI it 
                     Inner Join PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produt = pr.Cod_Produt 
               Where it.Cod_Estabe = @PCodEstabe And it.Id_Consig = @PIdConsig and it.Num_Sequen = @PNumSequen)
  Set @PMsgErr = 'Não existe itens a gerar'
else
if Exists(Select 1 
            From PDVCB 
           Where Cod_Estabe = @PCodEstabe and Id_Consig = @PIdConsig and Num_SequenciaCtr = @PNumSequen)
  Select @PMsgErr = 'Pedido ('+cast(Numero as varchar)+') já havia sido gerado'
    From PDVCB 
   Where Cod_Estabe = @PCodEstabe and Id_Consig = @PIdConsig and Num_SequenciaCtr = @PNumSequen
else
if not Exists(Select 1 
                From TPOPE 
               Where Tip_EntSai = 'S' and Cod_CfoNorInt = 5917 and Cod_CfoNorExt = 6917
                 And Cod_Ope = @PTipOpe And Tip_Ope = 'O')
  Set @PMsgErr = 'Tipo de operação (O/5917/6917) inválido para Remessa em Consignação'
else
  begin

    BEGIN TRANSACTION

    Declare @ct_CodCli int,
            @ct_IdPolCom int, 
            @ct_CodVended int,
            @ct_CodOperad int,
            @ct_CodDigita int,
--            @ct_PerComVnd numeric(8,4),

            @pm_FlgUsaPolComPdv bit,
            @pm_FlgAltUnvItePdv bit, 
            @pm_FlgRegDscCliItePdv bit,

            @WFlgUsaWms bit,
            @WFlgBlqWms bit, 
            @WFlgBlqPol bit,
            @WCodTabPrz int, 
            @WCodLayout int,
            @WFlgBlqDscAutIte bit,
            @WFlgCriVrb bit,
            @WFlgBlqQtdPar bit, 

            @WFlgSnhEsp bit,          
            @WFlgNaoCriConCom bit,    
            @WFlgBlqCriPrcVen bit,
            @WNomUsuSnhEsp varchar(35)

    Select @pm_FlgAltUnvItePdv = IsNull(FlgAltUnvItePdv,0), 
           @pm_FlgRegDscCliItePdv = IsNull(FlgRegDscCliItePdv,0),
           @pm_FlgUsaPolComPdv = IsNull(FlgUsaPolComPdv,0)
      From PARAM
     Where Cod_Estabe = @PCodEstabe

    Select @ct_CodCli = cl.Codigo,
           @ct_IdPolCom = IsNull(ct.Id_PolCom,0),
           @ct_CodVended = ct.Cod_Vended, 
           @ct_CodOperad = ct.Cod_Operad, 
           @ct_CodDigita = ct.Cod_Digita 
	  From CNGCB ct
           Inner Join CLIEN cl on ct.Cod_TipCng = 'C' and ct.Cod_Entida = cl.Codigo 
     Where ct.Cod_Estabe = @PCodEstabe and ct.Id_Consig = @PIdConsig

    -- WMS
    Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
                                              HASHBYTES('MD5',(Select Num_Cnpj From ESTAB Where Cod_Estabe = @PCodEstabe))))

    Set @WFlgBlqWms = 0
    Set @WFlgBlqPol = 0
    Set @WCodTabPrz = 0
    Set @WCodLayout = 0

	-- Substring(Cod_OrigemPdv,1,1) = 'G'
    Exec PR_IncluiPDVCB 'P', @PCodEstabe, @PNumPdv output, 'G', @ct_CodCli, @WFlgUsaWms, @PTipOpe,
                        @ct_CodVended, @ct_CodOperad, @ct_CodDigita, @ct_IdPolCom, @WCodTabPrz, @WCodLayout,
                        @WFlgBlqWms, @WFlgBlqPol, @PMsgErr output, 0

    Update pv
       Set pv.Status2 = 'X'
         , pv.Tip_Vencimento = ''
         , pv.Id_Consig = @PIdConsig    
         , pv.Num_SequenciaCtr = @PNumSequen
     From PDVCB pv
    Where pv.Cod_Estabe = @PCodEstabe
      And pv.Numero = @PNumPdv

    if @PNumPdv > 0
      begin
    
        Declare @WPFlgAchou bit,
                @WPTipSai varchar(1),
                @WPCodLot varchar(20),
                @WPLocFis varchar(15),
                @WPCodFab int,
                @WPFatCnvImpFat int,
                @WPPrcFab numeric(18,8),
                @WPPrcMaxCon numeric(18,8),
                @WPPrcRefFpb numeric(18,8),
                @WPPrcCusMinComMarkup numeric(18,8),
                @WPPrcTab numeric(18,8),
                @WPPrcTabBru numeric(18,8),
                @WPPrcUni numeric(18,8),
                @WPPrcUniLiqPer numeric(18,8),
                @WPFlgEmbDscPrc bit,
                @WPPerDscLin numeric(18,8),
                @WPPerDscPrz numeric(18,8),
                @WPPerDscVis numeric(18,8),
                @WPQtdPrzMax int,
                @WPCodRej varchar(3),
                @WPDesMsg varchar(80),
                @WPCmp varchar(20),
                @WPNomUsuDbq varchar(35),
                @WPDesMsgDbq varchar(60),
    
                @cr_NumSeq int,
                @cr_CodPrd int,
                @cr_QtdPed int, 
                @cr_PrcUni numeric(18,8), 
                @cr_PerDsc numeric(8,4), 
                @cr_FatCnvApr int,
                @cr_QtdImpFat numeric(18,4), 
                @cr_PrcUniImp numeric(18,8), 
                @cr_CodRej varchar(3),
                --@cr_DesMsg varchar(80),
                @WIte_QtdSolInf int,
                @WIte_QtdPedInf int, 
                @WIte_QtdBonInf int,
                @WIte_IdPolCom int,
    
                @WPPerDscPolCom numeric(18,8),
                @WPPerDscVisPolCom numeric(18,8),
                @WPPrcPolCom numeric(18,8),
                @WPQtdPrzPolCom int,
                @WPCodKitPrm int,
                @WPCodPromoc int,
                @WPFlgVerba bit,
                @WPFlgPolPrm bit,
    
                @WPC_PrcUni numeric(18,8),
                @WPC_PerDscIte numeric(18,8),
                @WPPrcUniLiqPdv numeric(18,8),
                @WPC_VlrDesconto numeric(18,8)  -- aqui
    
    ----------------------------------------------------------------------------------
    
        Declare PDVIT_Cr Cursor Local Fast_Forward For
    
          Select NumSeq = row_number() over(Order by it.Num_Sequen), it.Cod_Produt,
                 QtdPed = it.Qtd_Pedido,  
                 PrcUni = it.Prc_Unitar, 
                 it.Per_Descon, 
                 IsNull(it.Fat_CnvApr,1), QtdImpFat = it.Qtd_Pedido, PrcUniImp = it.Prc_Unitar
            From CNGRI it
                 Inner Join PRXES p on it.Cod_Estabe = p.Cod_Estabe and it.Cod_Produt = p.Cod_Produt
           Where it.Cod_Estabe = @PCodEstabe 
             And it.Id_Consig = @PIdConsig 
             And it.Num_Sequen = @PNumSequen
             And it.Qtd_Pedido > 0
    
        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @cr_NumSeq, @cr_CodPrd, 
                                      @cr_QtdPed, @cr_PrcUni, @cr_PerDsc, 
                                      @cr_FatCnvApr, @cr_QtdImpFat, @cr_PrcUniImp 
        While @@FETCH_STATUS = 0
          begin
            Set @WIte_QtdPedInf = @cr_QtdPed
            Set @WIte_QtdBonInf = 0
            Set @WIte_IdPolcom  = 0   -- ???????

            Set @WFlgBlqDscAutIte = 0
    
            Exec PR_InfoDefaultPDVIT @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @cr_CodPrd, 
                                     @WIte_QtdPedInf, @WIte_QtdBonInf, @WIte_IdPolCom output, @WFlgBlqDscAutIte,
                                     @WPFlgAchou output,
                                     @WPLocFis output,
                                     @WPCodFab output,
                                     @WPPrcFab output,
                                     @WPPrcMaxCon output,
                                     @WPPrcRefFpb output,
                                     @WPPrcTab output,
                                     @WPPrcTabBru output,
                                     @WPFatCnvImpFat output,     
                                     @WPPrcUni output,
                                     @WPPrcCusMinComMarkup output,
                                     @WPPerDscPolCom output,
                                     @WPPerDscVisPolCom output,
                                     @WPPrcPolCom output,
                                     @WPQtdPrzPolCom output,
                                     @WPFlgVerba output,
                                     @WPFlgPolPrm output,
                                     @WPCodKitPrm output,
                                     @WPCodPromoc output,
                                     @WPFlgEmbDscPrc output, 
                                     @WPQtdPrzMax output,
                                     @WPPerDscLin output,
                                     @WPPerDscPrz output,
                                     @WPPerDscVis output,
                                     @WPPrcUniLiqPer output
    
            if @WPFlgAchou = 1
              begin

                /*if @cr_PrcUni > 0 Conforme reunião com a Meire, 31/03/23, não há comno definir preço em consignação (validação indevida)
                  begin				
                    Set @WPPrcUni       = @cr_PrcUni
                    Set @WPPerDscLin    = @cr_PerDsc  
                    Set @WPPerDscPrz    = @cr_PerDsc
                    Set @WPPerDscVis    = @cr_PerDsc
                  end*/

                if IsNull(@cr_PrcUniImp,0) = 0
                  Set @cr_PrcUniImp = @WPPrcUni*@cr_FatCnvApr

                Set @WPCodLot       = '*'
                Set @WPTipSai       = ''
                Set @WPFatCnvImpFat = @cr_FatCnvApr
    
    ----------------------------------------------------------------
                --  calcfields 
                Set @WPC_PrcUni = @WPPrcUni
                Set @WPC_PerDscIte = @cr_PerDsc
                   
                --  calcula preco unitario liquido
                Set @WPPrcUniLiqPdv = @WPPrcUni*(1-@WPC_PerDscIte/100)
                   
                if @WPFlgEmbDscPrc = 1
                  begin
                    Set @WPC_PrcUni = @WPPrcUni*(1-@WPC_PerDscIte/100)
                    Set @WPC_PerDscIte = 0
                  end
                   
                Set @WFlgSnhEsp = 0 
                Set @WNomUsuSnhEsp = ''
                Set @WFlgNaoCriConCom = 0  -- coloquei
                Set @WFlgBlqCriPrcVen = 0  -- coloquei
                Set @WFlgCriVrb = 0        -- coloquei
                Set @WFlgBlqQtdPar = 0
    
                Exec PR_CriticaItemPDV @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @cr_CodPrd, 
                                       @WIte_IdPolCom, @WIte_QtdPedInf, @WIte_QtdBonInf, @WPTipSai, @WPQtdPrzMax,
                                       @WPPrcUni, @WPPerDscVis, @WPPerDscPrz, @cr_QtdImpFat, @cr_PrcUniImp,
                                       @WPCodKitPrm, @WPPerDscPolCom, @WPPerDscVisPolCom, @WPPrcPolCom,
                                       @WPPrcUniLiqPdv, @WPPrcCusMinComMarkup, @WPPrcUniLiqPer, @WPFlgVerba,
                                       @WFlgSnhEsp, @WNomUsuSnhEsp, @WFlgNaoCriConCom, @WFlgBlqCriPrcVen, @WFlgCriVrb, @WFlgBlqQtdPar,
                                       @WPCodRej output, @WPDesMsg output, @WPCmp output, @WPNomUsuDbq output, @WPDesMsgDbq output

                Set @WIte_QtdSolInf = @WIte_QtdPedInf + @WIte_QtdBonInf
    
                if (@WPDesMsg = '') or (Substring(@WPCodRej,1,2) = 'PZ')  
                  begin
                    Set @WPCodRej = ''
                    Set @WPDesMsg = ''
                  end
                else
                  begin
                    Set @WIte_QtdPedInf = 0
                    Set @WIte_QtdBonInf = 0
                  end
    
                --Set @WPCodRej = @cr_CodRej
                --Set @WPDesMsg = @cr_DesMsg
    
                Insert Into PDVIT (Cod_Estabe, Num_SeqDig, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai)
                  Values (@PCodEstabe, @cr_NumSeq, @PNumPdv, @cr_CodPrd, @WPCodLot, @WPTipSai)
                         
                Update PDVIT 
                   Set Qtd_Pedido = @WIte_QtdPedInf 
                     , Qtd_Bonificacao = @WIte_QtdBonInf 
                     , Id_PolCom = @WIte_IdPolCom 
                     , Loc_Fisica = @WPLocFis 
                     , Cod_Fabricante = @WPCodFab
                     , Qtd_PrzMax = @WPQtdPrzMax 
                     , Prc_Fabric = @WPPrcFab 
                     , Prc_MaxCon = @WPPrcMaxCon 
                     , Prc_RefFpb = @WPPrcRefFpb 
                     , Prc_Tabela = @WPPrcTab 
                     , Prc_TabBru = @WPPrcTabBru
					 , Prc_Unitario = @WPPrcUni
                     , Per_Desconto = @WPPerDscLin 
                     , Per_Descon = @WPPerDscPrz 
                     , Per_DscVis = @WPPerDscVis 
                     , Flg_Verba = @WPFlgVerba 
                     , Prc_CusMinComMarkup = @WPPrcCusMinComMarkup
                     , Qtd_PrzPolCom = @WPQtdPrzPolCom 
					 , Prc_PolCom = @WPPrcPolCom 
					 , Per_DscPolCom = @WPPerDscPolCom 
					 , Per_DscVisPolCom = @WPPerDscVisPolCom 
					 , Cod_KitPrm = @WPCodKitPrm 
					 , Cod_Promocao = @WPCodPromoc

                     , Prc_UniPde = 0
					 , Per_DscPde = 0 
					 , Cod_PrjPde = '' 
					 , Num_SeqPdc = ''
                         
                     , Flg_PrcUniDsc = @WPFlgEmbDscPrc 
                     , Fat_CnvImpFat = @cr_FatCnvApr 
					 , Qtd_ImpFat = @cr_QtdImpFat 
					 , Prc_UniImpFat = @cr_PrcUniImp
					 , C_PrcUni = @WPC_PrcUni 
					 , C_PerDscIte = @WPC_PerDscIte

                     , Prc_UniLiqPer = @WPPrcUniLiqPer 
					 , Qtd_Solicitado = @WIte_QtdSolInf 
					 , Qtd_Acerto = 0 
					 , Flg_PolPrm = @WPFlgPolPrm

                     , Cod_MtvRej = @WPCodRej
					 , Des_MtvRej = Substring(@WPDesMsg,1,40)
					 , Nom_UsuDesbloq = Substring(@WPNomUsuDbq,1,15)
					 , Des_MsgDesbloq = Substring(@WPDesMsgDbq,1,60)

                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Pedido = @PNumPdv
                   And Cod_Produto = @cr_CodPrd 
                   And Cod_Lote = @WPCodLot
                   And Tip_Sai = @WPTipSai


                --  atualiza motivo qdo for o caso
                Update PDVIT 
                   Set Cod_MtvRej = Case 
                                      When Qtd_Pedido > 0 then 'ES-' 
                                      Else 'ES0'
                                     End 
                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Pedido = @PNumPdv
                   And Cod_Produto = @cr_CodPrd 
                   And Cod_Lote = @WPCodLot
                   And Tip_Sai = @WPTipSai
                   And Qtd_Pedido < Qtd_Solicitado 
                   And IsNull(Cod_MtvRej,'') = '' 

              end  -- if @WPFlgAchou = 1
    
            Fetch Next From PDVIT_Cr Into @cr_NumSeq, @cr_CodPrd, 
                                          @cr_QtdPed, @cr_PrcUni, @cr_PerDsc, 
                                          @cr_FatCnvApr, @cr_QtdImpFat, @cr_PrcUniImp 
          end
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

        Update PDVCB 
    	   Set Status2 = 'A'
         Where Cod_Estabe = @PCodEstabe
           And Numero = @PNumPdv
    
        Exec PR_AtualizaCNGRI @PCodEstabe, @PIdConsig, @PNumSequen
        if (@@error <> 0)
          begin
            if @@trancount > 0
              Rollback Transaction
            Return
          end

        Update CNGRC
           Set Sta_CngPed = '2',
		   Num_PedVen = @PNumPdv 
         Where Cod_Estabe = @PCodEstabe 
           And Id_Consig  = @PIdConsig 
           And Num_Sequen = @PNumSequen

      end  -- if @PNumPdv > 0
    
    if @@trancount > 0
      COMMIT TRANSACTION

  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ProIni_EncerraMes]
@CodEstabe int

WITH RECOMPILE
AS

SET NOCOUNT ON

Begin Transaction

  -- Pegar a data atual com a hora zerada 
  Set DateFormat ymd  
  Declare @Now smalldatetime,
          @Date smalldatetime,
      @pm_DatEncRotMen smalldatetime,
      @pm_QtdMesMedRotMen int,
        @AnoRef int,
        @MesRef int,
      @AnoMesPar int
        
  Set @Now = GetDate()
  Set @Date = cast(GetDate() as Date)

  -- verifica se executa encerramento mensal (todos os estabelecimentos)
  Select @pm_DatEncRotMen = IsNull(DatFecRotMen,0),
         @pm_QtdMesMedRotMen = IsNull(QtdMesMedRotMen,3)
    From PARAM 
   Where Cod_Estabe = @CodEstabe

  Set @AnoRef = DatePart(Year,@Date)
  Set @MesRef = DatePart(Month,@Date)
  Set @AnoMesPar = DatePart(Year,IsNull(@pm_DatEncRotMen,0))*100+DatePart(Month,IsNull(@pm_DatEncRotMen,0))

  if (@AnoRef*100+@MesRef) > @AnoMesPar
    begin
    Set @MesRef = @MesRef-1
    if @MesRef = 0
      begin
      Set @MesRef = 12
      Set @AnoRef = @AnoRef - 1
    end

      Exec PR_ProcessaClaABC @pm_QtdMesMedRotMen, 1, 1, 1
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

      Exec PR_ProcessaResumoGeral @MesRef, @AnoRef
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

      Exec PR_ProIni_ZeraVerbasMes -1     -- todos os estabelecimentos
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

  end

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ProIni_ReservaProdutosVencidos] 
@CodEstabe int

WITH RECOMPILE
AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDate() as Date)

Begin Transaction

  Declare @WFlgUsaWms bit = 0,
          @pm_QtdDiaResPrdVen int,
          @pm_FlgResPrdVen bit,
          @DatLim smalldatetime,
          @pl_Chave int,
          @pl_CodDep smallint,
          @pl_CodPrd int,
          @pl_CodLot varchar(20),
          @pl_QtdSldPra int,
          @pl_QtdSldDep int,
          @rs_Numero int

  Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
                                            HASHBYTES('MD5',(Select Num_Cnpj From dbo.ESTAB Where Cod_Estabe = @CodEstabe))))

  -- coloca campos de PARAM na memoria
  Select @pm_QtdDiaResPrdVen = Isnull(QtdDiaResPrdVen,0),
         @pm_FlgResPrdVen = IsNull(FlgResPrdVen,0)
    From PARAM
    Where Cod_Estabe = @CodEstabe

  if (@WFlgUsaWms = 0) and (@pm_FlgResPrdVen = 1)
    begin
      -- data de vencimento
      Set @DatLim = @Date + @pm_QtdDiaResPrdVen

      Declare @Tab Table(
        Chave Int Identity(1,1) PRIMARY KEY,
        Cod_Dep smallint, 
        Cod_Produt int, 
        Cod_Lote varchar(20), 
        Qtd_SldPra int,
        Qtd_SldDep int
      )

      -- seleciona lotes vencidos
      Insert Into @Tab (Cod_Dep, Cod_Produt, Cod_Lote, Qtd_SldPra, Qtd_SldDep)
        Select l.Cod_Dep, l.Cod_Produt, l.Cod_Lote, l.Qtd_SldPra, l.Qtd_SldDep
          From PRLOT l 
               inner Join PRXES p 
                       on l.Cod_Estabe = p.Cod_Estabe and l.Cod_Produt = p.Cod_Produt
          Where l.Cod_Estabe = @CodEstabe
            And l.Qtd_Saldo > 0 
            And IsNull(l.Dat_Vencim,0) > 0 
            And IsNull(l.Dat_Vencim,0) <= @DatLim 
            And p.Qtd_Dispon >= l.Qtd_Saldo

      -- reserva lotes vencidos
      While Exists(Select 1 From @Tab)
        begin
          Select top 1 @pl_Chave = Chave,
                       @pl_CodDep =  Cod_Dep,
                       @pl_CodPrd = Cod_Produt,
                       @pl_CodLot = Cod_Lote,
                       @pl_QtdSldPra = Qtd_SldPra,
                       @pl_QtdSldDep = Qtd_SldDep
            From @Tab
           Order by Chave

          Set @rs_Numero = IsNull((Select max(Numero) From RESER Where Cod_Estabe = @CodEstabe),0)
      
          While @rs_Numero >= 0
            begin
             Set @rs_Numero = @rs_Numero + 1
             if not Exists (Select Numero From RESER Where Cod_Estabe = @CodEstabe And Numero = @rs_Numero)
               begin
                 -- bloqueia produto
                 Update PRXES
                    Set Qtd_Transi = Qtd_Transi + 0
                  Where Cod_Estabe = @CodEstabe 
                    And Cod_Produt = @pl_CodPrd

                 -- registra reserva
                 Insert Into RESER (Cod_Estabe, Numero, Cod_Dep, Cod_Produto, Cod_Lote
                                 ,  Qtd_Movimento, Qtd_ResDep, Historico, Dat_Movimento, Usuario, Transacao)
                            Values (@CodEstabe, @rs_Numero, @pl_CodDep, @pl_CodPrd, @pl_CodLot
                                 ,  @pl_QtdSldPra, @pl_QtdSldDep, 'RESERVA AUTOMATICA POR VENCIMENTO', @Date, 'SISTEMA', @Now)
                 if @@error <> 0
                   RollBack Transaction

                 Break
               end
            end

          Delete From @Tab
           Where Chave = @pl_Chave

        end  -- While Exists(Select 1 From @Tab)

    end  -- if (@WFlgUsaWms = 0) and (@pm_FlgResPrdVen = 1)

Commit transaction
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ProIni_VerificaOcorrenciasCheques]
@CodEstabe int

WITH RECOMPILE
AS

SET NOCOUNT ON 

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
             @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(Cast(Year(@Now) as varchar)+'-'+Cast(Month(@Now) as varchar)+'-'+Cast(Day(@Now) as varchar)+' 00:00:00' as smalldatetime)

if (Select Isnull(QtdDiaRecChqDvl,0) From PARAM Where Cod_Estabe = @CodEstabe) > 0
  begin

  Begin Transaction

  Declare @ch_CodDoc int,
          @ch_Num varchar(12),
          @ch_Vlr numeric(18,4),
          @ch_CodVdr int,
          @ch_DatEnvVdr smalldatetime,
          @ch_DesUsu varchar(35),
          @pm_PerDedVlrChqDvl numeric(18,4),
          @pm_QtdDiaRecChqDvl int,
          @cr_CodDoc int,
          @cr_VlrSld numeric(18,4),
          @cr_DatVct smalldatetime,
          @cr_IsnCtaFin int,
          @cr_CodCntCus int,
          @WCodDoc int,
          @WValDoc numeric(18,4),
          @WValDeb numeric(18,4),
          @WStrDat varchar(10),
          @WQtdDiaAtr int

  -- coloca parametros na memoria
  Select @pm_QtdDiaRecChqDvl = Isnull(QtdDiaRecChqDvl,0),
         @pm_PerDedVlrChqDvl = Isnull(PerDedVlrChqDvl,0)
    From PARAM
    Where Cod_Estabe = @CodEstabe

  -- seleciona cheques entrgues ao vendedor e nao retornadps em x(parametro) dias
  Declare CHEQU_Cr Cursor Local Fast_Forward For 
    Select Cod_Cheque
      From CHEQU
      Where Cod_Cob = 'V'
      And Status = '2'
      And Cod_Estabe = @CodEstabe
      And (Dat_Env_Vdr + @pm_QtdDiaRecChqDvl) < @Date
  Open CHEQU_Cr
  Fetch Next From CHEQU_Cr Into @ch_CodDoc
  While @@FETCH_STATUS = 0
    begin
      -- coloca dados do cheque na memoria
      Select @ch_Num = Num_Cheque,
             @ch_Vlr = ChqVlr,
             @ch_CodVdr = Cod_Vendedor,
             @ch_DatEnvVdr = Dat_Env_Vdr,
             @ch_DesUsu = Usuario
        From CHEQU
        Where Cod_Cheque = @ch_CodDoc
        And Cod_Estabe = @CodEstabe

      -- inclui vale
      if not Exists(Select bx.Cod_Documento From CTREC cr, BXREC bx Where cr.Cod_Estabe = bx.Cod_Estabe And cr.Cod_Documento = bx.Cod_Documento And cr.Cod_Cheque = @ch_CodDoc And cr.Vlr_Saldo > 0 And cr.Cod_Estabe = @CodEstabe)
        begin
          EXEC PR_ProxNumero 'Vale', @WCodDoc output
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end
          -- calcula valor do vale de debito
          Set @WStrDat = Cast(Day(@ch_DatEnvVdr) as varchar) + '/' + Cast(Month(@ch_DatEnvVdr) as varchar) + '/' + Cast(Year(@ch_DatEnvVdr) as varchar)
          Set @WValDeb = (Select Val_Saldo From VALES Where Cod_Estabe = @CodEstabe And Cod_CtrLanAut = 'DVC' and Num_CtrLanAut = @ch_CodDoc) 
          if @WValDeb is null Set @WValDeb = 0
          Set @WValDoc =  Round(@ch_Vlr-@WValDeb,2)

          -- inclui vale
          Insert into VALES
            (Cod_Estabe, Cod_Vale, Des_Vale, Tip_Entid, Cod_Entid, Dat_Emissa, Dat_Vencim, Val_Vale, Deb_Cre, 
             Cod_CtrLanAut, Num_CtrLanAut, Usuario, Transacao)
          Values
            (@CodEstabe, @WCodDoc,'Ch. '+@ch_Num+' Ret. em '+@WStrDat,'VEN',@ch_CodVdr,@Date,@Date,@WValDoc,'D',
             'RTC',@ch_CodDoc,@ch_DesUsu, @Now)
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          -- muda status do cheque p/ trocado (8)
          Update CHEQU
            Set Status = '8'
            Where Cod_Cheque = @ch_CodDoc
            And Cod_Estabe = @CodEstabe
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end
        end  -- if @WFlgIncVal = 1

      -- baixa o titulo
      if Exists(Select Cod_Documento From CTREC Where Cod_Estabe = @CodEstabe And Cod_Cheque = @ch_CodDoc)
        begin
          Select @cr_CodDoc =  Cod_Documento,
                 @cr_VlrSld = Isnull(Vlr_Saldo,0),
                 @cr_DatVct = Dat_Vencimento,
                 @cr_IsnCtaFin = Isn_CtaFin,
                 @cr_CodCntCus = Cod_CntCus
            From CTREC 
            Where Cod_Estabe = @CodEstabe
            And Cod_Cheque = @ch_CodDoc
          
          if (@cr_VlrSld > 0) and (not Exists(Select Cod_Documento From BXREC Where Cod_Estabe = @CodEstabe And Cod_Documento = @cr_CodDoc)) 
            begin
              EXEC PR_ProxNumero 'Lancamento', @WCodDoc output
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end

              -- calcula atraso
              Set @WQtdDiaAtr = 0
              if @Date > @cr_DatVct
                Set @WQtdDiaAtr = Datediff(day,@cr_DatVct,@Date)

              -- insere baixa
              Insert into BXREC (Cod_Estabe,Cod_Documento,Cod_Lancamento,Cod_Rec,Tip_Baixa,Tip_Doc,Dat_Caixa,Dat_Lancamento,Dat_Registro,
                                 Vlr_Principal,Qtd_DiasAtraso,Status,Cod_CtrOri,Isn_CtaFin,Cod_CntCus,Usuario,Transacao)
                          Values(@CodEstabe,@cr_CodDoc, @WCodDoc, -4, 'P', 'E', @Date, @Date, @Date,
                                 @cr_VlrSld, @WQtdDiaAtr, 'Q','V',@cr_IsnCtaFin,@cr_CodCntCus,@ch_DesUsu, @Now)
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end

            end       
        end    -- if Exists(Select Cod_Documento From CTREC Where Cod_Cheque = @ch_CodDoc)

      Fetch Next From CHEQU_Cr Into @ch_CodDoc
    end
  Close CHEQU_Cr
  Deallocate CHEQU_Cr

  Commit transaction
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RecalculaPisCofins] 
@PCodEstabe int,
@PNumNot int,
@PSerNot varchar(3),   -- se for entrada: ignorado
@PTipEntSai char(1)    --(S)aida, (E)ntrada

AS

SET NOCOUNT ON

Begin Transaction

  -- variaveis a gravar em NFSIT
  Declare @P_CstPis varchar(2),
          @P_VlrBasPis numeric(18,4),
          @P_AlqPis numeric(18,4),
          @P_VlrPis numeric(18,4),
          @P_CstCof varchar(2),
          @P_VlrBasCof numeric(18,4),
          @P_AlqCof numeric(18,4),
          @P_VlrCof numeric(18,4),
          @P_ObsNf varchar(200)

-- coloca campos de tabelas na memoria
  Declare @cb_CodCfo int,
          @cb_DatMov smalldatetime,
          @cb_TipNot varchar(1),
          @em_CodTipLuc varchar(2),
          @pm_FlgIncIpiCalPis bit,
          @pm_FlgExcIcmCalPis bit,
          @cl_CodRamAtv int,
          @op_FlgCalPisCof bit,
          @pr_CodNcm varchar(8),
          @it_CodPrd int,
          @it_CodLot varchar(20),
          @it_NumSeqIte int,
          @it_TipLis varchar(1),
          @it_VlrBasTri numeric(18,4),
		  @it_VlrSbtRes  numeric(18,4),
          @it_VlrIpi numeric(18,4),
          @it_VlrIcmNor numeric(18,4),
          @it_VlrIcmTri numeric(18,4),
		  @WVlrBasPisCof numeric(18,4)

  -- ESTAB / PARAM
  Select @em_CodTipLuc = IsNull(Cod_TipLucro,'')
    From ESTAB
  Where Cod_Estabe = @PCodEstabe  

  Select @pm_FlgIncIpiCalPis = IsNull(FlgIncIpiCalPis,0),
         @pm_FlgExcIcmCalPis = IsNull(FlgExcIcmCalPis,0)
    From PARAM
  Where Cod_Estabe = @PCodEstabe


  if (@PTipEntSai = 'S') and Exists(Select 1 From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot)
    begin
      -- indica se reduz aliq. PIS/COFINS
      Set @cl_CodRamAtv = 0
  
      Select @cb_CodCfo = IsNull(cb.Cod_Cfo1,0),
             @cb_DatMov = Dat_Emissao,
             @cb_TipNot = Tip_Saida,
             @cl_CodRamAtv = IsNull(cl.Cod_RamoAtividade,0),
             @op_FlgCalPisCof = IsNull(op.Flg_CalPisCof,0)
        From NFSCB cb   
             Left Join TPOPE op on cb.Cod_Ope = op.Cod_Ope 
             Left Join CLIEN cl on cb.Cod_Cliente = cl.Codigo 
             Left Join RMATV ra on cl.Cod_RamoAtividade = ra.Codigo
      Where cb.Cod_Estabe = @PCodEstabe 
      and cb.Ser_Nota = @PSerNot 
      and cb.Num_Nota = @PNumNot

      Update NFSCB
        Set Vlr_Pis = 0,
            Vlr_Cofins = 0
      Where Cod_Estabe = @PCodEstabe 
      and Ser_Nota = @PSerNot 
      and Num_Nota = @PNumNot

      Declare NFSIT_Cr Cursor Local Fast_Forward For 
        Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, it.Vlr_BasTri, IsNull(it.Vlr_SbtRes,0), 
               IsNull(it.Vlr_Ipi,0), IsNull(it.Vlr_IcmsNor,0), IsNull(it.Vlr_IcmsTri,0),
               IsNull(it.Tip_Aux,pr.Tip_LisPis), Substring(Ltrim(Rtrim(pr.Cod_ClaFis)),1,8)
          From NFSIT it 
               Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
        Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
        And (Qtd_Produto+Qtd_Bonificacao) > 0
      Open NFSIT_Cr
      Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_VlrBasTri, @it_VlrSbtRes, 
                                    @it_VlrIpi, @it_VlrIcmNor, @it_VlrIcmTri, 
                                    @it_TipLis, @pr_CodNcm
      While @@FETCH_STATUS = 0
        begin
          -- ressarcimento
          Set @WVlrBasPisCof = Round(@it_VlrBasTri+@it_VlrSbtRes,2)

          -- ipi
          if @pm_FlgIncIpiCalPis = 1
            Set @WVlrBasPisCof = @WVlrBasPisCof + @it_VlrIpi

          -- exclui icms destacado  
          if @pm_FlgExcIcmCalPis = 1
            Set @WVlrBasPisCof = @WVlrBasPisCof - @it_VlrIcmTri

          Exec PR_CalculaPisCofins @PCodEstabe, @op_FlgCalPisCof, @PTipEntSai, @em_CodTipLuc, @cb_DatMov, @cb_CodCfo, @cl_CodRamAtv, @pr_CodNcm, @it_TipLis, @WVlrBasPisCof, 
                                   @P_CstPis output, @P_VlrBasPis output, @P_AlqPis output, @P_VlrPis output,
                                   @P_CstCof output, @P_VlrBasCof output, @P_AlqCof output, @P_VlrCof output, @P_ObsNf output
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          Update NFSIT
            Set Cod_Ncm = @pr_CodNcm,  
                Vlr_BasPis = @P_VlrBasPis,
                Vlr_Pis = @P_VlrPis,
                Alq_Pis = @P_AlqPis,
                Cst_Pis = @P_CstPis,
                Vlr_BasCofins = @P_VlrBasCof,
                Vlr_Cofins = @P_VlrCof,
                Alq_Cofins = @P_AlqCof,
                Cst_Cofins = @P_CstCof,
                Obs_Nf = @P_ObsNf
          From NFSIT
          Where Cod_Estabe = @PCodEstabe
          And Ser_Nota = @PSerNot
          And Num_Nota = @PNumNot
          And Cod_Produto = @it_CodPrd
          And Cod_Lote = @it_CodLot
          And Num_SeqIte = @it_NumSeqIte

          -- ajusta pis/Cofins
          Update it
            Set it.Vlr_Pis = 0.01
          From NFSIT it
          Where it.Cod_Estabe = @PCodEstabe
          And it.Ser_Nota = @PSerNot
          And it.Num_Nota = @PNumNot
          And it.Cod_Produto = @it_CodPrd
          And it.Cod_Lote = @it_CodLot
          And it.Num_SeqIte = @it_NumSeqIte
          And (it.Vlr_BasPis > 0) and (it.Alq_Pis > 0) and (it.Vlr_Pis = 0)
    
          Update it
            Set it.Vlr_Cofins = 0.01
          From NFSIT it
          Where it.Cod_Estabe = @PCodEstabe
          And it.Ser_Nota = @PSerNot
          And it.Num_Nota = @PNumNot
          And it.Cod_Produto = @it_CodPrd
          And it.Cod_Lote = @it_CodLot
          And it.Num_SeqIte = @it_NumSeqIte
          And (it.Vlr_BasCofins > 0) and (it.Alq_Cofins > 0) and (it.Vlr_Cofins = 0)
    
          Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_VlrBasTri, @it_VlrSbtRes, 
                                        @it_VlrIpi, @it_VlrIcmNor, @it_VlrIcmTri, 
                                        @it_TipLis, @pr_CodNcm
        end
      Close NFSIT_Cr
      Deallocate NFSIT_Cr

      Update NFSCB
        Set Cod_RamAtv = @cl_CodRamAtv,
	        Vlr_Pis = (Select Round(Sum(IsNull(Vlr_Pis,0)),2) From NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot),
            Vlr_Cofins = (Select Round(Sum(IsNull(Vlr_Cofins,0)),2) From NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot)
      Where Cod_Estabe = @PCodEstabe 
      and Ser_Nota = @PSerNot 
      and Num_Nota = @PNumNot

	end  -- if (@PTipEntSai = 'S')

  else
  if (@PTipEntSai = 'E') and Exists(Select 1 From NFECB Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumNot)
    begin
      -- indica se reduz aliq. PIS/COFINS
      Set @cl_CodRamAtv = 0
  
      Select @cb_CodCfo = IsNull(cb.Cod_Cfo,0),
             @cb_DatMov = Dat_Movimento,
             @cb_TipNot = Tip_NF,
             @cl_CodRamAtv = IsNull(cl.Cod_RamoAtividade,0),
             @op_FlgCalPisCof = IsNull(op.Flg_CalPisCof,0)
      From NFECB cb   
           Left Join TPOPE op on cb.Cod_Ope = op.Cod_Ope 
           Left Outer Join CLIEN cl on cb.Cod_EmiCliente = cl.Codigo 
           Left Outer Join RMATV ra on cl.Cod_RamoAtividade = ra.Codigo
      Where cb.Cod_Estabe = @PCodEstabe 
      and cb.Protocolo = @PNumNot

      -- atualiza cabecalho
      Update NFECB
        Set Vlr_Pis = 0,
            Vlr_Cofins = 0
      Where Cod_Estabe = @PCodEstabe
      And Protocolo = @PNumNot
     
      DECLARE NFEIT_Cr Cursor Local Fast_Forward For
        Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, it.Vlr_BasTri, IsNull(it.Vlr_SbtRes,0), 
               IsNull(it.Vlr_Ipi,0), IsNull(it.Vlr_IcmsNor,0), IsNull(it.Vlr_IcmsTrib,0),
               IsNull(it.Tip_LisPis,pr.Tip_LisPis), Substring(Ltrim(Rtrim(pr.Cod_ClaFis)),1,8)
          From NFEIT it 
               Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
        Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumNot
        And (Qtd_Pedido+Qtd_Bonificacao) > 0
      OPEN NFEIT_Cr
      Fetch Next From NFEIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_VlrBasTri, @it_VlrSbtRes, 
                                    @it_VlrIpi, @it_VlrIcmNor, @it_VlrIcmTri, 
                                    @it_TipLis, @pr_CodNcm
     
      WHILE @@FETCH_STATUS = 0
        BEGIN
          -- ressarcimento
          Set @WVlrBasPisCof = Round(@it_VlrBasTri+@it_VlrSbtRes,2)

          -- ipi
          if @pm_FlgIncIpiCalPis = 1
            Set @WVlrBasPisCof = @WVlrBasPisCof + @it_VlrIpi

          -- exclui icm destacado na devolução de venda
          if @pm_FlgExcIcmCalPis = 1
            begin
              if @cb_TipNot = 'D'
                Set @WVlrBasPisCof = @WVlrBasPisCof - @it_VlrIcmTri
              else
                Set @WVlrBasPisCof = @WVlrBasPisCof - @it_VlrIcmNor
            end

          Exec PR_CalculaPisCofins @PCodEstabe, @op_FlgCalPisCof, @PTipEntSai, @em_CodTipLuc, @cb_DatMov, @cb_CodCfo, @cl_CodRamAtv, @pr_CodNcm, @it_TipLis, @WVlrBasPisCof, 
                                   @P_CstPis output, @P_VlrBasPis output, @P_AlqPis output, @P_VlrPis output,
                                   @P_CstCof output, @P_VlrBasCof output, @P_AlqCof output, @P_VlrCof output, @P_ObsNf output
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          -- atualiza item
          Update NFEIT
            Set Cod_Ncm = @pr_CodNcm,  
                Vlr_BasPis = @P_VlrBasPis,
                Vlr_Pis = @P_VlrPis,
                Alq_Pis = @P_AlqPis,
                Cst_Pis = @P_CstPis,
                Vlr_BasCofins = @P_VlrBasCof,
                Vlr_Cofins = @P_VlrCof,
                Alq_Cofins = @P_AlqCof,
                Cst_Cofins = @P_CstCof
          From NFEIT
          Where Cod_Estabe = @PCodEstabe
          And Protocolo = @PNumNot
          And Cod_Produto = @it_CodPrd
          And Cod_Lote = @it_CodLot
          And Num_SeqIte = @it_NumSeqIte

          -- ajusta pis/Cofins
          Update it
            Set it.Vlr_Pis = 0.01
          From NFEIT it
          Where it.Cod_Estabe = @PCodEstabe
          And it.Protocolo = @PNumNot
          And it.Cod_Produto = @it_CodPrd
          And it.Cod_Lote = @it_CodLot
          And it.Num_SeqIte = @it_NumSeqIte
          And (it.Vlr_BasPis > 0) and (it.Alq_Pis > 0) and (it.Vlr_Pis = 0)
    
          Update it
            Set it.Vlr_Cofins = 0.01
          From NFEIT it
          Where it.Cod_Estabe = @PCodEstabe
          And it.Protocolo = @PNumNot
          And it.Cod_Produto = @it_CodPrd
          And it.Cod_Lote = @it_CodLot
          And it.Num_SeqIte = @it_NumSeqIte
          And (it.Vlr_BasCofins > 0) and (it.Alq_Cofins > 0) and (it.Vlr_Cofins = 0)

          Fetch Next From NFEIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_VlrBasTri, @it_VlrSbtRes, 
                                        @it_VlrIpi, @it_VlrIcmNor, @it_VlrIcmTri, 
                                        @it_TipLis, @pr_CodNcm
        END 
      
      CLOSE NFEIT_Cr
      DEALLOCATE NFEIT_Cr 
     
      Update NFECB
        Set Vlr_Pis = (Select Round(Sum(IsNull(Vlr_Pis,0)),2) From NFEIT Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumNot),
            Vlr_Cofins = (Select Round(Sum(IsNull(Vlr_Cofins,0)),2) From NFEIT Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumNot)
      Where Cod_Estabe = @PCodEstabe 
      and Protocolo = @PNumNot

    end  -- if PTipEntSai = 'E'

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RetornaItensNF]
@PCodEstabe int,
@PNumNota int,
@PSerNota varchar(3),
@PTipNota char(1)

AS

SET NOCOUNT ON 

Set dateformat ymd

IF OBJECT_ID('tempdb..#TMP_Itens') IS NOT NULL
  DROP TABLE #TMP_Itens
  
CREATE TABLE #TMP_Itens
(
    Chave int identity,
    Cod_Produto int,
    Num_SeqIte int,
    Num_SeqPdc varchar(6),
    Cod_EAN varchar(14),
    Tip_Sai varchar(1),
    Cod_NCM varchar(8),
    Cod_GrpPrc varchar(1),
    Cod_Cfo int,
    Tip_Por344 varchar(2),
    Tip_LisPis varchar(3),
    Des_Produto varchar(120),
    Obs_Produto varchar(500), 
    Und_Com varchar(12),
    Qtd_Com numeric(18,8),
    Prc_UniCom numeric(18,8),
    Vlr_TotBruIte numeric(18,8),
    Vlr_TotIte numeric(18,8),
    Per_Desconto numeric(18,8),
    Vlr_BasRepIcm numeric(18,8),
    Per_RepIcm numeric(7,4),
    Vlr_RepIcm numeric(18,8),
    Tip_Consumidor varchar(1),
    Vlr_DscTri numeric(18,8),
    Per_DscTri numeric(18,2),
    Vlr_DscRat numeric(18,8),
    Vlr_DscBonRat numeric(18,8),
    Vlr_DscTotIte numeric(18,8),
    Vlr_BasSbtRes numeric(18,8),
    Vlr_SbtRes numeric(18,8), 
    Vlr_BasSbtEmb numeric(18,8),
    Vlr_SbtEmb numeric(18,8), 
    Cod_Lote varchar(20), 
    Cod_LoteOri varchar(20), 
    Dat_Vencim datetime,
    Dat_Fabric datetime,
    Qtd_MesValid integer,
    Vlr_Frete numeric(18,8),
    Vlr_Seguro numeric(18,8),
    Vlr_DspRat numeric(18,8),
    Vlr_DspExt numeric(18,8), 
    Vlr_TotDsp numeric(18,8), 
    Und_Tri varchar(12),
    Qtd_Tri int,
    Prc_UniTri numeric(18,8),
    Cod_OriPrd varchar(1),
    Cod_CstIcm varchar(2),
    Cod_CsosnIcm varchar(3),
    Cod_ModBasCalIcm varchar(1),
    Per_RedBasCalIcm numeric(8,4),
    Vlr_BasIcm numeric(18,8),
    Alq_Icm numeric(8,4),
    Vlr_Icm numeric(18,8), 
    Dif_VlrIcm numeric(18,8), 
    Vlr_BasIcmPro numeric(18,8),
    Vlr_IcmPro numeric(18,8), 
    Per_IcmDiferi numeric(8,4),
    Vlr_IcmDiferi numeric(18,8), 
    Vlr_DscCalSuframa numeric(18,8),
    Vlr_IcmDesone numeric(18,8), 
    Cod_MtvIcmDesone varchar(1),
    Vlr_BasIcmSbtRet numeric(18,8), 
    Vlr_IcmSbtRet numeric(18,8),
    Cod_ModBasCalIcmSbt varchar(1),
    Alq_AgrSbt numeric(8,4), 
    Per_RedBasCalIcmSbt numeric(8,4),
    Vlr_BasIcmSbt numeric(18,8), 
    Alq_IcmSbt numeric(8,4),
    Vlr_IcmSbt numeric(18,8),
    CST_Ipi varchar(2), 
    Cod_EnqIpi varchar(3),
    Vlr_BasIpi numeric(18,8),
    Alq_Ipi numeric(8,4),
    Vlr_Ipi numeric(18,8),
    Vlr_BasDevIpi numeric(18,8),
    Per_DevIpi numeric(8,4),
    Vlr_DevIpi numeric(18,8), 
    CST_Pis varchar(2), 
    Vlr_BasPis numeric(18,8), 
    Alq_Pis numeric(8,4),
    Vlr_Pis numeric(18,8),
    Dif_VlrPis numeric(18,8),
    CST_Cofins varchar(2), 
    Vlr_BasCofins numeric(18,8), 
    Alq_Cofins numeric(8,4), 
    Vlr_Cofins numeric(18,8),
    Dif_VlrCofins numeric(18,8),
    Prc_MaxCon numeric(18,8),
    Prc_Fabric numeric(18,8),
    Des_Fabric varchar(25),
    Flg_DscItePdv bit,
    Prc_UniPdv numeric(18,8),
    Per_DscPdv numeric(8,4),
    Cod_CEST varchar(7),    
    Vlr_BasIcmDes numeric(18,8),
    Per_AcrAlqIntFcp numeric(8,4),
    Alq_IntDes numeric(8,4),
    Alq_Interesta numeric(8,4),
    Per_PrvParIcm numeric(8,4),
    Vlr_IcmFcpDes numeric(18,8),
    Vlr_IcmParDes numeric(18,8),
    Vlr_IcmParRem numeric(18,8),
    Cod_PedCmpCli varchar(20),
    Str_VolEmb varchar(50),
    Obs_IteNf varchar(200),
    Reg_MS varchar(20),
    Des_MtvIseRegMS varchar(255),

    Alq_FcpIcm numeric(8,4),
    Vlr_FcpIcm numeric(18,8),
    Alq_FcpSbt numeric(8,4), 
    Vlr_FcpSbt numeric(18,8), 
    Alq_FcpSbtRet numeric(8,4),
    Vlr_FcpSbtRet numeric(18,8),

    vBCSTRet numeric(18,8),
    pST numeric(8,4),
    vICMSSubstituto numeric(18,8),
    vICMSSTRet numeric(18,8),
    vBCFCPSTRet numeric(18,8),
    pFCPSTRet numeric(8,4), 
    vFCPSTRet numeric(18,8),
    pRedBCEfet numeric(8,4),
    vBCEfet numeric(18,8),
    pICMSEfet numeric(8,4),
    vICMSEfet numeric(18,8),

    cBenef varchar(10)
) 


Declare @Tab Table(
  ChaveTab Int Identity(1,1) PRIMARY KEY
, Obs_Fiscal varchar(800)
)

Declare @NumPdv int,
        @Chave int,
        @ChaveTab int,
        @CodPrd int,
        @SeqIte int,
        @CodLot varchar(20),
        @DatVct datetime,
        @DatFab datetime,
        @QtdMesVld integer,
        @WCodLotOri varchar(20),
        @WValDif numeric(18,8),
        @ParDif numeric(4,2),
        @WValLimDif numeric(18,8),

        @WStatusCab varchar(1),
        @WTipNotCab varchar(1),
        @WValCabRetCStat smallint,
        @WCodTipCon varchar(1),
        @WDatEmiCab datetime,
        @WValCabCodRegTri int,
        @WValCabTipConsumidor varchar(1),
        @WValCabUFEmi varchar(2),
        @WValCabUFDes varchar(2),
        @WValCabBasIcm numeric(18,8),
        @WValCabIcm numeric(18,8),
        @WValCabIcmPro numeric(18,8),
        @WValCabDscCom numeric(18,8),
        @WValCabDscBon numeric(18,8),
        @WValCabRepIcm numeric(18,8),
        @WValCabDscTri numeric(18,8),
        @WValCabBasIcmSbt numeric(18,8),
        @WValCabIcmSbt numeric(18,8),
        @WValCabBasSbtRes numeric(18,8),
        @WValCabSbtRes numeric(18,8),
        @WValCabSbtEmb numeric(18,8),
        @WValCabIpi numeric(18,8),
        @WValCabDevIpi numeric(18,8),
        @WValCabPis numeric(18,8),
        @WValCabCof numeric(18,8),
        @WValCabIcmParDes numeric(18,8), 
        @WValCabIcmParRem numeric(18,8),
        @WValCabCodCmpCli varchar(20),
        @WValCabIcmFcpDes numeric(18,8), 
        @WValCabFcpIcm numeric(18,8), 
        @WValCabFcpSbt numeric(18,8), 
        @WValCabFcpSbtRet numeric(18,8), 
        @WValCabDscSufram numeric(18,8), 
        @WCabObsRodape varchar(max),
        @WCabInsSufram varchar(9),

        @WDesProduto varchar(120),
        @WDesCplProduto varchar(max),
        @WTipLisPis varchar(3),
        @WVlrTotBruIte numeric(18,8),
        @WVlrTotLiqIte numeric(18,8),
        @WVlrDscTotIte numeric(18,8),
        @WVlrBasRepIcm numeric(18,8),
        @WPerRepIcm numeric(7,4),
        @WVlrRepIcm numeric(18,8),
        @WFlgDscItePdv bit,
        @WPrcUniPdv numeric(18,8),
        @WPerDscPdv numeric(8,4),
        @WPerDsc    numeric(8,4),
        @WVlrBasSbtRes numeric(18,8),
        @WVlrBasSbtEmb numeric(18,8),
        @WVlrSbtRes numeric(18,8), 
        @WVlrSbtEmb numeric(18,8),
        @WTipCon varchar(1),
        @WVlrDscTri numeric(18,8),
        @WPerDscTri numeric(18,2),
        @WPerDscIte numeric(18,2),
        @WDesFabric varchar(25),
        @WTipPor344 varchar(2),
        @WTipSai varchar(1),
        @WStrVolEmb varchar(50),
        @WObsIteNf varchar(800),
        @WPrcFabric numeric(18,8),
        @WPerParIcmDef numeric(8,4),
        @WPerAlqInterestaDef numeric(8,4),
        @WAlqIcm numeric(8,4),
        @WObsAux varchar(max),
        @WObsFis varchar(800)


-- normaliza PRODU
Update PRODU
   Set Reg_MS = IsNull(Reg_MS,'')
 Where Reg_MS <> Ltrim(Rtrim(Reg_MS))

-- preencher com zeros à esquerda até 13 posições
Update PRODU
Set Reg_MS = Substring('0000000000000',1,13-Len(Reg_MS))+Reg_MS
Where IsNull(Reg_MS,'') <> ''
And Len(IsNull(Reg_MS,'')) < 13 
And ISNULL(Reg_MS, '') <> 'ISENTO' 

-- parametros na memoria
Declare @pm_FlgImpDscEmbNot bit,
        @pm_CtrImpIteNotFis varchar(1),
        @pm_CodImpPrcFab varchar(1),
        @pm_CodImpDscFab varchar(1),
        @pm_CodImpPMC varchar(1),
        @pm_VerNfe varchar(20),
        @WSelect varchar(max)

Select @pm_FlgImpDscEmbNot = IsNull(FlgImpDscEmbNot,0),
       @pm_CtrImpIteNotFis = IsNull(Ctr_ImpIteNotFis,'') 
From PARAM 
Where Cod_Estabe = @PCodEstabe

Set @pm_CodImpPrcFab = Substring((Select LTrim(Val_Param) From FS_PARAM Where Cod_Estabe = @PCodEstabe and Cod_Param = 'NFE_CFG_DNF_PFABNFE'),1,1)
Set @pm_CodImpDscFab = Substring((Select LTrim(Val_Param) From FS_PARAM Where Cod_Estabe = @PCodEstabe and Cod_Param = 'NFE_CFG_DNF_IMPFBNFE'),1,1)
Set @pm_CodImpPMC = Substring((Select LTrim(Val_Param) From FS_PARAM Where Cod_Estabe = @PCodEstabe and Cod_Param = 'NFE_CFG_DNF_PMCNFE'),1,1)
-- versão da NF-e
Set @pm_VerNfe = Substring((Select Ltrim(Rtrim(Val_Param)) From FS_PARAM Where Cod_Estabe = @PCodEstabe and Cod_PARAM = 'NFE_CFG_VER'),1,20)
if (@pm_VerNfe <> '') and (charIndex('.',@pm_VerNfe) = 0)
  Set @pm_VerNfe = @pm_VerNfe + '.0'

-------------------------------------------------------------------------------------------------------------------------
if @PTipNota = 'S'
  begin

    -- atualiza IE cabecalho
    Update cb 
       Set cb.Cgf = cl.Cgf
     From NFSCB cb 
          Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
    Where cb.Cod_Estabe = @PCodEstabe 
      and cb.Ser_Nota = @PSerNota 
      and cb.Num_Nota = @PNumNota
      and cb.Cod_Cliente > 0
      And IsNull(cl.Cgf,'') <> ''
      And cb.Cgf <> cl.Cgf

    Update cb 
       Set cb.Inscricao_Suframa = cl.Inscricao_Suframa
      From NFSCB cb 
           Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNota 
       and cb.Num_Nota = @PNumNota
       and cb.Cod_Cliente > 0
       And IsNull(cl.Inscricao_Suframa,'') <> ''
       And cb.Inscricao_Suframa <> cl.Inscricao_Suframa

    Update cb 
       Set cb.Cgf = fo.Cgf_Rg
      From NFSCB cb 
           Inner Join FORNE fo on cb.Cod_Fornecedor = fo.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNota 
       and cb.Num_Nota = @PNumNota
       and cb.Cod_Fornecedor > 0
       and IsNull(fo.Cgf_Rg,'') <> ''
       and cb.Cgf <> fo.Cgf_Rg

    Exec PR_CalcTributSTRetAntNFSCB @PCodEstabe, @PSerNota, @PNumNota

    -- monta mensagens NFS em NSCOB e NSIOB
    Exec PR_GeraMensagensNF @PCodEstabe, @PNumNota, @PSerNota, @PTipNota

    Select @NumPdv = IsNull(cb.Cod_Pedido,0), 
           @WStatusCab = IsNull(cb.Status,''),
           @WValCabRetCStat = IsNull(cb.Ret_CStat,0),
           @WTipNotCab = cb.Tip_Saida, 
           @WCodTipCon = dbo.FN_CodTipConsum (cb.Tip_Consumidor, '', cb.Cgc, cb.Cgf, cb.Estado),
           @WDatEmiCab = cb.Dat_Emissao,
           @WValCabCodRegTri = IsNull(cb.Cod_RegTri,0),
           @WValCabTipConsumidor = IsNull(cb.Tip_Consumidor,''),
           @WValCabUFEmi = IsNull(es.Des_Estado,''),
           @WValCabUFDes = IsNull(cb.Estado,''),
           @WValCabBasIcm = Round(IsNull(cb.Vlr_BasIcmsTri,0),2),
           @WValCabIcm = Round(IsNull(cb.Vlr_IcmsTri,0),2),
           @WValCabIcmPro = Round(IsNull(cb.Vlr_IcmsNor,0),2),
           @WValCabDscCom = Round(IsNull(cb.Vlr_DescontoCom,0),2),
           @WValCabDscBon = Round(IsNull(cb.Vlr_DscBon,0),2),
           @WValCabRepIcm = Round(IsNull(cb.Vlr_RepIcms,0),2),
           @WValCabDscTri = Round(IsNull(cb.Vlr_DscTri,0),2),
           @WValCabBasIcmSbt = Round(IsNull(cb.Vlr_BasSubsTrib,0),2),
           @WValCabIcmSbt = Round(IsNull(cb.Vlr_SubsTrib,0),2),
           @WValCabBasSbtRes = Round(IsNull(cb.Vlr_BasSbtRes,0),2),
           @WValCabSbtRes = Round(IsNull(cb.Vlr_SbtRes,0),2),
           @WValCabSbtEmb = Round(IsNull(oc.Vlr_SubsTrib,0),2),  -- aqui pode ser Vlr_SbtRes, recalcular este valor
           @WValCabIpi = Case When (cb.Tip_Saida = 'D') and (IsNull(cb.Vlr_Ipi,0) > 0) then 0 Else Round(IsNull(cb.Vlr_Ipi,0),2) End, 
           @WValCabDevIpi = Case When (cb.Tip_Saida = 'D') and (IsNull(cb.Vlr_Ipi,0) > 0) then Round(IsNull(cb.Vlr_Ipi,0),2) Else 0 End, 
           @WValCabPis = Round(IsNull(cb.Vlr_Pis,0),2),
           @WValCabCof = Round(IsNull(cb.Vlr_Cofins,0),2),
           @WValCabIcmParDes = Round(IsNull(cb.Vlr_IcmParDes,0),2), 
           @WValCabIcmParRem = Round(IsNull(cb.Vlr_IcmParRem,0),2),
           @WValCabCodCmpCli = IsNull(cb.Ide_PedCmp,''),
           @WValCabIcmFcpDes = Round(IsNull(cb.Vlr_IcmFcpDes,0),2), 
           @WValCabFcpIcm = Round(IsNull(cb.Vlr_FcpIcm,0),2), 
           @WValCabFcpSbt = Round(IsNull(cb.Vlr_FcpSbt,0),2), 
           @WValCabFcpSbtRet = Round(IsNull(cb.Vlr_FcpSbtRet,0),2),
           @WValCabDscSufram = Round(IsNull(cb.Vlr_DscCalSuframa,0),2),
           @WCabObsRodape = IsNull(cb.Obs_Rodape,''),
           @WCabInsSufram = IsNull(cb.Inscricao_Suframa,'?')
      From NFSCB cb 
           Inner Join ESTAB es on cb.Cod_Estabe = es.Cod_Estabe
           left join NSOCB oc on ((cb.Cod_Estabe = oc.Cod_Estabe) and (cb.Ser_Nota = oc.Ser_Nota) and (cb.Num_Nota = oc.Num_Nota))       
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNota 
       and cb.Num_Nota = @PNumNota

/* aqui registros em NSCOB montados em uFiscal

    -- Observacao cabeçalho
    Set @WObsAux = Ltrim(Rtrim(@WCabObsRodape))

    Delete From @Tab


    Insert Into @Tab (Obs_Fiscal)
      Select Des_Observ From NSCOB
       Where Cod_Estabe = @PCodEstabe 
         and Ser_Nota = @PSerNota 
         and Num_Nota = @PNumNota

    While Exists(Select 1 From @Tab)
      begin
        Select top 1
               @ChaveTab = ChaveTab
             , @WObsFis = Obs_Fiscal
          From @Tab
         Order by ChaveTab

        if PatIndex(@WObsFis+'%', @WObsAux) = 0
          begin
            if (Len(@WObsAux) > 0) and
               (Substring(@WObsAux,1,Len(@WObsAux)) <> ';')
              Set @WObsAUx = @WObsAux + ';  '

            Set @WObsAux = @WObsAux + @WObsFis
          end

        Delete From @Tab Where ChaveTab = @ChaveTab
      end

    -- FECOP Icms
    if (@WValCabFcpIcm > 0) and  -- NFSCB: Vlr_FcpIcm, Vlr_BasIcmsNor
       (PatIndex('%B.Calculo Fecop%', @WObsAux) = 0)
      begin
        if (Len(@WObsAux) > 0) and
           (Substring(@WObsAux,1,Len(@WObsAux)) <> ';')
          Set @WObsAUx = @WObsAux + ';  '

        Set @WObsAux = @WObsAux + 
                               'B.Calculo Fecop: '+cast(cast(Round(@WValCabIcmPro,2) as money) as varchar)+' '+
                       'Vlr.Fecop: '+cast(cast(Round(@WValCabFcpIcm,2) as money) as varchar) -- +char(13)+char(10)
      end

    -- FECOP ST
    if (@WValCabFcpSbt > 0) and  -- NFSCB.Vlr_FcpSbt
       (PatIndex('%B.Calc.Fecop ST%', @WObsAux) = 0)
      begin
        if (Len(@WObsAux) > 0) and
           (Substring(@WObsAux,1,Len(@WObsAux)) <> ';')
          Set @WObsAUx = @WObsAux + ';  '

        Set @WObsAux = @WObsAux + 
                               'B.Calc.Fecop ST: '+cast(cast(Round(@WValCabBasIcmSbt,2) as money) as varchar)+' '+
                       'Vlr.Fecop ST: '+cast(cast(Round(@WValCabFcpSbt,2) as money) as varchar) -- +char(13)+char(10)
      end

    -- SUFRAMA
        -- Conforme ICM (65/88) e Lei 10.966/2004 Art 2º desconto de R$ 99,99 aplicado ref. isenção ICMS - 12% Suframa destinatário XXXXXXXXX
    if (@WValCabDscSufram > 0) and
       (PatIndex('%Lei 10.966/2004%', @WObsAux) = 0)
      begin
        Set @WAlqIcm = 0

        -- pegar alq de um item suframa....  
        Select Top 1 @WAlqIcm = Case When (@WTipNotCab <> 'D') then Isnull(rx.Alq_IcmExtLoc,0) Else Isnull(rx.Alq_IcmExtReg,0) End
          From NFSIT it
               inner Join RTXCT rx on rx.Cod_RegTri = @WValCabCodRegTri and rx.Cod_ClaTri = it.Cod_ClaTri
         Where IsNull(it.Vlr_DscCalSuframa,0) > 0 

        if (Len(@WObsAux) > 0) and
           (Substring(@WObsAux,1,Len(@WObsAux)) <> ';')
          Set @WObsAUx = @WObsAux + ';  '

        Select @WObsAux = @WObsAux +
                          'Conforme ICM (65/88) e Lei 10.966/2004 Art 2º '+
                          'desconto de '+cast(cast(Round(@WValCabDscSufram,2) as money) as varchar)+' '+
                          'aplicado ref. isenção ICMS - '+cast(cast(Round(@WAlqIcm,2) as money) as varchar)+'% '+
                          'destinatario '+cl.Razao_Social  -- +char(13)+char(10)
             From NFSCB cb 
                  Inner Join CLIEN cl on cb.Cod_CLiente = cl.Codigo
             Where cb.Cod_Estabe = @PCodEstabe
             And cb.Ser_Nota = @PSerNota
             And cb.Num_Nota = @PNumNota
      end

    if @WObsAux <> ''
      Update NFSCB
        Set Obs_Rodape = @WObsAux
      Where Cod_Estabe = @PCodEstabe
      And Ser_Nota = @PSerNota
      And Num_Nota = @PNumNota

*/

    if Exists(Select 1 From NFSIT it Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
               Where it.Cod_Estabe = @PCodEstabe
                 And it.Num_Nota = @PNumNota
                 And it.Ser_Nota = @PSerNota
                 And IsNull(it.Cod_NCM,'') <> cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar))
      begin
        Exec PR_RecalculaPisCofins @PCodEstabe, @PNumNota, @PSerNota, @PTipNota
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end
      end

    Update it
       Set it.Cod_NCM = cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar)
      From NFSIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
       And IsNull(it.Cod_NCM,'') <> cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar)
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_CEST = cast(Substring(IsNull(pr.Cod_CEST,''),1,7) as varchar)
      From NFSIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
       And IsNull(it.Cod_CEST,'') <> cast(Substring(IsNull(pr.Cod_CEST,''),1,7) as varchar)
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_GrpPrc = IsNull(pr.Cod_GrpPrc,'')
      From NFSIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
--       And IsNull(it.Cod_GrpPrc,'') = ''
       And it.Cod_GrpPrc <> IsNull(pr.Cod_GrpPrc,'')
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_OriMer = IsNull(pr.Cod_OriMer,'0')
      From NFSIT it
           Inner Join PRXES pr on pr.Cod_Estabe = it.Cod_Estabe and pr.Cod_Produt = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
--       And IsNull(it.Cod_OriMer,'') = ''
       And it.Cod_OriMer <> IsNull(pr.Cod_OriMer,'0')
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'


    -- atualiza dados faturamento por peso/volume
    Update it
      Set it.Des_UnvPesVolImpFat = ap.Des_UndPesVolApr,
          it.Qtd_PesVolImpFat = (it.Qtd_Produto+it.Qtd_Bonificacao)/it.Fat_CnvImpFat*ap.Qtd_PesVolApr,
          it.Prc_UniPesVolImpFat = it.Prc_Unitario*it.Fat_CnvImpFat/ap.Qtd_PesVolApr
    From NFSIT it 
         Inner Join PARAM pm on it.Cod_Estabe = pm.Cod_Estabe
         Inner Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and it.Fat_CnvImpFat = ap.Fat_CnvApr
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota
    And it.Fat_CnvImpFat > 0
    And IsNull(it.Des_UnvImpFat,'') = IsNull(ap.Des_UnvApr,'')
    And IsNull(pm.FlgAltUnvItePdv,0) = 1
    And ((IsNull(ap.Flg_FatPes,0) = 1) or (IsNull(ap.Flg_FatVol,0) = 1))
    And IsNull(ap.Qtd_PesVolApr,0) > 0


    -- % FCP default
    Set @WPerParIcmDef = IsNull((Select max(Per_PrvParIcm)
                                 From NFSIT
                                 Where Cod_Estabe = @PCodEstabe
                                 And Num_Nota = @PNumNota
                                 And Ser_Nota = @PSerNota),0)
      
    -- 7%  UF Emissao: Sul e SE exceto ES:  ';MG;RJ;SP;PR;SC;RS;'
    --        Destino: N, NE e ES
    if (Charindex(@WValCabUFEmi,';MG;RJ;SP;PR;SC;RS;') > 0) and   -- S, SE, exceto ES
           (Charindex(@WValCabUFDes,';MG;RJ;SP;PR;SC;RS;') = 0)       -- N, NE e ES
      Set @WPerAlqInterestaDef = 7.00
    else
      Set @WPerAlqInterestaDef = 12.00


    -- atualiza cBenef NFSIT: UF Emitente
    -- Exige o código de benefício fiscal (cBenef) quando se utiliza um CST de benefício fiscal (20, 30, 40, 41, 50, 51, 60 ou 90).
        -- verifica beneficio por NCM
        -- devolucao ?????
/*
    Update it
      Set it.cBenef = ''
    From NFSIT it
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota

    Update it
      Set it.cBenef = IsNull(un.Cod_Benefe,'')
    From NFSIT it
         Inner JOIN UFNCM un on (un.Cod_UF = @WValCabUFEmi) and (un.Cod_NCM = Substring(it.Cod_NCM,1,Len(IsNull(un.Cod_NCM,''))))
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota
    And IsNull(un.Cod_Benefe,'') <> ''
--    And Charindex(it.Ctrl_Tributacao,';20;30;40;41;50;51;60;90;') > 0
    And Charindex(it.Ctrl_Tributacao,dbo.FN_ListaCSTBeneficio(un.Cod_Benefe)) > 0
    And Len(IsNull(un.Cod_NCM,'')) < 8

    Update it
      Set it.cBenef = IsNull(un.Cod_Benefe,'')
    From NFSIT it
         Inner JOIN UFNCM un on un.Cod_UF = @WValCabUFEmi and un.Cod_NCM = it.Cod_NCM
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota
    And IsNull(un.Cod_Benefe,'') <> ''
    And Charindex(it.Ctrl_Tributacao,dbo.FN_ListaCSTBeneficio(un.Cod_Benefe)) > 0

        -- verifica beneficio por Produto
    Update it
      Set it.cBenef = IsNull(up.Cod_Benefe,'')
    From NFSIT it
         Inner JOIN UFXPR up on up.Cod_UF = @WValCabUFEmi and up.Cod_Produt = it.Cod_Produto
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota
    And IsNull(up.Cod_Benefe,'') <> ''
    And Charindex(it.Ctrl_Tributacao,dbo.FN_ListaCSTBeneficio(up.Cod_Benefe)) > 0
*/

    Update it
       Set it.cBenef = dbo.FN_RetornaCBenef(@WValCabUFEmi, it.Ctrl_Tributacao, it.Cod_NCM, it.Cod_Produto, @WDatEmiCab)
     From NFSIT it
    Where it.Cod_Estabe = @PCodEstabe
      And it.Num_Nota = @PNumNota
      And it.Ser_Nota = @PSerNota

   -- paleativo: corrige CST 90 para não contribuintes
    Update it
       Set it.Ctrl_Tributacao = '41'
      From NFSIT it
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
       And @WCodTipCon = 'N'
       And it.Ctrl_Tributacao = '90'

   -- paleativo: corrige % Repasse enquanto este % não for determinado pela procedure PR_CalTributItem....
    Update it
       Set it.Per_RepIcms = Case
                              When it.Vlr_RepIcms = 0 then 0
                              When (IsNull(rx.Cod_RegTri,0) > 0) and (@WTipNotCab <> 'D') then Round(rx.C_PerRepIcmLoc,2)
                              When (IsNull(rx.Cod_RegTri,0) > 0) and (@WTipNotCab  = 'D') then Round(rx.C_PerRepIcmReg,2)
                              -- Diego: Forçando o valor para a Neosul (Clamed) Temporário, rever com o Cládio
                              When (IsNull(it.Vlr_BasRepIcms,0) > 0) and (Round(it.Vlr_RepIcms*100/it.Vlr_BasRepIcms,2) > 14) then 14.58
                              When (IsNull(it.Vlr_BasRepIcms,0) > 0) and (Round(it.Vlr_RepIcms*100/it.Vlr_BasRepIcms,2) >  6) then  6.82
                              When IsNull(it.Vlr_BasRepIcms,0) > 0 then Round(it.Vlr_RepIcms*100/it.Vlr_BasRepIcms,2)
                              Else 0
                            End
      From NFSIT it
           left Join RTXCT rx on rx.Cod_RegTri = @WValCabCodRegTri and rx.Cod_ClaTri = it.Cod_ClaTri
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
       And IsNull(it.Per_RepICms,0) = 0

    Insert Into #TMP_Itens
      Select it.Cod_Produto, it.Num_SeqIte,
             Num_SeqPdc = Case 
                            When IsNull(it.Num_SeqPdc,'') <> '' then Substring(IsNull(it.Num_SeqPDc,''),1,6)
                            Else Substring(Cast(it.Num_SeqIte as varchar),1,6)
                          End,
             Cod_EAN = Case 
                         When (IsNull(pr.Cod_Ean, '') = '') and Exists(Select 1 From PREAN pe Where pr.Codigo = pe.Cod_Produt And pe.Tip_Cod = '3') Then
                             (Select top 1 IsNull(pe.Cod_Ean, '') 
                                From PREAN pe 
                               Where pr.Codigo = pe.Cod_Produt 
                                 And pe.Tip_Cod = '3'
                                 And len(pe.Cod_Ean) > 1 
                               Order by len(pe.Cod_Ean) Desc)
                         When (IsNull(pr.Cod_Ean, '') = '') and Exists(Select 1 From PREAN pe  Where pr.Codigo = pe.Cod_Produt And pe.Tip_Cod = '4') Then
                             (Select top 1 IsNull(pe.Cod_Ean, '') 
                                From PREAN pe 
                               Where pr.Codigo = pe.Cod_Produt 
                                 And pe.Tip_Cod = '4'
                                 And len(pe.Cod_Ean) > 1 
                               Order by len(pe.Cod_Ean) Desc)
                         Else IsNull(pr.Cod_Ean,'')
                       End,
             Tip_Sai = IsNull(it.Tip_Sai,''),
             Cod_NCM = IsNull(it.Cod_NCM,''),
             Cod_GrpPrc = IsNull(it.Cod_GrpPrc,''),
             it.Cod_Cfo, 
             Tip_Por344 = IsNull(pr.Tip_Por344,''),
             Tip_LisPis = ISNull(it.Tip_Aux,''),
             Des_Produto = Case 
                             When ix.Cod_Produt > 0 then Substring(ix.Des_PrdDet,1,120) 
                             When IsNull(it.Des_AprImpFat,'') <> '' then rtrim(pr.Descri)+' '+it.Des_AprImpFat
                             Else pr.Descricao
                           End,
             Obs_Produto = '', 

             Und_Com = Case
                         When IsNull(it.Qtd_PesVolImpfat,0) > 0 then it.Des_UnvPesVolImpFat
                             When (IsNull(it.Qtd_ImpFat,0) > 0) and (IsNull(it.Prc_UniImpFat,0) > 0) and (IsNull(it.Des_UnvImpFat,'') <> '') and
                              (not Exists(Select 1 From NFSIT 
                                           Where Cod_Estabe = it.Cod_Estabe 
                                             And Ser_Nota = it.Ser_Nota And Num_Nota = it.Num_Nota
                                             And Cod_Produto = it.Cod_Produto
                                             And Qtd_ImpFat-cast(Qtd_ImpFat as integer) <> 0)) then it.Des_UnvImpFat
                         When ((ix.Cod_Produt > 0) and (IsNull(ix.Des_UndVen,'') <> '')) then ix.Des_UndVen
                         Else pr.Unidade_Venda
                       End,
             Qtd_Com = Case 
                         When IsNull(it.Qtd_PesVolImpfat,0) > 0 then it.Qtd_PesVolImpfat
                             When (IsNull(it.Qtd_ImpFat,0) > 0) and (IsNull(it.Prc_UniImpFat,0) > 0) and
                              (not Exists(Select 1 From NFSIT 
                                           Where Cod_Estabe = it.Cod_Estabe 
                                             And Ser_Nota = it.Ser_Nota And Num_Nota = it.Num_Nota
                                             And Cod_Produto = it.Cod_Produto
                                             And Qtd_ImpFat-cast(Qtd_ImpFat as integer) <> 0)) then Qtd_ImpFat
                         Else IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)
                       end,

             Prc_UniCom = Case 
                            When IsNull(it.Qtd_PesVolImpfat,0) > 0 then it.Prc_UniPesVolImpFat
                                When (IsNull(it.Qtd_ImpFat,0) > 0) and (IsNull(it.Prc_UniImpFat,0) > 0) and
                                 (not Exists(Select 1 From NFSIT 
                                              Where Cod_Estabe = it.Cod_Estabe 
                                                And Ser_Nota = it.Ser_Nota And Num_Nota = it.Num_Nota
                                                And Cod_Produto = it.Cod_Produto
                                                And Qtd_ImpFat-cast(Qtd_ImpFat as integer) <> 0)) then it.Prc_UniImpFat
                            Else IsNull(it.Prc_Unitario,0)
                          end,

             Vlr_TotBruIte = Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)),2),
--             Vlr_TotIte = Round(IsNull(it.Qtd_Produto,0)*(IsNull(it.Prc_Unitar,0)*(1-IsNull(it.Per_Desconto,0)/100)),2),
--             Vlr_TotIte = Round(IsNull(it.Vlr_TotItem,0),2),
             Vlr_TotIte = Case
                            When Round(IsNull(it.Vlr_TotItem,0),2) <= Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)),2)
                                 Then Round(IsNull(it.Vlr_TotItem,0),2) 
                            Else Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)),2)
                          End,
             Per_Desconto = IsNull(it.Per_Desconto,0),
             Vlr_BasRepIcm = IsNull(it.Vlr_BasRepIcms,0),
             Per_RepIcm = IsNull(it.Per_RepIcms,0),
             Vlr_RepIcm = Round(IsNull(it.Vlr_RepIcms,0),2),
             Tip_Consumidor = @WValCabTipConsumidor,
             Vlr_DscTri = Round(IsNull(it.Vlr_DscTri,0),2),
                         Per_DscTri = IsNull(it.Per_DscTri,0),
             Vlr_DscRat = Round(IsNull(it.Vlr_DescRateado,0),2),
             Vlr_DscBonRat = Round(IsNull(it.Vlr_DscBonRat,0),2),
             Vlr_DscTotIte = 0,
             Vlr_BasSbtRes = Round(IsNull(it.Vlr_BasSbtRes,0),2),        
             Vlr_SbtRes = Round(IsNull(it.Vlr_SbtRes,0),2), 
             Vlr_BasSbtEmb = Round(IsNull(oi.Vlr_BasSubsTrib,0),2),
             Vlr_SbtEmb = Round(IsNull(oi.Vlr_SubsTrib,0),2),
             it.Cod_Lote, 
             it.Cod_Lote, 
             IsNull(lt.Dat_Vencim,0),
             IsNull(lt.Dat_Fabric,0),
             IsNull(pr.Validade,0),
             Vlr_Frete  = Round(IsNull(it.Vlr_Frete,0),2),
             Vlr_Seguro = Round(IsNull(it.Vlr_Seguro,0),2),
             Vlr_DspRat = Round(IsNull(it.Vlr_DespRateada,0),2),
             Vlr_DspExt = Round(IsNull(it.Vlr_DspExt,0),2),
             Vlr_TotDsp = 0,
             Und_Tri = pr.Unidade_Venda,
             Qtd_Tri = IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0),
             Prc_UniTri = IsNull(it.Prc_Unitario,0),          
             Cod_OriPrd = IsNull(it.Cod_OriMer,'0'),
             Cod_CstIcm = IsNull(it.Ctrl_Tributacao,''),
             Cod_CsosnIcm = IsNull(it.Cod_CSOSN,''),
             Cod_ModBasCalIcm = IsNull(it.Cod_ModBasCalIcm,''),
             Per_RedBasCalIcm = IsNull(it.Per_RedBasCalIcm,0),
             Vlr_BasIcm = Round(IsNull(it.Vlr_BasIcmsTri,0),2),
             Alq_Icm = IsNull(it.Alq_Icms,0),
             Vlr_Icm = Round(IsNull(it.Vlr_IcmsTri,0),2),
             Dif_VlrIcm = Round(IsNull(it.Vlr_IcmsTri,0),2) - IsNull(it.Vlr_IcmsTri,0),
             Vlr_BasIcmPro = Round(IsNull(it.Vlr_BasIcmsNor,0),2),
             Vlr_IcmPro = Round(IsNull(it.Vlr_IcmsNor,0),2),
             Per_IcmDiferi = IsNull(it.Per_IcmDiferi,0),
             Vlr_IcmDiferi = Round(IsNull(it.Vlr_IcmDiferi,0),2),
             Vlr_DscCalSuframa = Round(IsNull(it.Vlr_DscCalSuframa,0),2),
             Vlr_IcmDesone = IsNull(it.Vlr_IcmsDeson,0), 
             Cod_MtvIcmDesone = IsNull(it.Cod_MtvIcmsDeson,''),
             Vlr_BasIcmSbtRet = 0,
             Vlr_IcmSbtRet = 0,  --IsNull(oi.Vlr_SubsTrib,0),
             Cod_ModBasCalIcmSbt = IsNull(it.Cod_ModBasCalIcmSbt,''),
             Alq_AgrSbt = IsNull(it.Alq_AgrSbt,0), 
             Per_RedBasCalIcmSbt = IsNull(it.Per_RedBasCalIcmSbt,0),
             Vlr_BasIcmSbt = Round(IsNull(it.Vlr_BasSubsTrib,0),2),
             Alq_IcmSbt = IsNull(it.Alq_IcmSbt,0),
             Vlr_IcmSbt = Round(IsNull(it.Vlr_SubsTrib,0),2),

             CST_Ipi    = Case When IsNull(CST_Ipi,'') = '' then '99' Else CST_Ipi End, -- outras
                         Cod_EnqIpi = Case When IsNull(Cod_EnqIpi,'') = '' then '999' Else Cod_EnqIpi End,
                         Vlr_BasIpi = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_BasIpi,0) > 0) then 0 Else Round(IsNull(it.Vlr_BasIpi,0),2) End,
             Alq_Ipi    = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_Ipi,0) > 0) then 0 
                               Else Case When it.Vlr_TotItem > 0 then (it.Vlr_Ipi * 100 / it.Vlr_TotItem) Else 0 End End, 
             Vlr_Ipi    = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_Ipi,0) > 0) then 0 Else IsNull(it.Vlr_Ipi,0) End, 
                         Vlr_BasDevIpi = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_BasIpi,0) > 0) then Round(IsNull(it.Vlr_BasIpi,0),2) Else 0 End,
             Per_DevIpi = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_Ipi,0) > 0) then 100.00 Else 0 End,
             Vlr_DevIpi = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_Ipi,0) > 0) then it.Vlr_Ipi Else 0 End,

             it.CST_Pis, it.Vlr_BasPis, it.Alq_Pis, Vlr_Pis = Round(IsNull(it.Vlr_Pis,0),2), 
             Dif_VlrPis = Round(IsNull(it.Vlr_Pis,0),2)-IsNull(it.Vlr_Pis,0), 
             it.CST_Cofins, it.Vlr_BasCofins, it.Alq_Cofins, Vlr_Cofins = Round(IsNull(it.Vlr_Cofins,0),2),
             Dif_VlrCofins = Round(IsNull(it.Vlr_Cofins,0),2)-IsNull(it.Vlr_Cofins,0),
             Prc_MaxCon = Case
                            When @pm_CodImpPMC = '1' then IsNull(it.Prc_MaxCon,0)*IsNull(it.Fat_CnvImpFat,1)
                            Else 0
                          End, 
             Prc_Fabric = IsNull(it.Prc_Fabric,0)*IsNull(it.Fat_CnvImpFat,1), 
             Des_Fabric = Case 
                             When (ix.Cod_Produt > 0) and (IsNull(ix.Des_Fabric,'') <> '') then Substring(ix.Des_Fabric,1,25) 
                             Else Substring(fb.Fantasia,1,25)
                           End,
             Flg_DscItePdv = IsNull(it.Flg_DscItePdv,0),
             Prc_UniPdv = ISNULL(it.Prc_UniPdv,0),
             Per_DscPdv = ISNULL(it.Per_DscPdv,0),
             Cod_CEST = ISNULL(it.Cod_CEST,''),
  
             Vlr_BasIcmDes = Case 
                               When (@WPerParIcmDef > 0) or (IsNull(it.Vlr_IcmFcpDes,0) > 0) then Round(IsNull(it.Vlr_BasIcmsNor,0),2) 
                               Else 0
                             End,
             Per_AcrAlqIntFcp = Case
                                  When (ISNULL(it.Per_PrvParIcm,0) > 0) and (IsNull(it.Vlr_IcmFcpDes,0) > 0) then ISNULL(it.Per_AcrAlqIntFcp,0) 
                                  Else 0
                                End,
             Alq_IntDes = Case 
                            When (@WPerParIcmDef > 0) then ISNULL(it.Alq_IntIcmDes,0)
                            Else 0
                          End,
             Alq_Interesta = Case
                               When (@WPerParIcmDef > 0) and (it.Cod_OriMer IN ('1', '2', '3', '8')) then 4.0 /* DMD-8037: Regra NA09-20 */
                 When (@WPerParIcmDef > 0) and (ISNULL(it.Alq_Icms,0) > 0) then ISNULL(it.Alq_Icms,0)
                               When (@WPerParIcmDef > 0) and (ISNULL(it.Alq_Icms,0) = 0) then @WPerAlqInterestaDef                 
                               Else 0
                             End,
             Per_PrvParIcm = Case 
                               When (@WPerParIcmDef > 0) or (IsNull(it.Vlr_IcmFcpDes,0) > 0) then @WPerParIcmDef 
                               Else 0 
                             End, 
             Vlr_IcmFcpDes = Round(IsNull(it.Vlr_IcmFcpDes,0),2), 
             Vlr_IcmParDes = Round(IsNull(it.Vlr_IcmParDes,0),2), 
             Vlr_IcmParRem = Round(IsNull(it.Vlr_IcmParRem,0),2),
             Cod_PedCmpCli = @WValCabCodCmpCli,
             Str_VolEmb = IsNull(it.Str_VolEmb,''),
             Obs_IteNf = IsNull(it.Obs_Nf,''),
             Reg_MS = IsNull(pr.Reg_MS,''),
             Des_MtvIseRegMS = Substring(IsNull(pr.Des_MtvIseRegMS,''),1,255),

             Alq_FcpIcm = IsNull(it.Alq_FcpIcm,0),
             Vlr_FcpIcm = Round(IsNull(it.Vlr_FcpIcm,0),2),
             Alq_FcpSbt = IsNull(it.Alq_FcpSbt,0),
             Vlr_FcpSbt = Round(IsNull(it.Vlr_FcpSbt,0),2),
             Alq_FcpSbtRet = IsNull(it.Alq_FcpSbtRet,0),
             Vlr_FcpSbtRet = Round(IsNull(it.Vlr_FcpSbtRet,0),2),

             vBCSTRet = IsNull(it.vBCSTRet,0),
             pST = IsNull(it.pST,0),
             vICMSSubstituto = IsNull(it.vICMSSubstituto,0),
             vICMSSTRet = IsNull(it.vICMSSTRet,0),
             vBCFCPSTRet = IsNull(it.vBCFCPSTRet,0),
             pFCPSTRet = IsNull(it.pFCPSTRet,0), 
             vFCPSTRet = Round(IsNull(it.vFCPSTRet,0),2),

             pRedBCEfet = Case When @WValCabTipConsumidor = 'F' then IsNull(it.pRedBCEfet,0) Else 0 End,  -- somente para consumidor final: @WValCabTipConsumidor
             vBCEfet    = Case When @WValCabTipConsumidor = 'F' then IsNull(it.vBCEfet,0)    Else 0 End,
             pICMSEfet  = Case When @WValCabTipConsumidor = 'F' then IsNull(it.pICMSEfet,0)  Else 0 End,
             vICMSEfet  = Case When @WValCabTipConsumidor = 'F' then IsNull(it.vICMSEfet,0)  Else 0 End,

             cBenef = IsNull(it.cBenef,'')

      From NFSIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
           Inner Join FABRI fb on fb.Codigo = pr.Cod_Fabricante
           left  join NSOIT oi on ((it.Cod_Estabe = oi.Cod_Estabe) and (it.Ser_Nota = oi.Ser_Nota) and (it.Num_Nota = oi.Num_Nota)       
                              and (it.Cod_Produto = oi.Cod_Produto) and (it.Cod_Lote = oi.Cod_Lote) and (it.Num_SeqIte = oi.Num_SeqIte)) 
           left  join ITDES ix on ((it.Cod_Estabe = ix.Cod_Estabe) and (ix.Num_Pedido = @NumPdv) and (it.Cod_Produto = ix.Cod_Produt)) 
           left  Join (Select Cod_Estabe, Cod_Produt, Cod_Lote,
                              Dat_Vencim = MIN(Dat_Vencim), Dat_Fabric = MIN(Dat_Fabric) 
                        From PRLOT 
                       Where Cod_Estabe = @PCodEstabe
                       Group by Cod_Estabe, Cod_Produt, Cod_Lote) lt on ((it.Cod_Estabe = lt.Cod_Estabe) and (it.Cod_Produto = lt.Cod_Produt) and (it.Cod_Lote = lt.Cod_Lote))
      Where it.Cod_Estabe = @PCodEstabe
        And it.Num_Nota = @PNumNota
        And it.Ser_Nota = @PSerNota
      Order by it.Cod_Produto

  end  -- if @PTipNota = 'S'
else
  begin

    -- se for devolucao
    if @WTipNotCab = 'D'
      Exec PR_CalcTributSTRetAntNFECB @PCodEstabe, @PNumNota

    -- normaliza itens da NF
    Update it
       Set it.Cod_NCM = cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar)
      From NFEIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Protocolo = @PNumNota
       And IsNull(it.Cod_NCM,'') <> cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar)
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_CEST = cast(Substring(IsNull(pr.Cod_CEST,''),1,7) as varchar)
      From NFEIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Protocolo = @PNumNota
       And IsNull(it.Cod_CEST,'') <> cast(Substring(IsNull(pr.Cod_CEST,''),1,7) as varchar)
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_OriMer = IsNull(pr.Cod_OriMer,'0')
      From NFEIT it
           Inner Join PRXES pr on pr.Cod_Estabe = it.Cod_Estabe and pr.Cod_Produt = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Protocolo = @PNumNota
--       And IsNull(it.Cod_OriMer,'') = ''
       And it.Cod_OriMer <> IsNull(pr.Cod_OriMer,'0')
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    -- atualiza IE cabecalho
    Update cb 
       Set cb.Cgf_Rg = fo.Cgf_Rg
      From NFECB cb 
           Inner Join FORNE fo on cb.Cod_EmiFornec = fo.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Protocolo = @PNumNota
       and cb.Cod_EmiFornec > 0
       And IsNull(fo.Cgf_Rg,'') <> ''
       And cb.Cgf_Rg <> fo.Cgf_Rg

    Update cb 
       Set cb.Cgf_Rg = cl.Cgf
      From NFECB cb 
           Inner Join CLIEN cl on cb.Cod_EmiCliente = cl.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Protocolo = @PNumNota
       and cb.Cod_EmiCliente > 0
       And IsNull(cl.Cgf,'') <> ''
       And cb.Cgf_Rg <> cl.Cgf

    Update cb 
       Set cb.Cgf_Rg = tr.Cgf_Rg
      From NFECB cb 
           Inner Join TRANS tr on cb.Cod_EmiTransp = tr.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Protocolo = @PNumNota
       and cb.Cod_EmiTransp > 0
       And IsNull(tr.Cgf_Rg,'') <> ''
       And cb.Cgf_Rg <> tr.Cgf_Rg


    -- monta mensagens NFS em NECOB e NEIOB
    Exec PR_GeraMensagensNF @PCodEstabe, @PNumNota, @PSerNota, @PTipNota

    Select @NumPdv = cb.Cod_Pedido, 
           @WStatusCab = IsNull(cb.Status,''),
           @WValCabRetCStat = IsNull(cb.Ret_CStat,0),
           @WTipNotCab = cb.Tip_NF,
           @WCodTipCon = dbo.FN_CodTipConsum (cb.Tip_Consumidor, '', cb.Cgc_Cpf, cb.Cgf_Rg, cb.Cod_UfOrigem),
           @WDatEmiCab = cb.Dat_Emissao,
           @WValCabCodRegTri = IsNull(cb.Cod_RegTri,0),
           @WValCabTipConsumidor = IsNull(cb.Tip_Consumidor,''),
           @WValCabUFEmi = IsNull(cb.Cod_UFOrigem,''),
           @WValCabUFDes = IsNull(es.Des_Estado,''),
           @WValCabBasIcm = Round(IsNull(cb.Vlr_BasIcmsTri,0),2),
           @WValCabIcm = Round(IsNull(cb.Vlr_IcmsTri,0),2),
           @WValCabIcmPro = Round(IsNull(cb.Vlr_IcmsNor,0),2),
           @WValCabDscCom = Round(IsNull(cb.Vlr_Desconto,0),2),
           @WValCabDscBon = 0,
           @WValCabRepIcm = Round(IsNull(cb.Vlr_RepIcms,0),2),
           @WValCabDscTri = Round(IsNull(cb.Vlr_DscTri,0),2),
           @WValCabBasIcmSbt = Round(IsNull(cb.Vlr_BasIstFon,0),2),
           @WValCabIcmSbt = Round(IsNull(cb.Vlr_IstFon,0),2),
           @WValCabBasSbtRes = Round(IsNull(cb.Vlr_BasSbtRes,0),2),
           @WValCabSbtRes = Round(IsNull(cb.Vlr_SbtRes,0),2),
           @WValCabIpi = Round(IsNull(cb.Vlr_Ipi,0),2),
           @WValCabDevIpi = 0,
           @WValCabPis =  Round(IsNull(cb.Vlr_Pis,0),2),
           @WValCabCof =  Round(IsNull(cb.Vlr_Cofins,0),2),
           @WValCabIcmParDes = Round(IsNull(cb.Vlr_IcmParDes,0),2), 
           @WValCabIcmParRem = Round(IsNull(cb.Vlr_IcmParRem,0),2),
           @WValCabCodCmpCli = '',
           @WValCabIcmFcpDes = Round(IsNull(cb.Vlr_IcmFcpDes,0),2), 
           @WValCabFcpIcm = Round(IsNull(cb.Vlr_FcpIcm,0),2), 
           @WValCabFcpSbt = Round(IsNull(cb.Vlr_FcpSbt,0),2), 
           @WValCabFcpSbtRet = Round(IsNull(cb.Vlr_FcpSbtRet,0),2)
      From NFECB cb 
           Inner Join ESTAB es on cb.Cod_Estabe = es.Cod_Estabe
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Protocolo = @PNumNota

    Set @WPerParIcmDef = IsNull((Select max(Per_PrvParIcm)
                                   From NFEIT
                                  Where Cod_Estabe = @PCodEstabe
                                    And Protocolo = @PNumNota),0)
    -- 7%  UF Emissao: Sul e SE exceto ES:  ';MG;RJ;SP;PR;SC;RS;'
    --        Destino: N, NE e ES
    if (Charindex(@WValCabUFEmi,';MG;RJ;SP;PR;SC;RS;') > 0) and   -- S, SE, exceto ES
           (Charindex(@WValCabUFDes,';MG;RJ;SP;PR;SC;RS;') = 0)       -- N, NE e ES
      Set @WPerAlqInterestaDef = 7.00
    else
      Set @WPerAlqInterestaDef = 12.00
    
    -- atualiza cBenef NFEIT: UF Emitente
    -- Exige o código de benefício fiscal (cBenef) quando se utiliza um CST de benefício fiscal (20, 30, 40, 41, 50, 51, 60 ou 90).
        -- verifica beneficio por NCM
        -- cBenef em devolução é calculado em PR_CalculaTributosEntradasDevlucao
    Exec PR_CalculaBeneficiosEntrada @PCodEstabe, @PNumNota

    Insert Into #TMP_Itens
      Select it.Cod_Produto, it.Num_SeqIte,
             Num_SeqPdc = Substring(Cast(it.Num_SeqIte as varchar),1,6),
             Cod_EAN = Case 
                         When (IsNull(pr.Cod_Ean, '') = '') and Exists(Select 1 From PREAN pe Where pr.Codigo = pe.Cod_Produt And pe.Tip_Cod = '3') Then
                             (Select top 1 IsNull(pe.Cod_Ean, '') 
                                From PREAN pe 
                               Where pr.Codigo = pe.Cod_Produt 
                                 And pe.Tip_Cod = '3'
                                 And len(pe.Cod_Ean) > 1 
                               Order by len(pe.Cod_Ean) Desc)
                         When (IsNull(pr.Cod_Ean, '') = '') and Exists(Select 1 From PREAN pe  Where pr.Codigo = pe.Cod_Produt And pe.Tip_Cod = '4') Then
                             (Select top 1 IsNull(pe.Cod_Ean, '') 
                                From PREAN pe 
                               Where pr.Codigo = pe.Cod_Produt 
                                 And pe.Tip_Cod = '4'
                                 And len(pe.Cod_Ean) > 1 
                               Order by len(pe.Cod_Ean) Desc)
                         Else IsNull(pr.Cod_Ean,'')
                       End,
             Tip_Sai = '',
             Cod_NCM = ISNULL(it.Cod_NCM,''),
             Cod_GrpPrc = IsNull(pr.Cod_GrpPrc,''),
             it.Cod_Cfo, 
             Tip_Por344 = IsNull(pr.Tip_Por344,''),
             Tip_LisPis = ISNull(it.Tip_LisPis,''),
             Des_Produto = pr.Descricao,
             Obs_Produto = '',
             Und_Com = pr.Unidade_Venda,
             Qtd_Com = IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0),
             Prc_UniCom = IsNull(it.Prc_Unitario,0),
             Vlr_TotBruIte = Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)),2),
--             Vlr_TotIte = Round(IsNull(it.Qtd_Pedido,0)*(IsNull(it.Prc_Unitario,0)*(1-IsNull(it.Per_DescItem,0)/100)),2),
--             Vlr_TotIte = Round(IsNull(it.Vlr_TotItem,0),2),
             Vlr_TotIte = Case
                            When Round(IsNull(it.Vlr_TotItem,0),2) <= Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)),2)
                            Then Round(IsNull(it.Vlr_TotItem,0),2) 
                            Else Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)),2)
                          End,
             Per_Desconto = IsNull(it.Per_DescItem,0),
             Vlr_BasRepIcm = IsNull(it.Vlr_BasRepIcm,0),
             Per_RepIcm = IsNull(it.Per_RepIcm,0),
             Vlr_RepIcm = Round(IsNull(it.Vlr_RepIcm,0),2),
             Tip_Consumidor = @WValCabTipConsumidor,
             Vlr_DscTri = Round(IsNull(it.Vlr_DscTri,0),2),
             Per_DscTri = 0,
             Vlr_DscRat = Round(IsNull(it.Vlr_DescRateado,0),2),
             Vlr_DscBonRat = 0,
             Vlr_DscTotIte = 0,
             Vlr_BasSbtRes = Round(IsNull(it.Vlr_BasSbtRes,0),2),        
             Vlr_SbtRes = Round(IsNull(it.Vlr_SbtRes,0),2), 
             Vlr_BasSbtEmb = 0,
             Vlr_SbtEmb = 0, 
             it.Cod_Lote,
             it.Cod_Lote, 
             IsNull(lt.Dat_Vencim,0),
             IsNull(lt.Dat_Fabric,0),
             IsNull(pr.Validade,0),
             Vlr_Frete = Round(IsNull(it.Vlr_Frete,0),2),
             Vlr_Seguro = Round(IsNull(it.Vlr_Seguro,0),2),
             Vlr_DspRat = Round(IsNull(it.Vlr_DespRateada,0),2),
             Vlr_DspExt = Round(IsNull(it.Vlr_DspExt,0),2),
             Vlr_TotDsp = 0,
             Und_Tri = pr.Unidade_Venda,
             Qtd_Tri = IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0),
             Prc_UniTri = IsNull(it.Prc_Unitario,0),          
             Cod_OriPrd = IsNull(it.Cod_OriMer,'0'),
             Cod_CstIcm = IsNull(it.Ctrl_Tributacao,''),
             Cod_CsosnIcm = IsNull(it.Cod_CSOSN,''),
             Cod_ModBasCalIcm = IsNull(it.Cod_ModBasCalIcm,''),
             Per_RedBasCalIcm = IsNull(it.Per_RedBasCalIcm,0),
             Vlr_BasIcm = Round(IsNull(it.Vlr_BasIcmsTrib,0),2),
             Alq_Icm = IsNull(it.Alq_Icms,0),
             Vlr_Icm = Round(IsNull(it.Vlr_IcmsTrib,0),2),
             Dif_VlrIcm = Round(IsNull(it.Vlr_IcmsTrib,0),2) - IsNull(it.Vlr_IcmsTrib,0),
             Vlr_BasIcmPro = Round(IsNull(it.Vlr_BasIcmsNor,0),2),
             Vlr_IcmPro = Round(IsNull(it.Vlr_IcmsNor,0),2),
             Per_IcmDiferi = IsNull(it.Per_IcmDiferi,0),
             Vlr_IcmDiferi = Round(IsNull(it.Vlr_IcmDiferi,0),2),
             Vlr_DscCalSuframa = Round(IsNull(it.Vlr_DscCalSuframa,0),2),
             Vlr_IcmDesone = IsNull(it.Vlr_IcmsDeson,0), 
             Cod_MtvIcmDesone = IsNull(it.Cod_MtvIcmsDeson,''),
             Vlr_BasIcmSbtRet = 0,
             Vlr_IcmSbtRet = 0,
             Cod_ModBasCalIcmSbt = IsNull(it.Cod_ModBasCalIcmSbt,''),
             Alq_AgrSbt = IsNull(it.Alq_AgrDeb,0), 
             Per_RedBasCalIcmSbt = IsNull(it.Per_RedBasCalIcmSbt,0),
             Vlr_BasIcmSbt = Round(IsNull(it.Vlr_BasSubsTrib,0),2),
             Alq_IcmSbt = Case When IsNull(it.Alq_IcmSbt,0) > 0 then it.Alq_IcmSbt Else IsNull(it.Alq_IcmDeb,0) End,  -- ????
             Vlr_IcmSbt = Round(IsNull(it.Vlr_SubsTrib,0),2),
             CST_Ipi    = Case When IsNull(CST_Ipi,'') = '' then '49' Else CST_Ipi End, -- outras
             Cod_EnqIpi = Case When IsNull(Cod_EnqIpi,'') = '' then '999' Else Cod_EnqIpi End,
             Vlr_BasIpi = IsNull(it.Vlr_BasIpi,0),
             Alq_Ipi = Case 
                         When it.Vlr_TotItem > 0 then (it.Vlr_Ipi * 100 / it.Vlr_TotItem) 
                         Else 0
                       End, 
             Vlr_Ipi = it.Vlr_Ipi, 
             Vlr_BasDevIpi = 0,
             Per_DevIpi = 0,
             Vlr_DevIpi = 0,
             it.CST_Pis, it.Vlr_BasPis, it.Alq_Pis, Vlr_Pis = Round(IsNull(it.Vlr_Pis,0),2), 
             Dif_VlrPis = Round(IsNull(it.Vlr_Pis,0),2)-IsNull(it.Vlr_Pis,0), 
             it.CST_Cofins, it.Vlr_BasCofins, it.Alq_Cofins, Vlr_Cofins = Round(IsNull(it.Vlr_Cofins,0),2),
             Dif_VlrCofins = Round(IsNull(it.Vlr_Cofins,0),2)-IsNull(it.Vlr_Cofins,0),
             Prc_MaxCon = Case
                            When @pm_CodImpPMC = '1' then IsNull(it.Prc_MaxCon,0)*IsNull(it.Fator_Fat,1)
                            Else 0
                          End, 
             Prc_Fabric = IsNull(it.Prc_Fabric,0)*IsNull(it.Fator_Fat,1), 
             Des_Fabric = Substring(fb.Fantasia,1,25),
             Flg_DscItePdv = 0,
             Prc_UniPdv = 0,
             Per_DscPdv = 0,
             Cod_CEST = ISNULL(it.Cod_CEST,''),
             
             Vlr_BasIcmDes = Case 
                               When (@WPerParIcmDef > 0) and (IsNull(it.Vlr_IcmFcpDes,0) > 0)  then Round(IsNull(it.Vlr_BasIcmsNor,0),2) 
                               Else 0
                             End,
             Per_AcrAlqIntFcp = Case
                                  When (ISNULL(it.Per_PrvParIcm,0) > 0) and (IsNull(it.Vlr_IcmFcpDes,0) > 0) then ISNULL(it.Per_AcrAlqIntFcp,0)
                                  Else 0
                                End,
             Alq_IntDes = Case 
                            When (@WPerParIcmDef > 0) then ISNULL(it.Alq_IntIcmDes,0)
                            Else 0
                          End,
             Alq_Interesta = Case
                               When (@WPerParIcmDef > 0) and (it.Cod_OriMer IN ('1', '2', '3', '8')) then 4.0 /* DMD-8037: Regra NA09-20 */
                 When (@WPerParIcmDef > 0) and (ISNULL(it.Alq_Icms,0) > 0) then ISNULL(it.Alq_Icms,0)
                               When (@WPerParIcmDef > 0) and (ISNULL(it.Alq_Icms,0) = 0) then @WPerAlqInterestaDef                 
                               Else 0
                             End,
             Per_PrvParIcm = Case 
                               When (@WPerParIcmDef > 0) and (IsNull(it.Vlr_IcmFcpDes,0) > 0) then @WPerParIcmDef 
                               Else 0 
                             End, 

             Vlr_IcmFcpDes = Round(IsNull(it.Vlr_IcmFcpDes,0),2), 
             Vlr_IcmParDes = Round(IsNull(it.Vlr_IcmParDes,0),2),
             Vlr_IcmParRem = Round(IsNull(it.Vlr_IcmParRem,0),2), 
             Cod_PedCmpCli = @WValCabCodCmpCli,
             Str_VolEmb = '',
             Obs_IteNf = '',
             Reg_MS = IsNull(pr.Reg_MS,''),
             Des_MtvIseRegMS = Substring(IsNull(pr.Des_MtvIseRegMS,''),1,255),

             Alq_FcpIcm = IsNull(it.Alq_FcpIcm,0),
             Vlr_FcpIcm = Round(IsNull(it.Vlr_FcpIcm,0),2),
             Alq_FcpSbt = IsNull(it.Alq_FcpSbt,0),
             Vlr_FcpSbt = Round(IsNull(it.Vlr_FcpSbt,0),2),
             Alq_FcpSbtRet = IsNull(it.Alq_FcpSbtRet,0),
             Vlr_FcpSbtRet = Round(IsNull(it.Vlr_FcpSbtRet,0),2),

             vBCSTRet = IsNull(it.Xml_vBCSTRet,0),
             pST = IsNull(it.Xml_pST,0),
             vICMSSubstituto = IsNull(it.Xml_vICMSSubstituto,0),
             vICMSSTRet = IsNull(it.Xml_vICMSSTRet,0),
             vBCFCPSTRet = IsNull(it.Xml_vBCFCPSTRet,0),
             pFCPSTRet = IsNull(it.Xml_pFCPSTRet,0),
             vFCPSTRet = IsNull(it.Xml_vFCPSTRet,0),

             pRedBCEfet = Case When @WValCabTipConsumidor = 'F' then IsNull(it.Xml_pRedBCEfet,0) Else 0 End,
             vBCEfet    = Case When @WValCabTipConsumidor = 'F' then IsNull(it.Xml_vBCEfet,0)    Else 0 End,
             pICMSEfet  = Case When @WValCabTipConsumidor = 'F' then IsNull(it.Xml_pICMSEfet,0)  Else 0 End,
             vICMSEfet  = Case When @WValCabTipConsumidor = 'F' then IsNull(it.Xml_vICMSEfet,0)  Else 0 End,

             cBenef = IsNull(it.cBenef,'')

      From NFEIT it
           Inner Join NFECB cb on cb.Protocolo = it.Protocolo
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
           Inner Join FABRI fb on fb.Codigo = pr.Cod_Fabricante
           left outer Join (Select Cod_Estabe, Cod_Produt, Cod_Lote,
                            Dat_Vencim = MIN(Dat_Vencim), Dat_Fabric = MIN(Dat_Fabric) 
                            From PRLOT 
                            Where Cod_Estabe = @PCodEstabe
                            Group by Cod_Estabe, Cod_Produt, Cod_Lote) lt on ((it.Cod_Estabe = lt.Cod_Estabe) and (it.Cod_Produto = lt.Cod_Produt) and (it.Cod_Lote = lt.Cod_Lote))
           
      Where it.Cod_Estabe = @PCodEstabe
      And it.Protocolo = @PNumNota
      Order by it.Cod_Produto
  end  
  
--normaliza lote ------------------------------------------------------------------------------------------------
DECLARE ITENS_Cr Cursor Local Fast_Forward For
  Select Chave, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_MesValid
  From #TMP_Itens
  Where ((Dat_Vencim < 10) or (Dat_Fabric < 10))
        
OPEN ITENS_Cr
FETCH NEXT FROM ITENS_Cr INTO @Chave, @CodLot, @DatVct, @DatFab, @QtdMesVld 
WHILE @@FETCH_STATUS = 0
BEGIN
  if @DatVct < 10
    begin
      Set @CodLot = ''
      Set @DatVct = null
      Set @DatFab = null 
    end      
  else  
  if @DatFab < 10
    begin
      if @QtdMesVld <= 0
        Set @QtdMesVld = 24
      if @QtdMesVld > 1000
        Set @QtdMesVld = 60   
      Set @DatFab = DATEADD(mm,-@QtdMesVld,@DatVct)
          if @DatFab > @WDatEmiCab
        Set @DatFab = @WDatEmiCab
    end  

  Update #TMP_Itens
    Set Cod_Lote = @CodLot,
        Dat_Vencim = @DatVct,
        Dat_Fabric = @DatFab  
  Where Chave = @Chave

  FETCH NEXT FROM ITENS_Cr INTO @Chave, @CodLot, @DatVct, @DatFab, @QtdMesVld
END

CLOSE ITENS_Cr
DEALLOCATE ITENS_Cr  

-- Normaliza desconto Comercial ----------------------------------------------------------------------------------------------
Set @WValDif = Round(@WValCabDscCom - (Select SUM(Vlr_DscRat) From #TMP_Itens),2) 
if @WValDif < 0
  Set @ParDif = -0.01  
else  
  Set @ParDif = 0.01  
  
while (@WValDif <> 0) and (Abs(@WValDif) < @WValCabDscCom)
  begin
    if @ParDif > 0
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_DscRat > 0
        Order by Vlr_TotIte desc, Chave
    else
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_DscRat > 0
        Order by Vlr_TotIte desc, Chave 
        
    OPEN ITENS_Cr
    FETCH NEXT FROM ITENS_Cr INTO @Chave 
    WHILE @@FETCH_STATUS = 0
    BEGIN
      if @WValDif <> 0
         begin
           Update #TMP_Itens
             Set Vlr_DscRat = Vlr_DscRat + @ParDif   
           Where Chave = @Chave
           And Vlr_DscRat > 0
                      
           Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
    END

    CLOSE ITENS_Cr
    DEALLOCATE ITENS_Cr     
          
  end  -- while @WValDif <> 0
------------------------------------------------------------------------------------------------------------------------

