-- normaliza ICMS ----------------------------------------------------------------------------------------
Set @WValDif = Round(@WValCabBasIcm - (Select SUM(Vlr_BasIcm) From #TMP_Itens),2) 
if @WValDif < 0
  Set @ParDif = -0.01  
else  
  Set @ParDif = 0.01  

while (@WValDif <> 0) and (Abs(@WValDif) < @WValCabBasIcm)
  begin
