    BEGIN
      if @WValDif <> 0
         begin
           Update #TMP_Itens
             Set Vlr_BasIcm = Vlr_BasIcm + @ParDif   
           Where Chave = @Chave
           And Vlr_BasIcm > 0 
           
           Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
    END

    CLOSE ITENS_Cr
