Set @WValDif = Round(@WValCabIcm - (Select SUM(Vlr_Icm) From #TMP_Itens),2) 
if @WValDif < 0
  Set @ParDif = -0.01  
else  
  Set @ParDif = 0.01  
Set @WValLimDif = 0.005  
  
while (@WValDif <> 0) and (Abs(@WValDif) < @WValCabIcm)
  begin
    DECLARE ITENS_Cr Cursor Local Fast_Forward For
      Select Chave
      From #TMP_Itens
      Where Vlr_BasIcm > 0
      Order by Vlr_TotIte desc, Chave 
        
    OPEN ITENS_Cr
    FETCH NEXT FROM ITENS_Cr INTO @Chave 
    WHILE @@FETCH_STATUS = 0
    BEGIN
      if @WValDif <> 0
         begin
           Update #TMP_Itens
             Set Vlr_Icm = Vlr_Icm + @ParDif   
           Where Chave = @Chave
           And Vlr_Icm > 0 
           And Abs(Dif_VlrIcm) < @WValLimDif  
           
           if @@ROWCOUNT > 0
             Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
    END

    CLOSE ITENS_Cr
    DEALLOCATE ITENS_Cr     

    Set @WValLimDif = @WValLimDif + 0.005  
          
  end  -- while @WValDif <> 0


--  Base de calculo x aliquota icms
Update #TMP_Itens
  Set Vlr_Icm = Round(Vlr_BasIcm*Alq_Icm/100,2)
Where Round(Vlr_BasIcm*Alq_Icm/100,2) <> Vlr_Icm
And ((Vlr_IcmDiferi = 0) or ((Vlr_IcmDiferi > 0) and (Vlr_DscCalSuframa > 0)))

Update #TMP_Itens
  Set Vlr_Icm = Round((Vlr_BasIcm*Alq_Icm/100)-Vlr_IcmDiferi,2)
Where Round(Vlr_BasIcm*Alq_Icm/100,2)-Vlr_IcmDiferi <> Vlr_Icm
And Vlr_IcmDiferi > 0
And Vlr_DscCalSuframa = 0


-- ----- Normaliza ICMS: B.Calculo x Aliquota = Vlr_Icms  -----------------------------------------------------------
if Round(@WValCabIcm,2) <> Round( (Select SUM(Vlr_Icm) From #TMP_Itens),2) 
  begin
    Set @WValDif = Round(@WValCabIcm - (Select SUM(Vlr_Icm) From #TMP_Itens),2) 
    if ABS(@WValDif) > 0 
      begin
        -- atualiza valor na tabela de origem (alterando valor original ????)
        Set @WValCabIcm = Round((Select sum(Vlr_Icm) From #TMP_Itens),2)
        if @PTipNota = 'S'
          begin
            Update NFSCB
              Set Vlr_IcmsTri = @WValCabIcm
            Where Cod_Estabe = @PCodEstabe 
            and Ser_Nota = @PSerNota 
            and Num_Nota = @PNumNota
          end
        else
          begin
            Update NFECB
              Set Vlr_IcmsTri = @WValCabIcm
            From NFECB 
            Where Cod_Estabe = @PCodEstabe 
            and Protocolo = @PNumNota
          end
      end
  end  


-- ICMS Proprio
Set @WValDif = Round(@WValCabIcmPro - (Select SUM(Vlr_IcmPro) From #TMP_Itens),2) 
if @WValDif < 0
  Set @ParDif = -0.01  
else  
  Set @ParDif = 0.01  
Set @WValLimDif = 0.005  
  
while (@WValDif <> 0) and (Abs(@WValDif) < @WValCabIcmPro)
  begin
    DECLARE ITENS_Cr Cursor Local Fast_Forward For
      Select Chave
      From #TMP_Itens
      Where Vlr_BasIcmPro > 0
      Order by Vlr_TotIte desc, Chave 
        
    OPEN ITENS_Cr
    FETCH NEXT FROM ITENS_Cr INTO @Chave 
    WHILE @@FETCH_STATUS = 0
    BEGIN
      if @WValDif <> 0
         begin
           Update #TMP_Itens
             Set Vlr_IcmPro = Vlr_IcmPro + @ParDif   
           Where Chave = @Chave
           And Vlr_IcmPro > 0 
           
           if @@ROWCOUNT > 0
             Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
    END

    CLOSE ITENS_Cr
    DEALLOCATE ITENS_Cr     

    Set @WValLimDif = @WValLimDif + 0.005  
          
  end  -- while @WValDif <> 0



--  Base de calculo x aliquota icms proprio
Update #TMP_Itens
  Set Vlr_IcmPro = Round(Vlr_BasIcmPro*Alq_Icm/100,2)
Where Round(Vlr_BasIcmPro*Alq_Icm/100,2) <> Vlr_IcmPro

if Round(@WValCabIcmPro,2) <> Round( (Select SUM(Vlr_IcmPro) From #TMP_Itens),2) 
  begin
    -- atualiza valor na tabela de origem (alterando valor original ????)
    Set @WValCabIcmPro = Round((Select sum(Vlr_IcmPro) From #TMP_Itens),2)
    if @PTipNota = 'S'
      begin
        Update NFSCB
          Set Vlr_IcmsNor = @WValCabIcmPro
        Where Cod_Estabe = @PCodEstabe 
        and Ser_Nota = @PSerNota 
        and Num_Nota = @PNumNota
      end
    else
      begin
        Update NFECB
          Set Vlr_IcmsNor = @WValCabIcmPro
        From NFECB 
        Where Cod_Estabe = @PCodEstabe 
        and Protocolo = @PNumNota
      end
  end  

