------- Normaliza FCP: B.Calculo x Aliquota = Vlr_IcmFcp  -----------------------------------------------------------
--  está alterando NFSCB.Vlr_IcmFcpDes ????
if Round(@WValCabIcmFcpDes,2) = Round((Select SUM(Vlr_IcmFcpDes) From #TMP_Itens),2) 
  begin
    Set @WValDif = Round(@WValCabIcmFcpDes - (Select sum(Round(Vlr_BasIcmDes*Per_AcrAlqIntFcp/100,2)) From #TMP_Itens),2) 
    if ABS(@WValDif) > 0 
      begin
        Update #TMP_Itens
          Set Vlr_IcmFcpDes = Round(Vlr_BasIcmDes*Per_AcrAlqIntFcp/100,2)
          Where Round(Vlr_BasIcmDes*Per_AcrAlqIntFcp/100,2) <> Vlr_IcmFcpDes
          
        -- atualiza valor na tabela de origem (alterando valor original ????)
        Set @WValCabIcmFcpDes = Round((Select sum(Vlr_IcmFcpDes) From #TMP_Itens),2)
        if @PTipNota = 'S'
          begin
            Update NFSCB
              Set Vlr_IcmFcpDes = @WValCabIcmFcpDes
            Where Cod_Estabe = @PCodEstabe 
            and Ser_Nota = @PSerNota 
            and Num_Nota = @PNumNota
          end
        else
          begin
            Update NFECB
              Set Vlr_IcmFcpDes = @WValCabIcmFcpDes
            From NFECB 
            Where Cod_Estabe = @PCodEstabe 
            and Protocolo = @PNumNota
          end
      end
  end  

---------------------------------------------------------------------------------------------------------------

-- normaliza EAN (a partir da versão 4.0)
Update #TMP_Itens
  Set Cod_EAN = 'SEM GTIN'
Where IsNull(Cod_EAN,'') = ''
And Cast(Substring(@pm_VerNfe,1,CharIndex('.',@pm_VerNfe)-1) as int) > 3

------------------------------------------------------------------------------------------------------------------
-- recalcula campos
Update #TMP_Itens
  Set Vlr_DscTotIte = Vlr_TotBruIte - Vlr_TotIte + Vlr_DscRat + Vlr_DscBonRat + Vlr_DscTri, -- desc. sem repasse
      Vlr_TotDsp = Vlr_DspRat + Vlr_DspExt + Vlr_SbtRes,
      Vlr_BasIcmSbtRet = Vlr_BasSbtRes + Vlr_BasSbtEmb,
      Vlr_IcmSbtRet = Vlr_SbtRes + Vlr_SbtEmb
      
-- monta observacao 
DECLARE ITENS_Cr Cursor Local Fast_Forward For
  Select Chave, Cod_Produto, Num_SeqIte, Cod_Lote, Cod_LoteOri, Tip_LisPis, Vlr_TotBruIte, Vlr_DscTotIte,
         Flg_DscItePdv, Prc_UniPdv, Per_DscPdv, Prc_Fabric,
         Vlr_BasSbtRes, Vlr_SbtRes, Vlr_BasSbtEmb, Vlr_SbtEmb, Tip_Consumidor,
         Vlr_DscTri, Per_DscTri, Des_Produto, Des_Fabric, Tip_Por344, Tip_Sai, 
         Str_VolEmb, Obs_IteNf, Vlr_BasRepIcm, Per_RepIcm, Vlr_RepIcm,
         Per_Desconto = Case When (Vlr_DscRat + Vlr_DscBonRat) > 0 then 0 Else Per_Desconto End,
         Vlr_TotIte
  From #TMP_Itens
  Order by Chave 
OPEN ITENS_Cr
FETCH NEXT FROM ITENS_Cr INTO @Chave, @CodPrd, @SeqIte, @CodLot, @WCodLotOri, @WTipLisPis, @WVlrTotBruIte, @WVlrDscTotIte,
                              @WFlgDscItePdv, @WPrcUniPdv, @WPerDscPdv, @WPrcFabric,
                              @WVlrBasSbtRes, @WVlrSbtRes, @WVlrBasSbtEmb, @WVlrSbtEmb, @WTipCon,
                              @WVlrDscTri, @WPerDscTri, @WDesProduto, @WDesFabric, @WTipPor344, @WTipSai, 
                              @WStrVolEmb, @WObsIteNf, @WVlrBasRepIcm, @WPerRepIcm, @WVlrRepIcm, @WPerDscIte, @WVlrTotLiqIte
WHILE @@FETCH_STATUS = 0
  BEGIN
    -- monta observacao cancatenada infAdProd
    Set @WDesCplProduto = ''

    Delete From @Tab

    if @PTipNota = 'S'
      Insert Into @Tab (Obs_Fiscal)
        Select Des_Observ From NSIOB
         Where Cod_Estabe = @PCodEstabe 
           and Ser_Nota = @PSerNota 
           and Num_Nota = @PNumNota
           and Cod_Produto = @CodPrd
           and Cod_Lote = @CodLot
           and Num_SeqIte = @SeqIte
    else
      Insert Into @Tab (Obs_Fiscal)
        Select Des_Observ From NEIOB
         Where Cod_Estabe = @PCodEstabe 
           and Protocolo = @PNumNota
           and Cod_Produto = @CodPrd
           and Cod_Lote = @CodLot
           and Num_SeqIte = @SeqIte

    While Exists(Select 1 From @Tab)
      begin
        Select top 1
               @ChaveTab = ChaveTab
             , @WObsFis = Obs_Fiscal
          From @Tab
         Order by ChaveTab

        if PatIndex(@WObsFis+'%', @WDesCplProduto) = 0
          begin
            if (Len(@WDesCplProduto) > 0) and
               (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
              Set @WDesCplProduto = @WDesCplProduto + ';  '
            Set @WDesCplProduto = @WDesCplProduto + @WObsFis
          end

        Delete From @Tab Where ChaveTab = @ChaveTab
      end


    if (@pm_CodImpDscFab = '1') and (@WDesFabric <> '')
      Set @WDesProduto = @WDesProduto+' ('+Substring(@WDesFabric,1,5)+')'
    if @WTipPor344 <> ''
      Set @WDesProduto = @WDesProduto+' ('+@WTipPor344+')'  
    if @WTipSai = 'B'                     
      Set @WDesProduto = @WDesProduto+' **Bonific.**'

    if (@CodLot = '') and (@WCodLotOri <> '')
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'Lote: '+@WCodLotOri
      end
    
    if (@pm_CodImpPrcFab = '1') and (@WPrcFabric > 0)
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'PF: '+CAST(cast(@WPrcFabric as numeric(12,2)) as varchar)
      end


    Set @WTipLisPis = Case              
                        When @WTipLisPis = 'P' then '(+)'
                        When @WTipLisPis = 'N' then '(-)'
                        When @WTipLisPis = 'X' then '(n)'
                        When @WTipLisPis = 'O' then '(o)'
                      End
    if (Len(@WDesCplProduto) > 0) and
       (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
      Set @WDesCplProduto = @WDesCplProduto + ';  '
    Set @WDesCplProduto = @WDesCplProduto+'Lista '+@WTipLisPis

    -- desconto repasse
    if @WPerRepIcm > 0
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'Repasse '+CAST(cast(@WPerRepIcm as numeric(8,2)) as varchar)+'%'
      end

    -- desconto total (-repasse)
    Set @WPerDsc = 0
    if (@WVlrDscTotIte > 0) and (@WVlrTotBruIte > 0) 
      begin
        if @WPerDscIte > 0 
          Set @WPerDsc = @WPerDscIte
        else
          Set @WPerDsc = Round(@WVlrDscTotIte*100/@WVlrTotBruIte,2)
        if @WPerDsc > 0
          Set @WDesCplProduto = @WDesCplProduto + 'Desc.'+CAST(cast(@WPerDsc as numeric(8,2)) as varchar)+'%  '
      end

    if (@pm_FlgImpDscEmbNot = 1) and (@WFlgDscItePdv = 1) and (@WPerDscPdv > 0) 
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'Desc.Emb.'+CAST(cast(@WPerDscPdv as numeric(8,2)) as varchar)+'%'
      end
    
    if ((@WVlrBasSbtRes+@WVlrBasSbtEmb) > 0) and
       ((@WVlrSbtRes+@WVlrSbtEmb) > 0)
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'BCRE: '+CAST(cast((@WVlrBasSbtRes+@WVlrBasSbtEmb) as numeric(12,2)) as varchar)
        Set @WDesCplProduto = @WDesCplProduto + '  VRE: '+CAST(cast((@WVlrSbtRes+@WVlrSbtEmb) as numeric(12,2)) as varchar)
      end   
  
/*    
    if @WVlrDscTri > 0
      if Charindex(@WTipCon,';P;E;M;') > 0  -- consumidor final
        Set @WDesCplProduto = @WDesCplProduto + 'ICMS abatido no valor de '+CAST(cast(@WVlrDscTri as numeric(12,2)) as varchar)+'  '
          else
      if @WPerDscTri > 0
        Set @WDesCplProduto = @WDesCplProduto + 'Desc.Repasse '+ CAST(cast(@WVlrDscTri as numeric(12,2)) as varchar) +'/'+CAST(@WPerDscTri as varchar)+'%  '
*/

    if @WStrVolEmb <> ''
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + @WStrVolEmb
      end

    if @WObsIteNf <> ''
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + @WObsIteNf
      end
---------------------------------------------------------------------------------------------------

    Update #TMP_Itens
      Set Des_Produto = @WDesProduto,
          Obs_Produto = Substring(@WDesCplProduto,1,500)
    Where Chave = @Chave

  FETCH NEXT FROM ITENS_Cr INTO @Chave, @CodPrd, @SeqIte, @CodLot, @WCodLotOri, @WTipLisPis, @WVlrTotBruIte, @WVlrDscTotIte,
                                @WFlgDscItePdv, @WPrcUniPdv, @WPerDscPdv, @WPrcFabric,
                                @WVlrBasSbtRes, @WVlrSbtRes, @WVlrBasSbtEmb, @WVlrSbtEmb, @WTipCon,
                                @WVlrDscTri, @WPerDscTri, @WDesProduto, @WDesFabric, @WTipPor344, @WTipSai, 
                                @WStrVolEmb, @WObsIteNf, @WVlrBasRepIcm, @WPerRepIcm, @WVlrRepIcm, @WPerDscIte, @WVlrTotLiqIte
END

CLOSE ITENS_Cr
DEALLOCATE ITENS_Cr     
      
----------------------------------------------------------------------------------------------------------

Set @WSelect = 'Select cProd = Cod_Produto, 
       cEAN = Cod_EAN, 
       NCM = Cod_NCM, 
       nItem = Num_SeqIte,
       nItemPed = Num_SeqPdc,
       Cod_GrpPrc = Cod_GrpPrc,
       CFOP = Cod_Cfo, 
       Tip_Por344,
       xProd = Des_Produto,
       cProdANVISA = Reg_MS, 
       xMotivoIsencao = Des_MtvIseRegMS,

       infAdProd = Obs_Produto,
       uCom = Und_Com,
       qCom = Qtd_Com,
       vUnCom = Prc_UniCom,
       vProd = Vlr_TotBruIte,
       vDesc = Vlr_DscTotIte + Vlr_RepIcm,
       Vlr_LiqMer = Vlr_TotIte,
       Vlr_BasSbtRes, Vlr_SbtRes, 
       nLote = Cod_Lote, 
       dVal = Dat_Vencim,
       dFab = Dat_Fabric,
       vFrete = Vlr_Frete,
       vSeg = Vlr_Seguro,
       vOutro = Vlr_TotDsp,
       uTrib = Und_Tri,
       qTrib = Qtd_Tri,
       vUnTrib = Prc_UniTri,

       orig = Cod_OriPrd,
       CST_Icm = Cod_CstIcm,
       CSOSN_Icm = Cod_CsosnIcm,
       modBC = Cod_ModBasCalIcm,
       pRedBC = Per_RedBasCalIcm, 
       vBC = Vlr_BasIcm, 
       pICMS = Alq_Icm - Alq_FcpIcm, 
           
       vICMSOp = Vlr_IcmPro,
       pDif = Per_IcmDiferi,
       vIcmsDif = Case 
                    When Vlr_IcmDiferi > 0 then 
                      Case 
                        When Vlr_IcmDiferi = (Vlr_IcmPro - (Vlr_Icm - Vlr_FcpIcm)) then Vlr_IcmDiferi 
                        Else (Vlr_IcmPro - (Vlr_Icm - Vlr_FcpIcm)) 
                      End
                    Else 0
                  End,
       vICMS = Vlr_Icm - Vlr_FcpIcm, 
       vICMSDeson = Vlr_IcmDesone, 
       motDesICMS = Cod_MtvIcmDesone,

       modBCST = Cod_ModBasCalIcmSbt,
       pMVAST = Alq_AgrSbt, 
       pRedBCST = Per_RedBasCalIcmSbt,
       vBCST = Vlr_BasIcmSbt, 
       pICMSST = Alq_IcmSbt - Alq_FcpSbt, 
       vICMSST = Vlr_IcmSbt - Vlr_FcpSbt,
       
       CST_Ipi, cEnq = Cod_EnqIpi,
       vBCIPI = Vlr_BasIpi+Vlr_BasDevIpi, 
       pIPI = Alq_Ipi, vIPI = Vlr_Ipi,
       pDevol = Per_DevIpi, vIPIDevol = Vlr_DevIpi,

       CST_Pis, Vlr_BasPis, Alq_Pis, Vlr_Pis,
       CST_Cofins, Vlr_BasCofins, Alq_Cofins, Vlr_Cofins, 
       vPMC = Prc_MaxCon, 
       Prc_Fabric,
  
       CEST = Cod_CEST,

       vBCUFDest = Vlr_BasIcmDes,
       vBCFCPUFDest = Vlr_BasIcmDes,
       pFCPUFDest = Per_AcrAlqIntFcp, 
       pICMSUFDest = Alq_IntDes,    
       pICMSInter = Alq_Interesta,
       pICMSInterPart = Per_PrvParIcm,

       vFCPUFDest = Vlr_IcmFcpDes,
       vICMSUFDest = Vlr_IcmParDes,    
       vICMSUFRemet = Vlr_IcmParRem,

       vBCFCP = Vlr_BasIcm,
       pFCP = Alq_FcpIcm,         
       vFCP = Vlr_FcpIcm,         

       vBCFCPST = Vlr_BasIcmSbt,
       pFCPST = Alq_FcpSbt,       
       vFCPST = Vlr_FcpSbt,       

       vBCSTRet, 
       pST,
       vICMSSubstituto,
       vICMSSTRet,

       vBCFCPSTRet,
       pFCPSTRet, 
       vFCPSTRet, 

       pRedBCEfet,
       vBCEfet,
       pICMSEfet,
       vICMSEfet,
           
       cBenef, 
       xPed = Cod_PedCmpCli   
       
From #TMP_Itens '

if @pm_CtrImpIteNotFis = 'A'
  Set @WSelect = @WSelect +'Order by xProd'
else  
  Set @WSelect = @WSelect +'Order by cProd'

Exec (@WSelect)

DROP TABLE #TMP_Itens

RETURN;

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraPedidoVendaPDE]
@PCodEstabe int,
@PCodLayout int,
@PNumCnpj varchar(14),
@PCodPedCli varchar(20),
@PNumDesdob int,
@PNumPdv int = NULL output,     -- se = 0 : cria novo pedido
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

Set @PMsgErr = ''

if not Exists(Select 1 From dbo.PDECB 
              Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli And Num_Desdob = @PNumDesdob)
  Set @PMsgErr ='Pedido Eletrônico não existe'
else
if Exists(Select 1 From dbo.PDECB 
          Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli And Num_Desdob = @PNumDesdob
          And IsNull(Sta_Pedido,'') <> '0')
  Set @PMsgErr ='Pedido Eletrônico inválido (status)'
else
if not Exists(Select 1 From dbo.PDEIT 
              Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli And Num_Desdob = @PNumDesdob)
  Set @PMsgErr ='Pedido Eletrônico inválido (sem itens)'
else
  begin

    if @PNumPdv is null
      Set @PNumPdv = 0

    if not Exists(Select 1
                    From dbo.PDECB
                   Where Cod_Estabe = @PCodEstabe
                     And Cod_Layout = @PCodLayout
                     And Num_Cnpj   = @PNumCnpj
                     And Cod_PedCli = @PCodPedCli
                     And Num_Desdob = @PNumDesdob
                     And IsNull(Num_PedVen,0) > 0)
      begin  
        EXEC PR_ProxNumero 'Pedido_Venda', @PNumPdv output
      end  

    BEGIN TRANSACTION

    Set @PMsgErr = ''

    Declare @WCodDig int,
            @WTipFat varchar(3),
            @WTipPrc varchar(1),
            @WMsgAux varchar(100),
            @WNumSeqIte int,
            @WTipPrz varchar(1),
            @WNomUsuSnhEsp varchar(35),
            @WFlgBlqDscAutIte bit,
            @WFlgBlqAltPrcPol bit,
            @WTipImpPrcPdvCfg varchar(1),
            @WTipImpPrcPdv varchar(1),
            @WFlgTemVdrVnc bit,
            @WFlgUsaVdrPar bit,
            @WFlgSnhEsp bit,          
            @WFlgBlqCriConCom bit,    
            @WFlgBlqCriPrcVen bit,
            @WFlgBlqEstFisNeg bit,
            @WFlgCriVrb bit,
            @WFatCnvCxaFec int,			     
            @WPerDscArq numeric(8,4),
            @WPrcUniArq numeric(18,8),
            @WPerDsc numeric(8,4),
            @WPrcLiqArq numeric(18,8),
            @WDesLayout varchar(25),

            @WFlgBlqWms bit = 0,     -- nunca usa WMS
            @WFlgBlqPol bit = 0,     -- nunca usa politica
            @WFlgUsaWms bit = 0

    Declare @pm_FlgUsaPolComPdv bit = 0,
            @pm_PrzRefPrcVen int,
            @pm_FlgAltUnvItePdv bit,
            @pm_CodVdrPdvCon int,
            @pm_QtdDecPrcItePdv int,

            @pe_NumPedVen int,
            @pe_Layout varchar(20),
            @pe_CodOriPed varchar(1),
            @pe_TipPed varchar(1),
            @pe_CodPedCmpCli varchar(20),
            @pe_CodClient int, 
            @pe_CodVended int, 
            @pe_CodOperad int,
            @pe_IdPolCom int,
            @pe_CodTabPrz int,
            @pe_CodMtvRej varchar(3),
            @pe_CodGrpClp int,
            @pe_FlgFatPedIntegral bit

    -- PARAM
    Select @pm_FlgUsaPolComPdv = IsNull(FlgUsaPolComPdv,0),
           @pm_PrzRefPrcVen = IsNull(PrzRefPrcVen,0),
           @pm_FlgAltUnvItePdv = IsNull(FlgAltUnvItePdv,0),
		   @pm_CodVdrPdvCon = IsNull(CodVdrPdvCon,0),
           @pm_QtdDecPrcItePdv = IsNull(QtdDecPrcItePdv,0)
      From dbo.PARAM
      Where Cod_Estabe = @PCodEstabe

    -- PDECB
    Select @pe_NumPedVen = IsNull(Num_PedVen,0),
           @pe_CodOriPed = IsNull(Cod_OriPed,''),
           @pe_TipPed = IsNull(Tip_Pedido,''),
           @pe_CodPedCmpCli = IsNull(Cod_PedCmpCli,''),
           @pe_CodClient = IsNull(Cod_Client,0), 
           @pe_CodVended = IsNull(Cod_Vended,0), 
           @pe_CodOperad = IsNull(Cod_Operad,0), 
           @pe_IdPolCom = IsNull(Id_PolCom,0),
           @pe_CodTabPrz = IsNull(Cod_TabPrz,0),
		   @pe_CodMtvRej = IsNull(Cod_MtvRej,''),
           @pe_CodGrpClp = IsNull(Cod_GrpClp,0),
           @pe_FlgFatPedIntegral = ISNULL(Flg_FatPedIntegral, 0)
      From dbo.PDECB
     Where Cod_Estabe = @PCodEstabe
       And Cod_Layout = @PCodLayout
       And Num_Cnpj = @PNumCnpj
       And Cod_PedCli = @PCodPedCli
       And Num_Desdob = @PNumDesdob

    Set @WDesLayout = (Select Des_Layout From dbo.TBCLP Where Cod_Layout = @PCodLayout)

    -- TBLPG
    Set @WFlgBlqDscAutIte = 0
    Set @WTipImpPrcPdvCfg = ''
    Set @WFlgTemVdrVnc = 0
    Set @WFlgUsaVdrPar = 0

    if Exists(Select 1 From dbo.TBLPG Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Cod_Grupo = @pe_CodGrpClp)
      begin
        Select @WFlgBlqDscAutIte = IsNull(it.Flg_BlqDscAutIte,0),
               @WTipImpPrcPdvCfg = IsNull(it.Tip_ImpPrcPdv,0),
               @WFlgBlqAltPrcPol = IsNull(Flg_BlqAltPrcPol,0),
               @WFlgTemVdrVnc = Case 
                                  When Exists(Select 1 From dbo.LGXVD Where Cod_Estabe = it.Cod_Estabe and Cod_Layout = it.Cod_Layout and Cod_Grupo = it.Cod_Grupo) then Cast(1 as bit) 
                                  Else Cast(0 as bit) 
                                End,
               @WFlgUsaVdrPar = IsNull(Flg_UsaVdrPar,0)
          From dbo.TBLPG it
         Where it.Cod_Estabe = @PCodEstabe
           And it.Cod_Layout = @PCodLayout
           And it.Cod_Grupo = @pe_CodGrpClp
      end

    Set @WTipImpPrcPdv = @WTipImpPrcPdvCfg
    if @WTipImpPrcPdv = 'A'
      Set @WFlgBlqCriConCom = 1
    else
      Set @WFlgBlqCriConCom = 0

    if IsNull(@pe_NumPedVen,0) > 0
      Set @PNumPdv = @pe_NumPedVen

   if (@PNumPdv = 0) or (not Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv))
      begin
        -- WMS
        Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
		                                          HASHBYTES('MD5',(Select Num_Cnpj From dbo.ESTAB Where Cod_Estabe = @PCodEstabe))))

        if @pe_CodOriPed = '' Set @pe_CodOriPed = 'A'

        -- ajusta flags
        if @WFlgBlqWms = 1         -- nunca usa WMS
          Set @WFlgUsaWms = 0

        if @WFlgBlqPol = 1         -- nunca usa politica
          begin
            Set @pm_FlgUsaPolComPdv = 0
            Set @pe_IdPolCom = 0
          end
        
        Set @WTipFat = 'FAT'
        Set @WCodDig = 0
        Set @WFlgBlqWms = 0
        Set @WFlgBlqPol = 0

        Exec PR_IncluiPDVCB 'P', @PCodEstabe, @PNumPdv output, @pe_CodOriPed, @pe_CodClient, @WFlgUsaWms, @WTipFat,
                            @pe_CodVended, @pe_CodOperad, @WCodDig, @pe_IdPolCom, @pe_CodTabPrz, @PCodLayout,
                            @WFlgBlqWms, @WFlgBlqPol, @PMsgErr output, 0

		Update dbo.PDECB
           Set Cod_MtvRej = 'CAD',
               Des_MtvRej = @PMsgErr
         Where Cod_Estabe = @PCodEstabe
           And Cod_Layout = @PCodLayout
           And Num_Cnpj   = @PNumCnpj
           And Cod_PedCli = @PCodPedCli
           And Num_Desdob = @PNumDesdob
           And @PMsgErr <> ''

        -- procedimento que simula EditCodClienteExit no EdPedVen
		-- já eh executado em PR_IncluiPDVCB
        --Exec PR_InfoDefaultPDVCB @PCodEstabe, @PNumPdv
      end  -- if @PNumPdv = 0

    Update pv
       Set pv.Status2 = 'X',    
           pv.Cod_PedCli = @PCodPedCli, 
           pv.Cod_PedCmpCli = Case 
                                When IsNull(pe.Cod_PedCmpCli,'') <> '' then IsNull(pe.Cod_PedCmpCli,'') 
                                Else @PCodPEdCli 
                              End,
           pv.Cod_PrjPde = IsNull(pe.Cod_Projeto,''),
           pv.Tip_Vencimento = '',
           pv.Observacao = pe.Observacao,     -- ''
           pv.Obs_NotFis = pe.Obs_NotFis,      -- ''
           pv.Qtd_Parcela = IsNull(pe.Qtd_Parcela,0), 
           pv.Qtd_PrzMed  = IsNull(pe.Qtd_PrzMed,0)*1.0,
           pv.Dat_LimEnvPrp = cast(pe.Dat_Encerra as smalldatetime)
      From dbo.PDVCB pv, dbo.PDECB pe
     Where pv.Cod_Estabe = @PCodEstabe
       And pv.Numero = @PNumPdv
       And pv.Status1 = 'P'     -- Pendente
       And ((pv.Status2 = 'A') or (pv.Status2 = 'X'))  -- em aberto    
       And pe.Cod_Estabe = @PCodEstabe
       And pe.Cod_Layout = @PCodLayout
       And pe.Num_Cnpj   = @PNumCnpj
       And pe.Cod_PedCli = @PCodPedCli
       And pe.Num_Desdob = @PNumDesdob

    -- registra num.pedido venda em PDECB (informação necessária ao incluir itens em PDVIT) em 25/08/2022
    Update dbo.PDECB
       Set Num_PedVen = @PNumPdv
     Where Cod_Estabe = @PCodEstabe
       And Cod_Layout = @PCodLayout
       And Num_Cnpj   = @PNumCnpj
       And Cod_PedCli = @PCodPedCli
       And Num_Desdob = @PNumDesdob

    -- inclui itens somente se pedido está "aberto"
    if Exists(Select Numero From dbo.PDVCB 
               Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv 
                 And Status1 = 'P' And ((Status2 = 'A') or (Status2 = 'X')))
      begin

        Declare @op_CfoNorInt int,
                @cl_Codigo int,
                @cl_FlgLicSauInv bit,
                @cl_FlgLicAnvInv bit,
                @pv_CodTipPed varchar(3)  -- 'PDV','COT'

        Select @WTipPrc = op.Tip_Prc,    -- ver tipo de transacao p/ escolher o preco a ser utilizado no pedido
               @op_CfoNorInt = IsNull(op.Cod_CfoNorInt,0),
               @WTipPrz = Substring(cb.Cod_OrigemPdv,2,1),
               @cl_Codigo = IsNull(cl.Codigo,0), 
               @cl_FlgLicSauInv = 0,
               @cl_FlgLicAnvInv = 0,
               @pv_CodTipPed = Case When cb.Tip_Pedido = 'C' then 'COT' Else'PDV' End
          From dbo.PDVCB cb 
               Left Outer Join dbo.TPOPE op on cb.Tip_Faturamento = op.Cod_Ope 
               Left Outer Join dbo.CLIEN cl on cb.Cod_Cliente = cl.Codigo 
         Where cb.Cod_Estabe = @PCodEstabe
           And cb.Numero = @PNumPdv
           And cb.Status1 = 'P'
           And ((cb.Status2 = 'A') or (cb.Status2 = 'X')) 

        -- flg licenças
        Set @cl_FlgLicSauInv = 0
        Set @cl_FlgLicAnvInv = 0
        if @cl_Codigo > 0
          begin
            Exec PR_AnalisaLicencaCliente @pv_CodTipPed, 'SAUDE',  @cl_Codigo, @cl_FlgLicSauInv output, @WMsgAux output
            Exec PR_AnalisaLicencaCliente @pv_CodTipPed, 'ANVISA', @cl_Codigo, @cl_FlgLicAnvInv output, @WMsgAux output
          end
         
        -- estoque fiscal
        Set @WFlgBlqEstFisNeg = 0
        if (IsNull((Select BlqEstFisNeg From dbo.PMEST Where Cod_Estabe = @PCodEstabe),0) = 1) and (@op_CfoNorInt > 0)
          Set @WFlgBlqEstFisNeg = 1

         -- coloca o pedido em processamento
        Update dbo.PDVCB 
           Set Status2 = 'X'
         Where Cod_Estabe = @PCodEstabe
           And Numero = @PNumPdv
           And Status2 <> 'X' 

        -- sequencial do item na PDVIT
        Set @WNumSeqIte = IsNull((Select max(Num_SeqDig) From dbo.PDVIT 
                                   Where Cod_Estabe = @PCodEstabe
                                     And Cod_Pedido = @PNumPdv),0) + 1

        -- inclui itens emm PDVIT
        Declare @WPFlgAchou bit,
                @WPLocFis varchar(15),
                @WPCodFab int,
                @WPFatCnvImpFat int,
                @WPPrcFab numeric(18,8),
                @WPPrcMaxCon numeric(18,8),
                @WPPrcRefFpb numeric(18,8),
                @WPPrcCusMinComMarkup numeric(18,8),
                @WPPrcTab numeric(18,8),
                @WPPrcTabBru numeric(18,8),
                @WPPrcUni numeric(18,8),
                @WPPrcMin numeric(18,8),
                @WPPrcUniLiqPer numeric(18,8),
                @WPFlgEmbDscPrc bit,
                @WPPerDscLin numeric(8,4),
                @WPPerDscPrz numeric(8,4),
                @WPPerDscVis numeric(8,4),
                @WPQtdPrzMax int,

                @WPPerDscPolCom numeric(8,4),
                @WPPerDscVisPolCom numeric(8,4),
                @WPPrcPolCom numeric(18,8),
                @WPQtdPrzPolCom int,
                @WPCodKitPrm int,
                @WPCodPromoc int,
                @WPFlgVerba bit,
                @WPFlgPolPrm bit,
                @WPVlrVrbDis numeric(18,4),

                @WPCodRej varchar(3),
                @WPDesMsg varchar(80),
                @WPCmp varchar(20),
                @WPNomUsuDbq varchar(35),
                @WPDesMsgDbq varchar(60),
                @WPQtdImpFat int, 
                @WPPrcUniImpFat numeric(18,8),
		        @WPCodLot varchar(20),
                @WPPrcUniPde numeric(18,8),
                @WPPerDscPde numeric(8,4),
                @WPCodPrjPde varchar(12),
                @WPNumSeqPdc varchar(6),
                @WPTipSai varchar(1),
                @WPC_PrcUni numeric(18,8),
                @WPC_PerDscIte numeric(8,4),
                @WPPrcUniLiqPdv numeric(18,8),
                --@WPC_VlrDesconto numeric(18,8),
                --@WPC_PrcTotal numeric(18,8),

                @WIte_Chave int = 0,
                @WIte_FlgDscInf bit,
                @WIte_FlgPrcInf bit,
                @WIte_FlgPrzInf bit,
                @WIte_FlgPolInf bit,
                @WIte_FlgBlqQtdPar bit,

				@WIte_CodPrdArq varchar(14),
		        @WIte_CodPrd int,
                @WIte_CodRej varchar(3),
                @WIte_FatCnvImpFat int,
                @WIte_FatAprPad smallint,
                @WIte_QtdPed int,
                @WIte_QtdBon int,
                @WIte_PrcUni numeric(18,4),
                @WIte_IdPolCom int,
                @WIte_PerDsc numeric(18,4),
                @WIte_PrcUniArq numeric(18,8),
                @WIte_PerDscArq numeric(8,4),

                @WIte_QtdPedInf int,
                @WIte_QtdBonInf int,
                @WIte_QtdSolInf int,
                @WIte_QtdAceInf int,
                @WIte_PrcUniInf numeric(18,8),
                @WIte_PerDscInf numeric(8,4),
                @WIte_DesUnvImpFat varchar(3),
				@WIte_DesAprImpFat varchar(12), 
                @WIte_PrcUniImpFat numeric(18,8),
                @WIte_CodProjeto varchar(12),
                @WIte_NumSeqPdc varchar(6),
                @WIte_TipSai varchar(1),
                @WIte_CodTipDsc varchar(1),
                @WIte_CodPrdEmbFec varchar(4), 
                @WIte_QtdEmbFec int,
                @WIte_PerDscEmbPrc numeric(8,4),

                @Wpr_PrcCusLiqEnt numeric(18,4),

                @pvit_CodLot varchar(20),
                @ap_FatCnvApr int,
                @ap_DesUnvApr varchar(3),
                @ap_DesApr varchar(12),

                @pc_FlgNegDsc bit,
                @pc_FlgBlqVerba bit,

				@WQtdPedAte int,
                @WQtdFisDsp int


        Declare @tb_PDEIT table(
          Chave int identity(1,1) primary key,
          Cod_PrdCli varchar(14), 
          Cod_Produt int, 
          Tip_Sai varchar(1), 
          Qtd_Pedido int, 
          Prc_Unitario numeric(18,4),
          Cod_TipDsc varchar(1), 
          Per_Desconto numeric(18,4), 
          Id_PolCom int, 
		  Cod_PrdEmbFec varchar(14),
          Qtd_Embala int,
          Fat_CnvImpFat int, 
          Fat_AprPad smallint,
          Des_UnvImpFat char(3),
          Des_AprImpFat varchar(12),
          Prc_UniImpFat numeric(18,8),
          Cod_Projeto varchar(12),
          Num_SeqPdc varchar(6),
          Per_DscEmbPrc numeric(18,4),
          Flg_PrcInf bit,
          Flg_DscInf bit,
          Flg_PrzInf bit,
          Flg_PolInf bit,
          Flg_BlqQtdPar bit,
          Prc_UnitarArq numeric(18,4),
          Per_DesconArq numeric(8,4)
        )


        -- normaliza campos em PDEIT
        Update dbo.PDEIT
           Set Prc_UnitarArq = Case When IsNull(Flg_PrcInf,0) = 1 Then IsNull(Prc_Unitario,0) Else 0 End, 
               Per_DesconArq = Case When IsNull(Flg_DscInf,0) = 1 Then IsNull(Per_Desconto,0) Else 0 End
         Where Cod_Estabe = @PCodEstabe
           And Cod_Layout = @PCodLayout
           And Num_Cnpj   = @PNumCnpj
           And Cod_PedCli = @PCodPedCli
           And Num_Desdob = @PNumDesdob


        -- seleciona registros candidatos
        Insert Into @tb_PDEIT
          Select Cod_PrdCli, IsNull(Cod_Produt,0), IsNull(Tip_Sai,''), IsNull(Qtd_Pedido,0), IsNull(Prc_Unitario,0), 
                 IsNull(Cod_TipDsc,''), IsNull(Per_Desconto,0), IsNull(Id_PolCom,0), IsNull(Cod_PrdEmbFec,''), IsNull(Qtd_Embala,0),
                 IsNull(Fat_CnvImpFat,0), IsNull(Fat_AprPad,0), IsNull(Des_UnvImpFat,''), IsNull(Des_AprImpFat,''), 
                 IsNull(Prc_UniImpFat,0), IsNull(Cod_Projeto,''), IsNull(Num_SeqPdc,''), IsNull(Per_DscEmbPrc,0),
				 IsNull(Flg_PrcInf,0), IsNull(Flg_DscInf,0), IsNull(Flg_PrzInf,0), IsNull(Flg_PolInf,0), IsNull(Flg_BlqQtdPar,0),
				 IsNull(Prc_UnitarArq,0), IsNull(Per_DesconArq,0)
            From dbo.PDEIT
           Where Cod_Estabe = @PCodEstabe
             And Cod_Layout = @PCodLayout
             And Num_Cnpj   = @PNumCnpj
             And Cod_PedCli = @PCodPedCli
             And Num_Desdob = @PNumDesdob

        While Exists(Select 1 From @tb_PDEIT)
          BEGIN
            Select top 1 @WIte_Chave = t.Chave,
                         @WIte_CodPrdArq = t.Cod_PrdCli, 
                         @WIte_CodPrd = t.Cod_Produt,
                         @WIte_TipSai = t.Tip_Sai,
                         @WIte_QtdPed = t.Qtd_Pedido,
                         @WIte_PrcUni = t.Prc_Unitario,
                         @WIte_CodTipDsc = t.Cod_TipDsc, 
                         @WIte_PerDsc = t.Per_Desconto, 
                         @WIte_IdPolCom = t.Id_PolCom, 
                         @WIte_CodPrdEmbFec = t.Cod_PrdEmbFec, 
                         @WIte_QtdEmbFec = t.Qtd_Embala,
                         @WIte_FatCnvImpFat = t.Fat_CnvImpFat, 
                         @WIte_FatAprPad = t.Fat_AprPad, 
                         @WIte_DesUnvImpFat = t.Des_UnvImpFat, 
                         @WIte_DesAprImpFat = t.Des_AprImpFat, 
                         @WIte_PrcUniImpFat = t.Prc_UniImpFat, 
                         @WIte_CodProjeto = t.Cod_Projeto,
                         @WIte_NumSeqPdc = t.Num_SeqPdc,
                         @WIte_PerDscEmbPrc = t.Per_DscEmbPrc,
                         @WIte_FlgPrcInf = t.Flg_PrcInf, 
                         @WIte_FlgDscInf = t.Flg_DscInf, 
                         @WIte_FlgPrzInf = t.Flg_PrzInf, 
                         @WIte_FlgPolInf = t.Flg_PolInf, 
                         @WIte_FlgBlqQtdPar = t.Flg_BlqQtdPar,
                         @WIte_PrcUniArq = t.Prc_UnitarArq, 
                         @WIte_PerDscArq = t.Per_DesconArq
              From @tb_PDEIT t

            -- Tudofarma: Cod_TipDsc = '1' (industria) -> @WTipImpPrcPdv = 'A'
            if @WIte_CodTipDsc = '1' --desconto da industria
              begin
                Set @WIte_FlgDscInf = 1
                Set @WTipImpPrcPdv = @WTipImpPrcPdvCfg   -- aceita, rejeita ou ignora
              end
            else
            if @WIte_CodTipDsc = '0' --desconto distribuidor
              Set @WTipImpPrcPdv = 'I' 
				              
            Set @WIte_CodRej = ''
            Set @WQtdPedAte  = 0
            Set @WIte_QtdBon = 0
            if @WIte_FatCnvImpFat = 0 
              Set @WIte_FatCnvImpFat = 1
            if @WIte_FatAprPad = 0 
              Set @WIte_FatAprPad = 1

            if @WIte_CodPrd = 0 
              begin
                Set @WIte_CodRej = 'PRX'    -- produto invalido
              end

            -- inclui PDVIT
            if @WIte_CodPrd > 0
              begin

                Select @pvit_CodLot = IsNull(Cod_Lote,'') 
                  From dbo.PDVIT 
                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Pedido = @PNumPdv
                   And Cod_Produto = @WIte_CodPrd
                 Order by Qtd_Pedido desc 

                if not Exists(Select Cod_Lote From dbo.PDVIT 
                               Where Cod_Estabe = @PCodEstabe
                                 And Cod_Pedido = @PNumPdv
                                 And Cod_Produto = @WIte_CodPrd) 
                  begin  

-------------------------  Confirmar se vem tudo calculado em PDEIT --------------------------------------------------------------------------------------------------------------------
                    if @WIte_FatCnvImpFat = 0 
                      Set @WIte_FatCnvImpFat = 1

                    if @WIte_FatAprPad = 0 
                      Set @WIte_FatAprPad = 1

                    if (@pm_FlgAltUnvItePdv = 1) and (@WIte_FatCnvImpFat = 1) and
                       Exists(Select Cod_Apr From dbo.PRXAP 
                               Where Cod_Produt = @WIte_CodPrd 
                                 And IsNull(Flg_Padrao,0) = 1 And IsNull(Fat_CnvApr,0) > 1) 
                      begin
                        Select @ap_DesApr = Des_Apr, 
                               @ap_FatCnvApr = IsNull(Fat_CnvApr,0), 
                               @ap_DesUnvApr = IsNull(Des_UnvApr,'') 
                          From dbo.PRXAP 
                         Where Cod_Produt = @WIte_CodPrd
                           And IsNull(Flg_Padrao,0) = 1 
                           And IsNull(Fat_CnvApr,0) > 1 

-----------------------------------------------------------------------------
                       Set @WIte_FatAprPad    = @ap_FatCnvApr
                       Set @WIte_FatCnvImpFat = @ap_FatCnvApr
                       Set @WIte_DesUnvImpFat = @ap_DesUnvApr
                       Set @WIte_DesAprImpFat = @ap_DesApr
                      end

                    if (@WIte_PrcUniImpFat = 0) and (@WIte_FatCnvImpFat > 1) 
                      Set @WIte_PrcUniImpFat = @WIte_PrcUni * @WIte_FatCnvImpFat

-------------------------------------------------------------------------------------------------------------

                    Set @WIte_QtdPedInf = @WIte_QtdPed*@WIte_FatAprPad
                    Set @WIte_QtdBonInf = @WIte_QtdBon*@WIte_FatAprPad
                    Set @WIte_PrcUniInf = @WIte_PrcUni/@WIte_FatAprPad
                    Set @WIte_PerDscInf = @WIte_PerDsc

--------------------------------------------------------------------------------------------------------------

                    if (@pe_IdPolCom = 0) and (@WIte_IdPolCom > 0)
                      begin
                        Set @pe_IdPolCom = @WIte_IdPolCom
                        --RegravaRegistroPdecb('POL')
                        Update dbo.PDECB
                           Set Id_PolCom = @pe_IdPolCom
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Layout = @PCodLayout
                           And Num_Cnpj = @PNumCnpj
                           And Cod_PedCli = @PCodPedCli
                           And Num_Desdob = @PNumDesdob
                      end

                    if (@WFlgTemVdrVnc = 1) and (@pe_CodVended = 0) 
                      begin
                        -- pega vendedor
                        if (@WIte_CodPrd > 0) and (@pe_CodClient > 0)
                          begin
                            Select @pe_CodVended = lg.Cod_Vended 
                              From dbo.LGXVD lg 
                                   Inner Join dbo.PRODU pr on pr.Codigo = @WIte_CodPrd
                             Where lg.Cod_Estabe = @PCodEstabe
                               And lg.Cod_Layout = @PCodLayOut
                               And lg.Cod_Grupo = @pe_CodGrpClp
                               And lg.Cod_Client = @pe_CodClient 
                               And lg.Cod_Fabric = pr.Cod_Fabricante
                          end
                         
                        if (@pe_CodVended = 0) and (@WFlgUsaVdrPar = 1)
                          Set @pe_CodVended = @pm_CodVdrPdvCon
                         
                        --RegravaRegistroPdecb('VDR')
                        Update dbo.PDECB
                           Set Cod_Vended = @pe_CodVended
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Layout = @PCodLayout
                           And Num_Cnpj = @PNumCnpj
                           And Cod_PedCli = @PCodPedCli
                           And Num_Desdob = @PNumDesdob
                           And @pe_CodVended > 0
                      end

-- @WIte_FatCnvImpFat, : pode ter sido alterado devido apresentação padrão: 
-- @WIte_QtdPedInf, 
-- @WIte_QtdBonInf
-- @WIte_PrcUniInf

                    Exec PR_InfoDefaultPDVIT @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @WIte_CodPrd, 
                                             @WIte_QtdPedInf, @WIte_QtdBonInf, @WIte_IdPolCom output, @WFlgBlqDscAutIte,
                                             @WPFlgAchou output,
                                             @WPLocFis output,
                                             @WPCodFab output,
                                             @WPPrcFab output,
                                             @WPPrcMaxCon output,
                                             @WPPrcRefFpb output,
                                             @WPPrcTab output,
                                             @WPPrcTabBru output,
                                             @WPFatCnvImpFat output,     -- ???? @WIte_FatCnvImpFat
                                             @WPPrcUni output,
                                             @WPPrcCusMinComMarkup output,
                                             @WPPerDscPolCom output,
                                             @WPPerDscVisPolCom output,
                                             @WPPrcPolCom output,
                                             @WPQtdPrzPolCom output,
                                             @WPFlgVerba output,
                                             @WPFlgPolPrm output,
                                             @WPCodKitPrm output,
                                             @WPCodPromoc output,
                                             @WPFlgEmbDscPrc output, 
                                             @WPQtdPrzMax output,
                                             @WPPerDscLin output,
                                             @WPPerDscPrz output,
                                             @WPPerDscVis output,
                                             @WPPrcUniLiqPer output

                    if @WPFlgAchou = 1
                      begin
                        if @pm_FlgUsaPolComPdv = 0
                          begin
                            if @WTipImpPrcPdv <> 'I' 
                              if (@WIte_FlgDscInf = 1) or (@WIte_FlgPrcInf = 1)
                                begin
                                  -- variaveis ref. desc. a ser considerado
                                  Set @WPerDscArq = 0
                                  if (@WIte_FlgDscInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R')) and (IsNull(@WIte_PerDscEmbPrc,0) = 0) 
                                    Set @WPerDscArq = @WIte_PerDsc

                                  Set @WPrcUniArq = @WPPrcUni

                                  if (@WIte_FlgPrcInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R'))
                                    Set @WPrcUniArq = @WIte_PrcUniInf

                                  if Isnull(@WPrcUniArq,0) = IsNull(@WPPrcUni,0)
                                    Set @WPerDsc = @WPerDscArq
                                  else
                                    begin
                                      Set @WPrcLiqArq = Round(@WPrcUniArq*(1-@WPerDscArq/100),@pm_QtdDecPrcItePdv)
                                      if @WPPrcUni > @WPrcLiqArq 
                                         Set @WPerDsc = Round((@WPPrcUni-@WPrcLiqArq)*100/@WPPrcUni,2)
                                      else
                                        Set @WPerDsc = @WIte_PerDscEmbPrc
                                    end

                                  Set @WPPrcUni = @WPrcUniArq
                                  Set @WPPerDscLin = @WPerDsc
                                  Set @WPPerDscPrz = @WPerDsc
                                  Set @WPPerDscVis = @WPerDsc
                                end
                          end  -- if @pm_FlgUsaPolComPdv = 0

                        if @pm_FlgUsaPolComPdv = 1
                          begin
                            Set @pc_FlgNegDsc = 0
                            Set @pc_FlgBlqVerba = 0
                            
                            Select @pc_FlgNegDsc = IsNull(Flg_NegDsc,0), 
                                   @pc_FlgBlqVerba = Case 
                                                       When ((IsNull(Flg_AcuVrbPos,0) = 0) and (IsNull(Flg_AcuVrbNeg,0) = 0)) then 1 
                                                       Else 0 
                                                     End
                              From dbo.POCOM 
                             Where Id_PolCom = @WIte_IdPolCom 

                            --  politica de comercialização (não alterava preço unitario), somente desconto, e, se estiver configurado para permitir negociação
                            if ((@pc_FlgNegDsc = 1) and (@WTipImpPrcPdv <> 'I'))
                              begin
                                if (@WIte_FlgDscInf = 1) or (@WIte_FlgPrcInf = 1) 
                                  begin
                                    -- variaveis ref. desc. a ser considerado
                                    Set @WPerDscArq = 0
                                    if (@WIte_FlgDscInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R')) and (IsNull(@WIte_PerDscEmbPrc,0) = 0) 
                                      Set @WPerDscArq = @WIte_PerDsc
                            
                                    Set @WPrcUniArq = @WPPrcUni
                                    if (@WIte_FlgPrcInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R')) 
                                      Set @WPrcUniArq = @WIte_PrcUniInf
                            
                                    --  verifica se permite alterar preço da politica
                                    if @WFlgBlqAltPrcPol = 0 
                                      begin
                                        Set @WPPrcUni = @WPrcUniArq
                                        Set @WPerDsc  = @WPerDscArq
                                      end
                                    else
                                      begin
                                        if Round(@WPrcUniArq,2) = Round(@WPPrcUni,2) 
                                          Set @WPerDsc = @WPerDscArq
                                        else
                                          begin
                                            Set @WPrcLiqArq = Round(@WPrcUniArq*(1-@WPerDscArq/100),@pm_QtdDecPrcItePdv)
                                            if @WPPrcUni > @WPrcLiqArq 
                                              Set @WPerDsc = Round((@WPPrcUni-@WPrcLiqArq)*100/@WPPrcUni,2)
                                            else
                                              Set @WPerDsc = @WIte_PerDscEmbPrc
                                          end
                                      end
                            
                                    Set @WPPerDscPrz = @WPerDsc
                                    Set @WPPerDscVis = @WPerDsc
                                  end
                              end  -- if ((@pc_FlgNegDsc = 1) and (@WTipImpPrcPdv <> 'I'))
                          end  -- if @pm_FlgUsaPolComPdv = 1

                        Set @WPCodLot = '*'

                        if @WIte_FatCnvImpFat = 0 
                          Set @WIte_FatCnvImpFat = 1
                       
                        -- estoque fiscal negativo
                        if @WFlgBlqEstFisNeg = 1
                          begin
                            Set @WQtdFisDsp = dbo.FN_SldFiscalDisponPrd(@PCodEstabe,@WIte_CodPrd)
                            if @WIte_QtdPedInf > @WQtdFisDsp
                              begin
                                if @WQtdFisDsp < 0 Set @WQtdFisDsp = 0
                                Set @WIte_QtdPedInf = @WQtdFisDsp
                              end
                          end
                       
                        Set @WPPrcUniPde = @WPPrcUni
                        if @WTipPrz = 'L' 
                          Set @WPPerDscPde = @WPPerDscLin  -- Per_Desconto
                        else
                          Set @WPPerDscPde = @WPPerDscPrz  -- Per_Descon

                        Set @WPCodPrjPde = @WIte_CodProjeto
                        Set @WPNumSeqPdc = @WIte_NumSeqPdc
                        Set @WPTipSai = @WIte_TipSai
                     
                        -- calcfields 
                        -- arredonda prc_unitario conforma parametro do sistema
                        Set @WPPrcUni = Round(@WPPrcUni,@pm_QtdDecPrcItePdv)

                        if @WPFatCnvImpFat <> @WIte_FatCnvImpFat
                          Set @WPFatCnvImpFat = @WIte_FatCnvImpFat   -- em 23/08/2020
                        Set @WPQtdImpFat = Round((@WIte_QtdPedInf + @WIte_QtdBonInf)/@WIte_FatCnvImpFat,0)  -- calculado na trigger
                        Set @WPPrcUniImpFat = @WPPrcUni * @WIte_FatCnvImpFat  -- calculado na trigger

                        Set @WPC_PrcUni = @WPPrcUni
                        if @WTipPrz = 'L'
                          Set @WPC_PerDscIte = @WPPerDscLin
                        else
                          Set @WPC_PerDscIte = @WPPerDscPrz
                     
                        --  calcula preco unitario liquido
                        Set @WPPrcUniLiqPdv = @WPPrcUni*(1-@WPC_PerDscIte/100)
                        
                        --Set @WPC_VlrDesconto = 0
                        if @WPFlgEmbDscPrc = 1
                          begin
                            if @WTipPrz = 'L'
                              Set @WPC_PrcUni = @WPPrcUni*(1-@WPPerDscLin/100)
                            else
                              Set @WPC_PrcUni = @WPPrcUni*(1-@WPPerDscPrz/100)
                        
                            Set @WPC_PerDscIte = 0
                          end
                        
                        --Set @WPC_VlrDesconto = Round(@WIte_QtdPedInf*@WPC_PrcUni,2) - Round(@WIte_QtdPedInf*@WPC_PrcUni*(1-@WPC_PerDscIte/100),2)  -- calculado na trigger
                        --Set @WPC_PrcTotal = Round(@WIte_QtdPedInf*@WPC_PrcUni,2) - @WPC_VlrDesconto   -- trigger
                        
                        Set @WFlgSnhEsp = 0 
                        Set @WNomUsuSnhEsp = ''
                        Set @WFlgCriVrb = 0        -- coloquei

                       -- preço mínimo
                        Set @WPPrcMin = 0   -- calcula na critica
                        Set @WPVlrVrbDis = 0 -- calcula na critica

						-- tem que informar atual: @WPPrcPolCom, @WPQtdPrzPolCom, @WPPerDscPolCom, @WPPerDscVisPolCom  (InfoDefault)

                        --  normaliza campos: @WTipImpPrcPdv = (A)ceita, (R)ejeita, (I)gnora 
                        if @WTipImpPrcPdv = 'A'
                          Set @WFlgBlqCriConCom = 1
                        else
                          Set @WFlgBlqCriConCom = 0

                        if ((@WIte_FlgPrcInf = 1) or (@WIte_FlgDscInf = 1)) and 
                           (@WTipImpPrcPdv = 'A') 
                          Set @WFlgBlqCriPrcVen = 1 
                        else
                          Set @WFlgBlqCriPrcVen = 0

                        Exec PR_CriticaItemPDVIT @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @WIte_CodPrd, @WPTipSai,
                                                 @WIte_IdPolCom, @WIte_QtdPedInf output, @WIte_QtdBonInf, @WPQtdPrzMax output,
                                                 @WPPrcUni, @WPPerDscLin output, @WPPerDscPrz output, @WPPerDscVis output, 
                                                 @WPFatCnvImpFat, @WPQtdImpFat output, @WPPrcUniImpFat,
                                                 @WPPrcTabBru, @WPPrcTab output, @WPPrcUniLiqPer output, @WPPrcMin,
                                                 @WPCodKitPrm, @WPPrcCusMinComMarkup, 
                                                 @WPPrcPolCom output, @WPQtdPrzPolCom output, @WPPerDscPolCom output, @WPPerDscVisPolCom output, 
                                                 @WPFlgVerba output, @WPVlrVrbDis, @WFlgSnhEsp, @WNomUsuSnhEsp,
                                                 @WIte_FlgBlqQtdPar, @WFlgBlqCriConCom, @WFlgBlqCriPrcVen, @WFlgCriVrb, @WFlgBlqDscAutIte,
                                                 @WIte_QtdSolInf output, @WIte_QtdAceInf output, @WPFlgPolPrm output, @WPCodPromoc output, 
                                                 @WPCodRej output, @WPDesMsg output, @WPCmp output, @WPNomUsuDbq output, @WPDesMsgDbq  output

                    --Set @WIte_QtdPedInf = @WIte_QtdPed*@WIte_FatAprPad
                    --Set @WIte_QtdBonInf = @WIte_QtdBon*@WIte_FatAprPad
                    --Set @WIte_PrcUniInf = @WIte_PrcUni/@WIte_FatAprPad
---------------------------------------------------------------------------------------------------

                        if (@WPDesMsg = '') or (Substring(@WPCodRej,1,2) = 'PZ')  
                          begin
                            Set @WPCodRej = ''
                            Set @WPDesMsg = ''
                          end
                        else
                          begin
                            Set @WIte_QtdPedInf = 0
                            Set @WIte_QtdBonInf = 0
                          end

                        Insert Into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai)
                          Values (@PCodEstabe, @PNumPdv, @WIte_CodPrd, @WPCodLot, @WPTipSai)

                        Update PDVIT
                           Set Num_SeqDig = @WNumSeqIte,
                               Qtd_Pedido = @WIte_QtdPedInf, 
                               Qtd_Bonificacao = @WIte_QtdBonInf, 
							   Id_PolCom = @WIte_IdPolCom, 
							   Loc_Fisica = @WPLocFis,   
							   Cod_Fabricante = @WPCodFab,
                               Qtd_PrzMax = @WPQtdPrzMax, 
							   Prc_Fabric = @WPPrcFab, 
							   Prc_MaxCon = @WPPrcMaxCon, 
							   Prc_RefFpb = @WPPrcRefFpb,   
							   Prc_Tabela = @WPPrcTab, 
							   Prc_TabBru = @WPPrcTabBru, 
                               Prc_Unitario = @WPPrcUni, 
							   Per_Desconto = @WPPerDscLin, 
							   Per_Descon = @WPPerDscPrz,   
							   Per_DscVis = @WPPerDscVis,  
							   Flg_Verba = @WPFlgVerba,  
							   Prc_CusMinComMarkup = @WPPrcCusMinComMarkup, 
                               Qtd_PrzPolCom = @WPQtdPrzPolCom, 
							   Prc_PolCom = @WPPrcPolCom, 
							   Per_DscPolCom = @WPPerDscPolCom, 
							   Per_DscVisPolCom = @WPPerDscVisPolCom,  
							   Cod_KitPrm = @WPCodKitPrm,    
							   Cod_Promocao = @WPCodPromoc,
                               Fat_CnvImpFat = @WIte_FatCnvImpFat, 
							   Qtd_ImpFat = @WPQtdImpFat,          -- calculado na trigger
							   Prc_UniImpFat = @WPPrcUniImpFat,    -- calculado na trigger
							   Des_UnvImpFat = @WIte_DesUnvImpFat, 
							   Des_AprImpFat = @WIte_DesAprImpFat, 
                               Prc_UniPde = @WPPrcUniPde, 
							   Per_DscPde = @WPPerDscPde, 
							   Cod_PrjPde = @WPCodPrjPde, 
							   Num_SeqPdc = @WPNumSeqPdc, 
                               Flg_PrcUniDsc = @WPFlgEmbDscPrc, 
							   C_PrcUni = @WPC_PrcUni, 
							   C_PerDscIte = @WPC_PerDscIte, 
							   --C_VlrDesconto = @WPC_VlrDesconto, -- calculado na trigger
                               --C_PrcTotal = @WPC_PrcTotal,     -- calculado na trigger
							   Prc_UniLiqPer = @WPPrcUniLiqPer, 
							   Qtd_Solicitado = @WIte_QtdSolInf, 
							   Qtd_Acerto = @WIte_QtdAceInf,
                               Flg_PolPrm = @WPFlgPolPrm, 
							   Cod_MtvRej = @WPCodRej, 
							   Des_MtvRej = Substring(@WPDesMsg,1,80), 
							   Nom_UsuDesbloq = Substring(@WPNomUsuDbq,1,15), 
							   Des_MsgDesbloq = Substring(@WPDesMsgDbq,1,60)
                         Where Cod_Estabe  = @PCodEstabe
                           And Cod_Pedido  = @PNumPdv 
                           And Cod_Produto = @WIte_CodPrd 
                           And Cod_Lote    = @WPCodLot 
                           And Tip_Sai     = @WPTipSai

                        Set @WNumSeqIte = @WNumSeqIte + 1
   
                        --  abate quantidade atendida
                        Update it 
                           Set it.Qtd_Pedido = Round(it.Qtd_Pedido*(1-IsNull(lg.Per_AbatimQtd,0)/100),0) 
                          From dbo.PDVIT it 
                               Inner Join dbo.PDVCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Pedido = cb.Numero 
                               Inner JOIN dbo.LGXGC lg on lg.Cod_Estabe = cb.Cod_Estabe and lg.Cod_Layout = @PCodLayout And
                                                          lg.Cod_Grupo = @pe_CodGrpClp and lg.Cod_GrpCli = cb.Cod_GrpCli 
                         Where cb.Cod_Estabe  = @PCodEstabe
                           And cb.Numero      = @PNumPdv
                           And it.Cod_Produto = @WIte_CodPrd 
                           And it.Cod_Lote    = @WPCodLot
                           And it.Tip_Sai     = @WPTipSai
                           And IsNull(lg.Per_AbatimQtd,0) > 0 
                           And it.Qtd_Pedido >= IsNull(lg.Qtd_AbatimMin,0) 

                        --  atualiza motivo qdo for o caso
                        Update it 
                           Set it.Cod_MtvRej = Case 
                                                 When it.Qtd_Pedido > 0 then 'ES-' 
                                                 Else 'ES0'
                                               End 
                          From dbo.PDVIT it 
                         Where it.Cod_Estabe = @PCodEstabe
                           And it.Cod_Pedido = @PNumPdv
                           And it.Cod_Produto = @WIte_CodPrd 
                           And it.Cod_Lote = @WPCodLot
                           And it.Tip_Sai = @WPTipSai
                           And it.Qtd_Pedido < it.Qtd_Solicitado 
                           And IsNull(it.Cod_MtvRej,'') = '' 
                      end  -- if @WPFlgAchou = 1
                    else
                      begin
                        Set @WIte_CodRej = 'PRX'    --  produto invalido
                      end

                  end  

                else
                  begin
                    -- acumula em PDVIT
                    Update dbo.PDVIT 
                       Set Qtd_Pedido = Qtd_Pedido + @WIte_QtdPedInf
                     Where Cod_Estabe = @PCodEstabe
                       And Cod_Pedido = @PNumPdv
                       And Cod_Produto = @WIte_CodPrd
                       And Cod_Lote = @pvit_CodLot
                  end

                -- registra falta e motivo de rejeicao
                Set @WFatCnvCxaFec = 1
                if (@WIte_CodPrdEmbFec <> '') and (@WIte_QtdEmbFec > 0) 
                  Set @WFatCnvCxaFec = @WIte_QtdEmbFec

                Exec PR_VerificaFaltasPdv false, @PCodEstabe, @PNumPdv, @WIte_CodPrd, @WFatCnvCxaFec, @WTipPrz,
                                          @WQtdPedAte output, @WIte_PrcUniInf output, @WIte_PerDscInf output, @WIte_CodRej output

              end  --if @WIte_CodPrd > 0
            else
              begin
                Set @WQtdPedAte = 0
              end

            -- aquix WQtdPedAte converter WIte_PrcUni
            if @WIte_PrcUni = 0
              Set @WIte_PrcUni = Round((@WIte_PrcUniInf*@WIte_FatAprPad),@pm_QtdDecPrcItePdv)

            if (@WIte_PrcUniImpFat = 0) and (@WIte_FatCnvImpFat > 1) 
              Set @WIte_PrcUniImpFat = Round((@WIte_PrcUniInf*@WIte_FatAprPad),@pm_QtdDecPrcItePdv) * @WIte_FatCnvImpFat

            Set @WQtdPedAte = @WQtdPedAte/@WIte_FatAprPad

            -- Atualizar PDEIT.Fat_AprPad : @WIte_FatAprPad
            Update dbo.PDEIT
               Set Fat_CnvImpFat = @WIte_FatCnvImpFat,
                   Fat_AprPad    = @WIte_FatAprPad,
                   Des_UnvImpFat = @WIte_DesUnvImpFat,
                   Des_AprImpFat = @WIte_DesAprImpFat,
                   Prc_UniImpFat = @WIte_PrcUniImpFat
             Where Cod_Estabe = @PCodEstabe
               And Cod_Layout = @PCodLayout
               And Num_Cnpj   = @PNumCnpj
               And Cod_PedCli = @PCodPedCli
               And Num_Desdob = @PNumDesdob
               And Cod_PrdCli = @WIte_CodPrdArq

            Delete 
              From @tb_PDEIT 
             Where Chave = @WIte_Chave
          end

      end  

------------------------------------------------------------------------------------------------------------------------------------------------------

    -- Finaliza
    Update dbo.PDVCB 
       Set Status2 = 'A',
           Cod_LayoutPde = @PCodLayout,
           Des_LayoutPde = @WDesLayout
     Where Cod_Estabe = @PCodEstabe
       And Numero = @PNumPdv
       And Status2 = 'X'

    Update dbo.PDECB
       Set Sta_Pedido = '1', 
           Num_PedVen = @PNumPdv,
           Msg_Erro = Substring(@PMsgErr,1,400)
    Where Cod_Estabe = @PCodEstabe
      And Cod_Layout = @PCodLayout
      And Num_Cnpj   = @PNumCnpj
      And Cod_PedCli = @PCodPedCli
      And Num_Desdob = @PNumDesdob
      And Sta_Pedido = '0'

    Update dbo.PDEIT
       Set Cod_MtvRej    = 'PRX',
           Cod_MtvRejOri = 'PRX'
     Where Cod_Estabe = @PCodEstabe
       And Cod_Layout = @PCodLayout
       And Num_Cnpj   = @PNumCnpj
       And Cod_PedCli = @PCodPedCli
       And Num_Desdob = @PNumDesdob
       And Cod_Produt = 0

    Update it
       Set it.Cod_MtvRej    = ipv.CodMtvRej, 
	       it.Cod_MtvRejOri = ipv.CodMtvRej, 
	       --it.Des_MtvRej, 
		   it.Qtd_Atendi    = ipv.QtdPdv,
		   it.Prc_Unitario  = ipv.PrcUnitar,
		   it.Per_Desconto  = ipv.PerDescon,
		   it.Fat_CnvImpFat = ipv.FatCnvImp,
		   it.Des_UnvImpFat = ipv.DesUnvImp,
		   it.Des_AprImpFat = ipv.DesAprImp,
		   it.Prc_UniImpFat = ipv.PrcUniImp
      From dbo.PDECB cb
           Inner Join dbo.PDEIT it on cb.Cod_Estabe = it.Cod_Estabe and 
	                                  cb.Cod_Layout = it.Cod_Layout and
	                                  cb.Num_Cnpj = it.Num_Cnpj and
		                              cb.Cod_PedCli = it.Cod_PedCli and
      				                  cb.Num_Desdob = it.Num_Desdob
           Inner Join (Select Cod_Estabe, Cod_Pedido, Cod_Produto,
                              QtdPdv = sum(Qtd_Pedido+Qtd_Bonificacao),
                              CodMtvRej = max(IsNull(Cod_MtvRej,'')),
                              PrcUnitar = max(Prc_Unitario),
                              PerDescon = max(Per_Desconto),
                              FatCnvImp = max(Fat_CnvImpFat),
                              DesUnvImp = max(Des_UnvImpFat),
                              DesAPrImp = max(Des_AprImpFat),
                              PrcUniImp = max(Prc_UniImpFat)
                         From dbo.PDVIT
                        Where Cod_Estabe = @PCodEstabe
                          And Cod_Pedido = @PNumPdv
                        Group by Cod_Estabe, Cod_Pedido, Cod_Produto) ipv on it.Cod_Estabe = ipv.Cod_Estabe and 
                                                                             cb.Num_PedVen = ipv.Cod_Pedido and 
                                                                             it.Cod_Produt = ipv.Cod_Produto 
     Where cb.Cod_Estabe = @PCodEstabe
       And cb.Cod_Layout = @PCodLayout
       And cb.Num_Cnpj   = @PNumCnpj
       And cb.Cod_PedCli = @PCodPedCli
       And cb.Num_Desdob = @PNumDesdob


    -- PDEIT.Qtd_Atendi deve está alimentado antes do cálculo do total
    declare @VlrTotal numeric(18,8)
	set @VlrTotal = 
			Round((Select Sum(Round(Qtd_Atendi*Prc_Unitario*(1-IsNull(Per_Desconto,0)/100),2)) 
				   From dbo.PDEIT 
				   Where Cod_Estabe = @PCodEstabe 
				     And Cod_Layout = @PCodLayout 
					 And Num_Cnpj = @PNumCnpj 
					 And Cod_PedCli = @PCodPedCli 
					 And Num_Desdob = @PNumDesdob),2)
	set @VlrTotal = ISNULL(@VlrTotal, 0)

    Update dbo.PDECB
       Set Vlr_Total = @VlrTotal
    Where Cod_Estabe = @PCodEstabe
      And Cod_Layout = @PCodLayout
      And Num_Cnpj   = @PNumCnpj
      And Cod_PedCli = @PCodPedCli
      And Num_Desdob = @PNumDesdob
      And ISNULL(Vlr_Total, 0) <> @VlrTotal


    --  verifica se pedido pode ser rejeitado
    Exec PR_RejeitaPDVCB @PCodEstabe, @PNumPdv, @pe_FlgFatPedIntegral, @WPCodRej output, @WPDesMsg output

    if @WPCodRej <> ''
      begin
        if Exists(Select Numero From dbo.PDVCB 
                   Where Cod_Estabe = @PCodEstabe
                     And Numero = @PNumPdv
                     And Status1 = 'P'
                     And ((Status2 = 'A') or (Status2 = 'X')))
          begin
            Delete From dbo.PDVCB 
             Where Cod_Estabe = @PCodEstabe
               And Numero = @PNumPdv
   
            Set @PNumPdv = 0

            -- zera qtds atendidas em PDEIT
            Update dbo.PDEIT 
               Set Qtd_Atendi = 0
             Where Cod_Estabe = @PCodEstabe
               And Cod_Layout = @PCodLayout
               And Num_Cnpj = @PNumCnpj
               And Cod_PedCli = @PCodPedCli
               And Num_Desdob = @PNumDesdob
   
            -- motivos de rejeicao
            if not ((@WDesLayout = 'CLAMED') or
                    (@WDesLayout = 'PDVLINK_TEUTO') or
                    (@WDesLayout = 'PDVLINK_AUGEFARMA') or 
                    (@WDesLayout = 'PDVLINK_INOVA') or 
                    (@WDesLayout = 'PDVLINK_REDEMED') or 
                    (@WDesLayout = 'PDVLINK_NATULAB') or
                    (@WDesLayout = 'WEBLINE') or 
                    (@WDesLayout = 'CALLFARMA') or
                    (@WDesLayout = 'CLOSEUP')) 
              begin
                Update dbo.PDEIT 
                   Set Cod_MtvRej = @WPCodRej,
                       Des_MtvRej = Substring(@WPDesMsg,1,80)
                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Layout = @PCodLayout
                   And Num_Cnpj   = @PNumCnpj
                   And Cod_PedCli = @PCodPedCli
                   And Num_Desdob = @PNumDesdob
                   And IsNull(Cod_MtvRej,'') = ''
              end  -- if not ((@WDesLayout = 'WEBLINE') or

            Update dbo.PDECB 
               Set Vlr_Total = 0,
                   Num_PedVen = 0, 
                   Cod_MtvRej = @WPCodRej, 
                   Des_MtvRej = Substring(@WPDesMsg,1,40)  
             Where Cod_Estabe = @PCodEstabe
               And Cod_Layout = @PCodLayout
               And Num_Cnpj   = @PNumCnpj
               And Cod_PedCli = @PCodPedCli
               And Num_Desdob = @PNumDesdob

          end  -- if Exists(Select Numero From dbo.PDVCB 
      end  -- if @WPCodRej <> ''

    if @@trancount > 0
      COMMIT TRANSACTION
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION dbo.[FN_TipSaiPdv] 
(
  @PCodOpe varchar(3)
)
RETURNS VARCHAR(1)
-- tipo de saida de Pedido de Venda: 'B'= bonificacao, 'V'endas, ..

AS

BEGIN

Declare @WTipSai varchar(1)

Set @WTipSai = IsNull((Select Case
                                When ((IsNull(Cod_CfoNorInt,0) = 5910) or (IsNull(Cod_CfoNorExt,0) = 6910)) then 'B'  -- bonificacao
                                Else Tip_Ope
                              End
                         From TPOPE 
                        Where Cod_Ope = @PCodOpe),'')

-- Retorna o resultado da function
RETURN @WTipSai

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_RetornaPoliticasCliente] 
(
@PCodOri varchar(1),      -- Origem (A-Ativo, P-Receptivo, M-Móvel, T-Eletronico/EDI, W-Internet/WEB, H-Hospitalar, D-por Desdobramento, V-por Val)
@PTipPrz varchar(1),      -- OPCIONAL: Tipo de Prazo: '',  (F-fabricante, L-Linear) 
@PCodEstabe int,          -- OPCIONAL: cod.Estabelecimento: -1
@PCodCli int,
@PCodVdr int,             -- OPCIONAL: cod.vendedor: 0
@PCodOpe int,             -- OPCIONAL: cod.operador: 0 
@PCodPrz int              -- OPCIONAL: cod.prazo: 0 
)

RETURNS @retPoliticas TABLE 
(
    Cod_Estabe int NOT NULL,
    Id_Polcom int NOT NULL,
    Dat_Cadastro smalldatetime NULL,
	Flg_BlqCli bit null,
    Flg_BlqPolDifCabPdv bit null, 
	Flg_BlqPolDifItePdv bit null,
	Prioridade smallint,
	primary key (Cod_Estabe, ID_PolCom, Prioridade)
)

AS

--Retorna todas politicas permitidas para o cliente
BEGIN

Declare @Date smalldatetime

Set @Date = cast(GetDate() as date)

Set @PCodOri = Ltrim(Rtrim(@PCodOri))
Set @PTipPrz = Ltrim(Rtrim(@PTipPrz))

Delete from @retPoliticas

if Exists(Select 1 From PARAM Where Cod_Estabe = @PCodEstabe And IsNull(FlgUsaPolComPdv,0) = 1) or
   Exists(Select 1 From PARAM Where @PCodEstabe < 0 And IsNull(FlgUsaPolComPdv,0) = 1)
  begin
    if @PCodCli > 0 
	  begin
        INSERT @retPoliticas
        Select distinct pe.Cod_Estabe, p.Id_Polcom, p.Dat_Cadastro,
               IsNull(p.Flg_BlqCli,0), IsNull(p.Flg_BlqPolDifCabPdv,0), IsNull(p.Flg_BlqPolDifItePdv,0),
		       2 as Prioridade 
        From POCOM p 
             Inner Join PCXES pe on ((p.Id_PolCom = pe.Id_PolCom) and ( ((@PCodEstabe > -1) and (pe.Cod_Estabe = @PCodEstabe)) or (@PCodEstabe < 0)) ) 

             Left Join CLIEN cl on cl.Codigo = @PCodCli
             Left Join PCXCL pc on ((p.Id_PolCom = pc.Id_PolCom) and (pc.Cod_Client = cl.Codigo)) 
             Left Join PCXGC pg on ((p.Id_PolCom = pg.Id_PolCom) and (pg.Cod_GrpCli = cl.Cod_GrpCli)) 
             Left Join PCXUF pu on ((p.Id_PolCom = pu.Id_PolCom) and (pu.Cod_Uf = cl.Cod_Estado)) 

             Left Join PCXVE pv on ((p.Id_PolCom = pv.Id_PolCom) and (pv.Cod_Vended = @PCodVdr)) 
             Left Join PCXOP po on ((p.Id_PolCom = po.Id_PolCom) and (po.Cod_Vended = @PCodOpe)) 
             Left Join PCXPZ pz on ((p.Id_PolCom = pz.Id_PolCom) and (pz.Cod_TabPrz = @PCodPrz)) 

        Where ((pc.Cod_Client > 0) or (pg.Cod_GrpCli > 0) or (pu.Cod_Uf <> '')) 
        And ((p.Dat_Inicio is Null) or (@Date >= p.Dat_Inicio)) 
        And ((p.Dat_Termino is Null) or (@Date <= p.Dat_Termino)) 
        And IsNull(p.Tip_PolCom,'') <> 'KIT'
        And IsNull(p.Bloqueado,0) = 0 
        And ((p.Flg_BlqCli = 0) or ((p.Flg_BlqCli = 1) and (IsNull(cl.Flg_BlqPrm,0) = 0)))  

		And (((@PCodOri = 'M') and (p.Flg_Cfv = 1)) or
             ((@PCodOri = 'T') and (p.Flg_PedEle = 1)) or
             ((@PCodOri = 'W') and (p.Flg_Web = 1)) or
             ((Charindex(@PCodOri,';M;T;W;') = 0) and (p.Flg_Televendas = 1)))

        And ((@PTipPrz = '') or ((@PTipPrz <> '') and (p.Cod_TipPrz = @PTipPrz)))
        And ((@PCodEstabe < 0) or ((@PCodEstabe > -1) and (pe.Cod_Estabe > -1)))
        And ((@PCodVdr = 0) or ((@PCodVdr > 0) and (pv.Cod_Vended > 0)))
        And ((@PCodOpe = 0) or ((@PCodOpe > 0) and (po.Cod_Vended > 0))) 
        And ((@PCodPrz = 0) or ((@PCodPrz > 0) and (pz.Cod_TabPrz > 0))) 
--        Order by p.Flg_BlqCli, p.Dat_Cadastro desc
        UNION
		-- valida politica do cadastro de clientes
        Select distinct pe.Cod_Estabe, p.Id_Polcom, p.Dat_Cadastro,
               IsNull(p.Flg_BlqCli,0), IsNull(p.Flg_BlqPolDifCabPdv,0), IsNull(p.Flg_BlqPolDifItePdv,0),
               1 as Prioridade  
        From POCOM p 
             Inner Join PCXES pe on ((p.Id_PolCom = pe.Id_PolCom) and ( ((@PCodEstabe > -1) and (pe.Cod_Estabe = @PCodEstabe)) or (@PCodEstabe < 0)) ) 
             Inner Join CLIEN cl on cl.Codigo = @PCodCli and p.Id_PolCom = cl.Id_PolCom
             Left Join PCXCL pc on ((p.Id_PolCom = pc.Id_PolCom) and (pc.Cod_Client = cl.Codigo)) 
             Left Join PCXGC pg on ((p.Id_PolCom = pg.Id_PolCom) and (pg.Cod_GrpCli = cl.Cod_GrpCli)) 
             Left Join PCXUF pu on ((p.Id_PolCom = pu.Id_PolCom) and (pu.Cod_Uf = cl.Cod_Estado)) 
             Left Join PCXVE pv on ((p.Id_PolCom = pv.Id_PolCom) and (pv.Cod_Vended = @PCodVdr)) 
             Left Join PCXOP po on ((p.Id_PolCom = po.Id_PolCom) and (po.Cod_Vended = @PCodOpe)) 
             Left Join PCXPZ pz on ((p.Id_PolCom = pz.Id_PolCom) and (pz.Cod_TabPrz = @PCodPrz)) 
        Where ((pc.Cod_Client > 0) or (pg.Cod_GrpCli > 0) or (pu.Cod_Uf <> '')) 
        And ((p.Dat_Inicio is Null) or (@Date >= p.Dat_Inicio)) 
        And ((p.Dat_Termino is Null) or (@Date <= p.Dat_Termino)) 
        And IsNull(p.Tip_PolCom,'') <> 'KIT'
        And IsNull(p.Bloqueado,0) = 0 
        And ((p.Flg_BlqCli = 0) or ((p.Flg_BlqCli = 1) and (IsNull(cl.Flg_BlqPrm,0) = 0)))  
		And (((@PCodOri = 'M') and (p.Flg_Cfv = 1)) or
              ((@PCodOri = 'T') and (p.Flg_PedEle = 1)) or
              ((@PCodOri = 'W') and (p.Flg_Web = 1)) or
              ((Charindex(@PCodOri,';M;T;W;') = 0) and (p.Flg_Televendas = 1)))
        And ((@PTipPrz = '') or ((@PTipPrz <> '') and (p.Cod_TipPrz = @PTipPrz)))
        And ((@PCodEstabe < 0) or ((@PCodEstabe > -1) and (pe.Cod_Estabe > -1)))
        And ((@PCodVdr = 0) or ((@PCodVdr > 0) and (pv.Cod_Vended > 0)))
        And ((@PCodOpe = 0) or ((@PCodOpe > 0) and (po.Cod_Vended > 0))) 
        And ((@PCodPrz = 0) or ((@PCodPrz > 0) and (pz.Cod_TabPrz > 0))) 
	  end
  end

RETURN

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_SugerePoliticaProduto]
(
 @PCodOri varchar(1),      -- Origem (A-Ativo, P-Receptivo, M-Móvel, T-Eletronico/EDI, W-Internet/WEB, H-Hospitalar, D-por Desdobramento, V-por Val)
 @PCodEstabe int,          -- cod.estabelecimento
 @PCodCli int,             -- codigo cliente
 @PCodVdr int,             -- OPCIONAL: cod.vendedor 
 @PCodOpe int,             -- OPCIONAL: cod.operador 
 @PIdPolComCab int,        -- politica do cabeçalho do pedido
 @PCodPrd int,             -- codigo produto
 @PQtdPed int,             -- OPCIONAL: quantidade produto
 @PCodLayPde int,          -- OPCIONAL: layout pedido eletronico
 @PCodGrpLay int           -- OPCIONAL: grupo do layout pedido eletronico
)
RETURNS int

AS

BEGIN

Declare @Date smalldatetime,
        @IdPolCom int

Set @Date = cast(GetDate() as Date)

Set @IdPolCom = 0
Set @PCodOri = Ltrim(Rtrim(@PCodOri))

Set @IdPolCom = IsNull((Select top 1 x.Id_PolCom 
                          From dbo.FN_RetornaPoliticasProduto(@PCodOri, @PCodEstabe, @PCodCli, @PCodVdr, @PCodOpe, @PIdPolComCab, 
                                                              @PCodPrd, @Date, @PCodLayPde, @PCodGrpLay) x
                               inner join PARAM pm on x.Cod_Estabe = pm.Cod_Estabe
                         Where ((@PQtdPed = 0) or (@PQtdPed >= x.Qtd_Minimo))
                         Order by Case 
                                    When IsNull(pm.FlgSugPolComIdeal,0) = 1  then x.Per_Descon 
                                    When IsNull(pm.FlgSugPolComMenDsc,0) = 1 then x.Per_Descon 
                                    Else x.Dat_Cadastro
                                  End desc, x.Nivel, x.Ordem),0)

-- Retorna o resultado da function
RETURN IsNull(@IdPolCom,0)

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_SugereEstabePoliticaProduto]
 @PIdPVMCB int,            -- Id da pré-venda já existente 
 @PCodOri varchar(1),      -- Origem (A-Ativo, P-Receptivo, M-Móvel, T-Eletronico/EDI, W-Internet/WEB, H-Hospitalar, D-por Desdobramento, V-por Val)
 @PCodEstabe int output,   -- OPCIONAL: cod.estabelecimento: -1
 @PCodCli int,             -- codigo cliente
 @PCodVdr int,             -- OPCIONAL: cod.vendedor 
 @PCodOpe int,             -- OPCIONAL: cod.operador 
 @PIdPolComCab int,        -- politica do cabeçalho do pedido
 @PCodPrd int,             -- codigo produto
 @PQtdPed int,             -- OPCIONAL: quantidade produto
 @PIdPolCom int output

AS

BEGIN

Declare @Date smalldatetime = cast(GetDate() as Date),
        @CodLayPde int = 0,
        @CodGrpLay int = 0,
		@OrdEstoqu smallint = 0

Set @PCodOri = Ltrim(Rtrim(@PCodOri))

Set @PIdPolCom = 0

if Exists(Select 1
            From dbo.FN_RetornaPoliticasProduto(@PCodOri, @PCodEstabe, @PCodCli, @PCodVdr, @PCodOpe, @PIdPolComCab, 
                                                @PCodPrd, @Date, @CodLayPde, @CodGrpLay) x
                 inner join PARAM pm on x.Cod_Estabe = pm.Cod_Estabe
           Where ((@PQtdPed = 0) or (@PQtdPed >= x.Qtd_Minimo)))
  begin
    Select top 1 @PCodEstabe = x.Cod_Estabe,
                 @PIdPolCom = x.Id_PolCom
      From dbo.FN_RetornaPoliticasProduto(@PCodOri, @PCodEstabe, @PCodCli, @PCodVdr, @PCodOpe, @PIdPolComCab, 
                                          @PCodPrd, @Date, @CodLayPde, @CodGrpLay) x
           Inner join dbo.POCOM pit on x.Id_PolCom = pit.Id_PolCom
           inner join dbo.PARAM pm  on x.Cod_Estabe = pm.Cod_Estabe

           left  join dbo.PDVCB cb on ( (x.Cod_Estabe = cb.Cod_Estabe) and
		                                (cb.Id_Pvmcb = @PIdPVMCB) and 
		                                ((cb.Status1 = 'P') and ((cb.Status2 = 'A') or (cb.Status2 = 'X'))) )
           left  join dbo.POCOM pcb on cb.Id_PolCom = pcb.Id_PolCom

		   inner join PRXES px on x.Cod_Estabe = px.Cod_Estabe and px.Cod_Produt = @PCodPrd
		   inner join ENXES es on x.Cod_Estabe = es.Cod_Estabe and es.Cod_Client = @PCodCli

     Where ((@PQtdPed = 0) or (@PQtdPed >= x.Qtd_Minimo))
     Order by Case 
	            When (px.Qtd_Dispon >= px.Qtd_Quaren) and (px.Qtd_Dispon-px.Qtd_Quaren) > @PQtdPed then 1 
	            When (px.Qtd_Dispon >= px.Qtd_Quaren) and (px.Qtd_Dispon-px.Qtd_Quaren) > 0 then 2 
				Else 3 
              End,
	          Case 
                When (IsNull(cb.Numero,0) > 0) and (IsNull(pcb.Id_PolCom,0) = pit.Id_PolCom) then 1 
				When (IsNull(cb.Numero,0) > 0) and (IsNull(pcb.Flg_BlqPolDifItePdv,0) = 0) and (IsNull(pit.Flg_BlqPolDIfCabPdv,0) = 0) then 1 
                Else 2 
              End,
              Case
                When IsNull(pm.FlgSugPolComIdeal,0) = 1  then x.Per_Descon 
                When IsNull(pm.FlgSugPolComMenDsc,0) = 1 then x.Per_Descon 
				Else x.Per_Descon
              End desc, x.Dat_Cadastro desc, x.Cod_Estabe, x.Nivel, x.Ordem 
  end

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AtualizaPVMCB]
@PIdPVMCB int     -- se = 0, atualiza todos registros em PVMCB
AS

SET NOCOUNT ON

Update cb

   Set cb.C_QtdItens    = IsNull(c.C_QtdItens,0)
     , cb.C_QtdUndIte   = IsNull(i.C_QtdUndIte,0)
     , cb.C_VlrBruto    = IsNull(i.C_VlrBruto,0)
     , cb.C_VlrDscIte   = IsNull(i.C_VlrBruto,0)-IsNull(c.C_VlrLiqItens,0)
     , cb.C_VlrLiqItens = IsNull(c.C_VlrLiqItens,0)
     , cb.C_VlrRepIcm   = IsNull(c.C_VlrRepIcm,0)
     , cb.C_VlrSubTri   = IsNull(c.C_VlrSubTri,0)
     , cb.C_VlrSbtRes   = IsNull(c.C_VlrSbtRes,0)
     , cb.C_VlrDscTri   = IsNull(c.C_VlrDscTri,0)
     , cb.C_VlrImposto  = IsNull(c.C_VlrImposto,0)
     , cb.C_VlrDespes   = IsNull(c.C_VlrDespes,0)
     , cb.C_VlrDesconto = IsNull(c.C_VlrDesconto,0)
     , cb.C_VlrDscBon   = IsNull(c.C_VlrDscBon,0)
     , cb.C_VlrIpi      = IsNull(c.C_VlrIpi,0)
     , cb.C_VlrPedido   = IsNull(c.C_VlrPedido,0)
     , cb.C_PerLuc      = IsNull(c.C_PerLuc,0)

  From dbo.PVMCB cb

       Left Join (Select Id_PVMCB
                       , C_QtdItens    = Sum(IsNull(Qtd_Itens,0))
                       , C_VlrLiqItens = Round(Sum(IsNull(Vlr_LiqItens,0)),2)
                       , C_VlrRepIcm   = Round(Sum(IsNull(Vlr_RepIcms,0)),2)
                       , C_VlrSubTri   = Round(Sum(IsNull(Vlr_SubsTrib,0)),2)
                       , C_VlrSbtRes   = Round(Sum(IsNull(Vlr_SbtRes,0)),2)
                       , C_VlrDscTri   = Round(Sum(IsNull(Vlr_DscTri,0)),2)
                       , C_VlrImposto  = Round(Sum(IsNull(Vlr_SubsTrib,0)+IsNull(Vlr_SbtRes,0)-IsNull(Vlr_DscTri,0)),2)
                       , C_VlrDespes   = Round(Sum(IsNull(Vlr_Despes,0)+IsNull(Vlr_DspExt,0)),2)
                       , C_VlrDesconto = Round(Sum(IsNull(C_VlrDesconto,0)),2)
                       , C_VlrDscBon   = Round(Sum(IsNull(Vlr_DscBon,0)),2)
                       , C_VlrIpi      = Round(Sum(IsNull(Vlr_Ipi,0)),2)
                       , C_VlrPedido   = Round(Sum(IsNull(C_VlrPedido,0)),2)
                       , C_PerLuc      = Case 
                                           When (Select sum(Vlr_LiqItens)) > 0 then (Select Sum(Per_Rnt*Vlr_LiqItens)/sum(Vlr_LiqItens))
                                           Else 0
                                         End
                    From dbo.PDVCB
                   Where IsNull(Id_PVMCB,0) > 0 
                     And ((@PIdPVMCB = 0) or (Id_PVMCB = @PIdPVMCB))
                     And ((Status1 = 'P') and (Status2 <> 'N') and (Status2 <> 'D'))
                   Group by Id_PVMCB) c on cb.Id_PVMCB = c.Id_PVMCB

       Left Join (Select cab.Id_PVMCB
                       , C_QtdUndIte = sum(ite.Qtd_Pedido+ite.Qtd_Bonificacao)
                       , C_VlrBruto = Round(Sum(IsNull(ite.Vlr_Bruto,0)),2)
                    From dbo.PDVIT ite
                         inner join dbo.PDVCB cab on ite.Cod_Estabe = cab.Cod_Estabe and 
                                                     ite.Cod_Pedido = cab.Numero
                   Where IsNull(cab.Id_PVMCB,0) > 0 
                     And ((@PIdPVMCB = 0) or (cab.Id_PVMCB = @PIdPVMCB))
                   Group by cab.Id_PVMCB) i on cb.Id_PVMCB = i.Id_PVMCB

 Where ((@PIdPVMCB = 0) or (cb.Id_PVMCB = @PIdPVMCB))

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AtualizaPVMIT]
@PIdPVMCB int,
@PCodProdut int  -- opcional, se = 0, atualiza todos os produtos

AS

SET NOCOUNT ON

Update pv
   Set pv.Qtd_Atendi = IsNull(ix.S_QtdAtendi,0)
     , pv.C_PrcTotal = IsNull(ix.S_C_PrcTotal,0)
  From dbo.PVMIT pv
       Left Join (Select cb.ID_PVMCB, it.Cod_Produto
                       , S_QtdAtendi  = sum(it.Qtd_Pedido+it.Qtd_Bonificacao)
                       , S_C_PrcTotal = Round(Sum(IsNull(it.C_PrcTotal,0)),2)
                    From dbo.PDVIT it
                         inner join dbo.PDVCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Pedido = cb.Numero
                   Where cb.Id_PVMCB = @PIdPVMCB
                     And ((@PCodProdut = 0) or (it.Cod_Produto = @PCodProdut))
                     And ((cb.Status1 = 'P') and (cb.Status2 <> 'N') and (cb.Status2 <> 'D'))
                     And it.Qtd_Pedido > 0
                   Group by cb.ID_PVMCB, it.Cod_Produto) ix on (pv.ID_PVMCB = ix.ID_PVMCB) and (pv.Cod_Produto = ix.Cod_Produto) 
 Where pv.ID_PVMCB = @PIdPVMCB
   And ((@PCodProdut = 0) or (pv.Cod_Produto = @PCodProdut))

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AtualizaCabecPDV]
@CodEstabe int,
@NumPdv int

AS

SET NOCOUNT ON

Begin Transaction

Declare @cb_VlrBasDsc numeric(18,4),
        @cb_VlrDscCom numeric(18,4),
        @cb_VlrRepDsc numeric(18,4),
        @cb_QtdItePrm int,
        @cb_VlrBasPar numeric(18,4)


-- verifica se necessita ratear despesas...
Exec PR_RateiaDespesasPDV @CodEstabe, @NumPdv
if @@error <> 0
  begin
    if @@trancount > 0
      Rollback Transaction
    Return
  end


-- verifica se necessita ratear descontos...
Set @cb_VlrBasDsc = 0
Set @cb_VlrDscCom = 0
Set @cb_VlrRepDsc = 0
Set @cb_QtdItePrm = 0
Set @cb_VlrBasPar = 0

Set @cb_VlrBasDsc = Isnull(Round((Select Sum(C_PrcTotal)  from PDVIT Where Qtd_Pedido > 0 and Cod_Estabe = @CodEstabe and IsNull(Desconto,0) = 0      and Cod_Pedido = @NumPdv),2),0)
Set @cb_VlrRepDsc = Isnull(Round((Select Sum(Vlr_RepIcms) from PDVIT Where Qtd_Pedido > 0 and Cod_Estabe = @CodEstabe and IsNull(Desconto,0) = 0      and Cod_Pedido = @NumPdv),2),0)
Set @cb_VlrBasPar = Isnull(Round((Select Sum(C_PrcTotal)  from PDVIT Where Qtd_Pedido > 0 and Cod_Estabe = @CodEstabe and IsNull(Flg_BlqInfPar,0) = 0 and Cod_Pedido = @NumPdv),2),0)

Set @cb_QtdItePrm = Isnull((Select Count(*) from PDVIT 
                             Where Qtd_Pedido > 0 and Cod_Estabe = @CodEstabe and Cod_Pedido = @NumPdv
                               And (Qtd_Bonificacao > 0 or Per_Desconto > 0)
                               -- aqui deveia considerer descontos embutidos no preço, etc....
                           ),0)

Update PDVCB
   Set Vlr_BasDscCom = @cb_VlrBasDsc,
       --C_VlrDesconto = Round(IsNull(Per_DescontoCom,0)/100 * (IsNull(@cb_VlrBasDsc,0)-IsNull(@cb_VlrRepDsc,0)),2), calculado na trigger
       Vlr_BasPar    = @cb_VlrBasPar,
       Qtd_ItensProm = @cb_QtdItePrm
 Where Cod_Estabe = @CodEstabe 
   and Numero = @NumPdv

Exec PR_RateiaDescontosPDV @CodEstabe, @NumPDv
if @@error <> 0
  begin
    if @@trancount > 0
      Rollback Transaction
    Return
  end


Update cb
   Set cb.Qtd_Itens     = IsNull(it.S_QtdIte,0)
     , cb.Vlr_LiqItens  = IsNull(it.S_VlrLiqIte,0)
     , cb.C_VlrDesconto = IsNull(it.S_VlrDscRat,0)

     , cb.Vlr_RepIcms   = IsNull(S_VlrRepIcm,0)
     , cb.Vlr_SubsTrib  = IsNull(S_VlrSubTri,0)
     , cb.Vlr_SbtRes    = IsNull(S_VlrSbtRes,0)
     , cb.Vlr_DscTri    = IsNull(S_VlrDscTri,0)
     , cb.Vlr_IcmsDeson = IsNull(S_VlrIcmDes,0)
     , cb.Vlr_DscBon    = IsNull(S_VlrDscBon,0)
     , cb.Vlr_Despes    = IsNull(S_VlrDespes,0)
     , cb.Vlr_DspExt    = IsNull(S_VlrDspExt,0)
     , cb.Vlr_Ipi       = IsNull(S_VlrIpi,0)
     , cb.Vlr_Verba     = IsNull(S_VlrVerba,0)
     , cb.Per_Rnt       = IsNull(S_PerRnt,0)
	 , cb.Vlr_BasIrf    = IsNull(S_VlrBasIrf,0)
	 , cb.Vlr_Irf       = IsNull(S_VlrIrf,0) 
  From PDVCB cb
       Left Join (Select Cod_Estabe, Cod_Pedido
                       , S_QtdIte    = count(*)
                       , S_VlrLiqIte = Round(Sum(IsNull(C_PrcTotal,0)),2)
                       , S_VlrDscRat = Round(Sum(IsNull(Vlr_DscRat,0)),2)

                       , S_VlrRepIcm = Round(Sum(IsNull(Vlr_RepIcms,0)),2)
                       , S_VlrSubTri = Round(Sum(IsNull(Vlr_SubsTrib,0)),2)
                       , S_VlrSbtRes = Round(Sum(IsNull(Vlr_SbtRes,0)),2)
                       , S_VlrDscTri = Round(Sum(IsNull(Vlr_DscTri,0)),2)
                       , S_VlrIcmDes = Round(Sum(IsNull(Vlr_IcmsDeson,0)),2)
                       , S_VlrDscBon = Round(Sum(IsNull(Vlr_Bonificacao,0)),2)
                       , S_VlrDespes = Round(Sum(IsNull(Vlr_Despes,0)),2)
                       , S_VlrDspExt = Round(Sum(IsNull(Vlr_DspExt,0)),2)
                       , S_VlrIpi    = Round(Sum(IsNull(Vlr_Ipi,0)),2)
                       , S_VlrVerba  = Round(Sum(IsNull(Vlr_Verba,0)),2)
                       , S_PerRnt    = Case 
                                         When Exists(Select 1 From PDVIT Where Cod_Estabe = @CodEstabe and Cod_Pedido = @NumPdv and Tip_BasRnt = 'M') -- MarkUp 
                                           then Case 
                                                  When (Select sum(Prc_BasRnt*(Qtd_Pedido+Qtd_Bonificacao))) > 0 
                                                    then (Select ((sum(Vlr_BasTri+Vlr_SbtRes)/sum(Prc_BasRnt*(Qtd_Pedido+Qtd_Bonificacao))-1)*100))
                                                  Else 0
                                                End
                                         When (Select sum(C_PrcTotal)) > 0 then (Select Sum(Per_Rnt*C_PrcTotal)/sum(C_PrcTotal))
                                         Else -100.0
                                        End
					   , S_VlrBasIrf        = Round(Sum(IsNull(Vlr_BasIrf,0)),2)
					   , S_VlrIrf           = Round(Sum(IsNull(Vlr_Irf,0)),2) 
                    From PDVIT
                   Where Cod_Estabe = @CodEstabe 
                     And Cod_Pedido = @NumPdv
                     And Qtd_Pedido > 0
                   Group by Cod_Estabe, Cod_Pedido
                 ) it on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido
 Where cb.Cod_Estabe = @CodEstabe 
   And cb.Numero = @NumPdv

Update PDVCB
   Set C_VlrPedido = dbo.FN_ValPdv(Cod_Estabe,Numero)
 Where Cod_Estabe = @CodEstabe 
   and Numero = @NumPdv

if Exists(Select 1 From PDVCB 
           Where Cod_Estabe = @CodEstabe 
             and Numero = @NumPdv
             and IsNull(Id_PVMCB,0) > 0)
   begin
     Declare @IdPVMCB int
     Set @IdPVMCB = IsNull((Select Id_PVMCB From PDVCB Where Cod_Estabe = @CodEstabe and Numero = @NumPdv),0)
     Exec PR_AtualizaPVMCB @IdPVMCB
   end

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_PDVIT_CalculaTributos] ON [dbo].[PDVIT] 
FOR INSERT, UPDATE, DELETE 
NOT FOR REPLICATION
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 

/*
SET CONTEXT_INFO 0x31415161345234625623046972340597854029752304523067825672039782364082

if (SELECT CONTEXT_INFO()) = 0x31415161345234625623046972340597854029752304523067825672039782364082
  RETURN
*/

Declare @CodEstabe int,
        @CodPed int,
        @IdConsig int = 0,
        @NumSeqCtr int = 0,
        @CodPrd int,
        @CodLot varchar(20),
        @TipSai varchar(1),
        @CodPrm int,
        @CodKitPrm int,
        @QtdPed int,
        @QtdBon int,
        @QtdPra int,
        @QtdDep int,
        @FatCnvImpFat int,
        @TipPed varchar(1),
        @StaPdv1 varchar(1),
        @StaPdv2 varchar(1),
        @TipBlq varchar(2),
        @NumPrtOri int,            -- numero do protocolo de origem se pedido foi gerado por uma NFE
        @CodOriPed varchar(2),
        @FlgCal bit,
        @FlgCalAnt bit,
        @FlgLotEsp bit,    -- lote especifico
        @FlgAltQtd bit,
        @FlgAltPrc bit,
        @FlgAltLot bit,
        @FlgWms bit,
        @FlgCriIteFec bit,
        @FlgLotNaoFra bit,
        @FlgTemPDVLT bit,
        @CodGrpCli int,
        @CodCliPag int,
		@QtdMesMinPrzVctLot int

Set @FlgAltQtd = 0
Set @FlgAltPrc = 0
Set @FlgAltLot = 0

if Update(Qtd_Pedido) or Update(Qtd_Bonificacao) or Update(Id_PolCom)
  Set @FlgAltQtd = 1
  
if (@FlgAltQtd = 0) and ((Select Count(*) from Deleted) > 0) and ((Select Count(*) from Inserted) = 0)
  Set @FlgAltQtd = 1

if (@FlgAltQtd = 0) and ((Select Count(*) from Inserted) > 0) and ((Select Count(*) from Deleted) = 0)
  Set @FlgAltQtd = 1
  
if Update(Prc_Unitario) or Update(Per_Desconto) or Update(Per_Descon) or Update(Per_DscVis)
  Set @FlgAltPrc = 1

if Update(Cod_Lote)
  Set @FlgAltLot = 1

if (Select Count(*) from Deleted) > 0
  begin
    Select @TipPed    = IsNull(Ltrim(Rtrim(cb.Tip_Pedido)),''),
           @StaPdv1   = IsNull(Ltrim(Rtrim(cb.Status1)),''),
           @StaPdv2   = IsNull(Ltrim(Rtrim(cb.Status2)),''),
           @TipBlq    = IsNull(Ltrim(Rtrim(cb.Bloqueio)),''),
           @NumPrtOri = IsNull(cb.Num_PrtOri,0),
           @FlgCal    = IsNull(cb.Flg_Calc,0),
           @FlgWms    = IsNull(cb.Flg_Wms,0),
           @IdConsig  = IsNull(cb.Id_Consig,0),
           @NumSeqCtr = IsNull(cb.Num_SequenciaCtr,0)
      From PDVCB cb Inner Join 
           Deleted d on cb.Cod_Estabe = d.Cod_Estabe And cb.Numero = d.Cod_Pedido

    if @FlgCal = 0
      begin
        DECLARE Deleted_Cr CURSOR Local Fast_Forward For
          Select d.Cod_Estabe, d.Cod_Pedido, d.Cod_Produto, d.Cod_Lote, d.Tip_Sai, 
                 IsNull(d.Cod_Promocao,0), IsNull(d.Qtd_Pedido,0), IsNull(d.Qtd_Bonificacao,0),
                 IsNull(d.Qtd_Pra,0), IsNull(d.Qtd_Dep,0)
            From Deleted d
           Order by d.Cod_Produto
        OPEN Deleted_Cr
        FETCH NEXT FROM Deleted_Cr INTO @CodEstabe, @CodPed, @CodPrd, @CodLot, @TipSai, 
                                        @CodPrm, @QtdPed, @QtdBon,
                                        @QtdPra, @QtdDep
        WHILE @@FETCH_STATUS = 0
        BEGIN
          -- decrementa quantidades solicitadas
          -- esta rotina nao eh executada qdo se exclui o cab. do pedido e a trigger de PDVCB executa rotina que exclui itens em PDVIT (o cab. nao existe mais)
          if (@QtdPra+@QtdDep) <> (@QtdPed+@QtdBon)
            begin
              Set @QtdPra = @QtdPed + @QtdBon - @QtdDep
            end
          if @FlgAltQtd = 1
            if @FlgWms = 0
              EXEC PR_DecrementaSaldoSolicitado @CodEstabe, @TipPed, @StaPdv1, @StaPdv2, @TipBlq, @NumPrtOri,
                                                @CodPrd, @CodLot, @CodPrm, @QtdPra, @QtdDep
            else
              begin
                EXEC PR_DecrementaSaldoSolicitado_PRODU @CodEstabe, @TipPed, @StaPdv1, @StaPdv2, @TipBlq, @CodPrd, @CodPrm, @QtdPra, @QtdDep, 0
              end  

          FETCH NEXT FROM Deleted_Cr INTO @CodEstabe, @CodPed, @CodPrd, @CodLot, @TipSai, 
                                          @CodPrm, @QtdPed, @QtdBon,
                                          @QtdPra, @QtdDep
        END

        CLOSE Deleted_Cr
        DEALLOCATE Deleted_Cr           
      end       
  end

if (Select Count(*) from Inserted) > 0
  begin
    Select @TipPed = IsNull(Ltrim(Rtrim(cb.Tip_Pedido)),''),
           @TipBlq = IsNull(Ltrim(Rtrim(cb.Bloqueio)),''),
           @CodOriPed = IsNull(cb.Cod_OrigemPdv,''),
           @FlgCal = IsNull(cb.Flg_Calc,0),
           @FlgWms = IsNull(cb.Flg_Wms,0),
           @CodGrpCli = IsNull(cb.Cod_GrpCli,0),
		   @CodCliPag = IsNull(cl.Cod_CliPag,0),
		   @QtdMesMinPrzVctLot = IsNull(cl.Qtd_MesMinPrzVctLot,0),
           @FlgCriIteFec = IsNull(cb.Flg_CriIteFec,0),
           @FlgLotEsp = Case 
                          When IsNull(cb.Num_Referencia,0)+IsNull(cb.Num_PrtOri,0) > 0 Then 1 
                          Else 0 
                        End,
           @FlgLotNaoFra = Case
                             When (IsNull(cb.Cod_Contrato,0) > 0) and (CharIndex(cb.Tip_Consumidor,';P;E;M;') > 0) Then 1
                             Else 0
                           End,

           @IdConsig  = IsNull(cb.Id_Consig,0),
           @NumSeqCtr = IsNull(cb.Num_SequenciaCtr,0)
      From PDVCB cb Left Outer Join
	       CLIEN cl on cb.Cod_Cliente = cl.Codigo Inner Join 
           Inserted i on cb.Cod_Estabe = i.Cod_Estabe And cb.Numero = i.Cod_Pedido 


    if ( (@FlgCal = 0) and (@TipPed = 'P') and (@TipBlq <> 'SR') and (@QtdPed > 0) ) or
       ( (@FlgCriIteFec = 0) or (@TipSai = 'B') or (@FlgAltPrc = 1) or (@FlgAltQtd = 1) or (@FlgALtLot = 1) )
      begin
	    Set @FlgCalAnt = @FlgCal

        -- coloca o pedido em modo de calculo para evitar recursividade na procedure PR_SolicitaLoteProduto
        Update PDVCB
           Set Flg_Calc = 1
         Where Cod_Estabe = @CodEstabe
           And Numero = @CodPed

        DECLARE Inserted_Cr CURSOR Local Fast_Forward For
          Select i.Cod_Estabe, i.Cod_Pedido, i.Cod_Produto, i.Cod_Lote, i.Tip_Sai, 
                 IsNull(i.Cod_Promocao,0), IsNull(Cod_KitPrm,0), IsNull(i.Qtd_Pedido,0), IsNull(i.Qtd_Bonificacao,0),
                 Case 
                   When IsNull(i.Fat_CnvImpFat,1) = 0 then 1
                   Else IsNull(i.Fat_CnvImpFat,1)
                 End
            From Inserted i
           Order by i.Cod_Produto
        OPEN Inserted_Cr
        FETCH NEXT FROM Inserted_Cr INTO @CodEstabe, @CodPed, @CodPrd, @CodLot, @TipSai, 
                                         @CodPrm, @CodKitPrm, @QtdPed, @QtdBon,
                                         @FatCnvImpFat
        WHILE @@FETCH_STATUS = 0
        BEGIN
          if (@FlgCal = 0) and (@TipPed = 'P') and (@TipBlq <> 'SR') and (@QtdPed > 0) and (@FlgAltQtd = 1)
            begin
               -- solicita o(s) lote(s) do produto / calcula tributos e campos calculados
              if @FlgWms = 0
                begin
                  EXEC PR_SolicitaLoteProduto @CodEstabe, @CodPed, @FlgLotEsp, @CodPrd, @CodLot, @TipSai, @CodPrm, @CodKitPrm, @QtdPed, @QtdBon, @FatCnvImpFat, @FlgLotNaoFra
                end
              else
                begin
                  Set @FlgTemPDVLT = 0
                  if Exists(Select 1 From PDVLT Where Cod_Estabe = @CodEstabe and Cod_Pedido = @CodPed)
                    Set @FlgTemPDVLT = 1
                  EXEC PR_IncrementaSaldoSolicitado @CodEstabe, @CodPed, @CodGrpCli, @CodCliPag, @QtdMesMinPrzVctLot, @CodOriPed, @FlgTemPDVLT, @CodPrd, @CodLot, @TipSai, @CodPrm, @QtdPed, @QtdBon, @FatCnvImpFat
                end
            end

          -- calcula tributos  e campos calculados     
          if (@FlgCriIteFec = 0) or (@TipSai = 'B') or (@FlgAltQtd = 1) or (@FlgAltPrc = 1) or (@FlgAltLot = 1)
            EXEC PR_CalcTributPdvit @CodEstabe, @CodPed, @CodPrd, @CodLot, @TipSai

          FETCH NEXT FROM Inserted_Cr INTO @CodEstabe, @CodPed, @CodPrd, @CodLot, @TipSai, 
                                           @CodPrm, @CodKitPrm, @QtdPed, @QtdBon,
                                           @FatCnvImpFat
        END

        CLOSE Inserted_Cr
        DEALLOCATE Inserted_Cr           

        Update PDVCB
           Set Flg_Calc = @FlgCalAnt
         Where Cod_Estabe = @CodEstabe
           And Numero = @CodPed
      end       
  end  -- se inserted

-- Atualiza cabeçalho do pedido
EXEC PR_AtualizaCabecPDV @CodEstabe, @CodPed

-- Atualiza consignacao
if @IdConsig > 0
  Exec PR_AtualizaCNGRI @CodEstabe, @IdConsig, @NumSeqCtr

GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[V_PAGCT] AS

Select pg.Cod_Estabe, pg.Cod_Ctapag , pg.Tip_Documento, pg.Num_Docume, pg.Sta_Docume,
       pg.Dat_Emissa, pg.Dat_Vencim, pg.Dat_DscAtc, pg.Dat_Quitac,
     pg.Val_Saldo, pg.Val_DscAtc, pg.Val_Docume, pg.Val_DscCon, pg.Per_DscAtc,
     pg.Observacao, pg.Flg_Previs, pg.Cod_PrtNfe, pg.Cod_PrtPdc, 
     pg.Tip_Docume, pg.Cod_Fornec, pg.Cod_Favore, pg.Cod_AgeCob, pg.Isn_CtaFin,
     C_CodFavore = Case
                     When pg.Tip_Docume = 'F' then pg.Cod_Fornec
             Else pg.Cod_Favore
           End,
     C_DesFavore = Case
                     When pg.Tip_Docume = 'F' then (Select Razao_Social From FORNE Where Codigo = pg.Cod_Fornec)
             Else (Select Des_Favore From FAVOR Where Cod_Favore = pg.Cod_Favore)
          End,
     C_TipFavore = Case
                     When pg.Tip_Docume = 'F' then (Select Tipo From FORNE Where Codigo = pg.Cod_Fornec)
             Else (Select Tip_Favore From FAVOR Where Cod_Favore = pg.Cod_Favore)
          End,
       C_DesAgeCob = (Select Descricao From AGCOB Where Codigo = pg.Cod_AgeCob),
     C_QtdDiaPrz = Case
                       When (pg.Dat_Emissa > 0) and (pg.Dat_Vencim > 0) then DateDiff(day,pg.Dat_Emissa, pg.Dat_Vencim)
             Else 0
                   End,
     C_QtdDiaAtr = Case 
                       When pg.Dat_Vencim > 0 then
                         case 
                         when GetDate() > pg.Dat_Vencim then
                             case 
                           When IsNull(pg.Dat_Quitac,0) = 0 then dbo.FN_DiasAtraso(pg.Dat_Vencim,GetDate()) --DateDiff(day,pg.Dat_Vencim,GetDate())
                               else
                                 case 
                             When pg.Dat_Quitac > pg.Dat_Vencim then DateDiff(day,pg.Dat_Vencim,pg.Dat_Quitac)
                             Else 0
                           end      
                         end   
                         else 0
                       end
                       else 0
                     end,
     pg.Num_NotOri                     
From PAGCT pg

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_PDVCB_Atualiza_Depois] ON [dbo].[PDVCB] 
AFTER DELETE
NOT FOR REPLICATION
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 

Declare @Chave int,
        @CodEstabe int,
        @CodPed int,
        @IdPVMCB int

Declare @Tbl_Deleted table (Chave int Identity(1,1) not null,
                            Cod_Estabe int,
                            Numero int,
                            Id_PVMCB int)

Insert Into @Tbl_Deleted (Cod_Estabe, Numero, Id_PVMCB)
  Select d.Cod_Estabe, d.Numero, IsNull(d.Id_PVMCB,0)
    From Deleted d
   Where IsNull(Id_PVMCB,0) > 0
   Order by d.Numero

while Exists(Select 1 From @Tbl_Deleted)
  begin
    Select top 1 
           @Chave = Chave,
           @CodEstabe = Cod_Estabe, 
           @CodPed = Numero, 
           @IdPVMCB = Id_PVMCB
      From @Tbl_Deleted
     Order by Chave

    -- atualiza vinculados 
    Exec PR_AtualizaPVMIT @IdPVMCB, 0
    Exec PR_AtualizaPVMCB @IdPVMCB

    Delete From @Tbl_Deleted
     Where Chave = @Chave
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_PDVIT_AtualizaDados] ON [dbo].[PDVIT] 
AFTER INSERT, UPDATE, DELETE 
NOT FOR REPLICATION
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 

if Update(Cod_MtvRej)
  begin
	IF trigger_nestlevel() > 3 
	  RETURN

    Update P
       Set P.Des_MtvRej = Case
                            When IsNull(P.Des_MtvRej,'') = '' then Substring(dbo.FN_PegaDescricaoTBGEN('MTV',P.Cod_MtvRej),1,40)
                            Else P.Des_MtvRej
                         End
      From Inserted I 
           inner Join PDVIT P on (P.Cod_Estabe = I.Cod_Estabe and P.Cod_Pedido = I.Cod_Pedido and
                                  P.Cod_Produto = I.Cod_Produto and P.Cod_Lote = I.Cod_Lote and
                                  P.Tip_Sai = I.Tip_Sai)
     Where IsNull(P.Des_MtvRej,'') <> dbo.FN_PegaDescricaoTBGEN('MTV',I.Cod_MtvRej)
  end

if Update(Qtd_Pedido) or Update(Qtd_Bonificacao) or Update(Prc_Unitario) or Update(Fat_CnvImpFat)
  begin
	IF trigger_nestlevel() > 3 
	  RETURN

    Update P
       Set P.Vlr_Bruto = Round(P.Prc_Unitario * (P.Qtd_Pedido+P.Qtd_Bonificacao),2),
           P.Qtd_ImpFat = (P.Qtd_Pedido+P.Qtd_Bonificacao)*1.0/P.Fat_CnvImpFat,
           P.Prc_UniImpFat = P.Prc_Unitario * P.Fat_CnvImpFat
      From Inserted I 
           inner Join PDVIT P on (P.Cod_Estabe = I.Cod_Estabe and P.Cod_Pedido = I.Cod_Pedido and
                                  P.Cod_Produto = I.Cod_Produto and P.Cod_Lote = I.Cod_Lote and
                                  P.Tip_Sai = I.Tip_Sai)
     Where ((P.Vlr_Bruto <> Round(P.Prc_Unitario * (P.Qtd_Pedido+P.Qtd_Bonificacao),2)) or
	        (P.Qtd_ImpFat <> (P.Qtd_Pedido+P.Qtd_Bonificacao)*1.0/P.Fat_CnvImpFat) or
	        (P.Prc_UniImpFat <> P.Prc_Unitario * P.Fat_CnvImpFat))
       And P.Fat_CnvImpFat > 0
  end

if Update(C_PrcUni) or Update(C_PerDscIte)
  begin
	IF trigger_nestlevel() > 3 
	  RETURN

    Update P
       Set P.C_VlrDesconto = Round(P.Qtd_Pedido*P.C_PrcUni,2) - Round(P.Qtd_Pedido*P.C_PrcUni*(1-P.C_PerDscIte/100),2),
           P.C_PrcTotal    = Round(P.Qtd_Pedido*P.C_PrcUni*(1-P.C_PerDscIte/100),2),
           P.Prc_UniImpFat = Case When C.Flg_AltUnvItePdv = 1 then Round(P.C_PrcUni*P.Fat_CnvImpFat,pm.QtdDecPrcItePdv) Else P.C_PrcUni*P.Fat_CnvImpFat End
      From Inserted I 
           inner Join PDVIT P on (P.Cod_Estabe = I.Cod_Estabe and P.Cod_Pedido = I.Cod_Pedido and
                                  P.Cod_Produto = I.Cod_Produto and P.Cod_Lote = I.Cod_Lote and
                                  P.Tip_Sai = I.Tip_Sai)
           inner Join PDVCB C on (P.Cod_Estabe = C.Cod_Estabe and P.Cod_Pedido = C.Numero)
           inner Join PARAM pm on (P.Cod_Estabe = pm.Cod_Estabe)
     Where ((P.C_VlrDesconto <> Round(P.Qtd_Pedido*P.C_PrcUni,2) - Round(P.Qtd_Pedido*P.C_PrcUni*(1-P.C_PerDscIte/100),2)) or
            (P.C_PrcTotal    <> Round(P.Qtd_Pedido*P.C_PrcUni*(1-P.C_PerDscIte/100),2)) or
            (P.Prc_UniImpFat <> Case When C.Flg_AltUnvItePdv = 1 then Round(P.C_PrcUni*P.Fat_CnvImpFat,pm.QtdDecPrcItePdv) Else P.C_PrcUni*P.Fat_CnvImpFat End))
  end

if Update(C_PrcTotal) or Update(Vlr_DscRat) or Update(Vlr_RepIcms) or Update(Vlr_Despes) or
   Update(Vlr_SubsTrib) or Update(Vlr_SbtRes) or Update(Vlr_DspExt) or Update(Vlr_DscTri)
  begin
	IF trigger_nestlevel() > 3 
	  RETURN

    Update P
       Set P.C_VlrLiquido = P.C_PrcTotal -IsNull(P.Vlr_DscRat,0)- IsNull(P.Vlr_RepIcms ,0) +IsNull(P.Vlr_Despes,0) 
	                       +P.Vlr_SubsTrib +P.Vlr_SbtRes +P.Vlr_DspExt -P.Vlr_DscTri
      From Inserted I 
           inner Join PDVIT P on (P.Cod_Estabe = I.Cod_Estabe and P.Cod_Pedido = I.Cod_Pedido and
                                  P.Cod_Produto = I.Cod_Produto and P.Cod_Lote = I.Cod_Lote and
                                  P.Tip_Sai = I.Tip_Sai)
     Where P.C_VlrLiquido <> P.C_PrcTotal -IsNull(P.Vlr_DscRat,0)- IsNull(P.Vlr_RepIcms ,0) +IsNull(P.Vlr_Despes,0) 
	                        +P.Vlr_SubsTrib +P.Vlr_SbtRes +P.Vlr_DspExt -P.Vlr_DscTri

  end


Declare @IdPVMCB int = 0,
        @CodPrd int

if (Select Count(*) from Deleted) > 0
  begin
    Select @IdPVMCB   = IsNull(cb.Id_PVMCB,0)
      From PDVCB cb Inner Join 
           Deleted d on cb.Cod_Estabe = d.Cod_Estabe And cb.Numero = d.Cod_Pedido

    if @IdPVMCB > 0
	  begin
        DECLARE Deleted_Cr CURSOR Local Fast_Forward For
          Select distinct d.Cod_Produto
            From Deleted d
           Order by d.Cod_Produto
        OPEN Deleted_Cr
        FETCH NEXT FROM Deleted_Cr INTO @CodPrd
        WHILE @@FETCH_STATUS = 0
        BEGIN
          Exec PR_AtualizaPVMIT @IdPVMCB, @CodPrd

          FETCH NEXT FROM Deleted_Cr INTO @CodPrd
        END

        CLOSE Deleted_Cr
        DEALLOCATE Deleted_Cr           
	  end
  end  -- if (Select Count(*) from Deleted) > 0


if (Select Count(*) from Inserted) > 0
  begin
    Select @IdPVMCB   = IsNull(cb.Id_PVMCB,0)
      From PDVCB cb Inner Join 
           Inserted i on cb.Cod_Estabe = i.Cod_Estabe And cb.Numero = i.Cod_Pedido

    if @IdPVMCB > 0
	  begin
        DECLARE Inserted_Cr CURSOR Local Fast_Forward For
          Select distinct i.Cod_Produto
            From Inserted i
           Order by i.Cod_Produto
        OPEN Inserted_Cr
        FETCH NEXT FROM Inserted_Cr INTO @CodPrd
        WHILE @@FETCH_STATUS = 0
        BEGIN
          Exec PR_AtualizaPVMIT @IdPVMCB, @CodPrd

          FETCH NEXT FROM Inserted_Cr INTO @CodPrd
        END

        CLOSE Inserted_Cr
        DEALLOCATE Inserted_Cr           
	  end
  end  -- if (Select Count(*) from Inserted) > 0

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_FechaPVMCB]
@PIdPVMCB int   
AS

SET NOCOUNT ON

if Charindex((Select Sta_Pedido From dbo.PVMCB Where Id_PVMCB = @PIdPVMCB),';F;') > 0 
  RAISERROR('Pedido já fechado',16,1)
else
begin
  -- elimina pedidos de vendas sem itens
  Delete cb
    From dbo.PDVCB cb 
   Where cb.Id_PVMCB = @PIdPVMCB
     And cb.Status2 = 'A' 
     And not Exists (Select 1 
                       From dbo.PDVIT it 
                      Where it.Cod_Estabe = cb.Cod_estabe 
                        And it.Cod_Pedido = cb.Numero 
                        And it.Qtd_Pedido > 0) 

  if not exists(Select 1
                  From dbo.PDVCB
                 Where Id_PVMCB = @PIdPVMCB
                   And Status2 = 'A')
    Update cb
       Set cb.Sta_Pedido = 'F'
      From dbo.PVMCB cb
     Where cb.Id_PVMCB = @PIdPVMCB

end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CriaPedidoVendaPVM]
@PIdPVMCB int,
@PCodEstIte int,
@PIdPolComIte int,
@PCodPrd int,

@PEstPdv int output,
@PNumPdv int output,
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

Set @PMsgErr = ''
Set @PEstPdv = 0
Set @PNumPdv = 0

if Exists(Select 1 
            From dbo.PDVCB cb
                 inner join dbo.POCOM pcb on pcb.Id_PolCom = cb.Id_PolCom
                 inner join dbo.POCOM pit on pit.Id_PolCom = @PIdPolComIte
           Where cb.Cod_Estabe = @PCodEstIte and cb.Id_PVMCB = @PIdPVMCB 
             And ( (cb.Status1 <> 'P')  or  
                   ((cb.Status1 = 'P') and (cb.Status2 <> 'A') and (cb.Status2 <> 'X')) )
             And ( (pcb.Id_PolCom = pit.Id_PolCom) or 
                   (IsNull(pcb.Flg_BlqPolDifItePdv,0) = 0) and (IsNull(pit.Flg_BlqPolDIfCabPdv,0) = 0) ) )
  begin
    Select top 1 
           @PMsgErr = Case
                        When cb.Status1 <> 'P' then 'Pedido não está "pendente"'		   	 
                        Else 'Pedido não está "em aberto"'
                      End
      From dbo.PDVCB cb
           inner join dbo.POCOM pcb on pcb.Id_PolCom = cb.Id_PolCom
           inner join dbo.POCOM pit on pit.Id_PolCom = @PIdPolComIte
     Where cb.Cod_Estabe = @PCodEstIte and cb.Id_PVMCB = @PIdPVMCB 
       And ( (cb.Status1 <> 'P')  or  
             ((cb.Status1 = 'P') and (cb.Status2 <> 'A') and (cb.Status2 <> 'X')) )
       And ( (pcb.Id_PolCom = pit.Id_PolCom) or 
             (IsNull(pcb.Flg_BlqPolDifItePdv,0) = 0) and (IsNull(pit.Flg_BlqPolDIfCabPdv,0) = 0) ) 
  end

else
if Exists(Select 1 
            From dbo.PDVCB cb
                 inner join dbo.POCOM pcb on pcb.Id_PolCom = cb.Id_PolCom
                 inner join dbo.POCOM pit on pit.Id_PolCom = @PIdPolComIte
           Where cb.Cod_Estabe = @PCodEstIte and cb.Id_PVMCB = @PIdPVMCB
	         And cb.Status1 = 'P'
             And ( (cb.Status2 = 'A') or (cb.Status2 = 'X') )
             And ( (pcb.Id_PolCom = pit.Id_PolCom) or 
                   (IsNull(pcb.Flg_BlqPolDifItePdv,0) = 0) and (IsNull(pit.Flg_BlqPolDIfCabPdv,0) = 0) ) )
  begin
    Select top 1 
           @PEstPdv = cb.Cod_Estabe, 
		   @PNumPdv = cb.Numero
      From dbo.PDVCB cb
           inner join dbo.POCOM pcb on pcb.Id_PolCom = cb.Id_PolCom
           inner join dbo.POCOM pit on pit.Id_PolCom = @PIdPolComIte
     Where cb.Cod_Estabe = @PCodEstIte and cb.Id_PVMCB = @PIdPVMCB
       And cb.Status1 = 'P'
       And ( (cb.Status2 = 'A') or (cb.Status2 = 'X') )
       And ( (pcb.Id_PolCom = pit.Id_PolCom) or 
             (IsNull(pcb.Flg_BlqPolDifItePdv,0) = 0) and (IsNull(pit.Flg_BlqPolDIfCabPdv,0) = 0) )
  end

else
  begin
    BEGIN TRANSACTION

    Set @PEstPdv = @PCodEstIte
    Set @PNumPdv = 0

    Declare @WFlgBlqWms bit = 0,     -- nunca usa WMS
            @WFlgBlqPol bit = 0,     -- nunca usa politica
            @WFlgUsaWms bit = 0,

            @pvm_CodClient int,    
            @pvm_CodDigita int, 
            @pvm_CodOriPdv varchar(1),
            @pvm_TipFat varchar(3),
            @pvm_CodVended int, 
            @pvm_CodOperad int,
            @pvm_CodTabPrz int

    -- PVMCB
    Select @pvm_CodOriPdv = IsNull(Substring(Cod_OrigemPdv,1,1),'A'),
           @pvm_TipFat    = IsNull(Tip_Faturamento,'FAT'),
           @pvm_CodClient = IsNull(Cod_Cliente,0), 
           @pvm_CodDigita = IsNull(Cod_Digitador,0), 
           @pvm_CodOperad = IsNull(Cod_VendTlmkt,0), 
           @pvm_CodVended = IsNull(Cod_Vendedor,0),
           @pvm_CodTabPrz = 0
      From dbo.PVMCB
     Where ID_PVMCB = @PIdPVMCB

    Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
                                              HASHBYTES('MD5',(Select Num_Cnpj From dbo.ESTAB Where Cod_Estabe = @PEstPdv))))

    -- ajusta flags
    if @WFlgBlqWms = 1         -- nunca usa WMS
      Set @WFlgUsaWms = 0

    if @WFlgBlqPol = 1         -- nunca usa politica
      Set @PIdPolComIte = 0
        
    Set @WFlgBlqPol = 0

    Exec PR_IncluiPDVCB 'P', @PEstPdv, @PNumPdv output, @pvm_CodOriPdv, @pvm_CodClient, @WFlgUsaWms, @pvm_TipFat,
                        @pvm_CodVended, @pvm_CodOperad, @pvm_CodDigita, @PIdPolComIte, @pvm_CodTabPrz, 0,
                        @WFlgBlqWms, @WFlgBlqPol, @PMsgErr output, @PIdPVMCB



    Declare @WIdPolComCab int = 0,
	        @cb_TipPrz varchar(1) = '',
			@cb_IdPolComCab int,
            @cb_DatPed smalldatetime, 
			@cb_CodLayPde int, 
			@cb_CodGrpLay int
            
    Select @pvm_CodOriPdv = Substring(Cod_OrigemPdv,1,1),
           @cb_TipPrz = IsNull(Substring(Cod_OrigemPdv,2,1),''),
           @pvm_CodVended = Cod_Vendedor,
           @pvm_CodOperad = Cod_VendTlmkt,
		   @pvm_CodTabPrz = IsNull(Cod_Prz,0),

           @cb_DatPed = Dat_Pedido,
           @cb_IdPolComCab = 0,
           @cb_CodLayPde = 0,
           @cb_CodGrpLay = 0

      From PDVCB
     Where Cod_Estabe = @PEstPdv
       And Numero = @PNumPdv

    -- aqui define melhor Id_PolCom para cabeçalho do pedido
	Set @WIdPolComCab = 0

    Select top 1 @WIdPolComCab = pc.Id_Polcom 
      From dbo.FN_RetornaPoliticasCliente(@pvm_CodOriPdv, @cb_TipPrz, @PEstPdv, 
                                         @pvm_CodClient, @pvm_CodVended, @pvm_CodOperad, @pvm_CodTabPrz) pc
           inner join dbo.FN_RetornaPoliticasProduto(@pvm_CodOriPdv, @PEstPdv, 
                                                     @pvm_CodClient, @pvm_CodVended, @pvm_CodOperad, @cb_IdPolComCab, 
                                                     @PCodPrd, @cb_DatPed, @cb_CodLayPde, @cb_CodGrpLay) pp on pc.Id_PolCom = pp.Id_PolCom
     Where pc.Flg_BlqPolDifCabPdv = 0
       And pc.Flg_BlqPolDifItePdv = 0
     Order by pc.Prioridade, pc.Cod_Estabe, pc.Flg_BlqCli, pc.Dat_Cadastro desc

/*
    if IsNull(@WIdPolComCab,0) = 0
      Select top 1 @WIdPolComCab = pc.Id_Polcom 
        From dbo.FN_RetornaPoliticasCliente(@pvm_CodOriPdv, @cb_TipPrz, @PEstPdv, 
                                           @pvm_CodClient, @pvm_CodVended, @pvm_CodOperad, @pvm_CodTabPrz) pc
             inner join dbo.FN_RetornaPoliticasProduto(@pvm_CodOriPdv, @PEstPdv, 
                                                       @pvm_CodClient, @pvm_CodVended, @pvm_CodOperad, @cb_IdPolComCab, 
                                                       @PCodPrd, @cb_DatPed, @cb_CodLayPde, @cb_CodGrpLay) pp on pc.Id_PolCom = pp.Id_PolCom
       Where pc.Flg_BlqPolDifCabPdv = 0
       Order by pc.Prioridade, pc.Cod_Estabe, pc.Flg_BlqCli, pc.Dat_Cadastro desc
*/

    Update pv
       Set pv.Status2 = 'X',    
           pv.ID_PVMCB = @PIdPVMCB,
		   pv.Id_PolCom = Case 
                            When IsNull(@WIdPolComCab,0) > 0 then IsNull(@WIdPolComCab,0) 
                            Else pv.Id_PolCom 
                          End,
           pv.Observacao = IsNull((Select Obs_PreNot From PVMCB Where ID_PVMCB = @PIdPVMCB),'')
      From dbo.PDVCB pv
     Where pv.Cod_Estabe = @PEstPdv
       And pv.Numero = @PNumPdv

    -- mapeia pedido de venda com pedido de venda multi-estabe
    if (@PIdPVMCB > 0) and
       not Exists(Select 1
                    From PMXPV
                   Where Id_PVMCB = @PIdPVMCB
                     And Num_PedVen = @PNumPdv)
      Insert into PMXPV (ID_PVMCB, Num_PedVen) 
	             Values (@PIdPVMCB, @PNumPdv);

    if @@trancount > 0
      COMMIT TRANSACTION

  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- desconsiderar esta rotina
CREATE PROCEDURE [dbo].[PR_GeraPedidoVendaPVM]
@PCodEstPad int,
@PCodEstIte int,
@PID_PVMCB int

AS

SET NOCOUNT ON
begin

    BEGIN TRANSACTION

    Declare @WTipPrc varchar(1),
            @WMsgAux varchar(100),
            @WNumSeqIte int,
            @WTipPrz varchar(1),
            @WNomUsuSnhEsp varchar(35),
            @WFlgBlqAltPrcPol bit,
            @WTipImpPrcPdv varchar(1),
            @WFlgSnhEsp bit,          
            @WFlgBlqCriConCom bit,    
            @WFlgBlqCriPrcVen bit,
            @WFlgBlqEstFisNeg bit,
            @WFlgCriVrb bit,
            @WFatCnvCxaFec int,			     
            @WPerDscArq numeric(8,4),
            @WPrcUniArq numeric(18,8),
            @WPerDsc numeric(8,4),
            @WPrcLiqArq numeric(18,8),
			@PMsgErr varchar(8000),
            @PNumPdv int = NULL,

            @WFlgBlqWms bit = 0,     -- nunca usa WMS
            @WFlgBlqPol bit = 0,     -- nunca usa politica
            @WFlgUsaWms bit = 0

    Declare @pm_FlgUsaPolComPdv bit = 0,
            @pm_PrzRefPrcVen int,
            @pm_FlgAltUnvItePdv bit,
            @pm_CodVdrPdvCon int,
            @pm_QtdDecPrcItePdv int,

            @pvm_Layout varchar(20),
            @pvm_CodOriPed varchar(1),
            @pvm_CodClient int, 
            @pvm_CodVended int, 
            @pvm_CodOperad int,
            @pvm_CodDigita int,
            @pvm_IdPolCom int,
            @pvm_CodTabPrz int,
            @pvm_TipFat varchar(3)

    -- PARAM
    Select @pm_FlgUsaPolComPdv = IsNull(FlgUsaPolComPdv,0),
           @pm_PrzRefPrcVen = IsNull(PrzRefPrcVen,0),
           @pm_FlgAltUnvItePdv = IsNull(FlgAltUnvItePdv,0),
		   @pm_CodVdrPdvCon = IsNull(CodVdrPdvCon,0),
           @pm_QtdDecPrcItePdv = IsNull(QtdDecPrcItePdv,0)
      From dbo.PARAM
      Where Cod_Estabe = @PCodEstIte

    -- PVMCB
    Select @pvm_TipFat    = IsNull(Tip_Faturamento,'FAT'),
	       @pvm_CodClient = IsNull(Cod_Cliente,0), 
           @pvm_CodVended = IsNull(Cod_Vendedor,0), 
           @pvm_CodOperad = IsNull(Cod_VendTlmkt,0), 
           @pvm_CodDigita = IsNull(Cod_Digitador,0), 
           @pvm_IdPolCom = IsNull(Id_PolCom,0),
           @pvm_CodTabPrz = 0
      From dbo.PVMCB
     Where Cod_EstPad = @PCodEstPad
	   and ID_PVMCB = @PID_PVMCB

    Set @PMsgErr = ''
    if @PNumPdv is null
      Set @PNumPdv = 0

    Set @WTipImpPrcPdv = 'A'
    if @WTipImpPrcPdv = 'A'
      Set @WFlgBlqCriConCom = 1
    else
      Set @WFlgBlqCriConCom = 0

   if (@PNumPdv = 0) or (not Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstIte and Numero = @PNumPdv))
      begin
        -- WMS
        Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
		                                          HASHBYTES('MD5',(Select Num_Cnpj From dbo.ESTAB Where Cod_Estabe = @PCodEstIte))))

        if @pvm_CodOriPed = '' 
		  Set @pvm_CodOriPed = 'A'

        -- ajusta flags
        if @WFlgBlqWms = 1         -- nunca usa WMS
          Set @WFlgUsaWms = 0

        if @WFlgBlqPol = 1         -- nunca usa politica
          begin
            Set @pm_FlgUsaPolComPdv = 0
            Set @pvm_IdPolCom = 0
          end
        
        Set @WFlgBlqWms = 0
        Set @WFlgBlqPol = 0

        Exec PR_IncluiPDVCB 'P', @PCodEstIte, @PNumPdv output, @pvm_CodOriPed, @pvm_CodClient, @WFlgUsaWms, @pvm_TipFat,
                            @pvm_CodVended, @pvm_CodOperad, @pvm_CodDigita, @pvm_IdPolCom, @pvm_CodTabPrz, 0,
                            @WFlgBlqWms, @WFlgBlqPol, @PMsgErr output, @PID_PVMCB

      end

    Update pv
       Set pv.Status2 = 'X',    
           pv.ID_PVMCB = @PID_PVMCB, 
           pv.Tip_Vencimento = '',
           pv.Observacao = pe.Observacao,     -- ''
           pv.Obs_NotFis = pe.Obs_NotFis,      -- ''
           pv.Qtd_Parcela = IsNull(pe.Qtd_Parcela,0), 
           pv.Qtd_PrzMed  = IsNull(pe.Qtd_PrzMed,0)*1.0,
           pv.Dat_LimEnvPrp = cast(GETDATE() as smalldatetime)
      From dbo.PDVCB pv, dbo.PVMCB pe
     Where pv.Cod_Estabe = @PCodEstIte
       And pv.Numero = @PNumPdv
       And pv.Status1 = 'P'     -- Pendente
       And ((pv.Status2 = 'A') or (pv.Status2 = 'X'))  -- em aberto    
       And pe.Cod_EstPad = @PCodEstPad
       And pe.ID_PVMCB = @PID_PVMCB

    -- mapeia pedido de venda com pedido de venda multi-estabe
    insert into PMXPV (ID_PVMCB, Num_PedVen) values (@PID_PVMCB, @PNumPdv);

    -- inclui itens somente se pedido está "aberto"
    if Exists(Select Numero From dbo.PDVCB 
               Where Cod_Estabe = @PCodEstIte and Numero = @PNumPdv 
                 And Status1 = 'P' And ((Status2 = 'A') or (Status2 = 'X')))
      begin

        Declare @op_CfoNorInt int,
                @cl_Codigo int,
                @cl_FlgLicSauInv bit,
                @cl_FlgLicAnvInv bit,
                @pv_CodTipPed varchar(3)  -- 'PDV','COT'

        Select @WTipPrc = op.Tip_Prc,    -- ver tipo de transacao p/ escolher o preco a ser utilizado no pedido
               @op_CfoNorInt = IsNull(op.Cod_CfoNorInt,0),
               @WTipPrz = Substring(cb.Cod_OrigemPdv,2,1),
               @cl_Codigo = IsNull(cl.Codigo,0), 
               @cl_FlgLicSauInv = 0,
               @cl_FlgLicAnvInv = 0,
               @pv_CodTipPed = Case When cb.Tip_Pedido = 'C' then 'COT' Else'PDV' End
          From dbo.PDVCB cb 
               Left Outer Join dbo.TPOPE op on cb.Tip_Faturamento = op.Cod_Ope 
               Left Outer Join dbo.CLIEN cl on cb.Cod_Cliente = cl.Codigo 
         Where cb.Cod_Estabe = @PCodEstIte
           And cb.Numero = @PNumPdv
           And cb.Status1 = 'P'
           And ((cb.Status2 = 'A') or (cb.Status2 = 'X')) 

        -- flg licenças
        Set @cl_FlgLicSauInv = 0
        Set @cl_FlgLicAnvInv = 0
        if @cl_Codigo > 0
          begin
            Exec PR_AnalisaLicencaCliente @pv_CodTipPed, 'SAUDE',  @cl_Codigo, @cl_FlgLicSauInv output, @WMsgAux output
            Exec PR_AnalisaLicencaCliente @pv_CodTipPed, 'ANVISA', @cl_Codigo, @cl_FlgLicAnvInv output, @WMsgAux output
          end
         
        -- estoque fiscal
        Set @WFlgBlqEstFisNeg = 0
        if (IsNull((Select BlqEstFisNeg From dbo.PMEST Where Cod_Estabe = @PCodEstIte),0) = 1) and (@op_CfoNorInt > 0)
          Set @WFlgBlqEstFisNeg = 1

         -- coloca o pedido em processamento
        Update dbo.PDVCB 
           Set Status2 = 'X'
         Where Cod_Estabe = @PCodEstIte
           And Numero = @PNumPdv
           And Status2 <> 'X' 

        -- sequencial do item na PDVIT
        Set @WNumSeqIte = IsNull((Select max(Num_SeqDig) From dbo.PDVIT 
                                   Where Cod_Estabe = @PCodEstIte
                                     And Cod_Pedido = @PNumPdv),0) + 1

        -- inclui itens emm PDVIT
        Declare @WPFlgAchou bit,
                @WPLocFis varchar(15),
                @WPCodFab int,
                @WPFatCnvImpFat int,
                @WPPrcFab numeric(18,8),
                @WPPrcMaxCon numeric(18,8),
                @WPPrcRefFpb numeric(18,8),
                @WPPrcCusMinComMarkup numeric(18,8),
                @WPPrcTab numeric(18,8),
                @WPPrcTabBru numeric(18,8),
                @WPPrcUni numeric(18,8),
                @WPPrcMin numeric(18,8),
                @WPPrcUniLiqPer numeric(18,8),
                @WPFlgEmbDscPrc bit,
                @WPPerDscLin numeric(8,4),
                @WPPerDscPrz numeric(8,4),
                @WPPerDscVis numeric(8,4),
                @WPQtdPrzMax int,

                @WPPerDscPolCom numeric(8,4),
                @WPPerDscVisPolCom numeric(8,4),
                @WPPrcPolCom numeric(18,8),
                @WPQtdPrzPolCom int,
                @WPCodKitPrm int,
                @WPCodPromoc int,
                @WPFlgVerba bit,
                @WPFlgPolPrm bit,
                @WPVlrVrbDis numeric(18,4),

                @WPCodRej varchar(3),
                @WPDesMsg varchar(80),
                @WPCmp varchar(20),
                @WPNomUsuDbq varchar(35),
                @WPDesMsgDbq varchar(60),
                @WPQtdImpFat int, 
                @WPPrcUniImpFat numeric(18,8),
		        @WPCodLot varchar(20),
                @WPPrcUniPde numeric(18,8),
                @WPPerDscPde numeric(8,4),
                @WPCodPrjPde varchar(12),
                @WPNumSeqPdc varchar(6),
                @WPTipSai varchar(1),
                @WPC_PrcUni numeric(18,8),
                @WPC_PerDscIte numeric(8,4),
                @WPPrcUniLiqPdv numeric(18,8),
                @WPC_VlrDesconto numeric(18,8),
                @WPC_PrcTotal numeric(18,8),

                @WIte_Chave int = 0,
                @WIte_FlgDscInf bit,
                @WIte_FlgPrcInf bit,
                @WIte_FlgPrzInf bit,
                @WIte_FlgPolInf bit,
                @WIte_FlgBlqQtdPar bit,

				@WIte_CodPrdArq varchar(14),
		        @WIte_CodPrd int,
                @WIte_FatCnvImpFat int,
                @WIte_FatAprPad smallint,
                @WIte_QtdPed int,
                @WIte_QtdBon int,
                @WIte_PrcUni numeric(18,4),
                @WIte_IdPolCom int,
                @WIte_PerDsc numeric(18,4),
                @WIte_PrcUniArq numeric(18,8),
                @WIte_PerDscArq numeric(8,4),

                @WIte_QtdPedInf int,
                @WIte_QtdBonInf int,
                @WIte_QtdSolInf int,
                @WIte_QtdAceInf int,
                @WIte_PrcUniInf numeric(18,8),
                @WIte_PerDscInf numeric(8,4),
                @WIte_DesUnvImpFat varchar(3),
				@WIte_DesAprImpFat varchar(12), 
                @WIte_PrcUniImpFat numeric(18,8),
                @WIte_CodProjeto varchar(12),
                @WIte_NumSeqPdc varchar(6),
                @WIte_TipSai varchar(1),
                @WIte_CodTipDsc varchar(1),
                @WIte_CodPrdEmbFec varchar(4), 
                @WIte_QtdEmbFec int,
                @WIte_PerDscEmbPrc numeric(8,4),

                @Wpr_PrcCusLiqEnt numeric(18,4),

                @pvit_CodLot varchar(20),
                @ap_FatCnvApr int,
                @ap_DesUnvApr varchar(3),
                @ap_DesApr varchar(12),

                @pc_FlgNegDsc bit,
                @pc_FlgBlqVerba bit,

				@WQtdPedAte int,
                @WQtdFisDsp int


        Declare @tb_PVMIT table(
          Chave int identity(1,1) primary key,
          Cod_Produt int, 
          Tip_Sai varchar(1), 
          Qtd_Pedido int, 
          Prc_Unitario numeric(18,4),
          Cod_TipDsc varchar(1), 
          Per_Desconto numeric(18,4), 
          Id_PolCom int, 
		  Cod_PrdEmbFec varchar(14),
          Qtd_Embala int,
          Fat_CnvImpFat int, 
          Fat_AprPad smallint,
          Des_UnvImpFat char(3),
          Des_AprImpFat varchar(12),
          Prc_UniImpFat numeric(18,8),
          Cod_Projeto varchar(12),
          Num_SeqPdc varchar(6),
          Per_DscEmbPrc numeric(18,4),
          Flg_PrcInf bit,
          Flg_DscInf bit,
          Flg_PrzInf bit,
          Flg_PolInf bit,
          Flg_BlqQtdPar bit,
          Prc_UnitarArq numeric(18,4),
          Per_DesconArq numeric(8,4)
        )

        -- seleciona registros candidatos
        Insert Into @tb_PVMIT
          Select IsNull(Cod_Produto,0), IsNull(Tip_Sai,''), IsNull(Qtd_Pedido,0), IsNull(Prc_Unitario,0), 
                 '', IsNull(Per_Desconto,0), IsNull(Id_PolCom,0), '', 0,
                 IsNull(Fat_CnvImpFat,0), 0, IsNull(Des_UnvImpFat,''), IsNull(Des_AprImpFat,''), 
                 IsNull(Prc_UniImpFat,0), '', '', 0,
				 0, 0, 0, 0, 0,
				 IsNull(Prc_Unitario,0), IsNull(Per_Desconto,0)
            From dbo.PVMIT
           Where Cod_Estabe = @PCodEstIte
             And ID_PVMCB = @PID_PVMCB

        While Exists(Select 1 From @tb_PVMIT)
          BEGIN
            Select top 1 @WIte_Chave = t.Chave,
                         @WIte_CodPrd = t.Cod_Produt,
                         @WIte_TipSai = t.Tip_Sai,
                         @WIte_QtdPed = t.Qtd_Pedido,
                         @WIte_PrcUni = t.Prc_Unitario,
                         @WIte_CodTipDsc = t.Cod_TipDsc, 
                         @WIte_PerDsc = t.Per_Desconto, 
                         @WIte_IdPolCom = t.Id_PolCom, 
                         @WIte_CodPrdEmbFec = t.Cod_PrdEmbFec, 
                         @WIte_QtdEmbFec = t.Qtd_Embala,
                         @WIte_FatCnvImpFat = t.Fat_CnvImpFat, 
                         @WIte_FatAprPad = t.Fat_AprPad, 
                         @WIte_DesUnvImpFat = t.Des_UnvImpFat, 
                         @WIte_DesAprImpFat = t.Des_AprImpFat, 
                         @WIte_PrcUniImpFat = t.Prc_UniImpFat, 
                         @WIte_CodProjeto = t.Cod_Projeto,
                         @WIte_NumSeqPdc = t.Num_SeqPdc,
                         @WIte_PerDscEmbPrc = t.Per_DscEmbPrc,
                         @WIte_FlgPrcInf = t.Flg_PrcInf, 
                         @WIte_FlgDscInf = t.Flg_DscInf, 
                         @WIte_FlgPrzInf = t.Flg_PrzInf, 
                         @WIte_FlgPolInf = t.Flg_PolInf, 
                         @WIte_FlgBlqQtdPar = t.Flg_BlqQtdPar,
                         @WIte_PrcUniArq = t.Prc_UnitarArq, 
                         @WIte_PerDscArq = t.Per_DesconArq
              From @tb_PVMIT t

            -- Tudofarma: Cod_TipDsc = '1' (industria) -> @WTipImpPrcPdv = 'A'
            if @WIte_CodTipDsc = '1' --desconto da industria
              begin
                Set @WIte_FlgDscInf = 1
              end
            else
            if @WIte_CodTipDsc = '0' --desconto distribuidor
              Set @WTipImpPrcPdv = 'I' 
				              
            Set @WQtdPedAte  = 0
            Set @WIte_QtdBon = 0
            if @WIte_FatCnvImpFat = 0 
              Set @WIte_FatCnvImpFat = 1
            if @WIte_FatAprPad = 0 
              Set @WIte_FatAprPad = 1

            -- inclui PDVIT
            if @WIte_CodPrd > 0
              begin

                Select @pvit_CodLot = IsNull(Cod_Lote,'') 
                  From dbo.PDVIT 
                 Where Cod_Estabe = @PCodEstIte
                   And Cod_Pedido = @PNumPdv
                   And Cod_Produto = @WIte_CodPrd
                 Order by Qtd_Pedido desc 

                if not Exists(Select Cod_Lote From dbo.PDVIT 
                               Where Cod_Estabe = @PCodEstIte
                                 And Cod_Pedido = @PNumPdv
                                 And Cod_Produto = @WIte_CodPrd) 
                  begin  

-------------------------  Confirmar se vem tudo calculado em PVMIT --------------------------------------------------------------------------------------------------------------------
                    if @WIte_FatCnvImpFat = 0 
                      Set @WIte_FatCnvImpFat = 1

                    if @WIte_FatAprPad = 0 
                      Set @WIte_FatAprPad = 1

                    if (@pm_FlgAltUnvItePdv = 1) and (@WIte_FatCnvImpFat = 1) and
                       Exists(Select Cod_Apr From dbo.PRXAP 
                               Where Cod_Produt = @WIte_CodPrd 
                                 And IsNull(Flg_Padrao,0) = 1 And IsNull(Fat_CnvApr,0) > 1) 
                      begin
                        Select @ap_DesApr = Des_Apr, 
                               @ap_FatCnvApr = IsNull(Fat_CnvApr,0), 
                               @ap_DesUnvApr = IsNull(Des_UnvApr,'') 
                          From dbo.PRXAP 
                         Where Cod_Produt = @WIte_CodPrd
                           And IsNull(Flg_Padrao,0) = 1 
                           And IsNull(Fat_CnvApr,0) > 1 

-----------------------------------------------------------------------------
                       Set @WIte_FatAprPad    = @ap_FatCnvApr
                       Set @WIte_FatCnvImpFat = @ap_FatCnvApr
                       Set @WIte_DesUnvImpFat = @ap_DesUnvApr
                       Set @WIte_DesAprImpFat = @ap_DesApr
                      end

                    if (@WIte_PrcUniImpFat = 0) and (@WIte_FatCnvImpFat > 1) 
                      Set @WIte_PrcUniImpFat = @WIte_PrcUni * @WIte_FatCnvImpFat

-------------------------------------------------------------------------------------------------------------

                    Set @WIte_QtdPedInf = @WIte_QtdPed*@WIte_FatAprPad
                    Set @WIte_QtdBonInf = @WIte_QtdBon*@WIte_FatAprPad
                    Set @WIte_PrcUniInf = @WIte_PrcUni/@WIte_FatAprPad
                    Set @WIte_PerDscInf = @WIte_PerDsc

--------------------------------------------------------------------------------------------------------------

                    if (@pvm_IdPolCom = 0) and (@WIte_IdPolCom > 0)
                      begin
                        Set @pvm_IdPolCom = @WIte_IdPolCom
                        Update dbo.PVMCB
                           Set Id_PolCom = @pvm_IdPolCom
                         Where Cod_EstPad = @PCodEstPad
                           And ID_PVMCB = @PID_PVMCB
                      end

                    Exec PR_InfoDefaultPDVIT @pm_FlgUsaPolComPdv, @PCodEstIte, @PNumPdv, @WIte_CodPrd, 
                                             @WIte_QtdPedInf, @WIte_QtdBonInf, @WIte_IdPolCom output, False,
                                             @WPFlgAchou output,
                                             @WPLocFis output,
                                             @WPCodFab output,
                                             @WPPrcFab output,
                                             @WPPrcMaxCon output,
                                             @WPPrcRefFpb output,
                                             @WPPrcTab output,
                                             @WPPrcTabBru output,
                                             @WPFatCnvImpFat output,     -- ???? @WIte_FatCnvImpFat
                                             @WPPrcUni output,
                                             @WPPrcCusMinComMarkup output,
                                             @WPPerDscPolCom output,
                                             @WPPerDscVisPolCom output,
                                             @WPPrcPolCom output,
                                             @WPQtdPrzPolCom output,
                                             @WPFlgVerba output,
                                             @WPFlgPolPrm output,
                                             @WPCodKitPrm output,
                                             @WPCodPromoc output,
                                             @WPFlgEmbDscPrc output, 
                                             @WPQtdPrzMax output,
                                             @WPPerDscLin output,
                                             @WPPerDscPrz output,
                                             @WPPerDscVis output,
                                             @WPPrcUniLiqPer output

                    if @WPFlgAchou = 1
                      begin
                        if @pm_FlgUsaPolComPdv = 0
                          begin
                            if @WTipImpPrcPdv <> 'I' 
                              if (@WIte_FlgDscInf = 1) or (@WIte_FlgPrcInf = 1)
                                begin
                                  -- variaveis ref. desc. a ser considerado
                                  Set @WPerDscArq = 0
                                  if (@WIte_FlgDscInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R')) and (IsNull(@WIte_PerDscEmbPrc,0) = 0) 
                                    Set @WPerDscArq = @WIte_PerDsc

                                  Set @WPrcUniArq = @WPPrcUni

                                  if (@WIte_FlgPrcInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R'))
                                    Set @WPrcUniArq = @WIte_PrcUniInf

                                  if Isnull(@WPrcUniArq,0) = IsNull(@WPPrcUni,0)
                                    Set @WPerDsc = @WPerDscArq
                                  else
                                    begin
                                      Set @WPrcLiqArq = Round(@WPrcUniArq*(1-@WPerDscArq/100),@pm_QtdDecPrcItePdv)
                                      if @WPPrcUni > @WPrcLiqArq 
                                         Set @WPerDsc = Round((@WPPrcUni-@WPrcLiqArq)*100/@WPPrcUni,2)
                                      else
                                        Set @WPerDsc = @WIte_PerDscEmbPrc
                                    end

                                  Set @WPPrcUni = @WPrcUniArq
                                  Set @WPPerDscLin = @WPerDsc
                                  Set @WPPerDscPrz = @WPerDsc
                                  Set @WPPerDscVis = @WPerDsc
                                end
                          end  -- if @pm_FlgUsaPolComPdv = 0

                        if @pm_FlgUsaPolComPdv = 1
                          begin
                            Set @pc_FlgNegDsc = 0
                            Set @pc_FlgBlqVerba = 0
                            
                            Select @pc_FlgNegDsc = IsNull(Flg_NegDsc,0), 
                                   @pc_FlgBlqVerba = Case 
                                                       When ((IsNull(Flg_AcuVrbPos,0) = 0) and (IsNull(Flg_AcuVrbNeg,0) = 0)) then 1 
                                                       Else 0 
                                                     End
                              From dbo.POCOM 
                             Where Id_PolCom = @WIte_IdPolCom 

                            --  politica de comercialização (não alterava preço unitario), somente desconto, e, se estiver configurado para permitir negociação
                            if ((@pc_FlgNegDsc = 1) and (@WTipImpPrcPdv <> 'I'))
                              begin
                                if (@WIte_FlgDscInf = 1) or (@WIte_FlgPrcInf = 1) 
                                  begin
                                    -- variaveis ref. desc. a ser considerado
                                    Set @WPerDscArq = 0
                                    if (@WIte_FlgDscInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R')) and (IsNull(@WIte_PerDscEmbPrc,0) = 0) 
                                      Set @WPerDscArq = @WIte_PerDsc
                            
                                    Set @WPrcUniArq = @WPPrcUni
                                    if (@WIte_FlgPrcInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R')) 
                                      Set @WPrcUniArq = @WIte_PrcUniInf
                            
                                    --  verifica se permite alterar preço da politica
                                    if @WFlgBlqAltPrcPol = 0 
                                      begin
                                        Set @WPPrcUni = @WPrcUniArq
                                        Set @WPerDsc  = @WPerDscArq
                                      end
                                    else
                                      begin
                                        if Round(@WPrcUniArq,2) = Round(@WPPrcUni,2) 
                                          Set @WPerDsc = @WPerDscArq
                                        else
                                          begin
                                            Set @WPrcLiqArq = Round(@WPrcUniArq*(1-@WPerDscArq/100),@pm_QtdDecPrcItePdv)
                                            if @WPPrcUni > @WPrcLiqArq 
                                              Set @WPerDsc = Round((@WPPrcUni-@WPrcLiqArq)*100/@WPPrcUni,2)
                                            else
                                              Set @WPerDsc = @WIte_PerDscEmbPrc
                                          end
                                      end
                            
                                    Set @WPPerDscPrz = @WPerDsc
                                    Set @WPPerDscVis = @WPerDsc
                                  end
                              end  -- if ((@pc_FlgNegDsc = 1) and (@WTipImpPrcPdv <> 'I'))
                          end  -- if @pm_FlgUsaPolComPdv = 1

                        Set @WPCodLot = '*'

                        if @WIte_FatCnvImpFat = 0 
                          Set @WIte_FatCnvImpFat = 1
                       
                        -- estoque fiscal negativo
                        if @WFlgBlqEstFisNeg = 1
                          begin
                            Set @WQtdFisDsp = dbo.FN_SldFiscalDisponPrd(@PCodEstIte,@WIte_CodPrd)
                            if @WIte_QtdPedInf > @WQtdFisDsp
                              begin
                                if @WQtdFisDsp < 0 Set @WQtdFisDsp = 0
                                Set @WIte_QtdPedInf = @WQtdFisDsp
                              end
                          end
                       
                        if @WPFatCnvImpFat <> @WIte_FatCnvImpFat
                          Set @WPFatCnvImpFat = @WIte_FatCnvImpFat   -- em 23/08/2020

                        Set @WPQtdImpFat = Round((@WIte_QtdPedInf + @WIte_QtdBonInf)/@WIte_FatCnvImpFat,0)
                        Set @WPPrcUniImpFat = @WPPrcUni * @WIte_FatCnvImpFat
                     
                        Set @WPPrcUniPde = @WPPrcUni
                        if @WTipPrz = 'L' 
                          Set @WPPerDscPde = @WPPerDscLin  -- Per_Desconto
                        else
                          Set @WPPerDscPde = @WPPerDscPrz  -- Per_Descon

                        Set @WPCodPrjPde = @WIte_CodProjeto
                        Set @WPNumSeqPdc = @WIte_NumSeqPdc
                        Set @WPTipSai = @WIte_TipSai
                     
                        --  calcfields 
                        Set @WPC_PrcUni = @WPPrcUni
                        if @WTipPrz = 'L'
                          Set @WPC_PerDscIte = @WPPerDscLin
                        else
                          Set @WPC_PerDscIte = @WPPerDscPrz
                     
                        --  calcula preco unitario liquido
                        Set @WPPrcUniLiqPdv = @WPPrcUni*(1-@WPC_PerDscIte/100)
                        
                        Set @WPC_VlrDesconto = 0
                        if @WPFlgEmbDscPrc = 1
                          begin
                            if @WTipPrz = 'L'
                              Set @WPC_PrcUni = @WPPrcUni*(1-@WPPerDscLin/100)
                            else
                              Set @WPC_PrcUni = @WPPrcUni*(1-@WPPerDscPrz/100)
                        
                            Set @WPC_PerDscIte = 0
                          end
                        
                        Set @WPC_VlrDesconto = Round(@WIte_QtdPedInf*@WPC_PrcUni,2) - Round(@WIte_QtdPedInf*@WPC_PrcUni*(1-@WPC_PerDscIte/100),2)
                        
                        Set @WPC_PrcTotal = Round(@WIte_QtdPedInf*@WPC_PrcUni,2) - @WPC_VlrDesconto
                        
                        Set @WFlgSnhEsp = 0 
                        Set @WNomUsuSnhEsp = ''
                        Set @WFlgCriVrb = 0        -- coloquei

                       -- preço mínimo
                        Set @WPPrcMin = 0   -- calcula na critica
                        Set @WPVlrVrbDis = 0 -- calcula na critica

						-- tem que informar atual: @WPPrcPolCom, @WPQtdPrzPolCom, @WPPerDscPolCom, @WPPerDscVisPolCom  (InfoDefault)

                        --  normaliza campos: @WTipImpPrcPdv = (A)ceita, (R)ejeita, (I)gnora 
                        if @WTipImpPrcPdv = 'A'
                          Set @WFlgBlqCriConCom = 1
                        else
                          Set @WFlgBlqCriConCom = 0

                        if ((@WIte_FlgPrcInf = 1) or (@WIte_FlgDscInf = 1)) and 
                           (@WTipImpPrcPdv = 'A') 
                          Set @WFlgBlqCriPrcVen = 1 
                        else
                          Set @WFlgBlqCriPrcVen = 0

                        Exec PR_CriticaItemPDVIT @pm_FlgUsaPolComPdv, @PCodEstIte, @PNumPdv, @WIte_CodPrd, @WPTipSai,
                                                 @WIte_IdPolCom, @WIte_QtdPedInf output, @WIte_QtdBonInf, @WPQtdPrzMax output,
                                                 @WPPrcUni, @WPPerDscLin output, @WPPerDscPrz output, @WPPerDscVis output, 
                                                 @WPFatCnvImpFat, @WPQtdImpFat output, @WPPrcUniImpFat,
                                                 @WPPrcTabBru, @WPPrcTab output, @WPPrcUniLiqPer output, @WPPrcMin,
                                                 @WPCodKitPrm, @WPPrcCusMinComMarkup, 
                                                 @WPPrcPolCom output, @WPQtdPrzPolCom output, @WPPerDscPolCom output, @WPPerDscVisPolCom output, 
                                                 @WPFlgVerba output, @WPVlrVrbDis, @WFlgSnhEsp, @WNomUsuSnhEsp,
                                                 @WIte_FlgBlqQtdPar, @WFlgBlqCriConCom, @WFlgBlqCriPrcVen, @WFlgCriVrb, False,
                                                 @WIte_QtdSolInf output, @WIte_QtdAceInf output, @WPFlgPolPrm output, @WPCodPromoc output, 
                                                 @WPCodRej output, @WPDesMsg output, @WPCmp output, @WPNomUsuDbq output, @WPDesMsgDbq  output

                    --Set @WIte_QtdPedInf = @WIte_QtdPed*@WIte_FatAprPad
                    --Set @WIte_QtdBonInf = @WIte_QtdBon*@WIte_FatAprPad
                    --Set @WIte_PrcUniInf = @WIte_PrcUni/@WIte_FatAprPad
---------------------------------------------------------------------------------------------------

                        if (@WPDesMsg = '') or (Substring(@WPCodRej,1,2) = 'PZ')  
                          begin
                            Set @WPCodRej = ''
                            Set @WPDesMsg = ''
                          end
                        else
                          begin
                            Set @WIte_QtdPedInf = 0
                            Set @WIte_QtdBonInf = 0
                          end

                        Insert Into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai)
                          Values (@PCodEstIte, @PNumPdv, @WIte_CodPrd, @WPCodLot, @WPTipSai)

                        Update PDVIT
                           Set Num_SeqDig = @WNumSeqIte,
                               Qtd_Pedido = @WIte_QtdPedInf, 
                               Qtd_Bonificacao = @WIte_QtdBonInf, 
							   Id_PolCom = @WIte_IdPolCom, 
							   Loc_Fisica = @WPLocFis,   
							   Cod_Fabricante = @WPCodFab,
                               Qtd_PrzMax = @WPQtdPrzMax, 
							   Prc_Fabric = @WPPrcFab, 
							   Prc_MaxCon = @WPPrcMaxCon, 
							   Prc_RefFpb = @WPPrcRefFpb,   
							   Prc_Tabela = @WPPrcTab, 
							   Prc_TabBru = @WPPrcTabBru, 
                               Prc_Unitario = @WPPrcUni, 
							   Per_Desconto = @WPPerDscLin, 
							   Per_Descon = @WPPerDscPrz,   
							   Per_DscVis = @WPPerDscVis,  
							   Flg_Verba = @WPFlgVerba,  
							   Prc_CusMinComMarkup = @WPPrcCusMinComMarkup, 
                               Qtd_PrzPolCom = @WPQtdPrzPolCom, 
							   Prc_PolCom = @WPPrcPolCom, 
							   Per_DscPolCom = @WPPerDscPolCom, 
							   Per_DscVisPolCom = @WPPerDscVisPolCom,  
							   Cod_KitPrm = @WPCodKitPrm,    
							   Cod_Promocao = @WPCodPromoc,
                               Fat_CnvImpFat = @WIte_FatCnvImpFat, 
							   Qtd_ImpFat = @WPQtdImpFat, 
							   Prc_UniImpFat = @WPPrcUniImpFat, 
							   Des_UnvImpFat = @WIte_DesUnvImpFat, 
							   Des_AprImpFat = @WIte_DesAprImpFat, 
                               Prc_UniPde = @WPPrcUniPde, 
							   Per_DscPde = @WPPerDscPde, 
							   Cod_PrjPde = @WPCodPrjPde, 
							   Num_SeqPdc = @WPNumSeqPdc, 
                               Flg_PrcUniDsc = @WPFlgEmbDscPrc, 
							   C_PrcUni = @WPC_PrcUni, 
							   C_PerDscIte = @WPC_PerDscIte, 
							   C_VlrDesconto = @WPC_VlrDesconto, 
                               C_PrcTotal = @WPC_PrcTotal, 
							   Prc_UniLiqPer = @WPPrcUniLiqPer, 
							   Qtd_Solicitado = @WIte_QtdSolInf, 
							   Qtd_Acerto = @WIte_QtdAceInf,
                               Flg_PolPrm = @WPFlgPolPrm, 
							   Cod_MtvRej = @WPCodRej, 
							   Des_MtvRej = Substring(@WPDesMsg,1,80), 
							   Nom_UsuDesbloq = Substring(@WPNomUsuDbq,1,15), 
							   Des_MsgDesbloq = Substring(@WPDesMsgDbq,1,60)
                         Where Cod_Estabe  = @PCodEstIte
                           And Cod_Pedido  = @PNumPdv 
                           And Cod_Produto = @WIte_CodPrd 
                           And Cod_Lote    = @WPCodLot 
                           And Tip_Sai     = @WPTipSai

                        Set @WNumSeqIte = @WNumSeqIte + 1  
                      end  -- if @WPFlgAchou = 1
                  end  
                else
                  begin
                    -- acumula em PDVIT
                    Update dbo.PDVIT 
                       Set Qtd_Pedido = Qtd_Pedido + @WIte_QtdPedInf
                     Where Cod_Estabe = @PCodEstIte
                       And Cod_Pedido = @PNumPdv
                       And Cod_Produto = @WIte_CodPrd
                       And Cod_Lote = @pvit_CodLot
                  end
              end  --if @WIte_CodPrd > 0
            else
              begin
                Set @WQtdPedAte = 0
              end

            -- aquix WQtdPedAte converter WIte_PrcUni
            if @WIte_PrcUni = 0
              Set @WIte_PrcUni = Round((@WIte_PrcUniInf*@WIte_FatAprPad),@pm_QtdDecPrcItePdv)

            if (@WIte_PrcUniImpFat = 0) and (@WIte_FatCnvImpFat > 1) 
              Set @WIte_PrcUniImpFat = Round((@WIte_PrcUniInf*@WIte_FatAprPad),@pm_QtdDecPrcItePdv) * @WIte_FatCnvImpFat

            Set @WQtdPedAte = @WQtdPedAte/@WIte_FatAprPad

/*
            -- Atualizar PVMIT.Cod_MtvRej : @WIte_CodRej
            Update dbo.PVMIT
               Set Qtd_Atendi    = @WQtdPedAte,
                   Prc_Unitario  = @WIte_PrcUni,
                   Per_Desconto  = @WIte_PerDsc,
                   Cod_MtvRej    = @WIte_CodRej,
                   Cod_MtvRejOri = @WIte_CodRej,
                   Fat_CnvImpFat = @WIte_FatCnvImpFat,
                   Fat_AprPad    = @WIte_FatAprPad,
                   Des_UnvImpFat = @WIte_DesUnvImpFat,
                   Des_AprImpFat = @WIte_DesAprImpFat,
                   Prc_UniImpFat = @WIte_PrcUniImpFat
             Where Cod_Estabe = @PCodEstabe
               And Cod_Layout = @PCodLayout
               And Num_Cnpj   = @PNumCnpj
               And Cod_PedCli = @PCodPedCli
               And Num_Desdob = @PNumDesdob
               And Cod_PrdCli = @WIte_CodPrdArq
*/
            Delete 
              From @tb_PVMIT 
             Where Chave = @WIte_Chave
          end

      end  

------------------------------------------------------------------------------------------------------------------------------------------------------

    -- Finaliza
    Update dbo.PDVCB
       Set Status2 = 'A',
           ID_PVMCB = @PID_PVMCB,
		   Cod_OrigemPdv = dbo.PVMCB.Cod_OrigemPdv
	from dbo.PDVCB
	inner join dbo.PVMCB on dbo.PVMCB.ID_PVMCB = dbo.PDVCB.ID_PVMCB
    Where dbo.PDVCB.Cod_Estabe = @PCodEstIte
      And dbo.PDVCB.Numero = @PNumPdv
      And dbo.PDVCB.Status2 = 'X'

    Update it
       Set it.Qtd_Atendi    = ipv.QtdPdv,
		   it.Prc_Unitario  = ipv.PrcUnitar,
		   it.Per_Desconto  = ipv.PerDescon,
		   it.Fat_CnvImpFat = ipv.FatCnvImp,
		   it.Fat_AprPad    = ipv.FatAprPad,
		   it.Des_UnvImpFat = ipv.DesUnvImp,
		   it.Des_AprImpFat = ipv.DesAprImp,
		   it.Prc_UniImpFat = ipv.PrcUniImp
      From dbo.PVMCB cb
           Inner Join dbo.PVMIT it on cb.ID_PVMCB = it.ID_PVMCB and 
	                                  it.Cod_Estabe = @PCodEstIte
           Inner Join (Select dbo.PDVIT.Cod_Estabe, 
		                      dbo.PDVCB.ID_PVMCB,
		                      Cod_Pedido, 
							  Cod_Produto,
                              QtdPdv = sum(Qtd_Pedido+Qtd_Bonificacao),
                              PrcUnitar = max(Prc_Unitario),
                              PerDescon = max(Per_Desconto),
                              FatCnvImp = max(Fat_CnvImpFat),
                              FatAPrPad = @WIte_FatAprPad,
                              DesUnvImp = max(Des_UnvImpFat),
                              DesAPrImp = max(Des_AprImpFat),
                              PrcUniImp = max(Prc_UniImpFat)
                         From dbo.PDVIT
						 inner join dbo.PDVCB on dbo.PDVCB.Cod_Estabe = dbo.PDVIT.Cod_Estabe and dbo.PDVCB.Numero = dbo.PDVIT.Cod_Pedido
                        Where dbo.PDVIT.Cod_Estabe = @PCodEstIte
                          And Cod_Pedido = @PNumPdv
                        Group by dbo.PDVIT.Cod_Estabe, dbo.PDVCB.ID_PVMCB, Cod_Pedido, Cod_Produto) ipv on it.Cod_Estabe = ipv.Cod_Estabe and 
                                                                             cb.ID_PVMCB = ipv.ID_PVMCB and 
                                                                             it.Cod_Produto = ipv.Cod_Produto 
     Where cb.ID_PVMCB = @PID_PVMCB

    -- PVMIT.Qtd_Atendi deve está alimentado antes do cálculo do total
    declare @VlrTotal numeric(18,8)
	set @VlrTotal = 
			Round((Select Sum(Round(Qtd_Atendi*Prc_Unitario*(1-IsNull(Per_Desconto,0)/100),2)) 
				   From dbo.PVMIT 
				   Where Cod_Estabe = @PCodEstIte
					 And ID_PVMCB = @PID_PVMCB),2)
	set @VlrTotal = ISNULL(@VlrTotal, 0)

    Update dbo.PVMCB
       Set Vlr_Total = Vlr_Total + @VlrTotal
    Where Cod_EstPad = @PCodEstPad
      And ID_PVMCB = @PID_PVMCB
      And ISNULL(Vlr_Total, 0) <> @VlrTotal

    if @@trancount > 0
      COMMIT TRANSACTION
end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraPedidoVendaCTRCB]
@PCodEstabe int, 
@PCodContra int, 
@PNumSequen int,  -- 0: não foi gerado CTPDC CTPDI
@PCodClient int,  -- 0: pega cliente do contrato
@PNumPdv int output,
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Set @PNumPdv = 0
Set @PMsgErr = ''

if @PNumSequen = 0
  begin
    Set @PNumSequen = 1
    if not Exists(Select 1 From CTPDC Where Cod_Estabe = @PCodEstabe And Cod_Contrato = @PCodContra And Num_Sequencia = @PNumSequen) and
       Exists(Select 1 From CTRCB Where Cod_Estabe = @PCodEstabe And Cod_Contrato = @PCodContra And ((Sta_Contrato = '1')  or (Sta_Contrato = '2'))) and
	   Exists(Select 1 From CTRIT it Inner JOIN PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produto = pr.Cod_Produt 
               Where it.Cod_Estabe = @PCodEstabe And it.Cod_Contrato = @PCodContra)
      begin
        -- inclui CTPDC
        Insert Into CTPDC (Cod_Estabe, Cod_Contrato, Num_Sequencia, Sta_CtrPed)
                   Values (@PCodEstabe, @PCodContra, @PNumSequen, '0')

        -- inclui CTPDI
        Insert Into CTPDI (Cod_Estabe, Cod_Contrato, Num_Sequencia, Cod_Produto, Qtd_Credito, Fat_CnvApr,
                           Qtd_Pedido, Prc_Unitario, Per_Desconto, Num_ItePrp, Num_SubIte)	 
          Select it.Cod_Estabe, it.Cod_Contrato, @PNumSequen, it.Cod_Produto,  it.Qtd_Credito, it.Fat_CnvApr,
                 QtdPed = Case When it.Qtd_Pedido > dbo.FN_EstoqueDisponivelPrd(pr.Cod_Estabe,pr.Cod_Produt) then dbo.FN_EstoqueDisponivelPrd(pr.Cod_Estabe,pr.Cod_Produt) Else it.Qtd_Pedido End, 
                 it.Prc_Unitario, it.Per_Desconto, it.Num_ItePrp, it.Num_SubIte
            From CTRIT it
                 Inner JOIN PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produto = pr.Cod_Produt
           Where it.Cod_Estabe = @PCodEstabe
             And it.Cod_Contrato = @PCodContra
             And dbo.FN_EstoqueDisponivelPrd(pr.Cod_Estabe,pr.Cod_Produt) > 0

          -- atualiza status
          if Exists(Select 1 From CTPDI Where Cod_Estabe = @PCodEstabe and Cod_Contrato = @PCodContra and Num_Sequencia = @PNumSequen)
            Update CTPDC
               Set Sta_CtrPed = '1'
             Where Cod_Estabe = @PCodEstabe and Cod_Contrato = @PCodContra and Num_Sequencia = @PNumSequen
               And Sta_CtrPed = '0'
      end
  end

if @PCodClient = 0
  Set @PCodClient = (Select Cod_Cliente from CTRCB Where Cod_Estabe = @PCodEstabe And Cod_Contrato = @PCodContra)

if not Exists(Select 1 From CTRCB ct
                Inner Join CLIEN cl on ct.Cod_Cliente = cl.Codigo
              Where ct.Cod_Estabe = @PCodEstabe And ct.Cod_Contrato = @PCodContra) 
  begin
   RAISERROR('Cliente inválido',16,1)
   Return
  end
else
if Exists(Select 1 From CTPDC 
          Where Cod_Estabe = @PCodEstabe And Cod_Contrato = @PCodContra And Num_Sequencia = @PNumSequen And Sta_CtrPed <> '1')
  begin
    RAISERROR('Contrato não foi fechado',16,1)
    Return
  end
else
if Exists(Select 1 From CTRCB ct
           Inner Join CTPDC dt on ct.Cod_Estabe = dt.Cod_Estabe and ct.Cod_Contrato = dt.Cod_Contrato and dt.Num_Sequencia = @PNumSequen
          Where ct.Cod_Estabe = @PCodEstabe And ct.Cod_Contrato = @PCodContra And dt.Sta_CtrPed = '1') and
   Exists(Select 1 From CTPDI 
           Where Cod_Estabe = @PCodEstabe And Cod_Contrato = @PCodContra And Num_Sequencia = @PNumSequen)
  begin
    BEGIN TRANSACTION

      Declare @ct_CodVended int,
              @ct_CodOperad int,
              @ct_CodDigita int,
              @ct_PerComVnd numeric(8,4),
              @ct_NumContra varchar(15),
              @dt_IdeNotEmp varchar(20),

              @pm_FlgUsaPolComPdv bit,
              @pm_FlgAltUnvItePdv bit, 
              @pm_FlgRegDscCliItePdv bit,

              @WTipFat varchar(3),
              @WFlgUsaWms bit,
              @WFlgBlqWms bit, 
              @WFlgBlqPol bit,
              @WIdPolCom int, 
              @WCodTabPrz int, 
              @WCodLayout int,
              @WFlgBlqDscAutIte bit,
              @WFlgCriVrb bit,
              @WFlgBlqQtdPar bit, 

              @WFlgSnhEsp bit,          
              @WFlgNaoCriConCom bit,    
              @WFlgBlqCriPrcVen bit,
              @WNomUsuSnhEsp varchar(35)

      Select @pm_FlgAltUnvItePdv = IsNull(FlgAltUnvItePdv,0), 
             @pm_FlgRegDscCliItePdv = IsNull(FlgRegDscCliItePdv,0),
             @pm_FlgUsaPolComPdv = IsNull(FlgUsaPolComPdv,0)
        From PARAM
       Where Cod_Estabe = @PCodEstabe

      Select @ct_CodVended = ct.Cod_Vendedor, 
             @ct_CodOperad = ct.Cod_Operador, 
             @ct_CodDigita = ct.Cod_Digitador, 
             @ct_PerComVnd = ct.Per_ComVnd, 
             @ct_NumContra = ct.Num_Contrato, 
             @dt_IdeNotEmp = dt.Ide_NotEmp
	    From CTRCB ct
             Inner Join CTPDC dt on ct.Cod_Estabe = dt.Cod_Estabe and ct.Cod_Contrato = dt.Cod_Contrato and dt.Num_Sequencia = @PNumSequen
       Where ct.Cod_Estabe = @PCodEstabe 
         And ct.Cod_Contrato = @PCodContra
         And dt.Sta_CtrPed = '1'

      -- WMS
      Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
                                                HASHBYTES('MD5',(Select Num_Cnpj From ESTAB Where Cod_Estabe = @PCodEstabe))))

      Set @WFlgBlqWms = 0
      Set @WFlgBlqPol = 0
      Set @WCodTabPrz = 0
      Set @WCodLayout = 0

      Set @WTipFat = 'FAT'
      Set @WIdPolCom = 0 

      Exec PR_IncluiPDVCB 'P', @PCodEstabe, @PNumPdv output, 'H', @PCodClient, @WFlgUsaWms, @WTipFat,
                          @ct_CodVended, @ct_CodOperad, @ct_CodDigita, @WIdPolCom, @WCodTabPrz, @WCodLayout,
                          @WFlgBlqWms, @WFlgBlqPol, @PMsgErr output, 0

      Update pv
         Set pv.Status2 = 'X',    
             pv.Cod_OrigemPdv = 'HL',  -- ????  Hospitalar / Linear
             pv.Tip_Vencimento = '',
             pv.Cod_Contrato = @PCodContra,
             pv.Num_SequenciaCtr = @PNumSequen,
             pv.Ide_NotEmp = @dt_IdeNotEmp,
             pv.Per_ComVnd = @ct_PerComVnd,
             pv.Ide_Contra = @ct_NumContra,
             pv.Cod_PedCmpCli = @ct_NumContra
        From PDVCB pv
       Where pv.Cod_Estabe = @PCodEstabe
         And pv.Numero = @PNumPdv

      if @PNumPdv > 0
        begin
          Declare @WPFlgAchou bit,
                  @WPTipSai varchar(1),
                  @WPCodLot varchar(20),
                  @WPLocFis varchar(15),
                  @WPCodFab int,
                  @WPFatCnvImpFat int,
                  @WPPrcFab numeric(18,8),
                  @WPPrcMaxCon numeric(18,8),
                  @WPPrcRefFpb numeric(18,8),
                  @WPPrcCusMinComMarkup numeric(18,8),
                  @WPPrcTab numeric(18,8),
                  @WPPrcTabBru numeric(18,8),
                  @WPPrcUni numeric(18,8),
                  @WPPrcUniLiqPer numeric(18,8),
                  @WPFlgEmbDscPrc bit,
                  @WPPerDscLin numeric(18,8),
                  @WPPerDscPrz numeric(18,8),
                  @WPPerDscVis numeric(18,8),
                  @WPQtdPrzMax int,
                  @WPCodRej varchar(3),
                  @WPDesMsg varchar(80),
                  @WPCmp varchar(20),
                  @WPNomUsuDbq varchar(35),
                  @WPDesMsgDbq varchar(60),

                  @cr_NumSeq int,
                  @cr_CodPrd int,
                  @cr_QtdPed int, 
                  @cr_PrcUni numeric(18,8), 
                  @cr_PerDsc numeric(8,4), 
                  @cr_FatCnvApr int,
                  @cr_QtdImpFat numeric(18,4), 
                  @cr_PrcUniImp numeric(18,8), 
                  @cr_DesUnvImpFat varchar(3), 
                  @cr_DesAprImpFat varchar(12),
                  @cr_CodRej varchar(3),
                  @cr_DesMsg varchar(80),
                  @WIte_QtdSolInf int,
                  @WIte_QtdPedInf int, 
                  @WIte_QtdBonInf int,
                  @WIte_IdPolCom int,
      
                  @WPPerDscPolCom numeric(18,8),
                  @WPPerDscVisPolCom numeric(18,8),
                  @WPPrcPolCom numeric(18,8),
                  @WPQtdPrzPolCom int,
                  @WPCodKitPrm int,
                  @WPCodPromoc int,
                  @WPFlgVerba bit,
                  @WPFlgPolPrm bit,

                  @WPC_PrcUni numeric(18,8),
                  @WPC_PerDscIte numeric(18,8),
                  @WPPrcUniLiqPdv numeric(18,8),
                  @WPC_VlrDesconto numeric(18,8),
                  @WPC_PrcTotal numeric(18,8)

----------------------------------------------------------------------------------------

          Declare PDVIT_Cr Cursor Local Fast_Forward For

            Select NumSeq = row_number() over(Order by it.Num_Sequencia), it.Cod_Produto,
                   QtdPed = Case When it.Fat_cnvApr > 0 then it.Qtd_Pedido*it.Fat_CnvApr Else it.Qtd_Pedido End,  
				   PrcUni = Case When it.Fat_cnvApr > 0 then it.Prc_Unitario/it.Fat_CnvApr Else it.Prc_Unitario End, 
				   it.Per_Desconto, IsNull(it.Fat_CnvApr,1),
				   QtdImpFat = it.Qtd_Pedido, PrcUniImp = it.Prc_Unitario, DesUnvImpFat = c.Des_Und, 
                   DesAprImpFat = Case 
                                    When (@pm_FlgAltUnvItePdv = 0) then 'C/'+cast(c.Qtd_AprCtr as varchar)+' '+c.Des_UndVen
                                    Else Case
                                           When IsNull(ap.Cod_Apr,0) > 0 then ap.Des_Apr
                                           Else p.Aprese									   									 
                                         End
                                  End
              From CTPDI it
                   Inner Join CTRIT c  on (it.Cod_Estabe = c.Cod_Estabe and it.Cod_Contrato = c.Cod_Contrato and it.Cod_Produto = c.Cod_Produto)
                   Inner Join PRODU p  on (it.Cod_Produto = p.Codigo)
                   Left  Join PRXAP ap on (c.Cod_Produto = ap.Cod_Produt and c.Cod_Apr = ap.Cod_Apr)
             Where it.Cod_Estabe = @PCodEstabe 
               And it.Cod_Contrato = @PCodContra 
               And it.Num_Sequencia = @PNumSequen

          Open PDVIT_Cr
          Fetch Next From PDVIT_Cr Into @cr_NumSeq, @cr_CodPrd, @cr_QtdPed, @cr_PrcUni, @cr_PerDsc, @cr_FatCnvApr,
                                        @cr_QtdImpFat, @cr_PrcUniImp, @cr_DesUnvImpFat, @cr_DesAprImpFat
          While @@FETCH_STATUS = 0
            begin

              Set @WIte_QtdPedInf = @cr_QtdPed
              Set @WIte_QtdBonInf = 0
              Set @WIte_IdPolcom  = 0   -- ???????

              Set @WFlgBlqDscAutIte = 0

              Exec PR_InfoDefaultPDVIT @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @cr_CodPrd, 
                                       @WIte_QtdPedInf, @WIte_QtdBonInf, @WIte_IdPolCom output, @WFlgBlqDscAutIte,
                                       @WPFlgAchou output,
                                       @WPLocFis output,
                                       @WPCodFab output,
                                       @WPPrcFab output,
                                       @WPPrcMaxCon output,
                                       @WPPrcRefFpb output,
                                       @WPPrcTab output,
                                       @WPPrcTabBru output,
                                       @WPFatCnvImpFat output,     
                                       @WPPrcUni output,
                                       @WPPrcCusMinComMarkup output,
                                       @WPPerDscPolCom output,
                                       @WPPerDscVisPolCom output,
                                       @WPPrcPolCom output,
                                       @WPQtdPrzPolCom output,
                                       @WPFlgVerba output,
                                       @WPFlgPolPrm output,
                                       @WPCodKitPrm output,
                                       @WPCodPromoc output,
                                       @WPFlgEmbDscPrc output, 
                                       @WPQtdPrzMax output,
                                       @WPPerDscLin output,
                                       @WPPerDscPrz output,
                                       @WPPerDscVis output,
                                       @WPPrcUniLiqPer output

              if @WPFlgAchou = 1
                begin

                  Set @WPPrcUni       = @cr_PrcUni
                  Set @WPPerDscLin    = @cr_PerDsc  -- ????
                  Set @WPPerDscPrz    = @cr_PerDsc  -- ????
                  Set @WPPerDscVis    = @cr_PerDsc  -- ???
                  Set @WPCodLot       = '*'
                  Set @WPTipSai       = ''
                  Set @WPFatCnvImpFat = @cr_FatCnvApr

----------------------------------------------------------------------
                  --  calcfields 
                  Set @WPC_PrcUni = @WPPrcUni
                  Set @WPC_PerDscIte = @cr_PerDsc
                     
                  --  calcula preco unitario liquido
                  Set @WPPrcUniLiqPdv = @WPPrcUni*(1-@WPC_PerDscIte/100)
                     
                  Set @WPC_VlrDesconto = 0
                  if @WPFlgEmbDscPrc = 1
                    begin
                      Set @WPC_PrcUni = @WPPrcUni*(1-@WPC_PerDscIte/100)
                      Set @WPC_PerDscIte = 0
                    end
                     
                  Set @WPC_VlrDesconto = Round(@WIte_QtdPedInf*@WPC_PrcUni,2) - Round(@WIte_QtdPedInf*@WPC_PrcUni*(1-@WPC_PerDscIte/100),2)
                  Set @WPC_PrcTotal = Round(@WIte_QtdPedInf*@WPC_PrcUni,2) - @WPC_VlrDesconto

                  Set @WFlgSnhEsp = 0 
                  Set @WNomUsuSnhEsp = ''
                  Set @WFlgNaoCriConCom = 0  -- coloquei
                  Set @WFlgBlqCriPrcVen = 0  -- coloquei
                  Set @WFlgCriVrb = 0        -- coloquei
                  Set @WFlgBlqQtdPar = 0

                  Exec PR_CriticaItemPDV @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @cr_CodPrd, 
                                         @WIte_IdPolCom, @WIte_QtdPedInf, @WIte_QtdBonInf, @WPTipSai, @WPQtdPrzMax,
                                         @WPPrcUni, @WPPerDscVis, @WPPerDscPrz, @cr_QtdImpFat, @cr_PrcUniImp,
                                         @WPCodKitPrm, @WPPerDscPolCom, @WPPerDscVisPolCom, @WPPrcPolCom,
                                         @WPPrcUniLiqPdv, @WPPrcCusMinComMarkup, @WPPrcUniLiqPer, @WPFlgVerba,
                                         @WFlgSnhEsp, @WNomUsuSnhEsp, @WFlgNaoCriConCom, @WFlgBlqCriPrcVen, @WFlgCriVrb, @WFlgBlqQtdPar,
                                         @WPCodRej output, @WPDesMsg output, @WPCmp output, @WPNomUsuDbq output, @WPDesMsgDbq output

                  Set @WIte_QtdSolInf = @WIte_QtdPedInf + @WIte_QtdBonInf
/*
                  if (@WPDesMsg = '') or (Substring(@WPCodRej,1,2) = 'PZ')  
                    begin
                      Set @WPCodRej = ''
                      Set @WPDesMsg = ''
                    end
                  else
                    begin
                      Set @WIte_QtdPedInf = 0
                      Set @WIte_QtdBonInf = 0
                    end
*/
                  Set @WPCodRej = @cr_CodRej
                  Set @WPDesMsg = @cr_DesMsg

                  Insert Into PDVIT (
                          Cod_Estabe, Num_SeqDig, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai,
                          Qtd_Pedido, Qtd_Bonificacao, Id_PolCom, Loc_Fisica, Cod_Fabricante, 
                          Qtd_PrzMax, Prc_Fabric, Prc_MaxCon, Prc_RefFpb, Prc_Tabela, Prc_TabBru, 
                          Prc_Unitario, Per_Desconto, Per_Descon, Per_DscVis, Flg_Verba, Prc_CusMinComMarkup,
                          Qtd_PrzPolCom, Prc_PolCom, Per_DscPolCom, Per_DscVisPolCom, Cod_KitPrm, Cod_Promocao,  
                          Fat_CnvImpFat, Qtd_ImpFat, Prc_UniImpFat, Des_UnvImpFat, Des_AprImpFat, 
                          Prc_UniPde, Per_DscPde, Cod_PrjPde, Num_SeqPdc,  
                          Flg_PrcUniDsc, C_PrcUni, C_PerDscIte, C_VlrDesconto, 
                          C_PrcTotal, Prc_UniLiqPer, Qtd_Solicitado, Qtd_Acerto, Flg_PolPrm, 
                          Cod_MtvRej, Des_MtvRej, Nom_UsuDesbloq, Des_MsgDesbloq) 
                      Values (  
                          @PCodEstabe, @cr_NumSeq, @PNumPdv, @cr_CodPrd, @WPCodLot, @WPTipSai,
                          @WIte_QtdPedInf, @WIte_QtdBonInf, @WIte_IdPolCom, @WPLocFis, @WPCodFab,
                          @WPQtdPrzMax, @WPPrcFab, @WPPrcMaxCon, @WPPrcRefFpb, @WPPrcTab, @WPPrcTabBru, 
                          @WPPrcUni, @WPPerDscLin, @WPPerDscPrz, @WPPerDscVis, @WPFlgVerba, @WPPrcCusMinComMarkup,  
                          @WPQtdPrzPolCom, @WPPrcPolCom, @WPPerDscPolCom, @WPPerDscVisPolCom, @WPCodKitPrm, @WPCodPromoc,  
                          @cr_FatCnvApr, @cr_QtdImpFat, @cr_PrcUniImp, @cr_DesUnvImpFat, @cr_DesAprImpFat,
                          0, 0, '', '', 
                          @WPFlgEmbDscPrc, @WPC_PrcUni, @WPC_PerDscIte, @WPC_VlrDesconto, 
                          @WPC_PrcTotal, @WPPrcUniLiqPer, @WIte_QtdSolInf, 0, @WPFlgPolPrm, 
                          @WPCodRej, Substring(@WPDesMsg,1,40), Substring(@WPNomUsuDbq,1,15), Substring(@WPDesMsgDbq,1,60))


                  --  atualiza motivo qdo for o caso
                  Update it 
                     Set it.Cod_MtvRej = Case 
                                           When it.Qtd_Pedido > 0 then 'ES-' 
                                           Else 'ES0'
                                         End 
                    From PDVIT it 
                   Where it.Cod_Estabe = @PCodEstabe
                     And it.Cod_Pedido = @PNumPdv
                     And it.Cod_Produto = @cr_CodPrd 
                     And it.Cod_Lote = @WPCodLot
                     And it.Tip_Sai = @WPTipSai
                     And it.Qtd_Pedido < it.Qtd_Solicitado 
                     And IsNull(it.Cod_MtvRej,'') = '' 

                end  -- if @WPFlgAchou = 1

              Fetch Next From PDVIT_Cr Into @cr_NumSeq, @cr_CodPrd, @cr_QtdPed, @cr_PrcUni, @cr_PerDsc, @cr_FatCnvApr,
                                            @cr_QtdImpFat, @cr_PrcUniImp, @cr_DesUnvImpFat, @cr_DesAprImpFat

            end
          Close PDVIT_Cr
          Deallocate PDVIT_Cr

          Insert Into ITDES (Cod_Estabe, Num_Pedido, Cod_Produt, Des_PrdDet, Des_UndVen)
            Select @PCodEstabe, @PNumPdv, c.Cod_Produto, c.Des_IteCtr, it.Des_UnvImpFat
              From CTRIT c
                   Inner Join PDVIT it on c.Cod_Estabe = it.Cod_Estabe and it.Cod_Pedido = @PNumPdv and c.Cod_Produto = it.Cod_Produto
             Where c.Cod_Estabe = @PCodEstabe 
               And c.Cod_Contrato = @PCodContra 
               And c.Des_IteCtr is not null
               And not Exists(Select 1 From ITDES id 
                 			   Where it.Cod_Estabe = id.Cod_Estabe and it.Cod_Pedido = id.Num_Pedido and it.Cod_Produto = id.Cod_Produt)
               and @pm_FlgRegDscCliItePdv = 1

          Update PDVCB 
             Set Status2 = 'A'
           Where Cod_Estabe = @PCodEstabe
             And Numero = @PNumPdv

          Update CTPDC
             Set Sta_CtrPed = '2',
                 Num_PedVen = @PNumPdv
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Contrato = @PCodContra 
             And Num_Sequencia = @PNumSequen

        end  -- if @PNumPdv > 0

    COMMIT TRANSACTION
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraPedidoVendaOPME]
@PCodEstabe int, 
@PIdOpmcb int, 
@PTipOpe varchar(3),
@PNumPdv int output,
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now  smalldatetime = GetDate(),
        @Date smalldatetime = cast(GetDate() as date)

Set @PNumPdv = 0
Set @PMsgErr = ''

if not Exists(Select 1 
                From OPMCB cb
               Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo 
               Where cb.Cod_Estabe = @PCodEstabe 
			     And cb.ID_Opmcb = @PIdOpmcb)
  Set @PMsgErr = 'Cliente inválido'
else
if not Exists(Select 1 
              From OPMIT it 
			  Inner Join OPMCB cb on cb.ID_Opmcb = it.ID_Opmcb
              Inner Join PRXES pr on cb.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produto = pr.Cod_Produt 
              Where cb.Cod_Estabe = @PCodEstabe And it.ID_Opmcb = @PIdOpmcb)
  Set @PMsgErr = 'Não existem itens a gerar'
else
  begin

    BEGIN TRANSACTION

    Declare @cb_CodCli int,
            
            @pm_FlgUsaPolComPdv bit,
            @pm_FlgAltUnvItePdv bit, 
            @pm_FlgRegDscCliItePdv bit,

            @WFlgUsaWms bit,
            @WFlgBlqWms bit, 
            @WFlgBlqPol bit,
            @WCodTabPrz int, 
            @WCodLayout int,
            @WFlgBlqDscAutIte bit,
            @WFlgCriVrb bit,
            @WFlgBlqQtdPar bit, 

            @WFlgSnhEsp bit,          
            @WFlgNaoCriConCom bit,    
            @WFlgBlqCriPrcVen bit,
            @WNomUsuSnhEsp varchar(35)

    Select @pm_FlgAltUnvItePdv = IsNull(FlgAltUnvItePdv,0), 
           @pm_FlgRegDscCliItePdv = IsNull(FlgRegDscCliItePdv,0),
           @pm_FlgUsaPolComPdv = IsNull(FlgUsaPolComPdv,0)
      From PARAM
     Where Cod_Estabe = @PCodEstabe

    Select @cb_CodCli = cl.Codigo
	  From OPMCB cb
      Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo 
     Where cb.Cod_Estabe = @PCodEstabe and cb.ID_Opmcb = @PIdOpmcb

    -- WMS
    Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
                                              HASHBYTES('MD5',(Select Num_Cnpj From ESTAB Where Cod_Estabe = @PCodEstabe))))

    Set @WFlgBlqWms = 0
    Set @WFlgBlqPol = 0
    Set @WCodTabPrz = 0
    Set @WCodLayout = 0

    Exec PR_IncluiPDVCB 'P', @PCodEstabe, @PNumPdv output, 'A', @cb_CodCli, @WFlgUsaWms, @PTipOpe,
                        0, 0, 0, 0, @WCodTabPrz, @WCodLayout,
                        @WFlgBlqWms, @WFlgBlqPol, @PMsgErr output, 0

    Update pv
       Set pv.Status2 = 'X',    
           pv.Tip_Vencimento = ''
     From PDVCB pv
    Where pv.Cod_Estabe = @PCodEstabe
      And pv.Numero = @PNumPdv

    if @PNumPdv > 0
      begin
    
        Declare @WPFlgAchou bit,
                @WPTipSai varchar(1),
                @WPCodLot varchar(20),
                @WPLocFis varchar(15),
                @WPCodFab int,
                @WPFatCnvImpFat int,
                @WPPrcFab numeric(18,8),
                @WPPrcMaxCon numeric(18,8),
                @WPPrcRefFpb numeric(18,8),
                @WPPrcCusMinComMarkup numeric(18,8),
                @WPPrcTab numeric(18,8),
                @WPPrcTabBru numeric(18,8),
                @WPPrcUni numeric(18,8),
                @WPPrcUniLiqPer numeric(18,8),
                @WPFlgEmbDscPrc bit,
                @WPPerDscLin numeric(18,8),
                @WPPerDscPrz numeric(18,8),
                @WPPerDscVis numeric(18,8),
                @WPQtdPrzMax int,
                @WPCodRej varchar(3),
                @WPDesMsg varchar(80),
                @WPCmp varchar(20),
                @WPNomUsuDbq varchar(35),
                @WPDesMsgDbq varchar(60),
    
                @cr_NumSeq int,
                @cr_CodPrd int,
                @cr_QtdPed int, 
                @cr_PrcUni numeric(18,8), 
                @cr_PerDsc numeric(8,4), 
                @cr_FatCnvApr int,
                @cr_QtdImpFat numeric(18,4), 
                @cr_PrcUniImp numeric(18,8), 
                @cr_CodRej varchar(3),
                --@cr_DesMsg varchar(80),
                @WIte_QtdSolInf int,
                @WIte_QtdPedInf int, 
                @WIte_QtdBonInf int,
                @WIte_IdPolCom int,
    
                @WPPerDscPolCom numeric(18,8),
                @WPPerDscVisPolCom numeric(18,8),
                @WPPrcPolCom numeric(18,8),
                @WPQtdPrzPolCom int,
                @WPCodKitPrm int,
                @WPCodPromoc int,
                @WPFlgVerba bit,
                @WPFlgPolPrm bit,
    
                @WPC_PrcUni numeric(18,8),
                @WPC_PerDscIte numeric(18,8),
                @WPPrcUniLiqPdv numeric(18,8),
                @WPC_VlrDesconto numeric(18,8),
                @WPC_PrcTotal numeric(18,8)
    
    ----------------------------------------------------------------------------------
    
        Declare PDVIT_Cr Cursor Local Fast_Forward For
    
          Select NumSeq = row_number() over(Order by it.ID_Opmit), 
		         it.Cod_Produto,
                 QtdPed = it.Qtd_Produto,  
                 PrcUni = tp.Val_PrcVen, 
                 Per_Descon = 0, 
                 Fat_CnvApr = 1, 
				 QtdImpFat = it.Qtd_Produto, 
				 PrcUniImp = tp.Val_PrcVen
           From OPMIT it
                Inner join OPMCB cb on cb.ID_Opmcb = it.ID_Opmcb
                Inner Join PRXES p  on cb.Cod_Estabe = p.Cod_Estabe and it.Cod_Produto = p.Cod_Produt
                Inner join CLIEN cl on cl.Codigo = cb.Cod_Cliente
                Inner Join ENXES es on cb.Cod_Estabe = es.Cod_Estabe and cl.Cgc_Cpf = es.Num_CgcCpf and cl.Codigo = es.Cod_Client
                Inner Join TBPRC tb on ((tb.Cod_Estabe = cb.Cod_Estabe) or (tb.Flg_AllEstabe = 1)) and
                                       (tb.Cod_TabPrc = es.Cod_TabPrc)
                Inner join TPXPR tp on tp.Cod_Estabe = tb.Cod_Estabe and tp.Cod_TabPrc = tb.Cod_TabPrc and 
                                       tp.Cod_Produt = it.Cod_Produto
           Where cb.Cod_Estabe = @PCodEstabe 
             And it.ID_Opmcb = @PIdOpmcb
    
        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @cr_NumSeq, @cr_CodPrd, 
                                      @cr_QtdPed, @cr_PrcUni, @cr_PerDsc, 
                                      @cr_FatCnvApr, @cr_QtdImpFat, @cr_PrcUniImp 
        While @@FETCH_STATUS = 0
          begin
            Set @WIte_QtdPedInf = @cr_QtdPed
            Set @WIte_QtdBonInf = 0
            Set @WIte_IdPolcom  = 0   -- ???????

            Set @WFlgBlqDscAutIte = 0
    
            Exec PR_InfoDefaultPDVIT @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @cr_CodPrd, 
                                     @WIte_QtdPedInf, @WIte_QtdBonInf, @WIte_IdPolCom output, @WFlgBlqDscAutIte,
                                     @WPFlgAchou output,
                                     @WPLocFis output,
                                     @WPCodFab output,
                                     @WPPrcFab output,
                                     @WPPrcMaxCon output,
                                     @WPPrcRefFpb output,
                                     @WPPrcTab output,
                                     @WPPrcTabBru output,
                                     @WPFatCnvImpFat output,     
                                     @WPPrcUni output,
                                     @WPPrcCusMinComMarkup output,
                                     @WPPerDscPolCom output,
                                     @WPPerDscVisPolCom output,
                                     @WPPrcPolCom output,
                                     @WPQtdPrzPolCom output,
                                     @WPFlgVerba output,
                                     @WPFlgPolPrm output,
                                     @WPCodKitPrm output,
                                     @WPCodPromoc output,
                                     @WPFlgEmbDscPrc output, 
                                     @WPQtdPrzMax output,
                                     @WPPerDscLin output,
                                     @WPPerDscPrz output,
                                     @WPPerDscVis output,
                                     @WPPrcUniLiqPer output
    
            if @WPFlgAchou = 1
              begin

                if @cr_PrcUni > 0
                  begin
                    Set @WPPrcUni       = @cr_PrcUni
                    Set @WPPerDscLin    = @cr_PerDsc  
                    Set @WPPerDscPrz    = @cr_PerDsc
                    Set @WPPerDscVis    = @cr_PerDsc
                  end

                if IsNull(@cr_PrcUniImp,0) = 0
                  Set @cr_PrcUniImp = @WPPrcUni*@cr_FatCnvApr

                Set @WPCodLot       = '*'
                Set @WPTipSai       = ''
                Set @WPFatCnvImpFat = @cr_FatCnvApr
    
    ----------------------------------------------------------------
                --  calcfields 
                Set @WPC_PrcUni = @WPPrcUni
                Set @WPC_PerDscIte = @cr_PerDsc
                   
                --  calcula preco unitario liquido
                Set @WPPrcUniLiqPdv = @WPPrcUni*(1-@WPC_PerDscIte/100)
                   
                Set @WPC_VlrDesconto = 0
                if @WPFlgEmbDscPrc = 1
                  begin
                    Set @WPC_PrcUni = @WPPrcUni*(1-@WPC_PerDscIte/100)
                    Set @WPC_PerDscIte = 0
                  end
                   
                Set @WPC_VlrDesconto = Round(@WIte_QtdPedInf*@WPC_PrcUni,2) - Round(@WIte_QtdPedInf*@WPC_PrcUni*(1-@WPC_PerDscIte/100),2)
                Set @WPC_PrcTotal = Round(@WIte_QtdPedInf*@WPC_PrcUni,2) - @WPC_VlrDesconto
    
                Set @WFlgSnhEsp = 0 
                Set @WNomUsuSnhEsp = ''
                Set @WFlgNaoCriConCom = 0  -- coloquei
                Set @WFlgBlqCriPrcVen = 0  -- coloquei
                Set @WFlgCriVrb = 0        -- coloquei
                Set @WFlgBlqQtdPar = 0
    
                Exec PR_CriticaItemPDV @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @cr_CodPrd, 
                                       @WIte_IdPolCom, @WIte_QtdPedInf, @WIte_QtdBonInf, @WPTipSai, @WPQtdPrzMax,
                                       @WPPrcUni, @WPPerDscVis, @WPPerDscPrz, @cr_QtdImpFat, @cr_PrcUniImp,
                                       @WPCodKitPrm, @WPPerDscPolCom, @WPPerDscVisPolCom, @WPPrcPolCom,
                                       @WPPrcUniLiqPdv, @WPPrcCusMinComMarkup, @WPPrcUniLiqPer, @WPFlgVerba,
                                       @WFlgSnhEsp, @WNomUsuSnhEsp, @WFlgNaoCriConCom, @WFlgBlqCriPrcVen, @WFlgCriVrb, @WFlgBlqQtdPar,
                                       @WPCodRej output, @WPDesMsg output, @WPCmp output, @WPNomUsuDbq output, @WPDesMsgDbq output

                Set @WIte_QtdSolInf = @WIte_QtdPedInf + @WIte_QtdBonInf
    
                if (@WPDesMsg = '') or (Substring(@WPCodRej,1,2) = 'PZ')  
                  begin
                    Set @WPCodRej = ''
                    Set @WPDesMsg = ''
                  end
                else
                  begin
                    Set @WIte_QtdPedInf = 0
                    Set @WIte_QtdBonInf = 0
                  end
    
                --Set @WPCodRej = @cr_CodRej
                --Set @WPDesMsg = @cr_DesMsg
    
                Insert Into PDVIT (
                         Cod_Estabe, Num_SeqDig, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai,
                         Qtd_Pedido, Qtd_Bonificacao, Id_PolCom, Loc_Fisica, Cod_Fabricante, 
                         Qtd_PrzMax, Prc_Fabric, Prc_MaxCon, Prc_RefFpb, Prc_Tabela, Prc_TabBru, 
                         Prc_Unitario, Per_Desconto, Per_Descon, Per_DscVis, Flg_Verba, Prc_CusMinComMarkup,
                         Qtd_PrzPolCom, Prc_PolCom, Per_DscPolCom, Per_DscVisPolCom, Cod_KitPrm, Cod_Promocao,  
                         Fat_CnvImpFat, Qtd_ImpFat, Prc_UniImpFat, 
                         Prc_UniPde, Per_DscPde, Cod_PrjPde, Num_SeqPdc,  
                         Flg_PrcUniDsc, C_PrcUni, C_PerDscIte, C_VlrDesconto, 
                         C_PrcTotal, Prc_UniLiqPer, Qtd_Solicitado, Qtd_Acerto, Flg_PolPrm, 
                         Cod_MtvRej, Des_MtvRej, Nom_UsuDesbloq, Des_MsgDesbloq) 
                    Values (  
                         @PCodEstabe, @cr_NumSeq, @PNumPdv, @cr_CodPrd, @WPCodLot, @WPTipSai,
                         @WIte_QtdPedInf, @WIte_QtdBonInf, @WIte_IdPolCom, @WPLocFis, @WPCodFab,
                         @WPQtdPrzMax, @WPPrcFab, @WPPrcMaxCon, @WPPrcRefFpb, @WPPrcTab, @WPPrcTabBru, 
                         @WPPrcUni, @WPPerDscLin, @WPPerDscPrz, @WPPerDscVis, @WPFlgVerba, @WPPrcCusMinComMarkup,  
                         @WPQtdPrzPolCom, @WPPrcPolCom, @WPPerDscPolCom, @WPPerDscVisPolCom, @WPCodKitPrm, @WPCodPromoc,  
                         @cr_FatCnvApr, @cr_QtdImpFat, @cr_PrcUniImp, 
                         0, 0, '', '', 
                         @WPFlgEmbDscPrc, @WPC_PrcUni, @WPC_PerDscIte, @WPC_VlrDesconto, 
                         @WPC_PrcTotal, @WPPrcUniLiqPer, @WIte_QtdSolInf, 0, @WPFlgPolPrm, 
                         @WPCodRej, Substring(@WPDesMsg,1,40), Substring(@WPNomUsuDbq,1,15), Substring(@WPDesMsgDbq,1,60))
    
                --  atualiza motivo qdo for o caso
                Update it 
                   Set it.Cod_MtvRej = Case 
                                         When it.Qtd_Pedido > 0 then 'ES-' 
                                         Else 'ES0'
                                       End 
                  From PDVIT it 
                 Where it.Cod_Estabe = @PCodEstabe
                   And it.Cod_Pedido = @PNumPdv
                   And it.Cod_Produto = @cr_CodPrd 
                   And it.Cod_Lote = @WPCodLot
                   And it.Tip_Sai = @WPTipSai
                   And it.Qtd_Pedido < it.Qtd_Solicitado 
                   And IsNull(it.Cod_MtvRej,'') = '' 

              end  -- if @WPFlgAchou = 1
    
            Fetch Next From PDVIT_Cr Into @cr_NumSeq, @cr_CodPrd, 
                                          @cr_QtdPed, @cr_PrcUni, @cr_PerDsc, 
                                          @cr_FatCnvApr, @cr_QtdImpFat, @cr_PrcUniImp 
          end
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

        Update PDVCB 
    	   Set Status2 = 'A'
         Where Cod_Estabe = @PCodEstabe
           And Numero = @PNumPdv
    
        Update OPMCB
           Set ID_Vale = @PNumPdv
         Where ID_Opmcb = @PIdOpmcb

        if (@@error <> 0)
          begin
            if @@trancount > 0
              Rollback Transaction
            Return
          end

      end  -- if @PNumPdv > 0
    
    if @@trancount > 0
      COMMIT TRANSACTION

  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraPedidoConsolidado]
@PIdPdvCon int,
@PTipOpe varchar(3), 
@PCodCli int,
@PCodVdr int,
@PCodOpe int,
@PDesUsu varchar(35),
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now  = GetDate()
Set @Date = cast(GetDate() as date)

Declare @CodEstabe int = 0,
        @NumPdv int = 0

Select @CodEstabe = Cod_Estabe, 
       @NumPdv = Num_PdvCon
  From PVCCB 
  Where Id_PdvCon = @PIdPdvCon

--Ajusta descrição usuario conforme função existente para evitar erro de "truncate" OUTROS-679
Set @PDesUsu = dbo.FN_UsuarioInfarma()


if (Select Sta_PdvCon From PVCCB Where Id_PdvCon = @PIdPdvCon)  <> '1'
  RAISERROR('Lote de Pedidos Matriz x Filiais não está aberto',16,1)
else
if (Select count(*) From PVCIT Where Id_PdvCon = @PIdPdvCon) = 0
  RAISERROR('Não Existem pedidos vinculados a este lote de pedidos',16,1)
else
if not Exists(Select Cod_Ope From TPOPE Where Cod_Ope = @PTipOpe and Tip_EntSai = 'S')
  RAISERROR('Tipo de Operação parametrizado inválido',16,1)
else
if not Exists(Select Codigo From CLIEN Where Codigo = @PCodCli)
  RAISERROR('Cliente parametrizado inválido',16,1)
else
if not Exists(Select Codigo From VENDE Where Codigo = @PCodVdr)
  RAISERROR('Vendedor parametrizado inválido',16,1)
else
if not Exists(Select Codigo From VENDE Where Codigo = @PCodOpe)
  RAISERROR('Operador parametrizado inválido',16,1)
else
if Exists(Select 1
          From PVCIT v
               Inner Join PDVCB cb on v.Cod_Estabe = cb.Cod_Estabe and v.Cod_Pedido = cb.Numero
	           Inner Join (Select Cod_Estabe, Cod_Pedido, Cod_Produto, QtdPdv=sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
	                       From PDVIT 
                           Where (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0
                           Group by Cod_Estabe, Cod_Pedido, Cod_Produto) it on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_pedido
               Full Join  (Select Cod_Estabe, Cod_Pedido, Cod_Produt, QtdLot=sum(IsNull(Qtd_Lote,0))
	                       From PDVLT 
			      	     Where IsNull(Qtd_Lote,0) > 0
				     Group by Cod_Estabe, Cod_Pedido, Cod_Produt) lt on cb.Cod_Estabe = lt.Cod_Estabe and cb.Numero = lt.Cod_pedido and it.Cod_Produto = lt.Cod_produt
          Where v.Id_Pdvcon = @PIdPdvCon
          And IsNull(cb.Flg_WMS,0) = 1
          And IsNull(it.QtdPdv,0) <> IsNull(lt.QtdLot,0))
  begin
    -- verifica divergencia entre PDVIT x PDVLT, se for o caso (WNMS)
    Declare @WCodPrd int,
            @WQtdPed int,
			@WQtdLot int,
            @WMsg varchar(50)

    Select top 1 
           @WCodPrd = Case When IsNull(it.Cod_Produto,0) > 0 then it.Cod_Produto else lt.Cod_Produt End, 
           @WQtdPed = IsNull(it.QtdPdv,0), @WQtdLot = IsNull(lt.QtdLot,0)
    From PVCIT v
         Inner Join PDVCB cb on v.Cod_Estabe = cb.Cod_Estabe and v.Cod_Pedido = cb.Numero
	     Inner Join (Select Cod_Estabe, Cod_Pedido, Cod_Produto, QtdPdv=sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
	                 From PDVIT 
                     Where (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0
                     Group by Cod_Estabe, Cod_Pedido, Cod_Produto) it on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_pedido
         Full Join  (Select Cod_Estabe, Cod_Pedido, Cod_Produt, QtdLot=sum(IsNull(Qtd_Lote,0))
	                 From PDVLT 
				     Where IsNull(Qtd_Lote,0) > 0
				     Group by Cod_Estabe, Cod_Pedido, Cod_Produt) lt on cb.Cod_Estabe = lt.Cod_Estabe and cb.Numero = lt.Cod_pedido and it.Cod_Produto = lt.Cod_produt
    Where v.Id_Pdvcon = @PIdPdvCon
    And IsNull(cb.Flg_WMS,0) = 1
    And IsNull(it.QtdPdv,0) <> IsNull(lt.QtdLot,0)
         
    Set @WMsg = 'Existe divergência de quantidade em PDVIT x PDVLT. Produto = '+CAST(@WCodPrd as varchar)
    RAISERROR(@WMsg,16,1)
  end
else                 
if @NumPdv > 0
  begin
    Begin Transaction

      Declare @CodEstCan int,
              @NumPdvCan int,
			  @FlgWmsCan bit,
              @CodOriPdv varchar(2) = '',
              @TotUndPdvCon int = 0,
              @TotUndPdvCan int = 0,

              @TipPrc varchar(1) = 'V',
			  @CodTabPrc int = 0,
              @WUndTotIte int = 0,
              @WUndTotSol int = 0,
              @WQtdItePrdLot int = 0,
              @WAccQtdIte int = 0,
              @WAccQtdSol int = 0,
              @WFatParIte numeric(18,8) = 0,

              @NumSeqDig int = 0,
              @PrcUni numeric(18,8) = 0,
              @CodPrdAnt int, 
              @CodPrd int, 
              @CodLot varchar(20),
			  @TipSai varchar(1),
              @CodDep smallint, 
              @NumRua smallint, 
              @NumCol smallint, 
              @NumNiv smallint, 
              @NumApt smallint, 
              @QtdPra int,
              @QtdDep int,
              @QtdTot int, 
              @QtdSol int,
              @QtdAce int, 
              @QtdPed int,
              @QtdBon int,
              @QtdPen int,

              @FatCnvImpFat int,
              @QtdImpFat int,
              @PrcUniImpFat numeric(18,8),
              @FlgUsaWms bit = 0,
              @FlgBlqWms bit = 0,        -- nunca usa WMS
              @FlgBlqPol bit = 0         -- nunca usa politica

	  Set @PMsgErr = ''
      Set @CodOriPdv = ''

      -- gera pedido sem wms, sem politica
      Set @FlgUsaWms = 0
      Set @FlgBlqWms = 1 
      Set @FlgBlqPol = 1

      -- cria pedido e coloca-o em processamento: Flg_Calc = 1
      Exec PR_IncluiPDVCB 'P', @CodEstabe, @NumPdv output, 'A', @PCodCli, @FlgUsaWms,
                          @PTipOpe, @PCodVdr, @PCodOpe, 0, 0, 0, 0,
                          @FlgBlqWms, @FlgBlqPol, @PMsgErr output, 0
						  
	  if (@@error <> 0)
	    begin
		  Rollback Transaction
		  Return
		end

      if @PMsgErr = ''
        begin
          -- tipo de preço 
          Set @TipPrc = IsNull((Select Tip_Prc From TPOPE Where Cod_Ope = @PTipOpe),'V')
          Set @CodTabPrc = IsNull((Select Cod_TabPrc From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @NumPdv),0)
          Set @CodOriPdv = (Select IsNull(Cod_OrigemPdv,'') From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @NumPdv)

          -- coloca em processamento: Flg_Calc = 1
	      Update PDVCB
	        Set Num_Referencia = @NumPdv,
	    	    Cod_OrigemPdv = @CodOriPdv,
		    	Flg_WMS = 0, 
		    	Flg_Calc = 1
	      Where Cod_Estabe = @CodEstabe
	      And Numero = @NumPdv

          -- IncluiItens
          -- Seleciona pedidos vinculados ao lote
          DECLARE Pdvcb_Cr CURSOR Local Fast_Forward For 
            Select ic.Cod_Estabe, ic.Cod_Pedido, IsNull(cb.Flg_WMS,0) 
	          From PVCIT ic
			       Inner Join PDVCB cb on ic.Cod_Estabe = cb.Cod_Estabe and ic.Cod_Pedido = cb.Numero
		      Where ic.Id_PdvCon = @PIdPdvCon
          OPEN Pdvcb_Cr
          FETCH NEXT FROM Pdvcb_Cr INTO @CodEstCan, @NumPdvCan, @FlgWmsCan
          WHILE @@FETCH_STATUS = 0
          BEGIN
            Update PDVCB 
              Set Num_Referencia = @NumPdv,
		          Status1 = 'C',
                  Bloqueio = 'SR',
                  Flg_Credito = null,
                  Usuario = @PDesUsu,
                  Transacao = GetDate(),
                  Flg_Calc = 0 
              Where Cod_Estabe = @CodEstCan
              And Numero = @NumPdvCan

            -- transfere lotes de PRLTL p/ PRLOT se for o caso -----------------------------------------------------------
            -- inclui lotes em PRLOT
            DECLARE Table_Cr Cursor Local Fast_Forward For 

              Select Cod_Produt, Cod_Lote, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_LotePra, Qtd_LoteDep, Qtd_Lote 
                From PDVLT 
                Where Cod_Estabe = @CodEstCan 
                And Cod_Pedido = @NumPdvCan 
                And Cod_LocFis = 'PRLTL'

            OPEN Table_Cr 
            FETCH NEXT FROM Table_Cr INTO @CodPrd, @CodLot, @CodDep,  @NumRua, @NumCol, @NumNiv, @NumApt, @QtdPra, @QtdDep, @QtdTot 
            WHILE @@FETCH_STATUS = 0 
            BEGIN 
              -- registra PRLOT
              Insert into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Qtd_FisPra, Qtd_SolPra, Qtd_FisDep, Qtd_SolDep) 
                      Select ldp.Cod_Estabe, ldp.Cod_Dep, ldp.Cod_Produt, ldp.Cod_Lote, ldp.Dat_Vencim, 0, 0, 0, 0 
                        From PRLTL ldp Left Outer Join 
                             PRLOT lpk on (ldp.Cod_Estabe = lpk.Cod_Estabe and ldp.Cod_Produt = lpk.Cod_Produt and ldp.Cod_Lote = lpk.Cod_Lote) 
                        Where ldp.Cod_Estabe = @CodEstCan 
                        and ldp.Cod_Produt = @CodPrd 
                        and ldp.Cod_Lote = @CodLot 
                        and ldp.Cod_Dep = @CodDep 
                        and ldp.Num_Rua = @NumRua and ldp.Num_Col = @NumCol 
                        and ldp.Num_Niv = @NumNiv and ldp.Num_Apt = @NumApt 
                        and lpk.Cod_Produt is null 

              -- decrementa PRLTL
              Update PRLTL 
                Set Qtd_FisPra = Qtd_FisPra - @QtdPra, 
                    Qtd_SolPra = Qtd_SolPra - @QtdPra 
                Where Cod_Estabe = @CodEstCan 
                and Cod_Produt = @CodPrd 
                and Cod_Lote = @CodLot 
                and Cod_Dep = @CodDep 
                and Num_Rua = @NumRua and Num_Col = @NumCol 
                and Num_Niv = @NumNiv and Num_Apt = @NumApt 
                and @QtdPra > 0 

              Update PRLTL 
                Set Qtd_FisDep = Qtd_FisDep - @QtdDep, 
                    Qtd_SolDep = Qtd_SolDep - @QtdDep 
                Where Cod_Estabe = @CodEstCan 
                and Cod_Produt = @CodPrd 
                and Cod_Lote = @CodLot 
                and Cod_Dep = @CodDep 
                and Num_Rua = @NumRua and Num_Col = @NumCol 
                and Num_Niv = @NumNiv and Num_Apt = @NumApt 
                and @QtdDep > 0 

              -- transfere para PRLOT
              Update PRLOT 
                Set Qtd_FisPra = Qtd_FisPra + @QtdPra + @QtdDep, 
                    Qtd_SolPra = Qtd_SolPra + @QtdPra + @QtdDep 
                Where Cod_Estabe = @CodEstCan 
                and Cod_Dep = @CodDep 
                and Cod_Produt = @CodPrd 
                and Cod_Lote = @CodLot 

              FETCH NEXT FROM Table_Cr INTO @CodPrd, @CodLot, @CodDep,  @NumRua, @NumCol, @NumNiv, @NumApt, @QtdPra, @QtdDep, @QtdTot 
            END 
            CLOSE Table_Cr 
            DEALLOCATE Table_Cr 
            -- fim transfere lotes de PRLTL p/ PRLOT se for o caso -----------------------------------------------------------

---------------------------------------------------------------------------------------------------------------------------------------
			-- inclui itens no pedido consolidado
            Set @NumSeqDig = 0
            if @FlgWmsCan = 1
              begin
                DECLARE Pdvlt_Cr CURSOR Local Fast_Forward For 
                  SELECT Cod_Produt, Cod_Lote, QtdPed = sum(Qtd_Lote), QtdBon = 0
                    FROM PDVLT 
                    Where Cod_Estabe =  @CodEstCan 
                    And Cod_Pedido = @NumPdvCan 
                    GROUP BY Cod_Produt, Cod_Lote
					ORDER BY Cod_Produt
                OPEN Pdvlt_Cr
                FETCH NEXT FROM Pdvlt_Cr INTO @CodPrd, @CodLot, @QtdPed, @QtdBon
                WHILE @@FETCH_STATUS = 0
                BEGIN
				  Set @CodPrdAnt = @CodPrd

	    		  Set @WUndTotIte = IsNull((Select SUM(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
                                              From PDVIT 
                                              Where Cod_Estabe = @CodEstCan And Cod_Pedido = @NumPdvCan 
                                              And Cod_Produto = @CodPrd),0)

	    		  Set @WUndTotSol = IsNull((Select SUM(IsNull(Qtd_Solicitado,0))
                                              From PDVIT 
                                              Where Cod_Estabe = @CodEstCan And Cod_Pedido = @NumPdvCan 
                                              And Cod_Produto = @CodPrd),0)

                  Set @WQtdItePrdLot = (Select count (*) 
                                          From (Select distinct Cod_Produt, Cod_Lote
                                                  From PDVLT
                                                  Where Cod_Estabe = @CodEstCan
                                                  And Cod_Pedido = @NumPdvCan
                                                  And Cod_Produt = @CodPrd) t)

                  Set @PrcUni = dbo.FN_PrecoProduto (@CodEstabe, @TipPrc, @CodPrd, @CodTabPrc)

                  Set @WAccQtdIte = 0
                  Set @WAccQtdSol = 0

				  WHILE (@CodPrdAnt = @CodPrd) and (@@FETCH_STATUS = 0) 
				    begin
                      Set @WAccQtdIte = @WAccQtdIte + 1
                      -- participacao do item
                      Set @WFatParIte = @QtdPed*1.0/@WUndTotIte

                      if @WAccQtdIte = @WQtdItePrdLot
                        begin
                          Set @QtdSol =  @WUndTotSol - @WAccQtdSol
                        end
                      else
                        begin
                          Set @QtdSol = @QtdPed
                          Set @WAccQtdSol = @WAccQtdSol + @QtdSol
                        end

                      Set @QtdAce = 0
                      Set @QtdPen = 0
                      Set @TipSai = ''

                      -- normaliza valores
                      Set @QtdPra = @QtdPed+@QtdBon
                      Set @QtdDep = 0
                      Set @QtdImpFat = (@QtdPed+@QtdBon)/@FatCnvImpFat

                      if not Exists( Select 1 From PDVIT
                                       Where Cod_Estabe = @CodEstabe
                                       And Cod_Pedido = @NumPdv
									   And Cod_Produto = @CodPrd
                                       And Cod_Lote = @CodLot
                                       And Tip_Sai = @TipSai)						 
                        begin
                          Insert Into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai,
                                             Num_SeqDig, Prc_Unitario, 
                                             Qtd_Solicitado, Qtd_Acerto, Qtd_Pedido, Qtd_Bonificacao, 
		    			                     Qtd_Pendente, Qtd_Pra, Qtd_Dep, Qtd_ImpFat)
                                     Values (@CodEstabe, @NumPdv, @CodPrd, @CodLot, @TipSai,
                                             @NumSeqDig, @PrcUni, 
                                             0, 0, 0, 0, 0, 0, 0, 0)

                          Update it
                            Set Cod_Fabricante = ic.Cod_Fabricante,
                                Loc_Fisica = ic.Loc_Fisica,
                                Flg_PrcUniDsc = ISNULL(ic.Flg_PrcUniDsc,0),
                                Per_Desconto = 0,
                                Per_Descon = 0,
                                Per_DscVis = 0,
                                Qtd_PrzMax = ISNULL(ic.Qtd_PrzMax,0),
                                Cod_Promocao = ISNULL(ic.Cod_Promocao,0),
                                Des_Und = ic.Des_Und,
                                Qtd_AprPdv = ic.Qtd_AprPdv,
                                Des_UndVen = ic.Des_UndVen,
                                Flg_Entreg = ISNULL(ic.Flg_Entreg,0),
							 
                                Prc_TabBru = ic.Prc_TabBru,
                                Prc_Tabela = ic.Prc_Tabela,
                                Prc_MaxCon = ic.Prc_MaxCon,
                                Prc_Fabric = ic.Prc_Fabric,
								 
                                Nom_UsuDesbloq = ic.Nom_UsuDesbloq,
                                Des_UnvImpFat = ic.Des_UnvImpFat,
                                Des_AprImpFat = ic.Des_AprImpFat,
                                Flg_VctLic = ISNULL(ic.Flg_VctLic,0)
                          From PDVIT it, (Select top 1 * 
                                          From PDVIT 
                                          Where Cod_Estabe = @CodEstCan 
	                                      And Cod_Pedido = @NumPdvCan 
                                          And Cod_Produto = @CodPrd
					                      Order by Tip_Sai) ic 
                          Where it.Cod_Estabe = @CodEstabe
                          And it.Cod_Pedido = @NumPdv
                          And it.Cod_Lote = @CodLot
                          And it.Tip_Sai = @TipSai						 
                          And ic.Cod_Estabe = @CodEstCan 
                          And ic.Cod_Pedido = @NumPdvCan
                          And it.Cod_Produto = ic.Cod_Produto
                        end

                      Update PDVCB 
                        Set Flg_Calc = 1 
                        Where Cod_Estabe = @CodEstabe
                        And Numero = @NumPdv
                        And IsNull(Flg_Calc,0) = 0 

                      -- normaliza valores
	        		  Set @FatCnvImpFat = (Select top 1 Fat_CnvImpFat 
		        	                       From PDVIT 
			        					   Where Cod_Estabe = @CodEstabe And Cod_Pedido = @NumPdv And Cod_Produto = @CodPrd)

                      Set @QtdPra = @QtdPed+@QtdBon
                      Set @QtdDep = 0
                      Set @QtdImpFat = (@QtdPed+@QtdBon)/@FatCnvImpFat

                      Update PDVIT
                        Set Qtd_Solicitado = Qtd_Solicitado + @QtdSol, 
                            Qtd_Acerto = Qtd_Acerto + @QtdAce, 
                            Qtd_Pedido = Qtd_Pedido + @QtdPed, 
                            Qtd_Bonificacao = Qtd_Bonificacao + @QtdBon, 
                            Qtd_Pendente = Qtd_Pendente + @QtdPen,
                            Qtd_Pra = Qtd_Pra + @QtdPra,
                            Qtd_Dep = Qtd_Dep + @QtdDep,
                            Qtd_ImpFat = Qtd_ImpFat + @QtdImpFat,
                            Prc_UniImpFat = Prc_Unitario*@FatCnvImpFat
                        Where Cod_Estabe = @CodEstabe
                        And Cod_Pedido = @NumPdv
                        And Cod_Produto = @CodPrd
                        And Cod_Lote = @CodLot
                        And Tip_Sai = @TipSai

                      FETCH NEXT FROM Pdvlt_Cr INTO @CodPrd, @CodLot, @QtdPed, @QtdBon
					end
                END
                CLOSE Pdvlt_Cr
                DEALLOCATE Pdvlt_Cr

              end
            else
              begin
                DECLARE Pdvit_Cr CURSOR Local Fast_Forward For 
                  Select Cod_Produto, Cod_Lote, 
                         sum(IsNull(Qtd_Solicitado,0)), sum(IsNull(Qtd_Pedido,0)), sum(IsNull(Qtd_Bonificacao,0)), 0, 0,
                         sum(IsNull(Qtd_Pra,0)+IsNull(Qtd_Dep,0)), 0
                    From PDVIT
                    Where Cod_Estabe =  @CodEstCan 
                    And Cod_Pedido = @NumPdvCan 
                    And (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0
				    Group by Cod_Produto, Cod_Lote
                OPEN Pdvit_Cr
                FETCH NEXT FROM Pdvit_Cr INTO @CodPrd, @CodLot, 
                                              @QtdSol, @QtdPed, @QtdBon, @QtdAce, @QtdPen,
                                              @QtdPra, @QtdDep 
                WHILE @@FETCH_STATUS = 0
                BEGIN   
                  -- checa se o produto já está no novo pedido
                  if not Exists(Select 1 From PDVIT
                                  Where Cod_Estabe = @CodEstabe
                                  And Cod_Pedido = @NumPdv
                                  And Cod_Produto = @CodPrd
                                  And Cod_Lote = @CodLot
								  And Tip_Sai = @TipSai)
                    begin
                      Set @NumSeqDig = @NumSeqDig + 1 
    				  Set @TipSai = ''
	    			  Set @PrcUni = dbo.FN_PrecoProduto (@CodEstabe, @TipPrc, @CodPrd, @CodTabPrc)

                      Insert Into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai,
                                         Num_SeqDig, Prc_Unitario, 
                                         Qtd_Solicitado, Qtd_Acerto, Qtd_Pedido, Qtd_Bonificacao, 
					                     Qtd_Pendente, Qtd_Pra, Qtd_Dep, Qtd_ImpFat)
                                 Values (@CodEstabe, @NumPdv, @CodPrd, @CodLot, @TipSai,
                                         @NumSeqDig, @PrcUni, 
                                         0, 0, 0, 0, 0, 0, 0, 0)

                      Update it
                        Set Cod_Fabricante = ic.Cod_Fabricante,
                            Loc_Fisica = ic.Loc_Fisica,
                            Flg_PrcUniDsc = ISNULL(ic.Flg_PrcUniDsc,0),
                            Per_Desconto = 0,
                            Per_Descon = 0,
                            Per_DscVis = 0,
                            Qtd_PrzMax = ISNULL(ic.Qtd_PrzMax,0),
                            Cod_Promocao = ISNULL(ic.Cod_Promocao,0),
                            Des_Und = ic.Des_Und,
                            Qtd_AprPdv = ic.Qtd_AprPdv,
                            Des_UndVen = ic.Des_UndVen,
                            Flg_Entreg = ISNULL(ic.Flg_Entreg,0),
							 
                            Prc_TabBru = ic.Prc_TabBru,
                            Prc_Tabela = ic.Prc_Tabela,
                            Prc_MaxCon = ic.Prc_MaxCon,
                            Prc_Fabric = ic.Prc_Fabric,

                            Nom_UsuDesbloq = ic.Nom_UsuDesbloq,
                            Des_UnvImpFat = ic.Des_UnvImpFat,
                            Des_AprImpFat = ic.Des_AprImpFat,
                            Flg_VctLic = ISNULL(ic.Flg_VctLic,0)
                      From PDVIT it, PDVIT ic 
                      Where it.Cod_Estabe = @CodEstabe
                      And it.Cod_Pedido = @NumPdv
                      And ic.Cod_Estabe = @CodEstCan 
                      And ic.Cod_Pedido = @NumPdvCan
                      And it.Cod_Produto = ic.Cod_Produto
                      And it.Cod_Lote = ic.Cod_Lote
                      And it.Tip_Sai = @TipSai						 
                    end

                  Update PDVCB 
                    Set Flg_Calc = 1 
                    Where Cod_Estabe = @CodEstabe
                    And Numero = @NumPdv
                    And IsNull(Flg_Calc,0) = 0 

                  -- normaliza valores
	    		  Set @FatCnvImpFat = (Select top 1 Fat_CnvImpFat 
		    	                       From PDVIT 
			    					   Where Cod_Estabe = @CodEstabe And Cod_Pedido = @NumPdv And Cod_Produto = @CodPrd)

                  Set @QtdPra = @QtdPed+@QtdBon
                  Set @QtdDep = 0
                  Set @QtdImpFat = (@QtdPed+@QtdBon)/@FatCnvImpFat

                  Update PDVIT
                    Set Qtd_Solicitado = Qtd_Solicitado + @QtdSol, 
                        Qtd_Acerto = Qtd_Acerto + @QtdAce, 
                        Qtd_Pedido = Qtd_Pedido + @QtdPed, 
                        Qtd_Bonificacao = Qtd_Bonificacao + @QtdBon, 
                        Qtd_Pendente = Qtd_Pendente + @QtdPen,
                        Qtd_Pra = Qtd_Pra + @QtdPra,
                        Qtd_Dep = Qtd_Dep + @QtdDep,
                        Qtd_ImpFat = Qtd_ImpFat + @QtdImpFat,
                        Prc_UniImpFat = Prc_Unitario*@FatCnvImpFat
                    Where Cod_Estabe = @CodEstabe
                    And Cod_Pedido = @NumPdv
                    And Cod_Produto = @CodPrd
                    And Cod_Lote = @CodLot
                    And Tip_Sai = @TipSai

                  FETCH NEXT FROM Pdvit_Cr INTO @CodPrd, @CodLot, 
                                                @QtdSol, @QtdPed, @QtdBon, @QtdAce, @QtdPen,
                                                @QtdPra, @QtdDep
                END
                CLOSE Pdvit_Cr
                DEALLOCATE Pdvit_Cr

              end

            FETCH NEXT FROM Pdvcb_Cr INTO @CodEstCan, @NumPdvCan, @FlgWmsCan
          END
          CLOSE Pdvcb_Cr
          DEALLOCATE Pdvcb_Cr
-------------------------------------------------------------------------------------------------------

          Set @TotUndPdvCon = 0
          Set @TotUndPdvCan = 0

          Select @TotUndPdvCon = sum(Qtd_Pedido+IsNull(Qtd_Bonificacao,0)) 
            From PDVIT 
            Where Cod_Estabe = @CodEstabe
            And Cod_Pedido = @NumPdv
  
          Select @TotUndPdvCan = sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)) 
            From PDVIT it
                 Inner Join PVCIT ic on it.Cod_Estabe = ic.Cod_Estabe and it.Cod_Pedido = ic.Cod_Pedido 
            Where ic.Id_PdvCon = @PIdPdvCon

          if (IsNull(@TotUndPdvCon,0) <> IsNull( @TotUndPdvCan,0)) or 
	         (IsNull(@TotUndPdvCon,0) = 0)
            begin
              Set @PMsgErr = 'Pedido Consolidado ('+Cast(@NumPdv as varchar)+') apresenta inconsistências nas quantidades. '
            end

          -- seta a flag para gerar arquivo de nf ao faturar
          -- seta a flag de movimentação de estoque do pedido para default 
          Update PDVCB 
            Set Flg_GerArqNF = 1,
                Flg_Calc = 0
            Where Cod_Estabe = @CodEstabe
            And Numero = @NumPdv

          Update PVCCB 
            Set Sta_PdvCon = '2'   -- indica que foi gerado pedido consolidado
            Where Id_PdvCon = @PIdPdvCon

        end -- if @PMsgErr = ''

    if @PMsgErr <> ''
      Rollback Transaction
	else
      Commit Transaction

  end  -- if @NumPdv > 0

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraPdvNfe]
@PCodEstabe int,
@PNumPrt int,                 -- protocolo da NF Entrada
@PTipOpe varchar(3),          -- tipo de operação do pedido a ser gerado
@PTipPrcOpc varchar(1),       -- tipo de preço de entrada, <V>-venda, 
                              --                           'E'-preço/desconto da NF entrada, 
                              --                           'L'-custo liquido da NF entrada, com IPI
                              --                           'M'-custo medio 
@PPerMarkupOpc numeric(7,4),  -- % Markup opcional

@PFlgPdvAteTot bit,      -- indica se pedido deve ser atentido totalmente
@PCodCli int,
@PIdPolCom int,
@PCodOpe int,            -- cod. operador
@PCodVdr int,            -- cod. vendedor do pedido a ser gerado
@PCodAgc int,            -- cod. agente cobrador
@PCodTra int,            -- cod. transportadora
@PDesUsu varchar(15),    -- usuario
@PNumPdv int output,     -- codigo do pedido gerado
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime
      , @Date smalldatetime

Set @Now = GetDate()
Set @Date = cast(GetDate() as Date)

Set @PNumPdv = 0
Set @PMsgErr = ''

if not Exists(Select 1 From NFECB Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumPrt And Status = 'F')
  Set @PMsgErr ='NF não está "fechada" (Status = "F")'
else
if Exists(Select 1 From PDVCB Where Cod_Estabe = @PCodEstabe And Num_PrtOri = @PNumPrt And Status1 <> 'C')
  Set @PMsgErr ='Já existe pedido de venda gerado para esta NF'
else
if Exists(Select  1 From NFECB cb inner Join ENDDP ed on cb.Cod_Estabe = ed.Cod_Estabe and cb.Id_EndDep = ed.Id_EndDep 
           Where cb.Cod_Estabe = @PCodEstabe And cb.Protocolo = @PNumPrt And IsNull(cb.Flg_CrossDocking,0) = 1
             And not Exists(Select 1 From PRLTL lt
                             Where lt.Cod_Estabe = ed.Cod_Estabe And lt.Cod_Dep = ed.Cod_Dep 
                               and lt.Num_Rua = ed.Num_Rua and lt.Num_Col = ed.Num_Col And lt.Num_Niv = ed.Num_Niv
                               and lt.Qtd_Saldo > 0))
  Set @PMsgErr ='Não existe ao menos um item com saldo no endereço de Cross Docking'
else

  begin
    BEGIN TRANSACTION

    Declare @ne_FlgCrosDock bit = 0
          , @ne_IdEndDep int = 0
          , @pm_FlgUsaPolComPdv bit
          , @pm_QtdDecPrcItePdv smallint

          , @WFlgWMS bit = 0
          , @WCodDig int = 0
          , @WFlgBlqWms bit = 0
          , @WFlgBlqPol bit = 0
          , @WCodTabPrz int = 0
          , @WCodLayout int = 0
          , @WFlgBlqDscAutIte bit
          , @WFlgCriVrb bit
          , @WFlgBlqQtdPar bit
          , @WMsgErrPrd varchar(8000)

          , @WFlgSnhEsp bit
          , @WFlgBlqCriConCom bit
          , @WFlgBlqCriPrcVen bit
          , @WNomUsuSnhEsp varchar(35)

          , @Usuario varchar(15)
          , @CodOri varchar(20)
          , @CodMtvTrfLot varchar(6) = ''
	
	-- Auditoria usuario infarma ou banco
	Set @Usuario = dbo.FN_UsuarioInfarma()
	Set @CodOri = 'NFE_PDV'

    Select @ne_FlgCrosDock = IsNull(cb.Flg_CrossDocking,0)
         , @ne_IdEndDep = IsNull(cb.Id_EndDep,0)
		 , @pm_FlgUsaPolComPdv = IsNull(pa.FlgUsaPolComPdv,0)
         , @pm_QtdDecPrcItePdv = IsNull(pa.QtdDecPrcItePdv,4)
      From NFECB cb 
           Inner Join PARAM pa on cb.Cod_Estabe = pa.Cod_Estabe
     Where cb.Cod_Estabe = @PCodEstabe 
       And cb.Protocolo = @PNumPrt
   
    Set @WFlgWMS = 0
    Set @PTipOpe = 'FAT'
    Set @WCodDig = 0
    Set @WFlgBlqWms = 0
    Set @WFlgBlqPol = 0
    Set @WCodTabPrz = 0
    Set @WCodLayout = 0
	Set @WMsgErrPrd = ''

    Exec PR_IncluiPDVCB 'P', @PCodEstabe, @PNumPdv output, 'A', @PCodCli, @WFlgWMS, @PTipOpe,
                        @PCodVdr, @PCodOpe, @WCodDig, @PIdPolCom, @WCodTabPrz, @WCodLayout,
                        @WFlgBlqWms, @WFlgBlqPol, @PMsgErr output, 0

    if (@PNumPdv > 0) and (@PMsgErr = '')
      begin
        -- procedimento que simula EditCodClienteExit no EdPedVen
		-- já eh executado em PR_IncluiPDVCB
        --Exec PR_InfoDefaultPDVCB @PCodEstabe, @PNumPdv

        Update pv
           Set pv.Status2 = 'X' -- em processamento   
             , Flg_Calc = 1     -- não solicita lotes
             , Bloqueio = 'SR'  -- para não solicitar lotes
             , pv.Num_PrtOri = @PNumPrt
             , pv.Tip_Vencimento = ''
         From PDVCB pv
        Where pv.Cod_Estabe = @PCodEstabe
          And pv.Numero = @PNumPdv

        Declare @WPFlgAchou bit,
                @WPTipSai varchar(1),
                @WPLocFis varchar(15),
                @WPCodFab int,
                @WPFatCnvImpFat int,
                @WPPrcFab numeric(18,8),
                @WPPrcMaxCon numeric(18,8),
                @WPPrcRefFpb numeric(18,8),
                @WPPrcCusMinComMarkup numeric(18,8),
                @WPPrcTab numeric(18,8),
                @WPPrcTabBru numeric(18,8),
                @WPPrcUni numeric(18,8),
                @WPPrcUniLiqPer numeric(18,8),
                @WPFlgEmbDscPrc bit,
                @WPPerDscLin numeric(18,8),
                @WPPerDscPrz numeric(18,8),
                @WPPerDscVis numeric(18,8),
                @WPQtdPrzMax int,
                @WPCodRej varchar(3),
                @WPDesMsg varchar(80),
                @WPCmp varchar(20),
                @WPNomUsuDbq varchar(35),
                @WPDesMsgDbq varchar(60),
    
                @cr_NumSeq int,
                @cr_CodPrd int,
                @cr_CodLot varchar(20),
                @cr_QtdPed int, 
                @cr_QtdPra int, 
                @cr_QtdDep int, 
                @cr_PrcUni numeric(18,8), 
                @cr_PerDsc numeric(8,4), 
                @cr_FatCnvApr int,
                @cr_QtdImpFat numeric(18,4), 
                @cr_PrcUniImp numeric(18,8), 

                @cr_CodDep smallint,
                @cr_NumRua smallint,
                @cr_NumCol smallint,
                @cr_NumNiv smallint,
                @cr_NumApt smallint,
                @cr_DatVct smalldatetime,
                @WQtdTrfTot int,

                @WCodDepPck smallint,
                @WNumRuaPck smallint,
                @WNumColPck smallint,
                @WNumNivPck smallint,
                @WNumAptPck smallint,

                @WIte_QtdSolInf int,
                @WIte_QtdPedInf int, 
                @WIte_QtdBonInf int,
                @WIte_IdPolCom int,
    
                @WPPerDscPolCom numeric(18,8),
                @WPPerDscVisPolCom numeric(18,8),
                @WPPrcPolCom numeric(18,8),
                @WPQtdPrzPolCom int,
                @WPCodKitPrm int,
                @WPCodPromoc int,
                @WPFlgVerba bit,
                @WPFlgPolPrm bit,
    
                @WPC_PrcUni numeric(18,8),
                @WPC_PerDscIte numeric(7,4),
                @WPPrcUniLiqPdv numeric(18,8)
    
    ----------------------------------------------------------------------------------
        Declare PDVIT_Cr Cursor Local Fast_Forward For
          Select NumSeq = row_number() over(Order by it.Cod_Produt)
               , it.Cod_Produt, it.Cod_Lote
               , QtdPra = lt.Qtd_SldPra, QtdDep = lt.Qtd_SldDep
               , PrcUni = Case 
                            When @PTipPrcOpc = 'E' then i.Prc_Unitario 
                            When @PTipPrcOpc = 'L' then i.Prc_Unitario+i.Vlr_IpiUni 
                            Else 0 
                          End
               , PerDsc = Case 
                            When @PTipPrcOpc = 'E' then i.Per_DescItem 
                            When @PTipPrcOpc = 'L' then i.Per_DescItem 
                            Else 0 
                          End
               , Fat_CnvApr = 1, QtdImpFat = Qtd_Est, PrcUniImp = 0
               , lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt,lt.Dat_Vencim
            From NELTL it
                 Cross Apply (Select top 1 x.Prc_Unitario, x.Per_DescItem,
                                           Vlr_IpiUni = x.Vlr_Ipi/(x.Qtd_Pedido+x.Qtd_Bonificacao)
                                From NFEIT x
                               Where x.Cod_Estabe = it.Cod_Estabe
                                 And x.Protocolo = it.Num_Protoc
                                 And x.Cod_Produto = it.Cod_Produt
                                 And x.Cod_Lote = it.Cod_Lote
                               Order by x.Num_SeqIte) i
                 inner join PRLTL lt on it.Cod_Estabe = lt.Cod_Estabe 
                                    and it.Cod_Produt = lt.Cod_Produt and it.Cod_Lote = lt.Cod_Lote
                                    and it.Cod_Dep = lt.Cod_Dep and it.Num_Rua = lt.Num_Rua 
                                    and it.Num_Col = lt.Num_Col and it.Num_Niv = lt.Num_Niv
                                    and it.Num_Apt = lt.Num_Apt

           Where it.Cod_Estabe = @PCodEstabe
             And it.Num_Protoc = @PNumPrt
             And dbo.FN_TipLocEnd(it.Cod_Estabe, it.Cod_Dep, it.Num_Rua) = 'C'
    
        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @cr_NumSeq
                                    , @cr_CodPrd, @cr_CodLot, @cr_QtdPra, @cr_QtdDep
                                    , @cr_PrcUni, @cr_PerDsc
                                    , @cr_FatCnvApr, @cr_QtdImpFat, @cr_PrcUniImp 
                                    , @cr_CodDep, @cr_NumRua, @cr_NumCol, @cr_NumNiv, @cr_NumApt, @cr_DatVct
        While @@FETCH_STATUS = 0
          begin
            Set @cr_QtdPed = @cr_QtdPra + @cr_QtdDep
            Set @WIte_QtdPedInf = @cr_QtdPed
            Set @WIte_QtdBonInf = 0
            Set @WIte_IdPolcom  = 0   -- ???????
  
            Set @WFlgBlqDscAutIte = 0
    
            Exec PR_InfoDefaultPDVIT @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @cr_CodPrd, 
                                     @WIte_QtdPedInf, @WIte_QtdBonInf, @WIte_IdPolCom output, @WFlgBlqDscAutIte,
                                     @WPFlgAchou output,
                                     @WPLocFis output,
                                     @WPCodFab output,
                                     @WPPrcFab output,
                                     @WPPrcMaxCon output,
                                     @WPPrcRefFpb output,
                                     @WPPrcTab output,
                                     @WPPrcTabBru output,
                                     @WPFatCnvImpFat output,     
                                     @WPPrcUni output,
                                     @WPPrcCusMinComMarkup output,
                                     @WPPerDscPolCom output,
                                     @WPPerDscVisPolCom output,
                                     @WPPrcPolCom output,
                                     @WPQtdPrzPolCom output,
                                     @WPFlgVerba output,
                                     @WPFlgPolPrm output,
                                     @WPCodKitPrm output,
                                     @WPCodPromoc output,
                                     @WPFlgEmbDscPrc output, 
                                     @WPQtdPrzMax output,
                                     @WPPerDscLin output,
                                     @WPPerDscPrz output,
                                     @WPPerDscVis output,
                                     @WPPrcUniLiqPer output
            if @WPFlgAchou = 1
              begin

                if @cr_PrcUni > 0  
                  begin
                    Set @WPPrcUni       = Round(@cr_PrcUni*(1+@PPerMarkupOpc/100),@pm_QtdDecPrcItePdv)
                    Set @cr_PrcUni      = @WPPrcUni
                    Set @WPPerDscLin    = @cr_PerDsc  
                    Set @WPPerDscPrz    = @cr_PerDsc
                    Set @WPPerDscVis    = @cr_PerDsc
                    Set @cr_PrcUniImp   = 0
                  end
  
                if IsNull(@cr_PrcUniImp,0) = 0
                  Set @cr_PrcUniImp = @WPPrcUni*@cr_FatCnvApr
  
                Set @WPTipSai       = ''
                Set @WPFatCnvImpFat = @cr_FatCnvApr
    
    ----------------------------------------------------------------
                --  calcfields 
                Set @WPC_PrcUni = @WPPrcUni
                Set @WPC_PerDscIte = @cr_PerDsc
                if @WPFlgEmbDscPrc = 1
                  begin
                    Set @WPC_PrcUni = @WPPrcUni*(1-@WPC_PerDscIte/100)
                    Set @WPC_PerDscIte = 0
                  end

                --  calcula preco unitario liquido
                Set @WPPrcUniLiqPdv = @WPPrcUni*(1-@WPC_PerDscIte/100)
                   
                Set @WFlgSnhEsp = 1 
                Set @WNomUsuSnhEsp = @PDesUsu
                Set @WFlgBlqCriConCom = 1  -- nao critica  
                Set @WFlgBlqCriPrcVen = 1  -- nao critica  
                Set @WFlgCriVrb = 0        
                Set @WFlgBlqQtdPar = 0
    
                Exec PR_CriticaItemPDV @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @cr_CodPrd, 
                                       @WIte_IdPolCom, @WIte_QtdPedInf, @WIte_QtdBonInf, @WPTipSai, @WPQtdPrzMax,
                                       @WPPrcUni, @WPPerDscVis, @WPPerDscPrz, @cr_QtdImpFat, @cr_PrcUniImp,
                                       @WPCodKitPrm, @WPPerDscPolCom, @WPPerDscVisPolCom, @WPPrcPolCom,
                                       @WPPrcUniLiqPdv, @WPPrcCusMinComMarkup, @WPPrcUniLiqPer, @WPFlgVerba,
                                       @WFlgSnhEsp, @WNomUsuSnhEsp, @WFlgBlqCriConCom, @WFlgBlqCriPrcVen, @WFlgCriVrb, @WFlgBlqQtdPar,
                                       @WPCodRej output, @WPDesMsg output, @WPCmp output, @WPNomUsuDbq output, @WPDesMsgDbq output
  
                Set @WIte_QtdSolInf = @WIte_QtdPedInf + @WIte_QtdBonInf

                if (@WPDesMsg = '') or (Substring(@WPCodRej,1,2) = 'PZ')  
                  begin
                    Set @WPCodRej = ''
                    Set @WPDesMsg = ''
                  end
                else
                  begin
                    Set @WIte_QtdPedInf = 0
                    Set @WIte_QtdBonInf = 0
                    Set @cr_QtdPra = 0
                    Set @cr_QtdDep = 0

                   if (Len(@WMsgErrPrd)+Len(cast(@cr_CodPrd as varchar)+':'+@WPDesMsg) < 8000) 
                     Set @WMsgErrPrd = @WMsgErrPrd + cast(@cr_CodPrd as varchar)+':'+@WPDesMsg+';'
                  end
    
                -- transfere de PRLTL pra PRLOT
                Update PRLTL 
                   Set Qtd_FisPra = Qtd_FisPra - @cr_QtdPra
                     , Qtd_FisDep = Qtd_FisDep - @cr_QtdDep
                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Dep = @cr_CodDep
                   And Cod_Produt = @cr_CodPrd
                   And Cod_Lote = @cr_CodLot
                   And Num_Rua = @cr_NumRua
                   And Num_Col = @cr_NumCol
                   And Num_Niv = @cr_NumNiv
                   And Num_Apt = @cr_NumApt
                   And Qtd_SldPra >= @cr_QtdPra 
                   And Qtd_SldDep >= @cr_QtdDep

                -- registra transferencia pra PRLOT
                if @@rowcount > 0 
                  begin 
                	-- registra log saida
                    if (@cr_QtdPra + @cr_QtdDep) > 0
                      begin
                        Set @WQtdTrfTot = (@cr_QtdPra + @cr_QtdDep) * (-1) 
                        Exec PR_InserePRLOG @PCodEstabe, @cr_CodPrd, @cr_CodLot, @cr_CodDep, 
                                            @cr_NumRua, @cr_NumCol, @cr_NumNiv, @cr_NumApt, 
                                            @WQtdTrfTot, @CodOri, @CodMtvTrfLot, '', '', '', @Usuario
                      end
                						 
                	-- dá entrada no picking e solicita
                    if Not Exists(Select 1 From PRLOT 
                                   Where Cod_Estabe = @PCodEstabe 
                                     And Cod_Dep = @cr_CodDep
                                     And Cod_Produt = @cr_CodPrd 
                                     And Cod_Lote = @cr_CodLot) 
                      begin 
                        Insert Into PRLOT(Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Entrada, Qtd_FisPra, Qtd_FisDep) 
                                   Values(@PCodEstabe, @cr_CodDep, @cr_CodPrd, @cr_CodLot, @cr_DatVct, @Date, 0, 0) 
                      end 
                
                    -- dá entrada emPRLOT
                    Update PRLOT 
                       Set Qtd_FisPra = Qtd_FisPra + @cr_QtdPra, 
                           Qtd_FisDep = Qtd_FisDep + @cr_QtdDep 
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Dep = @cr_CodDep
                       And Cod_Produt = @cr_CodPrd
                       And Cod_Lote = @cr_CodLot

                    -- solicita PRLOT
                    Update PRLOT 
                       Set Qtd_SolPra = Qtd_SolPra + @cr_QtdPra, 
                           Qtd_SolDep = Qtd_SolDep + @cr_QtdDep 
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Dep = @cr_CodDep
                       And Cod_Produt = @cr_CodPrd
                       And Cod_Lote = @cr_CodLot

                    -- registra log entrada 
                    Set @WCodDepPck = 0
                    Set @WNumRuaPck = 0
                    Set @WNumColPck = 0
                    Set @WNumNivPck = 0
                    Set @WNumAptPck = 0

                    if (@cr_QtdPra + @cr_QtdDep) > 0
                      begin
                        Select top 1 
                               @WCodDepPck = dp.Cod_Dep
                             , @WNumRuaPck = dp.Num_Rua
                             , @WNumColPck = dp.Num_Col
                             , @WNumNivPck = dp.Num_Niv
                             , @WNumAptPck = dp.Num_Apt
                         From DPXPR dp
                              Inner Join PRXES pr on pr.Cod_Estabe = dp.Cod_Estabe and pr.Cod_Produt = dp.Cod_Produt 
                        Where pr.Cod_Estabe = @PCodEstabe
                          And pr.Cod_Produt = @cr_CodPrd
                        Order by dp.Cod_Dep

                        Set @WQtdTrfTot = @cr_QtdPra + @cr_QtdDep 
                        Exec PR_InserePRLOG @PCodEstabe, @cr_CodPrd, @cr_CodLot, @WCodDepPck, 
                                            @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck, 
                                            @WQtdTrfTot, @CodOri, @CodMtvTrfLot, '', '', '', @Usuario
                      end

                    -- solicita PRXES
                    Update PRXES
                       Set Qtd_Solici = Qtd_Solici + @cr_QtdPra + @cr_QtdDep
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Produt = @cr_CodPrd

                    Update PRXES
                       Set Qtd_PrmSolici = Qtd_PrmSolici + @cr_QtdPra + @cr_QtdDep
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Produt = @cr_CodPrd
                       And @WPCodPromoc > 0

                    -- inclui item de pedido  
                    Insert Into PDVIT (
                             Cod_Estabe, Num_SeqDig, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai,
                             Qtd_Pedido, Qtd_Bonificacao, Qtd_Pra, Qtd_Dep,
                             Id_PolCom, Loc_Fisica, Cod_Fabricante, 
                             Qtd_PrzMax, Prc_Fabric, Prc_MaxCon, Prc_RefFpb, Prc_Tabela, Prc_TabBru, 
                             Prc_Unitario, Per_Desconto, Per_Descon, Per_DscVis, Flg_Verba, Prc_CusMinComMarkup,
                             Qtd_PrzPolCom, Prc_PolCom, Per_DscPolCom, Per_DscVisPolCom, Cod_KitPrm, Cod_Promocao,  
                             Fat_CnvImpFat, Qtd_ImpFat, Prc_UniImpFat, 
                             Prc_UniPde, Per_DscPde, Cod_PrjPde, Num_SeqPdc,  
                             Flg_PrcUniDsc, C_PrcUni, C_PerDscIte, 
                             Prc_UniLiqPer, Qtd_Solicitado, Qtd_Acerto, Flg_PolPrm, 
                             Cod_MtvRej, Des_MtvRej, Nom_UsuDesbloq, Des_MsgDesbloq) 
                        Values (  
                             @PCodEstabe, @cr_NumSeq, @PNumPdv, @cr_CodPrd, @cr_CodLot, @WPTipSai,
                             @WIte_QtdPedInf, @WIte_QtdBonInf, @cr_QtdPra, @cr_QtdDep,
                             @WIte_IdPolCom, @WPLocFis, @WPCodFab,
                             @WPQtdPrzMax, @WPPrcFab, @WPPrcMaxCon, @WPPrcRefFpb, @WPPrcTab, @WPPrcTabBru, 
                             @WPPrcUni, @WPPerDscLin, @WPPerDscPrz, @WPPerDscVis, @WPFlgVerba, @WPPrcCusMinComMarkup,  
                             @WPQtdPrzPolCom, @WPPrcPolCom, @WPPerDscPolCom, @WPPerDscVisPolCom, @WPCodKitPrm, @WPCodPromoc,  
                             @cr_FatCnvApr, @cr_QtdImpFat, @cr_PrcUniImp, 
                             0, 0, '', '', 
                             @WPFlgEmbDscPrc, @WPC_PrcUni, @WPC_PerDscIte,
                             @WPPrcUniLiqPer, @WIte_QtdSolInf, 0, @WPFlgPolPrm, 
                             @WPCodRej, Substring(@WPDesMsg,1,40), Substring(@WPNomUsuDbq,1,15), Substring(@WPDesMsgDbq,1,60))
          
                    --  atualiza motivo qdo for o caso
                    Update it 
                       Set it.Cod_MtvRej = Case 
                                             When it.Qtd_Pedido > 0 then 'ES-' 
                                             Else 'ES0'
                                           End 
                      From PDVIT it 
                     Where it.Cod_Estabe = @PCodEstabe
                       And it.Cod_Pedido = @PNumPdv
                       And it.Cod_Produto = @cr_CodPrd 
                       And it.Cod_Lote = @cr_CodLot
                       And it.Tip_Sai = @WPTipSai
                       And it.Qtd_Pedido < it.Qtd_Solicitado 
                       And IsNull(it.Cod_MtvRej,'') = '' 
       
                  end  -- if @rowcount
               else
                 begin
                   Set @WPDesMsg = cast(@cr_CodPrd as varchar)+'/'+@cr_CodLot+':Lote insuficiente para atender o pedido'
                   if (Len(@WMsgErrPrd)+Len(cast(@cr_CodPrd as varchar)+':'+@WPDesMsg) < 8000) 
                     Set @WMsgErrPrd = @WMsgErrPrd + cast(@cr_CodPrd as varchar)+':'+@WPDesMsg+';'
                 end
  
              end  -- if @WPFlgAchou = 1

            Fetch Next From PDVIT_Cr Into @cr_NumSeq
                                        , @cr_CodPrd, @cr_CodLot, @cr_QtdPra, @cr_QtdDep
                                        , @cr_PrcUni, @cr_PerDsc
                                        , @cr_FatCnvApr, @cr_QtdImpFat, @cr_PrcUniImp 
                                        , @cr_CodDep, @cr_NumRua, @cr_NumCol, @cr_NumNiv, @cr_NumApt, @cr_DatVct
          end
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

        -- se for o caso verifica atendimento total
        if (@WMsgErrPrd = '') and (@PFlgPdvAteTot = 1)
		  if Exists(Select 1 From PDVIT
                     Where Cod_Estabe = @PCodEstabe
                       And Cod_Pedido = @PNumPdv
                       And (Qtd_Pedido+Qtd_Bonificacao) <> Qtd_Solicitado)
            Set @WMsgErrPrd = 'Pedido não foi totalmente atendido'

        if @WMsgErrPrd = ''
          begin
            Update PDVCB 
               Set Status2 = 'A'
                 , Flg_Calc = 0  
                 , Bloqueio = '' 
             Where Cod_Estabe = @PCodEstabe
               And Numero = @PNumPdv
          end
        else
          begin
            Set @PMsgErr = Substring(@WMsgErrPrd,1,8000)
            Set @PNumPdv = 0
            ROLLBACK TRANSACTION
            RETURN
          end
      end  -- if (@PNumPdv > 0) and (@PMsgErr <> '')

    if @@trancount > 0
      COMMIT TRANSACTION

  end  -- if Exists(Select 1
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_DesdobraPDV]
@TipDesdob varchar(1),  -- 'I'-Incetivo fiscal, 'G'-genericos/similares, 'L'-produto com mais de 1 lote, 'B'-bonificados
@CodEstabe int,
@CodPed int,
@CodPdvGer Int Output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Date smalldatetime
Set @Date = cast(GetDate() as date)

Declare @WQtdIteRef int,
        @WQtdIteOut int,
		@WFlgIncIte bit,
		@WCodPrdAnt int,
        @WIdIncFis smallint,
        @nw_TipFat varchar(3),
        @cb_FlgCriIteFec bit,
        @cb_NumPdvLig  int

Set @CodPdvGer = 0

Set @WIdIncFis = 0
Set @WQtdIteRef = 0
Set @WQtdIteOut = 0
Set @nw_TipFat = '?'
Set @cb_FlgCriIteFec = 1   -- ajusta Flg_CriIteFec = 1 para nao forçar recalculo de tributos do novo pedido
Set @cb_NumPdvLig = 0

if (IsNull(@TipDesdob,'') <> 'L') and
   (IsNull(@TipDesdob,'') <> 'G') and
   (IsNull(@TipDesdob,'') <> 'B')
  Set @TipDesdob = 'I'

if (@TipDesdob = 'L')
  begin
    Set @WQtdIteRef = IsNull((Select count (*) 
                                From (Select Cod_Estabe, Cod_Pedido, Cod_Produto, QtdLot=count(*)
                                        From dbo.PDVIT
                                       Where Cod_Estabe = @CodEstabe
                                         And Cod_Pedido = @CodPed
                                         And Qtd_Pedido > 0
                                       Group by Cod_Estabe, Cod_Pedido, Cod_Produto
                                      Having count(*) > 1) x),0)
  end

if (@TipDesdob = 'B') and
   ((Select IsNull(Flg_GerPdvBon,0) From dbo.PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) = 1) and
   ((Select IsNull(Num_PdvLig,0) From dbo.PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) = 0) and
   ((Select Substring(Cod_OrigemPdv,1,1) From dbo.PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) <> 'D') and
   ((Select tp.Tip_Ope 
       From dbo.TPOPE tp 
            Inner Join dbo.PDVCB pv on (pv.Tip_Faturamento = tp.Cod_Ope) 
       Where pv.Cod_Estabe = @CodEstabe And pv.Numero = @CodPed) = 'V') 
  begin
    Set @cb_NumPdvLig = @CodPed
    Set @cb_FlgCriIteFec = 0  -- tem que recalcular tributos
    Set @nw_TipFat = (Select IsNull(CodTpvBon,'') From dbo.PARAM Where Cod_Estabe = @CodEstabe)

    -- calcula qtd itens bonificados
    Set @WQtdIteRef = (Select count(*) 
                         From dbo.PDVIT it 
                        Where it.Cod_Estabe = @CodEstabe
                          And it.Cod_Pedido = @CodPed
                          And it.Qtd_Bonificacao > 0)
  end

if (@TipDesdob = 'G') and
   ((Select IsNull(Flg_DesdobGenericos,0) From dbo.ESTAB Where Cod_Estabe = @CodEstabe) = 1)
  begin
    -- calcula qtd itens genericos/similares
    Set @WQtdIteRef = IsNull((Select count(*) 
                                From dbo.PDVIT it 
                                     Inner Join dbo.PRODU pr on it.Cod_Produto = pr.Codigo
                               Where it.Cod_Estabe = @CodEstabe
                                 And it.Cod_Pedido = @CodPed
                                 And it.Qtd_Pedido > 0
                                 And ((pr.Cod_GrpPrc = 'G') or (pr.Cod_GrpPrc = 'S'))),0)
                   
    -- calcula qtd itens não genericos/similares
    Set @WQtdIteOut = IsNull((Select count(*) 
                                From dbo.PDVIT it 
                                     Inner Join dbo.PRODU pr on it.Cod_Produto = pr.Codigo
                               Where it.Cod_Estabe = @CodEstabe
                                 And it.Cod_Pedido = @CodPed
                                 And it.Qtd_Pedido > 0
                                 And ((pr.Cod_GrpPrc <> 'G') and (pr.Cod_GrpPrc <> 'S'))),0)
  end

if (@TipDesdob = 'I')
  begin
    -- determina o incentivo fiscal (com mais itens)
    Set @WIdIncFis = IsNull((Select top 1 v.Id_IncFis
                               From dbo.PDVIT it 
                                    Inner Join dbo.V_PrdIncFis v on it.Cod_Estabe = v.Cod_Estabe and it.Cod_Produto = v.Cod_Produt
                              Where it.Cod_Estabe = @CodEstabe
                                And it.Cod_Pedido = @CodPed
                                And it.Qtd_Pedido > 0
                                And IsNull(v.Flg_PdvEsp,0) = 1
                              Group by v.Id_IncFis
                              Order by count(*) desc),0)

   -- calcula qtd itens incentivados
   Set @WQtdIteRef = IsNull((Select count(*) 
                               From dbo.PDVIT it 
                              Where it.Cod_Estabe = @CodEstabe
                                And it.Cod_Pedido = @CodPed
                                And it.Qtd_Pedido > 0
                                And dbo.FN_ProdutoIncentivado(it.Cod_Estabe,it.Cod_Produto,@WIdIncFis) = 1),0)
                  
   -- calcula qtd itens não incentivados
   Set @WQtdIteOut = IsNull((Select count(*) 
                               From dbo.PDVIT it 
                              Where it.Cod_Estabe = @CodEstabe
                                And it.Cod_Pedido = @CodPed
                                And it.Qtd_Pedido > 0
                                And dbo.FN_ProdutoIncentivado(it.Cod_Estabe,it.Cod_Produto,@WIdIncFis) = 0),0)
  
   -- pedido possui somente produtos incentivados
   if @WQtdIteRef > 0 and @WQtdIteOut = 0
     begin
       Update dbo.PDVCB
          Set Id_IncFis = @WIdIncFis
        Where Cod_Estabe = @CodEstabe
          And Numero = @CodPed
          And IsNull(Id_IncFis,0) = 0
     end

  end

if ( (Select Status1 From dbo.PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) = 'P' ) and
   ( ( (@TipDesdob = 'L') and ((Select Status2 From dbo.PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) = 'F') ) or
     ( (@TipDesdob = 'I') and ((Select Status2 From dbo.PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) = 'A') ) or
     ( (@TipDesdob = 'G') and ((Select Status2 From dbo.PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) = 'A') ) or
     ( (@TipDesdob = 'B') and 
       ((Select Status2 From dbo.PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) = 'A') and
       ((Select IsNull(Flg_GerPdvBon,0) From dbo.PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) = 1) and
       (Exists(Select 1 From dbo.TPOPE Where Cod_Ope = @nw_TipFat)) )
   )

  if ( (@TipDesdob = 'L') and (@WQtdIteRef > 0) ) or
     ( (@TipDesdob = 'I') and (@WQtdIteRef > 0) and (@WQtdIteOut > 0) ) or
     ( (@TipDesdob = 'G') and (@WQtdIteRef > 0) and (@WQtdIteOut > 0) ) or
     ( (@TipDesdob = 'B') and (@WQtdIteRef > 0) ) 
    begin
      Begin Transaction
      -- bloqueia registro
      Update dbo.PDVCB
         Set Qtd_Itens = Qtd_Itens + 0
       Where Cod_Estabe = @CodEstabe 
         And Numero = @CodPed
  
      --variaveis p/ campos de PDVIT
      Declare @it_CodPrd int,
              @it_CodLot varchar(20),
              @it_TipSai varchar(1),
              @it_QtdPed int,
              @it_QtdBon int,
              @it_QtdPra int,
              @it_QtdDep int,
              @nw_QtdPra int,
              @nw_QtdDep int
  
      --coloca campos de PDVCB na memoria
      Declare @cb_BlqAnt varchar(2),
              @cb_CodOriPdv varchar(2)
  
      -- Variável auxiliar . . . 
      Declare @Pde_Cod_Layout int,
              @Pde_Num_Cnpj varchar(14),   
              @Pde_Cod_PedCli varchar(20),
              @Pde_Num_Desdob smallint,
              @Pde_Num_DesdobDes smallint,
              @Pdeit_Num_Desdob smallint,
              @Pdeit_Cod_PrdCli varchar(14)
  
      Select @cb_BlqAnt = Bloqueio,
             @cb_CodOriPdv = Cod_OrigemPdv
        From dbo.PDVCB 
       Where Cod_Estabe = @CodEstabe 
         And Numero = @CodPed
  
      -- cria novo pedido
      EXEC PR_ProxNumero 'Pedido_Venda', @CodPdvGer output
      
      -- cria cabecalho novo pedido com Tipo do bloqueio = 'SR' para nao decrementar saldo e em modo de calculo
      Insert into dbo.PDVCB (Cod_Estabe, Numero)
        Values (@CodEstabe, @CodPdvGer)
      if @@error <> 0
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end
  
      Update d
         Set d.Status1            = 'P',
             d.Status2            = 'A',
             d.Flg_JaFechado      = 0,
             d.Qtd_ImpPnt         = 0,
             d.Dat_Pedido         = @Date,
             d.Hor_Entrada        = GetDate(),
             d.Bloqueio           = 'SR',
             d.Flg_Calc           = 1,
             d.Flg_CriIteFec      = @cb_FlgCriIteFec,
  
             d.Num_PdvPai         = @CodPed,
             d.Num_PdvLig         = @cb_NumPdvLig,
             d.Id_IncFis          = @WIdIncFis,
             d.Tip_Pedido         = o.Tip_Pedido,
             d.Cod_OrigemPdv      = o.Cod_OrigemPdv,
             d.Tip_Faturamento    = Case 
                                      When @TipDesdob = 'B' Then @nw_TipFat 
                                      Else o.Tip_Faturamento 
                                    End,
             d.Flg_ComisNormal    = IsNull(o.Flg_ComisNormal,0),
             d.Flg_TabProgres     = IsNull(o.Flg_TabProgres,0),
             d.Flg_Credito        = IsNull(o.Flg_Credito,0),
             d.Flg_WMS            = IsNull(o.Flg_WMS,0),
             d.Flg_CalCom         = IsNull(o.Flg_CalCom,0),
             d.Flg_GerPdvBon      = IsNull(o.Flg_GerPdvBon,0),
             d.Flg_GerRetBon      = IsNull(o.Flg_GerRetBon,0),
             d.Cod_Cliente        = o.Cod_Cliente,
             d.Cod_RegTri         = o.Cod_RegTri,
             d.Cod_Agente         = o.Cod_Agente,
             d.Cod_Transportadora = o.Cod_Transportadora,
             d.Cod_Rota           = o.Cod_Rota,
             d.Des_LayoutPalm     = o.Des_LayoutPalm,
             d.Des_LayoutPde      = o.Des_LayoutPde,
             d.Cod_Vendedor       = o.Cod_Vendedor,
             d.Cod_VendTlmkt      = o.Cod_VendTlmkt,
             d.Cod_Digitador      = o.Cod_Digitador,
             d.Cod_Gerencia       = o.Cod_Gerencia,
             d.Cod_Supervisor     = o.Cod_Supervisor,
             d.Cod_GerOpe         = o.Cod_GerOpe,
             d.Cod_SupOpe         = o.Cod_SupOpe,
             d.Tip_Vencimento     = o.Tip_Vencimento,
             d.Qtd_PrzMed         = o.Qtd_PrzMed,
             d.Qtd_Parcela        = o.Qtd_Parcela,
             d.Qtd_Intervalo      = o.Qtd_Intervalo,
             d.Tip_DscPdv         = o.Tip_DscPdv,
             d.Num_Lote           = o.Num_Lote,
             d.Per_DescontoCom    = IsNull(o.Per_DescontoCom,0),
             d.Per_DescontoFin    = IsNull(o.Per_DescontoFin,0),
             d.Observacao         = o.Observacao,
             d.Msg_Bloqueio       = o.Msg_Bloqueio, 
             d.Obs_NotFis         = o.Obs_NotFis,  
             d.Tip_Consumidor     = o.Tip_Consumidor,
             d.Cod_PedRem         = o.Cod_PedRem,
             d.Cod_PedCli         = o.Cod_PedCli,
             d.Cod_Prz            = o.Cod_Prz,
             d.Cod_TabPrc         = o.Cod_TabPrc,
             d.Cod_PolCom         = o.Cod_PolCom,
             d.Id_PolCom          = o.Id_PolCom,
             d.Flg_MarkupCusCom   = IsNull(o.Flg_MarkupCusCom,0),
             d.Tip_SaiPdv         = o.Tip_SaiPdv,
             d.Tip_RatBon         = IsNull(o.Tip_RatBon,''),
             d.Tip_GerVrb         = o.Tip_GerVrb,
             d.Tip_Frete          = o.Tip_Frete,
             d.Cod_PedCmpCli      = o.Cod_PedCmpCli,
                                        
             d.Usuario            = o.Usuario,
             d.Transacao          = GetDate()
        From dbo.PDVCB d, dbo.PDVCB o
       Where d.Cod_Estabe = @CodEstabe
         And d.Numero = @CodPdvGer
         And o.Cod_Estabe = @CodEstabe 
         And o.Numero = @CodPed
  
      if (@TipDesdob = 'L')  -- Exists PDVLT
        begin
          Delete From dbo.PDVLT
           Where Cod_Estabe = @CodEstabe 
             and Cod_Pedido = @CodPdvGer
        end
  
      -- Variáveis para verificar se o pedido origem foi lido à partir de um pedido eletrônico (PDECB)
      Set @Pde_Num_Cnpj = ''
      Set @Pde_Cod_PedCli = ''
      Set @Pde_Num_Desdob = 0
  
      -- Se no pedido origem existir registro em PDECB, gravar um novo registro para o novo pedido gerado...
      -- Isso faz com que o retorno do arquivo de nota seja gerado no DMDPe. 
      if Exists(Select Num_Cnpj From dbo.PDECB Where Cod_Estabe = @CodEstabe And Num_PedVen = @CodPed)
        begin
          Select top 1
                 @Pde_Cod_Layout = Cod_Layout, 
                 @Pde_Num_Cnpj = RTRIM(Num_Cnpj),   
                 @Pde_Cod_PedCli = RTRIM(Cod_PedCli),
                 @Pde_Num_Desdob = Num_Desdob
            From dbo.PDECB
           Where Cod_Estabe = @CodEstabe 
             And Num_PedVen = @CodPed
  
          Set @Pde_Num_DesdobDes = Isnull((Select MAX(Num_Desdob) From dbo.PDECB Where Cod_Estabe = @CodEstabe And Cod_Layout = @Pde_Cod_Layout And Num_Cnpj = @Pde_Num_Cnpj And Cod_PedCli = @Pde_Cod_PedCli),0) + 1
    
          Exec _CopiaPDECB @CodEstabe, @Pde_Cod_Layout, @Pde_Num_Cnpj, @Pde_Cod_PedCli, @Pde_Num_Desdob, @Pde_Num_DesdobDes, @CodPdvGer
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end
        end
        
      -- muda o bloqueio temporariamente para nao decrementar saldos
      Update dbo.PDVCB
         Set Bloqueio = 'SR',
             Flg_Calc = 1
  		   -- Flg_CriIteFec = 0    p/ bonificação
       Where Cod_Estabe = @CodEstabe     
         And Numero = @CodPed
  
  	Set @WCodPrdAnt = -1
  
      if (@TipDesdob = 'I')
        begin
          -- seleciona itens de pedidos "incentivados"
          Declare PDVIT_Cr Cursor Local Fast_Forward For 
  
            Select it.Cod_Produto, it.Cod_Lote, it.Tip_Sai,
                   it.Qtd_Pedido, it.Qtd_Bonificacao, it.Qtd_Pra, it.Qtd_Dep
              From dbo.PDVIT it 
                   Inner Join dbo.PRODU pr on it.Cod_Produto = pr.Codigo 
             Where it.Cod_Estabe = @CodEstabe 
               and it.Cod_Pedido = @CodPed 
               and it.Qtd_Pedido > 0
               and dbo.FN_ProdutoIncentivado(it.Cod_Estabe,it.Cod_Produto,@WIdIncFis) = 1
             Order by C_PrcTotal Desc
        end
  
      if (@TipDesdob = 'B')
        begin
          -- seleciona itens de pedidos não genericos/similares
          Declare PDVIT_Cr Cursor Local Fast_Forward For 
  
            Select it.Cod_Produto, it.Cod_Lote, it.Tip_Sai,
                   it.Qtd_Pedido, it.Qtd_Bonificacao, it.Qtd_Pra, it.Qtd_Dep
              From dbo.PDVIT it 
             Where it.Cod_Estabe = @CodEstabe 
               and it.Cod_Pedido = @CodPed 
               and it.Qtd_Bonificacao > 0
             Order by C_PrcTotal Desc
        end
  
      if (@TipDesdob = 'G')
        begin
          -- seleciona itens de pedidos não genericos/similares
          Declare PDVIT_Cr Cursor Local Fast_Forward For 
  
            Select it.Cod_Produto, it.Cod_Lote, it.Tip_Sai,
                   it.Qtd_Pedido, it.Qtd_Bonificacao, it.Qtd_Pra, it.Qtd_Dep
              From dbo.PDVIT it 
                   Inner Join dbo.PRODU pr on it.Cod_Produto = pr.Codigo 
             Where it.Cod_Estabe = @CodEstabe 
               and it.Cod_Pedido = @CodPed 
               and it.Qtd_Pedido > 0
               and ((pr.Cod_GrpPrc <> 'G') and (pr.Cod_GrpPrc <> 'S'))
             Order by C_PrcTotal Desc
        end
  
      if (@TipDesdob = 'L')
        begin
          -- seleciona itens de pedidos com mais de um lote
          Declare PDVIT_Cr Cursor Local Fast_Forward For 
  
            Select it.Cod_Produto, it.Cod_Lote, it.Tip_Sai,
                   it.Qtd_Pedido, it.Qtd_Bonificacao, it.Qtd_Pra, it.Qtd_Dep
              From dbo.PDVIT it
             Where it.Cod_Estabe = @CodEstabe
               And it.Cod_Pedido = @CodPed
               And it.Qtd_Pedido > 0
               And Exists(Select Cod_Produto, count(*)
                            From dbo.PDVIT
                           Where Cod_Estabe = @CodEstabe
                             And Cod_Pedido = @CodPed
                             And Qtd_Pedido > 0
                             And Cod_Produto = it.Cod_Produto
                           Group by Cod_Produto
                          Having count(*) > 1)
             Order by it.Cod_Produto, it.Tip_Sai desc, it.C_PrcTotal desc
        end
  
      Open PDVIT_Cr
      Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_CodLot, @it_TipSai,
                                    @it_QtdPed, @it_QtdBon, @it_QtdPra, @it_QtdDep
      While @@FETCH_STATUS = 0
      begin
  	    Set @WFlgIncIte = 0
  
          -- normaliza estoques
          if @it_QtdPra < 0
            Set @it_QtdPra = 0
          if @it_QtdDep < 0
            Set @it_QtdDep = 0  
          if (@it_QtdPra+@it_QtdDep) <> (@it_QtdPed+@it_QtdBon)
            Set @it_QtdPra = @it_QtdPed + @it_QtdBon - @it_QtdDep
  
          Set @nw_QtdPra = @it_QtdPra
          Set @nw_QtdDep = @it_QtdDep
  
          if (@TipDesdob = 'L') and (@WCodPrdAnt = @it_CodPrd)
            Set @WFlgIncIte = 1
          else
          if (@TipDesdob = 'I')
            Set @WFlgIncIte = 1
  		else
          if (@TipDesdob = 'G')
            Set @WFlgIncIte = 1
  		else
          if (@TipDesdob = 'B')
            begin
              Set @WFlgIncIte = 1
  
              Set @nw_QtdPra = 0
              Set @nw_QtdDep = 0
  
              -- determina estoque 2
              if @it_QtdDep > 0
                if @it_QtdDep > @it_QtdBon
                  begin
                    Set @nw_QtdDep = @it_QtdBon
                    Set @it_QtdDep = @it_QtdDep - @it_QtdBon
                  end
                 else
                   begin
                    Set @nw_QtdDep = @it_QtdDep
                    Set @it_QtdDep = 0
                   end
        
              -- determina estoque 1
              if @nw_QtdDep < @it_QtdBon
                if @it_QtdPra > 0
                  if @it_QtdPra > (@it_QtdBon-@nw_QtdDep)
                    begin
                      Set @nw_QtdPra = (@it_QtdBon-@nw_QtdDep)
                      Set @it_QtdPra = @it_QtdPra - (@it_QtdBon-@nw_QtdDep)
                    end
                  else
                    begin
                      Set @nw_QtdPra = @it_QtdPra
                      Set @it_QtdPra = 0
                    end
        
              -- normaliza estoques 
              if (@it_QtdPra+@it_QtdDep) <> @it_QtdPed
                Set @it_QtdPra = @it_QtdPed - @it_QtdDep
  
              if @nw_QtdPra < 0
                Set @nw_QtdPra = 0
              if @nw_QtdDep < 0
                Set @nw_QtdDep = 0
              if (@nw_QtdPra+@nw_QtdDep) <> @it_QtdBon
                Set @nw_QtdPra = @it_QtdBon - @nw_QtdDep
  
            end  -- if (@TipDesdob = 'B')
  
          -- inclui item novo pedido
  		if @WFlgIncIte = 1
  		  begin
              Insert into dbo.PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai)
                Values (@CodEstabe, @CodPdvGer, @it_CodPrd, @it_CodLot, @it_TipSai)
              if @@error <> 0
                begin
                  if @@trancount > 0
                    Rollback Transaction
                  Return
                end
  
              Update d
                Set d.Qtd_Pedido          = Case 
                                              When @TipDesdob = 'B' then @it_QtdBon 
                                              Else @it_QtdPed 
                                             End,
                    d.Qtd_Bonificacao     = Case 
                                              When @TipDesdob = 'B' then 0 
                                              Else @it_QtdBon 
                                             End,
                    d.Qtd_Solicitado      = Case 
                                              When @TipDesdob = 'B' then @it_QtdBon 
                                              Else o.Qtd_Solicitado 
                                             End,
                    d.Qtd_ImpFat          = Case 
                                              When @TipDesdob = 'B' then @it_QtdBon*1.0/o.Fat_CnvImpFat 
                                              Else (@it_QtdPed+@it_QtdBon)*1.0/o.Fat_CnvImpFat
                                             End,
                    d.Qtd_Pra             = @nw_QtdPra,
                    d.Qtd_Dep             = @nw_QtdDep,
  
                    d.Prc_Unitario        = o.Prc_Unitario,
                    d.Per_Desconto        = IsNull(o.Per_Desconto,0),
                    d.Per_Descon          = IsNull(o.Per_Descon,0),
                    d.Per_DscVis          = IsNull(o.Per_DscVis,0),
                    d.C_PrcUni            = o.C_PrcUni,
                    d.C_PerDscIte         = IsNull(o.C_PerDscIte,0),
                    d.C_VlrDesconto       = o.C_VlrDesconto,
                    d.C_PrcTotal          = o.C_PrcTotal,
                    d.Fat_CnvImpFat       = o.Fat_CnvImpFat,
                    d.Prc_UniImpFat       = o.Prc_Unitario*o.Fat_CnvImpFat,
                    d.Des_UnvImpFat       = o.Des_UnvImpFat,
                    d.Des_AprImpFat       = o.Des_AprImpFat,
  
                    d.Loc_Fisica          = o.Loc_Fisica,
                    d.Cod_Fabricante      = o.Cod_Fabricante,
                    d.Cod_Promocao        = o.Cod_Promocao,
                    d.Qtd_PrzMax          = o.Qtd_PrzMax,
                    d.Prc_Tabela          = o.Prc_Tabela,
                    d.Prc_TabBru          = o.Prc_TabBru,
                    d.Flg_PrcUniDsc       = IsNull(o.Flg_PrcUniDsc,0),
                    d.Desconto            = IsNull(o.Desconto,0),
                    d.Flg_BlqInfPar       = IsNull(o.Flg_BlqInfPar,0),
  									    
                    d.Prc_MaxCon          = o.Prc_MaxCon,
                    d.Prc_Fabric          = o.Prc_Fabric,
                    d.Num_SeqDig          = o.Num_SeqDig,
                    d.Nom_UsuDesbloq      = o.Nom_UsuDesbloq,
                                                      
                    d.Id_PolCom           = o.Id_PolCom,
                    d.Flg_Verba           = IsNull(o.Flg_Verba,0),
                    d.Prc_PolCom          = o.Prc_PolCom,
                    d.Per_DscPolCom       = IsNull(o.Per_DscPolCom,0),
                    d.Per_DscVisPolCom    = IsNull(o.Per_DscVisPolCom,0),
                    d.Prc_CusMinComMarkup = IsNull(o.Prc_CusMinComMarkup,0),
                    d.Cod_KitPrm          = IsNull(o.Cod_KitPrm,0),
  
                    d.Vlr_BasVerba        = IsNull(o.Vlr_BasVerba,0),
                    d.Per_VrbPar          = IsNull(o.Per_VrbPar,0),
                    d.Vlr_VrbPar          = IsNull(o.Vlr_VrbPar,0),
                    d.Per_VrbBon          = IsNull(o.Per_VrbBon,0),
                    d.Vlr_VrbBon          = IsNull(o.Vlr_VrbBon,0),
                    d.Vlr_Bonificacao     = IsNull(o.Vlr_Bonificacao,0),
                    d.Vlr_DscBonRat       = IsNull(o.Vlr_DscBonRat,0),
  
                    d.Cod_PrjPde          = o.Cod_PrjPde,
                    d.Prc_UniPde          = IsNull(o.Prc_UniPde,0),
                    d.Per_DscPde          = IsNull(o.Per_DscPde,0),
                    d.Num_SeqPdc          = o.Num_SeqPdc
               From dbo.PDVIT d, dbo.PDVIT o
              Where d.Cod_Estabe  = o.Cod_Estabe
                And d.Cod_Pedido  = @CodPdvGer
                And d.Cod_Produto = o.Cod_Produto
                And d.Cod_Lote    = o.Cod_Lote
                And d.Tip_Sai     = o.Tip_Sai
  
                And o.Cod_Estabe  = @CodEstabe 
                And o.Cod_Pedido  = @CodPed
                And o.Cod_Produto = @it_CodPrd 
                And o.Cod_Lote    = @it_CodLot
                And o.Tip_Sai     = @it_TipSai
  
              if (@TipDesdob = 'L')  -- Exists PDVLT
                begin
                  if not Exists(Select 1 From dbo.PDVLT 
                                 Where Cod_Estabe = @CodEstabe
                                   And Cod_Pedido = @CodPdvGer
                                   And Cod_Produt = @it_CodPrd
                                   And Cod_Lote = @it_CodLot)
                    begin
                      Insert Into dbo.PDVLT (Cod_Estabe, Cod_Pedido, Num_Vol, Cod_Produt, Cod_Lote, Qtd_Lote, Qtd_CxaFec,
               	                             Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis,
               		                         Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Qtd_EmbFec, Flg_Desord, Cod_FunSep, Transacao)
                        Select @CodEstabe, @CodPdvGer, 1, Cod_Produt, Cod_Lote, Qtd_Lote, Qtd_CxaFec,
               	               Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis,
               		           Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Qtd_EmbFec, Flg_Desord, Cod_FunSep, Transacao
               	          From dbo.PDVLT
                         Where Cod_Estabe = @CodEstabe 
                           and Cod_Pedido = @CodPed 
                           and Cod_Produt = @it_CodPrd 
                           and Cod_Lote   = @it_CodLot
                      if @@error <> 0
                        begin
                          if @@trancount > 0
                            Rollback Transaction
                          Return
                        end
               
                      -- elimina rgistro origem
                      Delete From dbo.PDVLT
                       Where Cod_Estabe = @CodEstabe 
                         and Cod_Pedido = @CodPed 
                         and Cod_Produt = @it_CodPrd 
                         and Cod_Lote   = @it_CodLot
               	    end
                end  -- if (@TipDesdob = 'L')
  
              if Exists(Select it.Cod_Produt 
                          From dbo.PDEIT it Inner Join 
                               dbo.PDECB cb on ((it.Cod_Estabe = cb.Cod_Estabe) and (it.Cod_Layout = cb.Cod_Layout) and (it.Num_Cnpj = cb.Num_Cnpj) and (it.Cod_PedCli = cb.Cod_PedCli) and (it.Num_Desdob = cb.Num_Desdob)) 
                         Where it.Cod_Estabe = @CodEstabe      
                           and it.Cod_Layout = @Pde_Cod_Layout
                           and it.Num_Cnpj   = @Pde_Num_Cnpj 
                           and it.Cod_PedCli = @Pde_Cod_PedCli 
                           and it.Cod_Produt = @it_CodPrd 
                           and cb.Num_PedVen = @CodPed
                           and @Pde_Num_Cnpj <> '')
                begin
                  -- salvando produto que será deletado
                  Select @Pdeit_Num_Desdob = it.Num_Desdob,
                         @Pdeit_Cod_PrdCli = it.Cod_PrdCli
                    From dbo.PDEIT it Inner Join 
                         dbo.PDECB cb on ((it.Cod_Estabe = cb.Cod_Estabe) and 
                                          (it.Cod_Layout = cb.Cod_Layout) and 
                                          (it.Num_Cnpj   = cb.Num_Cnpj) and 
                                          (it.Cod_PedCli = cb.Cod_PedCli) and 
                                          (it.Num_Desdob = cb.Num_Desdob)) 
                   Where it.Cod_Estabe = @CodEstabe      
                     and it.Cod_Layout = @Pde_Cod_Layout
                     and it.Num_Cnpj   = @Pde_Num_Cnpj 
                     and it.Cod_PedCli = @Pde_Cod_PedCli 
                     and it.Cod_Produt = @it_CodPrd 
                     and cb.Num_PedVen = @CodPed
  
      			  -- transfere registro, eliminando origem
                  Exec _CopiaItemPDEIT @CodEstabe, @Pde_Cod_Layout, @Pde_Num_Cnpj, @Pde_Cod_PedCli, @Pdeit_Num_Desdob, @Pdeit_Cod_PrdCli, @Pde_Num_DesdobDes, 1 
                  if @@error <> 0
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end
  
                  if @TipDesdob = 'B'
                    begin
                      -- atualiza registro destino
                      Update dbo.PDEIT                          
                         Set Qtd_Pedido = @it_QtdBon,
                             Qtd_Atendi = 0
                       Where Cod_Estabe = @CodEstabe                  
                         and Cod_Layout = @Pde_Cod_Layout
                         and Num_Cnpj   = @Pde_Num_Cnpj
                         and Cod_PedCli = @Pde_Cod_PedCli 
                         and Num_Desdob = @Pde_Num_DesdobDes
                         and Cod_PedCli = @Pdeit_Cod_PrdCli
               
                      -- atualiza registro origem
                      Update dbo.PDEIT                          
                         Set Qtd_Pedido = Case
                                            When Qtd_Pedido > @it_QtdBon Then Qtd_Pedido - @it_QtdBon
                                            Else 1
                                          End
                       Where Cod_Estabe = @CodEstabe                  
                         and Cod_Layout = @Pde_Cod_Layout
                         and Num_Cnpj = @Pde_Num_Cnpj
                         and Cod_PedCli = @Pde_Cod_PedCli 
                         and Num_Desdob = @Pdeit_Num_Desdob
                         and Cod_PedCli = @Pdeit_Cod_PrdCli
  
                    end  -- if @TipDesdob = 'B'
  
                end  -- if Exists(
  
              -- atualiza item do pedido origem
              if @TipDesdob <> 'B'
                begin
                  Delete From dbo.PDVIT 
                   Where Cod_Estabe  = @CodEstabe 
                     and Cod_Pedido  = @CodPed 
                     and Cod_Produto = @it_CodPrd 
                     and Cod_Lote    = @it_CodLot
                     and Tip_Sai     = @it_TipSai
                end
              else
                begin
                  -- atualiza item do pedido de origem
                  -- tributos sao recalculados na triggeer
                  Update dbo.PDVIT
                     Set Qtd_Bonificacao = 0,
                         Qtd_Solicitado = Qtd_Solicitado - @it_QtdBon,
                         Qtd_Pra = @it_QtdPra,
                         Qtd_Dep = @it_QtdDep,
                         Qtd_ImpFat = Qtd_Pedido*1.0/Fat_CnvImpFat
                   Where Cod_Estabe  = @CodEstabe     
                     and Cod_Pedido  = @CodPed 
                     and Cod_Produto = @it_CodPrd 
                     and Cod_Lote    = @it_CodLot
                     and Tip_Sai     = @it_TipSai
                end
  
  		  end  -- if @WFlgIncIte = 1
  
            Set @WCodPrdAnt = @it_CodPrd
  
          Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_CodLot, @it_TipSai,
                                        @it_QtdPed, @it_QtdBon, @it_QtdPra, @it_QtdDep
      end
        
      Close PDVIT_Cr
      Deallocate PDVIT_Cr
  
      --  pedido origem
      Update dbo.PDVCB
         Set Bloqueio = @cb_BlqAnt,
             Flg_Calc = 0
       Where Cod_Estabe = @CodEstabe     
         And Numero = @CodPed
  
      Exec PR_AtualizaCabecPDV @CodEstabe, @CodPed
      if @@error <> 0
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end

      if (@TipDesdob = 'I') or
         (@TipDesdob = 'G') or
         (@TipDesdob = 'B')
        begin
          --  pedido origem
          Update dbo.PDVCB
             Set Flg_CriIteFec = 0
           Where Cod_Estabe = @CodEstabe     
             And Numero = @CodPed
  
          if @TipDesdob = 'B'
            Update dbo.PDVCB
               Set Num_PdvLig = @CodPdvGer
                   --Num_PdvFilho = @CodPdvGer,
             Where Cod_Estabe = @CodEstabe     
               And Numero = @CodPed
          else
            Delete From dbo.PDVDP
             Where Cod_Estabe = @CodEstabe 
               And Cod_Pedido = @CodPed
  
          --  Pedido gerado
          Update dbo.PDVCB
             Set Bloqueio = @cb_BlqAnt,
                 Status2 = 'A',
                 Cod_OrigemPdv = Case 
                                   When @TipDesdob = 'B' then 'D'+Substring(@cb_CodOriPdv,2,1) 
                                   Else @cb_CodOriPdv 
                                 End,
                 Flg_JaFechado = 0,
                 Flg_Calc = 0,
                 Flg_CriIteFec = 0
           Where Cod_Estabe = @CodEstabe     
             And Numero = @CodPdvGer
        end
  
      if (@TipDesdob = 'L')
        begin
          Exec PR_CalculaVencPDV @CodEstabe, @CodPed
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end
  
          --  Pedido gerado
          Update d
             Set d.Bloqueio = o.Bloqueio,
                 d.Status1 = o.Status1,
                 d.Status2 = o.Status2,
                 d.Flg_JaFechado = o.Flg_JaFechado,
                 d.Flg_CriIteFec = o.Flg_CriIteFec,
                 d.Flg_Calc = 0
            From dbo.PDVCB d, dbo.PDVCB o
           Where d.Cod_Estabe = @CodEstabe     
             And d.Numero = @CodPdvGer
             And o.Cod_Estabe = @CodEstabe     
             And o.Numero = @CodPed
  
          Exec PR_CalculaVencPDV @CodEstabe, @CodPdvGer
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end
        end
  
      -- Atualizar PDECB dos pedidos
      if @Pde_Num_Cnpj <> ''
        Update cb
           Set cb.Vlr_Total = IsNull(it.VlrTot,0)
          From dbo.PDECB cb Inner Join 
               (Select Cod_Estabe, Cod_Layout, Num_Cnpj, Cod_PedCli, Num_Desdob,
                       VlrTot = sum(Round(Qtd_Pedido*Prc_Unitario*(1-IsNull(Per_Desconto,0)/100),2)) 
                  From dbo.PDEIT
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_Layout = @Pde_Cod_Layout
                   And Num_Cnpj   = @Pde_Num_Cnpj
                   And Cod_PedCli = @Pde_Cod_PedCli
                 Group by Cod_Estabe, Cod_Layout, Num_Cnpj, Cod_PedCli, Num_Desdob) it on ((cb.Cod_Estabe = it.Cod_Estabe) and
                                                                                           (cb.Cod_Layout = it.Cod_Layout) and
                                                                                           (cb.Num_Cnpj   = it.Num_Cnpj) and 
                                                                                           (cb.Cod_PedCli = it.Cod_PedCli) and 
                                                                                           (cb.Num_Desdob = it.Num_Desdob))
         Where cb.Cod_Estabe = @CodEstabe
           And cb.Cod_Layout = @Pde_Cod_Layout
           And cb.Num_Cnpj   = @Pde_Num_Cnpj
           And cb.Cod_PedCli = @Pde_Cod_PedCli
           And cb.Num_Desdob = @Pde_Num_Desdob
  
      if @@trancount > 0
        Commit Transaction
    end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_FecAutPDV]
@PCodEstabe int,
@PNumPdv int,
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now  = GetDate()
Set @Date = cast(GetDate() as date)

/*
if Charindex((Select Status2 From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv),';N;D;') > 0 
  RAISERROR('Pedido já faturado',16,1)
else
if Charindex((Select Status2 From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv),';F;') > 0 
  RAISERROR('Pedido já fechado',16,1)
else
*/

if Exists(Select 1 From PDVCB  Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv) and
   (Charindex((Select Status2 From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv),';N;D;F;') = 0)
BEGIN
Begin Transaction

Declare @pv_CodTipPed varchar(3),  -- 'PDV','COT'
        @pv_TipFat varchar(3) = '',
        @pv_TipPrz varchar(1) = '',
        @pv_OriPdv varchar(1) = '',
		@pv_IdPolCom int = 0,
        @pv_CodRegTri int = 0,
		@pv_CodCli int = 0,
        @pv_VlrLiqIte numeric(18,4),
		@pv_TipVct varchar(1),            -- Tip_Vencimento original
		@P_TipVct varchar(1),             -- Tip_Vencimento a gravar
		@P_CodPrz int = 0,                -- Cod_Prz
		@P_QtdPrzMed numeric(18,8) = 0,   -- Qtd_PrzMed
		@P_QtdParcela int = 0,            -- Qtd_ParPrz
		@P_QtdIntervalo int = 0,          -- Qtd_Intervalo
		@P_PerDescontoCom numeric(18,8),  -- Per_DescontoCom
		@P_PerDescontoFin numeric(18,8),  -- Per_DescontoFin

        @pm_FlgBlqVenCliSemLimCre bit = 0,
        @pm_QtdDiaDupVis int = 0,		 
        @pc_FlgSugDscGlbPdv bit = 0,
        @pc_PerDscComVis numeric (18,8) = 0,
        @pc_PerDscComPrz numeric (18,8) = 0,
        @pc_PerDscFinVis numeric (18,8) = 0,
        @pc_PerDscFinPrz numeric (18,8) = 0,
        @op_FlgCodCli bit = 0,
        @op_FlgLanFin bit = 0,
        @op_QtdMaxDup int = 0,
        @op_VlrMinDup numeric(18,4) = 0,

		@WFlgPdvOk bit = 0,
		@WCodPrd int = 0,
		@WSldCreCli numeric(18,4) = 0,
        @WMsgObs varchar(8000),
        @WMsgAux varchar(8000),
        @WSta smallint,
        @WStaLic varchar(1),
        @WCodMtv varchar(3),
		@WCodPdvInc int = 0,
		@WCodPdvGen int = 0,
		@WCodPdvBon int = 0

-- verifica se rateia descontos por bonificacao
Exec PR_RateiaDescontoBonificacaoPDVCB @PCodEstabe, @PNumPdv
if @@error <> 0
  begin
    if @@trancount > 0
      Rollback Transaction
    Return
  end    

Select @pm_FlgBlqVenCliSemLimCre = IsNull(FlgBlqVenCliSemLimCre,0),
       @pm_QtdDiaDupVis = IsNull(QtdDiaDupVis,0)
  From PARAM
 Where Cod_Estabe = @PCodEstabe

Select @pv_CodTipPed = Case When cb.Tip_Pedido = 'C' then 'COT' Else'PDV' End,
       @pv_TipFat = IsNull(cb.Tip_Faturamento,''),
       @pv_OriPdv = Substring(IsNull(cb.Cod_OrigemPdv,''),1,1),
       @pv_TipPrz = Substring(IsNull(cb.Cod_OrigemPdv,''),2,1),
	   @pv_IdPolCom = IsNull(cb.Id_PolCom,0),
	   @pv_CodRegTri = IsNull(cb.Cod_RegTri,0),
       @pv_CodCli = IsNull(cb.Cod_Cliente,0),
       @pv_VlrLiqIte = IsNull(cb.Vlr_LiqItens,0),
	   @pv_TipVct = IsNull(cb.Tip_Vencimento,''),
       @WMsgObs = IsNull(cb.Observacao,''),
	   @P_CodPrz = IsNull(cb.Cod_Prz,0),
	   @P_QtdPrzMed = IsNull(cb.Qtd_PrzMed,0),
	   @P_QtdParcela = IsNull(cb.Qtd_Parcela,0),
       @P_QtdIntervalo = IsNull(cb.Qtd_Intervalo,0),
       @P_PerDescontoCom = IsNull(cb.Per_DescontoCom,0),
       @P_PerDescontoFin = IsNull(cb.Per_DescontoFin,0),

       @pc_FlgSugDscGlbPdv = IsNull(pc.Flg_SugDscGlbPdv,0),
       @pc_PerDscComVis = IsNull(pc.Per_DscComVis,0), 
       @pc_PerDscComPrz = IsNull(pc.Per_DscCom,0), 
       @pc_PerDscFinVis = IsNull(pc.Per_DscFinVis,0), 
       @pc_PerDscFinPrz = IsNull(pc.Per_DscFin,0) 

  From PDVCB cb
       Left Join POCOM pc on cb.Id_PolCOm = pc.Id_PolCom
 Where cb.Cod_Estabe = @PCodEstabe
   And cb.Numero = @PNumPdv

Set @WFlgPdvOk = 0
Set @PMsgErr = ''
Set @P_TipVct = ''

if @pv_IdPolCom > 0 
  begin
    if @pv_TipPrz = 'F'
      begin
        Set @WFlgPdvOk = 1
        Set @P_TipVct = 'C'
      end
    else
    if (@pv_TipPrz = 'L') and (@P_CodPrz = 0)
      begin
        Set @P_CodPrz = dbo.FN_SugerePrazoPDVCB (@PCodEstabe, @pv_OriPdv, @pv_CodCli, @pv_IdPolCom, cast(@P_QtdPrzMed as int), @P_QtdParcela, @pv_VlrLiqIte)
        if @P_CodPrz = 0
          begin
            Set @WMsgAux = 'Não existe prazo que atende ao pedido'
            if Charindex(@WMsgAux,@WMsgObs) = 0  
              begin
                if DataLength(@WMsgObs) > 0 Set @WMsgObs = @WMsgObs + ';'
                Set @WMsgObs = @WMsgObs + @WMsgAux
              end
          end
      end
  end

if (@P_CodPrz > 0) and
   Exists(Select 1 From PRZCB Where Cod_Prz = @P_CodPrz And Flg_ParOk = 1) 
  begin
    Set @P_QtdPrzMed = 0
	Set @P_QtdParcela = 0

    Select @P_QtdPrzMed = Qtd_PrzMed, 
           @P_QtdParcela = Qtd_ParPrz 
      From PRZCB 
     Where Cod_Prz = @P_CodPrz
       And Flg_ParOk = 1 

    Set @WFlgPdvOk = 1
    Set @P_TipVct = 'T'
  end

if @pv_TipVct = 'V' 
  begin
    Set @P_TipVct = 'V'
    Set @P_CodPrz = 0
    Set @P_QtdPrzMed = @pm_QtdDiaDupVis
	Set @P_QtdParcela = 1
    Set @P_QtdIntervalo = 0

    Set @WFlgPdvOk = 1
  end

-- verifica tributacao
Set @WCodPrd = 0

Select top 1 @WCodPrd = it.Cod_Produto
  From PDVIT it 
       Left Join RTXCT rx on rx.Cod_RegTri = @pv_CodRegTri and it.Cod_ClaTri = rx.Cod_ClaTri 
 Where it.Cod_Estabe = @PCodEstabe
   And it.Cod_Pedido = @PNumPdv
   And it.Qtd_Pedido > 0
   And rx.Cod_RegTri is null 

if IsNull(@WCodPrd,0) > 0
  begin
    Set @WFlgPdvOk = 0
    Set @WMsgAux = 'Existe pelo menos 1 item ('+CAST(@WCodPrd as varchar)+') com tributacao nao configurada'

    if DataLength(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + char(13)+char(10)
    Set @PMsgErr = @PMsgErr + @WMsgAux

    if Charindex(@WMsgAux,@WMsgObs) = 0  
      begin
        if DataLength(@WMsgObs) > 0 Set @WMsgObs = @WMsgObs + char(13)+char(10)
        Set @WMsgObs = @WMsgObs + @WMsgAux
      end
  end

-- verifica fabricante
Set @WCodPrd = 0

Select top 1 @WCodPrd = it.Cod_Produto
  From PDVIT it 
       Inner Join PRODU pr on it.Cod_Produto = pr.Codigo 
 Where it.Cod_Estabe = @PCodEstabe
   And it.Cod_Pedido = @PNumPdv
   And it.Qtd_Pedido > 0
   And it.Cod_Fabricante <> pr.Cod_Fabricante 

if IsNull(@WCodPrd,0) > 0
  begin
    Set @WFlgPdvOk = 0
    Set @WMsgAux = 'Existe pelo menos 1 item ('+CAST(@WCodPrd as varchar)+') com fabricante <> cadastro'

    if DataLength(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + char(13)+char(10)
    Set @PMsgErr = @PMsgErr + @WMsgAux

    if Charindex(@WMsgAux,@WMsgObs) = 0  
      begin
        if DataLength(@WMsgObs) > 0 Set @WMsgObs = @WMsgObs + char(13)+char(10)
        Set @WMsgObs = @WMsgObs + @WMsgAux
      end
  end

-- verifica verba
Exec PR_MsgCriticaVerbaPdv @PCodEstabe, @PNumPdv, @WMsgAux Output
if @WMsgAux <> ''
  begin
    Set @WFlgPdvOk = 0

    if DataLength(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + char(13)+char(10)
    Set @PMsgErr = @PMsgErr + @WMsgAux

    if Charindex(@WMsgAux,@WMsgObs) = 0  
      begin
        if DataLength(@WMsgObs) > 0 Set @WMsgObs = @WMsgObs + char(13)+char(10)
        Set @WMsgObs = @WMsgObs + @WMsgAux
      end
  end


if (@WFlgPdvOk = 0) and
   (CharIndex(@pv_OriPdv,';M;T;W;') > 0) and
   (DataLength(@WMsgObs) > 0)
  begin
    Update PDVCB
       Set Observacao = @WMsgObs
     Where Cod_Estabe = @PCodEstabe
       And Numero = @PNumPdv
  end
else
if @WFlgPdvOk = 1
  begin
    if (@pv_IdPolCom > 0) and
       (@pc_FlgSugDscGlbPdv = 1)
      begin
        if @P_TipVct = 'V'
          begin
            if @P_PerDescontoCom = 0 
              Set @P_PerDescontoCom = @pc_PerDscComVis
            if @P_PerDescontoFin = 0 
              Set @P_PerDescontoFin = @pc_PerDscFinVis
          end
        else
          begin
            if @P_PerDescontoCom = 0
               Set @P_PerDescontoCom = @pc_PerDscComPrz
            if @P_PerDescontoFin = 0 
              Set @P_PerDescontoFin = @pc_PerDscFinPrz
          end
      end

    Update PDVCB
       Set Tip_Vencimento =	@P_TipVct,
           Cod_Prz = @P_CodPrz,
           Qtd_PrzMed =	@P_QtdPrzMed,
           Qtd_Parcela = @P_QtdParcela,
           Qtd_Intervalo = @P_QtdIntervalo,
           Per_DescontoCom = @P_PerDescontoCom,
           Per_DescontoFin = @P_PerDescontoFin
     Where Cod_Estabe = @PCodEstabe
       And Numero = @PNumPdv

    Exec PR_CalculaVencPDV @PCodEstabe, @PNumPdv
	if @@ERROR <> 0
      begin
        if @@trancount > 0
          Rollback Transaction
		Return
      end

    -- critica se houver alteração do tipo de faturanebto(operação)
    Exec PR_CriticaFecPDV @pv_TipFat, @PCodEstabe, @PNumPdv
	if @@ERROR <> 0
      begin
        if @@trancount > 0
          Rollback Transaction
		Return
      end

    -- aqui faz outras criticas
    Set @op_FlgCodCli = 0
    Set @op_FlgLanFin = 0
    Set @op_QtdMaxDup = 0
    Set @op_VlrMinDup = 0
    if not Exists(Select 1 
                    From TPOPE op 
                         Inner Join PDVCB cb on op.Cod_Ope = cb.Tip_Faturamento 
                   Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv)
      begin
        Set @WFlgPdvOk = 0
        if DataLength(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + char(13)+char(10)
        Set @PMsgErr = @PMsgErr + 'Tipo de Operação invalida'
      end
    else
      begin
        Select @op_FlgCodCli = IsNull(Flg_CodCli,0), 
               @op_FlgLanFin = IsNull(Flg_LanFin,0), 
               @op_QtdMaxDup = IsNull(Qtd_MaxDup,0), 
               @op_VlrMinDup = IsNull(Vlr_MinDup,0)
          From TPOPE op 
               Inner Join PDVCB cb on op.Cod_Ope = cb.Tip_Faturamento 
         Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv        
      end

    -- data de vencimentos e valores dos titulos
    if (@op_FlgCodCli = 1) and (@op_FlgLanFin = 1)
      begin
        if (Select Round(C_VlrPedido,2) From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv) <>
           (Select Round(sum(Vlr_Duplic),2) From PDVDP Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PNumPdv)
          begin
            Set @WFlgPdvOk = 0
            if DataLength(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + char(13)+char(10)
            Set @PMsgErr = @PMsgErr + 'Valor do Pedido x Titulos divergentes'
          end

        if Exists(Select 1 From PDVDP Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PNumPdv And Vlr_Duplic < @op_VlrMinDup)
          begin
            Set @WFlgPdvOk = 0
            if DataLength(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + char(13)+char(10)
            Set @PMsgErr = @PMsgErr + 'Existe pelo menos 1 Titulo com valor menor que o minimo permitido'
          end
      end

    if @WFlgPdvOk = 1
      begin
        Exec PR_AnalisaCreditoCliente @pv_CodTipPed, @PCodEstabe, @pv_CodCli, @PNumPdv, 
                                      @WMsgAux output,
                                      @WSta output,
                                      @WStaLic output,
                                      @WCodMtv output

        Set @WSldCreCli = IsNull((Select dbo.FN_SaldoCreditoCliente(@pv_CodCli)),0)

        Update PDVCB
           Set Bloqueio = Case 
		                    When @WSta > 1 Then 'CR' 
                            When Round(C_VlrPedido,2) > @WSldCreCli then 'CR' 
                            Else '' 
                          End,
               Msg_Bloqueio = Case 
                                When Round(C_VlrPedido,2) > @WSldCreCli then 'ESTOUROU LIM. DE CRÉDITO' 
                                Else '' 
                              End,
               Flg_Credito = @WSta,
               Cod_BlqLic = @WStaLic,
               Cod_MtvRej = @WCodMtv
         Where Cod_Estabe = @PCodEstabe
           And Numero = @PNumPdv

        -- bloqueia cliente se for o caso
        if @pm_FlgBlqVenCliSemLimCre = 1
          Update cl
             Set cl.Bloqueado = 1,
                 cl.Motivo_Bloqueio = 'Bloq. auto. por lim. de créd.'
            From PDVCB cb
		         Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
           Where cb.Cod_Estabe = @PCodEstabe
             And cb.Numero = @PNumPdv
             And IsNull(cl.Bloqueado,0) = 0
             And Round(cb.C_VlrPedido,2) > @WSldCreCli

        -- desdobra incentivos fiscais
        Exec PR_DesdobraPDV 'I', @PCodEstabe, @PNumPdv, @WCodPdvInc Output

        -- desdobra genericos/similares
        Exec PR_DividePDVGen @PCodEstabe, @PNumPdv, @WCodPdvGen output 

        -- desdobra bonificacoes
        Exec PR_DividePDVBon @PCodEstabe, @PNumPdv, @WCodPdvBon output 


        --  fecha pedido
        Exec PR_FechaPDV @PCodEstabe, @PNumPdv, 'F'

        if @WCodPdvInc > 0 
          begin
            Exec PR_FecAutPdv @PCodEstabe, @WCodPdvInc, @WMsgAux output
          end

        if @WCodPdvGen > 0 
          begin
            Exec PR_FecAutPdv @PCodEstabe, @WCodPdvGen, @WMsgAux output
          end

        if @WCodPdvBon > 0 
          begin
            Exec PR_FecAutPdv @PCodEstabe, @WCodPdvBon, @WMsgAux output
          end

      end
   end   --  if @WFlgPdvOk = 1

if @@trancount > 0
  Commit Transaction
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_PDVCB_AtualizaCampos] ON [dbo].[PDVCB] 
FOR INSERT, UPDATE
NOT FOR REPLICATION
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 

-- para reduzir processamento desnecessário se outros campos forem atualizados
IF ( Update(Vlr_BasDscCom) or 
     Update(Vlr_RepIcms) or 
     Update(Per_DescontoCom) or 
     Update(Vlr_LiqItens) or
     Update(Vlr_SubsTrib) or 
     Update(Vlr_SbtRes) or 
     Update(Vlr_Despes) or 
     Update(Vlr_DspExt) or 
     Update(Vlr_DscTri) or 
     Update(Vlr_DscBon) or
     Update(Vlr_Ipi) ) 
  BEGIN
	-- para evitar inundacao na recursividade
	IF trigger_nestlevel() > 2 
	  RETURN

	-- Atualiza campos calculados
	Update cb
	   Set cb.C_VlrDesconto =  Round((cb.Vlr_BasDscCom - IsNull(cb.Vlr_RepIcms,0)) * IsNull(cb.Per_DescontoCom,0)/100,2)
	  From Inserted i 
		   Inner Join PDVCB cb on i.Cod_Estabe = cb.Cod_Estabe and i.Numero = cb.Numero
     Where IsNull(cb.C_VlrDesconto,0) <>  Round((cb.Vlr_BasDscCom - IsNull(cb.Vlr_RepIcms,0)) * IsNull(cb.Per_DescontoCom,0)/100,2)

	Update cb
	   Set cb.C_VlrPedido = dbo.FN_ValPdv(cb.Cod_Estabe,cb.Numero)
	  From Inserted i 
		   Inner Join PDVCB cb on i.Cod_Estabe = cb.Cod_Estabe and i.Numero = cb.Numero
	 Where IsNull(cb.C_VlrPedido,0) <> dbo.FN_ValPdv(cb.Cod_Estabe,cb.Numero)

  END

IF ( Update(Cod_Cliente) or
     Update(Cod_Vendedor) or
	 Update(Cod_VendTlmkt) or
	 Update(Tip_Faturamento) ) 
  BEGIN
	-- para evitar inundacao na recursividade
	IF trigger_nestlevel() > 2 
	  RETURN

	Update cb
	   Set cb.Flg_BlqDebVrbNotBon = IsNull(op.Flg_BlqDebVrbNotBon,0)
	  From Inserted i
           Inner Join PDVCB cb on i.Cod_Estabe = cb.Cod_Estabe and i.Numero = cb.Numero
           Inner Join TPOPE op on i.Tip_Faturamento = op.Cod_Ope
	 Where ( (cb.Flg_BlqDebVrbNotBon is null) or
            (IsNull(cb.Flg_BlqDebVrbNotBon,0) <> IsNull(op.Flg_BlqDebVrbNotBon,0)) )      

	Update cb
       Set cb.Cod_GrpCli = IsNull(cl.Cod_GrpCli,0)
      From Inserted i
		   Inner Join PDVCB cb on i.Cod_Estabe = cb.Cod_Estabe and i.Numero = cb.Numero
           Inner Join CLIEN cl on i.Cod_Cliente = cl.Codigo
     Where IsNull(cb.Cod_GrpCli,0) <> IsNull(cl.Cod_GrpCli,0)      
    
	Update cb 
       Set cb.Cod_Supervisor = ve.Cod_Supervisor 
      From Inserted i
           Inner Join PDVCB cb on i.Cod_Estabe = cb.Cod_Estabe and i.Numero = cb.Numero
           Inner Join VENDE ve on i.Cod_Vendedor = ve.Codigo
     Where IsNull(cb.Cod_Supervisor,0) <> IsNull(ve.Cod_Supervisor,0)
      
    Update cb 
       Set cb.Cod_Gerencia = su.Cod_Gerencia
	  From Inserted i
           Inner Join PDVCB cb on i.Cod_Estabe = cb.Cod_Estabe and i.Numero = cb.Numero
           Inner Join VENDE ve on i.Cod_Vendedor = ve.Codigo  
           Inner Join SUPER su on ve.Cod_Supervisor = su.Codigo
     Where IsNull(cb.Cod_Gerencia,0) <> IsNull(su.Cod_Gerencia,0)

    Update cb 
       Set cb.Cod_SupOpe = ve.Cod_Supervisor 
      From Inserted i
           Inner Join PDVCB cb on i.Cod_Estabe = cb.Cod_Estabe and i.Numero = cb.Numero
           Inner Join VENDE ve on i.Cod_VendTlmkt = ve.Codigo
     Where IsNull(cb.Cod_SupOpe,0) <> IsNull(ve.Cod_Supervisor,0)
      
    Update cb 
       Set cb.Cod_GerOpe = su.Cod_Gerencia
      From Inserted i
           Inner Join PDVCB cb on i.Cod_Estabe = cb.Cod_Estabe and i.Numero = cb.Numero
           Inner Join VENDE ve on i.Cod_VendTlmkt = ve.Codigo
           Inner Join SUPER su on ve.Cod_Supervisor = su.Codigo
     Where IsNull(cb.Cod_GerOpe,0) <> IsNull(su.Cod_Gerencia,0)

  END


IF Update(Id_PolCom)
  BEGIN
	-- para evitar inundacao na recursividade
	IF trigger_nestlevel() > 2 
	  RETURN

    -- se ainda nao houver itens no pedido atualiza informacoes ref. verbas
    if Exists(Select 1 From Inserted i where IsNull(i.Qtd_Itens, 0) > 0)
      begin
        Update cb 
           Set cb.Tip_GerVrb = dbo.FN_TipGerVrbPdv(i.Id_PolCom),
               cb.Flg_MarkupCusCom = dbo.FN_FlgMarkupPdvcb(i.Id_PolCom)
          From Inserted i 
               Inner Join PDVCB cb on i.Cod_Estabe = cb.Cod_Estabe and i.Numero = cb.Numero
               Inner Join POCOM pc on i.Id_PolCom = pc.Id_PolCom
         Where cb.Status1 = 'P'
           And cb.Status2 <> 'N'   -- Status2 = 'X'
           And cb.Status2 <> 'D'
      end
  END

IF Update(Status1)
  begin
	-- para evitar inundacao na recursividade
	IF trigger_nestlevel() > 2 
	  RETURN

    if Exists(Select i.Status1
                From Inserted i
                     Inner Join Deleted d on i.Cod_Estabe = d.Cod_Estabe and i.Numero = d.Numero
               Where i.Status1 = 'C'
                 And ((IsNull(i.Id_Consig,0) > 0) or (IsNull(i.Id_PVMCB,0) > 0)))
      begin
        Declare @CodEstabe int,
                @IdConsig int,
                @NumSeqCtr int,
                @IdPVMCB int

        Select @CodEstabe = i.Cod_Estabe,
               @IdConsig  = IsNull(i.Id_Consig,0),
               @NumSeqCtr = IsNull(i.Num_SequenciaCtr,0),
               @IdPVMCB  = IsNull(i.Id_PVMCB,0)
          From Inserted i
               Inner Join Deleted d on i.Cod_Estabe = d.Cod_Estabe and i.Numero = d.Numero
         Where i.Status1 = 'C'
           And ((IsNull(i.Id_Consig,0) > 0) or (IsNull(i.Id_PVMCB,0) > 0))

         if @IdConsig > 0
           Exec PR_AtualizaCNGRI @CodEstabe, @IdConsig, @NumSeqCtr

         if @IdPVMCB > 0
         begin
           Exec PR_AtualizaPVMIT @IdPVMCB, 0
           Exec PR_AtualizaPVMCB @IdPVMCB
         end

	  end     
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_SugereIdPolComCli]
(
  @PCodOri varchar(1),      -- Origem (A-Ativo, P-Receptivo, M-Móvel, T-Eletronico/EDI, W-Internet/WEB, H-Hospitalar, D-por Desdobramento, V-por Val)
  @PTipPrz varchar(1),      -- OPCIONAL: Tipo de Prazo (F-fabricante, L-Linear) 
  @PCodEstabe int,          -- OPCIONAL: cod.estabelecimento: -1
  @PCodCli int,
  @PCodVdr int,             -- OPCIONAL: cod.vendedor 
  @PCodOpe int,             -- OPCIONAL: cod.operador 
  @PCodPrz int              -- OPCIONAL: cod.prazo 
)
RETURNS int

AS

BEGIN

Declare @IdPolCom int,
        @Date smalldatetime

Set @Date = cast(GetDate() as date)
Set @PCodOri = Ltrim(Rtrim(@PcodOri))
Set @PTipPrz = Ltrim(Rtrim(@PTipPrz))

Set @IdPolCom = 0

if Exists(Select 1 From PARAM Where Cod_Estabe = @PCodEstabe And IsNull(FlgUsaPolComPdv,0) = 1) or
   Exists(Select 1 From PARAM Where @PCodEstabe < 0 And IsNull(FlgUsaPolComPdv,0) = 1)
  begin
    if @PCodCli > 0 
	  begin
        Set @IdPolCom = (Select top 1 Id_Polcom
                           From dbo.FN_RetornaPoliticasCliente(@PCodOri, @PTipPrz, @PCodEstabe, 
                                                               @PCodCli, @PCodVdr, @PCodOpe, @PCodPrz)
	                      Order by Prioridade, Cod_Estabe, Flg_BlqCli, Dat_Cadastro desc)
	  end
	else
	  begin
        if Charindex(@PCodOri,';M;T;W;') = 0  -- M-Móvel, T-Eletronico/EDI, W-Internet/WEB
          Set @IdPolCom = (Select top 1 p.Id_PolCom 
                             From POCOM p 
                                  Inner Join PCXES pe on ((p.Id_PolCom = pe.Id_PolCom) and ( ((@PCodEstabe > -1) and (pe.Cod_Estabe = @PCodEstabe)) or (@PCodEstabe < 0)) ) 
                            Where IsNull(p.Flg_Balcao,0) = 1 
                              And ((p.Dat_Inicio is Null) or (@Date >= p.Dat_Inicio)) 
                              And ((p.Dat_Termino is Null) or (@Date <= p.Dat_Termino)) 
                              And IsNull(p.Tip_PolCom,'') <> 'KIT'
                              And IsNull(p.Bloqueado,0) = 0 
                            Order by pe.Cod_Estabe, p.Flg_BlqCli, p.Dat_Cadastro desc)
	  end
  end

-- Retorna o resultado da function
RETURN IsNull(@IdPolCom,0)

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW dbo.V_PRODU_SIN AS

Select Cod_Produt = pr.Codigo, 
       Des_Produt = pr.Descricao, 
	   Cod_Fabric = fb.Codigo, 
	   Cod_Divisa = pr.Cod_Divisao,
	   Des_Fabric = fb.Fantasia, 
	   Prc_VenMax = ps.Prc_VenMax, 
       ps.Qtd_DspVen,
       Flg_FabBlq = IsNull(fb.Bloqueado, 0),
       pr.Tipo,	
	   pr.Cod_Classif,
	   Des_GrpPrc = IsNull(g.Des_GrpPrc,''),
	   pr.Cod_SubBas,
       Des_SubBas = IsNull(s.Descricao,''), 
	   pr.Ctrl_Preco,
	   pr.Tip_LisPis,
	   pr.Ctrl_Venda,
	   pr.Flag_ImprClassif1,
	   pr.Dat_Cadastro,
	   ps.Str_ClaTri,
	   ps.Flg_BlqDsc,
	   ps.Flg_BlqVen,
	   ps.Flg_BlqCmp,
	   ps.Flg_BlqCot,
	   pr.Cod_EAN, pr.Des_NomGen,
       pr.Des_PrdRef, pr.Ref_Detalhe,
       C_DesGen = Case 
                    When pr.Qtd_UndVen <> 0 then (ltrim(rtrim(IsNull(pr.Des_NomGen,''))) + ' ' +
                                                 ltrim(rtrim(IsNull(pr.Des_FormaFarmac,''))) + ' ' +
                                                 cast(pr.Qtd_UndVen as varchar) + ' ' + 
                                                 ltrim(rtrim(IsNull(pr.Des_UndVen,'')))) 
                    Else (ltrim(rtrim(IsNull(pr.Des_NomGen,''))) + ' ' + 
                          ltrim(rtrim(IsNull(pr.Des_FormaFarmac,''))) + ' ' + 
                          ltrim(rtrim(IsNull(pr.Des_UndVen,'')))) 
                  End

  From PRODU pr 
       inner Join FABRI fb on pr.Cod_Fabricante = fb.Codigo 
       inner Join (Select Cod_Produt, 
                          Str_Clatri = ';'+Substring( (Select distinct ';' + x.Cod_ClaTri AS [text()]
                                                         From PRXES x
                                                        Where x.Cod_Produt = p.Cod_Produt
                                                          And IsNull(x.Cod_ClaTri,'') <> ''
                                                          FOR XML PATH ('')) ,2,8000)+';',
                          Flg_BlqDsc = cast(max(cast(IsNull(p.Flg_BlqDsc,0) as int)) as bit),
                          Flg_BlqVen = cast(max(cast(IsNull(p.Flg_BlqVen,0) as int)) as bit),
                          Flg_BlqCmp = cast(max(cast(IsNull(p.Flg_BlqCmp,0) as int)) as bit),
                          Flg_BlqCot = cast(max(cast(IsNull(p.Flg_BlqCot,0) as int)) as bit),
                          Qtd_DspVen = Case 
                                         When sum(Qtd_Dispon) > sum(Qtd_Quaren) then 
                                           sum(Qtd_Dispon)-sum(Qtd_Quaren) 
                                         Else 0 
                                         End,
                          Prc_VenMax = max(Prc_Venda) 
                     From PRXES p 
                    Group by Cod_Produt) ps on pr.Codigo = ps.Cod_Produt 
       left join GRPRC g on pr.Cod_GrpPrc = g.Cod_GrpPrc 
       left join SBBAS s on pr.Cod_SubBas = s.Codigo

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- cuidado:verificar atualizações das estatisticas do cabeçalho
-- na PR_GeraNFS as esatisticas do cabeçalho são atualizadas somente após esta rotina

CREATE PROCEDURE [dbo].[PR_RecalculaNFSCB]
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int

AS

SET NOCOUNT ON

if Exists (Select 1 From dbo.NFSCB 
            Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot  and Num_Nota = @PNumNot
              And Status = 'F' and Cod_ModDoc = '55' and Ret_CStat = 100)
  begin
    RAISERROR('Nota Fiscal já fechada e processada',16,1)
    Return
  end
else
  begin
  Begin Transaction

  -- acumuladores
  Declare @SPerDscFin numeric(18,4),
          @SVlrSubsTrib numeric(18,4),
          @SVlrBasSbtRes numeric(18,4),
          @SVlrSbtRes numeric(18,4),
          @SVlrDscTri numeric(18,4),
          @SVlrRecSbt numeric(18,4),
          @SVlrRepIcms numeric(18,4),
          @SVlrLiqIte numeric(18,4),
          @SVlrDscCom numeric(18,4)

  Declare @cb_Status varchar(1),
          @cb_CodRegTri int,
          @cb_CodPedido int,
          @cb_TipCon varchar(1),
          @cb_PerDscFinAnt numeric(18,4),
          @cb_VlrSubTriAnt numeric(18,4), 
          @cb_VlrRecSbtAnt numeric(18,4),
          @rt_FlgDscIcmOrgPub bit,
          @rt_FlgDscIcmOrgPubComAcr bit

  Declare @it_CodPrd int,
          @it_CodLot varchar(20),
          @it_NumSeqIte int,
          @it_TipSai varchar(1),

          @FlgRepOrgPub bit,
		  @FlgRepSBtRetAnt bit,
          @WVlrTotLiq numeric(18,4)

  -- coloca campos de NFSCB na memoria
  Select @cb_Status = cb.Status,
         @cb_TipCon = cb.Tip_Consumidor,
         @cb_CodRegTri = IsNull(cb.Cod_RegTri,0),
         @cb_CodPedido = IsNull(cb.Cod_Pedido,0),
         @cb_PerDscFinAnt = IsNull(cb.Per_DescontoFin,0),
         @cb_VlrSubTriAnt = IsNull(cb.Vlr_SubsTrib,0)+IsNull(cb.Vlr_SbtRes,0),
         @cb_VlrRecSbtAnt = IsNull(cb.Vlr_RecSbt,0),
         @rt_FlgDscIcmOrgPub = IsNull(rt.Flg_DscIcmOrgPub,0),
         @rt_FlgDscIcmOrgPubComAcr = IsNull(rt.Flg_DscIcmOrgPubAcr,0)
    From dbo.NFSCB cb
         Left Join dbo.RGTRI rt on rt.Cod_RegTri = cb.Cod_RegTri
   Where cb.Cod_Estabe = @PCodEstabe 
     and cb.Ser_Nota = @PSerNot 
     and cb.Num_Nota = @PNumNot

  -- estorna estatisticas 
  Exec dbo.PR_AtualizaEstatisticasNFS @PCodEstabe, @PSerNot, @PNumNot, 'C'
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  Set @FlgRepOrgPub = 0
  Set @FlgRepSbtRetAnt = 0

  -- re-verifica concessão de desconto de icms
  -- recalcula preço unitario para orgaos publicos quando for o caso
  -- acrescenta icms ao preço unitario quando for o caso
  -- se este procedimento já não tiver sido executado anteriormente
  if (@cb_Status = 'F') and
	 ((@rt_FlgDscIcmOrgPub = 1) or (@rt_FlgDscIcmOrgPubComAcr = 1)) and
     Exists(Select 1 
              From dbo.NFSIT it 
                   inner join dbo.PRXES pr on pr.Cod_Estabe = @PCodEstabe And pr.Cod_Produt = it.Cod_Produto
                   inner join dbo.RTXCT rx on rx.Cod_RegTri = @cb_CodRegTri and rx.Cod_ClaTri = pr.Cod_ClaTri
             Where it.Cod_Estabe = @PCodEstabe 
               and it.Ser_Nota = @PSerNot and it.Num_Nota = @PNumNot
               and IsNull(it.Vlr_IcmsTri,0) > 0
               and IsNull(rx.Flg_DscDesIcmLoc,0) = 1)
    Set @FlgRepOrgPub = 1

  if (@cb_Status = 'F') and
     Exists(Select 1 
              From dbo.PDVIT 
             Where Cod_Estabe = @PCodEstabe 
               and Cod_Pedido = @cb_CodPedido
               and IsNull(Vlr_SbtRetAnt,0) > 0)
    Set @FlgRepSBtRetAnt = 1

  -- reprocessa tributos
  if (@FlgRepSBtRetAnt = 1) or (@FlgRepOrgPub = 1)
    begin
      if @FlgRepSBtRetAnt = 1
        begin
          Declare NFSIT_Cr Cursor Local Fast_Forward For 
            Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, IsNull(it.Tip_Sai,'')
              From dbo.NFSIT it 
                   inner join dbo.PRXES pr on pr.Cod_Estabe = @PCodEstabe And pr.Cod_Produt = it.Cod_Produto
                   inner join dbo.RTXCT rx on rx.Cod_RegTri = @cb_CodRegTri and rx.Cod_ClaTri = pr.Cod_ClaTri
             Where it.Cod_Estabe = @PCodEstabe 
               and it.Ser_Nota = @PSerNot and it.Num_Nota = @PNumNot
        end
      else
        begin
          Declare NFSIT_Cr Cursor Local Fast_Forward For 
            Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, IsNull(it.Tip_Sai,'')
              From dbo.NFSIT it 
                   inner join dbo.PRXES pr on pr.Cod_Estabe = @PCodEstabe And pr.Cod_Produt = it.Cod_Produto
                   inner join dbo.RTXCT rx on rx.Cod_RegTri = @cb_CodRegTri and rx.Cod_ClaTri = pr.Cod_ClaTri
             Where it.Cod_Estabe = @PCodEstabe 
               and it.Ser_Nota = @PSerNot and it.Num_Nota = @PNumNot
               and IsNull(it.Vlr_IcmsTri,0) > 0
               and IsNull(rx.Flg_DscDesIcmLoc,0) = 1
        end
      Open NFSIT_Cr
      Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_TipSai
      While @@FETCH_STATUS = 0
        begin
          -- calcula tributos
          Exec dbo.PR_CalcTributNFSIT @PCodEstabe, @PSerNot, @PNumNot, @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_TipSai
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end

          Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_TipSai
        end
      Close NFSIT_Cr
      Deallocate NFSIT_Cr

      if @rt_FlgDscIcmOrgPubComAcr = 1
        Update dbo.NFSCB
           Set Flg_PrcUniAcrIcm = 1   -- atualizar flag de controle para garantir que este procedimento será executado uma única vez
         Where Cod_Estabe = @PCodEstabe 
           and Ser_Nota = @PSerNot 
           and Num_Nota = @PNumNot

      -- Atualiza cabecalho da Nota
      Exec dbo.PR_AtualizaCabecNFS @PCodEstabe, @PSerNot, @PNumNot

      -- recalcula desconto financeiro (aplicar somente sobre valor tot. mercadoria)
      Select @SVlrSubsTrib = IsNull(Vlr_SubsTrib,0),
             @SVlrBasSbtRes = IsNull(Vlr_BasSbtRes,0),
             @SVlrSbtRes = IsNull(Vlr_SbtRes,0),
             @SVlrDscTri = Vlr_DscTri,
             @SVlrRepIcms = Vlr_RepIcms,
             @SVlrDscCom = Vlr_DescontoCom,
             @SVlrLiqIte = Round((Select Sum(Qtd_Produto*Prc_Unitario*(1 - Per_Desconto/100)) from NFSIT Where  Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot),2)
        From dbo.NFSCB
       Where Cod_Estabe = @PCodEstabe 
         and Ser_Nota = @PSerNot 
         and Num_Nota = @PNumNot

      Set @SPerDscFin = @cb_PerDscFinAnt
      if ((@SVlrSubsTrib+@SVlrSbtRes+@SVlrRecSbt ) > 0) and (@cb_PerDscFinAnt > 0) and ((@cb_VlrSubTriAnt+@cb_VlrRecSbtAnt) = 0)
        begin
          Set @WVlrTotLiq = @SVlrLiqIte - @SVlrDscCom - @SVlrRepIcms - @SVlrDscTri
         -- calcula novo desc fin
          Set @SPerDscFin = Round(@WVlrTotLiq*@SPerDscFin/(@WVlrTotLiq+@SVlrSubsTrib+@SVlrSbtRes+@SVlrRecSbt),4)
        end

      Update dbo.NFSCB
         Set Per_DescontoFin = @SPerDscFin,
             Vlr_TotalNota = dbo.FN_ValTotNFS(Cod_Estabe, Ser_Nota, Num_Nota)
       Where Cod_Estabe = @PCodEstabe 
         and Ser_Nota = @PSerNot 
         and Num_Nota = @PNumNot

    end  -- if (@cb_Status = 'F') and (@rt_FlgDscIcmOrgPubComAcr = 1) and Exists...


  -- rateia despesas
  --Exec PR_RateiaDespesasNFS @PCodEstabe, @PSerNot, @PNumNot  -- ??? já executa em PR_AtualizaCabecNFS


  -- Atualiza cabecalho da Nota
  Exec dbo.PR_AtualizaCabecNFS @PCodEstabe, @PSerNot, @PNumNot

  -- reatualiza estatisticas
  Exec dbo.PR_AtualizaEstatisticasNFS @PCodEstabe, @PSerNot, @PNumNot, 'F'
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  -- recalcula titulos
  Exec dbo.PR_RecalculaTitulosNFSCB @PCodEstabe, @PSerNot, @PNumNot
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  if @@trancount > 0
    Commit Transaction
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraNFS]
@CodEstabe int,                -- estabelecimento
@CodPed int,                   -- num. do pedido
@CodCfo int,                   -- codigo fiscal de operacao
@NumSel bigint,                -- num. do selo fiscal inicial
@NumFor int,                   -- num. do formulario inicial
@TipNfs varchar(1),            -- tipo de nota: 'V', 'D', 'O'
@DesUsu varchar(15),           -- usuario
@SerNfsRet varchar(3) output,  -- serie NF gerada
@NumNfsRet int output          -- num. NF gerada

AS

SET ANSI_WARNINGS OFF
SET NOCOUNT ON 

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime,
        @MsgErr varchar(200),
        @WFlgWMS bit

Set @Now = GetDate()
Set @Date = cast(GetDate() as Date)

If (@DesUsu = '' or @DesUsu = 'SISTEMA')
  Set @DesUsu = dbo.FN_UsuarioInfarma()

Set @SerNfsRet = ''
Set @NumNfsRet = 0
Set @MsgErr = ''

if Charindex((Select Status2 From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed),';N;D;') > 0 
  Set @MsgErr = 'Pedido já faturado'
else
if ((Select IsNull(FlgNfe,0) From PARAM Where Cod_Estabe = @CodEstabe) = 1) and (not Exists(Select 1 From NMNFE Where Cod_Estabe = @CodEstabe And Flg_Padrao = 1))
  Set @MsgErr = 'Não existe série padrão cadastrada para nota fiscal eletrônica'
else
if (Select Ltrim(Rtrim(IsNull(Cod_TipLucro,''))) From ESTAB Where Cod_Estabe = @CodEstabe) = ''
  Set @MsgErr = 'Tipo de Lucro do Estabelecimento não cadastrado'
else
if ((Select Flg_Wms From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) = 1) and
   Exists(Select it.QtdIte, lt.QtdLot
          From (Select Cod_Produto, QtdIte = SUM(IsNull(Qtd_Pedido,0)+Isnull(Qtd_Bonificacao,0))
                  From PDVIT 
                 Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                   And (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0
                 Group by Cod_Produto) it Full Outer Join
               (Select Cod_Produt, QtdLot = SUM(IsNull(Qtd_Lote,0))
                  From PDVLT
                 Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                   And IsNull(Qtd_Lote,0) > 0
                 Group by Cod_Produt) lt on it.Cod_Produto = lt.Cod_Produt
          Where (IsNull(it.QtdIte,0) <> IsNull(lt.QtdLot,0)))
  Set @MsgErr = 'Existem inconsistências nos Lotes do Pedido. Cancele-o'
else
-- verifica se existe NF faturada para este pedido nos ultimos 6 meses
if Exists(Select 1 From NFSCB
           Where Cod_Estabe = @CodEstabe
             And Cod_Pedido = @CodPed
             And DATEDIFF (month,Dat_Emissao,@Date ) < 6)
  Set @MsgErr = (Select top 1 'Já existe uma NF('+cast(Num_Nota as varchar)+') '+
                              'emitida para este pedido('+cast(@CodPed as varchar)+')'
                   From NFSCB
                  Where Cod_Estabe = @CodEstabe
                    And Cod_Pedido = @CodPed
                    And DATEDIFF (month,Dat_Emissao,@Date ) < 6)


if @MsgErr <> ''
  RAISERROR(@MsgErr,16,1)
else
begin
  Begin Transaction

  Set @SerNfsRet = ''
  Set @NumNfsRet = 0

  Set @WFlgWMS = IsNull((Select Flg_Wms From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed),0)

  Update PDVCB
     Set Qtd_Itens = Qtd_Itens + 0 
   Where Cod_Estabe = @CodEstabe And Numero = @CodPed
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  Update NMFIS
     Set Nota_Fiscal_M1 = Nota_Fiscal_M1 + 0
   Where Cod_Estabe = @CodEstabe
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  Update NMNFE     
     Set Num_Nfe = Num_Nfe + 0
   Where Cod_Estabe = @CodEstabe 
     And Flg_Padrao = 1
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  Declare @WCodOri varchar(20)

  -- variaveis a gravar em NFSCB
  Declare @PEspNfs varchar(3),
          @PQtdPagNfs int,
          @PSerSel varchar(2),
          @PNumSel bigint,
          @PNumFor int,
          @PCodCfo smallint,
          @PDatEmi smalldatetime,
          @PTipVct varchar(1),
          @PTipRetImp varchar(1),
          @PPerDscFin numeric(18,4),   -- novo desc. financeiro sobre valor toal da nf
          @PPerDscFinLiq numeric(18,4),  -- % aplicado sobre Valor da mercadoria
          @PCgc varchar(14),
          @PCgf varchar(15),
          @PDesEnd  varchar(50),
          @PDesBai varchar(20),
          @PCep varchar(8),
          @PEst varchar(2),
          @PDesCid varchar(25),
          @PCodCid int,
          @PCodCidIbge varchar(7),
          @PCodMacReg int,
          @PCodMicReg int,
          @PQtdPar int,
          @PQtdPrzMed numeric(18,4),
          @PFlgComNor bit,
          @PPerComVnd numeric(18,4),
          @PPerComOpe numeric(18,4),
          @PPerComSup numeric(18,4),
          @PPerComGer numeric(18,4),
          @PPerComSupOpe numeric(18,4),
          @PPerComGerOpe numeric(18,4),
          @PModNotFis varchar(2),
          @PCodStaNfe varchar(1),
          @PUfPlaVei varchar(2),
          @PCodPlaVei varchar(10),
		  @PNumInscriSbtEmiUfd varchar(15),

          @PVlrDebVrbVdr numeric(18,4),
          @PVlrComTra numeric(18,4),
          @PVlrDscCom numeric(18,4),
          @PVlrOutDsp numeric(18,4),
          @WVlrOutDsp numeric(18,4),
          @PVlrTotNot numeric(18,4),

          @PVlrSubTri numeric(18,4),
          @PVlrDscTri numeric(18,4),
          @PVlrRecSbt numeric(18,4),
          @PVlrFcpSbt numeric(18,4),
          @PVlrFcpSbtRec numeric(18,4),

		  @PVlrBasIrf numeric(18,4),
		  @PVlrIrf numeric(18,4)

  -- coloca campos de PDVCB na memoria
  Declare @cb_TipFat varchar(3),
          @cb_TipSaiPdv varchar(1),
          @cb_TipGerVrb varchar(1),
          @cb_TipRatBon varchar(1),
          @cb_FlgBlqDebVrbNotBon bit,
          @cb_StaPdv1 varchar(1),
          @cb_StaPdv2 varchar(1),
          @cb_TipBlq varchar(2),
          @cb_QtdIte int,
          @cb_TipVct varchar(1),
          @cb_CodCli int,
          @cb_TipCon varchar(1),
          @cb_CodFun int,
          @cb_NomCon varchar(45),
          @cb_CodOriPdv varchar(2),
          @WCodOriPdv varchar(1),
          @cb_CodDig int,
          @cb_CodOpe int,
          @cb_CodVdr int,
          @cb_CodSup int,
          @cb_CodGer int,
          @cb_CodSupOpe int,
          @cb_CodGerOpe int,
          @cb_CodAgc int,
          @cb_CodTra int,
          @cb_CodRot int,
          @cb_CodRegTri int,
          @cb_VlrLiqIte numeric(18,4),
          @cb_VlrBasDscCom numeric(18,4),
          @cb_VlrBasPar numeric(18,4),
          @cb_VlrRepIcm numeric(18,4),
          @cb_VlrSubTri numeric(18,4),
          @cb_VlrSubTriFcp numeric(18,4),
          @cb_VlrSbtRes numeric(18,4),
          @cb_VlrDscTri numeric(18,4),
          @cb_VlrDscBon numeric(18,4),
          @cb_VlrDspExt numeric(18,4),
          @cb_VlrDespes numeric(18,4),
          @cb_VlrIpi numeric(18,4),
          @cb_QtdPes numeric(18,4),
          @cb_QtdVol int,
          @cb_IdPolCom int,
          @cb_PerSubFat  numeric(7,4),
          @cb_PerDscCom numeric(7,4),
          @cb_FlgVlrFin bit,
          @cb_ObsNfs varchar(1600),
          @cb_DatPed smalldatetime,
          @cb_CodPedCliPde varchar(20),
          @cb_CodPedCmpCli varchar(20),
          @cb_NotEmpCli varchar(20),
          @cb_NumConCli varchar(40),
          @cb_DesLayPde varchar(25),
          @cb_CodPrjPde varchar(12),
          @cb_DesConven varchar(30),
          @cb_CodCtr int,
          @cb_NumSeqCtr int,
          @cb_IdConsig int,
          @WCodTipSaiCng varchar(3),
          @cb_TipFrete varchar(1),
          @cb_VlrFrete numeric(18,4),
          @cb_VlrFrePrv numeric(18,4),
          @cb_PerComSup numeric(7,4),
          @cb_PerComGer numeric(7,4),
          @cb_PerComSupOpe numeric(7,4),
          @cb_PerComGerOpe numeric(7,4),
          @cb_FlgGerRetBon bit,
          @cb_UfPlaVei varchar(2),
          @cb_CodPlaVei varchar(10),
          @cb_VlrSdoVrb numeric(18,4),
          @cb_InscricaoSuframa varchar(9),

          @pc_Controle_Saldo varchar(1),
          @pc_FlgAcuVrbPos bit,
          @pc_FlgAcuVrbNeg bit,
          @pc_FlgMarkupCusCom bit,
		  @pc_FlgCtrPdvVrbVdr bit,
		  @pc_FlgCtrPdvVrbOpe bit

  -- normaliza supervisor/gerencia
    Update cb 
       Set cb.Cod_Supervisor = ve.Cod_Supervisor 
     From PDVCB cb 
	      Inner Join VENDE ve on cb.Cod_Vendedor = ve.Codigo
    Where cb.Cod_Estabe = @CodEstabe 
	  And cb.Numero = @CodPed
      And IsNull(cb.Cod_Supervisor,0) <> IsNull(ve.Cod_Supervisor,0)
      
    Update cb 
       Set cb.Cod_Gerencia = su.Cod_Gerencia
      From PDVCB cb 
	       Inner Join VENDE ve on cb.Cod_Vendedor = ve.Codigo
           Inner Join SUPER su on ve.Cod_Supervisor = su.Codigo
     Where cb.Cod_Estabe = @CodEstabe 
	   And cb.Numero = @CodPed
       And IsNull(cb.Cod_Gerencia,0) <> IsNull(su.Cod_Gerencia,0)

    Update cb 
       Set cb.Cod_SupOpe = ve.Cod_Supervisor 
      From PDVCB cb 
	       Inner Join VENDE ve on cb.Cod_VendTlmkt = ve.Codigo
     Where cb.Cod_Estabe = @CodEstabe 
	   And cb.Numero = @CodPed
       And IsNull(cb.Cod_SupOpe,0) <> IsNull(ve.Cod_Supervisor,0)
      
    Update cb 
       Set cb.Cod_GerOpe = su.Cod_Gerencia
      From PDVCB cb 
	       Inner Join VENDE ve on cb.Cod_VendTlmkt = ve.Codigo
           Inner Join SUPER su on ve.Cod_Supervisor = su.Codigo
     Where cb.Cod_Estabe = @CodEstabe 
	   And cb.Numero = @CodPed
       And IsNull(cb.Cod_GerOpe,0) <> IsNull(su.Cod_Gerencia,0)

  Select @cb_TipFat = cb.Tip_Faturamento,
         @cb_TipSaiPdv = IsNull(cb.Tip_SaiPdv,''),
         @cb_TipGerVrb = IsNull(cb.Tip_GerVrb,''),
         @cb_TipRatBon = IsNull(cb.Tip_RatBon,''),
         @cb_FlgBlqDebVrbNotBon = IsNull(cb.Flg_BlqDebVrbNotBon,0),
         @cb_StaPdv1 = cb.Status1,
         @cb_StaPdv2 = cb.Status2,
         @cb_TipBlq = cb.Bloqueio,
         @cb_TipVct = cb.Tip_Vencimento,
         @cb_CodCli = cb.Cod_Cliente,
         @cb_TipCon = cb.Tip_Consumidor,
         @cb_CodFun = cb.Cod_Funcionario,
         @cb_NomCon = cb.Consumidor,
         @cb_CodOriPdv = cb.Cod_OrigemPdv,
         @WCodOriPdv = Substring(cb.Cod_OrigemPdv,1,1),
         @cb_CodDig = cb.Cod_Digitador,
         @cb_CodOpe = cb.Cod_VendTlmkt,
         @cb_CodVdr = cb.Cod_Vendedor,
         @cb_CodSup = cb.Cod_Supervisor,
         @cb_CodGer = cb.Cod_Gerencia,
         @cb_CodSupOpe = cb.Cod_SupOpe,
         @cb_CodGerOpe = cb.Cod_GerOpe,
         @cb_CodAgc = cb.Cod_Agente,
         @cb_CodTra = cb.Cod_Transportadora,
         @cb_CodRot = IsNull(cb.Cod_Rota,0),
         @cb_CodRegTri = cb.Cod_RegTri,
         @cb_VlrLiqIte = cb.Vlr_LiqItens,
         @cb_VlrBasDscCom = cb.Vlr_BasDscCom,
         @cb_VlrBasPar = cb.Vlr_BasPar,
         @cb_VlrRepIcm = ISNULL(cb.Vlr_RepIcms,0),
         @cb_VlrSubTri = ISNULL(cb.Vlr_SubsTrib,0),
         @cb_VlrSbtRes = ISNULL(cb.Vlr_SbtRes,0),
         @cb_VlrDscTri = ISNULL(cb.Vlr_DscTri,0),
         @cb_VlrDscBon = ISNULL(cb.Vlr_DscBon,0),
         @cb_VlrDspExt = ISNULL(cb.Vlr_DspExt,0),
         @cb_VlrDespes = ISNULL(cb.Vlr_Despes,0),
         @cb_VlrIpi = ISNULL(cb.Vlr_Ipi,0),
         @cb_QtdPes = cb.Qtd_Peso,
         @cb_QtdVol = cb.Qtd_Volumes,
         @cb_IdPolCom = cb.Id_PolCom, 
         @cb_QtdIte = cb.Qtd_Itens,
         @cb_PerSubFat = cb.Per_SubFat,
         @cb_PerDscCom = IsNull(cb.Per_DescontoCom,0),
         @cb_FlgVlrFin = cb.Flg_VlrFinanc,
         @cb_ObsNfs = Substring(cb.Obs_NotFis,1,1600),
         @cb_DatPed = cb.Dat_Pedido,
         @cb_CodPedCliPde = cb.Cod_PedCli,
         @cb_CodPedCmpCli = cb.Cod_PedCmpCli,
         @cb_NotEmpCli = cb.Ide_NotEmp,
         @cb_NumConCli = cb.Ide_Contra,
         @cb_DesLayPde = cb.Des_LayoutPde,
         @cb_CodPrjPde = cb.Cod_PrjPde,
         @cb_DesConven = cb.Des_Convenio,
         @cb_CodCtr = cb.Cod_Contrato,
         @cb_IdConsig = IsNull(cb.Id_Consig,0),
         @cb_NumSeqCtr = cb.Num_SequenciaCtr,
         @cb_TipFrete = IsNull(cb.Tip_Frete,'1'),   -- '1'-CIF
         @cb_VlrFrete = Round(IsNull(cb.Vlr_Frete,0),2),
         @cb_VlrFrePrv = Round(IsNull(cb.Vlr_FrePrv,0),2),
         @cb_FlgGerRetBon = IsNull(cb.Flg_GerRetBon,0),
         @cb_PerComSup = IsNull(cb.Per_ComSup,0),
         @cb_PerComGer = IsNull(cb.Per_ComGer,0),
         @cb_PerComSupOpe = IsNull(cb.Per_ComSupOpe,0),
         @cb_PerComGerOpe = IsNull(cb.Per_ComGerOpe,0),
         @cb_UfPlaVei = Ltrim(Rtrim(cb.Uf_PlaVei)),
         @cb_CodPlaVei =  Ltrim(Rtrim(cb.Cod_PlaVei)),
         @cb_VlrSdoVrb = IsNull(cb.Vlr_Verba,0),
         @cb_InscricaoSuframa = IsNull(cb.Inscricao_Suframa,''),

		 @PVlrBasIrf = IsNull(cb.Vlr_BasIrf,0),
		 @PVlrIrf = IsNull(cb.Vlr_Irf,0),
         @PQtdPar = cb.Qtd_Parcela,
         @PQtdPrzMed = cb.Qtd_PrzMed,
         @PPerDscFinLiq = IsNull(cb.Per_DescontoFin,0),
         @PFlgComNor = cb.Flg_ComisNormal,
         @PPerComOpe = Round(IsNull(cb.Per_ComOpe,0),2),
         @PPerComVnd = Round(IsNull(cb.Per_ComVnd,0),2),

         @pc_Controle_Saldo = pc.Controle_Saldo, 
         @pc_FlgAcuVrbPos = pc.Flg_AcuVrbPos,
         @pc_FlgAcuVrbNeg = pc.Flg_AcuVrbNeg,
         @pc_FlgMarkupCusCom = pc.Flg_MarkupCusCom,
         @pc_FlgCtrPdvVrbVdr = pc.Flg_CtrPdvVrbVdr,
         @pc_FlgCtrPdvVrbOpe = pc.Flg_CtrPdvVrbOpe

    From PDVCB cb
         left join VENDE ve on ve.Codigo = cb.Cod_Vendedor
         left join POCOM pc on pc.Id_PolCom = cb.Id_PolCom
         left join PCXVE xv on xv.Id_PolCom = cb.Id_PolCom and xv.Cod_Vended = cb.Cod_Vendedor
         left join PCXOP xo on xo.Id_PolCom = cb.Id_PolCom and xo.Cod_Vended = cb.Cod_VendTlmkt
         left join PCXSU xs on xs.Id_PolCom = cb.Id_PolCom and xs.Cod_Super  = ve.Cod_Supervisor
   Where cb.Cod_Estabe = @CodEstabe 
     And cb.Numero = @CodPed

  Select @cb_VlrSubTriFcp = ROUND(SUM(ISNULL(Vlr_FcpSbt,0)),2)          
    From PDVIT
   Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed

  -- coloca campos de ESTAB na memoria
  Declare @em_Cep varchar(8),
          @em_CodEst varchar(2),
          @em_CodTipLuc varchar(2),
		  @em_FlgContriSubstituido bit

  Select @em_Cep = Num_Cep,
         @em_CodEst = Des_Estado,
         @em_CodTipLuc = IsNull(Cod_TipLucro,''),
		 @em_FlgContriSubstituido = IsNull(Flg_ContriSubstituido,0)
    From ESTAB
    Where Cod_Estabe = @CodEstabe

  -- coloca campos de PARAM na memoria
  Declare @pm_NumItePagNfs int,
          @pm_FlgCtrSelFis bit,
          @pm_ModeloNotaFiscal varchar(3),
          @pm_SerieSeloFiscal varchar(2),
          @pm_CodCidEmpLoc int,
          @pm_CodMacRegEmpLoc int,
          @pm_CodMicRegEmpLoc int,
          @pm_FlgComPrdPrpDsc bit,
          @pm_FlgDespachMercad bit,
          @pm_FlgNfe bit,
          @pm_FlgIncIpiCalPis bit,
          @pm_FlgExcIcmCalPis bit,
          @pm_FlgDebBlqBanVrbVdr bit,
          @pm_PerCusFinDiaExcPrzMedCfg numeric(18,4),
          @pm_QtdPrzMedCfg int

  Select @pm_NumItePagNfs = IsNull(NumItePagNfs,0),
         @pm_FlgCtrSelFis = IsNull(FlgCtrSelFis,0),
         @pm_ModeloNotaFiscal = ModeloNotaFiscal,
         @pm_SerieSeloFiscal = SerieSeloFiscal,
         @pm_CodCidEmpLoc = CodCidadeEmpLoc,
         @pm_CodMacRegEmpLoc = CodMacRegEmpLoc,
         @pm_CodMicRegEmpLoc = CodMicRegEmpLoc,
         @pm_FlgComPrdPrpDsc = IsNull(FlgComPrdPrpDsc,0),
         @pm_FlgDespachMercad = IsNull(FlgDespachMercad,0),
         @pm_FlgNfe = IsNull(FlgNfe,0),
         @pm_FlgIncIpiCalPis = IsNull(FlgIncIpiCalPis,0),
         @pm_FlgExcIcmCalPis = IsNull(FlgExcIcmCalPis,0),
		 @pm_FlgDebBlqBanVrbVdr = IsNull(FlgDebBlqBanVrbVdr,0),
		 @pm_PerCusFinDiaExcPrzMedCfg = IsNull(PerCusFinDiaExcPrzMedCfg,0),
		 @pm_QtdPrzMedCfg = IsNull(QtdPrzMedCfg,0)
    From PARAM
   Where Cod_Estabe = @CodEstabe 

  -- coloca campos de CLIEN na memoria
  if Exists(Select Codigo From CLIEN Where Codigo = @cb_CodCli)
    begin
      Update CLIEN
         Set Total_Debito = IsNull(Total_Debito,0) + 0
       Where Codigo = @cb_CodCli
    end

  Declare @cl_CodEst varchar(2),
          @cl_TipCon varchar(1),
          @cl_CodCid int,
          @cl_CodBai int,
          @cl_CgcCpf varchar(14),
          @cl_Cgf varchar(15),
          @cl_DesEnd varchar(65),
          @cl_Cep varchar(8),
          @cl_FlgBlqCobTxaBan bit,
          @cl_CodRamAtv int,
          @uf_FlgRegSubTri bit,
          @Uf_BlqInsEstSbtNfs bit,
          @uf_NumInscriSbt varchar(15),
          @PTotDebCli numeric(18,4),
          @PVlrUltFatCli numeric(18,4),
          @PVlrMaiFatCli numeric(18,4)
            
  Select @cl_CodEst = cl.Cod_Estado,
         @cl_TipCon = cl.Tipo_Consumidor,
         @cl_CodCid = cl.Cod_Cidade,
         @cl_CodBai = cl.Cod_Bairro,
         @cl_CgcCpf = cl.Cgc_Cpf,
         @cl_Cgf = cl.Cgf,
         @cl_DesEnd = case
                        when IsNull(cl.Endereco,'') <> '' and IsNull(cl.Numero,'') <> '' and IsNull(cl.Complemento,'') <> '' then
                             ltrim(rtrim(cl.Endereco))+', '+ltrim(rtrim(cl.Numero))+', '+ltrim(rtrim(cl.Complemento))
                        else ltrim(rtrim(cl.Endereco))+', '+ltrim(rtrim(cl.Numero))
                      end,
         @cl_Cep = cl.Cep, 
         @cl_FlgBlqCobTxaBan = cl.Flg_BlqCobTxaBan,
		 @cl_CodRamAtv = cl.Cod_RamoAtividade,
         @PTotDebCli = IsNull(cl.Total_Debito,0),
         @PVlrUltFatCli = IsNull(cl.Valor_UltimaFatura,0),
         @PVlrMaiFatCli = IsNull(cl.Valor_MaiorFatura,0)
    From CLIEN cl 
    Where cl.Codigo = @cb_CodCli

  -- coloca campos de UFXES na memoria
  Select @uf_FlgRegSubTri = IsNull(Flg_RegSubTri,0),
         @Uf_BlqInsEstSbtNfs = IsNull(Flg_BlqNumInscriSubTriNfs,0),
         @uf_NumInscriSbt = case 
                              when (IsNull(Num_InscriSubTri,'') <> '.') and (IsNull(Num_InscriSubTri,'') <> '')  then IsNull(Num_InscriSubTri,'')
                              else ''
                            end
    From UFXES
   Where Cod_Estabe = @CodEstabe
     And Cod_UF = @cl_CodEst

  if @uf_FlgRegSubTri is null Set @uf_FlgRegSubTri = 0
  if @Uf_BlqInsEstSbtNfs is null Set @Uf_BlqInsEstSbtNfs = 0
  if @uf_NumInscriSbt is null Set @uf_NumInscriSbt = ''

  -- coloca campos de CIDAD na memoria
  Declare @ci_DesCid varchar(25),
          @ci_CodCidIbge varchar(7)

  Select @ci_DesCid = Descricao,
         @ci_CodCidIbge = Cod_CidIbge
    From CIDAD
   Where Cod_Estado = @cl_CodEst
     And Codigo = @cl_CodCid

  -- coloca campos de BAIRR na memoria
  Declare @ba_DesBai varchar(20),
          @ba_CodMacReg int,
          @ba_CodMicReg int 
    
  Select @ba_DesBai = Descricao,
         @ba_CodMacReg = Cod_MacroReg,
         @ba_CodMicReg = Cod_MicroReg
    From BAIRR
   Where Cod_Estado = @cl_CodEst
     And Cod_Cidade = @cl_CodCid
     And Codigo = @cl_CodBai

  -- coloca campos de TRANS na memoria
  Declare @tr_Pessoa varchar(1),
          @tr_PerFrete numeric(18,4),
          @tr_VlrMin numeric(18,4),
          @tr_FlgCalFreVerMer bit,
          @tr_UfPlaVei varchar(2),
          @tr_CodPlaVei varchar(10)

  Select @tr_Pessoa = tr.Pessoa,
         @tr_PerFrete = Case 
                          When tx.Cod_Transp is null then IsNull(tr.Per_Frete,0) 
                          Else IsNull(tx.Per_Frete,0) 
                        End,
         @tr_VlrMin = Case 
                          When tx.Cod_Transp is null then IsNull(tr.Vlr_Minimo,0) 
                          Else IsNull(tx.Vlr_Minimo,0) 
                        End,
         @tr_FlgCalFreVerMer = Case 
                                 When tx.Cod_Transp is null then IsNull(tr.Flg_CalFreVlrMer,0) 
                                 Else IsNull(tx.Flg_CalFreVlrMer,0) 
                               End,
         @tr_UfPlaVei = IsNull(Uf_PlaVei,''),
         @tr_CodPlaVei = IsNull(Cod_PlaVei,'')
    From TRANS tr
         Left Join TRXUF tx on tr.Codigo = tx.Cod_Transp and tx.Cod_UF COLLATE DATABASE_DEFAULT = @cl_CodEst COLLATE DATABASE_DEFAULT 
   Where tr.Codigo = @cb_CodTra


  -- colocar campos de AGCOB na memoria 
  -- despesa de boleto somente para banco cobrado na NF
  Declare @ag_VlrDspBolBan numeric(18,4),
          @ag_PerTaxAdm numeric(18,4),
          @ag_CodAplTaxAdm varchar(1)

  Select @ag_VlrDspBolBan = case 
                              When (Isnull(Flg_CobDspBolBanNtf,0) = 1) and (Tipo = 'BC') and
                                   (IsNull(@cl_FlgBlqCobTxaBan,0) = 0) then Round(Isnull(Vlr_DspBolBan,0),2)
                              else 0
                            end,
         @ag_PerTaxAdm = IsNull(Per_TaxAdm,0),
         @ag_CodAplTaxAdm = IsNull(Cod_AplTaxAdm,'')
    From AGCOB
   Where Codigo = @cb_CodAgc
    
  -- coloca campos de RGTRI na memoria
  Declare @rt_FlgConsumFin bit,
          @rt_CtrImpIcmTotNfs bit,
          @rt_FlgDscIcmOrgPub bit,
          @rt_FlgDscIcmOrgPubAcr bit,
          @rt_FlgUsaCfoSbtSaiIntGenSim bit

  Select @rt_FlgConsumFin = IsNull(Flg_ConsumFin,0),
         @rt_CtrImpIcmTotNfs = Isnull(Ctrl_ImpIcmTotNfs,0),
         @rt_FlgDscIcmOrgPub = IsNull(Flg_DscIcmOrgPub,0),
         @rt_FlgDscIcmOrgPubAcr = IsNull(Flg_DscIcmOrgPubAcr,0),
         @rt_FlgUsaCfoSbtSaiIntGenSim = IsNull(Flg_UsaCfoSbtSaiIntGenSim,0)
    From RGTRI
   Where Cod_RegTri = @cb_CodRegTri

  -- coloca campos TPOPE na memoria
  Declare @to_CodCfoConFinInt smallint,
          @to_CodCfoConFinExt smallint,
	      @to_CodCfoNorInt smallint,
          @to_CodCfoNorExt smallint,
          @to_CodCfoSbtInt smallint,
          @to_CodCfoSbtExt smallint,
          @to_CodCfoSubstituidoInt smallint,
          @to_CodCfoSubstituidoExt smallint,
          @to_FlgLanFin bit,
          @to_FlgBlqImpVol bit,
          @to_FlgCalPisCof bit,
          @to_IsnCtaFinDeb int,
          @to_IsnCtaFinDebInterv int,
          @to_IsnCtaFinCre int,
          @cf_FlgBlqTrfEstFis bit,
          @WCodCfoNor smallint,
          @WCodCfoSbt smallint,
          @WCodCfoBon smallint,
          @WFlgOpeInt bit,
          @WFlgRecalcula bit,
          @WVlrAux numeric(18,4)

  Select @to_CodCfoConFinInt = IsNull(Cod_CfoConFinInt,0),
	     @to_CodCfoConFinExt = IsNull(Cod_CfoConFinExt,0),
	     @to_CodCfoNorInt = Isnull(Cod_CfoNorInt,0),       
         @to_CodCfoNorExt = Isnull(Cod_CfoNorExt,0),
         @to_CodCfoSbtInt = Case 
		                      When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtIntSubstituido,0) > 0 then Cod_CfoSbtIntSubstituido
							  Else Isnull(Cod_CfoSbtInt,0)
							End, 
         @to_CodCfoSbtExt = Case 
		                      When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtExtSubstituido,0) > 0 then Cod_CfoSbtExtSubstituido
							  Else Isnull(Cod_CfoSbtExt,0)
							End, 
         @to_CodCfoSubstituidoInt = IsNull(Cod_CfoSbtIntSubstituido,0),
         @to_CodCfoSubstituidoExt = IsNull(Cod_CfoSbtExtSubstituido,0),
         @to_FlgLanFin = Isnull(Flg_LanFin,0),
         @to_FlgBlqImpVol = IsNull(Flg_BlqImpVol,0), 
         @to_FlgCalPisCof = IsNull(Flg_CalPisCof,0),
         @to_IsnCtaFinDeb = ISNULL(Isn_CtaFinDeb,0),
         @to_IsnCtaFinCre = ISNULL(Isn_CtaFinCre,0)
    From TPOPE
   Where Cod_Ope = @cb_TipFat 

  -- plano de contas   
  if (Select IsNull(FlgUsaInterv,0) From PMFIN) = 0
    begin
      Set @to_IsnCtaFinDeb = IsNull((Select Isn_CtaFin From CLIEN Where Codigo = @cb_CodCli),0)
      Set @to_IsnCtaFinCre = 0
    end
  else
    begin
      Set @to_IsnCtaFinDebInterv = 0
      if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinDeb)
        Set @to_IsnCtaFinDeb = 0
      if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinCre)
        Set @to_IsnCtaFinCre = 0
    
      if (@to_IsnCtaFinDeb = 0) or (@to_IsnCtaFinCre = 0)
        begin
          Set @to_IsnCtaFinDeb = 0
          Set @to_IsnCtaFinCre = 0
        end
      else
        if @to_IsnCtaFinDeb = (Select IsnCtaFinRecCli From PMFIN) 
          begin
            Set @to_IsnCtaFinDebInterv = IsNull((Select Isn_CtaFin From CLIEN Where Codigo = @cb_CodCli),0)
            if @to_IsnCtaFinDebInterv > 0
              Set @to_IsnCtaFinDeb = @to_IsnCtaFinDebInterv
          end
      if @to_IsnCtaFinDeb = @to_IsnCtaFinCre
        begin
         Set @to_IsnCtaFinDeb = 0
         Set @to_IsnCtaFinCre = 0
        end    
    end
     
  -- operacao interna ou externa
  if @cl_CodEst = @em_CodEst
    Set @WFlgOpeInt = 1
  else
    Set @WFlgOpeInt = 0

  if @rt_FlgConsumFin = 1
    if @WFlgOpeInt = 1
	  begin
        Set @WCodCfoNor = @to_CodCfoConFinInt
        Set @WCodCfoSbt = @to_CodCfoConFinInt
        Set @WCodCfoBon = 5910
      end
    else
	  begin
        Set @WCodCfoNor = @to_CodCfoConFinExt
        Set @WCodCfoSbt = @to_CodCfoConFinExt
        Set @WCodCfoBon = 6910
      end
  else
    if @WFlgOpeInt = 1
      begin
        Set @WCodCfoNor = @to_CodCfoNorInt
        Set @WCodCfoSbt = @to_CodCfoSbtInt
        Set @WCodCfoBon = 5910
	  end
    else
      begin
        Set @WCodCfoNor = @to_CodCfoNorExt
        Set @WCodCfoSbt = @to_CodCfoSbtExt
        Set @WCodCfoBon = 6910
      end

  -- coloca campos de NMFIS na memoria
  Declare @nm_NotFis int,
          @nm_SerNotFis int,
          @nm_ModNotFis varchar(2)

  if @pm_FlgNfe = 1
    begin
      -- verifica serie especifica para "incentivos"
      if Exists(Select ix.Ser_NfeEsp
                  From PDVCB cb
                       Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
                 Where cb.Cod_Estabe = @CodEstabe
                   And cb.Numero = @CodPed
                   And IsNull(ix.Ser_NfeEsp,0) > 0)
        if not Exists(Select ix.Ser_NfeEsp
                        From PDVCB cb
                             Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
                             Left  Join NMNFE nm on cb.Cod_Estabe = nm.Cod_Estabe and ix.Ser_NfeEsp = nm.Ser_Nfe
                       Where cb.Cod_Estabe = @CodEstabe
                         And cb.Numero = @CodPed
                         And IsNull(ix.Ser_NfeEsp,0) > 0
                         And IsNull(nm.Ser_Nfe,0) > 0)
          begin
            Insert Into NMNFE (Cod_Estabe, Ser_Nfe, Num_Nfe, Flg_Padrao, Flg_Contingencia, Mod_Nfe)
              Select cb.Cod_Estabe, ix.Ser_NfeEsp, 0, 0, 0, '55'
                From PDVCB cb
                     Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
               Where cb.Cod_Estabe = @CodEstabe
                 And cb.Numero = @CodPed
		  end

      -- poe dados de NMNFE na memoria
      if Exists(Select ix.Ser_NfeEsp
                  From PDVCB cb
                       Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
                       Inner Join NMNFE nm on cb.Cod_Estabe = nm.Cod_Estabe and ix.Ser_NfeEsp = nm.Ser_Nfe
                 Where cb.Cod_Estabe = @CodEstabe
                   And cb.Numero = @CodPed
                   And IsNull(ix.Ser_NfeEsp,0) > 0)
        Select @nm_SerNotFis = ix.Ser_NfeEsp
          From PDVCB cb
               Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
               Left Join NMNFE nm on cb.Cod_Estabe = nm.Cod_Estabe and ix.Ser_NfeEsp = nm.Ser_Nfe
          Where cb.Cod_Estabe = @CodEstabe
          And cb.Numero = @CodPed
          And IsNull(nm.Ser_Nfe,0) > 0
      else
        Select @nm_SerNotFis = Ser_Nfe
          From NMNFE
         Where Cod_Estabe = @CodEstabe 
           And Flg_Padrao = 1

      Select @nm_NotFis = Num_Nfe,
             @nm_ModNotFis = Mod_Nfe
        From NMNFE
       Where Cod_Estabe = @CodEstabe 
         And Ser_Nfe = @nm_SerNotFis
    end
  else
    begin
      Select @nm_NotFis = Nota_Fiscal_M1
        From NMFIS
       Where Cod_Estabe = @CodEstabe
    end

  -- variaveis de trabalho
  Declare @WQtdMov int,
          @WQtdPraNeg int,
          @WQtdDepNeg int,
          @WFlgEmpPra bit,
          @WFlgEmpDep bit,
          @WQtdMovLot int,
          @WQtdMovPed int,
          @WQtdMovBon int,
          @WQtdMovPra int,
          @WQtdMovDep int,
		  @WQtdDifDia int,
          @WTipNfs varchar(1),
          @WCodTabComOpe int,
          @WCodTabComVdr int,
          @WSumVlrBasDscIte numeric(18,4),
          @WCVlrTotNot numeric(18,4),
          @WVlrTotLiq numeric(18,4),
          @WVlrDesc numeric(18,4),
          @WVlrTotDspBolBan numeric(18,4),
          @WVlrJurPrzExc numeric(18,4),
          @WVlrBasFre numeric(18,4),
          @WCodDoc int,
          @WQtdPrdVrb int,
          @WPerRetBon numeric(18,4),
          @WCodPrm int,  -- codigo da promocao ou flag de politica promocional
          @WTipSai varchar(1),  -- 'B' = bonificacao
          @WVlrBasComiss numeric(18,4), 
          @WTipDes varchar(3),
          @WCodDes int,
          @WVlrMov numeric(18,4),
          @WIdTransacao int,
          @WCodFor int,
          @WVlrEdi numeric(18,4),
          @WVlrBru numeric(18,4),
          @WVlrLiqIte numeric(18,4),
          @WVlrLiqIteCusMed numeric(18,4)

          
  Set @PDatEmi = @Date
  Set @PEspNfs = ''
  Set @SerNfsRet = @cb_TipFat  -- FAT,ORC,FUN
  if @CodEstabe is null
    Set @CodEstabe = 0
  Set @NumNfsRet = @CodPed
  Set @PSerSel = ''
  Set @PNumSel = 0
  Set @PNumFor = 0
  Set @PQtdPagNfs = 0
  Set @PModNotFis = ''
  Set @PCodStaNfe = ''

  if @WCodCfoNor > 0
    begin
      Set @PEspNfs = 'NFF'
      Set @PQtdPagNfs = 0
      Set @PNumFor = 0
      Set @NumNfsRet = @nm_NotFis + 1

      if @pm_FlgNfe = 1 
        begin
          Set @SerNfsRet = cast(@nm_SerNotFis as varchar)
          Set @PModNotFis = @nm_ModNotFis
          Set @PCodStaNfe = 'N'         
		  exec PR_ProximoNumFiscal @CodEstabe, '', @nm_SerNotFis, 1, @NumNfsRet;
        end
      else
        begin
          Set @SerNfsRet = @pm_ModeloNotaFiscal    -- FAT para M1
          Set @PModNotFis = @pm_ModeloNotaFiscal
          Set @PCodStaNfe = ''
          if @pm_NumItePagNfs > 0
            Set @PQtdPagNfs = Ceiling(@cb_QtdIte*1.00 /@pm_NumItePagNfs)
          Set @PNumFor = @NumFor + @PQtdPagNfs - 1
          -- atualiza NMFIS
          if @pm_FlgCtrSelFis = 1
            begin
              Set @PSerSel = @pm_SerieSeloFiscal
              Set @PNumSel = @NumSel + @PQtdPagNfs - 1
              Update NMFIS
                 Set Nota_Fiscal_M1 = @NumNfsRet,
                     Formulario_M1 = @PNumFor,
                     Selo_Fiscal = @PNumSel
               Where Cod_Estabe = @CodEstabe    
            end
          else
            begin
              Update NMFIS
                 Set Nota_Fiscal_M1 = @NumNfsRet,
                     Formulario_M1 = @PNumFor
               Where Cod_Estabe = @CodEstabe    
            end
        end
    end

  if (@cb_TipVct <> 'V') and (@cb_TipVct <> 'A')
    Set @PTipVct = 'P'   -- parcelado
  else
    Set @PTipVct = @cb_TipVct

  Set @PVlrDscCom = 0
  Set @WSumVlrBasDscIte = 0
  if @cb_PerDscCom > 0
    begin
      Set @PVlrDscCom = Round((@cb_VlrBasDscCom - @cb_VlrRepIcm) * @cb_PerDscCom/100,2)
      Set @WSumVlrBasDscIte = IsNull((Select sum(Round(Qtd_Pedido*C_PrcUni*(1-C_PerDscIte/100),2)-Vlr_RepIcms)
                                        From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                                         And Desconto = 0 And Qtd_Pedido > 0),0)
      if @PVlrDscCom > @WSumVlrBasDscIte
        begin
          Set @PVlrDscCom = 0
          Set @cb_PerDscCom = 0
        end
     end
    
  -- registra tipo de retencao do imp. subst.
  -- se nao tem credenciamento no estado: nao retem na fonte
  -- F- imposto incluido no valor da NF
  -- R- imposto a recolher, nao incluido na NF mas cobrado na duplicata
  Set @PTipRetImp = 'F'
  if @to_CodCfoNorInt > 0  
    if @uf_FlgRegSubTri = 0
      Set @PTipRetImp = 'R'

  if @PTipRetImp = 'R'
    Set @PVlrTotNot = @cb_VlrLiqIte - @PVlrDscCom - @cb_VlrDscBon - @cb_VlrRepIcm + @cb_VlrDespes + @cb_VlrDspExt + @cb_VlrIpi + @cb_VlrSbtRes
  else
    Set @PVlrTotNot = @cb_VlrLiqIte - @PVlrDscCom - @cb_VlrDscBon - @cb_VlrRepIcm + @cb_VlrDespes + @cb_VlrDspExt + @cb_VlrIpi + @cb_VlrSbtRes + @cb_VlrSubTri - @cb_VlrDscTri

  if @cb_FlgVlrFin = 1
    if (@WCodCfoNor > 0) or (@SerNfsRet = 'ORC') or (@to_FlgLanFin = 1)
      begin
        -- recalcula prazo medio, qtd parcelas e desc. financ. ponderado da nf
        Declare @WSomat numeric(18,4), 
                @WVlrDup numeric(18,4), 
                @WVlrFin numeric(18,4)

        Set @PQtdPar = Isnull((Select COUNT(*)
                                 From PDVDP
                                Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed),0)
                
        Set @WSomat = Isnull((Select sum(Vlr_Duplic*cast(Dat_Vencim - @cb_DatPed as int))
                                From PDVDP
                               Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                                 And IsNull(Flg_Apresentacao,0)=0),0)
        
        Set @WVlrDup = Isnull((Select sum(Vlr_Duplic)
                                 From PDVDP
                                Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed),0)
                
        Set @WVlrFin = Isnull((Select sum(Vlr_DescFinanc)
                                 From PDVDP
                                Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed),0)
                
        -- atualiza cabecalho da NF
        if @WVlrDup > 0 
          begin
            Set @PQtdPrzMed = Round(@WSomat/@WVlrDup,0)
            if @cb_TipVct <> 'P'    --nao ponderado
              Set @PPerDscFinLiq = Round(@WVlrFin*100/@WVlrDup,4) 
          end
        else
          begin
            Set @PQtdPrzMed = 0
            Set @PPerDscFin = 0
          end
      end

  -- recalcula desconto financeiro (aplicar somente sobre valor tot. mercadoria) p/ gravar no item
  Set @PPerDscFin = IsNull(@PPerDscFinLiq,0)
  if ((@cb_VlrSubTri+@cb_VlrSbtRes) > 0) and (@PPerDscFinLiq > 0)
    begin
      Set @WVlrTotLiq = @cb_VlrLiqIte - @PVlrDscCom - @cb_VlrDscBon - @cb_VlrRepIcm - @cb_VlrDscTri 
      Set @WVlrDesc = @PPerDscFinLiq * @WVlrTotLiq / 100
      Set @WVlrTotLiq = @WVlrTotLiq + @cb_VlrSubTri + @cb_VlrSbtRes
      if @WVlrTotLiq > 0 
        Set @PPerDscFin = Round(@WVlrDesc/@WVlrTotLiq*100,2)
    end

  -- calcula despesa ref. taxa administrativa
  Set @WVlrOutDsp = 0.00     
  if @ag_PerTaxAdm > 0
    begin
      if @ag_CodAplTaxAdm = 'P' -- margem (participação)
        Set @WVlrOutDsp = Round(@cb_VlrLiqIte/(1-@ag_PerTaxAdm/100),2)-Round(@cb_VlrLiqIte,2)
      if @ag_CodAplTaxAdm = 'A'  -- mark-up (acrescimo)
        Set @WVlrOutDsp = Round(@cb_VlrLiqIte*@ag_PerTaxAdm/100,2)     
    end

  -- calcula despesa boleto bancario a cobrar na nota fiscal
  Set @WVlrTotDspBolBan = 0
  if @to_FlgLanFin = 1
    begin
      Set @WVlrTotDspBolBan = Round(Isnull(@ag_VlrDspBolBan,0) * @PQtdPar,2)
      Set @WVlrOutDsp = @WVlrOutDsp + @WVlrTotDspBolBan
    end

  -- debito verba/despesa de boleto vendedor
  Set @PVlrDebVrbVdr = 0
  if @TipNfs = 'V'
    begin
      -- taxa boleto
      if @pm_FlgDebBlqBanVrbVdr = 1
        begin
          Set @PVlrDebVrbVdr = @WVlrTotDspBolBan
          Set @WVlrOutDsp = @WVlrOutDsp - @WVlrTotDspBolBan    -- isenta cliente
        end
      -- juros prazo excedente
      Set @WVlrJurPrzExc = 0
      Set @WQtdDifDia = cast(@PQtdPrzMed as int) - @pm_QtdPrzMedCfg
      if (@WQtdDifDia > 0) and (@pm_QtdPrzMedCfg > 0) and (@pm_PerCusFinDiaExcPrzMedCfg > 0)
        begin
          Set @WVlrJurPrzExc = @WQtdDifDia*@pm_PerCusFinDiaExcPrzMedCfg*@PVlrTotNot/100
          Set @PVlrDebVrbVdr = @PVlrDebVrbVdr + @WVlrJurPrzExc
        end   
    end

  if @cb_VlrDespes <> @WVlrOutDsp
    Set @PVlrOutDsp = @WVlrOutDsp
  else
    Set @PVlrOutDsp = @cb_VlrDespes

  if @cb_CodCli > 0
    begin
      Set @PCgc = @cl_CgcCpf
      Set @PCgf = @cl_Cgf
      Set @PDesEnd  = Substring(@cl_DesEnd,1,50)
      Set @PDesBai = @ba_DesBai
      Set @PCep = @cl_Cep
      Set @PEst = @cl_CodEst
      Set @PDesCid = @ci_DesCid
      Set @PCodCid = @cl_CodCid
      Set @PCodCidIbge = @ci_CodCidIbge
      Set @PCodMacReg = @ba_CodMacReg 
      Set @PCodMicReg = @ba_CodMicReg
     end
  else
    begin
      Set @PCgc = ''
      Set @PCgf = ''
      Set @PDesEnd  = ''
      Set @PDesBai = ''
      Set @PCep = @em_Cep 
      Set @PEst = @em_CodEst
      Set @PDesCid = (Select Descricao From CIDAD Where Cod_Estado = @em_CodEst And Codigo = @pm_CodCidEmpLoc)
      Set @PCodCid = @pm_CodCidEmpLoc
      Set @PCodCidIbge = (Select Cod_CidIbge From CIDAD Where Cod_Estado = @em_CodEst And Codigo = @pm_CodCidEmpLoc)
      Set @PCodMacReg = @pm_CodMacRegEmpLoc
      Set @PCodMicReg = @pm_CodMicRegEmpLoc
    end

  -- Grava registro NFSCB 
  if (@cb_VlrSubTri+@cb_VlrSbtRes) > 0
    Set @PCodCfo = @WCodCfoSbt
  else
    Set @PCodCfo = @WCodCfoNor

  Set @PUfPlaVei = @cb_UfPlaVei
  Set @PCodPlaVei = @cb_CodPlaVei
  if (@PUfPlaVei = '') and (@tr_Pessoa = 'F')
    begin
      Set @PUfPlaVei = @tr_UfPlaVei
      Set @PCodPlaVei = @tr_CodPlaVei
    end

  -- registra Insc.Est. ST do emitente na UF destino
--  if (@WFlgOpeInt = 0) and (@uf_FlgRegSubTri= 1) and (@uf_BlqInsEstSbtNfs = 0)
  if @uf_FlgRegSubTri= 1
    Set @PNumInscriSbtEmiUfd = @uf_NumInscriSbt
  else
    Set @PNumInscriSbtEmiUfd = ''


  -- aqui cuidado: implementar em PR_AtualizaCabecNFS ou PR_CalcTributNFS ?????
  if @PTipRetImp = 'R'
    begin
      Set @PVlrSubTri = 0
      Set @PVlrDscTri = 0
      Set @PVlrRecSbt = @cb_VlrSubTri
	  if @cb_VlrSubTri >= @cb_VlrDscTri
        Set @PVlrRecSbt = @cb_VlrSubTri - @cb_VlrDscTri
    
	  Set @PVlrFcpSbt = 0
	  Set @PVlrFcpSbtRec = @cb_VlrSubTriFcp 
    end
  else
    begin
      Set @PVlrSubTri = @cb_VlrSubTri
      Set @PVlrDscTri = @cb_VlrDscTri
      Set @PVlrRecSbt = 0

	  Set @PVlrFcpSbt = @cb_VlrSubTriFcp
	  Set @PVlrFcpSbtRec = 0
    end


  Insert into NFSCB (Cod_Estabe, Ser_Nota, Num_Nota)
    Values (@CodEstabe, @SerNfsRet, @NumNfsRet)
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end    

  Select @cf_FlgBlqTrfEstFis = IsNull(Flg_BlqTrfEstFis,0) 
    From TBCFO 
   Where Codigo = @PCodCfo

  Update NFSCB 
     Set Esp_Nota = @PEspNfs, 
         Qtd_PagNf = @PQtdPagNfs, 
         Ser_Selo = @PSerSel, 
         Num_Selo = @PNumSel, 
         Num_Formulario = @PNumFor,
         Cod_Cfo1 = @PCodCfo,
         Flg_BlqTrfEstFis = IsNull(@cf_FlgBlqTrfEstFis,0),
         Flg_WMS = @WFlgWMS, 
         Cod_ModDoc = @PModNotFis, 
         Cod_StaNfe = @PCodStaNfe, 
         Flg_RetEnt = 0, 
         Flg_Storage = 0,  
         Flg_Email = 0,

         Tip_Vencimento = @PTipVct,
         Dat_Emissao = @PDatEmi, 
         Cod_Cliente = @cb_CodCli, 
         Tip_Consumidor = @cb_TipCon, 
         Cod_Funcionario = @cb_CodFun, 
         Consumidor = @cb_NomCon, 
         Cod_Pedido = @CodPed,  
         Cod_OrigemNfs = @cb_CodOriPdv,
         Cod_Digitador = @cb_CodDig,  
         Cod_VendTlmkt = @cb_CodOpe, 
         Cod_Vendedor = @cb_CodVdr, 
         Cod_Supervisor = @cb_CodSup, 
         Cod_Gerencia = @cb_CodGer, 
         Cod_SupOpe = @cb_CodSupOpe,  
         Cod_GerOpe = @cb_CodGerOpe, 
         Cod_Agente = @cb_CodAgc,  
         Cod_Transportadora = @cb_CodTra, 
         Cod_Rota = @cb_CodRot, 
         Cod_Ope = @cb_TipFat,
         Cod_RamAtv = @cl_CodRamAtv, 

         Vlr_FrePrv = @cb_VlrFrePrv, 
         Qtd_PrzMed = @PQtdPrzMed, 
         Qtd_Parcela = @PQtdPar, 
         Id_PolCom = @cb_IdPolCom, 
         Per_Faturado = cast(@cb_PerSubFat as int), 
         Num_NotSubFat = 0,  
         Per_DescontoFin = @PPerDscFin, 
         Per_DscFinLiq = @PPerDscFinLiq, 

         Qtd_Peso = @cb_QtdPes, 
         Qtd_Volumes = @cb_QtdVol, 

         Vlr_BasDscCom = @cb_VlrBasDscCom, 
         Vlr_BasPar = @cb_VlrBasPar, 

         Cod_RegTri = @cb_CodRegTri,
         Flg_IcmsSobreTotal = @rt_CtrImpIcmTotNfs, 
         Num_InscriSubTriEmiUfd = @PNumInscriSbtEmiUfd, 
         Inscricao_Suframa = @cb_InscricaoSuframa, 
         Vlr_SubsTribEmb = 0,

         Per_DescontoCom = @cb_PerDscCom, 
         Vlr_DscBon = @cb_VlrDscBon, 

         Cgc = @PCgc,  
         Cgf = @PCgf, 
         Endereco = @PDesEnd, 
         Bairro = @PDesBai, 
         Cep = @PCep, 
         Estado = @PEst, 
         Cidade = @PDesCid, 
         Cod_Cidade = @PCodCid, 
         Cod_CidIbge = @PCodCidIbge, 
         Cod_MacroReg = @PCodMacReg, 
         Cod_MicroReg = @PCodMicReg,

         Flg_ComisNormal = @PFlgComNor,  
         Per_ComOpe = @PPerComOpe,  
         Per_ComVnd = @PPerComVnd, 
         Per_ComSup = 0, 
         Per_ComGer = 0, 
         Per_ComSupOpe = 0,  
         Per_ComGerOpe = 0,
         Vlr_ComPagTlmkt = 0,  
         Vlr_ComPag = 0, 
         Vlr_ComPagSup = 0, 
         Vlr_ComPagGer = 0, 
         Vlr_ComPagSupOpe = 0, 
         Vlr_ComPagGerOpe = 0,

         Ide_PedCmp = @cb_CodPedCmpCli,  
         Ide_NotEmp = @cb_NotEmpCli, 
         Ide_Contra = @cb_NumConCli, 
         Des_Convenio = @cb_DesConven, 
         Des_LayoutPde = @cb_DesLayPde, 
         Cod_PrjPde = @cb_CodPrjPde,
         Cod_PedCliPde = @cb_CodPedCliPde,

         Flg_BlqImpVol = @to_FlgBlqImpVol, 
         Uf_PlaVei = @PUfPlaVei, 
         Cod_PlaVei = @PCodPlaVei, 
         Cod_Contrato = @cb_CodCtr, 
         Id_Consig = @cb_IdConsig,  
         Num_SequenciaCtr = @cb_NumSeqCtr,
         
         Vlr_DebVrbVdr = @PVlrDebVrbVdr, 
         Tip_GerVrb = @cb_TipGerVrb, 
         
         -- atualizados em PR_AtualizaCabecNFS
         Tip_Frete = @cb_TipFrete, 
         Qtd_Itens = @cb_QtdIte, 
         Vlr_LiqItens = @cb_VlrLiqIte,  
         VlrBruItens = 0, 
         Vlr_DescontoCom = @PVlrDscCom, 
         Vlr_OutDsp = @PVlrOutDsp, 
         Vlr_TotalNota = (@PVlrTotNot + @PVlrOutDsp),
         Vlr_Frete = @cb_VlrFrete, 
         Vlr_DspExt = @cb_VlrDspExt, 
         Vlr_BasRepIcms = 0, 
         Vlr_RepIcms = @cb_VlrRepIcm, 
         Vlr_PrdSubTri = 0, 
         Vlr_BasSubsTrib = 0, 
         Vlr_BasSbtRes = 0,
         Vlr_BasRecSbt = 0, 
         Vlr_BasIcmsNor = 0, 
         Vlr_IcmsNor = 0, 
         Vlr_BasIcmsTri = 0, 
