          @pr_CodGrpPrc varchar(1),          
		  @it_CodFab int,
		  
		  -- IRRF
		  @it_VlrBasIrf numeric(18,4),
		  @it_AlqIrf numeric(7,4),
		  @it_VlrIrf numeric(18,4)
                    
  Declare @WFlgAcumula bit,
          @WFatBon numeric(18,8),
          @WFatParIte numeric(18,8),
          
          @Acp_UndIte int,
          
          @Sld_QtdPed int,
          @Sld_QtdBon int,

          @Acp_VlrTotIte numeric(18,4),
          @Acp_VlrLiqIte numeric(18,4),
          @Acp_VlrBruIte numeric(18,4),
          @Acp_VlrDscBonRat numeric(18,4),
          @Acp_VlrDespes numeric(18,4),
          @Acp_VlrDspExt numeric(18,4),
          @Acp_VlrBasIcmNor numeric (18,4),
          @Acp_VlrIcmNor numeric (18,4),
          @Acp_VlrBasRepIcm numeric (18,4),
          @Acp_VlrRepIcm numeric (18,4),
          @Acp_VlrPrdSubTri numeric (18,4),
          @Acp_VlrBasSubTri numeric (18,4),
          @Acp_VlrSubTri numeric (18,4),
		  @Acp_VlrBasSbtRes numeric (18,4),
          @Acp_VlrSbtRes numeric (18,4),
