		  @Acp_VlrDscCalSuf numeric(18,4),
          @Acp_VlrIsento numeric (18,4),
          @Acp_VlrOutros numeric (18,4),
          @Acp_VlrBasTri numeric (18,4),

          @Acp_VlrBasVerba numeric (18,4),
          @Acp_VlrVerba numeric (18,4),
          @Acp_VlrVrbVdr numeric (18,4),
