GO

CREATE PROCEDURE [dbo].[PR_SolicitaLoteEspecificoPDV]
/*
Solicita lote especifico do Picking

*/
@PCodEstabe int,
@PCodPed int,             
@PCodPrd int,
@PCodLotEsp varchar(20),  -- lote especifico
@PQtdPed int             -- quantidade pedida do lote
--@PMsg varchar(80) output  -- Quantidde pedida do lote: 1000. Quantidae Atendida: 1000.

AS

SET NOCOUNT ON 

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)


Declare @MsgErr varchar(50) = '',
        @QtdSld int = 0,
        @FlgUndMin bit = 0 

Set @PCodLotEsp = Ltrim(Rtrim(@PCodLotEsp))

if not Exists(Select 1 From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PCodPed)
  begin
    RAISERROR('Pedido inexistente',16,1)
    Return
  end

if not Exists(Select 1 From PDVIT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed And Cod_Produto = @PCodPrd And Qtd_Pedido > 0)
  begin
    RAISERROR('Produto inexiste no pedido',16,1)
    Return
  end

Set @MsgErr = IsNull((Select MsgErr = Case
                                        When CharIndex(Status2,';N;D;') > 0 then 'Pedido já faturado'
                                        When (Status1 <> 'P') or (Status2 <> 'F') then 'Pedido não está pendente/fechado'
                                        When IsNull(Bloqueio,'') <> '' then 'Pedido está bloqueado'
                                        When IsNull(Flg_Wms,0) = 0 then 'Pedido não permite solicitar lotes'
                                        Else ''
                                      End
                        From PDVCB
                       Where Cod_Estabe = @PCodEstabe
                         And Numero = @PCodPed),'')

if (@MsgErr = '') and
   Exists(Select Cod_Produto, Tip_Sai, count(*) From PDVIT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed Group By Cod_Produto, Tip_Sai Having count(*) > 1)
  Set @MsgErr = 'Existe mais de um lote no pedido'

if @MsgErr <> ''
  begin
    RAISERROR(@MsgErr,16,1)
    Return
  end

if @PCodLotEsp = ''
  begin
    RAISERROR('Lote não informado',16,1)
    Return
  end

Set @QtdSld = IsNull((Select Qtd_Saldo From PRLOT Where Cod_Estabe = @PCodEstabe and Cod_Produt = @PCodPrd and Cod_Lote = @PCodLotEsp),0)
if @QtdSld = 0
  begin
    RAISERROR('Produto/Lote inexistente ou Sem Estoque',16,1)
    Return
  end

if @PQtdPed <= 0
  begin
    RAISERROR('Quantidade solicitada inválida',16,1)
    Return
  end

-- verifica se a qtd solicitade não excede a qtd pendente a solicitar
Set @QtdSld = IsNull((Select QtdSld = (IsNull(it.QtdPdvTot,0)-IsNull(d.QtdSolTot,0))
                        From (Select Cod_Estabe, Cod_Produto, sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) as QtdPdvTot
                                From PDVIT 
                               Where Cod_Estabe = @PCodEstabe
                                And Cod_Pedido = @PCodPed
                                And Cod_Produto = @PCodPrd
                                And IsNull(Qtd_Pedido,0) > 0
                              Group by Cod_Estabe, Cod_Produto
                             ) it Left Outer Join

                             (Select Cod_Estabe, Cod_Produt, sum(IsNull(Qtd_Lote,0)) as QtdSolTot
                                From PDVLT
                               Where Cod_Estabe = @PCodEstabe
                                And Cod_Pedido = @PCodPed
                                And Cod_Produt = @PCodPrd
                                And IsNull(Qtd_Lote,0) > 0 
                              Group by Cod_Estabe, Cod_Produt
                             ) d on (it.Cod_Estabe = d.Cod_Estabe and it.Cod_Produto = d.Cod_Produt
                     )
                    ),0)
if @QtdSld < 0
  begin
    RAISERROR('Quantidade já solicitada excede à quatidade pedida',16,1)
    Return
  end
if @QtdSld = 0
  begin
    RAISERROR('Quantidade do pedido já foi totalmente atendida',16,1)
    Return
  end
if @PQtdPed > @QtdSld
  begin
    Set @MsgErr = 'Quantidade pedida excede quantidade pendente ('+cast(@QtdSld as varchar)+')'
    RAISERROR(@MsgErr,16,1)
    Return
  end

-- verifica se cliente bloqueia produto com mais de um lote
if Exists(Select 1 From CLIEN cl Inner Join PDVCB cb on (cb.Cod_Cliente = cl.Codigo)
           Where cb.Cod_Estabe = @PCodEstabe And cb.Numero = @PCodPed
             And IsNull(cl.Flg_BlqLotVarPdv,0) = 1) and
   Exists(Select 1 From PDVLT WHere Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed 
             And Cod_Produt = @PCodPrd And Cod_Lote <> @PCodLotEsp)
  begin
    RAISERROR('Cliente não permite mais de um lote do mesmo produto',16,1)
    Return
  end

-- verifica se trabalha com unidade minima
Set @MsgErr = ''

Select @FlgUndMin = IsNull(FlgAltUnvItePdv,0) 
  From PARAM Where Cod_Estabe = @PCodEstabe

-- se trabalha com unidade minima verifica apresentações padrão
if Exists(Select 1
            From PDVIT it
                 Inner Join PARAM pa on it.Cod_Estabe = pa.Cod_Estabe
                 Left  Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and IsNull(ap.Flg_Padrao,0) = 1
           Where it.Cod_Estabe = @PCodEstabe And it.Cod_Pedido = @PCodPed And it.Cod_Produto = @PCodPrd
             And it.Qtd_Pedido > 0
             And @FlgUndMin = 1
             And ap.Cod_Produt is null)
  Set @MsgErr = 'Produto sem Apresentação Padrão'
else
-- se trabalha com unidade minima verifica produtos com mais de 1 apresentação padrão
if Exists(Select 1
            From PRXAP ap
           Where ap.Flg_Padrao = 1
             And @FlgUndMin = 1
             And Exists(Select 1 From PDVIT it Where it.Cod_Estabe = @PCodEstabe and it.Cod_Pedido = @PCodPed And it.Cod_Produto = ap.Cod_Produt And it.Qtd_Pedido > 0 )
           Group by ap.Cod_Produt
          Having count(*) > 1)
  Set @MsgErr = 'Produto com mais de uma Apresentação Padrão'
else
  -- se trabalha com unidade minima verifica produtos sem medidas da embalagem padrao
if Exists(Select 1
            From PDVIT it
                 Left Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and ap.Flg_Padrao = 1
           Where it.Cod_Estabe = @PCodEstabe 
             And it.Cod_Pedido = @PCodPed 
             And it.Cod_Produto = @PCodPrd
             And it.Qtd_Pedido > 0
             And ((IsNull(ap.Fat_CnvApr,0) = 0) or (IsNull(ap.Vol_Emb,0) = 0))
             And @FlgUndMin = 1)
  Set @MsgErr = 'Produto com Cadastro da Apresentação Padrão Incompleto'
else
-- se nao trabalha com unidade minima verifica produtos sem medidas da embalagem padrao
if Exists(Select 1
            From PDVIT it
                 Left Join PRODU pr on it.Cod_Produto = pr.Codigo
           Where it.Cod_Estabe = @PCodEstabe 
             And it.Cod_Pedido = @PCodPed 
             And it.Cod_Produto = @PCodPrd
             And it.Qtd_Pedido > 0
             And IsNull(pr.Vol_Emb,0) = 0
             And @FlgUndMin = 0)
  Set @MsgErr = 'Produto com Cadastro da Embalagem Padrão Incompleto'

if @MsgErr <> ''
  begin
    RAISERROR(@MsgErr,16,1)
    Return
  end


BEGIN
  --Set @PMsg = ''

  Declare @CodPrd int,
          @TipSai varchar(1),
          @QtdSdo int,
          @CodLotTip varchar(20),
          @QtdTotTip int,
          @QtdPraTip int,
          @QtdDepTip int,
          @QtdFra int,
          @QtdEmbFec int,
          @QtdSldFiscal int,
          @QtdSolTot int,
          @cl_CodCliPag int,
          @cl_CodGrpCli int,
          @cl_QtdMesMinPrzVctLot int,
          @cl_FlgBlqLotVarPdv bit,
          @FlgIntWms bit = 0,
          @BlqEstFisNeg bit = 0,
          @StaIntWms varchar(1),
          @FlgTipVenFat bit = 0,
          @FlgPodeFechar bit = 0,
		  @Usuario varchar(15)

  Set @Usuario = dbo.FN_UsuarioInfarma()

  Select @FlgIntWms = IsNull(FlgIntegrWmsExt,0),
         @BlqEstFisNeg = IsNull(BlqEstFisNeg,0)   -- nao permite negativar estoque fiscal
    From PMEST Where Cod_Estabe = @PCodEstabe

  Select @StaIntWms = IsNull(cb.Sta_IntWms,''),
         @FlgTipVenFat = Case When ISNull(op.Cod_CfoNorInt,0) > 0 then 1 ELse 0 End
    From PDVCB cb
         Left Join TPOPE op on cb.Tip_Faturamento = op.Cod_Ope 
   Where cb.Cod_Estabe = @PCodEstabe and cb.Numero = @PCodPed


  Begin Transaction

    Set @FlgPodeFechar = 0

    if @FlgIntWms = 0
      Set @FlgPodeFechar = 1
    else
    if @StaIntWms = ''
      begin
	  -- aqui ????
        Update PDVCB
           Set Sta_IntWMS = '0'
         Where Cod_Estabe = @PCodEstabe 
           And Numero = @PCodPed
           And IsNull(Sta_IntWMS,'') = ''

--aqui        Exec PR_WMSGerarXMLSaida @PCodEstabe, @PCodPed
      end

    if @FlgPodeFechar = 1
      begin 
		-- TBZON
        Update TBZON
           Set Num_Esteira = 1
         Where Cod_Estabe = @PCodEstabe
           And ISNULL(Num_Esteira,0) = 0

        Declare @NumVol int,
                @to_CodCfoNorInt int,
                @DatVct smalldatetime,
                @CodLot varchar(20),
                @LocEst varchar(1),
                @OrdDep varchar(1),
                @CodDep int, 
                @NumEst smallint,
                @NumRua int, 
                @NumCol int, 
                @NumNiv int, 
                @NumApt int, 
                @SldLot int,
                @FatCnvAprEmbPad int,
                @FatCnvImpFat int,
                @QtdPra int,
                @QtdDep int,
                @QtdLot int,
                @FlgDesord bit,
                @dx_CodLocFis varchar(15),
                @pr_VolUniMin numeric(18,8),  -- @pr_VolEmb
                @VolTotIte numeric(18,4),
                @QtdAteAcu int,
                @QtdAte int

        Select @cl_CodCliPag = Case 
                                 When IsNull(cl.Cod_CliPag,0) > 0 then cl.Cod_CliPag
                                 Else IsNull(cl.Codigo,0)
                               End,
               @cl_QtdMesMinPrzVctLot = IsNull(cl.Qtd_MesMinPrzVctLot,0),
               @cl_CodGrpCli = IsNull(cl.Cod_GrpCli,0),
			   @cl_FlgBlqLotVarPdv = IsNull(Flg_BlqLotVarPdv,0)
          From PDVCB cb Left Join CLIEN cl on (cb.Cod_Cliente = cl.Codigo)
         Where cb.Cod_Estabe = @PCodEstabe 
           And cb.Numero = @PCodPed
          
        Select @to_CodCfoNorInt = IsNull(t.Cod_CfoNorInt,0)
          From PDVCB p Left Join TPOPE t on (t.Cod_Ope = p.Tip_Faturamento)
         Where p.Cod_Estabe = @PCodEstabe 
           And p.Numero = @PCodPed

        Set @NumVol = 0

        -- elimina registro de conferencia existentes
        if Exists(Select 1 from CPVIT Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @PCodPed) 
          Delete from CPVIT Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @PCodPed
        if Exists(Select 1 From CPVCB Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @PCodPed)
          Delete from CPVCB Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @PCodPed
        
        -- cria arq. de fracionados
        IF OBJECT_ID('tempdb..#ARQ_FRAC') IS NOT NULL
          DROP TABLE #ARQ_FRAC
  
        CREATE TABLE #ARQ_FRAC
        (
            Chave int identity,
            Cod_Dep smallint,
            Num_Esteira smallint,
            Cod_Produto int,
            Cod_Lote varchar(20),
            Qtd_Lote int,
            Qtd_Pra int,
            Qtd_Dep int,
            Qtd_EmbFec int,
            Fat_CnvAprPad int, 
            Fat_CnvImpFat int, 
            Vol_UniIte numeric(18,8),
            Num_Rua smallint,
            Num_Col smallint,
            Num_Niv smallint,
            Num_Apt smallint,
            Cod_LocFis varchar(15),
            Flg_Desord bit
        ) 
        
        -- valida fracionado a solicitar descontando o que já foi soicitado (PDVLT)
        -- verifica se cliente bloqueia produto com lotes diferentes
        Select @QtdEmbFec = pr.Qtd_Embalagem, 
               @pr_VolUniMin = Case 
                                 When @FlgUndMin = 0 then IsNull(pr.Vol_Emb,0)
                                 Else IsNull(ap.Vol_Emb/ap.Fat_CnvApr,0)
                               End,
               @QtdFra = Case 
                           When x.QtdPen <= 0 then 0
                           When (@cl_FlgBlqLotVarPdv = 1) and 
                                Exists(Select 1 From PDVLT WHere Cod_Estabe = @PCodEstabe 
                                       And Cod_Pedido = @PCodPed And Cod_Produt = @PCodPrd And Cod_Lote <> @PCodLotEsp) then 0
                           When x.QtdPen >= @PQtdPed then @PQtdPed
                           Else x.QtdPen
                         End,
               @FatCnvImpFat = IsNull((Select max(IsNull(Fat_CnvImpFat,1)) From PDVIT WHere Cod_Estabe = @PCodEstabe 
                                          And Cod_Pedido = @PCodPed And Cod_Produto = @PCodPrd),1)
          From (Select it.Cod_Produto, QtdPen = (it.QtdPdvTot-IsNull(d.QtdSolTot,0))
                  From (Select Cod_Produto, sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) as QtdPdvTot
                          From PDVIT 
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Pedido = @PCodPed
                           And Cod_Produto = @PCodPrd
                           And IsNull(Qtd_Pedido,0) > 0
                         Group by Cod_Produto
                       ) it Left Outer Join
             
                       (Select Cod_Produt, sum(IsNull(Qtd_Lote,0)) as QtdSolTot
                          From PDVLT
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Pedido = @PCodPed
                           And Cod_Produt = @PCodPrd
                           And IsNull(Qtd_Lote,0) > 0 
                         Group by Cod_Produt
                       ) d on ( it.Cod_Produto = d.Cod_Produt)
               ) x 
               Inner Join PRODU pr on (x.Cod_Produto = pr.Codigo)
               Left  Join PRXAP ap on (pr.Codigo = ap.Cod_Produt) and (ap.Flg_Padrao = 1)


        -- verifica estoque fiscal negativo
        -- nao permite negativar estoque fiscal
        if (@BlqEstFisNeg = 1) and (@FlgTipVenFat = 1)
          begin
            -- qtd solicitada anteriormente
            Set @QtdSolTot = IsNull((Select sum(Qtd_Lote) From PDVLT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed 
                                        And Cod_Produt = @PCodPrd),0)
            Set @QtdSldFiscal = dbo.FN_SldFiscalDisponPrd(@PCodEstabe,@PCodPrd) - @QtdSolTot
            if @QtdSldFiscal < 0 Set @QtdSldFiscal = 0
            if @QtdFra > @QtdSldFiscal 
              Set @QtdFra = @QtdSldFiscal
          end
 
        Set @QtdAteAcu = 0    -- acumulador por produto

        -- fracionados solicita somente pelo vencimento --
        if @to_CodCfoNorInt > 0
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For   
              Select '1' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldPra, lt.Fat_CnvAprEmbPad
                From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                             Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                        From PRLOT l1 Inner Join
                             DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                       Where l1.Cod_Estabe = @PCodEstabe 
                         And l1.Cod_Produt = @PCodPrd
                         And l1.Cod_Lote = @PCodLotEsp
                         And IsNull(l1.Qtd_Saldo,0) > 0 
                         and IsNull(l1.Qtd_SldPra,0) > 0
                      UNION ALL
                      Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                             Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                        From PRLOT l2 
                       Where l2.Cod_Estabe = @PCodEstabe 
                         And l2.Cod_Produt = @PCodPrd
                         And l2.Cod_Lote = @PCodLotEsp
                         And IsNull(l2.Qtd_Saldo,0) > 0 
                         And IsNull(l2.Qtd_SldPra,0) > 0
        			     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                     PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where lt.Cod_Estabe = @PCodEstabe 
                 And lt.Cod_Produt = @PCodPrd
                 And lt.Cod_Lote = @PCodLotEsp
                 And IsNull(lt.Qtd_Saldo,0) > 0 and IsNull(lt.Qtd_SldPra,0) > 0
                 And ((lt.Dat_Vencim is null) or 
                      (lt.Dat_Vencim >= Case
                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                          Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                        End)) 
              UNION ALL
              Select '2' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldDep, lt.Fat_CnvAprEmbPad
                From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                             Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                        From PRLOT l1 Inner Join
                             DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                       Where l1.Cod_Estabe = @PCodEstabe 
                         And l1.Cod_Produt = @PCodPrd
                         And l1.Cod_Lote = @PCodLotEsp
                         And IsNull(l1.Qtd_Saldo,0) > 0 
                         and IsNull(l1.Qtd_SldDep,0) > 0
                      UNION ALL
                      Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                             Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                        From PRLOT l2 
                       Where l2.Cod_Estabe = @PCodEstabe 
                         And l2.Cod_Produt = @PCodPrd
                         And l2.Cod_Lote = @PCodLotEsp
                         And IsNull(l2.Qtd_Saldo,0) > 0 
                         And IsNull(l2.Qtd_SldDep,0) > 0
        			     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                     PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where lt.Cod_Estabe = @PCodEstabe 
                 And lt.Cod_Produt = @PCodPrd
                 And lt.Cod_Lote = @PCodLotEsp
                 And IsNull(lt.Qtd_Saldo,0) > 0 and IsNull(lt.Qtd_SldDep,0) > 0
                 And ((lt.Dat_Vencim is null) or 
                      (lt.Dat_Vencim >= Case
                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                          Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                        End)) 
               Order by OrdDep, Dat_Vencim, CodLocEst
          end -- if @to_CodCfoNorInt > 0
        else
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For 
              Select '1' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldPra, lt.Fat_CnvAprEmbPad
                From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                             Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                        From PRLOT l1 Inner Join
                             DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                       Where l1.Cod_Estabe = @PCodEstabe 
                         And l1.Cod_Produt = @PCodPrd
                         And l1.Cod_Lote = @PCodLotEsp
                         And IsNull(l1.Qtd_Saldo,0) > 0 
                         and IsNull(l1.Qtd_SldPra,0) > 0
                      UNION ALL
                      Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                             Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0) 
                        From PRLOT l2 
                       Where l2.Cod_Estabe = @PCodEstabe 
                         And l2.Cod_Produt = @PCodPrd
                         And l2.Cod_Lote = @PCodLotEsp
                         And IsNull(l2.Qtd_Saldo,0) > 0 
                         And IsNull(l2.Qtd_SldPra,0) > 0
        			     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                     PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where lt.Cod_Estabe = @PCodEstabe 
                 And lt.Cod_Produt = @PCodPrd
                 And lt.Cod_Lote = @PCodLotEsp
                 And IsNull(lt.Qtd_Saldo,0) > 0 and IsNull(lt.Qtd_SldPra,0) > 0
                 And ((lt.Dat_Vencim is null) or 
                      (lt.Dat_Vencim >= Case
                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                          Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                        End)) 
              UNION ALL
              Select '2' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldDep, lt.Fat_CnvAprEmbPad
                From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                             Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0)
                        From PRLOT l1 Inner Join
                             DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                       Where l1.Cod_Estabe = @PCodEstabe 
                         And l1.Cod_Produt = @PCodPrd
                         And l1.Cod_Lote = @PCodLotEsp
                         And IsNull(l1.Qtd_Saldo,0) > 0 
                         and IsNull(l1.Qtd_SldDep,0) > 0
                      UNION ALL
                      Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                             Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                        From PRLOT l2
                       Where l2.Cod_Estabe = @PCodEstabe 
                         And l2.Cod_Produt = @PCodPrd
                         And l2.Cod_Lote = @PCodLotEsp
                         And IsNull(l2.Qtd_Saldo,0) > 0 
                         And IsNull(l2.Qtd_SldDep,0) > 0
        			     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                     PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where lt.Cod_Estabe = @PCodEstabe 
                 And lt.Cod_Produt = @PCodPrd
                 And lt.Cod_Lote = @PCodLotEsp
                 And IsNull(lt.Qtd_Saldo,0) > 0 and IsNull(lt.Qtd_SldDep,0) > 0
                 And ((lt.Dat_Vencim is null) or 
                      (lt.Dat_Vencim >= Case
                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                          Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                        End)) 
               Order by OrdDep, Dat_Vencim, CodLocEst desc
          end
        -------------------------------------------------------------------------------------------------------------------------------------------------------
        Open PRLOT_Cr
        Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad
        
        Set @QtdAteAcu = 0
        
        While (@QtdAteAcu < @QtdFra) and (@QtdFra > 0) and (@@FETCH_STATUS = 0)
          begin
            -- calcula a quantidade ainda a ser atendida
            Set @QtdAte = @QtdFra - @QtdAteAcu

            -- se o saldo do lote nao atender a qtd.solicitada refazer a solicitacao proporcionalmente
            if @QtdAte > @SldLot
              begin
                Set @QtdAte = @SldLot
              end

             -- Atualiza saldo do lote
            Set @QtdPra = 0
            Set @QtdDep = 0
            if @LocEst = '1'
              Set @QtdPra = @QtdAte
            else
              Set @QtdDep = @QtdAte
        
            Update PRLOT
               Set Qtd_SolPra = Qtd_SolPra + @QtdPra,
                   Qtd_SolDep = Qtd_SolDep + @QtdDep
             Where Cod_Estabe = @PCodEstabe 
               And Cod_Dep = @CodDep
               And Cod_Produt = @PCodPrd
               And Cod_Lote = @CodLot
        
            Set @QtdAteAcu = @QtdAteAcu + @QtdAte
        
            -- verifica se lote foi solicitado fora de ordem
            Set @FlgDesord = 0
            if (@DatVct is not Null) and (@cl_QtdMesMinPrzVctLot > 0) and 
               (Exists(Select Cod_Lote From PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @CodDep And Cod_Produt = @PCodPrd And Qtd_Saldo > 0 And Dat_Vencim < @DatVct))
              Set @FlgDesord = 1
                       
            -- pega endereço de picking do produto
            Select @NumRua = dx.Num_Rua,
                   @NumCol = dx.Num_Col,   
                   @NumNiv = dx.Num_Niv,   
                   @NumApt = dx.Num_Apt,
                   @dx_CodLocFis = dx.Cod_LocFis,
                   @NumEst = ISNULL(z.Num_Esteira,0)   
              From DPXPR dx Left Outer Join
                   TBZON z on (dx.Cod_Estabe = z.Cod_Estabe and dx.Num_Rua between z.Num_RuaIni and z.Num_RuaFim)
             Where dx.Cod_Estabe = @PCodEstabe
               And dx.Cod_Dep = @CodDep
               And dx.Cod_Produt = @PCodPrd
                   
            Insert Into #ARQ_FRAC (Cod_Dep, Num_Esteira, Cod_Produto, Cod_Lote, Qtd_Lote, Qtd_Pra, Qtd_Dep, Vol_UniIte, 
                                   Qtd_EmbFec, Fat_CnvAprPad, Fat_CnvImpFat,
                                   Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis, Flg_Desord)
                           Values (@CodDep, @NumEst, @PCodPrd, @CodLot, @QtdAte, @QtdPra, @QtdDep, @pr_VolUniMin, 
                                   @QtdEmbFec, @FatCnvAprEmbPad, @FatCnvImpFat,
                                   @NumRua, @NumCol, @NumNiv, @NumApt, @dx_CodLocFis, @FlgDesord)
        
            Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad
        
          end  -- While (@QtdAteAcu < @QtdFra) and (@@FETCH_STATUS = 0)
          
        Close PRLOT_Cr
        Deallocate PRLOT_Cr
        

---------- **************************************************  solicita lotes por vencimento da LINHA DE PICKING (FRACIONADOS)  ***************************************************
        Declare PDVIT_Cr Cursor Local Fast_Forward For 

          Select Cod_Produto, Cod_Lote, Qtd_EmbFec, Fat_CnvAprPad, Fat_CnvImpFat,
                 Cod_LocFis, Vol_UniIte, Qtd_Lote, Qtd_Pra, Qtd_Dep,
                 Num_Esteira, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Flg_Desord
            From #ARQ_FRAC
           Order by Cod_Dep, Num_Esteira, Num_Rua, Num_Col, Num_Niv, Num_Apt

        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @CodPrd, @CodLot, @QtdEmbFec, @FatCnvAprEmbPad, @FatCnvImpFat,
                                      @dx_CodLocFis, @pr_VolUniMin, @QtdFra, @QtdPra, @QtdDep,
                                      @NumEst, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @FlgDesord 
                           
        While @@FETCH_STATUS = 0
          begin
            -- grava/regrava registro em PDVLT 
            Set @NumVol = 1
            Set @VolTotIte = (@QtdPra+@QtdDep)*@pr_VolUniMin
            if not Exists(Select 1 From PDVLT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed And Num_Vol = @NumVol And Cod_Produt = @CodPrd And Cod_Lote = @CodLot)
              begin
                Insert Into PDVLT (Cod_Estabe,  Cod_Pedido, Num_Vol, Cod_Produt, Cod_Lote
                                 , Qtd_EmbFec, Qtd_Lote, Qtd_CxaFec
                                 , Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis
                                 , Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Id_PolCom , Flg_Desord, Flg_Manual
                                 , Cod_FunSep, Transacao)
                           Values (@PCodEstabe, @PCodPed,   @NumVol, @CodPrd,    @CodLot
                                 ,  0,          0,        0
                                 ,  @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @dx_CodLocFis
                                 ,  0,          0,           0,          0,          @FlgDesord, 1
                                 ,  0,          @Now)
                if @@error <> 0
                  begin
                    Rollback Transaction
                    Return
                  end
              end
         
            Update PDVLT
               Set Qtd_Lote = IsNull(Qtd_Lote,0) +  @QtdPra+@QtdDep
                 , Vol_TotIte = IsNull(Vol_TotIte,0) + @VolTotIte
                 , Qtd_LotePra = IsNull(Qtd_LotePra,0) + @QtdPra
                 , Qtd_LoteDep = IsNull(Qtd_LoteDep,0) + @QtdDep
             Where Cod_Estabe = @PCodEstabe 
               And Cod_Pedido = @PCodPed 
               And Num_Vol = @NumVol 
               And Cod_Produt = @CodPrd 
               And Cod_Lote = @CodLot

            Update PDVLT
               Set Flg_Manual = 1
                 , Qtd_Manual = Qtd_Lote
             Where Cod_Estabe = @PCodEstabe 
               And Cod_Pedido = @PCodPed 
               And Num_Vol = @NumVol 
               And Cod_Produt = @CodPrd 
               And Cod_Lote = @CodLot


            -- atualiza status de separação de lotes (manual)
            Update PDVCB
               Set Sta_SepLot = 'M'
             Where Cod_Estabe = @PCodEstabe 
               and Numero = @PCodPed
               and IsNull(Sta_SepLot,'') <> 'M'
         
            -- atualiza quantidades em PDVIT
            Declare Table_Cr Cursor Local Fast_Forward For 
           
              Select Cod_Lote, Tip_Sai, IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)-IsNull(Qtd_Pra,0)-IsNull(Qtd_Dep,0)
                From PDVIT 
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Pedido = @PCodPed
                 And Cod_Produto = @CodPrd 
                 And IsNull(Qtd_Pedido,0) > 0
               Order by Tip_Sai
           
            Open Table_Cr
            Fetch Next From Table_Cr Into @CodLotTip, @TipSai, @QtdTotTip
            While @@FETCH_STATUS = 0
              begin
                Set @QtdPraTip = 0
                Set @QtdDepTip = 0
                  
                Set @QtdSdo = @QtdTotTip
                while (@QtdSdo > 0) and (@QtdPra + @QtdDep > 0)
                  begin
                    if (@QtdPra > 0) and (@QtdSdo > 0)
                      begin
                        if @QtdSdo > @QtdPra
                          Set @QtdPraTip = @QtdPra
                        else
                          Set @QtdPraTip = @QtdSdo
                        Set @QtdPra = @QtdPra - @QtdPraTip
                        Set @QtdSdo = @QtdSdo - @QtdPraTip
                      end
                            
                    if (@QtdDep > 0) and (@QtdSdo > 0)
                      begin
                        if @QtdSdo > @QtdDep
                          Set @QtdDepTip = @QtdDep
                        else
                          Set @QtdDepTip = @QtdSdo
                        Set @QtdDep = @QtdDep - @QtdDepTip
                        Set @QtdSdo = @QtdSdo - @QtdDepTip
                      end
                  end  -- while @QtdSdo > 0
                      
                Update PDVIT
                   Set Qtd_Pra = Qtd_Pra + @QtdPraTip,
                       Qtd_Dep = Qtd_Dep + @QtdDepTip
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Pedido = @PCodPed 
                   And Cod_Produto = @CodPrd 
                   And Cod_Lote = @CodLotTip
                   And Tip_Sai = @TipSai
           
                Fetch Next From Table_Cr Into @CodLotTip, @TipSai, @QtdTotTip 
              end
            Close Table_Cr
            Deallocate Table_Cr
           
            Fetch Next From PDVIT_Cr Into @CodPrd, @CodLot, @QtdEmbFec, @FatCnvAprEmbPad, @FatCnvImpFat,
                                          @dx_CodLocFis, @pr_VolUniMin, @QtdFra, @QtdPra, @QtdDep,
                                          @NumEst, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @FlgDesord 
                                              
              
          end    -- While @@FETCH_STATUS = 0
          
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

        DROP TABLE #ARQ_FRAC


        -- aqui recalcula tributos PDV devido a SBt Ret Ant em PDVLT
        if Exists(Select 1
                    From PDVCB cb
                         inner join RGTRI rg on cb.Cod_RegTri = rg.Cod_RegTri
                   Where cb.Numero = @PCodPed
                     And cb.Tip_Pedido = 'P'
                     And rg.Flg_DscSbtOrgPub = 1)
          Exec dbo.PR_CalcTributPDV @PCodEstabe, @PCodPed

        
      end  -- if @FlgPodeFechar = 1

  Commit Transaction
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CorrigeLoteItemPDVLT]
@PCodEstabe int,
@PCodPed int,
@PNumVol int,
@PCodDep smallint,
@PCodPrd int,
@PCodLot varchar(20),
@PCodAltLot varchar(20),
@PCodMveEnt int,
@PCodMveSai int

AS

SET NOCOUNT ON
SET ANSI_WARNINGS OFF

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
             @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDate() as date)

Declare @WQtdPed int,
        @WQtdPraAnt int,
        @WQtdDepAnt int,
        @WTipMveEnt varchar(1),
        @WTipMveSai varchar(1),
        @WQtdEmbFec int,
        @WCodZon smallint,
        @WCodDep smallint,
        @WNumRua smallint,
        @WNumCol smallint,
        @WNumNiv smallint,
        @WNumApt smallint,
        @WDatVct smalldatetime,
        @WDatFab smalldatetime

-- quantidade total do item
Select @WQtdPed = Isnull(Qtd_Lote,0),
       @WQtdPraAnt = Isnull(Qtd_LotePra,0),
       @WQtdDepAnt = Isnull(Qtd_LoteDep,0)
  From PDVLT 
Where Cod_Estabe = @PCodEstabe 
and Cod_Pedido = @PCodPed and Num_Vol = @PNumVol 
and Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot 
if (@WQtdPraAnt+@WQtdDepAnt) <> @WQtdPed
  begin
    Set @WQtdPraAnt = @WQtdPed - @WQtdDepAnt
  end        

-- verifica codigos de movimentacao                 
Set @WTipMveEnt = (Select Tip_Movimento From TPMVE Where Codigo = @PCodMveEnt) 
Set @WTipMveSai = (Select Tip_Movimento From TPMVE Where Codigo = @PCodMveSai) 

-- verifica endereco de divergencias
Select @WCodDep = IsNull(z.Cod_Dep,0),
       @WCodZon = IsNull(z.Cod_Zon,0),
       @WNumRua = IsNull(z.Num_RuaIni,0) 
  From PMEST p
       Outer Apply (Select top 1 s.Cod_Dep, s.Cod_Zon, s.Num_RuaIni
	                  From TBZON s
                     Where s.Cod_Estabe = p.Cod_Estabe
                       And s.Cod_Zon = IsNull(p.CodZonDiv,0)
                       And dbo.FN_TipLocEnd(s.Cod_Estabe, s.Cod_Dep, s.Num_RuaIni) = 'X'
                     Order by s.Cod_Dep) z
 Where p.Cod_Estabe = @PCodEstabe 

Set @WNumCol = 0
Set @WNumNiv = 0
Set @WNumApt = 0

if (@WQtdPraAnt < 0) or (@WQtdDepAnt < 0)
  RAISERROR('Quantidades atribuídas inválidas',16,1)
else
if @WCodZon = 0
  RAISERROR('Zona para Divergências não configurada',16,1)
else
if @WNumRua = 0
  RAISERROR('Zona para Divergências invalida (produção)',16,1)
else
if (Select IsNull(Qtd_CxaFec,0) From PDVLT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed And Num_Vol = @PNumVol And Cod_Produt = @PCodPrd And Cod_Lote = @PCodLot) > 0
  RAISERROR('Produto/Lote caixa fechada',16,1)
else
if Exists(Select * From PDVLT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed and Num_Vol = @PNumVol and Cod_Produt = @PCodPrd and Cod_Lote = @PCodAltLot)
  RAISERROR('Lote já existe no pedido',16,1)
else
if  not Exists(Select Cod_Lote from PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @PCodDep And Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot)
  RAISERROR('Lote  substituído não existe',16,1)
else
if  not Exists(Select Cod_Lote from PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @PCodDep And Cod_Produt = @PCodPrd and Cod_Lote = @PCodAltLot)
  RAISERROR('Lote  substituto não existe',16,1)
else
if ((Select Qtd_SolPra from PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @PCodDep And Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot) < @WQtdPraAnt) or
   ((Select Qtd_SolDep from PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @PCodDep And Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot) < @WQtdDepAnt) 
  RAISERROR('Quantidade solicitada do Lote substituído insuficiente',16,1)
else
if (Select IsNull(Qtd_Saldo,0) From PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @PCodDep And Cod_Produt = @PCodPrd and Cod_Lote = @PCodAltLot) < (@WQtdPraAnt+@WQtdDepAnt)
  RAISERROR('Saldo do Lote  substituto insuficiente',16,1)
else
if @WTipMveEnt <> 'E'
  RAISERROR('Código de movimentação de entrada inválida',16,1)
else
if @WTipMveSai <> 'S'
  RAISERROR('Código de movimentação de saída inválida',16,1)
else
if (@PCodAltLot <> '') and (@PCodAltLot <> @PCodLot )
  begin
    Begin Transaction
      Declare @cb_FlgCal bit,
              @to_CodCfoNorInt int,
              @WMsg varchar(128),
              @WFlgErr bit,
              @WQtdTotSol int,
              @WAccQtdSol int,
              @WAccQtdPra int,
              @WAccQtdDep int,
              @WQtdMov int,
              @WQtdSldPra int,
              @WQtdSldDep int,

              @pl_CodDep smallint,
              @pl_NumRua smallint,
              @pl_NumCol smallint,
              @pl_NumNiv smallint,
              @pl_NumApt smallint,
              @pl_QtdLot integer,
              @pl_QtdLotPra integer,
              @pl_QtdLotDep integer,
              @pl_QtdCxaFec integer,
              @pl_QtdEmbFec integer

      Select @pl_CodDep = Cod_Dep,
             @pl_NumRua = Num_Rua,
             @pl_NumCol = Num_Col,
             @pl_NumNiv = Num_Niv,
             @pl_NumApt = Num_Apt,
             @pl_QtdLot = Qtd_Lote,
             @pl_QtdLotPra = Qtd_LotePra,
             @pl_QtdLotDep = Qtd_LoteDep,
             @pl_QtdCxaFec = Qtd_CxaFec,
             @pl_QtdEmbFec = Qtd_EmbFec
        From PDVLT
      Where Cod_Estabe = @PCodEstabe 
      And Cod_Pedido = @PCodPed
      And Num_Vol = @PNumVol
      And Cod_Produt = @PCodPrd
      And Cod_Lote = @PCodLot

      if @pl_QtdCxaFec = 0
        begin

          -- bloqueia os lotes dos produtos envolvidos na operacao
          Update PRLOT
            Set Qtd_Saldo = Qtd_Saldo + 0         
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Dep = @PCodDep
          And Cod_Produt = @PCodPrd
          And Cod_Lote = @PCodAltLot
          And Qtd_Saldo >= (@WQtdPraAnt+@WQtdDepAnt)
          if @@rowcount = 0
            begin
              Rollback Transaction
              Return
            end

          -- guarda flag original
          Select @cb_FlgCal = IsNull(Flg_Calc,0) From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PCodPed

          -- coloca campos de tabela na memoria
          Select @to_CodCfoNorInt = t.Cod_CfoNorInt
            From TPOPE t Inner Join PDVCB p on (t.Cod_Ope = p.Tip_Faturamento)
          Where p.Cod_Estabe = @PCodEstabe 
          And p.Numero = @PCodPed

          -- muda flag no cabecalho para nao disparar trigger em PDVIT
          Update PDVCB
            Set Flg_Calc = 1
          Where Cod_Estabe = @PCodEstabe 
          And Numero = @PCodPed
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          -- devolve o lote anterior
          Update PRLOT
            Set Qtd_SolPra = Qtd_SolPra - @WQtdPraAnt
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Dep = @PCodDep
          And Cod_Produt = @PCodPrd 
          And  Cod_Lote = @PCodLot
          And @WQtdPraAnt > 0
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          Update PRLOT
            Set Qtd_SolDep = Qtd_SolDep -  @WQtdDepAnt
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Dep = @PCodDep
          And Cod_Produt = @PCodPrd 
          And  Cod_Lote = @PCodLot
          And @WQtdDepAnt > 0
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          -- transfere o lote anterior para area de divergencias
          Set @WFlgErr = 0
          Set @WMsg = ''

          -- se nao existir o lote, cria
          if not Exists(Select * From PRLTL 
                        Where Cod_Estabe = @PCodEstabe 
                        and Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot 
                        and Cod_Dep = @WCodDep and Num_Rua = @WNumRua 
                        and Num_Col = @WNumCol and Num_Niv = @WNumNiv 
                        and Num_Apt = @WNumApt)
            begin
              Set @WDatVct = null
              Set @WDatFab = null
              Set @WQtdEmbFec = 1

              -- pega o vencimento do lote
              Select @WDatVct = Dat_Vencim, 
                     @WDatFab = Dat_Fabric 
                From PRLOT 
              Where Cod_Estabe = @PCodEstabe 
              And Cod_Dep = @PCodDep
              And Cod_Produt = @PCodPrd 
              and Cod_Lote = @PCodLot

              if @WDatVct is null
                Set @WDatVct = (Select top 1 Dat_Vencim From PRLTL Where Cod_Estabe = @PCodEstabe And Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot And Cod_Dep = @WCodDep)
              if @WDatFab is null
                Set @WDatFab = (Select top 1 Dat_Fabric From PRLTL Where Cod_Estabe = @PCodEstabe And Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot And Cod_Dep = @WCodDep)

              Insert into PRLTL (Cod_Estabe, Cod_Produt, Cod_Lote, Qtd_EmbFec, Dat_Vencim, Dat_Fabric, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Dat_Entrada, Qtd_FisPra, Qtd_SolPra,Qtd_FisDep,Qtd_SolDep)
                         Values (@PCodEstabe, @PCodPrd, @PCodLot, @WQtdEmbFec, @WDatVct, @WDatFab, @WCodDep, @WNumRua, @WNumCol, @WNumNiv, @WNumApt, @Date, 0, 0, 0, 0)
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end
            end

          -- tira de PRLOT
          Update PRLOT
            Set Qtd_FisPra = Qtd_FisPra - @WQtdPraAnt
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Dep = @PCodDep
          And Cod_Produt = @PCodPrd 
          and  Cod_Lote = @PCodLot
          And @WQtdPraAnt > 0
          And Qtd_SldPra >= @WQtdPraAnt
          And @WFlgErr = 0
          if (@@rowcount = 0) and (@WQtdPraAnt > 0) and (@WFlgErr = 0)
            begin
              Set @WFlgErr = 1
              Set @WMsg = 'Estoque insuficiente no Picking a transferir p/ zona de divergências'
            end

          Update PRLOT
            Set Qtd_FisDep = Qtd_FisDep - @WQtdDepAnt
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Dep = @PCodDep
          And Cod_Produt = @PCodPrd 
          and Cod_Lote = @PCodLot
          And @WQtdDepAnt > 0
          And Qtd_SldDep >= @WQtdDepAnt
          And @WFlgErr = 0
          if (@@rowcount = 0) and (@WQtdDepAnt > 0) and (@WFlgErr = 0)
            begin
              Set @WFlgErr = 1
              Set @WMsg = 'Estoque insuficiente no Picking a transferir p/ zona de divergências'
            end

          -- transfere para zona de cancelados
          Update PRLTL
            Set Qtd_FisPra = Qtd_FisPra +  @WQtdPraAnt
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot
          And Cod_Dep = @WCodDep
          And Num_Rua = @WNumRua 
          And Num_Col = @WNumCol
          And Num_Niv = @WNumNiv
          And Num_Apt = @WNumApt
          And @WQtdPraAnt > 0
          And @WFlgErr = 0
          if (@@rowcount = 0) and (@WQtdPraAnt > 0) and (@WFlgErr = 0)
            begin
              Set @WFlgErr = 1
              Set @WMsg = 'Erro na transferencia p/ zona de divergências (endereço inexistente)'
            end
          Update PRLTL
            Set Qtd_FisDep = Qtd_FisDep +  @WQtdDepAnt
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot
          And Cod_Dep = @WCodDep
          And Num_Rua = @WNumRua 
          And Num_Col = @WNumCol
          And Num_Niv = @WNumNiv
          And Num_Apt = @WNumApt
          And @WQtdDepAnt > 0
          And @WFlgErr = 0
          if (@@rowcount = 0) and (@WQtdDepAnt > 0) and (@WFlgErr = 0)
            begin
              Set @WFlgErr = 1
              Set @WMsg = 'Erro na transferencia p/ zona de divergências (endereço inexistente)'
            end

          if @WFlgErr = 1
            begin
              if @WMsg <> ''
                RAISERROR(@WMsg,16,1)
              Rollback Transaction
              Return
            end

          -- solicita novo lote
          Select @WQtdSldPra = IsNull(Qtd_SldPra,0),
                 @WQtdSldDep = IsNull(Qtd_SldDep,0)
            From PRLOT
          Where Cod_Estabe = @PCodEstabe 
          And Cod_Dep = @PCodDep
          And Cod_Produt = @PCodPrd
          And Cod_Lote = @PCodAltLot

          Set @WQtdTotSol = @WQtdPraAnt+@WQtdDepAnt
          Set @WAccQtdSol = 0
          Set @WAccQtdPra = 0
          Set @WAccQtdDep = 0
          if @to_CodCfoNorInt > 0
            begin
              -- solicita o que for possivel do lote
              if @WQtdSldPra > 0
                begin
                  if @WQtdSldPra > @WQtdTotSol
                    Set @WQtdMov = @WQtdTotSol
                  else
                    Set @WQtdMov = @WQtdSldPra
                  Set @WAccQtdPra = @WAccQtdPra + @WQtdMov
                  Set @WAccQtdSol = @WAccQtdSol + @WQtdMov
                  Update PRLOT
                    Set Qtd_SolPra = Qtd_SolPra + @WQtdMov
                  Where Cod_Estabe = @PCodEstabe 
                  And Cod_Dep = @PCodDep
                  And Cod_Produt = @PCodPrd
                  And Cod_Lote = @PCodAltLot
                  if @@error <> 0
                    begin
                      Rollback Transaction
                      Return
                    end
                end
              -- ver se precisa solicitar outro lote
              if @WAccQtdSol < @WQtdTotSol
                if @WQtdSldDep > 0
                  begin
                    if @WQtdSldDep > (@WQtdTotSol-@WAccQtdSol) 
                      Set @WQtdMov = @WQtdTotSol-@WAccQtdSol
                    else
                      Set @WQtdMov = @WQtdSldDep
                    Set @WAccQtdDep = @WAccQtdDep + @WQtdMov
                    Set @WAccQtdSol = @WAccQtdSol + @WQtdMov
                  Update PRLOT
                    Set Qtd_SolDep = Qtd_SolDep + @WQtdMov
                  Where Cod_Estabe = @PCodEstabe 
                  And Cod_Dep = @PCodDep
                  And Cod_Produt = @PCodPrd
                  And Cod_Lote = @PCodAltLot
                  if @@error <> 0
                    begin
                      Rollback Transaction
                      Return
                    end
                  end
            end
          else
            begin
              -- solicita o que for possivel do lote
              if @WQtdSldDep > 0
                begin
                  if @WQtdSldDep > @WQtdTotSol
                    Set @WQtdMov = @WQtdTotSol
                  else
                    Set @WQtdMov = @WQtdSldDep
                  Set @WAccQtdDep = @WAccQtdDep + @WQtdMov
                  Set @WAccQtdSol = @WAccQtdSol + @WQtdMov
                Update PRLOT
                  Set Qtd_SolDep = Qtd_SolDep + @WQtdMov
                Where Cod_Estabe = @PCodEstabe 
                And Cod_Dep = @PCodDep
                And Cod_Produt = @PCodPrd
                And Cod_Lote = @PCodAltLot
                if @@error <> 0
                  begin
                    Rollback Transaction
                    Return
                  end
                end
              -- ver se precisa solicitar outro lote
              if @WAccQtdSol < @WQtdTotSol
                if @WQtdSldPra > 0
                  begin
                    if @WQtdSldPra > (@WQtdTotSol-@WAccQtdSol) 
                      Set @WQtdMov = @WQtdTotSol-@WAccQtdSol
                    else
                      Set @WQtdMov = @WQtdSldPra
                    Set @WAccQtdPra = @WAccQtdPra + @WQtdMov
                    Set @WAccQtdSol = @WAccQtdSol + @WQtdMov
                    Update PRLOT
                      Set Qtd_SolPra = Qtd_SolPra + @WQtdMov
                    Where Cod_Estabe = @PCodEstabe 
                    And Cod_Dep = @PCodDep
                    And Cod_Produt = @PCodPrd
                    And Cod_Lote = @PCodAltLot
                    if @@error <> 0
                      begin
                        Rollback Transaction
                        Return
                      end
                  end
            end

          if @WAccQtdSol <> @WQtdTotSol
            begin
              Rollback Transaction
              Return
            end
            
          -- corrige o lote
          Update PDVLT
            Set Cod_Lote = @PCodAltLot,
                Qtd_LotePra = @WAccQtdPra,
                Qtd_LoteDep = @WAccQtdDep
          Where Cod_Estabe = @PCodEstabe     
          And Cod_Pedido = @PCodPed and Num_Vol = @PNumVol 
          and Cod_Produt = @PCodPrd and Cod_Lote = @PCodLot 
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

         -- retorna flag anterior
         Update PDVCB
           Set Flg_Calc = @cb_FlgCal
         Where Cod_Estabe = @PCodEstabe 
         And Numero = @PCodPed 
         if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

        -- aqui recalcula tributos PDV devido a SBt Ret Ant em PDVLT
        if Exists(Select 1
                    From PDVCB cb
                         inner join RGTRI rg on cb.Cod_RegTri = rg.Cod_RegTri
                   Where cb.Numero = @PCodPed
                     And cb.Tip_Pedido = 'P'
                     And rg.Flg_DscSbtOrgPub = 1)
          Exec dbo.PR_CalcTributPDV @PCodEstabe, @PCodPed
        end

    Commit Transaction
  end

GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ManutencaoCliente] 
@CodEstabe int,      -- estabelecimento
@Campo varchar(25),  -- nome do campo 
@Valor int,          -- novo valor
@Codigo int          -- cod. cliente

AS

SET NOCOUNT ON

Begin Transaction

  if @Campo = 'Cod_Vendedor' 
    Update e
      Set e.Cod_Vendedor = @Valor
    From ENXES e 
         Inner Join CLIEN c ON c.Cgc_Cpf = e.Num_CgcCpf 
    Where e.Cod_Estabe =  @CodEstabe
    And c.Codigo = @Codigo

  if @Campo = 'Cod_OperTlmk' 
    Update e
      Set e.Cod_Operador = @Valor
    From ENXES e 
         Inner Join CLIEN c ON c.Cgc_Cpf = e.Num_CgcCpf 
    Where e.Cod_Estabe =  @CodEstabe
    And c.Codigo = @Codigo

  if @Campo = 'Cod_AgeCob' 
    Update e
      Set e.Cod_AgeCob = @Valor
    From ENXES e 
         Inner Join CLIEN c ON c.Cgc_Cpf = e.Num_CgcCpf 
    Where e.Cod_Estabe =  @CodEstabe
    And c.Codigo = @Codigo

  if @Campo = 'Cod_Transp' 
    Update e
      Set e.Cod_Transp = @Valor
    From ENXES e 
         Inner Join CLIEN c ON c.Cgc_Cpf = e.Num_CgcCpf 
    Where e.Cod_Estabe =  @CodEstabe
    And c.Codigo = @Codigo

  if @Campo = 'Cod_Rota' 
    Update e
      Set e.Cod_Rota = @Valor
    From ENXES e 
         Inner Join CLIEN c ON c.Cgc_Cpf = e.Num_CgcCpf 
    Where e.Cod_Estabe =  @CodEstabe
    And c.Codigo = @Codigo

  if @Campo = 'Cod_RegTri' 
    Update e
      Set e.Cod_RegTri = @Valor
    From ENXES e 
         Inner Join CLIEN c ON c.Cgc_Cpf = e.Num_CgcCpf 
    Where e.Cod_Estabe =  @CodEstabe
    And c.Codigo = @Codigo

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_PrcCusPrdDatRef]
(
@PCodEstabe int,
@PCodPrd int,
@PCodCus char(1),   -- Preco (V)enda, (E)ntrada sem IPI, (I)- entrada com IPI, (C)usto, (M)édio, (B)-Medio Comercial
@PCodOri char(1),   -- (G)erencial,(O)ficial, (N)ao Oficial
@PDatRef smalldatetime
)
RETURNS numeric(18,4)

AS

BEGIN

Declare @PVlrCus numeric(18,4)

Set @PVlrCus = 0
Set @PDatRef = @PDatRef + 1

-- Preco pelo Registro do Historico de Precos
-- nao eh pelo preco de entrada (compra)
if ((@PCodCus <> 'E') and (@PCodCus <> 'I'))
  if Exists(Select 1 From HSPRC 
             Where Cod_Estabe = @PCodEstabe And Cod_Produto = @PCodPrd
               And Dat_Alteracao < @PDatRef)
    Select top 1 
	       @PVlrCus = Case 
                        When (@PCodCus = 'V') then Vlr_PrcVen
                        When (@PCodCus = 'C') then Vlr_CusLiqPra
                        When (@PCodCus = 'B') and (IsNull(Vlr_CusMedCom,0) > 0) then Vlr_CusMedCom
                        When (@PCodCus = 'B') and (IsNull(Vlr_CusMedCom,0) = 0) then Vlr_CusMed
                        When (@PCodCus = 'M') and (@PCodOri = 'G') then Vlr_CusMed
                        When (@PCodCus = 'M') and (@PCodOri = 'O') then Vlr_CusMedPra
                        When (@PCodCus = 'M') and (@PCodOri = 'N') then Vlr_CusMedDep
                        Else 0
                      End
	  From HSPRC 
     Where Cod_Estabe = @PCodEstabe
       And Cod_Produto = @PCodPrd
       And Dat_Alteracao < @PDatRef
     Order by Dat_Alteracao desc, Seq_Alteracao desc


-- Preco pelo Registro de Entrada
if IsNull(@PVlrCus,0) = 0 
  Select top 1 
	     @PVlrCus = Case 
                      When (@PCodCus = 'C') then i.Cus_LiqUni
                      When (@PCodCus = 'M') or (@PCodCus = 'B') then i.Prc_CustoMedio
                      When (@PCodCus = 'V') then i.Prc_Venda
                      When (@PCodCus = 'E') then i.Prc_Unitario*(1-i.Per_DescItem/100)
                      When (@PCodCus = 'I') then i.Prc_Unitario*(1-i.Per_DescItem/100)+(i.Vlr_Ipi/(i.Qtd_Pedido+i.Qtd_Bonificacao))
                      When (@PCodCus = 'X') then Round((i.Vlr_TotItem-i.Vlr_DescRateado-IsNull(i.Vlr_DscTri,0)+i.Vlr_DespRateada+i.Vlr_Ipi)/(i.Qtd_Pedido+i.Qtd_Bonificacao),4)
                      Else 0
                    End
    From NFEIT i 
         Inner Join NFECB c on i.Cod_Estabe = c.Cod_Estabe and i.Protocolo = c.Protocolo 
   Where c.Status = 'F' and c.Tip_NF = 'C'
     And c.Cod_Estabe = @PCodEstabe
     And i.Cod_Produto = @PCodPrd
     And i.Dat_Movimento < @PDatRef
   Order by i.Dat_Movimento desc, i.Protocolo desc


-- ultimo caso pega precos atuais do cadastro
if IsNull(@PVlrCus,0) = 0 
  Select @PVlrCus = Case 
                      When (@PCodCus = 'C') or (@PCodCus = 'X') then es.Prc_CusLiqEnt
                      When (@PCodCus = 'B') and (IsNull(es.Prc_CusMedCom,0) > 0) then es.Prc_CusMedCom
                      When (@PCodCus = 'B') and (IsNull(es.Prc_CusMedCom,0) = 0) then es.Prc_CusMed
                      When (@PCodCus = 'M') and (@PCodOri = 'G') then es.Prc_CusMed
                      When (@PCodCus = 'M') and (@PCodOri = 'O') then es.Prc_CusMedPra
                      When (@PCodCus = 'M') and (@PCodOri = 'N') then es.Prc_CusMedDep
                      When (@PCodCus = 'E') then es.Prc_UltEnt*(1-IsNull(es.Per_DscUltEnt,0)/100)
                      When (@PCodCus = 'I') then (es.Prc_UltEnt*(1-IsNull(es.Per_DscUltEnt,0)/100))*(1+IsNull(pr.Per_Ipi,0)/100)
                      Else es.Prc_Venda
                    End
    From PRXES es
         inner join PRODU pr on es.Cod_Produt = pr.Codigo
   Where es.Cod_Estabe = @PCodEstabe
     And es.Cod_Produt = @PCodPrd

-- Retorna o resultado da function
RETURN Round(@PVlrCus,4)

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_EstoquePulmaoPrd]
(
  @PCodEstabe int,
