-- relação de produtos e seus incentivos por estabelecimento
CREATE VIEW [dbo].[V_PrdIncFis] AS

Select ix.Cod_Estabe, Cod_Produt = pr.Codigo, ix.Id_IncFis, ix.Dat_IniIfs, ix.Dat_FimIfs, Flg_PdvEsp=IsNull(ix.Flg_PdvEsp,0)
  From PRODU pr
       Inner Join (Select x.Cod_Estabe, t.Cod_TipIfs, g.Id_IncFis, g.Cod_GrpIfs, t.Dat_IniIfs, t.Dat_FimIfs, x.Flg_PdvEsp
                     From IFXGI g
                          Inner Join TBIFS t on g.Id_IncFis = t.Id_IncFis
                          Inner Join ESXIF x on t.Id_IncFis = x.Id_IncFis
                  ) ix on ix.Cod_GrpIfs = Case 
                                            When ix.Cod_TipIfs = 'C' then pr.Cod_Cest     -- CEST
                                            When ix.Cod_TipIfs = 'G' then pr.Cod_GrpPrc   -- Grupo de preços: similares, genericos, ...
                                            Else 'X'
                                          End
GO

