-- relação de produtos com NF faturadas pelo fornecedor 
-- registradas no distribuidor
-- e ainda não fechadas
CREATE VIEW [dbo].[V_PULMAO] AS

Select it.Cod_Estabe, it.Cod_Produto,
       C_QtdPulmao = sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0))
  From dbo.NFEIT it  
       inner join dbo.NFECB cb on it.Cod_Estabe = cb.Cod_Estabe and
                                  it.Protocolo = cb.Protocolo
 Where ( (cb.Status = 'A') or (cb.Status = 'P') )
   And ( (cb.Tip_Nf = 'C') or  -- compra
         (CharIndex(cast(cb.Cod_Cfo as varchar), '2910;1910') > 0)   -- bonificacao
       )
 Group by it.Cod_Estabe, it.Cod_Produto

GO

