      Insert Into TLPMT (Cod_Layout,Cod_MtvRejLay,Des_MtvRejLay,Str_CodMtvRejInf)
                  Values(@CodLay,@CodMtv,@DesMtv,@StrMtv)

    Set @CodMtv = '06'
    Set @DesMtv = 'Produto nao cadastrado/desativado'
	Set @StrMtv = ';PRX;PR-;'
    if not Exists(Select * From TLPMT Where Cod_Layout = @CodLay And Cod_MtvRejLay = @CodMtv)
      Insert Into TLPMT (Cod_Layout,Cod_MtvRejLay,Des_MtvRejLay,Str_CodMtvRejInf)
                  Values(@CodLay,@CodMtv,@DesMtv,@StrMtv)

    Set @CodMtv = '07'
