		If (@Opcao = 0 or @Opcao = 2) And Not Exists(Select 1 From PMEST Where Cod_Estabe = @CodEstabe)
		  Begin
			Insert Into PMEST (Cod_Estabe ,
					CodClaAbc1 ,PerClaAbcVal1 ,PerClaAbcVol1 ,QtdDiaSeg1 ,CodClaAbc2 ,PerClaAbcVal2 ,PerClaAbcVol2 ,
					QtdDiaSeg2 ,CodClaAbc3 ,PerClaAbcVal3 ,PerClaAbcVol3 ,QtdDiaSeg3 ,CodClaAbc4 ,PerClaAbcVal4 ,PerClaAbcVol4 ,QtdDiaSeg4 ,CodClaAbc5 ,
					PerClaAbcVal5 ,PerClaAbcVol5 ,QtdDiaSeg5 ,CodClaAbc6 ,PerClaAbcVal6 ,PerClaAbcVol6 ,QtdDiaSeg6 ,Usuario ,Transacao ,CodZonDev ,
					CodZonCan ,CodZonDiv ,QtdNivEndPck ,QtdNivEndDep ,WmsFlgBlqImpEtqVol ,WmsFlgBlqImpCodBarPckLst ,WmsFlgBlqRotFecEmbPdv ,FlgCnfIUM ,
					WmsFlgImpFabPckLst ,BalImpIniCodBar ,BalImpTamCodBar ,BalImpIniQtdPrd ,BalImpTamQtdPrd ,BalExpIniCodBar ,BalExpTamCodBar ,BalExpIniDesPrd ,
					BalExpTamDesPrd ,BalExpIniQtdPrd ,BalExpTamQtdPrd ,BalExpFlgCodPrd ,DesMscEndPrd ,CodOpeNfsBal ,CodOpeNfeBal ,CodCliNotBal ,CodZonDivBal ,
					FlgBlqCnfTrf ,CodOpeWmsDef ,BlqEstFisNeg,FlgIntegrWmsExt,DesSisIntWms,FlgIgnQtdMenDvgPdc,FlgIgnPrcMenDvgPdc,WmsFlgBlqImpEtqVolPul)
